INSERT INTO `cards` (`id`, `abilities`, `ancient_trait`, `artist`, `attacks`, `card_set`, `converted`, `evolves_from`, `evolves_to`, `flavor_text`, `generation`, `hp`, `img`, `legalities`, `level`, `name`, `national_pokedex_numbers`, `publisher`, `rarity`, `regulation_mark`, `release_date`, `resistances`, `retreat_cost`, `rules`, `series`, `set_num`, `subtypes`, `supertype`, `types`, `weakness`) VALUES
('base1-1', '[{\'name\': \'Damage Swap\', \'text\': \"As often as you like during your turn (before your attack), you may move 1 damage counter from 1 of your Pokémon to another as long as you don\'t Knock Out that Pokémon. This power can\'t be used if Alakazam is Asleep, Confused, or Paralyzed.\", \'type\': \'Pokémon Power\'}]', '', 'Ken Sugimori', '[{\'name\': \'Confuse Ray\', \'cost\': [\'Psychic\', \'Psychic\', \'Psychic\'], \'convertedEnergyCost\': 3, \'damage\': \'30\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Confused.\'}]', 'Base', '3', 'Kadabra', '', 'Its brain can outperform a supercomputer. Its intelligence quotient is said to be 5000.', 'First', '80', 'https://images.pokemoncard.io/images/base1/base1-1.png', 'unlimited: Legal', '42', 'Alakazam', '65', 'WOTC', 'Rare Holo', '', '01/09/1999', '', 'Colorless, Colorless, Colorless', '', 'Base', '1', 'Stage 2', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2'),
('base1-10', '', '', 'Ken Sugimori', '[{\'name\': \'Psychic\', \'cost\': [\'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'10+\', \'text\': \'Does 10 damage plus 10 more damage for each Energy card attached to the Defending Pokémon.\'}, {\'name\': \'Barrier\', \'cost\': [\'Psychic\', \'Psychic\'], \'convertedEnergyCost\': 2, \'damage\': \'\', \'text\': \"Discard 1 Psychic Energy card attached to Mewtwo in order to prevent all effects of attacks, including damage, done to Mewtwo during your opponent\'s next turn.\"}]', 'Base', '3', '', '', 'A scientist created this Pokémon after years of horrific gene-splicing and DNA engineering experiments.', 'First', '60', 'https://images.pokemoncard.io/images/base1/base1-10.png', 'unlimited: Legal', '53', 'Mewtwo', '150', 'WOTC', 'Rare Holo', '', '01/09/1999', '', 'Colorless, Colorless, Colorless', '', 'Base', '10', 'Basic', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2'),
('base1-100', '', '', 'Keiji Kinebuchi', '', 'Base', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/base1/base1-100.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Lightning Energy', '', 'WOTC', '', '', '01/09/1999', '', '', '', 'Base', '100', 'Basic', 'Energy', '', ''),
('base1-101', '', '', 'Keiji Kinebuchi', '', 'Base', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/base1/base1-101.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Psychic Energy', '', 'WOTC', '', '', '01/09/1999', '', '', '', 'Base', '101', 'Basic', 'Energy', '', ''),
