('base4-14', '', '', 'Kagemaru Himeno', '[{\'name\': \'Wing Attack\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'\'}, {\'name\': \'Hurricane\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'30\', \'text\': \"Unless this attack Knocks Out the Defending Pokémon, return the Defending Pokémon and all cards attached to it to your opponent\'s hand.\"}]', 'Base Set 2', '', 'Pidgeotto', '', 'When hunting, it skims the surface of water at high speed to pick off unwary prey such as Magikarp.', 'First', '80', 'https://images.pokemoncard.io/images/base4/base4-14.png', 'unlimited: Legal', '40', 'Pidgeot', '18', 'WOTC', 'Rare Holo', '', '2/24/2000', 'type: Fighting, value: -30', '', '', 'Base', '14', 'Stage 2', 'Pokémon', 'Colorless', 'type: Lightning, value: ×2'),
('base4-15', '', '', 'Ken Sugimori', '[{\'name\': \'Water Gun\', \'cost\': [\'Water\', \'Water\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'30+\', \'text\': \"Does 30 damage plus 10 more damage for each Water Energy attached to Poliwrath but not used to pay for this attack\'s Energy cost. You can\'t add more than 20 damage in this way.\"}, {\'name\': \'Whirlpool\', \'cost\': [\'Water\', \'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'40\', \'text\': \'If the Defending Pokémon has any Energy cards attached to it, choose 1 of them and discard it.\'}]', 'Base Set 2', '3', 'Poliwhirl', '', 'An adept swimmer at both the front crawl and breaststroke. Easily overtakes the best human swimmers.', 'First', '90', 'https://images.pokemoncard.io/images/base4/base4-15.png', 'unlimited: Legal', '48', 'Poliwrath', '62', 'WOTC', 'Rare Holo', '', '2/24/2000', '', 'Colorless, Colorless, Colorless', '', 'Base', '15', 'Stage 2', 'Pokémon', 'Water', 'type: Grass, value: ×2'),
('base4-16', '', '', 'Ken Sugimori', '[{\'name\': \'Agility\', \'cost\': [\'Lightning\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'20\', \'text\': \"Flip a coin. If heads, during your opponent\'s next turn, prevent all effects of attacks, including damage, done to Raichu.\"}, {\'name\': \'Thunder\', \'cost\': [\'Lightning\', \'Lightning\', \'Lightning\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'60\', \'text\': \'Flip a coin. If tails, Raichu does 30 damage to itself.\'}]', 'Base Set 2', '1', 'Pikachu', '', 'Its long tail serves as a ground to protect itself from its own high-voltage power.', 'First', '80', 'https://images.pokemoncard.io/images/base4/base4-16.png', 'unlimited: Legal', '40', 'Raichu', '26', 'WOTC', 'Rare Holo', '', '2/24/2000', '', 'Colorless', '', 'Base', '16', 'Stage 1', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
('base4-17', '', '', 'Ken Sugimori', '[{\'name\': \'Swords Dance\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"During your next turn, Scyther\'s Slash attack\'s base damage is 60 instead of 30.\"}, {\'name\': \'Slash\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'30\', \'text\': \'\'}]', 'Base Set 2', '', '', 'Scizor', 'With ninja-like agility and speed, it can create the illusion that there is more than one of it.', 'First', '70', 'https://images.pokemoncard.io/images/base4/base4-17.png', 'unlimited: Legal', '25', 'Scyther', '123', 'WOTC', 'Rare Holo', '', '2/24/2000', 'type: Fighting, value: -30', '', '', 'Base', '17', 'Basic', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('base4-18', '[{\'name\': \'Energy Trans\', \'text\': \"As often as you like during your turn (before your attack), you may take 1 Grass Energy card attached to 1 of your Pokémon and attach it to a different one. This power can\'t be used if Venusaur is Asleep, Confused, or Paralyzed.\", \'type\': \'Pokémon Power\'}]', '', 'Mitsuhiro Arita', '[{\'name\': \'Solarbeam\', \'cost\': [\'Grass\', \'Grass\', \'Grass\', \'Grass\'], \'convertedEnergyCost\': 4, \'damage\': \'60\', \'text\': \'\'}]', 'Base Set 2', '2', 'Ivysaur', '', 'This plant blooms when it is absorbing solar energy. It stays on the move to seek sunlight.', 'First', '100', 'https://images.pokemoncard.io/images/base4/base4-18.png', 'unlimited: Legal', '67', 'Venusaur', '3', 'WOTC', 'Rare Holo', '', '2/24/2000', '', 'Colorless, Colorless', '', 'Base', '18', 'Stage 2', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('base4-19', '', '', 'Mitsuhiro Arita', '[{\'name\': \'Lullaby\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'The Defending Pokémon is now Asleep.\'}, {\'name\': \'Do the Wave\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'10+\', \'text\': \'Does 10 damage plus 10 more damage for each of your Benched Pokémon.\'}]', 'Base Set 2', '2', 'Jigglypuff', '', 'The body is soft and rubbery. When angered, it will suck in air and inflate itself to an enormous size.', 'First', '80', 'https://images.pokemoncard.io/images/base4/base4-19.png', 'unlimited: Legal', '36', 'Wigglytuff', '40', 'WOTC', 'Rare Holo', '', '2/24/2000', 'type: Psychic, value: -30', 'Colorless, Colorless', '', 'Base', '19', 'Stage 1', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2');
INSERT INTO `cards` (`id`, `abilities`, `ancient_trait`, `artist`, `attacks`, `card_set`, `converted`, `evolves_from`, `evolves_to`, `flavor_text`, `generation`, `hp`, `img`, `legalities`, `level`, `name`, `national_pokedex_numbers`, `publisher`, `rarity`, `regulation_mark`, `release_date`, `resistances`, `retreat_cost`, `rules`, `series`, `set_num`, `subtypes`, `supertype`, `types`, `weakness`) VALUES
('base4-2', '[{\'name\': \'Rain Dance\', \'text\': \"As often as you like during your turn (before your attack), you may attach 1 Water Energy card to 1 of your Water Pokémon. (This doesn\'t use up your 1 Energy card attachment for the turn.) This power can\'t be used if Blastoise is Asleep, Confused, or Paralyzed.\", \'type\': \'Pokémon Power\'}]', '', 'Ken Sugimori', '[{\'name\': \'Hydro Pump\', \'cost\': [\'Water\', \'Water\', \'Water\'], \'convertedEnergyCost\': 3, \'damage\': \'40+\', \'text\': \"Does 40 damage plus 10 more damage for each Water Energy attached to Blastoise but not used to pay for this attack\'s Energy cost. You can\'t add more than 20 damage in this way.\"}]', 'Base Set 2', '3', 'Wartortle', '', 'A brutal Pokémon with pressurized water jets on its shell. They are used for high-speed tackles.', 'First', '100', 'https://images.pokemoncard.io/images/base4/base4-2.png', 'unlimited: Legal', '52', 'Blastoise', '9', 'WOTC', 'Rare Holo', '', '2/24/2000', '', 'Colorless, Colorless, Colorless', '', 'Base', '2', 'Stage 2', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('base4-20', '', '', 'Ken Sugimori', '[{\'name\': \'Thunder\', \'cost\': [\'Lightning\', \'Lightning\', \'Lightning\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'60\', \'text\': \'Flip a coin. If tails, Zapdos does 30 damage to itself.\'}, {\'name\': \'Thunderbolt\', \'cost\': [\'Lightning\', \'Lightning\', \'Lightning\', \'Lightning\'], \'convertedEnergyCost\': 4, \'damage\': \'100\', \'text\': \'Discard all Energy cards attached to Zapdos in order to use this attack.\'}]', 'Base Set 2', '3', '', '', 'A legendary bird Pokémon said to appear from clouds while wielding enormous lightning bolts.', 'First', '90', 'https://images.pokemoncard.io/images/base4/base4-20.png', 'unlimited: Legal', '64', 'Zapdos', '145', 'WOTC', 'Rare Holo', '', '2/24/2000', 'type: Fighting, value: -30', 'Colorless, Colorless, Colorless', '', 'Base', '20', 'Basic', 'Pokémon', 'Lightning', ''),
('base4-21', '', '', 'Ken Sugimori', '[{\'name\': \'Twineedle\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'30×\', \'text\': \'Flip 2 coins. This attack does 30 damage times the number of heads.\'}, {\'name\': \'Poison Sting\', \'cost\': [\'Grass\', \'Grass\', \'Grass\'], \'convertedEnergyCost\': 3, \'damage\': \'40\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Poisoned.\'}]', 'Base Set 2', '', 'Kakuna', '', 'Flies at high speed and attacks using the large, venomous stingers on its forelegs and tail.', 'First', '80', 'https://images.pokemoncard.io/images/base4/base4-21.png', 'unlimited: Legal', '32', 'Beedrill', '15', 'WOTC', 'Rare', '', '2/24/2000', 'type: Fighting, value: -30', '', '', 'Base', '21', 'Stage 2', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('base4-22', '', '', 'Mitsuhiro Arita', '[{\'name\': \'Slam\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'30×\', \'text\': \'Flip 2 coins. This attack does 30 damage times the number of heads.\'}, {\'name\': \'Hyper Beam\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'20\', \'text\': \'If the Defending Pokémon has any Energy cards attached to it, choose 1 of them and discard it.\'}]', 'Base Set 2', '2', 'Dratini', 'Dragonite', 'A mystical Pokémon that exudes a gentle aura. Has the ability to change climate conditions.', 'First', '80', 'https://images.pokemoncard.io/images/base4/base4-22.png', 'unlimited: Legal', '33', 'Dragonair', '148', 'WOTC', 'Rare', '', '2/24/2000', 'type: Psychic, value: -30', 'Colorless, Colorless', '', 'Base', '22', 'Stage 1', 'Pokémon', 'Colorless', ''),
('base4-23', '', '', 'Keiji Kinebuchi', '[{\'name\': \'Slash\', \'cost\': [\'Fighting\', \'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40\', \'text\': \'\'}, {\'name\': \'Earthquake\', \'cost\': [\'Fighting\', \'Fighting\', \'Fighting\', \'Fighting\'], \'convertedEnergyCost\': 4, \'damage\': \'70\', \'text\': \"Does 10 damage to each of your own Benched Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'Base Set 2', '2', 'Diglett', '', 'A team of Diglett triplets. It triggers huge earthquakes by burrowing 60 miles underground.', 'First', '70', 'https://images.pokemoncard.io/images/base4/base4-23.png', 'unlimited: Legal', '36', 'Dugtrio', '51', 'WOTC', 'Rare', '', '2/24/2000', 'type: Lightning, value: -30', 'Colorless, Colorless', '', 'Base', '23', 'Stage 1', 'Pokémon', 'Fighting', 'type: Grass, value: ×2'),
('base4-24', '', '', 'Ken Sugimori', '[{\'name\': \'Thundershock\', \'cost\': [\'Lightning\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Paralyzed.\'}, {\'name\': \'Thunderpunch\', \'cost\': [\'Lightning\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30+\', \'text\': \'Flip a coin. If heads, this attack does 30 damage plus 10 more damage; if tails, this attack does 30 damage and Electabuzz does 10 damage to itself.\'}]', 'Base Set 2', '2', '', 'Electivire', 'Normally found near power plants, it can wander away and cause major blackouts in cities.', 'First', '70', 'https://images.pokemoncard.io/images/base4/base4-24.png', 'unlimited: Legal', '35', 'Electabuzz', '125', 'WOTC', 'Rare', '', '2/24/2000', '', 'Colorless, Colorless', '', 'Base', '24', 'Basic', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
('base4-25', '[{\'name\': \'Buzzap\', \'text\': \"At any time during your turn (before your attack), you may Knock Out Electrode and attach it to 1 of your other Pokémon. If you do, choose a type of Energy. Electrode is now an Energy card of that type (instead of a Pokémon) that provides 2 energy. This power can\'t be used if Electrode is Asleep, Confused, or Paralyzed.\", \'type\': \'Pokémon Power\'}]', '', 'Keiji Kinebuchi', '[{\'name\': \'Electric Shock\', \'cost\': [\'Lightning\', \'Lightning\', \'Lightning\'], \'convertedEnergyCost\': 3, \'damage\': \'50\', \'text\': \'Flip a coin. If tails, Electrode does 10 damage to itself.\'}]', 'Base Set 2', '1', 'Voltorb', '', 'It stores electrical energy under very high pressure. It often explodes with little or no provocation.', 'First', '80', 'https://images.pokemoncard.io/images/base4/base4-25.png', 'unlimited: Legal', '40', 'Electrode', '101', 'WOTC', 'Rare', '', '2/24/2000', '', 'Colorless', '', 'Base', '25', 'Stage 1', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
('base4-26', '', '', 'Mitsuhiro Arita', '[{\'name\': \'Fetch\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Draw a card.\'}, {\'name\': \'Comet Punch\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'20×\', \'text\': \'Flip 4 coins. This attack does 20 damage times the number of heads.\'}]', 'Base Set 2', '3', '', '', 'The infant rarely ventures out of its mothers protective pouch until it is three years old.', 'First', '90', 'https://images.pokemoncard.io/images/base4/base4-26.png', 'unlimited: Legal', '40', 'Kangaskhan', '115', 'WOTC', 'Rare', '', '2/24/2000', 'type: Psychic, value: -30', 'Colorless, Colorless, Colorless', '', 'Base', '26', 'Basic', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('base4-27', '[{\'name\': \'Invisible Wall\', \'text\': \'Whenever an attack (including your own) does 30 or more damage to Mr. Mime (after applying Weakness and Resistance), prevent that damage. (Any other effects of attacks still happen.) This power stops working while Mr. Mime is Asleep, Confused, or Paralyzed.\', \'type\': \'Pokémon Power\'}]', '', 'Ken Sugimori', '[{\'name\': \'Meditate\', \'cost\': [\'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'10+\', \'text\': \'Does 10 damage plus 10 more damage for each damage counter on the Defending Pokémon.\'}]', 'Base Set 2', '1', 'Mime Jr.', '', 'If interrupted while miming, it will slap around the enemy with its broad hands.', 'First', '40', 'https://images.pokemoncard.io/images/base4/base4-27.png', 'unlimited: Legal', '28', 'Mr. Mime', '122', 'WOTC', 'Rare', '', '2/24/2000', '', 'Colorless', '', 'Base', '27', 'Basic', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2'),
('base4-28', '', '', 'Ken Sugimori', '[{\'name\': \'Whirlwind\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'If your opponent has any Benched Pokémon, he or she chooses 1 of them and switches it with the Defending Pokémon. (Do the damage before switching the Pokémon.)\'}, {\'name\': \'Mirror Move\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'\', \'text\': \'If Pidgeotto was attacked last turn, do the final result of that attack on Pidgeotto to the Defending Pokémon.\'}]', 'Base Set 2', '1', 'Pidgey', 'Pidgeot', 'Very protective of its sprawling territory, this Pokémon will fiercely peck at any intruder.', 'First', '60', 'https://images.pokemoncard.io/images/base4/base4-28.png', 'unlimited: Legal', '36', 'Pidgeotto', '17', 'WOTC', 'Rare', '', '2/24/2000', 'type: Fighting, value: -30', 'Colorless', '', 'Base', '28', 'Stage 1', 'Pokémon', 'Colorless', 'type: Lightning, value: ×2'),
('base4-29', '', '', 'Kagemaru Himeno', '[{\'name\': \'Irongrip\', \'cost\': [\'Grass\', \'Grass\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Paralyzed.\'}, {\'name\': \'Guillotine\', \'cost\': [\'Grass\', \'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'50\', \'text\': \'\'}]', 'Base Set 2', '1', '', '', 'If it fails to crush the victim in its pincers, it will swing its victim around and toss it hard.', 'First', '60', 'https://images.pokemoncard.io/images/base4/base4-29.png', 'unlimited: Legal', '24', 'Pinsir', '127', 'WOTC', 'Rare', '', '2/24/2000', '', 'Colorless', '', 'Base', '29', 'Basic', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('base4-3', '', '', 'Ken Sugimori', '[{\'name\': \'Scrunch\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'\', \'text\': \"Flip a coin. If heads, prevent all damage done to Chansey during your opponent\'s next turn. (Any other effects of attacks still happen.)\"}, {\'name\': \'Double-edge\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'80\', \'text\': \'Chansey does 80 damage to itself.\'}]', 'Base Set 2', '1', '', 'Blissey', 'A rare and elusive Pokémon that is said to bring happiness to those who manage to catch it.', 'First', '120', 'https://images.pokemoncard.io/images/base4/base4-3.png', 'unlimited: Legal', '55', 'Chansey', '113', 'WOTC', 'Rare Holo', '', '2/24/2000', 'type: Psychic, value: -30', 'Colorless', '', 'Base', '3', 'Basic', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('base4-30', '[{\'name\': \'Thick Skinned\', \'text\': \"Snorlax can\'t become Asleep, Confused, Paralyzed, or Poisoned. This power can\'t be used if Snorlax is already Asleep, Confused, or Paralyzed.\", \'type\': \'Pokémon Power\'}]', '', 'Ken Sugimori', '[{\'name\': \'Body Slam\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'30\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Paralyzed.\'}]', 'Base Set 2', '4', 'Munchlax', '', 'Very lazy. Just eats and sleeps. As its rotund bulk builds, it becomes steadily more slothful.', 'First', '90', 'https://images.pokemoncard.io/images/base4/base4-30.png', 'unlimited: Legal', '20', 'Snorlax', '143', 'WOTC', 'Rare', '', '2/24/2000', 'type: Psychic, value: -30', 'Colorless, Colorless, Colorless, Colorless', '', 'Base', '30', 'Basic', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('base4-31', '[{\'name\': \'Shift\', \'text\': \"Once during your turn (before your attack), you may change the type of Venomoth to the type of any other Pokémon in play other than Colorless. This power can\'t be used if Venomoth is Asleep, Confused, or Paralyzed.\", \'type\': \'Pokémon Power\'}]', '', 'Ken Sugimori', '[{\'name\': \'Venom Powder\', \'cost\': [\'Grass\', \'Grass\'], \'convertedEnergyCost\': 2, \'damage\': \'10\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Confused and Poisoned.\'}]', 'Base Set 2', '', 'Venonat', '', 'The dust-like scales covering its wings are color coded to indicate the kinds of poison it has.', 'First', '70', 'https://images.pokemoncard.io/images/base4/base4-31.png', 'unlimited: Legal', '28', 'Venomoth', '49', 'WOTC', 'Rare', '', '2/24/2000', 'type: Fighting, value: -30', '', '', 'Base', '31', 'Stage 1', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('base4-32', '', '', 'Ken Sugimori', '[{\'name\': \'Lure\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'If your opponent has any Benched Pokémon, choose 1 of them and switch it with his or her Active Pokémon.\'}, {\'name\': \'Acid\', \'cost\': [\'Grass\', \'Grass\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \"Flip a coin. If heads, the Defending Pokémon can\'t retreat during your next turn.\"}]', 'Base Set 2', '2', 'Weepinbell', '', 'Said to live in huge colonies deep in jungles, although no one has ever returned from there.', 'First', '80', 'https://images.pokemoncard.io/images/base4/base4-32.png', 'unlimited: Legal', '42', 'Victreebel', '71', 'WOTC', 'Rare', '', '2/24/2000', '', 'Colorless, Colorless', '', 'Base', '32', 'Stage 2', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('base4-33', '', '', 'Ken Sugimori', '[{\'name\': \'Flamethrower\', \'cost\': [\'Fire\', \'Fire\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50\', \'text\': \'Discard 1 Fire Energy card attached to Arcanine in order to use this attack.\'}, {\'name\': \'Take Down\', \'cost\': [\'Fire\', \'Fire\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'80\', \'text\': \'Arcanine does 30 damage to itself.\'}]', 'Base Set 2', '3', 'Growlithe', '', 'A Pokémon that has been long admired for its beauty. It runs gracefully, as if on wings.', 'First', '100', 'https://images.pokemoncard.io/images/base4/base4-33.png', 'unlimited: Legal', '45', 'Arcanine', '59', 'WOTC', 'Uncommon', '', '2/24/2000', '', 'Colorless, Colorless, Colorless', '', 'Base', '33', 'Stage 1', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('base4-34', '', '', 'Kagemaru Himeno', '[{\'name\': \'Whirlwind\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'If your opponent has any Benched Pokémon, he or she chooses 1 of them and switches it with the Defending Pokémon. (Do the damage before switching the Pokémon.)\'}, {\'name\': \'Mega Drain\', \'cost\': [\'Grass\', \'Grass\', \'Grass\', \'Grass\'], \'convertedEnergyCost\': 4, \'damage\': \'40\', \'text\': \'Remove a number of damage counters from Butterfree equal to half the damage done to the Defending Pokémon (after applying Weakness and Resistance) (rounded up to the nearest 10). If Butterfree has fewer damage counters than that, remove all of them.\'}]', 'Base Set 2', '', 'Metapod', '', 'In battle, it flaps its wings at high speed to release highly toxic dust into the air.', 'First', '70', 'https://images.pokemoncard.io/images/base4/base4-34.png', 'unlimited: Legal', '28', 'Butterfree', '12', 'WOTC', 'Uncommon', '', '2/24/2000', 'type: Fighting, value: -30', '', '', 'Base', '34', 'Stage 2', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('base4-35', '', '', 'Mitsuhiro Arita', '[{\'name\': \'Slash\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'30\', \'text\': \'\'}, {\'name\': \'Flamethrower\', \'cost\': [\'Fire\', \'Fire\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50\', \'text\': \'Discard 1 Fire Energy card attached to Charmeleon in order to use this attack.\'}]', 'Base Set 2', '1', 'Charmander', 'Charizard', 'When it swings its burning tail, it raises the temperature to unbearably high levels.', 'First', '80', 'https://images.pokemoncard.io/images/base4/base4-35.png', 'unlimited: Legal', '32', 'Charmeleon', '5', 'WOTC', 'Uncommon', '', '2/24/2000', '', 'Colorless', '', 'Base', '35', 'Stage 1', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('base4-36', '', '', 'Mitsuhiro Arita', '[{\'name\': \'Aurora Beam\', \'cost\': [\'Water\', \'Water\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50\', \'text\': \'\'}, {\'name\': \'Ice Beam\', \'cost\': [\'Water\', \'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'30\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Paralyzed.\'}]', 'Base Set 2', '3', 'Seel', '', 'Stores thermal energy in its body. Swims at a steady 8 knots even in intensely cold waters.', 'First', '80', 'https://images.pokemoncard.io/images/base4/base4-36.png', 'unlimited: Legal', '42', 'Dewgong', '87', 'WOTC', 'Uncommon', '', '2/24/2000', '', 'Colorless, Colorless, Colorless', '', 'Base', '36', 'Stage 1', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('base4-37', '[{\'name\': \'Retreat Aid\', \'text\': \'As long as Dodrio is Benched, pay Colorless less to retreat your Active Pokémon.\', \'type\': \'Pokémon Power\'}]', '', 'Mitsuhiro Arita', '[{\'name\': \'Rage\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'10+\', \'text\': \'Does 10 damage plus 10 more damage for each damage counter on Dodrio.\'}]', 'Base Set 2', '', 'Doduo', '', 'Uses its three brains to execute complex plans. While two heads sleep, one head stays awake.', 'First', '70', 'https://images.pokemoncard.io/images/base4/base4-37.png', 'unlimited: Legal', '28', 'Dodrio', '85', 'WOTC', 'Uncommon', '', '2/24/2000', 'type: Fighting, value: -30', '', '', 'Base', '37', 'Stage 1', 'Pokémon', 'Colorless', 'type: Lightning, value: ×2'),
('base4-38', '', '', 'Ken Sugimori', '[{\'name\': \'Pound\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'\'}]', 'Base Set 2', '1', '', 'Dragonair', 'Long considered a mythical Pokémon until recently, when a small colony was found living underwater.', 'First', '40', 'https://images.pokemoncard.io/images/base4/base4-38.png', 'unlimited: Legal', '10', 'Dratini', '147', 'WOTC', 'Uncommon', '', '2/24/2000', 'type: Psychic, value: -30', 'Colorless', '', 'Base', '38', 'Basic', 'Pokémon', 'Colorless', ''),
