('basep-52', '', '', 'Mitsuhiro Arita', '[{\'name\': \'Sacred Wing\', \'cost\': [\'Fire\', \'Fire\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'60\', \'text\': \"Flip a coin. If tails, this attack\'s base damage is 20 instead of 60.\"}]', 'Wizards Black Star Promos', '2', '', '', '', 'First', '80', 'https://images.pokemoncard.io/images/basep/basep-52.png', 'unlimited: Legal', '', 'Ho-oh', '250', 'WOTC', 'Promo', '', '07/01/1999', 'type: Fighting, value: -30', 'Colorless, Colorless', '', 'Base', '52', 'Basic', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('basep-53', '[{\'name\': \'Pure Body\', \'text\': \'To attach a Water Energy card from your hand to Suicune, you must discard an Energy card attached to Suicune. (Attach the Water Energy, and then discard an Energy card from Suicune.)\', \'type\': \'Poké-Body\'}]', '', 'Atsuko Nishida', '[{\'name\': \'Hypno Wave\', \'cost\': [\'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'30+\', \'text\': \'Flip a coin. If heads, this attack does 30 damage plus 20 more damage. If tails, this attack does 30 damage and the Defending Pokémon is now Asleep.\'}]', 'Wizards Black Star Promos', '1', '', '', '', 'First', '70', 'https://images.pokemoncard.io/images/basep/basep-53.png', 'unlimited: Legal', '', 'Suicune', '245', 'WOTC', 'Promo', '', '07/01/1999', '', 'Colorless', '', 'Base', '53', 'Basic', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('basep-6', '', '', 'Ken Sugimori', '[{\'name\': \'Quick Attack\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'10+\', \'text\': \'Flip a coin. If heads, this attack does 10 damage plus 20 more damage; if tails, this attack does 10 damage.\'}, {\'name\': \'Flames of Rage\', \'cost\': [\'Fire\', \'Fire\'], \'convertedEnergyCost\': 2, \'damage\': \'40+\', \'text\': \'Discard 2 Fire Energy cards attached to Arcanine in order to use this attack. This attack does 40 damage plus 10 more damage for each damage counter on Arcanine.\'}]', 'Wizards Black Star Promos', '1', 'Growlithe', '', 'A legendary Pokémon famous for its beauty. It looks almost as if it flies when it runs.', 'First', '70', 'https://images.pokemoncard.io/images/basep/basep-6.png', 'unlimited: Legal', '34', 'Arcanine', '59', 'WOTC', 'Promo', '', '07/01/1999', '', 'Colorless', '', 'Base', '6', 'Stage 1', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
