('bw1-100', '', '', 'Ayaka Yoshida', '', 'Black & White', '', '', '', '', 'Fifth', '', 'https://images.pokemoncard.io/images/bw1/bw1-100.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Potion', '', 'TPCI', 'Common', '', '4/25/2011', '', '', '[\'Heal 30 damage from 1 of your Pokémon.\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Black & White', '100', 'Item', 'Trainer', '', ''),
('bw1-101', '', '', 'Ken Sugimori', '', 'Black & White', '', '', '', '', 'Fifth', '', 'https://images.pokemoncard.io/images/bw1/bw1-101.png', 'unlimited: Legal, expanded: Legal', '', 'Professor Juniper', '', 'TPCI', 'Uncommon', '', '4/25/2011', '', '', '[\'Discard your hand and draw 7 cards.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Black & White', '101', 'Supporter', 'Trainer', '', ''),
