('bw7-131', '', '', 'Yuri Umemura', '', 'Boundaries Crossed', '', '', '', '', 'Fifth', '', 'https://images.pokemoncard.io/images/bw7/bw7-131.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Poké Ball', '', 'TPCI', 'Common', '', '11/07/2012', '', '', '[\'Flip a coin. If heads, search your deck for a Pokémon, reveal it, and put it into your hand. Shuffle your deck afterward.\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Black & White', '131', 'Item', 'Trainer', '', ''),
('bw7-132', '', '', 'Ayaka Yoshida', '', 'Boundaries Crossed', '', '', '', '', 'Fifth', '', 'https://images.pokemoncard.io/images/bw7/bw7-132.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Potion', '', 'TPCI', 'Common', '', '11/07/2012', '', '', '[\'Heal 30 damage from 1 of your Pokémon.\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Black & White', '132', 'Item', 'Trainer', '', ''),
