('bw7-134', '', '', 'Yusuke Ohmura', '', 'Boundaries Crossed', '', '', '', '', 'Fifth', '', 'https://images.pokemoncard.io/images/bw7/bw7-134.png', 'unlimited: Legal, expanded: Legal', '', 'Skyla', '', 'TPCI', 'Uncommon', '', '11/07/2012', '', '', '[\'Search your deck for a Trainer card, reveal it, and put it into your hand. Shuffle your deck afterward.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Black & White', '134', 'Supporter', 'Trainer', '', ''),
('bw7-135', '', '', 'Ayaka Yoshida', '', 'Boundaries Crossed', '', '', '', '', 'Fifth', '', 'https://images.pokemoncard.io/images/bw7/bw7-135.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Switch', '', 'TPCI', 'Common', '', '11/07/2012', '', '', '[\'Switch your Active Pokémon with 1 of your Benched Pokémon.\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Black & White', '135', 'Item', 'Trainer', '', ''),
('bw7-136', '', '', 'Toyste Beach', '', 'Boundaries Crossed', '', '', '', '', 'Fifth', '', 'https://images.pokemoncard.io/images/bw7/bw7-136.png', 'unlimited: Legal, expanded: Legal', '', 'Town Map', '', 'TPCI', 'Uncommon', '', '11/07/2012', '', '', '[\'Turn all of your Prize cards face up. (Those Prize cards remain face up for the rest of the game.)\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Black & White', '136', 'Item', 'Trainer', '', ''),
('bw7-137', '', '', 'Ryo Ueda', '', 'Boundaries Crossed', '', '', '', '', 'Fifth', '', 'https://images.pokemoncard.io/images/bw7/bw7-137.png', 'unlimited: Legal, expanded: Legal', '', 'Computer Search', '', 'TPCI', 'Rare ACE', '', '11/07/2012', '', '', '[\"Discard 2 cards from your hand. (If you can\'t discard 2 cards, you can\'t play this card.) Search your deck for a card and put it into your hand. Shuffle your deck afterward.\", \'You may play as many Item cards as you like during your turn (before your attack).\', \"You can\'t have more than 1 ACE SPEC card in your deck.\"]', 'Black & White', '137', 'Item, ACE SPEC', 'Trainer', '', ''),
('bw7-138', '', '', '5ban Graphics', '', 'Boundaries Crossed', '', '', '', '', 'Fifth', '', 'https://images.pokemoncard.io/images/bw7/bw7-138.png', 'unlimited: Legal, expanded: Legal', '', 'Crystal Edge', '', 'TPCI', 'Rare ACE', '', '11/07/2012', '', '', '[\"Attach a Pokémon Tool to 1 of your Pokémon that doesn\'t already have a Pokémon Tool attached to it.\", \'If this card is attached to White Kyurem-EX, each of its attacks does 50 more damage to the Active Pokémon (before applying Weakness and Resistance).\', \'You may play as many Item cards as you like during your turn (before your attack).\', \"You can\'t have more than 1 ACE SPEC card in your deck.\"]', 'Black & White', '138', 'Pokémon Tool, ACE SPEC', 'Trainer', '', ''),
