('bw7-147', '', '', 'Megumi Mizutani', '', 'Boundaries Crossed', '', '', '', '', 'Fifth', '', 'https://images.pokemoncard.io/images/bw7/bw7-147.png', 'unlimited: Legal, expanded: Legal', '', 'Bianca', '', 'TPCI', 'Rare Ultra', '', '11/07/2012', '', '', '[\'Draw cards until you have 6 cards in your hand.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Black & White', '147', 'Supporter', 'Trainer', '', ''),
('bw7-148', '', '', 'Megumi Mizutani', '', 'Boundaries Crossed', '', '', '', '', 'Fifth', '', 'https://images.pokemoncard.io/images/bw7/bw7-148.png', 'unlimited: Legal, expanded: Legal', '', 'Cheren', '', 'TPCI', 'Rare Ultra', '', '11/07/2012', '', '', '[\'Draw 3 cards.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Black & White', '148', 'Supporter', 'Trainer', '', ''),
('bw7-149', '', '', 'Kanako Eo', '', 'Boundaries Crossed', '', '', '', '', 'Fifth', '', 'https://images.pokemoncard.io/images/bw7/bw7-149.png', 'unlimited: Legal, expanded: Legal', '', 'Skyla', '', 'TPCI', 'Rare Ultra', '', '11/07/2012', '', '', '[\'Search your deck for a Trainer card, reveal it, and put it into your hand. Shuffle your deck afterward.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Black & White', '149', 'Supporter', 'Trainer', '', ''),
('bw7-15', '', '', 'Kagemaru Himeno', '[{\'name\': \'Fluffy Tag\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Switch this Pokémon with 1 of your Benched Pokémon. During your next turn, the attacks of that Pokémon do 40 more damage to the Active Pokémon (before applying Weakness and Resistance).\'}, {\'name\': \'Stun Spore\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'20\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Paralyzed.\'}]', 'Boundaries Crossed', '1', 'Cottonee', '', 'They appear along with whirlwinds. They pull pranks, such as moving furniture and leaving balls of cotton in homes.', 'Fifth', '80', 'https://images.pokemoncard.io/images/bw7/bw7-15.png', 'unlimited: Legal, expanded: Legal', '', 'Whimsicott', '547', 'TPCI', 'Rare', '', '11/07/2012', 'type: Water, value: -20', 'Colorless', '', 'Black & White', '15', 'Stage 1', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('bw7-150', '', '', '5ban Graphics', '[{\'name\': \'Devolution Punch\', \'cost\': [\'Psychic\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60\', \'text\': \"Devolve the Defending Pokémon and put the highest Stage evolution card on it into your opponent\'s hand.\"}, {\'name\': \'Ghost Hammer\', \'cost\': [\'Psychic\', \'Psychic\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'90\', \'text\': \"During your opponent\'s next turn, this Pokémon has no Weakness.\"}]', 'Boundaries Crossed', '4', 'Golett', '', 'This extremely rare Pokémon is a different color than usual. It is very hard to find.', 'Fifth', '130', 'https://images.pokemoncard.io/images/bw7/bw7-150.png', 'unlimited: Legal, expanded: Legal', '', 'Golurk', '623', 'TPCI', 'Rare Secret', '', '11/07/2012', '', 'Colorless, Colorless, Colorless, Colorless', '', 'Black & White', '150', 'Stage 1', 'Pokémon', 'Psychic', 'type: Darkness, value: ×2'),
('bw7-151', '', '', '5ban Graphics', '[{\'name\': \'Retaliate\', \'cost\': [\'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30+\', \'text\': \"If any of your Pokémon were Knocked Out by damage from an opponent\'s attack during his or her last turn, this attack does 60 more damage.\"}, {\'name\': \'Land Crush\', \'cost\': [\'Fighting\', \'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'90\', \'text\': \'\'}]', 'Boundaries Crossed', '4', '', '', 'This extremely rare Pokémon is a different color than usual. It is very hard to find.', 'Fifth', '130', 'https://images.pokemoncard.io/images/bw7/bw7-151.png', 'unlimited: Legal, expanded: Legal', '', 'Terrakion', '639', 'TPCI', 'Rare Secret', '', '11/07/2012', '', 'Colorless, Colorless, Colorless, Colorless', '', 'Black & White', '151', 'Basic', 'Pokémon', 'Fighting', 'type: Grass, value: ×2'),
('bw7-152', '[{\'name\': \'Fight Song\', \'text\': \"Your Dragon Pokémon\'s attacks do 20 more damage to the Active Pokémon (before applying Weakness and Resistance).\", \'type\': \'Ability\'}]', '', '5ban Graphics', '[{\'name\': \'Glide\', \'cost\': [\'Water\', \'Metal\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40\', \'text\': \'\'}]', 'Boundaries Crossed', '1', 'Swablu', '', 'This extremely rare Pokémon is a different color than usual. It is very hard to find.', 'Fifth', '70', 'https://images.pokemoncard.io/images/bw7/bw7-152.png', 'unlimited: Legal, expanded: Legal', '', 'Altaria', '334', 'TPCI', 'Rare Secret', '', '11/07/2012', '', 'Colorless', '', 'Black & White', '152', 'Stage 1', 'Pokémon', 'Dragon', 'type: Dragon, value: ×2'),
('bw7-153', '', '', 'Ryo Ueda', '', 'Boundaries Crossed', '', '', '', '', 'Fifth', '', 'https://images.pokemoncard.io/images/bw7/bw7-153.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Rocky Helmet', '', 'TPCI', 'Rare Secret', '', '11/07/2012', '', '', '[\"Attach a Pokémon Tool to 1 of your Pokémon that doesn\'t already have a Pokémon Tool attached to it.\", \"If the Pokémon this card is attached to is your Active Pokémon and is damage by an opponent\'s attack (even if that Pokémon is Knocked Out), put 2 damage counters on the Attacking Pokémon.\", \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Black & White', '153', 'Pokémon Tool', 'Trainer', '', ''),
('bw7-16', '', '', 'sui', '[{\'name\': \'Sleep Powder\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Asleep.\'}]', 'Boundaries Crossed', '1', '', 'Lilligant', 'The leaves on its head grow right back even if they fall out. These bitter leaves refresh those who eat them.', 'Fifth', '50', 'https://images.pokemoncard.io/images/bw7/bw7-16.png', 'unlimited: Legal, expanded: Legal', '', 'Petilil', '548', 'TPCI', 'Uncommon', '', '11/07/2012', 'type: Water, value: -20', 'Colorless', '', 'Black & White', '16', 'Basic', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('bw7-17', '', '', 'Kanako Eo', '[{\'name\': \'Return\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'20\', \'text\': \'Draw cards until you have 6 cards in your hand.\'}, {\'name\': \'Magical Leaf\', \'cost\': [\'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50+\', \'text\': \'Flip a coin. If heads, this attack does 30 more damage and heal 30 damage from this Pokémon.\'}]', 'Boundaries Crossed', '1', 'Petilil', '', 'The fragrance of the garland on its head has a relaxing effect, but taking care of it is very difficult.', 'Fifth', '80', 'https://images.pokemoncard.io/images/bw7/bw7-17.png', 'unlimited: Legal, expanded: Legal', '', 'Lilligant', '549', 'TPCI', 'Rare', '', '11/07/2012', 'type: Water, value: -20', 'Colorless', '', 'Black & White', '17', 'Stage 1', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('bw7-18', '', '', 'Akira Komayama', '[{\'name\': \'Draw In\', \'cost\': [\'Fire\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Attach 2 Fire Energy cards from your discard pile to this Pokémon.\'}, {\'name\': \'Flare\', \'cost\': [\'Fire\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'\'}]', 'Boundaries Crossed', '2', '', 'Charmeleon', 'The fire on the tip of its tail is a measure of its life. If healthy, its tail burns intensely.', 'Fifth', '70', 'https://images.pokemoncard.io/images/bw7/bw7-18.png', 'unlimited: Legal, expanded: Legal', '', 'Charmander', '4', 'TPCI', 'Common', '', '11/07/2012', '', 'Colorless, Colorless', '', 'Black & White', '18', 'Basic', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('bw7-19', '', '', 'Masakazu Fukuda', '[{\'name\': \'Flare\', \'cost\': [\'Fire\'], \'convertedEnergyCost\': 1, \'damage\': \'20\', \'text\': \'\'}, {\'name\': \'Raging Claws\', \'cost\': [\'Fire\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50+\', \'text\': \'Does 10 more damage for each damage counter on this Pokémon.\'}]', 'Boundaries Crossed', '2', 'Charmander', 'Charizard', 'In the rocky mountains where Charmeleon live, their fiery tails shine at night like stars.', 'Fifth', '90', 'https://images.pokemoncard.io/images/bw7/bw7-19.png', 'unlimited: Legal, expanded: Legal', '', 'Charmeleon', '5', 'TPCI', 'Uncommon', '', '11/07/2012', '', 'Colorless, Colorless', '', 'Black & White', '19', 'Stage 1', 'Pokémon', 'Fire', 'type: Water, value: ×2');
