('bw8-135', '', '', 'Kanako Eo', '', 'Plasma Storm', '', '', '', '', 'Fifth', '', 'https://images.pokemoncard.io/images/bw8/bw8-135.png', 'unlimited: Legal, expanded: Legal', '', 'Colress', '', 'TPCI', 'Rare Ultra', '', '02/06/2013', '', '', '[\"Shuffle your hand into your deck. Then, draw a number of cards equal to the number of Benched Pokémon (both yours and your opponent\'s).\", \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Black & White', '135', 'Supporter, Team Plasma', 'Trainer', '', ''),
('bw8-136', '', '', 'Ayaka Yoshida', '[{\'name\': \'Split Bomb\', \'cost\': [\'Fire\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'\', \'text\': \"This attack does 40 damage to 2 of your opponent\'s Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}, {\'name\': \'Scorching Fire\', \'cost\': [\'Fire\', \'Colorless\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 5, \'damage\': \'150\', \'text\': \'Discard a Fire Energy attached to this Pokémon.\'}]', 'Plasma Storm', '3', 'Charmeleon', '', 'This extremely rare Pokémon is a different color than usual. It is very hard to find.', 'Fifth', '160', 'https://images.pokemoncard.io/images/bw8/bw8-136.png', 'unlimited: Legal, expanded: Legal', '', 'Charizard', '6', 'TPCI', 'Rare Secret', '', '02/06/2013', '', 'Colorless, Colorless, Colorless', '', 'Black & White', '136', 'Stage 2', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('bw8-137', '[{\'name\': \'Deluge\', \'text\': \'As often as you like during your turn (before your attack), you may attach a Water Energy card from your hand to 1 of your Pokémon.\', \'type\': \'Ability\'}]', '', 'Ayaka Yoshida', '[{\'name\': \'Hydro Pump\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'60+\', \'text\': \'Does 10 more damage for each Water Energy attached to this Pokémon.\'}]', 'Plasma Storm', '4', 'Wartortle', '', 'This extremely rare Pokémon is a different color than usual. It is very hard to find.', 'Fifth', '140', 'https://images.pokemoncard.io/images/bw8/bw8-137.png', 'unlimited: Legal, expanded: Legal', '', 'Blastoise', '9', 'TPCI', 'Rare Secret', '', '02/06/2013', '', 'Colorless, Colorless, Colorless, Colorless', '', 'Black & White', '137', 'Stage 2', 'Pokémon', 'Water', 'type: Grass, value: ×2'),
('bw8-138', '', '', '5ban Graphics', '', 'Plasma Storm', '', '', '', '', 'Fifth', '', 'https://images.pokemoncard.io/images/bw8/bw8-138.png', 'unlimited: Legal, expanded: Legal', '', 'Random Receiver', '', 'TPCI', 'Rare Secret', '', '02/06/2013', '', '', '[\'Reveal cards from the top of your deck until you reveal a Supporter card. Put it into your hand. Shuffle the other cards back into your deck.\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Black & White', '138', 'Item', 'Trainer', '', ''),
('bw8-14', '', '', 'Eske Yoshinob', '[{\'name\': \'Destructive Flame\', \'cost\': [\'Fire\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'Flip a coin. If heads, discard an Energy attached to the Defending Pokémon.\'}, {\'name\': \'Power Flame\', \'cost\': [\'Fire\', \'Fire\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'80+\', \'text\': \'If this Pokémon has any Plasma Energy attached to it, this attack does 40 more damage.\'}]', 'Plasma Storm', '1', '', '', '', 'Fifth', '170', 'https://images.pokemoncard.io/images/bw8/bw8-14.png', 'unlimited: Legal, expanded: Legal', '', 'Moltres-EX', '146', 'TPCI', 'Rare Holo EX', '', '02/06/2013', 'type: Fighting, value: -20', 'Colorless', '[\'Pokémon-EX rule: When a Pokémon-EX has been Knocked Out, your opponent takes 2 Prize cards.\']', 'Black & White', '14', 'Basic, EX, Team Plasma', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('bw8-15', '', '', 'sui', '[{\'name\': \'Flare\', \'cost\': [\'Fire\'], \'convertedEnergyCost\': 1, \'damage\': \'20\', \'text\': \'\'}]', 'Plasma Storm', '1', '', 'Monferno', 'It is very agile. Before going to sleep, it extinguishes the flame on its tail to prevent fires.', 'Fifth', '50', 'https://images.pokemoncard.io/images/bw8/bw8-15.png', 'unlimited: Legal, expanded: Legal', '', 'Chimchar', '390', 'TPCI', 'Common', '', '02/06/2013', '', 'Colorless', '', 'Black & White', '15', 'Basic', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('bw8-16', '', '', 'Masakazu Fukuda', '[{\'name\': \'Loud Howl\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Your opponent Switches the Defending Pokémon with 1 of his or her Benched Pokémon.\'}, {\'name\': \'Fire Tail Slap\', \'cost\': [\'Fire\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'50\', \'text\': \'Discard an Energy attached to this Pokémon.\'}]', 'Plasma Storm', '1', 'Chimchar', 'Infernape', 'It skillfully controls the intensity of the fire on its tail to keep its foes at an ideal distance.', 'Fifth', '80', 'https://images.pokemoncard.io/images/bw8/bw8-16.png', 'unlimited: Legal, expanded: Legal', '', 'Monferno', '391', 'TPCI', 'Uncommon', '', '02/06/2013', '', 'Colorless', '', 'Black & White', '16', 'Stage 1', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('bw8-17', '', '', '5ban Graphics', '[{\'name\': \'Torment\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'30\', \'text\': \"Choose 1 of the Defending Pokémon\'s attack. That Pokémon can\'t use that attack during your opponent\'s next turn.\"}, {\'name\': \'Malevolent Fire\', \'cost\': [\'Fire\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'120\', \'text\': \'Discard all Energy attached to this Pokémon.\'}]', 'Plasma Storm', '', 'Monferno', '', 'It uses unique fighting moves with fire on its hand and feet. It will take on any opponent.', 'Fifth', '130', 'https://images.pokemoncard.io/images/bw8/bw8-17.png', 'unlimited: Legal, expanded: Legal', '', 'Infernape', '392', 'TPCI', 'Rare Holo', '', '02/06/2013', '', '', '', 'Black & White', '17', 'Stage 2, Team Plasma', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('bw8-18', '', '', 'Eske Yoshinob', '[{\'name\': \'Turbo Energize\', \'cost\': [\'Fire\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Search your deck for 2 basic Energy cards and attach them to your Benched Pokémon in any way you like. Shuffle your deck afterward.\'}, {\'name\': \'Intensifying Burn\', \'cost\': [\'Fire\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50+\', \'text\': \'If the Defending Pokémon is a Pokémon-EX, this attack does 50 more damage.\'}]', 'Plasma Storm', '1', '', '', '', 'Fifth', '110', 'https://images.pokemoncard.io/images/bw8/bw8-18.png', 'unlimited: Legal, expanded: Legal', '', 'Victini-EX', '494', 'TPCI', 'Rare Holo EX', '', '02/06/2013', '', 'Colorless', '[\'Pokémon-EX rule: When a Pokémon-EX has been Knocked Out, your opponent takes 2 Prize cards.\']', 'Black & White', '18', 'Basic, EX', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('bw8-19', '', '', 'Atsuko Nishida', '[{\'name\': \'Scratch\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'\'}, {\'name\': \'Double Fire\', \'cost\': [\'Fire\', \'Fire\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40×\', \'text\': \'Flip 2 coins. This attack does 40 damage times the number of heads.\'}]', 'Plasma Storm', '1', '', 'Simisear', 'Very intelligent, it roasts berries before eating them. It likes to help people.', 'Fifth', '70', 'https://images.pokemoncard.io/images/bw8/bw8-19.png', 'unlimited: Legal, expanded: Legal', '', 'Pansear', '513', 'TPCI', 'Common', '', '02/06/2013', '', 'Colorless', '', 'Black & White', '19', 'Basic', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('bw8-2', '', '', 'Sumiyoshi Kizuki', '[{\'name\': \'Knock Away\', \'cost\': [\'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40+\', \'text\': \'Flip a coin. If heads, this attack does 20 more damage.\'}]', 'Plasma Storm', '3', 'Turtwig', 'Torterra', 'It knows where pure water wells up. It carries fellow Pokémon there on its back.', 'Fifth', '100', 'https://images.pokemoncard.io/images/bw8/bw8-2.png', 'unlimited: Legal, expanded: Legal', '', 'Grotle', '388', 'TPCI', 'Uncommon', '', '02/06/2013', 'type: Water, value: -20', 'Colorless, Colorless, Colorless', '', 'Black & White', '2', 'Stage 1', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('bw8-20', '', '', 'Naoki Saito', '[{\'name\': \'Searing Flame\', \'cost\': [\'Fire\'], \'convertedEnergyCost\': 1, \'damage\': \'20\', \'text\': \'The Defending Pokémon is now Burned.\'}, {\'name\': \'Flame Blast\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40+\', \'text\': \'Does 20 more damage for each Fire Energy attached to this Pokémon.\'}]', 'Plasma Storm', '2', 'Pansear', '', 'When it gets excited, embers rise from its head and tail and it gets hot. For some reason, it loves sweets.', 'Fifth', '90', 'https://images.pokemoncard.io/images/bw8/bw8-20.png', 'unlimited: Legal, expanded: Legal', '', 'Simisear', '514', 'TPCI', 'Uncommon', '', '02/06/2013', '', 'Colorless, Colorless', '', 'Black & White', '20', 'Stage 1', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('bw8-21', '', '', 'Kouki Saitou', '[{\'name\': \'Surprise Attack\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'20\', \'text\': \'Flip a coin. If tails, this attack does nothing.\'}]', 'Plasma Storm', '1', '', 'Lampent', 'Its flame is usually out, but it starts shining when it absorbs life force from people or Pokémon.', 'Fifth', '60', 'https://images.pokemoncard.io/images/bw8/bw8-21.png', 'unlimited: Legal, expanded: Legal', '', 'Litwick', '607', 'TPCI', 'Common', '', '02/06/2013', '', 'Colorless', '', 'Black & White', '21', 'Basic', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('bw8-22', '[{\'name\': \'Freefloating\', \'text\': \'If this Pokémon has no Energy attached to it, this Pokémon has no Retreat Cost.\', \'type\': \'Ability\'}]', '', 'Kouki Saitou', '[{\'name\': \'Will-O-Wisp\', \'cost\': [\'Fire\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'\'}]', 'Plasma Storm', '1', 'Litwick', 'Chandelure', 'The spirits it absorbs fuel its baleful fire. It hangs around hospitals waiting for people to pass on.', 'Fifth', '70', 'https://images.pokemoncard.io/images/bw8/bw8-22.png', 'unlimited: Legal, expanded: Legal', '', 'Lampent', '608', 'TPCI', 'Uncommon', '', '02/06/2013', '', 'Colorless', '', 'Black & White', '22', 'Stage 1', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('bw8-23', '', '', 'Suwama Chiaki', '[{\'name\': \'Luring Flame\', \'cost\': [\'Fire\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Switch 1 of your opponent\'s Benched Pokémon with the Defending Pokémon. The new Defending Pokémon is now Burned.\"}, {\'name\': \'Fiery Licks\', \'cost\': [\'Fire\', \'Fire\', \'Fire\'], \'convertedEnergyCost\': 3, \'damage\': \'50×\', \'text\': \'Discard the top 4 cards of your deck. This attack does 50 damage times the number of Fire Energy cards discarded.\'}]', 'Plasma Storm', '2', '', '', 'It draws in air through its tail, transforms it into fire, and uses it like a tongue. It melts Durant and eats them.', 'Fifth', '90', 'https://images.pokemoncard.io/images/bw8/bw8-23.png', 'unlimited: Legal, expanded: Legal', '', 'Heatmor', '631', 'TPCI', 'Uncommon', '', '02/06/2013', '', 'Colorless, Colorless', '', 'Black & White', '23', 'Basic', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('bw8-24', '', '', 'Naoki Saito', '[{\'name\': \'Tackle\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'\'}]', 'Plasma Storm', '1', '', 'Wartortle', 'It shelters itself in its shell, then strikes back with spouts of water at every opportunity.', 'Fifth', '60', 'https://images.pokemoncard.io/images/bw8/bw8-24.png', 'unlimited: Legal, expanded: Legal', '', 'Squirtle', '7', 'TPCI', 'Common', '', '02/06/2013', '', 'Colorless', '', 'Black & White', '24', 'Basic', 'Pokémon', 'Water', 'type: Grass, value: ×2'),
('bw8-25', '', '', 'Toyste Beach', '[{\'name\': \'Blizzard\', \'cost\': [\'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60\', \'text\': \"Does 10 damage to each of your opponent\'s Benched Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}, {\'name\': \'Frost Prison\', \'cost\': [\'Water\', \'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'80\', \'text\': \'If this Pokémon has any Plasma Energy attached to it, the Defending Pokémon is now Paralyzed.\'}]', 'Plasma Storm', '1', '', '', '', 'Fifth', '170', 'https://images.pokemoncard.io/images/bw8/bw8-25.png', 'unlimited: Legal, expanded: Legal', '', 'Articuno-EX', '144', 'TPCI', 'Rare Holo EX', '', '02/06/2013', 'type: Fighting, value: -20', 'Colorless', '[\'Pokémon-EX rule: When a Pokémon-EX has been Knocked Out, your opponent takes 2 Prize cards.\']', 'Black & White', '25', 'Basic, EX, Team Plasma', 'Pokémon', 'Water', 'type: Metal, value: ×2'),
('bw8-26', '', '', 'Kouki Saitou', '[{\'name\': \'Double Headbutt\', \'cost\': [\'Water\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20×\', \'text\': \'Flip 2 coins. This attack does 20 damage times the number of heads.\'}]', 'Plasma Storm', '2', '', 'Piloswine', 'Rooting the tip of its snout into the ground, it searches for food. Sometimes, it even digs up a hot spring.', 'Fifth', '60', 'https://images.pokemoncard.io/images/bw8/bw8-26.png', 'unlimited: Legal, expanded: Legal', '', 'Swinub', '220', 'TPCI', 'Common', '', '02/06/2013', '', 'Colorless, Colorless', '', 'Black & White', '26', 'Basic', 'Pokémon', 'Water', 'type: Metal, value: ×2'),
('bw8-27', '', '', 'Suwama Chiaki', '[{\'name\': \'Ice Beam\', \'cost\': [\'Water\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Paralyzed.\'}, {\'name\': \'Quintuple Headbutt\', \'cost\': [\'Water\', \'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'40×\', \'text\': \'Flip 5 coins. This attack does 40 damage times the number of heads.\'}]', 'Plasma Storm', '3', 'Swinub', 'Mamoswine', 'With its excellent sense of smell, its even able to find mushrooms that are buried under frozen ground.', 'Fifth', '100', 'https://images.pokemoncard.io/images/bw8/bw8-27.png', 'unlimited: Legal, expanded: Legal', '', 'Piloswine', '221', 'TPCI', 'Uncommon', '', '02/06/2013', '', 'Colorless, Colorless, Colorless', '', 'Black & White', '27', 'Stage 1', 'Pokémon', 'Water', 'type: Metal, value: ×2'),
('bw8-28', '', '', 'match', '[{\'name\': \'Frost Stone\', \'cost\': [\'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50+\', \'text\': \'Flip a coin. If heads, this attack does 20 more damage and the Defending Pokémon is now Paralyzed.\'}, {\'name\': \'Continuous Headbutt\', \'cost\': [\'Water\', \'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'90×\', \'text\': \'Flip a coin until you get tails. This attack does 90 damage times the number of heads.\'}]', 'Plasma Storm', '4', 'Piloswine', '', 'When the temperature rose at the end of the ice age, most Mamoswine disappeared.', 'Fifth', '150', 'https://images.pokemoncard.io/images/bw8/bw8-28.png', 'unlimited: Legal, expanded: Legal', '', 'Mamoswine', '473', 'TPCI', 'Rare', '', '02/06/2013', '', 'Colorless, Colorless, Colorless, Colorless', '', 'Black & White', '28', 'Stage 2', 'Pokémon', 'Water', 'type: Metal, value: ×2'),
('bw8-29', '', '', 'Midori Harada', '[{\'name\': \'Bubble Beam\', \'cost\': [\'Water\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Paralyzed.\'}]', 'Plasma Storm', '1', '', 'Lombre', 'It looks like an aquatic plant and serves as a ferry to Pokémon that cant swim.', 'Fifth', '60', 'https://images.pokemoncard.io/images/bw8/bw8-29.png', 'unlimited: Legal, expanded: Legal', '', 'Lotad', '270', 'TPCI', 'Common', '', '02/06/2013', '', 'Colorless', '', 'Black & White', '29', 'Basic', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('bw8-3', '', '', '5ban Graphics', '[{\'name\': \'Guard Press\', \'cost\': [\'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60\', \'text\': \"During your opponent\'s next turn, any damage to this Pokémon by attacks is reduced by 20 (after applying Weakness and Resistance).\"}, {\'name\': \'Rumble Stomp\', \'cost\': [\'Grass\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'80+\', \'text\': \'Flip a coin until you get tails. This attack does 20 more damage for each heads.\'}]', 'Plasma Storm', '4', 'Grotle', '', 'Some Pokémon are born on a Torterras back and spend their entire life there.', 'Fifth', '150', 'https://images.pokemoncard.io/images/bw8/bw8-3.png', 'unlimited: Legal, expanded: Legal', '', 'Torterra', '389', 'TPCI', 'Rare', '', '02/06/2013', 'type: Water, value: -20', 'Colorless, Colorless, Colorless, Colorless', '', 'Black & White', '3', 'Stage 2, Team Plasma', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('bw8-30', '', '', 'Suwama Chiaki', '[{\'name\': \'Jump On\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20+\', \'text\': \'Flip a coin. If heads, this attack does 20 more damage.\'}, {\'name\': \'Wave Splash\', \'cost\': [\'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50\', \'text\': \'\'}]', 'Plasma Storm', '2', 'Lotad', 'Ludicolo', 'It has a mischievous spirit. If it spots an angler, it will tug on the fishing line to interfere.', 'Fifth', '80', 'https://images.pokemoncard.io/images/bw8/bw8-30.png', 'unlimited: Legal, expanded: Legal', '', 'Lombre', '271', 'TPCI', 'Uncommon', '', '02/06/2013', '', 'Colorless, Colorless', '', 'Black & White', '30', 'Stage 1', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('bw8-31', '[{\'name\': \'Rain Dish\', \'text\': \'At any times between turns, heal 20 damage from this Pokémon.\', \'type\': \'Ability\'}]', '', 'match', '[{\'name\': \'Groovy Dance\', \'cost\': [\'Water\', \'Water\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'70\', \'text\': \'You may discard an Energy attached to this Pokémon. If you do, the Defending Pokémon is now Confused.\'}]', 'Plasma Storm', '3', 'Lombre', '', 'If it hears festive music, all its muscles fill with energy. It cant help breaking out into a dance.', 'Fifth', '130', 'https://images.pokemoncard.io/images/bw8/bw8-31.png', 'unlimited: Legal, expanded: Legal', '', 'Ludicolo', '272', 'TPCI', 'Rare', '', '02/06/2013', '', 'Colorless, Colorless, Colorless', '', 'Black & White', '31', 'Stage 2', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('bw8-32', '', '', 'Mitsuhiro Arita', '[{\'name\': \'Bite\', \'cost\': [\'Water\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'\'}]', 'Plasma Storm', '1', '', 'Sharpedo', 'They swarm any foe that invades their territory. Their sharp fangs can tear out boat hulls.', 'Fifth', '60', 'https://images.pokemoncard.io/images/bw8/bw8-32.png', 'unlimited: Legal, expanded: Legal', '', 'Carvanha', '318', 'TPCI', 'Common', '', '02/06/2013', '', 'Colorless', '', 'Black & White', '32', 'Basic', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('bw8-33', '[{\'name\': \'Rough Skin\', \'text\': \"If this Pokémon is your Active Pokémon and is damaged by an opponent\'s attack (even if this Pokémon is Knocked Out), put 2 damage counters on the Attacking Pokémon.\", \'type\': \'Ability\'}]', '', '5ban Graphics', '[{\'name\': \'Hard Bite\', \'cost\': [\'Water\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'40+\', \'text\': \'Flip a coin. If heads, this attack does 20 more damage.\'}]', 'Plasma Storm', '', 'Carvanha', '', 'Its fangs rip through sheet iron. It swims at 75 mph and is known as', 'Fifth', '90', 'https://images.pokemoncard.io/images/bw8/bw8-33.png', 'unlimited: Legal, expanded: Legal', '', 'Sharpedo', '319', 'TPCI', 'Rare', '', '02/06/2013', '', '', '', 'Black & White', '33', 'Stage 1, Team Plasma', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('bw8-34', '[{\'name\': \'Final Wish\', \'text\': \"When this Pokémon is Knocked Out by damage from an opponent\'s attack, search your deck for a card and put it into your hand. Shuffle your deck afterward.\", \'type\': \'Ability\'}]', '', 'Naoki Saito', '[{\'name\': \'Seafaring\', \'cost\': [\'Water\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Flip 3 coins. For each heads, attach a Water Energy card from your discard pile to your Benched Pokémon in any way you like.\'}]', 'Plasma Storm', '1', '', '', 'It is born with a wondrous power that lets it bond with any kind of Pokémon.', 'Fifth', '70', 'https://images.pokemoncard.io/images/bw8/bw8-34.png', 'unlimited: Legal, expanded: Legal', '', 'Manaphy', '490', 'TPCI', 'Rare Holo', '', '02/06/2013', '', 'Colorless', '', 'Black & White', '34', 'Basic', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('bw8-35', '', '', 'Shin Nagasawa', '[{\'name\': \'Snow Squall\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \"This attack\'s damage isn\'t affected by Resistance.\"}]', 'Plasma Storm', '1', '', 'Vanillish', 'Theoretically, this Pokémon formed from icicles bathed in energy from the morning sun. Their breath is -58° F.', 'Fifth', '60', 'https://images.pokemoncard.io/images/bw8/bw8-35.png', 'unlimited: Legal, expanded: Legal', '', 'Vanillite', '582', 'TPCI', 'Common', '', '02/06/2013', '', 'Colorless', '', 'Black & White', '35', 'Basic', 'Pokémon', 'Water', 'type: Metal, value: ×2'),
