('bw9-112', '[{\'name\': \'Bright Down\', \'text\': \"Prevent all effects of attacks, including damage, done to this Pokémon by your opponent\'s Pokémon with Abilities.\", \'type\': \'Ability\'}]', '', 'Ryo Ueda', '[{\'name\': \'Barrier Break\', \'cost\': [\'Fire\', \'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'70\', \'text\': \"This attack\'s damage isn\'t affected by Weakness, Resistance, or any other effects on the Defending Pokémon.\"}]', 'Plasma Freeze', '1', '', '', '', 'Fifth', '160', 'https://images.pokemoncard.io/images/bw9/bw9-112.png', 'unlimited: Legal, expanded: Legal', '', 'Latias-EX', '380', 'TPCI', 'Rare Ultra', '', '05/08/2013', '', 'Colorless', '[\'Pokémon-EX rule: When a Pokémon-EX has been Knocked Out, your opponent takes 2 Prize cards.\']', 'Black & White', '112', 'Basic, EX', 'Pokémon', 'Dragon', 'type: Dragon, value: ×2'),
('bw9-113', '', '', 'Ryo Ueda', '[{\'name\': \'Mach Flight\', \'cost\': [\'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'40\', \'text\': \"The Defending Pokémon can\'t retreat during your opponent\'s next turn.\"}, {\'name\': \'Luster Purge\', \'cost\': [\'Water\', \'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'150\', \'text\': \'Discard all Energy attached to this Pokémon.\'}]', 'Plasma Freeze', '2', '', 'M Latios-EX', '', 'Fifth', '170', 'https://images.pokemoncard.io/images/bw9/bw9-113.png', 'unlimited: Legal, expanded: Legal', '', 'Latios-EX', '381', 'TPCI', 'Rare Ultra', '', '05/08/2013', '', 'Colorless, Colorless', '[\'Pokémon-EX rule: When a Pokémon-EX has been Knocked Out, your opponent takes 2 Prize cards.\']', 'Black & White', '113', 'Basic, EX', 'Pokémon', 'Dragon', 'type: Dragon, value: ×2'),
('bw9-114', '', '', '5ban Graphics', '[{\'name\': \'Windfall\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Shuffle your hand into your deck. Then, draw 6 cards.\'}, {\'name\': \'Jet Blast\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'60+\', \'text\': \'This attack does 30 more damage for each Plasma Energy attached to this Pokémon.\'}]', 'Plasma Freeze', '2', '', '', '', 'Fifth', '180', 'https://images.pokemoncard.io/images/bw9/bw9-114.png', 'unlimited: Legal, expanded: Legal', '', 'Tornadus-EX', '641', 'TPCI', 'Rare Ultra', '', '05/08/2013', 'type: Fighting, value: -20', 'Colorless, Colorless', '[\'Pokémon-EX rule: When a Pokémon-EX has been Knocked Out, your opponent takes 2 Prize cards.\']', 'Black & White', '114', 'Basic, EX, Team Plasma', 'Pokémon', 'Colorless', 'type: Lightning, value: ×2'),
('bw9-115', '', '', 'Kanako Eo', '', 'Plasma Freeze', '', '', '', '', 'Fifth', '', 'https://images.pokemoncard.io/images/bw9/bw9-115.png', 'unlimited: Legal, expanded: Banned', '', 'Ghetsis', '', 'TPCI', 'Rare Ultra', '', '05/08/2013', '', '', '[\'Your opponent reveals his or her hand and shuffles all Item cards found there into his or her deck. Then, draw a number of cards equal to the number of Item cards your opponent shuffled into his or her deck.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Black & White', '115', 'Supporter, Team Plasma', 'Trainer', '', ''),
('bw9-116', '', '', 'Kanako Eo', '', 'Plasma Freeze', '', '', '', '', 'Fifth', '', 'https://images.pokemoncard.io/images/bw9/bw9-116.png', 'unlimited: Legal, expanded: Legal', '', 'Professor Juniper', '', 'TPCI', 'Rare Ultra', '', '05/08/2013', '', '', '[\'Discard your hand and draw 7 cards.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Black & White', '116', 'Supporter', 'Trainer', '', ''),
('bw9-117', '[{\'name\': \'Diving Draw\', \'text\': \'Once during your turn (before your attack), you may discard 1 card from your hand. Then, draw 2 cards.\', \'type\': \'Ability\'}]', '', 'Ayaka Yoshida', '[{\'name\': \'Attack Command\', \'cost\': [\'Water\'], \'convertedEnergyCost\': 1, \'damage\': \'10×\', \'text\': \"Does 10 damage times the number of Pokémon in play (both yours and your opponent\'s).\"}]', 'Plasma Freeze', '2', 'Prinplup', '', 'This extremely rare Pokémon is a different color than usual. It is very hard to find.', 'Fifth', '140', 'https://images.pokemoncard.io/images/bw9/bw9-117.png', 'unlimited: Legal, expanded: Legal', '', 'Empoleon', '395', 'TPCI', 'Rare Secret', '', '05/08/2013', '', 'Colorless, Colorless', '', 'Black & White', '117', 'Stage 2', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('bw9-118', '[{\'name\': \'Safeguard\', \'text\': \'Prevent all effects of attacks, including damage, done to this Pokémon by Pokémon-EX.\', \'type\': \'Ability\'}]', '', 'Ayaka Yoshida', '[{\'name\': \'Psychic\', \'cost\': [\'Psychic\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50+\', \'text\': \'Does 10 more damage for each Energy attached to the Defending Pokémon.\'}]', 'Plasma Freeze', '1', '', '', 'This extremely rare Pokémon is a different color than usual. It is very hard to find.', 'Fifth', '90', 'https://images.pokemoncard.io/images/bw9/bw9-118.png', 'unlimited: Legal, expanded: Legal', '', 'Sigilyph', '561', 'TPCI', 'Rare Secret', '', '05/08/2013', '', 'Colorless', '', 'Black & White', '118', 'Basic', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2'),
('bw9-119', '[{\'name\': \'Garbotoxin\', \'text\': \"If this Pokémon has a Pokémon Tool card attached to it, each Pokémon in play, in each player\'s hand, and in each player\'s discard pile has no Abilities (except for Garbotoxin).\", \'type\': \'Ability\'}]', '', 'Ayaka Yoshida', '[{\'name\': \'Sludge Toss\', \'cost\': [\'Psychic\', \'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60\', \'text\': \'\'}]', 'Plasma Freeze', '3', 'Trubbish', '', 'This extremely rare Pokémon is a different color than usual. It is very hard to find.', 'Fifth', '100', 'https://images.pokemoncard.io/images/bw9/bw9-119.png', 'unlimited: Legal, expanded: Legal', '', 'Garbodor', '569', 'TPCI', 'Rare Secret', '', '05/08/2013', '', 'Colorless, Colorless, Colorless', '', 'Black & White', '119', 'Stage 1', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2'),
('bw9-12', '', '', '5ban Graphics', '[{\'name\': \'Vengeance\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20+\', \'text\': \'Does 10 more damage for each Pokémon in your discard pile.\'}, {\'name\': \'Heat Tackle\', \'cost\': [\'Fire\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'90\', \'text\': \'This Pokémon does 10 damage to itself.\'}]', 'Plasma Freeze', '2', 'Eevee', '', 'Inhaled air is carried to its flame sac, heated, and exhaled as fire that reaches over 3,000 degrees F.', 'Fifth', '100', 'https://images.pokemoncard.io/images/bw9/bw9-12.png', 'unlimited: Legal, expanded: Legal', '', 'Flareon', '136', 'TPCI', 'Uncommon', '', '05/08/2013', '', 'Colorless, Colorless', '', 'Black & White', '12', 'Stage 1, Team Plasma', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('bw9-120', '', '', 'Ayaka Yoshida', '[{\'name\': \'Mach Cut\', \'cost\': [\'Fighting\'], \'convertedEnergyCost\': 1, \'damage\': \'60\', \'text\': \'Discard a Special Energy attached to the Defending Pokémon.\'}, {\'name\': \'Dragonblade\', \'cost\': [\'Water\', \'Fighting\'], \'convertedEnergyCost\': 2, \'damage\': \'100\', \'text\': \'Discard the top 2 cards of your deck.\'}]', 'Plasma Freeze', '1', 'Gabite', '', 'This extremely rare Pokémon is a different color than usual. It is very hard to find.', 'Fifth', '140', 'https://images.pokemoncard.io/images/bw9/bw9-120.png', 'unlimited: Legal, expanded: Legal', '', 'Garchomp', '445', 'TPCI', 'Rare Secret', '', '05/08/2013', '', 'Colorless', '', 'Black & White', '120', 'Stage 2', 'Pokémon', 'Dragon', 'type: Dragon, value: ×2'),
('bw9-121', '', '', '5ban Graphics', '', 'Plasma Freeze', '', '', '', '', 'Fifth', '', 'https://images.pokemoncard.io/images/bw9/bw9-121.png', 'unlimited: Legal, expanded: Legal', '', 'Max Potion', '', 'TPCI', 'Rare Secret', '', '05/08/2013', '', '', '[\'Heal all damage from 1 of your Pokémon. Then, discard all Energy attached to that Pokémon.\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Black & White', '121', 'Item', 'Trainer', '', ''),
('bw9-122', '', '', '5ban Graphics', '', 'Plasma Freeze', '', '', '', '', 'Fifth', '', 'https://images.pokemoncard.io/images/bw9/bw9-122.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Ultra Ball', '', 'TPCI', 'Rare Secret', '', '05/08/2013', '', '', '[\"Discard 2 cards from your hand. (If you can\'t discard 2 cards, you can\'t play this card.) Search your deck for a Pokémon, reveal it, and put it into your hand. Shuffle your deck afterward.\", \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Black & White', '122', 'Item', 'Trainer', '', ''),
('bw9-13', '', '', 'Eske Yoshinob', '[{\'name\': \'Heat Boiler\', \'cost\': [\'Fire\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60+\', \'text\': \'If this Pokémon is affected by a Special Condition, this attack does 60 more damage.\'}, {\'name\': \'Dynamite Press\', \'cost\': [\'Fire\', \'Fire\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'80+\', \'text\': \'If this Pokémon has any Plasma Energy attached to it, this attack does 10 more damage for each damage counter on the Defending Pokémon.\'}]', 'Plasma Freeze', '3', '', '', '', 'Fifth', '180', 'https://images.pokemoncard.io/images/bw9/bw9-13.png', 'unlimited: Legal, expanded: Legal', '', 'Heatran-EX', '485', 'TPCI', 'Rare Holo EX', '', '05/08/2013', '', 'Colorless, Colorless, Colorless', '[\'Pokémon-EX rule: When a Pokémon-EX has been Knocked Out, your opponent takes 2 Prize cards.\']', 'Black & White', '13', 'Basic, EX, Team Plasma', 'Pokémon', 'Fire', 'type: Water, value: ×2');
