('bwp-BW78', '', '', 'Mizue', '[{\'name\': \'Quick Attack\', \'cost\': [\'Lightning\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30+\', \'text\': \'Flip a coin. If heads, this attack does 20 more damage.\'}, {\'name\': \'Thunder Blast\', \'cost\': [\'Lightning\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'90\', \'text\': \'Discard an Energy attached to this Pokémon.\'}]', 'BW Black Star Promos', '1', 'Pikachu', '', 'Its tail discharges electricity into the ground, protecting it from getting shocked.', 'Fifth', '100', 'https://images.pokemoncard.io/images/bwp/bwp-BW78.png', 'unlimited: Legal, expanded: Legal', '', 'Raichu', '26', 'TPCI', 'Promo', '', '03/01/2011', '', 'Colorless', '', 'Black & White', 'BW78', 'Stage 1', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
('bwp-BW79', '', '', '5ban Graphics', '[{\'name\': \'Extrasensory\', \'cost\': [\'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20+\', \'text\': \'If you have the same number of cards in your hand as your opponent, this attack does 30 more damage.\'}, {\'name\': \'Rock Tomb\', \'cost\': [\'Fighting\', \'Fighting\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'90\', \'text\': \"The Defending Pokémon can\'t retreat during your opponent\'s next turn.\"}]', 'BW Black Star Promos', '2', '', '', 'From the forces of lightning and wind, it creates energy to give nutrients to the soil and make the land abundant.', 'Fifth', '110', 'https://images.pokemoncard.io/images/bwp/bwp-BW79.png', 'unlimited: Legal, expanded: Legal', '', 'Landorus', '645', 'TPCI', 'Promo', '', '03/01/2011', 'type: Lightning, value: -20', 'Colorless, Colorless', '', 'Black & White', 'BW79', 'Basic, Team Plasma', 'Pokémon', 'Fighting', 'type: Water, value: ×2'),
('bwp-BW80', '', '', '5ban Graphics', '[{\'name\': \'Taunt\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Switch 1 of your opponent\'s Benched Pokémon with the Defending Pokémon.\"}, {\'name\': \'Boost Claw\', \'cost\': [\'Fire\', \'Water\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60\', \'text\': \"During your next turn, each of this Pokémon\'s attacks does 30 more damage (before applying Weakness and Resistance).\"}]', 'BW Black Star Promos', '2', '', '', 'It runs through the narrow tunnels formed by Excadrill and Onix. It uses its sharp claws to catch prey.', 'Fifth', '100', 'https://images.pokemoncard.io/images/bwp/bwp-BW80.png', 'unlimited: Legal, expanded: Legal', '', 'Druddigon', '621', 'TPCI', 'Promo', '', '03/01/2011', '', 'Colorless, Colorless', '', 'Black & White', 'BW80', 'Basic, Team Plasma', 'Pokémon', 'Dragon', 'type: Dragon, value: ×2'),
('bwp-BW81', '', '', 'Eske Yoshinob', '[{\'name\': \'Raiden Knuckle\', \'cost\': [\'Lightning\'], \'convertedEnergyCost\': 1, \'damage\': \'30\', \'text\': \'Attach an Energy card from your discard pile to 1 of your Benched Team Plasma Pokémon.\'}, {\'name\': \'Thunderous Noise\', \'cost\': [\'Lightning\', \'Lightning\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'90\', \'text\': \'If this Pokémon has any Plasma Energy attached to it, discard an Energy attached to the Defending Pokémon.\'}]', 'BW Black Star Promos', '1', '', '', '', 'Fifth', '170', 'https://images.pokemoncard.io/images/bwp/bwp-BW81.png', 'unlimited: Legal, expanded: Legal', '', 'Thundurus-EX', '642', 'TPCI', 'Promo', '', '03/01/2011', '', 'Colorless', '[\'Pokémon-EX rule: When a Pokémon-EX has been Knocked Out, your opponent takes 2 Prize cards.\']', 'Black & White', 'BW81', 'Basic, EX, Team Plasma', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
('bwp-BW82', '[{\'name\': \'Power Connect\', \'text\': \"Your Team Plasma Pokémon\'s attacks (excluding Deoxys-EX) do 10 more damage to the Active Pokémon (before applying Weakness and Resistance).\", \'type\': \'Ability\'}]', '', 'Eske Yoshinob', '[{\'name\': \'Helix Force\', \'cost\': [\'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30+\', \'text\': \'If this Pokémon has any Plasma Energy attached to it, this attack does 30 more damage for each Energy attached to the Defending Pokémon.\'}]', 'BW Black Star Promos', '2', '', '', '', 'Fifth', '170', 'https://images.pokemoncard.io/images/bwp/bwp-BW82.png', 'unlimited: Legal, expanded: Legal', '', 'Deoxys-EX', '386', 'TPCI', 'Promo', '', '03/01/2011', '', 'Colorless, Colorless', '[\'Pokémon-EX rule: When a Pokémon-EX has been Knocked Out, your opponent takes 2 Prize cards.\']', 'Black & White', 'BW82', 'Basic, EX, Team Plasma', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2'),
('bwp-BW83', '[{\'name\': \'Overflow\', \'text\': \"If your opponent\'s Pokémon is Knocked Out by damage from an attack of this Pokémon, take 1 more Prize card.\", \'type\': \'Ability\'}]', '', 'Toyste Beach', '[{\'name\': \'Plasma Gale\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'120\', \'text\': \"Discard a Plasma Energy attached to this Pokémon. If you can\'t discard a Plasma Energy, this attack does nothing.\"}]', 'BW Black Star Promos', '2', '', '', '', 'Fifth', '180', 'https://images.pokemoncard.io/images/bwp/bwp-BW83.png', 'unlimited: Legal, expanded: Legal', '', 'Lugia-EX', '249', 'TPCI', 'Promo', '', '03/01/2011', 'type: Fighting, value: -20', 'Colorless, Colorless', '[\'Pokémon-EX rule: When a Pokémon-EX has been Knocked Out, your opponent takes 2 Prize cards.\']', 'Black & White', 'BW83', 'Basic, EX, Team Plasma', 'Pokémon', 'Colorless', 'type: Lightning, value: ×2'),
('bwp-BW84', '[{\'name\': \'Plasma Transfer\', \'text\': \'As often as you like during your turn (before your attack), you may move a Plasma Energy attached to 1 of your Pokémon to another of your Pokémon.\', \'type\': \'Ability\'}]', '', '5ban Graphics', '[{\'name\': \'Tri Attack\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50×\', \'text\': \'Flip 3 coins. This attack does 50 damage times the number of heads.\'}]', 'BW Black Star Promos', '1', 'Porygon2', '', 'Its programming was modified to enable work in alien dimensions. It did not work as planned.', 'Fifth', '130', 'https://images.pokemoncard.io/images/bwp/bwp-BW84.png', 'unlimited: Legal, expanded: Legal', '', 'Porygon-Z', '474', 'TPCI', 'Promo', '', '03/01/2011', '', 'Colorless', '', 'Black & White', 'BW84', 'Stage 2, Team Plasma', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('bwp-BW85', '[{\'name\': \'Intuition\', \'text\': \'When you play this Pokémon from your hand to evolve 1 of your Pokémon, you may draw 2 cards.\', \'type\': \'Ability\'}]', '', 'Masakazu Fukuda', '[{\'name\': \'Fast Punch\', \'cost\': [\'Fighting\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60+\', \'text\': \'Flip a coin. If heads, this attack does 30 more damage.\'}]', 'BW Black Star Promos', '2', 'Riolu', '', 'By reading the auras of all things, it can tell how others are feeling from over half a mile away.', 'Fifth', '100', 'https://images.pokemoncard.io/images/bwp/bwp-BW85.png', 'unlimited: Legal, expanded: Legal', '', 'Lucario', '448', 'TPCI', 'Promo', '', '03/01/2011', '', 'Colorless, Colorless', '', 'Black & White', 'BW85', 'Stage 1', 'Pokémon', 'Fighting', 'type: Psychic, value: ×2'),
('bwp-BW86', '', '', '5ban Graphics', '[{\'name\': \'Signal Beam\', \'cost\': [\'Grass\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Confused.\'}, {\'name\': \'Overdrive Smash\', \'cost\': [\'Grass\', \'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'60\', \'text\': \"During your next turn, this Pokémon\'s Overdrive Smash attack does 60 more damage (before applying Weakness and Resistance).\"}]', 'BW Black Star Promos', '2', '', '', 'This Pokémon existed 300 million years ago. Team Plasma altered it and attached a cannon to its back.', 'Fifth', '100', 'https://images.pokemoncard.io/images/bwp/bwp-BW86.png', 'unlimited: Legal, expanded: Legal', '', 'Genesect', '649', 'TPCI', 'Promo', '', '03/01/2011', '', 'Colorless, Colorless', '', 'Black & White', 'BW86', 'Basic, Team Plasma', 'Pokémon', 'Grass', 'type: Fire, value: ×2');
INSERT INTO `cards` (`id`, `abilities`, `ancient_trait`, `artist`, `attacks`, `card_set`, `converted`, `evolves_from`, `evolves_to`, `flavor_text`, `generation`, `hp`, `img`, `legalities`, `level`, `name`, `national_pokedex_numbers`, `publisher`, `rarity`, `regulation_mark`, `release_date`, `resistances`, `retreat_cost`, `rules`, `series`, `set_num`, `subtypes`, `supertype`, `types`, `weakness`) VALUES
('bwp-BW87', '', '', 'The Pokémon Company Art Team', '[{\'name\': \'Quick Attack\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10+\', \'text\': \'Flip a coin. If heads, this attack does 30 more damage.\'}, {\'name\': \'Energy Assist\', \'cost\': [\'Grass\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'40\', \'text\': \'Attach a basic Energy card from your discard pile to 1 of your Benched Pokémon.\'}]', 'BW Black Star Promos', '1', 'Eevee', '', 'It basically does not fight. With cells similar to those of plants, it can perform photosynthesis.', 'Fifth', '90', 'https://images.pokemoncard.io/images/bwp/bwp-BW87.png', 'unlimited: Legal, expanded: Legal', '', 'Leafeon', '470', 'TPCI', 'Promo', '', '03/01/2011', 'type: Water, value: -20', 'Colorless', '', 'Black & White', 'BW87', 'Stage 1', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('bwp-BW88', '', '', 'The Pokémon Company Art Team', '[{\'name\': \'Sand-Attack\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'20\', \'text\': \"If the Defending Pokémon tries to attack during your opponent\'s next turn, your opponent flips a coin. If tails, that attack does nothing.\"}, {\'name\': \'Fire Slash\', \'cost\': [\'Fire\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60+\', \'text\': \'You may discard a Fire Energy attached to this Pokémon. If you do, this attack does 30 more damage.\'}]', 'BW Black Star Promos', '1', 'Eevee', '', 'Inhaled air is heated in the flame sac in its body to an intense fire over 3,000 degrees Fahrenheit.', 'Fifth', '90', 'https://images.pokemoncard.io/images/bwp/bwp-BW88.png', 'unlimited: Legal, expanded: Legal', '', 'Flareon', '136', 'TPCI', 'Promo', '', '03/01/2011', '', 'Colorless', '', 'Black & White', 'BW88', 'Stage 1', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('bwp-BW89', '', '', 'The Pokémon Company Art Team', '[{\'name\': \'Muddy Water\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'20\', \'text\': \"Does 20 damage to 1 of your opponent\'s Benched Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}, {\'name\': \'Spiral Drain\', \'cost\': [\'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60\', \'text\': \'Recover 20 damage from this Pokémon.\'}]', 'BW Black Star Promos', '2', 'Eevee', '', 'Its cell composition is similar to water molecules. As a result, it can melt away into water.', 'Fifth', '110', 'https://images.pokemoncard.io/images/bwp/bwp-BW89.png', 'unlimited: Legal, expanded: Legal', '', 'Vaporeon', '134', 'TPCI', 'Promo', '', '03/01/2011', '', 'Colorless, Colorless', '', 'Black & White', 'BW89', 'Stage 1', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('bwp-BW90', '', '', 'The Pokémon Company Art Team', '[{\'name\': \'Quick Attack\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10+\', \'text\': \'Flip a coin. If heads, this attack does 30 more damage.\'}, {\'name\': \'Reflect Energy\', \'cost\': [\'Water\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'40\', \'text\': \'Move an Energy from this Pokémon to 1 of your Benched Pokémon.\'}]', 'BW Black Star Promos', '1', 'Eevee', '', 'By controlling its body heat, it can freeze the atmosphere around it to make a diamond-dust flurry.', 'Fifth', '90', 'https://images.pokemoncard.io/images/bwp/bwp-BW90.png', 'unlimited: Legal, expanded: Legal', '', 'Glaceon', '471', 'TPCI', 'Promo', '', '03/01/2011', '', 'Colorless', '', 'Black & White', 'BW90', 'Stage 1', 'Pokémon', 'Water', 'type: Metal, value: ×2'),
('bwp-BW91', '', '', 'The Pokémon Company Art Team', '[{\'name\': \'Electrigun\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'20+\', \'text\': \'You may discard a Lightning Energy attached to this Pokémon. If you do, this attack does 40 more damage.\'}, {\'name\': \'Pin Missile\', \'cost\': [\'Lightning\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40×\', \'text\': \'Flip 4 coins. This attack does 40 damage times the number of heads.\'}]', 'BW Black Star Promos', '', 'Eevee', '', 'If agitated, it uses electricity to straighten out its fur and launch it in small bunches.', 'Fifth', '90', 'https://images.pokemoncard.io/images/bwp/bwp-BW91.png', 'unlimited: Legal, expanded: Legal', '', 'Jolteon', '135', 'TPCI', 'Promo', '', '03/01/2011', '', '', '', 'Black & White', 'BW91', 'Stage 1', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
('bwp-BW92', '[{\'name\': \'Solar Revelation\', \'text\': \"Prevent all effects of your opponent\'s attacks, except damage, done to each of your Pokémon that has any Energy attached to it.\", \'type\': \'Ability\'}]', '', 'The Pokémon Company Art Team', '[{\'name\': \'Psy Report\', \'cost\': [\'Psychic\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60\', \'text\': \'Your opponent reveals his or her hand.\'}]', 'BW Black Star Promos', '1', 'Eevee', '', 'Its fur is so sensitive, it can sense minute shifts in the air and predict the weather.', 'Fifth', '90', 'https://images.pokemoncard.io/images/bwp/bwp-BW92.png', 'unlimited: Legal, expanded: Legal', '', 'Espeon', '196', 'TPCI', 'Promo', '', '03/01/2011', '', 'Colorless', '', 'Black & White', 'BW92', 'Stage 1', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2'),
('bwp-BW93', '', '', 'The Pokémon Company Art Team', '[{\'name\': \'Shadow Drain\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'Heal from this Pokémon the same amount of damage you did to the Defending Pokémon.\'}, {\'name\': \'Slashing Strike\', \'cost\': [\'Darkness\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'80\', \'text\': \"This Pokémon can\'t use Slashing Strike during your next turn.\"}]', 'BW Black Star Promos', '2', 'Eevee', '', 'When exposed to the moons aura, the rings on its body glow faintly and it gains a mysterious power.', 'Fifth', '100', 'https://images.pokemoncard.io/images/bwp/bwp-BW93.png', 'unlimited: Legal, expanded: Legal', '', 'Umbreon', '197', 'TPCI', 'Promo', '', '03/01/2011', 'type: Psychic, value: -20', 'Colorless, Colorless', '', 'Black & White', 'BW93', 'Stage 1', 'Pokémon', 'Darkness', 'type: Fighting, value: ×2'),
('bwp-BW94', '', '', 'The Pokémon Company Art Team', '[{\'name\': \'Growl\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"During your opponent\'s next turn, any damage done by attacks from the Defending Pokémon is reduced by 20 (before applying Weakness and Resistance).\"}, {\'name\': \'Quick Attack\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'10+\', \'text\': \'Flip a coin. If heads, this attack does 10 more damage.\'}]', 'BW Black Star Promos', '1', '', 'Vaporeon, Jolteon, Flareon, Sylveon, Espeon, Umbreon, Leafeon, Glaceon', 'Thanks to its unstable genetic makeup, this special Pokémon conceals many different possible evolutions.', 'Fifth', '60', 'https://images.pokemoncard.io/images/bwp/bwp-BW94.png', 'unlimited: Legal, expanded: Legal', '', 'Eevee', '133', 'TPCI', 'Promo', '', '03/01/2011', '', 'Colorless', '', 'Black & White', 'BW94', 'Basic', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('bwp-BW95', '', '', 'Naoki Saito', '', 'BW Black Star Promos', '', '', '', '', 'Fifth', '', 'https://images.pokemoncard.io/images/bwp/bwp-BW95.png', 'unlimited: Legal, expanded: Legal', '', 'Champions Festival', '', 'TPCI', 'Promo', '', '03/01/2011', '', '', '[\"Once during each player\'s turn, if that player has 6 Pokémon in play, he or she may heal 10 damage from each of his or her Pokémon.\", \"This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can\'t play this card.\"]', 'Black & White', 'BW95', 'Stadium', 'Trainer', '', ''),
('bwp-BW96', '', '', 'Ryo Ueda', '[{\'name\': \'Blow Through\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30+\', \'text\': \'If there is any Stadium card in play, this attack does 30 more damage.\'}, {\'name\': \'Power Blast\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'100\', \'text\': \'Flip a coin. If tails, discard an Energy attached to this Pokémon.\'}]', 'BW Black Star Promos', '1', '', '', '', 'Fifth', '170', 'https://images.pokemoncard.io/images/bwp/bwp-BW96.png', 'unlimited: Legal, expanded: Legal', '', 'Tornadus-EX', '641', 'TPCI', 'Promo', '', '03/01/2011', 'type: Fighting, value: -20', 'Colorless', '[\'Pokémon-EX rule: When a Pokémon-EX has been Knocked Out, your opponent takes 2 Prize cards.\']', 'Black & White', 'BW96', 'Basic, EX', 'Pokémon', 'Colorless', 'type: Lightning, value: ×2'),
('bwp-BW97', '', '', 'Akira Komayama', '[{\'name\': \'Growl\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"During your opponent\'s next turn, any damage done by attacks from the Defending Pokémon is reduced by 20 (before applying Weakness and Resistance).\"}, {\'name\': \'Quick Attack\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'10+\', \'text\': \'Flip a coin. If heads, this attack does 10 more damage.\'}]', 'BW Black Star Promos', '1', '', 'Vaporeon, Jolteon, Flareon, Sylveon, Espeon, Umbreon, Leafeon, Glaceon', 'Thanks to its unstable genetic makeup, this special Pokémon conceals many different possible evolutions.', 'Fifth', '60', 'https://images.pokemoncard.io/images/bwp/bwp-BW97.png', 'unlimited: Legal, expanded: Legal', '', 'Eevee', '133', 'TPCI', 'Promo', '', '03/01/2011', '', 'Colorless', '', 'Black & White', 'BW97', 'Basic', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('bwp-BW98', '[{\'name\': \'Psyscan\', \'text\': \'Once during your turn (before your attack), if this Pokémon is your Active Pokémon, you may have your opponent reveal his or her hand.\', \'type\': \'Ability\'}]', '', 'Naoki Saito', '[{\'name\': \'Psychic Exchange\', \'cost\': [\'Psychic\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Shuffle your hand into your deck. Then, draw 6 cards.\'}]', 'BW Black Star Promos', '1', '', '', 'Because it can use all kinds of moves, many scientists believe Mew to be the ancestor of Pokémon.', 'Fifth', '60', 'https://images.pokemoncard.io/images/bwp/bwp-BW98.png', 'unlimited: Legal, expanded: Legal', '', 'Mew', '151', 'TPCI', 'Promo', '', '03/01/2011', '', 'Colorless', '', 'Black & White', 'BW98', 'Basic', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2'),
('bwp-BW99', '', '', '5ban Graphics', '[{\'name\': \'Hyper Beam\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'Flip a coin. If heads, discard an Energy attached to the Defending Pokémon.\'}, {\'name\': \'Breaker Bazooka\', \'cost\': [\'Grass\', \'Grass\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'100\', \'text\': \'Discard all Grass Energy attached to this Pokémon.\'}]', 'BW Black Star Promos', '2', '', '', 'This Pokémon existed 300 million years ago. Team Plasma altered it and attached a cannon to its back.', 'Fifth', '110', 'https://images.pokemoncard.io/images/bwp/bwp-BW99.png', 'unlimited: Legal, expanded: Legal', '', 'Genesect', '649', 'TPCI', 'Promo', '', '03/01/2011', '', 'Colorless, Colorless', '', 'Black & White', 'BW99', 'Basic', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('cel25-1', '', '', 'Kouki Saitou', '[{\'cost\': [\'Fire\', \'Colorless\'], \'name\': \'Sacred Fire\', \'damage\': \'\', \'text\': \"This attack does 50 damage to 1 of your opponent\'s Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\", \'convertedEnergyCost\': 2}, {\'cost\': [\'Fire\', \'Fire\', \'Colorless\'], \'name\': \'Fire Blast\', \'damage\': \'120\', \'text\': \'Discard an Energy from this Pokémon.\', \'convertedEnergyCost\': 3}]', 'Celebrations', '2', '', '', 'It will reveal itself before a pure-hearted Trainer by shining its bright, rainbow-colored wings.', 'Eighth', '130', 'https://images.pokemoncard.io/images/cel25/cel25-1.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Ho-Oh', '250', 'TPCI', 'Rare', 'E', '10/08/2021', 'type: Fighting, value: -30', 'Colorless, Colorless', '', 'Sword & Shield', '1', 'Basic', 'Pokémon', 'Fire', 'type: Lightning, value: ×2'),
('cel25-10', '', '', 'Aya Kusube', '[{\'cost\': [\'Colorless\', \'Colorless\'], \'name\': \'Field Crush\', \'damage\': \'30\', \'text\': \'If your opponent has a Stadium in play, discard it.\', \'convertedEnergyCost\': 2}, {\'cost\': [\'Lightning\', \'Lightning\', \'Colorless\'], \'name\': \'White Thunder\', \'damage\': \'80+\', \'text\': \'If Reshiram is on your Bench, this attack does 80 more damage.\', \'convertedEnergyCost\': 3}]', 'Celebrations', '3', '', '', 'Concealing itself in lightning clouds, it flies throughout the Unova region. It creates electricity in its tail.', 'Eighth', '130', 'https://images.pokemoncard.io/images/cel25/cel25-10.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Zekrom', '644', 'TPCI', 'Rare', 'E', '10/08/2021', '', 'Colorless, Colorless, Colorless', '', 'Sword & Shield', '10', 'Basic', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
('cel25-11', '[{\'type\': \'Ability\', \'name\': \'Mysterious Tail\', \'text\': \'Once during your turn, if this Pokémon is in the Active Spot, you may look at the top 6 cards of your deck, reveal an Item card you find there, and put it into your hand. Shuffle the other cards back into your deck.\'}]', '', 'Yuu Nishida', '[{\'cost\': [\'Psychic\', \'Colorless\'], \'name\': \'Psyshot\', \'damage\': \'30\', \'text\': \'\', \'convertedEnergyCost\': 2}]', 'Celebrations', '1', '', '', 'Its DNA is said to contain the genetic codes of all Pokémon, so it can use all kinds of techniques.', 'Eighth', '60', 'https://images.pokemoncard.io/images/cel25/cel25-11.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Mew', '151', 'TPCI', 'Rare Holo', 'E', '10/08/2021', 'type: Fighting, value: -30', 'Colorless', '', 'Sword & Shield', '11', 'Basic', 'Pokémon', 'Psychic', 'type: Darkness, value: ×2'),
('cel25-12', '', '', 'AKIRA EGAWA', '[{\'cost\': [\'Colorless\', \'Colorless\'], \'name\': \'Breath of Life\', \'damage\': \'\', \'text\': \'Search your deck for up to 3 basic Energy cards of different types and attach them to your Pokémon in any way you like. Then, shuffle your deck.\', \'convertedEnergyCost\': 2}, {\'cost\': [\'Psychic\', \'Colorless\', \'Colorless\'], \'name\': \'Aurora Horns\', \'damage\': \'100\', \'text\': \'\', \'convertedEnergyCost\': 3}]', 'Celebrations', '2', '', '', 'When the horns on its head shine in seven colors, it is said to be sharing everlasting life.', 'Eighth', '120', 'https://images.pokemoncard.io/images/cel25/cel25-12.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Xerneas', '716', 'TPCI', 'Rare', 'E', '10/08/2021', '', 'Colorless, Colorless', '', 'Sword & Shield', '12', 'Basic', 'Pokémon', 'Psychic', 'type: Metal, value: ×2'),
('cel25-13', '', '', 'kirisAki', '[{\'cost\': [\'Colorless\'], \'name\': \'Star Protection\', \'damage\': \'\', \'text\': \"Flip a coin. If heads, during your opponent\'s next turn, prevent all damage done to this Pokémon by attacks.\", \'convertedEnergyCost\': 1}]', 'Celebrations', '1', '', 'Cosmoem', 'Whether or not its a Pokémon from this world is a mystery. When its in a jam, it warps away to a safe place to hide.', 'Eighth', '60', 'https://images.pokemoncard.io/images/cel25/cel25-13.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Cosmog', '789', 'TPCI', 'Rare', 'E', '10/08/2021', 'type: Fighting, value: -30', 'Colorless', '', 'Sword & Shield', '13', 'Basic', 'Pokémon', 'Psychic', 'type: Darkness, value: ×2'),
('cel25-14', '', '', 'kirisAki', '[{\'cost\': [\'Colorless\'], \'name\': \'Star Protection\', \'damage\': \'\', \'text\': \"Flip a coin. If heads, during your opponent\'s next turn, prevent all damage done to this Pokémon by attacks.\", \'convertedEnergyCost\': 1}]', 'Celebrations', '3', 'Cosmog', 'Solgaleo, Lunala', 'As it absorbs light, Cosmoem continues to grow. Its golden shell is surprisingly solid.', 'Eighth', '90', 'https://images.pokemoncard.io/images/cel25/cel25-14.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Cosmoem', '790', 'TPCI', 'Rare', 'E', '10/08/2021', 'type: Fighting, value: -30', 'Colorless, Colorless, Colorless', '', 'Sword & Shield', '14', 'Stage 1', 'Pokémon', 'Psychic', 'type: Darkness, value: ×2'),
('cel25-15', '', '', 'kirisAki', '[{\'cost\': [\'Colorless\', \'Colorless\'], \'name\': \'Lunar Pain\', \'damage\': \'\', \'text\': \"Double the number of damage counters on each of your opponent\'s Pokémon.\", \'convertedEnergyCost\': 2}, {\'cost\': [\'Psychic\', \'Colorless\', \'Colorless\'], \'name\': \'Psychic Shot\', \'damage\': \'130\', \'text\': \"This attack also does 30 damage to 1 of your opponent\'s Benched Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\", \'convertedEnergyCost\': 3}]', 'Celebrations', '2', 'Cosmoem', '', 'It sometimes summons unknown powers and life-forms here to this world from holes that lead to other worlds.', 'Eighth', '160', 'https://images.pokemoncard.io/images/cel25/cel25-15.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Lunala', '792', 'TPCI', 'Rare Holo', 'E', '10/08/2021', 'type: Fighting, value: -30', 'Colorless, Colorless', '', 'Sword & Shield', '15', 'Stage 2', 'Pokémon', 'Psychic', 'type: Darkness, value: ×2'),
