('dp1-125', '', '', '', '', 'Diamond & Pearl', '', '', '', '', 'Fourth ', '', 'https://images.pokemoncard.io/images/dp1/dp1-125.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Water Energy', '', 'TPCI', 'Common', '', '05/01/2007', '', '', '', 'Diamond & Pearl', '125', 'Basic', 'Energy', '', ''),
('dp1-126', '', '', '', '', 'Diamond & Pearl', '', '', '', '', 'Fourth ', '', 'https://images.pokemoncard.io/images/dp1/dp1-126.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Lightning Energy', '', 'TPCI', 'Common', '', '05/01/2007', '', '', '', 'Diamond & Pearl', '126', 'Basic', 'Energy', '', ''),
