('dp1-129', '', '', '', '', 'Diamond & Pearl', '', '', '', '', 'Fourth ', '', 'https://images.pokemoncard.io/images/dp1/dp1-129.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Darkness Energy', '', 'TPCI', 'Common', '', '05/01/2007', '', '', '', 'Diamond & Pearl', '129', 'Basic', 'Energy', '', ''),
('dp1-13', '', '', 'Nakaoka', '[{\'name\': \'Poison Sting\', \'cost\': [\'Grass\', \'Grass\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'The Defending Pokémon is now Poisoned.\'}, {\'name\': \'Spike Whip\', \'cost\': [\'Grass\', \'Grass\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50\', \'text\': \"If Budew is anywhere under Roserade, choose 1 of your opponent\'s Benched Pokémon. This attack does 30 damage to that Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'Diamond & Pearl', '1', 'Roselia', '', 'It attracts prey with a sweet aroma, then downs it with thorny whips hidden in its arms.', 'Fourth ', '90', 'https://images.pokemoncard.io/images/dp1/dp1-13.png', 'unlimited: Legal', '33', 'Roserade', '407', 'TPCI', 'Rare Holo', '', '05/01/2007', '', 'Colorless', '', 'Diamond & Pearl', '13', 'Stage 1', 'Pokémon', 'Grass', 'type: Fire, value: +20'),
('dp1-130', '', '', '', '', 'Diamond & Pearl', '', '', '', '', 'Fourth ', '', 'https://images.pokemoncard.io/images/dp1/dp1-130.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Metal Energy', '', 'TPCI', 'Common', '', '05/01/2007', '', '', '', 'Diamond & Pearl', '130', 'Basic', 'Energy', '', '');
INSERT INTO `cards` (`id`, `abilities`, `ancient_trait`, `artist`, `attacks`, `card_set`, `converted`, `evolves_from`, `evolves_to`, `flavor_text`, `generation`, `hp`, `img`, `legalities`, `level`, `name`, `national_pokedex_numbers`, `publisher`, `rarity`, `regulation_mark`, `release_date`, `resistances`, `retreat_cost`, `rules`, `series`, `set_num`, `subtypes`, `supertype`, `types`, `weakness`) VALUES
('dp1-14', '[{\'name\': \'Darkness Fan\', \'text\': \"Once during your turn (before your attack), if Shiftry is your Active Pokémon, you may flip a coin. If heads, choose 1 Evolved Pokémon on your opponent\'s Bench, remove the highest Stage Evolution card from that Pokémon, and put it back into his or her hand. This power can\'t be used if Shiftry is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Masakazu Fukuda', '[{\'name\': \'Spirit Dance\', \'cost\': [\'Darkness\', \'Darkness\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50+\', \'text\': \'Flip 2 coins. This attack does 50 damage plus 20 more damage for each heads.\'}]', 'Diamond & Pearl', '2', 'Nuzleaf', '', 'By flapping its leafy fan, it can whip up gusts of 100 ft/second that can level houses.', 'Fourth ', '120', 'https://images.pokemoncard.io/images/dp1/dp1-14.png', 'unlimited: Legal', '48', 'Shiftry', '275', 'TPCI', 'Rare Holo', '', '05/01/2007', 'type: Psychic, value: -20', 'Colorless, Colorless', '', 'Diamond & Pearl', '14', 'Stage 2', 'Pokémon', 'Darkness', 'type: Fighting, value: +30'),
('dp1-15', '', '', 'Hiroaki Ito', '[{\'name\': \'Frustration\', \'cost\': [\'Darkness\', \'Darkness\'], \'convertedEnergyCost\': 2, \'damage\': \'\', \'text\': \"Choose 1 of your opponent\'s Pokémon that doesn\'t have any damage counters on it. This attack does 30 damage to that Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}, {\'name\': \'Toxic Cloud\', \'cost\': [\'Darkness\', \'Darkness\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'30\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Poisoned. Put 2 damage counters instead of 1 on the Defending Pokémon between turns.\'}]', 'Diamond & Pearl', '1', 'Stunky', '', 'It sprays a vile-smelling fluid from the tip of its tail to attack. Its range is over 160 feet.', 'Fourth ', '90', 'https://images.pokemoncard.io/images/dp1/dp1-15.png', 'unlimited: Legal', '36', 'Skuntank', '435', 'TPCI', 'Rare Holo', '', '05/01/2007', 'type: Psychic, value: -20', 'Colorless', '', 'Diamond & Pearl', '15', 'Stage 1', 'Pokémon', 'Darkness', 'type: Fighting, value: +20'),
('dp1-16', '', '', 'Masahiko Ishii', '[{\'name\': \'Accelerative Dive\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'30\', \'text\': \"Flip a coin. If tails, this attack does nothing. If heads, prevent all damage done to Staraptor by attacks (both yours and your opponent\'s) until the end of your next turn.\"}, {\'name\': \'Brave Heart\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'100\', \'text\': \'Flip a coin. If tails, Staraptor does 100 damage to itself.\'}]', 'Diamond & Pearl', '', 'Staravia', '', 'It has a savage nature. It will courageously challenge foes that are much larger.', 'Fourth ', '100', 'https://images.pokemoncard.io/images/dp1/dp1-16.png', 'unlimited: Legal', '54', 'Staraptor', '398', 'TPCI', 'Rare Holo', '', '05/01/2007', 'type: Fighting, value: -20', '', '', 'Diamond & Pearl', '16', 'Stage 2', 'Pokémon', 'Colorless', 'type: Lightning, value: +30'),
('dp1-17', '', '', 'Masahiko Ishii', '[{\'name\': \'Body Slam\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'30\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Paralyzed.\'}, {\'name\': \'Leaf Storm\', \'cost\': [\'Grass\', \'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'60\', \'text\': \'Remove 2 damage counters from each of your Grass Pokémon.\'}]', 'Diamond & Pearl', '4', 'Grotle', '', 'Small Pokémon occasionally gather on its unmoving back to begin building their nests.', 'Fourth ', '140', 'https://images.pokemoncard.io/images/dp1/dp1-17.png', 'unlimited: Legal', '45', 'Torterra', '389', 'TPCI', 'Rare Holo', '', '05/01/2007', '', 'Colorless, Colorless, Colorless, Colorless', '', 'Diamond & Pearl', '17', 'Stage 2', 'Pokémon', 'Grass', 'type: Fire, value: +30'),
('dp1-18', '', '', 'Naoyo Kimura', '[{\'name\': \'Defense Curl\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Flip a coin. If heads, prevent all damage done to Azumarill during your opponent\'s next turn.\"}, {\'name\': \'Bubble Pump\', \'cost\': [\'Water\', \'Water\'], \'convertedEnergyCost\': 2, \'damage\': \'40+\', \'text\': \'If Azumarill has 3 or more Energy attached to it, this attack does 40 damage plus 20 more damage. If Azurill is anywhere under Azumarill, flip a coin. If heads, the Defending Pokémon is now Paralyzed.\'}]', 'Diamond & Pearl', '2', 'Marill', '', 'It lives in rivers and lakes. In water, its coloring and patterns trick the vision of foes.', 'Fourth ', '80', 'https://images.pokemoncard.io/images/dp1/dp1-18.png', 'unlimited: Legal', '35', 'Azumarill', '184', 'TPCI', 'Rare', '', '05/01/2007', '', 'Colorless, Colorless', '', 'Diamond & Pearl', '18', 'Stage 1', 'Pokémon', 'Water', 'type: Lightning, value: +20'),
('dp1-19', '', '', 'Atsuko Nishida', '[{\'name\': \'Whirlwind\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'Your opponent switches the Defending Pokémon with 1 of his or her Benched Pokémon.\'}, {\'name\': \'Giga Drain\', \'cost\': [\'Grass\', \'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'50\', \'text\': \'After your attack, remove from Beautifly the number of damage counters equal to the damage you did to the Defending Pokémon.\'}]', 'Diamond & Pearl', '1', 'Silcoon', '', 'It has an aggressive nature. It stabs prey with its long, narrow mouth to drain the preys fluids.', 'Fourth ', '100', 'https://images.pokemoncard.io/images/dp1/dp1-19.png', 'unlimited: Legal', '29', 'Beautifly', '267', 'TPCI', 'Rare', '', '05/01/2007', 'type: Fighting, value: -20', 'Colorless', '', 'Diamond & Pearl', '19', 'Stage 2', 'Pokémon', 'Grass', 'type: Fire, value: +20'),
('dp1-2', '[{\'name\': \'Dark Palm\', \'text\': \"Once during your turn (before your attack), if your opponent has 4 or more Benched Pokémon, you may choose 1 of them and shuffle that Pokémon and all cards attached to it into his or her deck. This power can\'t be used if Dusknoir if affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Takabon', '[{\'name\': \'Hard Feelings\', \'cost\': [\'Psychic\', \'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'\', \'text\': \'Put 5 damage counters on the Defending Pokémon. Then, count the number of Prize cards your opponent has taken and put that many damage counters on the Defending Pokémon.\'}]', 'Diamond & Pearl', '3', 'Dusclops', '', 'The antenna on its head captures radio waves from the world of spirits that command it to take people there.', 'Fourth ', '120', 'https://images.pokemoncard.io/images/dp1/dp1-2.png', 'unlimited: Legal', '42', 'Dusknoir', '477', 'TPCI', 'Rare Holo', '', '05/01/2007', 'type: Colorless, value: -20', 'Colorless, Colorless, Colorless', '', 'Diamond & Pearl', '2', 'Stage 2', 'Pokémon', 'Psychic', 'type: Darkness, value: +30'),
('dp1-20', '', '', 'Ken Sugimori', '[{\'name\': \'Rest\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Remove all Special Conditions and 4 damage counters from Bibarel. Bibarel is now Asleep.\'}, {\'name\': \'Take Down\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60\', \'text\': \'Bibarel does 10 damage to itself.\'}]', 'Diamond & Pearl', '2', 'Bidoof', '', 'It makes its nest by damming streams with bark and mud. It is known as an industrious worker.', 'Fourth ', '100', 'https://images.pokemoncard.io/images/dp1/dp1-20.png', 'unlimited: Legal', '26', 'Bibarel', '400', 'TPCI', 'Rare', '', '05/01/2007', '', 'Colorless, Colorless', '', 'Diamond & Pearl', '20', 'Stage 1', 'Pokémon', 'Colorless', 'type: Fighting, value: +20'),
('dp1-21', '', '', 'Kouki Saitou', '[{\'name\': \'Swallow Up\', \'cost\': [\'Grass\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \"Before doing damage, count the remaining HP of the Defending Pokémon and Carnivine. If the Defending Pokémon has fewer remaining HP than Carnivine\'s, this attack does 60 damage instead.\"}, {\'name\': \'Wring Out\', \'cost\': [\'Grass\', \'Grass\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Paralyzed and discard an Energy card attached to the Defending Pokémon.\'}]', 'Diamond & Pearl', '1', '', '', 'It attracts prey with its sweet-smelling saliva, then chomps down. It takes a whole day to eat prey.', 'Fourth ', '70', 'https://images.pokemoncard.io/images/dp1/dp1-21.png', 'unlimited: Legal', '32', 'Carnivine', '455', 'TPCI', 'Rare', '', '05/01/2007', 'type: Water, value: -20', 'Colorless', '', 'Diamond & Pearl', '21', 'Basic', 'Pokémon', 'Grass', 'type: Fire, value: +20'),
('dp1-22', '', '', 'Ken Sugimori', '[{\'name\': \'Double Slap\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30×\', \'text\': \'Flip 2 coins. This attack does 30 damage times the number of heads.\'}, {\'name\': \'Metronome\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'\', \'text\': \"Choose 1 of the Defending Pokémon\'s attacks. Metronome copies that attack except for its Energy cost. (You must still do anything else in order to use that attack.) Clefable performs that attack.\"}]', 'Diamond & Pearl', '2', 'Clefairy', '', 'Rarely seen by people, it is said to be drawn by the full moon to play at deserted lakes.', 'Fourth ', '90', 'https://images.pokemoncard.io/images/dp1/dp1-22.png', 'unlimited: Legal', '37', 'Clefable', '36', 'TPCI', 'Rare', '', '05/01/2007', '', 'Colorless, Colorless', '', 'Diamond & Pearl', '22', 'Stage 1', 'Pokémon', 'Colorless', 'type: Fighting, value: +20'),
('dp1-23', '', '', 'Kouki Saitou', '[{\'name\': \'Stomp\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20+\', \'text\': \'Flip a coin. If heads, this attack does 20 damage plus 20 more damage.\'}, {\'name\': \'Poison Claws\', \'cost\': [\'Psychic\', \'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50\', \'text\': \'The Defending Pokémon is now Poisoned.\'}]', 'Diamond & Pearl', '3', 'Skorupi', '', 'It has the power in its clawed arms to make scrap of a car. The tips of its claws release poison.', 'Fourth ', '100', 'https://images.pokemoncard.io/images/dp1/dp1-23.png', 'unlimited: Legal', '41', 'Drapion', '452', 'TPCI', 'Rare', '', '05/01/2007', '', 'Colorless, Colorless, Colorless', '', 'Diamond & Pearl', '23', 'Stage 1', 'Pokémon', 'Psychic', 'type: Psychic, value: +20'),
('dp1-24', '', '', 'Mitsuhiro Arita', '[{\'name\': \'Wind Wave\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Search your discard pile for up to 5 in any combination of Pokémon and Supporter cards. Show them to your opponent and shuffle them into your deck.\'}, {\'name\': \'Explosive Smoke\', \'cost\': [\'Psychic\', \'Psychic\', \'Psychic\'], \'convertedEnergyCost\': 3, \'damage\': \'60\', \'text\': \"Does 10 damage to each Benched Pokémon (both yours and your opponent\'s). (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'Diamond & Pearl', '', 'Drifloon', '', 'Its drowzy in daytime, but flies off in the evening in big groups. No one knows where they go.', 'Fourth ', '80', 'https://images.pokemoncard.io/images/dp1/dp1-24.png', 'unlimited: Legal', '40', 'Drifblim', '426', 'TPCI', 'Rare', '', '05/01/2007', 'type: Colorless, value: -20', '', '', 'Diamond & Pearl', '24', 'Stage 1', 'Pokémon', 'Psychic', 'type: Darkness, value: +20'),
('dp1-25', '', '', 'Kouki Saitou', '[{\'name\': \'Stun Spore\', \'cost\': [\'Grass\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Paralyzed.\'}, {\'name\': \'Toxic Dust\', \'cost\': [\'Grass\', \'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'50\', \'text\': \'The Defending Pokémon is now Poisoned. Put 2 damage counters instead of 1 on the Defending Pokémon between turns.\'}]', 'Diamond & Pearl', '2', 'Cascoon', '', 'A nocturnal Pokémon. Drawn by streetlights, they messily eat the leaves of trees lining boulevards.', 'Fourth ', '120', 'https://images.pokemoncard.io/images/dp1/dp1-25.png', 'unlimited: Legal', '34', 'Dustox', '269', 'TPCI', 'Rare', '', '05/01/2007', '', 'Colorless, Colorless', '', 'Diamond & Pearl', '25', 'Stage 2', 'Pokémon', 'Grass', 'type: Fire, value: +30'),
('dp1-26', '', '', 'Masahiko Ishii', '[{\'name\': \'Screw Tail\', \'cost\': [\'Water\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'Flip a coin. If heads, discard an Energy attached to the Defending Pokémon.\'}, {\'name\': \'Water Gun\', \'cost\': [\'Water\', \'Water\'], \'convertedEnergyCost\': 2, \'damage\': \'40+\', \'text\': \"Does 40 damage plus 20 more damage for each Water Energy attached to Floatzel but not used to pay for this attack\'s Energy cost. You can\'t add more than 40 damage in this way.\"}]', 'Diamond & Pearl', '1', 'Buizel', '', 'It floats using its well-developed floatation sac. It assists in the rescues of drowning people.', 'Fourth ', '90', 'https://images.pokemoncard.io/images/dp1/dp1-26.png', 'unlimited: Legal', '29', 'Floatzel', '419', 'TPCI', 'Rare', '', '05/01/2007', '', 'Colorless', '', 'Diamond & Pearl', '26', 'Stage 1', 'Pokémon', 'Water', 'type: Lightning, value: +20'),
('dp1-27', '', '', 'Kagemaru Himeno', '[{\'name\': \'Life Drain\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Flip a coin. If heads, put damage counter on the Defending Pokémon until it is 10 HP away from being Knocked Out.\'}, {\'name\': \'Shadow Dance\', \'cost\': [\'Psychic\', \'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'\', \'text\': \"Put 4 damage counters on your opponent\'s Pokémon in any way you like. Then, switch Gengar with 1 of your Benched Pokémon.\"}]', 'Diamond & Pearl', '1', 'Haunter', '', 'It hides in shadows. It is said that if Gengar is hiding, it cools that area by nearly 10 degrees F.', 'Fourth ', '110', 'https://images.pokemoncard.io/images/dp1/dp1-27.png', 'unlimited: Legal', '39', 'Gengar', '94', 'TPCI', 'Rare', '', '05/01/2007', 'type: Colorless, value: -20', 'Colorless', '', 'Diamond & Pearl', '27', 'Stage 2', 'Pokémon', 'Psychic', 'type: Darkness, value: +30'),
('dp1-28', '', '', 'Ken Sugimori', '[{\'name\': \'Pitch\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'Your opponent switches the Defending Pokémon with 1 of his or her Benched Pokémon.\'}, {\'name\': \'Horn Slash\', \'cost\': [\'Grass\', \'Grass\'], \'convertedEnergyCost\': 2, \'damage\': \'30+\', \'text\': \'Flip a coin. If heads, this attack does 30 damage plus 30 more damage.\'}]', 'Diamond & Pearl', '2', '', '', 'It gathers in forests to search for tree sap, its favorite food. Its strong enough to hurl foes.', 'Fourth ', '80', 'https://images.pokemoncard.io/images/dp1/dp1-28.png', 'unlimited: Legal', '29', 'Heracross', '214', 'TPCI', 'Rare', '', '05/01/2007', '', 'Colorless, Colorless', '', 'Diamond & Pearl', '28', 'Basic', 'Pokémon', 'Grass', 'type: Fire, value: +20'),
('dp1-29', '', '', 'Kouki Saitou', '[{\'name\': \'Vacuum Up\', \'cost\': [\'Fighting\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40\', \'text\': \"The Defending Pokémon can\'t retreat during your opponent\'s next turn.\"}, {\'name\': \'Sand Eject\', \'cost\': [\'Fighting\', \'Fighting\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'60\', \'text\': \'During your next turn, if an attack does damage to the Defending Pokémon (after applying Weakness and Resistance), that attack does 40 more damage.\'}]', 'Diamond & Pearl', '3', 'Hippopotas', '', 'It blasts internally stored sand from ports on its body to create a towering twister for attack.', 'Fourth ', '110', 'https://images.pokemoncard.io/images/dp1/dp1-29.png', 'unlimited: Legal', '45', 'Hippowdon', '450', 'TPCI', 'Rare', '', '05/01/2007', 'type: Lightning, value: -20', 'Colorless, Colorless, Colorless', '', 'Diamond & Pearl', '29', 'Stage 1', 'Pokémon', 'Fighting', 'type: Water, value: +20'),
('dp1-3', '[{\'name\': \'Intense Voltage\', \'text\': \"As often as you like during your turn (before your attack), if Elekid is anywhere under Electivire, you may move a Lightning Energy attached to your Pokémon to Electivire. This power can\'t be used if Electivire is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Nakaoka', '[{\'name\': \'Giga Impact\', \'cost\': [\'Lightning\', \'Lightning\', \'Lightning\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'60\', \'text\': \"You may discard all Lightning Energy attached to Electivire. If you do, this attack\'s base damage is 120 instead of 60.\"}]', 'Diamond & Pearl', '3', 'Electabuzz', '', 'It pushes the tips of its two tails against the foe, then lets loose with over 20,000 volts of power.', 'Fourth ', '100', 'https://images.pokemoncard.io/images/dp1/dp1-3.png', 'unlimited: Legal', '46', 'Electivire', '466', 'TPCI', 'Rare Holo', '', '05/01/2007', 'type: Metal, value: -20', 'Colorless, Colorless, Colorless', '', 'Diamond & Pearl', '3', 'Stage 1', 'Pokémon', 'Lightning', 'type: Fighting, value: +20'),
('dp1-30', '', '', 'Kagemaru Himeno', '[{\'name\': \'Healing Wish\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Flip a coin until you get tails. Remove a number of damage counters equal to the number of heads from 1 of your Pokémon.\'}, {\'name\': \'Flop\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'30\', \'text\': \"Does 20 damage to 1 of your opponent\'s Benched Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.) You may switch Lopunny with 1 of your Benched Pokémon.\"}]', 'Diamond & Pearl', '1', 'Buneary', '', 'An extremely cautious Pokémon. It cloaks its body with its fluffy ear fur when it senses danger.', 'Fourth ', '80', 'https://images.pokemoncard.io/images/dp1/dp1-30.png', 'unlimited: Legal', '33', 'Lopunny', '428', 'TPCI', 'Rare', '', '05/01/2007', '', 'Colorless', '', 'Diamond & Pearl', '30', 'Stage 1', 'Pokémon', 'Colorless', 'type: Fighting, value: +20'),
('dp1-31', '', '', 'Kagemaru Himeno', '[{\'name\': \'Revenge\', \'cost\': [\'Fighting\'], \'convertedEnergyCost\': 1, \'damage\': \'20+\', \'text\': \"If any of your Pokémon were Knocked Out by damage from an opponent\'s attack during his or her last turn, this attack does 20 damage plus 50 more damage.\"}, {\'name\': \'Dynamic Punch\', \'cost\': [\'Fighting\', \'Fighting\', \'Fighting\'], \'convertedEnergyCost\': 3, \'damage\': \'60+\', \'text\': \'Flip a coin. If heads, this attack does 60 damage plus 30 more damage and the Defending Pokémon is now Confused.\'}]', 'Diamond & Pearl', '3', 'Machoke', '', 'It punches with its four arms at blinding speed. It can launch 1,000 punches in two seconds.', 'Fourth ', '130', 'https://images.pokemoncard.io/images/dp1/dp1-31.png', 'unlimited: Legal', '59', 'Machamp', '68', 'TPCI', 'Rare', '', '05/01/2007', '', 'Colorless, Colorless, Colorless', '', 'Diamond & Pearl', '31', 'Stage 2', 'Pokémon', 'Fighting', 'type: Psychic, value: +30'),
('dp1-32', '', '', 'Kouki Saitou', '[{\'name\': \'Force Palm\', \'cost\': [\'Fighting\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Count the number of damage counters on Medicham. Put that many damage counters on 1 of your opponent\'s Pokémon.\"}, {\'name\': \'Spinning Kick\', \'cost\': [\'Fighting\', \'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'80\', \'text\': \'Medicham does 20 damage to itself.\'}]', 'Diamond & Pearl', '2', 'Meditite', '', 'Through yoga training, it has honed its sixth sense. Its movements are elegant.', 'Fourth ', '90', 'https://images.pokemoncard.io/images/dp1/dp1-32.png', 'unlimited: Legal', '42', 'Medicham', '308', 'TPCI', 'Rare', '', '05/01/2007', '', 'Colorless, Colorless', '', 'Diamond & Pearl', '32', 'Stage 1', 'Pokémon', 'Fighting', 'type: Psychic, value: +20'),
('dp1-33', '[{\'name\': \'Baby Evolution\', \'text\': \'Once during your turn (before your attack), you may put Snorlax from your hand onto Munchlax (this counts as evolving Munchlax) and remove all damage counters from Munchlax.\', \'type\': \'Poké-Power\'}]', '', 'Ken Sugimori', '[{\'name\': \'Heave\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'30×\', \'text\': \"Discard 2 cards from your hand. (If you can\'t discard 2 cards, this attack does nothing.) Flip 2 coins. This attack does 30 damage times the number of heads.\"}]', 'Diamond & Pearl', '2', '', 'Snorlax', 'It wolfs down its weight in food once a day, swallowing food whole with almost no chewing.', 'Fourth ', '60', 'https://images.pokemoncard.io/images/dp1/dp1-33.png', 'unlimited: Legal', '8', 'Munchlax', '446', 'TPCI', 'Rare', '', '05/01/2007', '', 'Colorless, Colorless', '', 'Diamond & Pearl', '33', 'Basic', 'Pokémon', 'Colorless', 'type: Fighting, value: +10'),
('dp1-34', '', '', 'Atsuko Nishida', '[{\'name\': \'See Beyond\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Choose a card from your hand and put it as a Prize card face up. Then, choose 1 of your face-down Prize cards without looking and put it into your hand. This attack does nothing if all of your Prize cards are face up.\'}, {\'name\': \'Extrasensory\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'30+\', \'text\': \'If you have the same number of cards in your hand as your opponent, this attack does 30 damage plus 50 more damage.\'}]', 'Diamond & Pearl', '1', 'Hoothoot', '', 'Its eyes are special. They can pick out objects as long as there is the tiniest amount of light.', 'Fourth ', '90', 'https://images.pokemoncard.io/images/dp1/dp1-34.png', 'unlimited: Legal', '40', 'Noctowl', '164', 'TPCI', 'Rare', '', '05/01/2007', 'type: Fighting, value: -20', 'Colorless', '', 'Diamond & Pearl', '34', 'Stage 1', 'Pokémon', 'Colorless', 'type: Lightning, value: +20'),
('dp1-35', '', '', 'Ken Sugimori', '[{\'name\': \'Minor Errand-Running\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Search your deck for a basic Energy card, show it to your opponent, and put it into your hand. Shuffle your deck afterward.\'}, {\'name\': \'Thunder Jolt\', \'cost\': [\'Lightning\'], \'convertedEnergyCost\': 1, \'damage\': \'20\', \'text\': \'Flip a coin. If tails, Pachirisu does 10 damage to itself.\'}]', 'Diamond & Pearl', '1', '', '', 'It makes fur balls that crackle with static electricity. It stores them with berries in tree holes.', 'Fourth ', '70', 'https://images.pokemoncard.io/images/dp1/dp1-35.png', 'unlimited: Legal', '23', 'Pachirisu', '417', 'TPCI', 'Rare', '', '05/01/2007', 'type: Metal, value: -20', 'Colorless', '', 'Diamond & Pearl', '35', 'Basic', 'Pokémon', 'Lightning', 'type: Fighting, value: +20'),
('dp1-36', '', '', 'Masakazu Fukuda', '[{\'name\': \'High Hat\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Choose 1 card from your opponent\'s hand without looking and discard it.\"}, {\'name\': \'Body Slam\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'50\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Paralyzed.\'}]', 'Diamond & Pearl', '1', 'Glameow', '', 'It is a brazen brute that barges its way into another Pokémons nest and claims it as its own.', 'Fourth ', '90', 'https://images.pokemoncard.io/images/dp1/dp1-36.png', 'unlimited: Legal', '44', 'Purugly', '432', 'TPCI', 'Rare', '', '05/01/2007', '', 'Colorless', '', 'Diamond & Pearl', '36', 'Stage 1', 'Pokémon', 'Colorless', 'type: Fighting, value: +20'),
('dp1-37', '', '', 'Ken Sugimori', '[{\'name\': \'Block\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"The Defending Pokémon can\'t retreat during your opponent\'s next turn.\"}, {\'name\': \'Ease Up\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'40+\', \'text\': \'Snorlax is now Asleep. If Snorlax is evolved from Munchlax, this attack does 40 damage plus 30 more damage.\'}]', 'Diamond & Pearl', '4', '', '', 'Its stomach can digest any kind of food, even if it happens to be moldy or rotten.', 'Fourth ', '100', 'https://images.pokemoncard.io/images/dp1/dp1-37.png', 'unlimited: Legal', '35', 'Snorlax', '143', 'TPCI', 'Rare', '', '05/01/2007', '', 'Colorless, Colorless, Colorless, Colorless', '', 'Diamond & Pearl', '37', 'Basic', 'Pokémon', 'Colorless', 'type: Fighting, value: +20'),
('dp1-38', '', '', 'Kouki Saitou', '[{\'name\': \'Slam\', \'cost\': [\'Metal\'], \'convertedEnergyCost\': 1, \'damage\': \'30×\', \'text\': \'Flip 2 coins. This attack does 30 damage times the number of heads.\'}, {\'name\': \'Metal Slash\', \'cost\': [\'Metal\', \'Metal\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'100\', \'text\': \"Steelix can\'t attack during your next turn.\"}]', 'Diamond & Pearl', '4', 'Onix', '', 'Tempered underground under high pressure and heat, its body is harder than any metal.', 'Fourth ', '110', 'https://images.pokemoncard.io/images/dp1/dp1-38.png', 'unlimited: Legal', '50', 'Steelix', '208', 'TPCI', 'Rare', '', '05/01/2007', 'type: Psychic, value: -20', 'Colorless, Colorless, Colorless, Colorless', '', 'Diamond & Pearl', '38', 'Stage 1', 'Pokémon', 'Metal', 'type: Fire, value: +20'),
('dp1-39', '', '', 'Mitsuhiro Arita', '[{\'name\': \'Leaf Honey\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Discard a Grass Energy attached to Vespiquen and remove all damage counters from 1 of your Benched Grass Pokémon.\'}, {\'name\': \'Attack Order\', \'cost\': [\'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'10×\', \'text\': \"Does 10 damage times the number of Grass Pokémon in play (both yours and your opponent\'s).\"}]', 'Diamond & Pearl', '3', 'Combee', '', 'Its abdomen is a honeycomb for grubs. It raises its grubs on honey collected by COMBEE.', 'Fourth ', '100', 'https://images.pokemoncard.io/images/dp1/dp1-39.png', 'unlimited: Legal', '40', 'Vespiquen', '416', 'TPCI', 'Rare', '', '05/01/2007', 'type: Fighting, value: -20', 'Colorless, Colorless, Colorless', '', 'Diamond & Pearl', '39', 'Stage 1', 'Pokémon', 'Grass', 'type: Fire, value: +20'),
('dp1-4', '', '', 'Nakaoka', '[{\'name\': \'Ice Blade\', \'cost\': [\'Water\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'\', \'text\': \"Choose 1 of your opponent\'s Pokémon. This attack does 40 damage to that Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}, {\'name\': \'Aqua Jet\', \'cost\': [\'Water\', \'Water\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'70\', \'text\': \"Flip a coin. If heads, this attack does 20 damage to 1 of your opponent\'s Benched Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'Diamond & Pearl', '2', 'Prinplup', '', 'The three horns that extend from its beak attest to its power. The leader has the biggest horns.', 'Fourth ', '130', 'https://images.pokemoncard.io/images/dp1/dp1-4.png', 'unlimited: Legal', '42', 'Empoleon', '395', 'TPCI', 'Rare Holo', '', '05/01/2007', '', 'Colorless, Colorless', '', 'Diamond & Pearl', '4', 'Stage 2', 'Pokémon', 'Water', 'type: Lightning, value: +30'),
('dp1-40', '', '', 'Naoyo Kimura', '[{\'name\': \'Nasty Plot\', \'cost\': [\'Darkness\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Search your deck for any 1 card and put it into your hand. Shuffle your deck afterward.\'}, {\'name\': \'Dark Pulse\', \'cost\': [\'Darkness\', \'Darkness\', \'Darkness\'], \'convertedEnergyCost\': 3, \'damage\': \'10×\', \'text\': \'Does 10 damage times the total amount of Darkness Energy attached to all of your Pokémon.\'}]', 'Diamond & Pearl', '1', 'Sneasel', '', 'They live in cold regions, forming groups of four or five that hunt prey with impressive coordination.', 'Fourth ', '80', 'https://images.pokemoncard.io/images/dp1/dp1-40.png', 'unlimited: Legal', '37', 'Weavile', '461', 'TPCI', 'Rare', '', '05/01/2007', 'type: Psychic, value: -20', 'Colorless', '', 'Diamond & Pearl', '40', 'Stage 1', 'Pokémon', 'Darkness', 'type: Fighting, value: +20'),
('dp1-41', '', '', 'Kouki Saitou', '[{\'name\': \'Countercharge\', \'cost\': [\'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'\', \'text\': \'Flip a coin. If heads, move all damage counters from Wobbuffet to the Defending Pokémon.\'}]', 'Diamond & Pearl', '3', '', '', 'It desperately tries to keep its black tail hidden. It is said to be proof the tail hides a secret.', 'Fourth ', '80', 'https://images.pokemoncard.io/images/dp1/dp1-41.png', 'unlimited: Legal', '25', 'Wobbuffet', '202', 'TPCI', 'Rare', '', '05/01/2007', '', 'Colorless, Colorless, Colorless', '', 'Diamond & Pearl', '41', 'Basic', 'Pokémon', 'Psychic', 'type: Psychic, value: +20'),
('dp1-42', '[{\'name\': \'Baby Evolution\', \'text\': \'Once during your turn (before your attack), you may put Wobbuffet from your hand onto Wynaut (this counts as evolving Wynaut) and remove all damage counters from Wynaut.\', \'type\': \'Poké-Power\'}]', '', 'Masakazu Fukuda', '[{\'name\': \'Astonish\', \'cost\': [], \'convertedEnergyCost\': 0, \'damage\': \'\', \'text\': \"Choose 1 card from your opponent\'s hand without looking. Look at the card you chose, then have your opponent shuffle that card into his or her deck.\"}]', 'Diamond & Pearl', '1', '', 'Wobbuffet', 'It grows strong by pushing up against others en masse. It loves eating sweet fruit.', 'Fourth ', '40', 'https://images.pokemoncard.io/images/dp1/dp1-42.png', 'unlimited: Legal', '6', 'Wynaut', '360', 'TPCI', 'Rare', '', '05/01/2007', '', 'Colorless', '', 'Diamond & Pearl', '42', 'Basic', 'Pokémon', 'Psychic', 'type: Psychic, value: +10'),
('dp1-43', '[{\'name\': \'Baby Evolution\', \'text\': \'Once during your turn (before your attack), you may put Roselia from your hand onto Budew (this counts as evolving Budew) and remove all damage counters from Budew.\', \'type\': \'Poké-Power\'}]', '', 'Ken Sugimori', '[{\'name\': \'Errand-Running\', \'cost\': [], \'convertedEnergyCost\': 0, \'damage\': \'\', \'text\': \'Search your deck for a Trainer card, show it to your opponent, and put it into your hand. Shuffle your deck afterward.\'}]', 'Diamond & Pearl', '1', '', 'Roselia', 'Over the winter, it closes its bud and endures the cold. In spring, the bud opens and releases pollen.', 'Fourth ', '40', 'https://images.pokemoncard.io/images/dp1/dp1-43.png', 'unlimited: Legal', '6', 'Budew', '406', 'TPCI', 'Uncommon', '', '05/01/2007', '', 'Colorless', '', 'Diamond & Pearl', '43', 'Basic', 'Pokémon', 'Grass', 'type: Fire, value: +10'),
('dp1-44', '', '', 'Ken Sugimori', '[{\'name\': \'Harden\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"During your opponent\'s next turn, if Cascoon would be damaged by an attack, prevent that attack\'s damage done to Cascoon if that damage is 30 or less.\"}, {\'name\': \'Gooey Thread\', \'cost\': [\'Grass\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \"The Defending Pokémon can\'t retreat during your opponent\'s next turn.\"}]', 'Diamond & Pearl', '3', 'Wurmple', 'Dustox', 'It is hot inside its cocoon. All the cells in its body create the energy for it to evolve.', 'Fourth ', '80', 'https://images.pokemoncard.io/images/dp1/dp1-44.png', 'unlimited: Legal', '8', 'Cascoon', '268', 'TPCI', 'Uncommon', '', '05/01/2007', '', 'Colorless, Colorless, Colorless', '', 'Diamond & Pearl', '44', 'Stage 1', 'Pokémon', 'Grass', 'type: Fire, value: +20'),
('dp1-45', '', '', 'Atsuko Nishida', '[{\'name\': \'Worry Seed\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'20\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Confused.\'}, {\'name\': \'Magical Leaf\', \'cost\': [\'Grass\', \'Grass\'], \'convertedEnergyCost\': 2, \'damage\': \'20+\', \'text\': \'Flip a coin. If heads, this attack does 20 damage plus 20 more damage and remove 3 damage counters from Cherrim.\'}]', 'Diamond & Pearl', '2', 'Cherubi', '', 'It blooms during times of strong sunlight. It tries to make up for everything it endured as a bud.', 'Fourth ', '80', 'https://images.pokemoncard.io/images/dp1/dp1-45.png', 'unlimited: Legal', '26', 'Cherrim', '421', 'TPCI', 'Uncommon', '', '05/01/2007', 'type: Water, value: -20', 'Colorless, Colorless', '', 'Diamond & Pearl', '45', 'Stage 1', 'Pokémon', 'Grass', 'type: Fire, value: +20'),
('dp1-46', '', '', 'Ken Sugimori', '[{\'name\': \'Blowing Wind\', \'cost\': [\'Psychic\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Flip a coin. If heads, put 1 of your Benched Pokémon and all cards attached to on top of your deck. Shuffle your deck afterward.\'}, {\'name\': \'Ominous Wind\', \'cost\': [\'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'10\', \'text\': \"Flip a coin. If heads, the Defending Pokémon is now Confused and can\'t retreat during your opponent\'s next turn.\"}]', 'Diamond & Pearl', '1', '', 'Drifblim', 'A Pokémon formed by the spirits of people and Pokémon. It loves damp, humid seasons.', 'Fourth ', '60', 'https://images.pokemoncard.io/images/dp1/dp1-46.png', 'unlimited: Legal', '17', 'Drifloon', '425', 'TPCI', 'Uncommon', '', '05/01/2007', 'type: Colorless, value: -20', 'Colorless', '', 'Diamond & Pearl', '46', 'Basic', 'Pokémon', 'Psychic', 'type: Darkness, value: +10'),
('dp1-47', '', '', 'Kouki Saitou', '[{\'name\': \'Roam\', \'cost\': [\'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'\', \'text\': \"Flip a coin. If heads, put 2 damage counters on each of your opponent\'s Pokémon. If tails, put 2 damage counters on 1 of your Pokémon.\"}, {\'name\': \'Gravity Wave\', \'cost\': [\'Psychic\', \'Psychic\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \"Does 10 damage to each of your opponent\'s Benched Pokémon that doesn\'t have a Retreat Cost. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'Diamond & Pearl', '2', 'Duskull', 'Dusknoir', 'Its body is hollow. It is said that those who look into its body are sucked into the void.', 'Fourth ', '80', 'https://images.pokemoncard.io/images/dp1/dp1-47.png', 'unlimited: Legal', '38', 'Dusclops', '356', 'TPCI', 'Uncommon', '', '05/01/2007', 'type: Colorless, value: -20', 'Colorless, Colorless', '', 'Diamond & Pearl', '47', 'Stage 1', 'Pokémon', 'Psychic', 'type: Darkness, value: +20'),
