('ecard1-137', '', '', 'Ken Sugimori', '', 'Expedition Base Set', '', '', '', '', 'Second', '', 'https://images.pokemoncard.io/images/ecard1/ecard1-137.png', 'unlimited: Legal, expanded: Legal', '', 'Bills Maintenance', '', 'WOTC', 'Uncommon', '', '9/15/2002', '', '', '[\'You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.\', \'If you have any cards in your hand, shuffle 1 of them into your deck, then draw 3 cards.\']', 'E-Card', '137', 'Supporter', 'Trainer', '', ''),
('ecard1-138', '', '', 'Ken Sugimori', '', 'Expedition Base Set', '', '', '', '', 'Second', '', 'https://images.pokemoncard.io/images/ecard1/ecard1-138.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Copycat', '', 'WOTC', 'Uncommon', '', '9/15/2002', '', '', '[\'You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.\', \"Shuffle your hand into your deck. Then, count the number of cards in your opponent\'s hand and draw that many cards.\"]', 'E-Card', '138', 'Supporter', 'Trainer', '', ''),
('ecard1-139', '', '', 'Big Mama Tagawa', '', 'Expedition Base Set', '', '', '', '', 'Second', '', 'https://images.pokemoncard.io/images/ecard1/ecard1-139.png', 'unlimited: Legal', '', 'Dual Ball', '', 'WOTC', 'Uncommon', '', '9/15/2002', '', '', '[\'Flip 2 coins. For each heads, search your deck for a Basic Pokémon card other than a Baby Pokémon card, show it to your opponent, and put it into your hand. Shuffle your deck afterward.\']', 'E-Card', '139', '', 'Trainer', '', ''),
('ecard1-14', '[{\'name\': \'Rock Body\', \'text\': \'All damage done by attacks to Golem is reduced by 10 (after applying Weakness and Resistance).\', \'type\': \'Poké-Body\'}]', '', 'Aya Kusube', '[{\'name\': \'Rock Tumble\', \'cost\': [\'Fighting\', \'Fighting\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'60\', \'text\': \"Don\'t apply Resistance.\"}]', 'Expedition Base Set', '4', 'Graveler', '', '', 'Second', '100', 'https://images.pokemoncard.io/images/ecard1/ecard1-14.png', 'unlimited: Legal', '', 'Golem', '76', 'WOTC', 'Rare Holo', '', '9/15/2002', '', 'Colorless, Colorless, Colorless, Colorless', '', 'E-Card', '14', 'Stage 2', 'Pokémon', 'Fighting', 'type: Water, value: ×2'),
('ecard1-140', '', '', 'Keiji Kinebuchi', '', 'Expedition Base Set', '', '', '', '', 'Second', '', 'https://images.pokemoncard.io/images/ecard1/ecard1-140.png', 'unlimited: Legal', '', 'Energy Removal 2', '', 'WOTC', 'Uncommon', '', '9/15/2002', '', '', '[\"Flip a coin. If heads, choose 1 Energy card attached to 1 of your opponent\'s Pokémon and discard it.\"]', 'E-Card', '140', '', 'Trainer', '', ''),
('ecard1-141', '', '', 'Hideyuki Nakajima', '', 'Expedition Base Set', '', '', '', '', 'Second', '', 'https://images.pokemoncard.io/images/ecard1/ecard1-141.png', 'unlimited: Legal', '', 'Energy Restore', '', 'WOTC', 'Uncommon', '', '9/15/2002', '', '', '[\"Flip 3 coins. For each heads, put a Basic Energy card from your discard pile into your hand. If you don\'t have that many basic Energy cards in your discard pile, put all of them into your hand.\"]', 'E-Card', '141', '', 'Trainer', '', ''),
('ecard1-142', '', '', 'Ken Sugimori', '', 'Expedition Base Set', '', '', '', '', 'Second', '', 'https://images.pokemoncard.io/images/ecard1/ecard1-142.png', 'unlimited: Legal', '', 'Marys Impulse', '', 'WOTC', 'Uncommon', '', '9/15/2002', '', '', '[\'You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.\', \'Flip a coin until you get tails. For each heads, draw 2 cards.\']', 'E-Card', '142', 'Supporter', 'Trainer', '', ''),
('ecard1-143', '', '', 'Keiji Kinebuchi', '', 'Expedition Base Set', '', '', '', '', 'Second', '', 'https://images.pokemoncard.io/images/ecard1/ecard1-143.png', 'unlimited: Legal', '', 'Master Ball', '', 'WOTC', 'Uncommon', '', '9/15/2002', '', '', '[\'Look at 7 cards from the top of your deck. You may choose a Basic Pokémon or Evolution card from those cards, show it your opponent, and put it into your hand. Shuffle the rest into your deck.\']', 'E-Card', '143', '', 'Trainer', '', ''),
('ecard1-144', '', '', 'Big Mama Tagawa', '[{\'name\': \'Paralyzing Gaze\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'The Defending Pokémon is now Paralyzed.\'}]', 'Expedition Base Set', '', '', '', '', 'Second', '', 'https://images.pokemoncard.io/images/ecard1/ecard1-144.png', 'unlimited: Legal', '', 'Multi Technical Machine 01', '', 'WOTC', 'Uncommon', '', '9/15/2002', '', '', '[\"Attach this card to 1 of your Pokémon in play. That Pokémon may use this card\'s attack instead of its own. At the end of your turn, discard Multi Technical Machine 01.\"]', 'E-Card', '144', 'Technical Machine', 'Trainer', '', ''),
('ecard1-145', '', '', 'Ken Sugimori', '', 'Expedition Base Set', '', '', '', '', 'Second', '', 'https://images.pokemoncard.io/images/ecard1/ecard1-145.png', 'unlimited: Legal', '', 'Pokémon Nurse', '', 'WOTC', 'Uncommon', '', '9/15/2002', '', '', '[\'You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.\', \'Remove all damage counters from 1 of your Pokémon. Then discard all Energy cards attached to it, if any.\']', 'E-Card', '145', 'Supporter', 'Trainer', '', ''),
('ecard1-146', '', '', 'Big Mama Tagawa', '', 'Expedition Base Set', '', '', '', '', 'Second', '', 'https://images.pokemoncard.io/images/ecard1/ecard1-146.png', 'unlimited: Legal', '', 'Pokémon Reversal', '', 'WOTC', 'Uncommon', '', '9/15/2002', '', '', '[\"Choose 1 of your opponent\'s Benched Pokémon. Flip a coin. If heads, switch that Pokémon with the Defending Pokémon.\"]', 'E-Card', '146', '', 'Trainer', '', ''),
('ecard1-147', '', '', 'Keiji Kinebuchi', '', 'Expedition Base Set', '', '', '', '', 'Second', '', 'https://images.pokemoncard.io/images/ecard1/ecard1-147.png', 'unlimited: Legal', '', 'Power Charge', '', 'WOTC', 'Uncommon', '', '9/15/2002', '', '', '[\'Flip a coin. If heads, shuffle 2 Energy cards from your discard pile into your deck (1 if you have only 1).\']', 'E-Card', '147', '', 'Trainer', '', ''),
('ecard1-148', '', '', 'Ken Sugimori', '', 'Expedition Base Set', '', '', '', '', 'Second', '', 'https://images.pokemoncard.io/images/ecard1/ecard1-148.png', 'unlimited: Legal', '', 'Professor Elms Training Method', '', 'WOTC', 'Uncommon', '', '9/15/2002', '', '', '[\'You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.\', \'Search your deck for an Evolution card, show it to your opponent, and put it into your hand. Shuffle your deck afterward.\']', 'E-Card', '148', 'Supporter', 'Trainer', '', ''),
('ecard1-149', '', '', 'Ken Sugimori', '', 'Expedition Base Set', '', '', '', '', 'Second', '', 'https://images.pokemoncard.io/images/ecard1/ecard1-149.png', 'unlimited: Legal', '', 'Professor Oaks Research', '', 'WOTC', 'Uncommon', '', '9/15/2002', '', '', '[\'You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.\', \'Shuffle your hand into your deck, then draw 5 cards.\']', 'E-Card', '149', 'Supporter', 'Trainer', '', ''),
('ecard1-15', '', '', 'Shin-ichi Yoshida', '[{\'name\': \'Bubble\', \'cost\': [\'Water\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Paralyzed.\'}, {\'name\': \'Giant Claw\', \'cost\': [\'Water\', \'Water\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'70\', \'text\': \'Flip a coin. If tails, this attack does nothing.\'}]', 'Expedition Base Set', '2', 'Krabby', '', '', 'Second', '80', 'https://images.pokemoncard.io/images/ecard1/ecard1-15.png', 'unlimited: Legal', '', 'Kingler', '99', 'WOTC', 'Rare Holo', '', '9/15/2002', '', 'Colorless, Colorless', '', 'E-Card', '15', 'Stage 1', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
