('ecard1-153', '', '', 'Kai Ishikawa', '', 'Expedition Base Set', '', '', '', '', 'Second', '', 'https://images.pokemoncard.io/images/ecard1/ecard1-153.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Energy Search', '', 'WOTC', 'Common', '', '9/15/2002', '', '', '[\'Search your deck for a basic Energy card, show it to your opponent, and put it into your hand. Shuffle your deck afterward.\']', 'E-Card', '153', '', 'Trainer', '', ''),
('ecard1-154', '', '', 'Keiji Kinebuchi', '', 'Expedition Base Set', '', '', '', '', 'Second', '', 'https://images.pokemoncard.io/images/ecard1/ecard1-154.png', 'unlimited: Legal, expanded: Legal', '', 'Full Heal', '', 'WOTC', 'Common', '', '9/15/2002', '', '', '[\'Remove all Special Conditions from your Active Pokémon.\']', 'E-Card', '154', '', 'Trainer', '', ''),
