('ecard1-158', '', '', 'Milky Isobe', '', 'Expedition Base Set', '', '', '', '', 'Second', '', 'https://images.pokemoncard.io/images/ecard1/ecard1-158.png', 'unlimited: Legal', '', 'Darkness Energy', '', 'WOTC', 'Rare', '', '9/15/2002', '', '', '[\"If the Pokémon Darkness Energy is attached to does damage with an attack (after applying Weakness and Resistance), the attack does 10 more damage. At the end of every turn, put 1 damage counter on the Pokémon Darkness Energy is attached to, unless it\'s Darkness or has Dark in its name. Darkness Energy provides Darkness Energy. (Doesn\'t count as a basic Energy card.)\"]', 'E-Card', '158', 'Special', 'Energy', '', ''),
('ecard1-159', '', '', 'Milky Isobe', '', 'Expedition Base Set', '', '', '', '', 'Second', '', 'https://images.pokemoncard.io/images/ecard1/ecard1-159.png', 'unlimited: Legal', '', 'Metal Energy', '', 'WOTC', 'Rare', '', '9/15/2002', '', '', '[\"Damage done by attacks to the Pokémon Metal Energy is attached to is reduced by 10 (after applying Weakness and Resistance). If the Pokémon Metal Energy is attached to isn\'t Metal, whenever it damages a Pokémon by an attack, reduce that damage by 10 (after applying Weakness and Resistance). Metal Energy provides Metal Energy. (Doesn\'t count as a basic Energy card.)\"]', 'E-Card', '159', 'Special', 'Energy', '', ''),
('ecard1-16', '[{\'name\': \'Terraforming\', \'text\': \"Once during your turn (before your attack), you may look at the top 4 cards of your deck and rearrange them as you like. This power can\'t be used if Machamp is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Shin-ichi Yoshida', '[{\'name\': \'Iron Fist\', \'cost\': [\'Fighting\', \'Fighting\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'50+\', \'text\': \'Count the number of Pokémon you have in play with damage counters on them. Flip a coin. If heads, this attack does 50 damage plus 10 more damage for each of those Pokémon.\'}]', 'Expedition Base Set', '2', 'Machoke', '', '', 'Second', '120', 'https://images.pokemoncard.io/images/ecard1/ecard1-16.png', 'unlimited: Legal', '', 'Machamp', '68', 'WOTC', 'Rare Holo', '', '9/15/2002', '', 'Colorless, Colorless', '', 'E-Card', '16', 'Stage 2', 'Pokémon', 'Fighting', 'type: Psychic, value: ×2'),
