('ecard2-H16', '[{\'name\': \'Magnetic Flow\', \'text\': \"Once during your turn (before your attack), if Magneton is your Active Pokémon, you may flip a coin. If heads, choose 2 of your opponent\'s Pokémon that have Energy cards attached to them. Choose 1 of the Energy cards attached to each of those Pokémon and switch them between the Pokémon. This power can\'t be used if Magneton is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Hikaru Koike', '[{\'name\': \'Steel Wave\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'30\', \'text\': \"This attack does 10 damage to each of your opponent\'s Benched Pokémon that are the same type (color) as the Defending Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'Aquapolis', '2', 'Magnemite', 'Magnezone', '', 'Second', '70', 'https://images.pokemoncard.io/images/ecard2/ecard2-H16.png', 'unlimited: Legal', '', 'Magneton', '82', 'WOTC', 'Rare Holo', '', '1/15/2003', 'type: Grass, value: -30', 'Colorless, Colorless', '', 'E-Card', 'H16', 'Stage 1', 'Pokémon', 'Metal', 'type: Fire, value: ×2'),
('ecard2-H17', '[{\'name\': \'Heavyweight\', \'text\': \'As long as there is a Grass Energy attached to Muk, you must pay an additional ColorlessColorless to retreat it.\', \'type\': \'Poké-Body\'}]', '', 'Hajime Kusajima', '[{\'name\': \'Burning Sludge\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'10\', \'text\': \'Flip a number of coins equal to the amount of Grass Energy attached to Muk. If any of them are heads, the Defending Pokémon is now Poisoned and Burned.\'}]', 'Aquapolis', '1', 'Grimer', '', '', 'Second', '70', 'https://images.pokemoncard.io/images/ecard2/ecard2-H17.png', 'unlimited: Legal', '', 'Muk', '89', 'WOTC', 'Rare Holo', '', '1/15/2003', '', 'Colorless', '', 'E-Card', 'H17', 'Stage 1', 'Pokémon', 'Grass', 'type: Psychic, value: ×2'),
('ecard2-H18', '[{\'name\': \'Earth Rage\', \'text\': \"Once during your turn (before your attack), if Nidoking is your Active Pokémon, you may flip a coin. If heads, put a damage counter on each of your opponent\'s Benched Pokémon. This power can\'t be used if Nidoking is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Naoyo Kimura', '[{\'name\': \'Giant Horn\', \'cost\': [\'Fighting\', \'Fighting\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'50+\', \'text\': \'Flip a coin. If heads, this attack does 50 damage plus 30 more damage.\'}]', 'Aquapolis', '3', 'Nidorino', '', '', 'Second', '110', 'https://images.pokemoncard.io/images/ecard2/ecard2-H18.png', 'unlimited: Legal', '', 'Nidoking', '34', 'WOTC', 'Rare Holo', '', '1/15/2003', 'type: Lightning, value: -30', 'Colorless, Colorless, Colorless', '', 'E-Card', 'H18', 'Stage 2', 'Pokémon', 'Fighting', 'type: Grass, value: ×2'),
('ecard2-H19', '', '', 'Kagemaru Himeno', '[{\'name\': \'Miracle Tail\', \'cost\': [\'Fire\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'Flip a coin. If heads, choose a Special Condition (Asleep, Burned, Confused, Paralyzed, or Poisoned). The Defending Pokémon is now affected by that Special Condition.\'}, {\'name\': \'Roasting Heat\', \'cost\': [\'Fire\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40+\', \'text\': \'If the Defending Pokémon is Burned, this attack does 40 damage plus 20 more damage.\'}]', 'Aquapolis', '1', 'Vulpix', '', '', 'Second', '80', 'https://images.pokemoncard.io/images/ecard2/ecard2-H19.png', 'unlimited: Legal', '', 'Ninetales', '38', 'WOTC', 'Rare Holo', '', '1/15/2003', '', 'Colorless', '', 'E-Card', 'H19', 'Stage 1', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('ecard2-H2', '[{\'name\': \'Extreme Speed\', \'text\': \'You pay Colorless less to retreat Arcanine for each Energy attached to it.\', \'type\': \'Poké-Body\'}]', '', 'Kyoko Umemoto', '[{\'name\': \'Fire Blow\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'30+\', \'text\': \'You may discard any number of Fire Energy cards attached to Arcanine when you use this attack. If you do, flip a number of coins equal to the number of Fire Energy cards you discarded. This attack does 30 damage plus 30 more damage for each heads.\'}]', 'Aquapolis', '3', 'Growlithe', '', '', 'Second', '90', 'https://images.pokemoncard.io/images/ecard2/ecard2-H2.png', 'unlimited: Legal', '', 'Arcanine', '59', 'WOTC', 'Rare Holo', '', '1/15/2003', '', 'Colorless, Colorless, Colorless', '', 'E-Card', 'H2', 'Stage 1', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('ecard2-H20', '[{\'name\': \'Suction Cups\', \'text\': \'As long as Octillery is your Active Pokémon, whenever the Defending Pokémon retreats, discard all Energy cards attached to the Defending Pokémon when it goes to the Bench.\', \'type\': \'Poké-Body\'}]', '', 'Kouki Saitou', '[{\'name\': \'Smokescreen\', \'cost\': [\'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40\', \'text\': \"If the Defending Pokémon tries to attack during your opponent\'s next turn, your opponent flips a coin. If tails, that attack does nothing.\"}]', 'Aquapolis', '2', 'Remoraid', '', '', 'Second', '80', 'https://images.pokemoncard.io/images/ecard2/ecard2-H20.png', 'unlimited: Legal', '', 'Octillery', '224', 'WOTC', 'Rare Holo', '', '1/15/2003', '', 'Colorless, Colorless', '', 'E-Card', 'H20', 'Stage 1', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('ecard2-H21', '[{\'name\': \'Poison Resistance\', \'text\': \"Scizor can\'t be Poisoned.\", \'type\': \'Poké-Body\'}]', '', 'Hisao Nakamura', '[{\'name\': \'Snatch\', \'cost\': [\'Metal\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \"Before doing damage, you may choose 1 of your opponent\'s Benched Pokémon with no damage counters on it and switch the Defending Pokémon with it.\"}, {\'name\': \'Heavy Metal\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'30+\', \'text\': \'Flip a number of coins equal to the amount of Metal Energy attached to Scizor. This attack does 30 damage plus 20 more damage for each heads.\'}]', 'Aquapolis', '2', 'Scyther', '', '', 'Second', '80', 'https://images.pokemoncard.io/images/ecard2/ecard2-H21.png', 'unlimited: Legal', '', 'Scizor', '212', 'WOTC', 'Rare Holo', '', '1/15/2003', '', 'Colorless, Colorless', '', 'E-Card', 'H21', 'Stage 1', 'Pokémon', 'Metal', 'type: Fire, value: ×2'),
('ecard2-H22', '', '', 'Aya Kusube', '[{\'name\': \'Bursting Hand\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10×\', \'text\': \"Look at your opponent\'s hand. This attack does 10 damage times the number of Energy cards there.\"}, {\'name\': \'Shuffle Attack\', \'cost\': [\'Psychic\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40\', \'text\': \"Look at a number of cards on top of your opponent\'s deck equal to the number of Energy cards attached to the Defending Pokémon. Put those cards in any order, and then put them back on top of your opponent\'s deck.\"}]', 'Aquapolis', '1', 'Slowpoke', '', '', 'Second', '80', 'https://images.pokemoncard.io/images/ecard2/ecard2-H22.png', 'unlimited: Legal', '', 'Slowking', '199', 'WOTC', 'Rare Holo', '', '1/15/2003', '', 'Colorless', '', 'E-Card', 'H22', 'Stage 1', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2'),
('ecard2-H23', '', '', 'Hajime Kusajima', '[{\'name\': \'Earth Rift\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'10\', \'text\': \"This attack does 10 damage to each of your opponent\'s Benched Pokémon. (Don\'t apply Weakness or Resistance for Benched Pokémon.) Then, flip a coin. If tails, this attack can\'t be used during your next turn.\"}, {\'name\': \'Iron Smash\', \'cost\': [\'Metal\', \'Metal\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'50+\', \'text\': \'Flip 2 coins. If both are heads, this attack does 50 damage plus 20 more damage. If both are tails, this attack does nothing. If 1 is heads and 1 is tails, this attack just does 50 damage.\'}]', 'Aquapolis', '4', 'Onix', '', '', 'Second', '100', 'https://images.pokemoncard.io/images/ecard2/ecard2-H23.png', 'unlimited: Legal', '', 'Steelix', '208', 'WOTC', 'Rare Holo', '', '1/15/2003', 'type: Grass, value: -30', 'Colorless, Colorless, Colorless, Colorless', '', 'E-Card', 'H23', 'Stage 1', 'Pokémon', 'Metal', 'type: Fire, value: ×2'),
('ecard2-H24', '', '', 'Kagemaru Himeno', '[{\'name\': \'Copy\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Choose 1 of the Defending Pokémon\'s attacks. Copy copies that attack. This attack does nothing if Sudowoodo doesn\'t have the Energy necessary to use that attack. (You must still do anything else required in order to use that attack.)\"}, {\'name\': \'Energy Draw\', \'cost\': [\'Fighting\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Search your deck for a basic Energy card and attach it to Sudowoodo. Shuffle your deck afterward.\'}]', 'Aquapolis', '2', '', '', '', 'Second', '60', 'https://images.pokemoncard.io/images/ecard2/ecard2-H24.png', 'unlimited: Legal', '', 'Sudowoodo', '185', 'WOTC', 'Rare Holo', '', '1/15/2003', '', 'Colorless, Colorless', '', 'E-Card', 'H24', 'Basic', 'Pokémon', 'Fighting', 'type: Water, value: ×2'),
('ecard2-H25', '[{\'name\': \'Pure Body\', \'text\': \'To attach a Water Energy card from your hand to Suicune, you must discard an Energy card attached to Suicune. (Attach the Water Energy, and then discard an Energy card from Suicune.)\', \'type\': \'Poké-Body\'}]', '', 'Atsuko Nishida', '[{\'name\': \'Hypno Wave\', \'cost\': [\'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'30+\', \'text\': \'Flip a coin. If heads, this attack does 30 damage plus 20 more damage. If tails, this attack does 30 damage and the Defending Pokémon is now Asleep.\'}]', 'Aquapolis', '1', '', '', '', 'Second', '70', 'https://images.pokemoncard.io/images/ecard2/ecard2-H25.png', 'unlimited: Legal', '', 'Suicune', '245', 'WOTC', 'Rare Holo', '', '1/15/2003', '', 'Colorless', '', 'E-Card', 'H25', 'Basic', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('ecard2-H26', '[{\'name\': \'Strange Tentacles\', \'text\': \"Once during your turn (before your attack), as long as the number of Energy cards attached to the Defending Pokémon is less than the number of Energy cards attached to your Active Pokémon, you may choose an Energy card, if any, in your opponent\'s discard pile and attach it to the Defending Pokémon. This power can\'t be used if Tentacruel is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Hajime Kusajima', '[{\'name\': \'Poison Sting\', \'cost\': [\'Water\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Poisoned.\'}]', 'Aquapolis', '', 'Tentacool', '', '', 'Second', '70', 'https://images.pokemoncard.io/images/ecard2/ecard2-H26.png', 'unlimited: Legal', '', 'Tentacruel', '73', 'WOTC', 'Rare Holo', '', '1/15/2003', '', '', '', 'E-Card', 'H26', 'Stage 1', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('ecard2-H27', '[{\'name\': \'Miracle Shift\', \'text\': \"Once during your turn (before your attack), discard a basic Energy card attached to 1 of your Pokémon. Then, choose a basic Energy card from your discard pile and attach it to that Pokémon. This power can\'t be used if Togetic is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Kagemaru Himeno', '[{\'name\': \'Mini-Metronome\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Flip a coin. If heads, choose 1 of the Defending Pokémon\'s attacks. Mini-Metronome copies that attack except for its Energy cost. (You must still do anything else required in order to use that attack.) (No matter what type the Defending Pokémon is, Togetic is still Colorless.) Togetic performs that attack.\"}]', 'Aquapolis', '1', 'Togepi', 'Togekiss', '', 'Second', '60', 'https://images.pokemoncard.io/images/ecard2/ecard2-H27.png', 'unlimited: Legal', '', 'Togetic', '176', 'WOTC', 'Rare Holo', '', '1/15/2003', 'type: Fighting, value: -30', 'Colorless', '', 'E-Card', 'H27', 'Stage 1', 'Pokémon', 'Colorless', 'type: Lightning, value: ×2'),
('ecard2-H28', '', '', 'Naoyo Kimura', '[{\'name\': \'Destructive Roar\', \'cost\': [\'Darkness\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Flip a coin. If heads, discard 1 Energy card attached to 1 of your opponent\'s Pokémon.\"}, {\'name\': \'Tail Slap\', \'cost\': [\'Darkness\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'30\', \'text\': \'\'}, {\'name\': \'Gigacrush\', \'cost\': [\'Darkness\', \'Darkness\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 5, \'damage\': \'60\', \'text\': \'Each player discards the top 3 cards from his or her deck.\'}]', 'Aquapolis', '3', 'Pupitar', '', '', 'Second', '120', 'https://images.pokemoncard.io/images/ecard2/ecard2-H28.png', 'unlimited: Legal', '', 'Tyranitar', '248', 'WOTC', 'Rare Holo', '', '1/15/2003', 'type: Psychic, value: -30', 'Colorless, Colorless, Colorless', '', 'E-Card', 'H28', 'Stage 2', 'Pokémon', 'Darkness', 'type: Fighting, value: ×2'),
('ecard2-H29', '[{\'name\': \'Dark Moon\', \'text\': \"As long as Umbreon is your Active Pokémon and has a Darkness Energy attached to it, once during your turn (before your attack), you may look at your opponent\'s hand. Choose from it a number of cards up to the number of Darkness Energy attached to Umbreon and shuffle them into your opponent\'s deck. Your opponent then draws the same number of cards from his or her deck. This power can\'t be used if Umbreon is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Mitsuhiro Arita', '[{\'name\': \'Shadow Bind\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'30\', \'text\': \"The Defending Pokémon can\'t retreat during your opponent\'s next turn.\"}]', 'Aquapolis', '1', 'Eevee', '', '', 'Second', '80', 'https://images.pokemoncard.io/images/ecard2/ecard2-H29.png', 'unlimited: Legal', '', 'Umbreon', '197', 'WOTC', 'Rare Holo', '', '1/15/2003', 'type: Psychic, value: -30', 'Colorless', '', 'E-Card', 'H29', 'Stage 1', 'Pokémon', 'Darkness', 'type: Fighting, value: ×2'),
('ecard2-H3', '[{\'name\': \'Gluey Slime\', \'text\': \"As long as Ariados is in play, each player must pay an additional Colorless to retreat his or her Active Pokémon. Gluey Slime can\'t make a player pay more than an additional Colorless to retreat a Pokémon, even if there is more than 1 Ariados in play.\", \'type\': \'Poké-Body\'}]', '', 'Shin-ichi Yoshida', '[{\'name\': \'Spider Force\', \'cost\': [\'Grass\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20+\', \'text\': \'Flip a coin. If heads, this attack does 20 damage plus 10 more damage. If tails, this attack does 20 damage and the defending Pokémon is now Paralyzed.\'}]', 'Aquapolis', '', 'Spinarak', '', '', 'Second', '70', 'https://images.pokemoncard.io/images/ecard2/ecard2-H3.png', 'unlimited: Legal', '', 'Ariados', '168', 'WOTC', 'Rare Holo', '', '1/15/2003', '', '', '', 'E-Card', 'H3', 'Stage 1', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('ecard2-H30', '[{\'name\': \'Fragrance Trap\', \'text\': \"Once during your turn (before your attack), you may flip a coin. If heads, choose 1 of your opponent\'s Benched Pokémon and switch the Defending Pokémon with it. This Power can\'t be used if Victreebel is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Miki Tanaka', '[{\'name\': \'Corrosive Acid\', \'cost\': [\'Grass\', \'Grass\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Burned.\'}]', 'Aquapolis', '2', 'Weepinbell', '', '', 'Second', '90', 'https://images.pokemoncard.io/images/ecard2/ecard2-H30.png', 'unlimited: Legal', '', 'Victreebel', '71', 'WOTC', 'Rare Holo', '', '1/15/2003', '', 'Colorless, Colorless', '', 'E-Card', 'H30', 'Stage 2', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('ecard2-H31', '', '', 'Kyoko Umemoto', '[{\'name\': \'Poison Scent\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Poisoned and Confused. If tails, the Defending Pokémon is now Poisoned and Asleep.\'}, {\'name\': \'Addictive Pollen\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40\', \'text\': \"Flip a coin. If heads, your opponent can\'t play Supporter cards during his or her next turn.\"}]', 'Aquapolis', '2', 'Gloom', '', '', 'Second', '100', 'https://images.pokemoncard.io/images/ecard2/ecard2-H31.png', 'unlimited: Legal', '', 'Vileplume', '45', 'WOTC', 'Rare Holo', '', '1/15/2003', '', 'Colorless, Colorless', '', 'E-Card', 'H31', 'Stage 2', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('ecard2-H32', '[{\'name\': \'Anti-Lightning\', \'text\': \"You can\'t attach Lightning Energy cards from your hand to Zapdos.\", \'type\': \'Poké-Body\'}]', '', 'Hajime Kusajima', '[{\'name\': \'Plasma\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'If there are any Lightning Energy cards in your discard pile, flip a coin. If heads, attach 1 of them to Zapdos.\'}, {\'name\': \'Lightning Storm\', \'cost\': [\'Lightning\', \'Lightning\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'60\', \'text\': \'Flip a coin. If tails, put 2 damage counters on Zapdos.\'}]', 'Aquapolis', '2', '', '', '', 'Second', '80', 'https://images.pokemoncard.io/images/ecard2/ecard2-H32.png', 'unlimited: Legal', '', 'Zapdos', '145', 'WOTC', 'Rare Holo', '', '1/15/2003', 'type: Fighting, value: -30', 'Colorless, Colorless', '', 'E-Card', 'H32', 'Basic', 'Pokémon', 'Lightning', 'type: Lightning, value: ×2'),
('ecard2-H4', '[{\'name\': \'Bubble Turn\', \'text\': \'Once during your turn (before your attack), if Azumarill is on your Bench, you may flip a coin. If heads, return Azumarill and all cards attached to it to your hand.\', \'type\': \'Poké-Power\'}]', '', 'Kagemaru Himeno', '[{\'name\': \'Aqua Sonic\', \'cost\': [\'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40\', \'text\': \"Don\'t apply Resistance.\"}]', 'Aquapolis', '1', 'Marill', '', '', 'Second', '70', 'https://images.pokemoncard.io/images/ecard2/ecard2-H4.png', 'unlimited: Legal', '', 'Azumarill', '184', 'WOTC', 'Rare Holo', '', '1/15/2003', '', 'Colorless', '', 'E-Card', 'H4', 'Stage 1', 'Pokémon', 'Water', 'type: Lightning, value: ×2');
INSERT INTO `cards` (`id`, `abilities`, `ancient_trait`, `artist`, `attacks`, `card_set`, `converted`, `evolves_from`, `evolves_to`, `flavor_text`, `generation`, `hp`, `img`, `legalities`, `level`, `name`, `national_pokedex_numbers`, `publisher`, `rarity`, `regulation_mark`, `release_date`, `resistances`, `retreat_cost`, `rules`, `series`, `set_num`, `subtypes`, `supertype`, `types`, `weakness`) VALUES
('ecard2-H5', '[{\'name\': \'Flower Supplement\', \'text\': \"Once during your turn (before your attack), you may flip a coin. If heads, attach 1 basic Energy card from your hand to 1 of your Benched Pokémon. This power can\'t be used if Bellossom is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Sumiyoshi Kizuki', '[{\'name\': \'Knife Leaf\', \'cost\': [\'Grass\', \'Grass\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'30×\', \'text\': \'Flip 3 coins. This attack does 30 damage times the number of heads.\'}]', 'Aquapolis', '2', 'Gloom', '', '', 'Second', '90', 'https://images.pokemoncard.io/images/ecard2/ecard2-H5.png', 'unlimited: Legal', '', 'Bellossom', '182', 'WOTC', 'Rare Holo', '', '1/15/2003', 'type: Water, value: -30', 'Colorless, Colorless', '', 'E-Card', 'H5', 'Stage 2', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('ecard2-H6', '[{\'name\': \'Happy Healing\', \'text\': \"Once during your turn (before your attack), choose 1 of your Benched Pokémon and flip a coin. If heads, count the number of Energy attached to Blissey and then remove that many damage counters from the chosen Benched Pokémon. This power can\'t be used if Blissey is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Naoyo Kimura', '[{\'name\': \'Smash Bomber\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50\', \'text\': \'Flip a coin. If tails, this attack does nothing.\'}]', 'Aquapolis', '2', 'Chansey', '', '', 'Second', '120', 'https://images.pokemoncard.io/images/ecard2/ecard2-H6.png', 'unlimited: Legal', '', 'Blissey', '242', 'WOTC', 'Rare Holo', '', '1/15/2003', '', 'Colorless, Colorless', '', 'E-Card', 'H6', 'Stage 1', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('ecard2-H7', '[{\'name\': \'Super Dynamo\', \'text\': \"Once during your turn (before your attack), if Electrode is your Active Pokémon, you may flip a coin. If heads, choose a Lightning Energy card from your discard pile and attach it to 1 of your Pokémon. This power can\'t be used if Electrode is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Shin-ichi Yoshida', '[{\'name\': \'Swift\', \'cost\': [\'Lightning\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \"This attack\'s damage isn\'t affected by Weakness, Resistance, Poké-Powers, Poké-Bodies, or any other effects on the Defending Pokémon.\"}]', 'Aquapolis', '1', 'Voltorb', '', '', 'Second', '70', 'https://images.pokemoncard.io/images/ecard2/ecard2-H7.png', 'unlimited: Legal', '', 'Electrode', '101', 'WOTC', 'Rare Holo', '', '1/15/2003', '', 'Colorless', '', 'E-Card', 'H7', 'Stage 1', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
('ecard2-H8', '[{\'name\': \'Pure Body\', \'text\': \'To attach a Fire Energy card from your hand to Entei, you must discard an Energy card attached to Entei. (Attach the Fire Energy, and then discard an Energy from Entei.)\', \'type\': \'Poké-Body\'}]', '', 'Atsuko Nishida', '[{\'name\': \'Burning Fang\', \'cost\': [\'Fire\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40\', \'text\': \'You may flip a coin. If heads, discard a Fire Energy card attached to Entei and the Defending Pokémon is now Burned.\'}]', 'Aquapolis', '1', '', '', '', 'Second', '70', 'https://images.pokemoncard.io/images/ecard2/ecard2-H8.png', 'unlimited: Legal', '', 'Entei', '244', 'WOTC', 'Rare Holo', '', '1/15/2003', '', 'Colorless', '', 'E-Card', 'H8', 'Basic', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('ecard2-H9', '[{\'name\': \'Energy Return\', \'text\': \"As often as you like during your turn (before your attack), choose an Energy card attached to 1 of your Pokémon and return it to your hand. This power can\'t be used if Espeon is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Kyoko Umemoto', '[{\'name\': \'Damage Blast\', \'cost\': [\'Psychic\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'30+\', \'text\': \'Flip a number of coins equal to the number of damage counters on the Defending Pokémon. This attack does 30 damage plus 10 more damage for each heads.\'}]', 'Aquapolis', '', 'Eevee', '', '', 'Second', '80', 'https://images.pokemoncard.io/images/ecard2/ecard2-H9.png', 'unlimited: Legal', '', 'Espeon', '196', 'WOTC', 'Rare Holo', '', '1/15/2003', '', '', '', 'E-Card', 'H9', 'Stage 1', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2'),
('ecard3-1', '[{\'name\': \'Ancient Wind\', \'text\': \"Once during your turn (before your attack), if Aerodactyl is your Active Pokémon, you may ignore all Poké-Bodies until the end of your turn. This power can\'t be used if Aerodactyl is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Toshinao Aoki', '[{\'name\': \'Rising Lunge\', \'cost\': [\'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20+\', \'text\': \'Flip a coin. If heads, this attack does 20 damage plus 20 more damage.\'}]', 'Skyridge', '1', 'Mysterious Fossil', '', '', 'Second', '70', 'https://images.pokemoncard.io/images/ecard3/ecard3-1.png', 'unlimited: Legal', '', 'Aerodactyl', '142', 'WOTC', 'Rare', '', '05/12/2003', '', 'Colorless', '', 'E-Card', '1', 'Stage 1', 'Pokémon', 'Fighting', 'type: Water, value: ×2'),
('ecard3-10', '[{\'name\': \'Manipulate\', \'text\': \'When you play Gengar from your hand to evolve your Active Pokémon, you may put a Basic Pokémon (excluding Baby Pokémon) from your discard pile onto your Bench. Then, flip 3 coins. For each heads, choose a basic Energy card from your discard pile and attach it to that Pokémon.\', \'type\': \'Poké-Power\'}]', '', 'Kyoko Umemoto', '[{\'name\': \'Hydrokinesis\', \'cost\': [\'Psychic\', \'Psychic\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'40\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Burned. If tails, the Defending Pokémon is now Confused.\'}]', 'Skyridge', '2', 'Haunter', '', '', 'Second', '100', 'https://images.pokemoncard.io/images/ecard3/ecard3-10.png', 'unlimited: Legal', '', 'Gengar', '94', 'WOTC', 'Rare', '', '05/12/2003', 'type: Fighting, value: -30', 'Colorless, Colorless', '', 'E-Card', '10', 'Stage 2', 'Pokémon', 'Psychic', 'type: Darkness, value: ×2'),
('ecard3-100', '[{\'name\': \'Lolling About\', \'text\': \"Once during your turn (before your attack), if Snorlax is your Active Pokémon, you may remove 1 damage counter from Snorlax. Snorlax is now Asleep. This power can\'t be used if Snorlax is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Naoyo Kimura', '[{\'name\': \'Continuous Tumble\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'30×\', \'text\': \'Flip a coin until you get tails. This attack does 30 damage times the number of heads.\'}]', 'Skyridge', '3', '', '', '', 'Second', '80', 'https://images.pokemoncard.io/images/ecard3/ecard3-100.png', 'unlimited: Legal', '', 'Snorlax', '143', 'WOTC', 'Common', '', '05/12/2003', '', 'Colorless, Colorless, Colorless', '', 'E-Card', '100', 'Basic', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('ecard3-101', '', '', 'Hisao Nakamura', '[{\'name\': \'Scary Face\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Flip a coin. If heads, until the end of your opponent\'s next turn the Defending Pokémon can\'t attack or retreat.\"}, {\'name\': \'Bite\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'\'}]', 'Skyridge', '1', '', 'Granbull', '', 'Second', '50', 'https://images.pokemoncard.io/images/ecard3/ecard3-101.png', 'unlimited: Legal', '', 'Snubbull', '209', 'WOTC', 'Common', '', '05/12/2003', '', 'Colorless', '', 'E-Card', '101', 'Basic', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
