('ecard3-119', '', '', 'Midori Harada', '', 'Skyridge', '', '', '', '', 'Second', '', 'https://images.pokemoncard.io/images/ecard3/ecard3-119.png', 'unlimited: Legal', '', 'Ancient Ruins', '', 'WOTC', 'Uncommon', '', '05/12/2003', '', '', '[\'This card stays in play when you play it. Discard this card if another Stadium card comes into play.\', \"Once during each player\'s turn (before he or she attacks), if he or she has not played a Supporter card, that player may reveal his or her hand to his or her opponent. If that player reveals his or her hand and there is no Supporter card there, that player draws a card.\"]', 'E-Card', '119', 'Stadium', 'Trainer', '', ''),
('ecard3-12', '', '', 'Kimiya Masago', '[{\'name\': \'Ambush\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'10+\', \'text\': \'Flip a coin. If heads, this attack does 10 damage plus 20 more damage.\'}, {\'name\': \'Lonely Fang\', \'cost\': [\'Darkness\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'30+\', \'text\': \"This attack does 30 damage plus 20 damage times the number of your opponent\'s Benched Pokémon minus the number of your Benched Pokémon. (For example, if your opponent has 3 Benched Pokémon and you have 1, this attack will do 30 damage plus 40 more damage.)\"}]', 'Skyridge', '1', 'Houndour', '', '', 'Second', '70', 'https://images.pokemoncard.io/images/ecard3/ecard3-12.png', 'unlimited: Legal', '', 'Houndoom', '229', 'WOTC', 'Rare', '', '05/12/2003', 'type: Psychic, value: -30', 'Colorless', '', 'E-Card', '12', 'Stage 1', 'Pokémon', 'Darkness', 'type: Fighting, value: ×2'),
('ecard3-120', '', '', 'Kagemaru Himeno', '', 'Skyridge', '', '', '', '', 'Second', '', 'https://images.pokemoncard.io/images/ecard3/ecard3-120.png', 'unlimited: Legal', '', 'Relic Hunter', '', 'WOTC', 'Uncommon', '', '05/12/2003', '', '', '[\'You can play only 1 Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.\', \'Search your deck for up to 2 Supporter and/or Stadium cards, show them to your opponent, and put them into your hand. Shuffle your deck afterward.\']', 'E-Card', '120', 'Supporter', 'Trainer', '', ''),
('ecard3-121', '', '', 'Kagemaru Himeno', '', 'Skyridge', '', '', '', '', 'Second', '', 'https://images.pokemoncard.io/images/ecard3/ecard3-121.png', 'unlimited: Legal', '', 'Apricorn Maker', '', 'WOTC', 'Uncommon', '', '05/12/2003', '', '', '[\'You can play only 1 Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.\', \'Search your deck for up to 2 Trainer cards with Ball in their names, show them to your opponent, and put them into your hand. Shuffle your deck afterward.\']', 'E-Card', '121', 'Supporter', 'Trainer', '', ''),
('ecard3-122', '', '', 'Jungo Suzuki', '', 'Skyridge', '', '', '', '', 'Second', '', 'https://images.pokemoncard.io/images/ecard3/ecard3-122.png', 'unlimited: Legal', '', 'Crystal Shard', '', 'WOTC', 'Uncommon', '', '05/12/2003', '', '', '[\"Attach Crystal Shard to 1 of your Pokémon that doesn\'t already have a Pokémon Tool attached to it. If that Pokémon is Knocked Out, discard this card.\", \"As long as this card is attached to a Pokémon, that Pokémon\'s type (color) is Colorless. If that Pokémon attacks, discard this card at the end of the turn.\"]', 'E-Card', '122', 'Pokémon Tool', 'Trainer', '', ''),
('ecard3-123', '', '', 'Kagemaru Himeno', '', 'Skyridge', '', '', '', '', 'Second', '', 'https://images.pokemoncard.io/images/ecard3/ecard3-123.png', 'unlimited: Legal', '', 'Desert Shaman', '', 'WOTC', 'Uncommon', '', '05/12/2003', '', '', '[\'You can play only 1 Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.\', \'Shuffle your hand into your deck and draw up to 4 cards. Your opponent does the same.\']', 'E-Card', '123', 'Supporter', 'Trainer', '', ''),
('ecard3-124', '', '', 'Katsura Tabata', '', 'Skyridge', '', '', '', '', 'Second', '', 'https://images.pokemoncard.io/images/ecard3/ecard3-124.png', 'unlimited: Legal', '', 'Fast Ball', '', 'WOTC', 'Uncommon', '', '05/12/2003', '', '', '[\"Reveal cards from your deck until you reveal an Evolution card. Show that card to your opponent and put it into your hand. Shuffle the other revealed cards into your deck. (If you don\'t reveal an Evolution card, shuffle all the revealed cards back into your deck.)\"]', 'E-Card', '124', '', 'Trainer', '', ''),
('ecard3-125', '', '', 'Kagemaru Himeno', '', 'Skyridge', '', '', '', '', 'Second', '', 'https://images.pokemoncard.io/images/ecard3/ecard3-125.png', 'unlimited: Legal, expanded: Legal', '', 'Fisherman', '', 'WOTC', 'Uncommon', '', '05/12/2003', '', '', '[\'You can play only 1 Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.\', \'Choose 4 basic Energy cards from your discard pile (if there are fewer basic Energy cards than choose, take all of them), show them to your opponent, and put them into your hand.\']', 'E-Card', '125', 'Supporter', 'Trainer', '', ''),
('ecard3-126', '', '', 'Katsura Tabata', '', 'Skyridge', '', '', '', '', 'Second', '', 'https://images.pokemoncard.io/images/ecard3/ecard3-126.png', 'unlimited: Legal', '', 'Friend Ball', '', 'WOTC', 'Uncommon', '', '05/12/2003', '', '', '[\"Choose 1 of your opponent\'s Pokémon. Search your deck for a Baby Pokémon, Basic Pokémon, or Evolution card of the same type (color), show it to your opponent, and put it into your hand. Shuffle your deck afterward.\"]', 'E-Card', '126', '', 'Trainer', '', ''),
('ecard3-127', '', '', 'Katsura Tabata', '', 'Skyridge', '', '', '', '', 'Second', '', 'https://images.pokemoncard.io/images/ecard3/ecard3-127.png', 'unlimited: Legal, expanded: Legal', '', 'Hyper Potion', '', 'WOTC', 'Uncommon', '', '05/12/2003', '', '', '[\'Choose 1 of your Pokémon. Discard 1 or 2 basic Energy cards attached to that Pokémon. If you discarded 1 Energy card, remove up to 3 damage counters from that Pokémon. If you discarded 2 Energy cards, remove up to 5 damage counters from that Pokémon.\']', 'E-Card', '127', '', 'Trainer', '', ''),
('ecard3-128', '', '', 'Katsura Tabata', '', 'Skyridge', '', '', '', '', 'Second', '', 'https://images.pokemoncard.io/images/ecard3/ecard3-128.png', 'unlimited: Legal, expanded: Legal', '', 'Lure Ball', '', 'WOTC', 'Uncommon', '', '05/12/2003', '', '', '[\'Flip 3 coins. For each heads, choose an Evolution card from your discard pile, show it to your opponent, and put it into your hand.\']', 'E-Card', '128', '', 'Trainer', '', ''),
('ecard3-129', '', '', 'Hiromichi Sugiyama', '[{\'name\': \'Fire Force\', \'cost\': [\'Fire\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'30+\', \'text\': \'If the Pokémon using this attack has Fire and Lightning basic Energy cards attached to it, the Defending Pokémon is now Confused. If the Pokémon using this attack has Fire and Fighting basic Energy cards attached to it, this attack does 30 damage plus 10 more damage and remove 3 damage counters from the Pokémon that Miracle Plate α is attached to.\'}]', 'Skyridge', '', '', '', '', 'Second', '', 'https://images.pokemoncard.io/images/ecard3/ecard3-129.png', 'unlimited: Legal', '', 'Miracle Sphere α', '', 'WOTC', 'Uncommon', '', '05/12/2003', '', '', '[\"Attach this card to 1 of your Evolved Fire, Lightning, or Fighting Pokémon in play. That Pokémon may use this card\'s attack instead of its own. At the end of your turn, discard Miracle Plate α.\"]', 'E-Card', '129', 'Technical Machine', 'Trainer', '', ''),
('ecard3-13', '[{\'name\': \'Self-healing\', \'text\': \'Whenever you attach a Lightning Energy card from your hand to Jolteon, remove all Special Conditions affecting Jolteon.\', \'type\': \'Poké-Body\'}]', '', 'Hikaru Koike', '[{\'name\': \'Thundershock\', \'cost\': [\'Lightning\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Paralyzed.\'}, {\'name\': \'Thunderspark\', \'cost\': [\'Lightning\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40\', \'text\': \"This attack does 10 damage to each Benched Pokémon with at least 1 Energy card attached to it (yours and your opponent\'s).\"}]', 'Skyridge', '', 'Eevee', '', '', 'Second', '70', 'https://images.pokemoncard.io/images/ecard3/ecard3-13.png', 'unlimited: Legal', '', 'Jolteon', '135', 'WOTC', 'Rare', '', '05/12/2003', '', '', '', 'E-Card', '13', 'Stage 1', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
('ecard3-130', '', '', 'Hiromichi Sugiyama', '[{\'name\': \'Freezing Force\', \'cost\': [\'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'30+\', \'text\': \'If the Pokémon using this attack has Fire and Water basic Energy cards attached to it, this attack does 30 damage plus 10 more damage and the Defending Pokémon is now Burned. If the Pokémon using this attack has Water and Psychic basic Energy cards attached to it, choose an Energy card attached to the Defending Pokémon, if any, and your opponent shuffles that card into his or her deck.\'}]', 'Skyridge', '', '', '', '', 'Second', '', 'https://images.pokemoncard.io/images/ecard3/ecard3-130.png', 'unlimited: Legal', '', 'Miracle Sphere β', '', 'WOTC', 'Uncommon', '', '05/12/2003', '', '', '[\"Attach this card to 1 of your Evolved Fire, Water, or Psychic Pokémon in play. That Pokémon may use this card\'s attack instead of its own. At the end of your turn, discard Miracle Sphere β.\"]', 'E-Card', '130', 'Technical Machine', 'Trainer', '', ''),
('ecard3-131', '', '', 'Hiromichi Sugiyama', '[{\'name\': \'Thunder Force\', \'cost\': [\'Lightning\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'30+\', \'text\': \"If the Pokémon using this attack has Grass and Lightning basic Energy cards attached to it, the Defending Pokémon is now Asleep and Poisoned. If the Pokémon using this attack has Water and Lightning basic Energy cards attached to it, this attack does 30 damage plus 10 more damage and lets you put 1 damage counter on each of your opponent\'s Benched Pokémon.\"}]', 'Skyridge', '', '', '', '', 'Second', '', 'https://images.pokemoncard.io/images/ecard3/ecard3-131.png', 'unlimited: Legal', '', 'Miracle Sphere γ', '', 'WOTC', 'Uncommon', '', '05/12/2003', '', '', '[\"Attach this card to 1 of your Evolved Grass, Water, or Lightning Pokémon in play. That Pokémon may use this card\'s attack instead of its own. At the end of your turn, discard Miracle Sphere γ.\"]', 'E-Card', '131', 'Technical Machine', 'Trainer', '', ''),
('ecard3-132', '', '', 'Midori Harada', '', 'Skyridge', '', '', '', '', 'Second', '', 'https://images.pokemoncard.io/images/ecard3/ecard3-132.png', 'unlimited: Legal', '', 'Mirage Stadium', '', 'WOTC', 'Uncommon', '', '05/12/2003', '', '', '[\'This card stays in play when you play it. Discard this card if another Stadium card comes into play.\', \"Whenever a player tries to retreat a Pokémon during his or her turn, that player flips a coin. If heads, that player retreats that Pokémon (and discards Energy normally). If tails, that Pokémon can\'t retreat this turn (the player doesn\'t discard any Energy).\"]', 'E-Card', '132', 'Stadium', 'Trainer', '', ''),
('ecard3-133', '', '', 'Hiromichi Sugiyama', '[{\'name\': \'Desert Burn\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'If your opponent has 5 or more Prizes, search your deck for a Trainer card, show it to your opponent, and put it into your hand. If your opponent has only 1 Prize, the Defending Pokémon is now Burned, Paralyzed, and Poisoned.\'}]', 'Skyridge', '', '', '', '', 'Second', '', 'https://images.pokemoncard.io/images/ecard3/ecard3-133.png', 'unlimited: Legal', '', 'Mystery Plate α', '', 'WOTC', 'Uncommon', '', '05/12/2003', '', '', '[\"Attach this card to 1 of your Pokémon in play. That Pokémon may use this card\'s attack instead of its own. At the end of your turn, discard Mystery Plate α.\"]', 'E-Card', '133', 'Technical Machine', 'Trainer', '', ''),
('ecard3-134', '', '', 'Hiromichi Sugiyama', '[{\'name\': \'Stone Crush\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'If your opponent has 5 or more Prizes, draw 3 cards. If your opponent has only 1 Prize, choose 2 Energy cards attached to the Defending Pokémon (1 if there is only 1). Your opponent shuffles those cards into his or her deck.\'}]', 'Skyridge', '', '', '', '', 'Second', '', 'https://images.pokemoncard.io/images/ecard3/ecard3-134.png', 'unlimited: Legal', '', 'Mystery Plate β', '', 'WOTC', 'Uncommon', '', '05/12/2003', '', '', '[\"Attach this card to 1 of your Pokémon in play. That Pokémon may use this card\'s attack instead of its own. At the end of your turn, discard Mystery Plate β.\"]', 'E-Card', '134', 'Technical Machine', 'Trainer', '', ''),
('ecard3-135', '', '', 'Hiromichi Sugiyama', '[{\'name\': \'Retro Cave\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"If your opponent has 5 or more Prizes, shuffle your hand into your deck and then draw 6 cards. If your opponent has exactly 2 Prizes, choose 1 of your opponent\'s Evolved Pokémon. Your opponent puts the top card on that Evolved Pokémon on the bottom of his or her deck. (This counts as devolving that Pokémon.)\"}]', 'Skyridge', '', '', '', '', 'Second', '', 'https://images.pokemoncard.io/images/ecard3/ecard3-135.png', 'unlimited: Legal', '', 'Mystery Plate γ', '', 'WOTC', 'Uncommon', '', '05/12/2003', '', '', '[\"Attach this card to 1 of your Pokémon in play. That Pokémon may use this card\'s attack instead of its own. At the end of your turn, discard Mystery Plate γ.\"]', 'E-Card', '135', 'Technical Machine', 'Trainer', '', ''),
('ecard3-136', '', '', 'Hiromichi Sugiyama', '[{\'name\': \'Healing Oasis\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'If your opponent has 5 or more Prizes, search your deck for up to 3 basic Energy cards, show them to your opponent, and put them into your hand. Shuffle your deck afterward. If your opponent has exactly 2 Prizes, remove all damage counters from 1 of your Pokémon.\'}]', 'Skyridge', '', '', '', '', 'Second', '', 'https://images.pokemoncard.io/images/ecard3/ecard3-136.png', 'unlimited: Legal', '', 'Mystery Plate δ', '', 'WOTC', 'Uncommon', '', '05/12/2003', '', '', '[\"Attach this card to 1 of your Pokémon in play. That Pokémon may use this card\'s attack instead of its own. At the end of your turn, discard Mystery Plate δ.\"]', 'E-Card', '136', 'Technical Machine', 'Trainer', '', ''),
('ecard3-137', '', '', 'Ken Ikuji', '', 'Skyridge', '', '', '', '', 'Second', '', 'https://images.pokemoncard.io/images/ecard3/ecard3-137.png', 'unlimited: Legal', '', 'Mystery Zone', '', 'WOTC', 'Uncommon', '', '05/12/2003', '', '', '[\'This card stays in play when you play it. Discard this card if another Stadium card comes into play.\', \"Once during each player\'s turn (before he or she attacks), if that player has an Evolution card in his or her hand, he or she may search his or her deck for a basic Energy card, show it to his or her opponent, and put it into his or her hand. Then that player chooses an Evolution card from his or her hand, shows it to his or her opponent, and puts it into his or her deck. That player shuffles his or her deck afterward.\"]', 'E-Card', '137', 'Stadium', 'Trainer', '', ''),
('ecard3-138', '', '', 'Kagemaru Himeno', '', 'Skyridge', '', '', '', '', 'Second', '', 'https://images.pokemoncard.io/images/ecard3/ecard3-138.png', 'unlimited: Legal', '', 'Oracle', '', 'WOTC', 'Uncommon', '', '05/12/2003', '', '', '[\'You can play only 1 Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.\', \'Choose 2 cards from your deck and shuffle the rest of your deck. Put the chosen cards on top of your deck in any order.\']', 'E-Card', '138', 'Supporter', 'Trainer', '', ''),
('ecard3-139', '', '', 'Jungo Suzuki', '', 'Skyridge', '', '', '', '', 'Second', '', 'https://images.pokemoncard.io/images/ecard3/ecard3-139.png', 'unlimited: Legal', '', 'Star Piece', '', 'WOTC', 'Uncommon', '', '05/12/2003', '', '', '[\"Attach Star Piece to 1 of your Pokémon that doesn\'t already have a Pokémon Tool attached to it. If that Pokémon is Knocked Out, discard this card.\", \'At any time between turns, if the Pokémon this card is attached to is Benched and has 2 or more damage counters on it, search your deck for an Evolution card that Pokémon evolves into and put it on top of that Pokémon. (This counts as evolving that Pokémon.) Shuffle your deck afterward. Then, discard Star Piece.\']', 'E-Card', '139', 'Pokémon Tool', 'Trainer', '', ''),
('ecard3-14', '[{\'name\': \'Primal Aura\', \'text\': \'As long as Kabutops is your Active Pokémon, neither player can play Basic Pokémon or Evolution cards from his or her hand to evolve Benched Pokémon.\', \'type\': \'Poké-Body\'}]', '', 'Kouki Saitou', '[{\'name\': \'Dual Cut\', \'cost\': [\'Fighting\', \'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50×\', \'text\': \'Flip 2 coins. This attack does 50 damage times the number of heads.\'}]', 'Skyridge', '2', 'Kabuto', '', '', 'Second', '90', 'https://images.pokemoncard.io/images/ecard3/ecard3-14.png', 'unlimited: Legal', '', 'Kabutops', '141', 'WOTC', 'Rare', '', '05/12/2003', '', 'Colorless, Colorless', '', 'E-Card', '14', 'Stage 2', 'Pokémon', 'Fighting', 'type: Grass, value: ×2'),
('ecard3-140', '', '', 'Kagemaru Himeno', '', 'Skyridge', '', '', '', '', 'Second', '', 'https://images.pokemoncard.io/images/ecard3/ecard3-140.png', 'unlimited: Legal, expanded: Legal', '', 'Underground Expedition', '', 'WOTC', 'Uncommon', '', '05/12/2003', '', '', '[\'You can play only 1 Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.\', \'Look at the bottom 4 cards of your deck. Put 2 of those cards into your hand, and then return the remaining cards to the bottom of your deck in any order.\']', 'E-Card', '140', 'Supporter', 'Trainer', '', ''),
('ecard3-141', '', '', 'Midori Harada', '', 'Skyridge', '', '', '', '', 'Second', '', 'https://images.pokemoncard.io/images/ecard3/ecard3-141.png', 'unlimited: Legal', '', 'Underground Lake', '', 'WOTC', 'Uncommon', '', '05/12/2003', '', '', '[\'This card stays in play when you play it. Discard this card if another Stadium card comes into play.\', \"Once during each player\'s turn, that player may put an Omanyte or a Kabuto card from his or her discard pile onto his or her Bench. (Cards put on the Bench this way are considered Basic Pokémon.)\"]', 'E-Card', '141', 'Stadium', 'Trainer', '', ''),
('ecard3-142', '', '', 'Shin-ichi Yoshikawa', '', 'Skyridge', '', '', '', '', 'Second', '', 'https://images.pokemoncard.io/images/ecard3/ecard3-142.png', 'unlimited: Legal', '', 'Bounce Energy', '', 'WOTC', 'Uncommon', '', '05/12/2003', '', '', '[\'This card provides ColorlessColorless Energy. You can attach this card to your Pokémon that has basic Energy cards attached to it. When you play this card from your hand and attach it to 1 of your Pokémon, return a basic Energy card attached to that Pokémon to your hand.\']', 'E-Card', '142', 'Special', 'Energy', '', ''),
('ecard3-143', '', '', 'Shin-ichi Yoshikawa', '', 'Skyridge', '', '', '', '', 'Second', '', 'https://images.pokemoncard.io/images/ecard3/ecard3-143.png', 'unlimited: Legal', '', 'Cyclone Energy', '', 'WOTC', 'Uncommon', '', '05/12/2003', '', '', '[\'This card provides Colorless Energy. When you play this card from your hand and attach it to your Active Pokémon, your opponent switches his or her Active Pokémon with 1 of his or her Benched Pokémon.\']', 'E-Card', '143', 'Special', 'Energy', '', ''),
('ecard3-144', '', '', 'Shin-ichi Yoshikawa', '', 'Skyridge', '', '', '', '', 'Second', '', 'https://images.pokemoncard.io/images/ecard3/ecard3-144.png', 'unlimited: Legal', '', 'Retro Energy', '', 'WOTC', 'Uncommon', '', '05/12/2003', '', '', '[\'This card provides Colorless Energy. When you play this card from your hand and attach it to 1 of your Evolved Pokémon, you may remove up to 2 damage counters from that Pokémon and discard the top card from it. (This counts as devolving it.)\']', 'E-Card', '144', 'Special', 'Energy', '', ''),
('ecard3-145', '[{\'name\': \'Crystal Type\', \'text\': \"Whenever you attach a Grass, Water, or Psychic basic Energy card from your hand to Celebi, Celebi\'s type (color) becomes the same as that type of Energy until the end of the turn.\", \'type\': \'Poké-Body\'}]', '', 'Mitsuhiro Arita', '[{\'name\': \'Empathic Healing\', \'cost\': [\'Grass\', \'Water\'], \'convertedEnergyCost\': 2, \'damage\': \'\', \'text\': \"Remove 2 damage counters from Celebi and each Pokémon that\'s the same type (color) as Celebi.\"}, {\'name\': \'Mind Bend\', \'cost\': [\'Grass\', \'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'20\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Confused.\'}]', 'Skyridge', '1', '', '', '', 'Second', '60', 'https://images.pokemoncard.io/images/ecard3/ecard3-145.png', 'unlimited: Legal', '', 'Celebi', '251', 'WOTC', 'Rare Secret', '', '05/12/2003', '', 'Colorless', '', 'E-Card', '145', 'Basic', 'Pokémon', 'Colorless', 'type: Fire, value: ×2'),
('ecard3-146', '[{\'name\': \'Crystal Type\', \'text\': \"Whenever you attach a Fire, Lightning, or Fighting basic Energy card from your hand to Charizard, Charizard\'s type (color) becomes the same as that type of Energy until the end of the turn.\", \'type\': \'Poké-Body\'}]', '', 'Kouki Saitou', '[{\'name\': \'Fireblast\', \'cost\': [\'Fire\', \'Fire\', \'Fighting\'], \'convertedEnergyCost\': 3, \'damage\': \'40\', \'text\': \'Discard an Energy card attached to Charizard.\'}, {\'name\': \'Dragon Tail\', \'cost\': [\'Fire\', \'Lightning\', \'Lightning\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'50×\', \'text\': \'Flip 2 coins. This attack does 50 damage times the number of heads.\'}]', 'Skyridge', '4', 'Charmeleon', '', '', 'Second', '110', 'https://images.pokemoncard.io/images/ecard3/ecard3-146.png', 'unlimited: Legal', '', 'Charizard', '6', 'WOTC', 'Rare Secret', '', '05/12/2003', '', 'Colorless, Colorless, Colorless, Colorless', '', 'E-Card', '146', 'Stage 2', 'Pokémon', 'Colorless', 'type: Water, value: ×2'),
('ecard3-147', '[{\'name\': \'Crystal Type\', \'text\': \"Whenever you attach a Grass, Fire, or Psychic basic Energy card from your hand to Crobat, Crobat\'s type (color) becomes the same as that type of Energy until the end of the turn.\", \'type\': \'Poké-Body\'}]', '', 'Atsuko Nishida', '[{\'name\': \'Poison Flame\', \'cost\': [\'Grass\', \'Fire\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'20\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Burned and Poisoned.\'}, {\'name\': \'Squared Attack\', \'cost\': [\'Grass\', \'Psychic\', \'Psychic\'], \'convertedEnergyCost\': 3, \'damage\': \'20×\', \'text\': \'Flip 4 coins. This attack does 20 damage times the number of heads.\'}]', 'Skyridge', '', 'Golbat', '', '', 'Second', '80', 'https://images.pokemoncard.io/images/ecard3/ecard3-147.png', 'unlimited: Legal', '', 'Crobat', '169', 'WOTC', 'Rare Secret', '', '05/12/2003', '', '', '', 'E-Card', '147', 'Stage 2', 'Pokémon', 'Colorless', 'type: Psychic, value: ×2'),
('ecard3-148', '[{\'name\': \'Crystal Type\', \'text\': \"Whenever you attach a Grass, Fire, or Fighting basic Energy card from your hand to Golem, Golem\'s type (color) becomes the same as that type of Energy until the end of the turn.\", \'type\': \'Poké-Body\'}]', '', 'Mitsuhiro Arita', '[{\'name\': \'Rock Throw\', \'cost\': [\'Fighting\', \'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'30\', \'text\': \'\'}, {\'name\': \'Earth Bomb\', \'cost\': [\'Grass\', \'Fire\', \'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'50\', \'text\': \"Golem does 20 damage to itself. This attack also does 10 damage to each Benched Pokémon (yours and your opponent\'s). (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'Skyridge', '4', 'Graveler', '', '', 'Second', '100', 'https://images.pokemoncard.io/images/ecard3/ecard3-148.png', 'unlimited: Legal', '', 'Golem', '76', 'WOTC', 'Rare Secret', '', '05/12/2003', '', 'Colorless, Colorless, Colorless, Colorless', '', 'E-Card', '148', 'Stage 2', 'Pokémon', 'Colorless', 'type: Water, value: ×2'),
('ecard3-149', '[{\'name\': \'Crystal Type\', \'text\': \"Whenever you attach a Fire, Water, or Lightning basic Energy card from your hand to Ho-oh, Ho-oh\'s type (color) becomes the same as that type of Energy until the end of the turn.\", \'type\': \'Poké-Body\'}]', '', 'Hajime Kusajima', '[{\'name\': \'Holy Flame\', \'cost\': [\'Fire\', \'Lightning\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'\'}, {\'name\': \'Scalding Steam\', \'cost\': [\'Fire\', \'Water\', \'Water\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'40\', \'text\': \'Discard an Energy card attached to Ho-oh and flip a coin. If heads, the Defending Pokémon is now Burned.\'}]', 'Skyridge', '3', '', '', '', 'Second', '80', 'https://images.pokemoncard.io/images/ecard3/ecard3-149.png', 'unlimited: Legal', '', 'Ho-oh', '250', 'WOTC', 'Rare Secret', '', '05/12/2003', '', 'Colorless, Colorless, Colorless', '', 'E-Card', '149', 'Basic', 'Pokémon', 'Colorless', 'type: Water, value: ×2'),
('ecard3-15', '', '', 'Hikaru Koike', '[{\'name\': \'Pollen Shield\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \"During your opponent\'s next turn, Ledian can\'t become affected by a Special Condition. (Any other effects of attacks, Poké-Powers, Poké-Bodies, and Trainer cards still happen.)\"}, {\'name\': \'Swift\', \'cost\': [\'Grass\', \'Grass\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50\', \'text\': \"This attack\'s damage isn\'t affected by Weakness, Resistance, Poké-Powers, Poké-Bodies, or any other effects on the Defending Pokémon.\"}]', 'Skyridge', '', 'Ledyba', '', '', 'Second', '70', 'https://images.pokemoncard.io/images/ecard3/ecard3-15.png', 'unlimited: Legal', '', 'Ledian', '166', 'WOTC', 'Rare', '', '05/12/2003', '', '', '', 'E-Card', '15', 'Stage 1', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('ecard3-150', '[{\'name\': \'Crystal Type\', \'text\': \"Whenever you attach a Water, Lightning, or Fighting basic Energy card from your hand to Kabutops, Kabutops\'s type (color) becomes the same as that type of Energy until the end of the turn.\", \'type\': \'Poké-Body\'}]', '', 'Atsuko Nishida', '[{\'name\': \'Draining Cut\', \'cost\': [\'Water\', \'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'20\', \'text\': \'Remove a damage counter from Kabutops.\'}, {\'name\': \'Triple Cutter\', \'cost\': [\'Lightning\', \'Lightning\', \'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'30×\', \'text\': \'Flip 3 coins. This attack does 30 damage times the number of heads.\'}]', 'Skyridge', '3', 'Kabuto', '', '', 'Second', '90', 'https://images.pokemoncard.io/images/ecard3/ecard3-150.png', 'unlimited: Legal', '', 'Kabutops', '141', 'WOTC', 'Rare Secret', '', '05/12/2003', '', 'Colorless, Colorless, Colorless', '', 'E-Card', '150', 'Stage 2', 'Pokémon', 'Colorless', 'type: Grass, value: ×2');
INSERT INTO `cards` (`id`, `abilities`, `ancient_trait`, `artist`, `attacks`, `card_set`, `converted`, `evolves_from`, `evolves_to`, `flavor_text`, `generation`, `hp`, `img`, `legalities`, `level`, `name`, `national_pokedex_numbers`, `publisher`, `rarity`, `regulation_mark`, `release_date`, `resistances`, `retreat_cost`, `rules`, `series`, `set_num`, `subtypes`, `supertype`, `types`, `weakness`) VALUES
('ecard3-16', '[{\'name\': \'Immunity\', \'text\': \"Prevent all effects of your opponent\'s attacks done to Machamp.\", \'type\': \'Poké-Body\'}]', '', 'Naoyo Kimura', '[{\'name\': \'Drag Off\', \'cost\': [\'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'Before doing damage, if your opponent has any Benched Pokémon, choose 1 of them and switch it with the Defending Pokémon. If your opponent has no Benched Pokémon, ignore this effect.\'}, {\'name\': \'Hurricane Punch\', \'cost\': [\'Fighting\', \'Fighting\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'30×\', \'text\': \'Flip 4 coins. This attack does 30 damage times the number of heads.\'}]', 'Skyridge', '2', 'Machoke', '', '', 'Second', '120', 'https://images.pokemoncard.io/images/ecard3/ecard3-16.png', 'unlimited: Legal', '', 'Machamp', '68', 'WOTC', 'Rare', '', '05/12/2003', '', 'Colorless, Colorless', '', 'E-Card', '16', 'Stage 2', 'Pokémon', 'Fighting', 'type: Psychic, value: ×2'),
('ecard3-17', '', '', 'Hajime Kusajima', '[{\'name\': \'Eruption\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20+\', \'text\': \'Each player discard the top card of his or her deck. This attack does 20 damage plus 20 more damage for each Fire Energy card discarded in this way.\'}, {\'name\': \'Fire Stream\', \'cost\': [\'Fire\', \'Fire\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'60\', \'text\': \"Discard a Fire Energy card attached to Magcargo in order to use this attack. If your opponent has any Benched Pokémon, this attack does 10 damage to each of them. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'Skyridge', '3', 'Slugma', '', '', 'Second', '80', 'https://images.pokemoncard.io/images/ecard3/ecard3-17.png', 'unlimited: Legal', '', 'Magcargo', '219', 'WOTC', 'Rare', '', '05/12/2003', '', 'Colorless, Colorless, Colorless', '', 'E-Card', '17', 'Stage 1', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('ecard3-18', '[{\'name\': \'Streaming Mantle\', \'text\': \'When you play Magcargo from your hand to evolve your Active Pokémon, you may discard the top 3 cards of your deck and and then shuffle 3 basic Energy cards from your discard pile into your deck. If you do, your opponent does the same.\', \'type\': \'Poké-Power\'}]', '', 'Mitsuhiro Arita', '[{\'name\': \'Crushing Lava\', \'cost\': [\'Fighting\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40+\', \'text\': \'You may discard a Fire or Fighting basic Energy card attached to Magcargo. If you discard a Fire Energy card in this way, the Defending Pokémon is now Burned. If you discard a Fighting Energy card in this way, this attack does 40 damage plus 20 more damage.\'}]', 'Skyridge', '3', 'Slugma', '', '', 'Second', '80', 'https://images.pokemoncard.io/images/ecard3/ecard3-18.png', 'unlimited: Legal', '', 'Magcargo', '219', 'WOTC', 'Rare', '', '05/12/2003', '', 'Colorless, Colorless, Colorless', '', 'E-Card', '18', 'Stage 1', 'Pokémon', 'Fighting', 'type: Water, value: ×2'),
('ecard3-19', '[{\'name\': \'Attract Energy\', \'text\': \'When you play Magneton from your hand to evolve 1 of your Pokémon, you may move any number of basic Energy cards attached to your other Pokémon to Magneton.\', \'type\': \'Poké-Power\'}]', '', 'Hajime Kusajima', '[{\'name\': \'Electric Blast\', \'cost\': [\'Lightning\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40\', \'text\': \"You may discard all Lightning Energy cards attached to Magneton when you use this attack. If you do, put damage counters equal to the amount of Energy cards removed in this way on any number of your opponent\'s Benched Pokémon in the way you like. (For example, if you discard 3 Lightning Energy cards, you can put 1 damage counter on 1 of your opponent\'s Benched Pokémon and 2 on another.)\"}]', 'Skyridge', '1', 'Magnemite', 'Magnezone', '', 'Second', '80', 'https://images.pokemoncard.io/images/ecard3/ecard3-19.png', 'unlimited: Legal', '', 'Magneton', '82', 'WOTC', 'Rare', '', '05/12/2003', '', 'Colorless', '', 'E-Card', '19', 'Stage 1', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
('ecard3-2', '[{\'name\': \'Energy Jump\', \'text\': \"Once during your turn (before your attack), you may move an Energy card from 1 of your Pokémon to another of your Pokémon. This power can\'t be used if Alakazam is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Kimiya Masago', '[{\'name\': \'Psychic\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'30+\', \'text\': \'This attack does 30 damage plus 10 more damage for each Energy card attached to the Defending Pokémon.\'}]', 'Skyridge', '2', 'Kadabra', '', '', 'Second', '100', 'https://images.pokemoncard.io/images/ecard3/ecard3-2.png', 'unlimited: Legal', '', 'Alakazam', '65', 'WOTC', 'Rare', '', '05/12/2003', '', 'Colorless, Colorless', '', 'E-Card', '2', 'Stage 2', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2'),
('ecard3-20', '', '', 'Kouki Saitou', '[{\'name\': \'Bounce Off\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \"If Magneton and the Defending Pokémon don\'t have the same number of Energy cards attached to them, the player controlling the Active Pokémon with the fewest number of Energy cards attached to it switches 1 of his or her Benched Pokémon with his or her Active Pokémon.\"}, {\'name\': \'Magnetic Wave\', \'cost\': [\'Metal\', \'Metal\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'30+\', \'text\': \"This attack does 30 damage plus 10 damage times the number of your Benched Pokémon minus the number of your opponent\'s Benched Pokémon. (For example, if your opponent has 1 Benched Pokémon and you have 3, this attack will do 30 damage plus 20 more damage.)\"}]', 'Skyridge', '2', 'Magnemite', 'Magnezone', '', 'Second', '70', 'https://images.pokemoncard.io/images/ecard3/ecard3-20.png', 'unlimited: Legal', '', 'Magneton', '82', 'WOTC', 'Rare', '', '05/12/2003', 'type: Grass, value: -30', 'Colorless, Colorless', '', 'E-Card', '20', 'Stage 1', 'Pokémon', 'Metal', 'type: Fire, value: ×2'),
('ecard3-21', '[{\'name\': \'Fire Immunity\', \'text\': \"You can\'t attach Fire Energy cards from your hand to Moltres.\", \'type\': \'Poké-Body\'}]', '', 'Kouki Saitou', '[{\'name\': \'Collect Fire\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'If there are any Fire Energy cards in your discard pile, flip a coin. If heads, attach 1 of them to Moltres.\'}, {\'name\': \'Burning Tail\', \'cost\': [\'Fire\', \'Fire\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'60\', \'text\': \'Flip a coin. If tails, discard a Fire Energy card attached to Moltres.\'}]', 'Skyridge', '2', '', '', '', 'Second', '80', 'https://images.pokemoncard.io/images/ecard3/ecard3-21.png', 'unlimited: Legal', '', 'Moltres', '146', 'WOTC', 'Rare', '', '05/12/2003', 'type: Fighting, value: -30', 'Colorless, Colorless', '', 'E-Card', '21', 'Basic', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('ecard3-22', '[{\'name\': \'Evolution Helper\', \'text\': \'Once during your turn (before your attack), if Nidoqueen is on your Bench, you may search your deck for a card that evolves from your Active Pokémon and attach it to your Active Pokémon. (This counts as evolving that Pokémon.) Shuffle your deck afterward.\', \'type\': \'Poké-Power\'}]', '', 'Mitsuhiro Arita', '[{\'name\': \'Double Claw\', \'cost\': [\'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'30+\', \'text\': \'Flip 2 coins. This attack does 30 damage plus 20 more damage for each heads\'}]', 'Skyridge', '3', 'Nidorina', '', '', 'Second', '110', 'https://images.pokemoncard.io/images/ecard3/ecard3-22.png', 'unlimited: Legal', '', 'Nidoqueen', '31', 'WOTC', 'Rare', '', '05/12/2003', '', 'Colorless, Colorless, Colorless', '', 'E-Card', '22', 'Stage 2', 'Pokémon', 'Grass', 'type: Psychic, value: ×2'),
('ecard3-23', '[{\'name\': \'Primal Stare\', \'text\': \"As long as Omastar is your Active Pokémon, your opponent can\'t play Basic Pokémon or Evolution cards from his or her hand to evolve his or her Active Pokémon.\", \'type\': \'Poké-Body\'}]', '', 'Hajime Kusajima', '[{\'name\': \'Spook\', \'cost\': [\'Water\', \'Water\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50\', \'text\': \"The Defending Pokémon can\'t retreat during your opponent\'s next turn.\"}]', 'Skyridge', '2', 'Omanyte', '', '', 'Second', '90', 'https://images.pokemoncard.io/images/ecard3/ecard3-23.png', 'unlimited: Legal', '', 'Omastar', '139', 'WOTC', 'Rare', '', '05/12/2003', '', 'Colorless, Colorless', '', 'E-Card', '23', 'Stage 2', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('ecard3-24', '', '', 'Yuka Morii', '[{\'name\': \'Freezing Breath\', \'cost\': [\'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'20\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Paralyzed. If tails, the Defending Pokémon is now Asleep.\'}, {\'name\': \'Trample\', \'cost\': [\'Fighting\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'40\', \'text\': \"For each Benched Pokémon (yours and your opponent\'s), flip a coin. If heads, this attack does 20 damage to that Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'Skyridge', '3', 'Swinub', 'Mamoswine', '', 'Second', '90', 'https://images.pokemoncard.io/images/ecard3/ecard3-24.png', 'unlimited: Legal', '', 'Piloswine', '221', 'WOTC', 'Rare', '', '05/12/2003', '', 'Colorless, Colorless, Colorless', '', 'E-Card', '24', 'Stage 1', 'Pokémon', 'Water', 'type: Metal, value: ×2'),
('ecard3-25', '', '', 'Atsuko Nishida', '[{\'name\': \'Sudden Growth\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Attach any number of basic Energy cards from your hand to Politoed.\'}, {\'name\': \'Frog Hop\', \'cost\': [\'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'30+\', \'text\': \'Flip a coin. If heads, this attack does 30 damage plus 20 more damage.\'}, {\'name\': \'Energy Splash\', \'cost\': [\'Water\', \'Water\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 5, \'damage\': \'70\', \'text\': \'Move 2 Water Energy cards attached to Politoed to 1 or 2 of your Benched Pokémon. (You may put both on the same Pokémon or 1 each on 2 different Pokémon.) If you have no Benched Pokémon, ignore this effect.\'}]', 'Skyridge', '2', 'Poliwhirl', '', '', 'Second', '110', 'https://images.pokemoncard.io/images/ecard3/ecard3-25.png', 'unlimited: Legal', '', 'Politoed', '186', 'WOTC', 'Rare', '', '05/12/2003', '', 'Colorless, Colorless', '', 'E-Card', '25', 'Stage 2', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('ecard3-26', '[{\'name\': \'Strange Spiral\', \'text\': \"Once during your turn (before your attack), if Poliwrath is your Active Pokémon, you may discard a basic Energy card attached to Poliwrath. If you do, the Defending Pokémon is now Confused. This power can\'t be used if Poliwrath is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Naoyo Kimura', '[{\'name\': \'Spiral Punch\', \'cost\': [\'Fighting\', \'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40+\', \'text\': \'Flip a coin until you get tails. This attack does 40 damage plus 20 more damage for each heads.\'}]', 'Skyridge', '2', 'Poliwhirl', '', '', 'Second', '110', 'https://images.pokemoncard.io/images/ecard3/ecard3-26.png', 'unlimited: Legal', '', 'Poliwrath', '62', 'WOTC', 'Rare', '', '05/12/2003', '', 'Colorless, Colorless', '', 'E-Card', '26', 'Stage 2', 'Pokémon', 'Fighting', 'type: Psychic, value: ×2'),
('ecard3-27', '', '', 'Yuka Morii', '[{\'name\': \'Zzzap\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'\', \'text\': \"This attack does 20 damage to each Pokémon with a Poké-Body or Poké-Power (yours and your opponent\'s). (Don\'t apply Weakness or Resistance.)\"}, {\'name\': \'Lightning Storm\', \'cost\': [\'Lightning\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50\', \'text\': \'Flip a coin. If tails, put 2 damage counters on Raichu.\'}]', 'Skyridge', '1', 'Pikachu', '', '', 'Second', '80', 'https://images.pokemoncard.io/images/ecard3/ecard3-27.png', 'unlimited: Legal', '', 'Raichu', '26', 'WOTC', 'Rare', '', '05/12/2003', '', 'Colorless', '', 'E-Card', '27', 'Stage 1', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
('ecard3-28', '[{\'name\': \'Pure Body\', \'text\': \'To attach a Lightning Energy card from your hand to Raikou, you must discard an Energy card attached to Raikou. (Attach the Lightning Energy, and then discard an Energy card from Raikou.)\', \'type\': \'Poké-Body\'}]', '', 'Mitsuhiro Arita', '[{\'name\': \'Lightning Sphere\', \'cost\': [\'Lightning\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40+\', \'text\': \'You may flip a coin. If heads, discard all Lightning Energy cards attached to Raikou. This attack does 40 damage plus 20 more damage for each Energy card discarded in this way.\'}]', 'Skyridge', '1', '', '', '', 'Second', '70', 'https://images.pokemoncard.io/images/ecard3/ecard3-28.png', 'unlimited: Legal', '', 'Raikou', '243', 'WOTC', 'Rare', '', '05/12/2003', '', 'Colorless', '', 'E-Card', '28', 'Basic', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
('ecard3-29', '', '', 'Mitsuhiro Arita', '[{\'name\': \'Stomp\', \'cost\': [\'Fighting\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'30+\', \'text\': \'Flip a coin. If heads, this attack does 30 damage plus 20 more damage.\'}, {\'name\': \'Giant Tail\', \'cost\': [\'Fighting\', \'Fighting\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 5, \'damage\': \'100\', \'text\': \'Flip a coin. If tails, this attack does nothing.\'}]', 'Skyridge', '2', 'Rhyhorn', 'Rhyperior', '', 'Second', '90', 'https://images.pokemoncard.io/images/ecard3/ecard3-29.png', 'unlimited: Legal', '', 'Rhydon', '112', 'WOTC', 'Rare', '', '05/12/2003', 'type: Lightning, value: -30', 'Colorless, Colorless', '', 'E-Card', '29', 'Stage 1', 'Pokémon', 'Fighting', 'type: Grass, value: ×2'),
('ecard3-3', '[{\'name\': \'Energy Recharge\', \'text\': \'When you play Arcanine from your hand to evolve your Active Pokémon, you may flip 3 coins. For each heads, choose a basic Energy card from your discard pile and attach it to Arcanine.\', \'type\': \'Poké-Power\'}]', '', 'Aya Kusube', '[{\'name\': \'Shake\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'Your opponent switches the Defending Pokémon with 1 of his or her Benched Pokémon, if any.\'}, {\'name\': \'White Flames\', \'cost\': [\'Fire\', \'Fire\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'70\', \'text\': \'Discard all Fire Energy cards attached to Arcanine.\'}]', 'Skyridge', '2', 'Growlithe', '', '', 'Second', '80', 'https://images.pokemoncard.io/images/ecard3/ecard3-3.png', 'unlimited: Legal', '', 'Arcanine', '59', 'WOTC', 'Rare', '', '05/12/2003', '', 'Colorless, Colorless', '', 'E-Card', '3', 'Stage 1', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('ecard3-30', '', '', 'Hajime Kusajima', '[{\'name\': \'Energy Burst\', \'cost\': [\'Psychic\'], \'convertedEnergyCost\': 1, \'damage\': \'10×\', \'text\': \'Flip a coin. If heads, this attack does 10 damage times the number of Energy attached to Starmie and the Defending Pokémon.\'}, {\'name\': \'Star Back\', \'cost\': [\'Psychic\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40\', \'text\': \'Attach a basic Energy card from your discard pile to 1 of your Pokémon.\'}]', 'Skyridge', '1', 'Staryu', '', '', 'Second', '80', 'https://images.pokemoncard.io/images/ecard3/ecard3-30.png', 'unlimited: Legal', '', 'Starmie', '121', 'WOTC', 'Rare', '', '05/12/2003', '', 'Colorless', '', 'E-Card', '30', 'Stage 1', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2'),
('ecard3-31', '[{\'name\': \'Rare Metal\', \'text\': \'All basic Energy cards attached to Steelix provide Metal Energy instead of their usual types.\', \'type\': \'Poké-Body\'}]', '', 'Hikaru Koike', '[{\'name\': \'Squeeze\', \'cost\': [\'Metal\', \'Metal\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'20+\', \'text\': \'Flip a coin. If heads, this attack does 20 damage plus 10 more damage and the Defending Pokémon is now Paralyzed.\'}, {\'name\': \'Metal Tail\', \'cost\': [\'Metal\', \'Metal\', \'Metal\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'40\', \'text\': \'Before doing damage, you may flip a coin. If heads, this attack does 80 damage. If tails, this attack does nothing.\'}]', 'Skyridge', '4', 'Onix', '', '', 'Second', '100', 'https://images.pokemoncard.io/images/ecard3/ecard3-31.png', 'unlimited: Legal', '', 'Steelix', '208', 'WOTC', 'Rare', '', '05/12/2003', 'type: Grass, value: -30', 'Colorless, Colorless, Colorless, Colorless', '', 'E-Card', '31', 'Stage 1', 'Pokémon', 'Metal', 'type: Fire, value: ×2'),
('ecard3-32', '[{\'name\': \'Dark Gaze\', \'text\': \"As long as Umbreon is your Active Pokémon, Benched Pokémon (yours and your opponent\'s) can\'t use Poké-Powers.\", \'type\': \'Poké-Body\'}]', '', 'Atsuko Nishida', '[{\'name\': \'Sharp Claws\', \'cost\': [\'Darkness\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'10+\', \'text\': \'Flip a coin. If heads, this attack does 10 damage plus 30 more damage.\'}]', 'Skyridge', '1', 'Eevee', '', '', 'Second', '70', 'https://images.pokemoncard.io/images/ecard3/ecard3-32.png', 'unlimited: Legal', '', 'Umbreon', '197', 'WOTC', 'Rare', '', '05/12/2003', 'type: Psychic, value: -30', 'Colorless', '', 'E-Card', '32', 'Stage 1', 'Pokémon', 'Darkness', 'type: Fighting, value: ×2'),
('ecard3-33', '[{\'name\': \'Self-healing\', \'text\': \'Whenever you attach a Water Energy card from your hand to Vaporeon, remove all Special Conditions affecting Vaporeon.\', \'type\': \'Poké-Body\'}]', '', 'Naoyo Kimura', '[{\'name\': \'Hypnosplash\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'10\', \'text\': \'The Defending Pokémon is now Asleep.\'}, {\'name\': \'Aqua Trick\', \'cost\': [\'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40\', \'text\': \"If the Defending Pokémon has any Energy cards attached to it, flip a coin. If heads, choose 1 of those Energy cards and move it to 1 of your opponent\'s Benched Pokémon. If your opponent has no Benched Pokémon, ignore this effect.\"}]', 'Skyridge', '1', 'Eevee', '', '', 'Second', '70', 'https://images.pokemoncard.io/images/ecard3/ecard3-33.png', 'unlimited: Legal', '', 'Vaporeon', '134', 'WOTC', 'Rare', '', '05/12/2003', '', 'Colorless', '', 'E-Card', '33', 'Stage 1', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('ecard3-34', '[{\'name\': \'Good Neighbor\', \'text\': \"Once during your turn (before your attack), if Wigglytuff is on your bench, you may flip a coin. If heads, each player removes up to 2 damage counters from his or her Active Pokémon. This power can\'t be used if you have already used another Wigglytuff\'s Good Neighbor Poké-Power this turn.\", \'type\': \'Poké-Power\'}]', '', 'Hizuki Misono', '[{\'name\': \'Do the Wave\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'10×\', \'text\': \'Flip a coin. If heads, this attack does 10 damage times the number of Pokémon you have in play.\'}]', 'Skyridge', '1', 'Jigglypuff', '', '', 'Second', '70', 'https://images.pokemoncard.io/images/ecard3/ecard3-34.png', 'unlimited: Legal', '', 'Wigglytuff', '40', 'WOTC', 'Rare', '', '05/12/2003', '', 'Colorless', '', 'E-Card', '34', 'Stage 1', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('ecard3-35', '[{\'name\': \'Synchronicity\', \'text\': \'You may attach any Technical Machine to Xatu.\', \'type\': \'Poké-Body\'}]', '', 'Atsuko Nishida', '[{\'name\': \'Warp Hole\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'30\', \'text\': \'Flip a coin. If heads, choose a card from your discard pile and put it on top of your deck.\'}]', 'Skyridge', '1', 'Natu', '', '', 'Second', '80', 'https://images.pokemoncard.io/images/ecard3/ecard3-35.png', 'unlimited: Legal', '', 'Xatu', '178', 'WOTC', 'Rare', '', '05/12/2003', '', 'Colorless', '', 'E-Card', '35', 'Stage 1', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2'),
('ecard3-36', '', '', 'Sumiyoshi Kizuki', '[{\'name\': \'Plasma\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'If there are any Lightning Energy card in your discard pile, flip a coin. If heads, attach 1 of them to Electrode.\'}, {\'name\': \'Selfdestruct\', \'cost\': [\'Lightning\', \'Lightning\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'100\', \'text\': \"This attack does 20 damage to each Pokémon on each player\'s Bench. (Don\'t apply Weakness and Resistance for Benched Pokémon.) Electrode does 100 damage to itself.\"}]', 'Skyridge', '1', 'Voltorb', '', '', 'Second', '70', 'https://images.pokemoncard.io/images/ecard3/ecard3-36.png', 'unlimited: Legal', '', 'Electrode', '101', 'WOTC', 'Uncommon', '', '05/12/2003', '', 'Colorless', '', 'E-Card', '36', 'Stage 1', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
