('ecard3-H17', '[{\'name\': \'Streaming Mantle\', \'text\': \'When you play Magcargo from your hand to evolve your Active Pokémon, you may discard the top 3 cards of your deck and and then shuffle 3 basic Energy cards from your discard pile into your deck. If you do, your opponent does the same.\', \'type\': \'Poké-Power\'}]', '', 'Mitsuhiro Arita', '[{\'name\': \'Crushing Lava\', \'cost\': [\'Fighting\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40+\', \'text\': \'You may discard a Fire or Fighting basic Energy card attached to Magcargo. If you discard a Fire Energy card in this way, the Defending Pokémon is now Burned. If you discard a Fighting Energy card in this way, this attack does 40 damage plus 20 more damage.\'}]', 'Skyridge', '3', 'Slugma', '', '', 'Second', '80', 'https://images.pokemoncard.io/images/ecard3/ecard3-H17.png', 'unlimited: Legal', '', 'Magcargo', '219', 'WOTC', 'Rare Holo', '', '05/12/2003', '', 'Colorless, Colorless, Colorless', '', 'E-Card', 'H17', 'Stage 1', 'Pokémon', 'Fighting', 'type: Water, value: ×2'),
('ecard3-H18', '[{\'name\': \'Attract Energy\', \'text\': \'When you play Magneton from your hand to evolve 1 of your Pokémon, you may move any number of basic Energy cards attached to your other Pokémon to Magneton.\', \'type\': \'Poké-Power\'}]', '', 'Hajime Kusajima', '[{\'name\': \'Electric Blast\', \'cost\': [\'Lightning\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40\', \'text\': \"You may discard all Lightning Energy cards attached to Magneton when you use this attack. If you do, put damage counters equal to the amount of Energy cards removed in this way on any number of your opponent\'s Benched Pokémon in the way you like. (For example, if you discard 3 Lightning Energy cards, you can put 1 damage counter on 1 of your opponent\'s Benched Pokémon and 2 on another.)\"}]', 'Skyridge', '1', 'Magnemite', 'Magnezone', '', 'Second', '80', 'https://images.pokemoncard.io/images/ecard3/ecard3-H18.png', 'unlimited: Legal', '', 'Magneton', '82', 'WOTC', 'Rare Holo', '', '05/12/2003', '', 'Colorless', '', 'E-Card', 'H18', 'Stage 1', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
('ecard3-H19', '', '', 'Kouki Saitou', '[{\'name\': \'Bounce Off\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \"If Magneton and the Defending Pokémon don\'t have the same number of Energy cards attached to them, the player controlling the Active Pokémon with the fewest number of Energy cards attached to it switches 1 of his or her Benched Pokémon with his or her Active Pokémon.\"}, {\'name\': \'Magnetic Wave\', \'cost\': [\'Metal\', \'Metal\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'30+\', \'text\': \"This attack does 30 damage plus 10 damage times the number of your Benched Pokémon minus the number of your opponent\'s Benched Pokémon. (For example, if your opponent has 1 Benched Pokémon and you have 3, this attack will do 30 damage plus 20 more damage.)\"}]', 'Skyridge', '2', 'Magnemite', 'Magnezone', '', 'Second', '70', 'https://images.pokemoncard.io/images/ecard3/ecard3-H19.png', 'unlimited: Legal', '', 'Magneton', '82', 'WOTC', 'Rare Holo', '', '05/12/2003', 'type: Grass, value: -30', 'Colorless, Colorless', '', 'E-Card', 'H19', 'Stage 1', 'Pokémon', 'Metal', 'type: Fire, value: ×2'),
('ecard3-H2', '[{\'name\': \'Energy Recharge\', \'text\': \'When you play Arcanine from your hand to evolve your Active Pokémon, you may flip 3 coins. For each heads, choose a basic Energy card from your discard pile and attach it to Arcanine.\', \'type\': \'Poké-Power\'}]', '', 'Aya Kusube', '[{\'name\': \'Shake\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'Your opponent switches the Defending Pokémon with 1 of his or her Benched Pokémon, if any.\'}, {\'name\': \'White Flames\', \'cost\': [\'Fire\', \'Fire\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'70\', \'text\': \'Discard all Fire Energy cards attached to Arcanine.\'}]', 'Skyridge', '2', 'Growlithe', '', '', 'Second', '80', 'https://images.pokemoncard.io/images/ecard3/ecard3-H2.png', 'unlimited: Legal', '', 'Arcanine', '59', 'WOTC', 'Rare Holo', '', '05/12/2003', '', 'Colorless, Colorless', '', 'E-Card', 'H2', 'Stage 1', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('ecard3-H20', '[{\'name\': \'Fire Immunity\', \'text\': \"You can\'t attach Fire Energy cards from your hand to Moltres.\", \'type\': \'Poké-Body\'}]', '', 'Kouki Saitou', '[{\'name\': \'Collect Fire\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'If there are any Fire Energy cards in your discard pile, flip a coin. If heads, attach 1 of them to Moltres.\'}, {\'name\': \'Burning Tail\', \'cost\': [\'Fire\', \'Fire\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'60\', \'text\': \'Flip a coin. If tails, discard a Fire Energy card attached to Moltres.\'}]', 'Skyridge', '2', '', '', '', 'Second', '80', 'https://images.pokemoncard.io/images/ecard3/ecard3-H20.png', 'unlimited: Legal', '', 'Moltres', '146', 'WOTC', 'Rare Holo', '', '05/12/2003', 'type: Fighting, value: -30', 'Colorless, Colorless', '', 'E-Card', 'H20', 'Basic', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('ecard3-H21', '[{\'name\': \'Evolution Helper\', \'text\': \'Once during your turn (before your attack), if Nidoqueen is on your Bench, you may search your deck for a card that evolves from your Active Pokémon and attach it to your Active Pokémon. (This counts as evolving that Pokémon.) Shuffle your deck afterward.\', \'type\': \'Poké-Power\'}]', '', 'Mitsuhiro Arita', '[{\'name\': \'Double Claw\', \'cost\': [\'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'30+\', \'text\': \'Flip 2 coins. This attack does 30 damage plus 20 more damage for each heads\'}]', 'Skyridge', '3', 'Nidorina', '', '', 'Second', '110', 'https://images.pokemoncard.io/images/ecard3/ecard3-H21.png', 'unlimited: Legal', '', 'Nidoqueen', '31', 'WOTC', 'Rare Holo', '', '05/12/2003', '', 'Colorless, Colorless, Colorless', '', 'E-Card', 'H21', 'Stage 2', 'Pokémon', 'Grass', 'type: Psychic, value: ×2'),
('ecard3-H22', '', '', 'Yuka Morii', '[{\'name\': \'Freezing Breath\', \'cost\': [\'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'20\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Paralyzed. If tails, the Defending Pokémon is now Asleep.\'}, {\'name\': \'Trample\', \'cost\': [\'Fighting\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'40\', \'text\': \"For each Benched Pokémon (yours and your opponent\'s), flip a coin. If heads, this attack does 20 damage to that Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'Skyridge', '3', 'Swinub', 'Mamoswine', '', 'Second', '90', 'https://images.pokemoncard.io/images/ecard3/ecard3-H22.png', 'unlimited: Legal', '', 'Piloswine', '221', 'WOTC', 'Rare Holo', '', '05/12/2003', '', 'Colorless, Colorless, Colorless', '', 'E-Card', 'H22', 'Stage 1', 'Pokémon', 'Water', 'type: Metal, value: ×2'),
('ecard3-H23', '', '', 'Atsuko Nishida', '[{\'name\': \'Sudden Growth\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Attach any number of basic Energy cards from your hand to Politoed.\'}, {\'name\': \'Frog Hop\', \'cost\': [\'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'30+\', \'text\': \'Flip a coin. If heads, this attack does 30 damage plus 20 more damage.\'}, {\'name\': \'Energy Splash\', \'cost\': [\'Water\', \'Water\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 5, \'damage\': \'70\', \'text\': \'Move 2 Water Energy cards attached to Politoed to 1 or 2 of your Benched Pokémon. (You may put both on the same Pokémon or 1 each on 2 different Pokémon.) If you have no Benched Pokémon, ignore this effect.\'}]', 'Skyridge', '2', 'Poliwhirl', '', '', 'Second', '110', 'https://images.pokemoncard.io/images/ecard3/ecard3-H23.png', 'unlimited: Legal', '', 'Politoed', '186', 'WOTC', 'Rare Holo', '', '05/12/2003', '', 'Colorless, Colorless', '', 'E-Card', 'H23', 'Stage 2', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('ecard3-H24', '[{\'name\': \'Strange Spiral\', \'text\': \"Once during your turn (before your attack), if Poliwrath is your Active Pokémon, you may discard a basic Energy card attached to Poliwrath. If you do, the Defending Pokémon is now Confused. This power can\'t be used if Poliwrath is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Naoyo Kimura', '[{\'name\': \'Spiral Punch\', \'cost\': [\'Fighting\', \'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40+\', \'text\': \'Flip a coin until you get tails. This attack does 40 damage plus 20 more damage for each heads.\'}]', 'Skyridge', '2', 'Poliwhirl', '', '', 'Second', '110', 'https://images.pokemoncard.io/images/ecard3/ecard3-H24.png', 'unlimited: Legal', '', 'Poliwrath', '62', 'WOTC', 'Rare Holo', '', '05/12/2003', '', 'Colorless, Colorless', '', 'E-Card', 'H24', 'Stage 2', 'Pokémon', 'Fighting', 'type: Psychic, value: ×2'),
('ecard3-H25', '', '', 'Yuka Morii', '[{\'name\': \'Zzzap\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'\', \'text\': \"This attack does 20 damage to each Pokémon with a Poké-Body or Poké-Power (yours and your opponent\'s). (Don\'t apply Weakness or Resistance.)\"}, {\'name\': \'Lightning Storm\', \'cost\': [\'Lightning\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50\', \'text\': \'Flip a coin. If tails, put 2 damage counters on Raichu.\'}]', 'Skyridge', '1', 'Pikachu', '', '', 'Second', '80', 'https://images.pokemoncard.io/images/ecard3/ecard3-H25.png', 'unlimited: Legal', '', 'Raichu', '26', 'WOTC', 'Rare Holo', '', '05/12/2003', '', 'Colorless', '', 'E-Card', 'H25', 'Stage 1', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
('ecard3-H26', '[{\'name\': \'Pure Body\', \'text\': \'To attach a Lightning Energy card from your hand to Raikou, you must discard an Energy card attached to Raikou. (Attach the Lightning Energy, and then discard an Energy card from Raikou.)\', \'type\': \'Poké-Body\'}]', '', 'Mitsuhiro Arita', '[{\'name\': \'Lightning Sphere\', \'cost\': [\'Lightning\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40+\', \'text\': \'You may flip a coin. If heads, discard all Lightning Energy cards attached to Raikou. This attack does 40 damage plus 20 more damage for each Energy card discarded in this way.\'}]', 'Skyridge', '1', '', '', '', 'Second', '70', 'https://images.pokemoncard.io/images/ecard3/ecard3-H26.png', 'unlimited: Legal', '', 'Raikou', '243', 'WOTC', 'Rare Holo', '', '05/12/2003', '', 'Colorless', '', 'E-Card', 'H26', 'Basic', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
('ecard3-H27', '', '', 'Mitsuhiro Arita', '[{\'name\': \'Stomp\', \'cost\': [\'Fighting\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'30+\', \'text\': \'Flip a coin. If heads, this attack does 30 damage plus 20 more damage.\'}, {\'name\': \'Giant Tail\', \'cost\': [\'Fighting\', \'Fighting\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 5, \'damage\': \'100\', \'text\': \'Flip a coin. If tails, this attack does nothing.\'}]', 'Skyridge', '2', 'Rhyhorn', 'Rhyperior', '', 'Second', '90', 'https://images.pokemoncard.io/images/ecard3/ecard3-H27.png', 'unlimited: Legal', '', 'Rhydon', '112', 'WOTC', 'Rare Holo', '', '05/12/2003', 'type: Lightning, value: -30', 'Colorless, Colorless', '', 'E-Card', 'H27', 'Stage 1', 'Pokémon', 'Fighting', 'type: Grass, value: ×2'),
('ecard3-H28', '', '', 'Hajime Kusajima', '[{\'name\': \'Energy Burst\', \'cost\': [\'Psychic\'], \'convertedEnergyCost\': 1, \'damage\': \'10×\', \'text\': \'Flip a coin. If heads, this attack does 10 damage times the number of Energy attached to Starmie and the Defending Pokémon.\'}, {\'name\': \'Star Back\', \'cost\': [\'Psychic\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40\', \'text\': \'Attach a basic Energy card from your discard pile to 1 of your Pokémon.\'}]', 'Skyridge', '1', 'Staryu', '', '', 'Second', '80', 'https://images.pokemoncard.io/images/ecard3/ecard3-H28.png', 'unlimited: Legal', '', 'Starmie', '121', 'WOTC', 'Rare Holo', '', '05/12/2003', '', 'Colorless', '', 'E-Card', 'H28', 'Stage 1', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2'),
('ecard3-H29', '[{\'name\': \'Rare Metal\', \'text\': \'All basic Energy cards attached to Steelix provide Metal Energy instead of their usual types.\', \'type\': \'Poké-Body\'}]', '', 'Hikaru Koike', '[{\'name\': \'Squeeze\', \'cost\': [\'Metal\', \'Metal\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'20+\', \'text\': \'Flip a coin. If heads, this attack does 20 damage plus 10 more damage and the Defending Pokémon is now Paralyzed.\'}, {\'name\': \'Metal Tail\', \'cost\': [\'Metal\', \'Metal\', \'Metal\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'40\', \'text\': \'Before doing damage, you may flip a coin. If heads, this attack does 80 damage. If tails, this attack does nothing.\'}]', 'Skyridge', '4', 'Onix', '', '', 'Second', '100', 'https://images.pokemoncard.io/images/ecard3/ecard3-H29.png', 'unlimited: Legal', '', 'Steelix', '208', 'WOTC', 'Rare Holo', '', '05/12/2003', 'type: Grass, value: -30', 'Colorless, Colorless, Colorless, Colorless', '', 'E-Card', 'H29', 'Stage 1', 'Pokémon', 'Metal', 'type: Fire, value: ×2'),
('ecard3-H3', '[{\'name\': \'Water Immunity\', \'text\': \"You can\'t attach Water Energy cards from your hand to Articuno.\", \'type\': \'Poké-Body\'}]', '', 'Hajime Kusajima', '[{\'name\': \'Freeze Solid\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'If there are any Water Energy cards in your discard pile, flip a coin. If heads, attach 1 of them to Articuno.\'}, {\'name\': \'Ice Cyclone\', \'cost\': [\'Water\', \'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'50\', \'text\': \"Flip a coin. If heads, this attack does 10 damage to each of your opponent\'s Benched Pokémon. If tails, this attack does 10 damage to each of your Pokémon in play. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'Skyridge', '2', '', '', '', 'Second', '80', 'https://images.pokemoncard.io/images/ecard3/ecard3-H3.png', 'unlimited: Legal', '', 'Articuno', '144', 'WOTC', 'Rare Holo', '', '05/12/2003', 'type: Fighting, value: -30', 'Colorless, Colorless', '', 'E-Card', 'H3', 'Basic', 'Pokémon', 'Water', 'type: Metal, value: ×2'),
('ecard3-H30', '[{\'name\': \'Dark Gaze\', \'text\': \"As long as Umbreon is your Active Pokémon, Benched Pokémon (yours and your opponent\'s) can\'t use Poké-Powers.\", \'type\': \'Poké-Body\'}]', '', 'Atsuko Nishida', '[{\'name\': \'Sharp Claws\', \'cost\': [\'Darkness\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'10+\', \'text\': \'Flip a coin. If heads, this attack does 10 damage plus 30 more damage.\'}]', 'Skyridge', '1', 'Eevee', '', '', 'Second', '70', 'https://images.pokemoncard.io/images/ecard3/ecard3-H30.png', 'unlimited: Legal', '', 'Umbreon', '197', 'WOTC', 'Rare Holo', '', '05/12/2003', 'type: Psychic, value: -30', 'Colorless', '', 'E-Card', 'H30', 'Stage 1', 'Pokémon', 'Darkness', 'type: Fighting, value: ×2'),
('ecard3-H31', '[{\'name\': \'Self-healing\', \'text\': \'Whenever you attach a Water Energy card from your hand to Vaporeon, remove all Special Conditions affecting Vaporeon.\', \'type\': \'Poké-Body\'}]', '', 'Naoyo Kimura', '[{\'name\': \'Hypnosplash\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'10\', \'text\': \'The Defending Pokémon is now Asleep.\'}, {\'name\': \'Aqua Trick\', \'cost\': [\'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40\', \'text\': \"If the Defending Pokémon has any Energy cards attached to it, flip a coin. If heads, choose 1 of those Energy cards and move it to 1 of your opponent\'s Benched Pokémon. If your opponent has no Benched Pokémon, ignore this effect.\"}]', 'Skyridge', '1', 'Eevee', '', '', 'Second', '70', 'https://images.pokemoncard.io/images/ecard3/ecard3-H31.png', 'unlimited: Legal', '', 'Vaporeon', '134', 'WOTC', 'Rare Holo', '', '05/12/2003', '', 'Colorless', '', 'E-Card', 'H31', 'Stage 1', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('ecard3-H32', '[{\'name\': \'Synchronicity\', \'text\': \'You may attach any Technical Machine to Xatu.\', \'type\': \'Poké-Body\'}]', '', 'Atsuko Nishida', '[{\'name\': \'Warp Hole\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'30\', \'text\': \'Flip a coin. If heads, choose a card from your discard pile and put it on top of your deck.\'}]', 'Skyridge', '1', 'Natu', '', '', 'Second', '80', 'https://images.pokemoncard.io/images/ecard3/ecard3-H32.png', 'unlimited: Legal', '', 'Xatu', '178', 'WOTC', 'Rare Holo', '', '05/12/2003', '', 'Colorless', '', 'E-Card', 'H32', 'Stage 1', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2'),
('ecard3-H4', '[{\'name\': \'Venom Spray\', \'text\': \'When you play Beedrill from your hand to evolve your Active Pokémon, the Defending Pokémon is now Paralyzed and Poisoned.\', \'type\': \'Poké-Power\'}]', '', 'Hikaru Koike', '[{\'name\': \'Needle Rush\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'10+\', \'text\': \'Flip 4 coins. If you get 1 heads, this attack does 10 damage plus 10 more damage. If you get 2 heads, this attack does 10 damage plus 20 more damage. If you get 3 heads, this attack does 10 damage plus 50 more damage. If you get 4 heads, this attack does 10 damage plus 90 more damage.\'}]', 'Skyridge', '', 'Kakuna', '', '', 'Second', '80', 'https://images.pokemoncard.io/images/ecard3/ecard3-H4.png', 'unlimited: Legal', '', 'Beedrill', '15', 'WOTC', 'Rare Holo', '', '05/12/2003', '', '', '', 'E-Card', 'H4', 'Stage 2', 'Pokémon', 'Grass', 'type: Fire, value: ×2');
INSERT INTO `cards` (`id`, `abilities`, `ancient_trait`, `artist`, `attacks`, `card_set`, `converted`, `evolves_from`, `evolves_to`, `flavor_text`, `generation`, `hp`, `img`, `legalities`, `level`, `name`, `national_pokedex_numbers`, `publisher`, `rarity`, `regulation_mark`, `release_date`, `resistances`, `retreat_cost`, `rules`, `series`, `set_num`, `subtypes`, `supertype`, `types`, `weakness`) VALUES
('ecard3-H5', '[{\'name\': \'Carry Off\', \'text\': \"Once during your turn (before your attack), you may flip a coin. If heads, look at your opponent\'s hand. If your opponent has any Baby Pokémon, Basic Pokémon, or Evolution cards there, choose 1 of them. Your opponent shuffles that card into his or her deck. This power can\'t be used if Crobat is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Kimiya Masago', '[{\'name\': \'Double Cross\', \'cost\': [\'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40×\', \'text\': \'Flip 2 coins. This attack does 40 damage times the number of heads. If both of them are tails, the Defending Pokémon is now Confused and Poisoned.\'}]', 'Skyridge', '', 'Golbat', '', '', 'Second', '90', 'https://images.pokemoncard.io/images/ecard3/ecard3-H5.png', 'unlimited: Legal', '', 'Crobat', '169', 'WOTC', 'Rare Holo', '', '05/12/2003', '', '', '', 'E-Card', 'H5', 'Stage 2', 'Pokémon', 'Grass', 'type: Psychic, value: ×2'),
('ecard3-H6', '', '', 'Kouki Saitou', '[{\'name\': \'Freeze Lock\', \'cost\': [\'Water\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \"Flip a coin. If heads, your opponent can\'t attach Energy cards from his or her hand to his or her Active Pokémon during his or her next turn.\"}, {\'name\': \'Crushing Ice\', \'cost\': [\'Water\', \'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'40+\', \'text\': \"This attack does 40 damage plus 10 more damage for each Colorless Energy in the Defending Pokémon\'s Retreat Cost. Damage is calculated using the Defending Pokémon\'s Retreat Cost after applying effects to the Retreat Cost.\"}]', 'Skyridge', '2', 'Seel', '', '', 'Second', '80', 'https://images.pokemoncard.io/images/ecard3/ecard3-H6.png', 'unlimited: Legal', '', 'Dewgong', '87', 'WOTC', 'Rare Holo', '', '05/12/2003', '', 'Colorless, Colorless', '', 'E-Card', 'H6', 'Stage 1', 'Pokémon', 'Water', 'type: Metal, value: ×2'),
('ecard3-H7', '[{\'name\': \'Self-healing\', \'text\': \'Whenever you attach a Fire Energy card from your hand to Flareon, remove all Special Conditions affecting Flareon.\', \'type\': \'Poké-Body\'}]', '', 'Kyoko Umemoto', '[{\'name\': \'Singe\', \'cost\': [\'Fire\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'The Defending Pokémon is now Burned.\'}, {\'name\': \'Burn Booster\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40+\', \'text\': \'Discard an Energy card attached to Flareon in order to use this attack. If the discarded card is a Fire Energy card, this attack does 40 damage plus 10 more damage.\'}]', 'Skyridge', '1', 'Eevee', '', '', 'Second', '70', 'https://images.pokemoncard.io/images/ecard3/ecard3-H7.png', 'unlimited: Legal', '', 'Flareon', '136', 'WOTC', 'Rare Holo', '', '05/12/2003', '', 'Colorless', '', 'E-Card', 'H7', 'Stage 1', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('ecard3-H8', '', '', 'Midori Harada', '[{\'name\': \'Spinning Blow\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20×\', \'text\': \'Flip 2 coins. This attack does 20 damage times the number of heads. If both coins are heads, switch Forretress with 1 of your Benched Pokémon.\'}, {\'name\': \'Scatterbomb\', \'cost\': [\'Metal\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40\', \'text\': \"Flip 2 coins. For each heads, do 10 damage to each of your opponent\'s Benched Pokémon. For each tails, do 10 damage to each of your own Benched Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'Skyridge', '2', 'Pineco', '', '', 'Second', '70', 'https://images.pokemoncard.io/images/ecard3/ecard3-H8.png', 'unlimited: Legal', '', 'Forretress', '205', 'WOTC', 'Rare Holo', '', '05/12/2003', 'type: Grass, value: -30', 'Colorless, Colorless', '', 'E-Card', 'H8', 'Stage 1', 'Pokémon', 'Metal', 'type: Fire, value: ×2'),
('ecard3-H9', '[{\'name\': \'Manipulate\', \'text\': \'When you play Gengar from your hand to evolve your Active Pokémon, you may put a Basic Pokémon (excluding Baby Pokémon) from your discard pile onto your Bench. Then, flip 3 coins. For each heads, choose a basic Energy card from your discard pile and attach it to that Pokémon.\', \'type\': \'Poké-Power\'}]', '', 'Kyoko Umemoto', '[{\'name\': \'Hydrokinesis\', \'cost\': [\'Psychic\', \'Psychic\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'40\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Burned. If tails, the Defending Pokémon is now Confused.\'}]', 'Skyridge', '2', 'Haunter', '', '', 'Second', '100', 'https://images.pokemoncard.io/images/ecard3/ecard3-H9.png', 'unlimited: Legal', '', 'Gengar', '94', 'WOTC', 'Rare Holo', '', '05/12/2003', 'type: Fighting, value: -30', 'Colorless, Colorless', '', 'E-Card', 'H9', 'Stage 2', 'Pokémon', 'Psychic', 'type: Darkness, value: ×2'),
('ex1-1', '', '', 'Mitsuhiro Arita', '[{\'name\': \'Retaliate\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10×\', \'text\': \'Flip a coin. If heads, this attack does 10 damage times the number of damage counters on Aggron.\'}, {\'name\': \'Mega Punch\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40\', \'text\': \'\'}, {\'name\': \'Double Lariat\', \'cost\': [\'Metal\', \'Metal\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 5, \'damage\': \'70×\', \'text\': \'Flip 2 coins. This attack does 70 damage times the number of heads.\'}]', 'Ruby & Sapphire', '4', 'Lairon', '', '', 'Third', '110', 'https://images.pokemoncard.io/images/ex1/ex1-1.png', 'unlimited: Legal', '', 'Aggron', '306', 'TPCI', 'Rare Holo', '', '07/01/2003', 'type: Grass, value: -30', 'Colorless, Colorless, Colorless, Colorless', '', 'EX', '1', 'Stage 2', 'Pokémon', 'Metal', 'type: Fire, value: ×2'),
('ex1-10', '[{\'name\': \'Intimidating Fang\', \'text\': \"As long as Mightyena is your Active Pokémon, any damage done to your Pokémon by an opponent\'s attack is reduced by 10 (before applying Weakness and Resistance).\", \'type\': \'Poké-Body\'}]', '', 'Atsuko Nishida', '[{\'name\': \'Shakedown\', \'cost\': [\'Darkness\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40\', \'text\': \"Flip a coin. If heads, choose 1 card from your opponent\'s hand without looking and discard it.\"}]', 'Ruby & Sapphire', '1', 'Poochyena', '', '', 'Third', '70', 'https://images.pokemoncard.io/images/ex1/ex1-10.png', 'unlimited: Legal', '', 'Mightyena', '262', 'TPCI', 'Rare Holo', '', '07/01/2003', 'type: Psychic, value: -30', 'Colorless', '', 'EX', '10', 'Stage 1', 'Pokémon', 'Darkness', 'type: Fighting, value: ×2'),
('ex1-100', '', '', 'Hikaru Koike', '[{\'name\': \'Smokescreen\', \'cost\': [\'Fire\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \"If the Defending Pokémon tries to attack during your opponent\'s next turn, your opponent flips a coin. If tails, that attack does nothing.\"}, {\'name\': \'Super Singe\', \'cost\': [\'Fire\', \'Fire\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40\', \'text\': \'The Defending Pokémon is now Burned.\'}]', 'Ruby & Sapphire', '2', '', 'Magmortar', '', 'Third', '90', 'https://images.pokemoncard.io/images/ex1/ex1-100.png', 'unlimited: Legal', '', 'Magmar ex', '126', 'TPCI', 'Rare Holo EX', '', '07/01/2003', '', 'Colorless, Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '100', 'Basic, EX', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
