('ex12-4', '[{\'name\': \'Reactive Shift\', \'text\': \"Once during your turn (before your attack), you may move a React Energy card attached to 1 of your Pokémon to another of your Pokémon. This power can\'t be used if Delcatty is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Naoyo Kimura', '[{\'name\': \'Energy Link\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'20\', \'text\': \'Search your discard pile for an Energy card and attach it to Delcatty.\'}, {\'name\': \'Tail Whap\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40\', \'text\': \'\'}]', 'Legend Maker', '1', 'Skitty', '', '', 'Third', '80', 'https://images.pokemoncard.io/images/ex12/ex12-4.png', 'unlimited: Legal', '', 'Delcatty', '301', 'TPCI', 'Rare Holo', '', '02/01/2006', '', 'Colorless', '', 'EX', '4', 'Stage 1', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('ex12-40', '[{\'name\': \'Deep Sleep\', \'text\': \'As long as Misdreavus is your Active Pokémon, each player flips 2 coins for his or her Pokémon that is Asleep between turns. If either coin is tails, that Pokémon is still Asleep.\', \'type\': \'Poké-Body\'}]', '', 'Yukiko Baba', '[{\'name\': \'Return Trance\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Return an Energy card attached to Misdreavus to your hand. The Defending Pokémon is now Asleep.\'}, {\'name\': \'Dream Eater\', \'cost\': [\'Psychic\'], \'convertedEnergyCost\': 1, \'damage\': \'30\', \'text\': \'If the Defending Pokémon is not Asleep, this attack does nothing.\'}]', 'Legend Maker', '1', '', 'Mismagius', '', 'Third', '50', 'https://images.pokemoncard.io/images/ex12/ex12-40.png', 'unlimited: Legal', '', 'Misdreavus', '200', 'TPCI', 'Uncommon', '', '02/01/2006', 'type: Fighting, value: -30', 'Colorless', '', 'EX', '40', 'Basic', 'Pokémon', 'Psychic', 'type: Darkness, value: ×2'),
