('ex13-15', '', '', 'Masakazu Fukuda', '[{\'name\': \'Zzzap\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Does 20 damage to each Pokémon that has any Poké-Powers or Poké-Bodies (both yours and your opponent\'s). Don\'t apply Weakness or Resistance.\"}, {\'name\': \'Metallic Thunder\', \'cost\': [\'Metal\', \'Metal\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50\', \'text\': \"You may discard 2 Metal Energy attached to Raichu. If you do, this attack\'s base damage is 90 instead of 50.\"}]', 'Holon Phantoms', '', 'Pikachu', '', '', 'Third', '70', 'https://images.pokemoncard.io/images/ex13/ex13-15.png', 'unlimited: Legal', '', 'Raichu δ', '26', 'TPCI', 'Rare Holo', '', '05/01/2006', '', '', '', 'EX', '15', 'Stage 1', 'Pokémon', 'Metal', 'type: Fighting, value: ×2'),
('ex13-16', '[{\'name\': \'Hydro Barrier\', \'text\': \'As long as Rayquaza has any Holon Energy cards attached to it, each of your Water Pokémon has no Weakness.\', \'type\': \'Poké-Body\'}]', '', 'Mitsuhiro Arita', '[{\'name\': \'Delta Search\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Search your deck for a Holon Energy card and attach it to Rayquaza. Shuffle your deck afterward.\'}, {\'name\': \'Ozone Flare\', \'cost\': [\'Water\', \'Metal\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'60\', \'text\': \'\'}]', 'Holon Phantoms', '2', '', '', '', 'Third', '80', 'https://images.pokemoncard.io/images/ex13/ex13-16.png', 'unlimited: Legal', '', 'Rayquaza δ', '384', 'TPCI', 'Rare Holo', '', '05/01/2006', 'type: Water, value: -30, type: Fighting, value: -30', 'Colorless, Colorless', '[\'This Pokémon is both Water Metal type.\']', 'EX', '16', 'Basic', 'Pokémon', 'Water, Metal', 'type: Colorless, value: ×2'),
('ex13-17', '[{\'name\': \'Poison Pollen\', \'text\': \"Once during your turn (before your attack), you may flip a coin. If heads, choose 1 of the Defending Pokémon. That Pokémon is now Poisoned. This power can\'t be used if Vileplume is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Mitsuhiro Arita', '[{\'name\': \'Poltergeist\', \'cost\': [\'Psychic\', \'Metal\'], \'convertedEnergyCost\': 2, \'damage\': \'30+\', \'text\': \"Look at your opponent\'s hand. This attack does 30 damage plus 10 more damage for each Trainer card in your opponent\'s hand.\"}]', 'Holon Phantoms', '1', 'Gloom', '', '', 'Third', '90', 'https://images.pokemoncard.io/images/ex13/ex13-17.png', 'unlimited: Legal', '', 'Vileplume δ', '45', 'TPCI', 'Rare Holo', '', '05/01/2006', '', 'Colorless', '[\'This Pokémon is both Psychic Metal type.\']', 'EX', '17', 'Stage 2', 'Pokémon', 'Psychic, Metal', 'type: Psychic, value: ×2'),
('ex13-18', '', '', 'Masakazu Fukuda', '[{\'name\': \'Foresight\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Look at the top 5 cards of either player\'s deck and put them back on top of that player\'s deck in any order.\"}, {\'name\': \'Overrun\', \'cost\': [\'Darkness\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'10\', \'text\': \"Choose 1 of your opponent\'s Benched Pokémon. This attack does 20 damage to that Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'Holon Phantoms', '1', '', '', '', 'Third', '70', 'https://images.pokemoncard.io/images/ex13/ex13-18.png', 'unlimited: Legal', '', 'Absol', '359', 'TPCI', 'Rare', '', '05/01/2006', 'type: Psychic, value: -30', 'Colorless', '', 'EX', '18', 'Basic', 'Pokémon', 'Darkness', 'type: Fighting, value: ×2'),
('ex13-19', '[{\'name\': \'Fellowship\', \'text\': \'Bellossom can use the attacks of all Oddish, Gloom, Vileplume, Vileplume ex, or other Bellossom you have in play as its own. (You still need the necessary Energy to use each attack.)\', \'type\': \'Poké-Body\'}]', '', 'Kagemaru Himeno', '[{\'name\': \'Aqua Flower\', \'cost\': [\'Water\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'40\', \'text\': \"During your opponent\'s next turn, Bellossom has no Weakness.\"}]', 'Holon Phantoms', '1', 'Gloom', '', '', 'Third', '100', 'https://images.pokemoncard.io/images/ex13/ex13-19.png', 'unlimited: Legal', '', 'Bellossom δ', '182', 'TPCI', 'Rare', '', '05/01/2006', 'type: Water, value: -30', 'Colorless', '', 'EX', '19', 'Stage 2', 'Pokémon', 'Water', 'type: Fire, value: ×2'),
('ex13-2', '', '', 'Kouki Saitou', '[{\'name\': \'Harsh Fluid\', \'cost\': [\'Darkness\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \"Put 5 damage counters on the Defending Pokémon at the end of your opponent\'s next turn.\"}, {\'name\': \'Poison Tentacles\', \'cost\': [\'Metal\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50\', \'text\': \'The Defending Pokémon is now Poisoned.\'}]', 'Holon Phantoms', '2', 'Lileep', '', '', 'Third', '100', 'https://images.pokemoncard.io/images/ex13/ex13-2.png', 'unlimited: Legal', '', 'Cradily δ', '346', 'TPCI', 'Rare Holo', '', '05/01/2006', '', 'Colorless, Colorless', '[\'This Pokémon is both Darkness Metal type.\']', 'EX', '2', 'Stage 2', 'Pokémon', 'Darkness, Metal', 'type: Fire, value: ×2'),
