('ex14-65', '', '', 'Sachiko Adachi', '[{\'name\': \'Claw\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'20\', \'text\': \'Flip a coin. If tails, this attack does nothing.\'}]', 'Crystal Guardians', '1', '', 'Combusken', '', 'Third', '50', 'https://images.pokemoncard.io/images/ex14/ex14-65.png', 'unlimited: Legal', '', 'Torchic', '255', 'TPCI', 'Common', '', '08/01/2006', '', 'Colorless', '', 'EX', '65', 'Basic', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('ex14-66', '', '', 'Sumiyoshi Kizuki', '[{\'name\': \'Sand Attack\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \"If the Defending Pokémon tries to attack during your opponent\'s next turn, your opponent flips a coin. If tails, that attack does nothing.\"}]', 'Crystal Guardians', '1', '', 'Combusken', '', 'Third', '40', 'https://images.pokemoncard.io/images/ex14/ex14-66.png', 'unlimited: Legal', '', 'Torchic', '255', 'TPCI', 'Common', '', '08/01/2006', '', 'Colorless', '', 'EX', '66', 'Basic', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('ex14-67', '', '', 'Sachiko Adachi', '[{\'name\': \'Paralyzing Gaze\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Paralyzed.\'}, {\'name\': \'Scratch\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'\'}]', 'Crystal Guardians', '1', '', 'Grovyle', '', 'Third', '40', 'https://images.pokemoncard.io/images/ex14/ex14-67.png', 'unlimited: Legal', '', 'Treecko', '252', 'TPCI', 'Common', '', '08/01/2006', 'type: Water, value: -30', 'Colorless', '', 'EX', '67', 'Basic', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('ex14-68', '', '', 'Masakazu Fukuda', '[{\'name\': \'Pound\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'\'}, {\'name\': \'Shining Claws\', \'cost\': [\'Psychic\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Confused.\'}]', 'Crystal Guardians', '1', '', 'Grovyle', '', 'Third', '40', 'https://images.pokemoncard.io/images/ex14/ex14-68.png', 'unlimited: Legal', '', 'Treecko δ', '252', 'TPCI', 'Common', '', '08/01/2006', 'type: Water, value: -30', 'Colorless', '', 'EX', '68', 'Basic', 'Pokémon', 'Psychic', 'type: Fire, value: ×2');
INSERT INTO `cards` (`id`, `abilities`, `ancient_trait`, `artist`, `attacks`, `card_set`, `converted`, `evolves_from`, `evolves_to`, `flavor_text`, `generation`, `hp`, `img`, `legalities`, `level`, `name`, `national_pokedex_numbers`, `publisher`, `rarity`, `regulation_mark`, `release_date`, `resistances`, `retreat_cost`, `rules`, `series`, `set_num`, `subtypes`, `supertype`, `types`, `weakness`) VALUES
('ex14-69', '', '', 'Atsuko Nishida', '[{\'name\': \'Supersonic\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Confused.\'}, {\'name\': \'Hyper Voice\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'30\', \'text\': \'\'}]', 'Crystal Guardians', '1', '', 'Loudred', '', 'Third', '50', 'https://images.pokemoncard.io/images/ex14/ex14-69.png', 'unlimited: Legal', '', 'Whismur', '293', 'TPCI', 'Common', '', '08/01/2006', '', 'Colorless', '', 'EX', '69', 'Basic', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('ex14-7', '', '', 'Kyoko Umemoto', '[{\'name\': \'Even Game\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Count the number of your opponent\'s Pokémon. Search your deck for up to that number of Basic Pokémon and put them onto your Bench. Shuffle your deck afterward.\"}, {\'name\': \'Stadium Play\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \"If you have a Stadium card in play, remove 1 damage counter from each of your Pokémon. If your opponent has a Stadium card in play, this attack does 10 damage to each of your opponent\'s Benched Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'Crystal Guardians', '1', '', '', '', 'Third', '60', 'https://images.pokemoncard.io/images/ex14/ex14-7.png', 'unlimited: Legal', '', 'Luvdisc', '370', 'TPCI', 'Rare Holo', '', '08/01/2006', '', 'Colorless', '', 'EX', '7', 'Basic', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('ex14-70', '', '', 'Midori Harada', '[{\'name\': \'Wing Attack\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'\'}]', 'Crystal Guardians', '1', '', 'Pelipper', '', 'Third', '40', 'https://images.pokemoncard.io/images/ex14/ex14-70.png', 'unlimited: Legal', '', 'Wingull', '278', 'TPCI', 'Common', '', '08/01/2006', 'type: Fighting, value: -30', 'Colorless', '', 'EX', '70', 'Basic', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('ex14-71', '', '', 'Ken Sugimori', '', 'Crystal Guardians', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex14/ex14-71.png', 'unlimited: Legal, expanded: Legal', '', 'Bills Maintenance', '', 'TPCI', 'Uncommon', '', '08/01/2006', '', '', '[\'You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.\', \'If you have any cards in your hand, shuffle 1 of them into your deck, then draw 3 cards.\']', 'EX', '71', 'Supporter', 'Trainer', '', ''),
('ex14-72', '', '', 'Kouki Saitou', '', 'Crystal Guardians', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex14/ex14-72.png', 'unlimited: Legal', '', 'Castaway', '', 'TPCI', 'Uncommon', '', '08/01/2006', '', '', '[\'You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.\', \'Search your deck for a Supporter card, a Pokémon Tool card, and a basic Energy card. Show them to your opponent, and put them into your hand. Shuffle your deck afterward.\']', 'EX', '72', 'Supporter', 'Trainer', '', ''),
('ex14-73', '', '', 'Ken Sugimori', '', 'Crystal Guardians', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex14/ex14-73.png', 'unlimited: Legal', '', 'Celios Network', '', 'TPCI', 'Uncommon', '', '08/01/2006', '', '', '[\'You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.\', \'Search your deck for a Basic Pokémon or Evolution card (excluding Pokémon-ex), show it to your opponent, and put it into your hand. Shuffle your deck afterward.\']', 'EX', '73', 'Supporter', 'Trainer', '', ''),
('ex14-74', '', '', 'Takumi Akabane', '', 'Crystal Guardians', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex14/ex14-74.png', 'unlimited: Legal', '', 'Cessation Crystal', '', 'TPCI', 'Uncommon', '', '08/01/2006', '', '', '[\"Attach Cessation Crystal to 1 of your Pokémon (excluding Pokémon-ex) that doesn\'t already have a Pokémon Tool attached to it. If the Pokémon Cessation Crystal is attached to is a Pokémon-ex, discard this card.\", \"As long as Cessation Crystal is attached to an Active Pokémon, each player\'s Pokémon (both yours and your opponent\'s) can\'t use any Poké-Powers or Poké-Bodies.\"]', 'EX', '74', 'Pokémon Tool', 'Trainer', '', ''),
('ex14-75', '', '', 'Shizurow', '', 'Crystal Guardians', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex14/ex14-75.png', 'unlimited: Legal', '', 'Crystal Beach', '', 'TPCI', 'Uncommon', '', '08/01/2006', '', '', '[\"This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can\'t play this card.\", \"Each Special Energy card that provides 2 or more Energy (both yours and your opponent\'s) now provides only 1 Colorless Energy. This isn\'t affected by any Poké-Powers or Poké-Bodies.\"]', 'EX', '75', 'Stadium', 'Trainer', '', ''),
('ex14-76', '', '', 'Takumi Akabane', '', 'Crystal Guardians', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex14/ex14-76.png', 'unlimited: Legal', '', 'Crystal Shard', '', 'TPCI', 'Uncommon', '', '08/01/2006', '', '', '[\"Attach Crystal Shard to 1 of your Pokémon that doesn\'t already have a Pokémon Tool attached to it. If that Pokémon is Knocked Out, discard this card.\", \"As long as Crystal Shard is attached to a Pokémon, that Pokémon\'s type is Colorless. If that Pokémon attacks, discard this card at the end of the turn.\"]', 'EX', '76', 'Pokémon Tool', 'Trainer', '', ''),
('ex14-77', '', '', 'Ryo Ueda', '', 'Crystal Guardians', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex14/ex14-77.png', 'unlimited: Legal', '', 'Double Full Heal', '', 'TPCI', 'Uncommon', '', '08/01/2006', '', '', '[\'Remove all Special Conditions from each of your Active Pokémon.\']', 'EX', '77', 'Item', 'Trainer', '', ''),
('ex14-78', '', '', 'Big Mama Tagawa', '', 'Crystal Guardians', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex14/ex14-78.png', 'unlimited: Legal', '', 'Dual Ball', '', 'TPCI', 'Uncommon', '', '08/01/2006', '', '', '[\'Flip 2 coins. For each heads, search your deck for a Basic Pokémon card, show it to your opponent, and put it into your hand. Shuffle your deck afterward.\']', 'EX', '78', 'Item', 'Trainer', '', ''),
('ex14-79', '', '', 'Ryo Ueda', '', 'Crystal Guardians', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex14/ex14-79.png', 'unlimited: Legal', '', 'Holon Circle', '', 'TPCI', 'Uncommon', '', '08/01/2006', '', '', '[\"This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can\'t play this card.\", \"Prevent all effects of an attack, including damage, done by either player\'s Active Pokémon. If an Active Pokémon uses an attack, that attack ends, and discard this card.\"]', 'EX', '79', 'Stadium', 'Trainer', '', ''),
('ex14-8', '', '', 'Hisao Nakamura', '[{\'name\': \'Kick Away\', \'cost\': [\'Lightning\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'Your opponent switches the Defending Pokémon with 1 of his or her Benched Pokémon, if any.\'}, {\'name\': \'Strong Current\', \'cost\': [\'Lightning\', \'Lightning\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50\', \'text\': \"If Manectric has a Pokémon Tool card attached to it, this attack does 20 damage to each of your opponent\'s Benched Pokémon-ex. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'Crystal Guardians', '1', 'Electrike', '', '', 'Third', '80', 'https://images.pokemoncard.io/images/ex14/ex14-8.png', 'unlimited: Legal', '', 'Manectric', '310', 'TPCI', 'Rare Holo', '', '08/01/2006', 'type: Metal, value: -30', 'Colorless', '', 'EX', '8', 'Stage 1', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
('ex14-80', '', '', 'Shizurow', '', 'Crystal Guardians', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex14/ex14-80.png', 'unlimited: Legal', '', 'Memory Berry', '', 'TPCI', 'Uncommon', '', '08/01/2006', '', '', '[\"Attach Memory Berry to 1 of your Pokémon that doesn\'t already have a Pokémon Tool attached to it. If that Pokémon is Knocked Out, discard this card.\", \"The Pokémon this card is attached to can use any attack from its Basic Pokémon or its Stage 1 Evolution card. (You still have to pay for that attack\'s Energy cost.) If that Pokémon attacks, discard this card at the end of the turn.\"]', 'EX', '80', 'Pokémon Tool', 'Trainer', '', ''),
('ex14-81', '', '', 'Takumi Akabane', '', 'Crystal Guardians', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex14/ex14-81.png', 'unlimited: Legal', '', 'Mysterious Shard', '', 'TPCI', 'Uncommon', '', '08/01/2006', '', '', '[\"Attach Mysterious Shard to 1 of your Pokémon (excluding Pokémon-ex) that doesn\'t already have a Pokémon Tool attached to it. If the Pokémon Mysterious Shard is attached to is a Pokémon-ex, discard this card.\", \"Prevent all effects of attacks, including damage, done to the Pokémon that Mysterious Shard is attached to by your opponent\'s Pokémon-ex. Discard this card at the end of your opponent\'s next turn.\"]', 'EX', '81', 'Pokémon Tool', 'Trainer', '', ''),
('ex14-82', '', '', 'Shin-ichi Yoshikawa', '', 'Crystal Guardians', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex14/ex14-82.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Poké Ball', '', 'TPCI', 'Uncommon', '', '08/01/2006', '', '', '[\'Flip a coin. If heads, search your deck for a Basic Pokémon or Evolution card, show it to your opponent, and put it into your hand. Shuffle your deck afterward.\']', 'EX', '82', 'Item', 'Trainer', '', ''),
('ex14-83', '', '', 'Katsura Tabata', '', 'Crystal Guardians', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex14/ex14-83.png', 'unlimited: Legal', '', 'PokéNav', '', 'TPCI', 'Uncommon', '', '08/01/2006', '', '', '[\'Look at the top 3 cards of your deck, and choose a Basic Pokémon, Evolution card, or Energy card. Show it to your opponent and put it into your hand. Put the 2 other cards back on top of your deck in any order.\']', 'EX', '83', 'Item', 'Trainer', '', ''),
('ex14-84', '', '', 'Keiji Kinebuchi', '', 'Crystal Guardians', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex14/ex14-84.png', 'unlimited: Legal', '', 'Warp Point', '', 'TPCI', 'Uncommon', '', '08/01/2006', '', '', '[\'Your opponent switches 1 of his or her Defending Pokémon with 1 of his or her Benched Pokémon, if any. You switch 1 of your Active Pokémon with 1 of your Benched Pokémon, if any.\']', 'EX', '84', 'Item', 'Trainer', '', ''),
('ex14-85', '', '', 'Ryo Ueda', '', 'Crystal Guardians', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex14/ex14-85.png', 'unlimited: Legal', '', 'Windstorm', '', 'TPCI', 'Uncommon', '', '08/01/2006', '', '', '[\"Choose up to 2 in any combination of Pokémon Tool cards and Stadium cards in play (both yours and your opponent\'s) and discard them.\"]', 'EX', '85', 'Item', 'Trainer', '', ''),
('ex14-86', '', '', 'Kai Ishikawa', '', 'Crystal Guardians', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex14/ex14-86.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Energy Search', '', 'TPCI', 'Common', '', '08/01/2006', '', '', '[\'Search your deck for a basic Energy card, show it to your opponent, and put it into your hand. Shuffle your deck afterward.\']', 'EX', '86', 'Item', 'Trainer', '', ''),
('ex14-87', '', '', 'Shin-ichi Yoshikawa', '', 'Crystal Guardians', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex14/ex14-87.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Potion', '', 'TPCI', 'Common', '', '08/01/2006', '', '', '[\'Remove 2 damage counters from 1 of your Pokémon (remove 1 damage counter if that Pokémon has only 1).\']', 'EX', '87', 'Item', 'Trainer', '', ''),
('ex14-88', '', '', 'Takumi Akabane', '', 'Crystal Guardians', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex14/ex14-88.png', 'unlimited: Legal', '', 'Double Rainbow Energy', '', 'TPCI', 'Rare', '', '08/01/2006', '', '', '[\"Double Rainbow Energy can be attached only to an Evolved Pokémon (excluding Pokémon-ex). While in play, Double Rainbow Energy provides every type of Energy but provides 2 Energy at a time. (Has no effect other than providing Energy.) Damage done to your opponent\'s Pokémon by the Pokémon Double Rainbow Energy is attached to is reduced by 10 (before applying Weakness and Resistance). When the Pokémon Double Rainbow Energy is attached to is no longer an Evolved Pokémon, discard Double Rainbow Energy.\"]', 'EX', '88', 'Special', 'Energy', '', ''),
('ex14-89', '[{\'name\': \'Intimidating Armor\', \'text\': \"As long as Aggron ex is your Active Pokémon, your opponent\'s Basic Pokémon can\'t attack or use any Poké-Powers or Poké-Bodies.\", \'type\': \'Poké-Body\'}]', '', 'Ryo Ueda', '[{\'name\': \'Split Bomb\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'\', \'text\': \"Choose 2 of your opponent\'s Pokémon. This attack doe 30 damage to each of them. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}, {\'name\': \'Mega Burn\', \'cost\': [\'Metal\', \'Metal\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'100\', \'text\': \"During your next turn, Aggron ex can\'t use Mega Burn.\"}]', 'Crystal Guardians', '4', 'Lairon', '', '', 'Third', '150', 'https://images.pokemoncard.io/images/ex14/ex14-89.png', 'unlimited: Legal', '', 'Aggron ex', '306', 'TPCI', 'Rare Holo EX', '', '08/01/2006', 'type: Grass, value: -30', 'Colorless, Colorless, Colorless, Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '89', 'Stage 2, EX', 'Pokémon', 'Metal', 'type: Fire, value: ×2'),
('ex14-9', '', '', 'Kagemaru Himeno', '[{\'name\': \'Mining\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Search your deck for a Trainer card, show it to your opponent, and put it into your hand. If that card is a Pokémon Tool card, you may attach it to 1 of your Pokémon instead. Shuffle your deck afterward.\'}, {\'name\': \'Bite Off\', \'cost\': [\'Metal\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20+\', \'text\': \'If the Defending Pokémon is Pokémon-ex, this attack does 20 damage plus 30 more damage.\'}]', 'Crystal Guardians', '1', '', '', '', 'Third', '60', 'https://images.pokemoncard.io/images/ex14/ex14-9.png', 'unlimited: Legal', '', 'Mawile', '303', 'TPCI', 'Rare Holo', '', '08/01/2006', 'type: Grass, value: -30', 'Colorless', '', 'EX', '9', 'Basic', 'Pokémon', 'Metal', 'type: Fire, value: ×2'),
('ex14-90', '', '', 'Mitsuhiro Arita', '[{\'name\': \'Drag Off\', \'cost\': [\'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \"Before doing damage, you may choose 1 of your opponent\'s Benched Pokémon and switch it with 1 of the Defending Pokémon. Your opponent chooses the Defending Pokémon to switch.\"}, {\'name\': \'Burn Away\', \'cost\': [\'Fire\', \'Fighting\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'100\', \'text\': \"Before doing damage, count the remaining HP of the Defending Pokémon. If that Pokémon is Knocked Out by this attack, Blaziken ex does damage to itself equal to the attack\'s damage minus the remaining HP of the Defending Pokémon. This attack\'s damage isn\'t by Weakness, Resistance, Poké-Powers, Poké-Bodies, or any other effects on that Pokémon.\"}]', 'Crystal Guardians', '2', 'Combusken', '', '', 'Third', '150', 'https://images.pokemoncard.io/images/ex14/ex14-90.png', 'unlimited: Legal', '', 'Blaziken ex', '257', 'TPCI', 'Rare Holo EX', '', '08/01/2006', '', 'Colorless, Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '90', 'Stage 2, EX', 'Pokémon', 'Fighting', 'type: Psychic, value: ×2'),
('ex14-91', '[{\'name\': \'Constrain\', \'text\': \"Once during your turn (before your attack), you may use this power. Each player discards cards until that player has 6 cards in his or her hand. (You discard first.) This power can\'t be used if Delcatty ex is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Shizurow', '[{\'name\': \'Upstream\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10×\', \'text\': \'Search your discard pile for all Energy cards. This attack does 10 damage times the number of Energy cards you find there. Show them to your opponent, and put them on top of your deck. Shuffle your deck afterward.\'}, {\'name\': \'Tail Slap\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60\', \'text\': \'\'}]', 'Crystal Guardians', '', 'Skitty', '', '', 'Third', '90', 'https://images.pokemoncard.io/images/ex14/ex14-91.png', 'unlimited: Legal', '', 'Delcatty ex', '301', 'TPCI', 'Rare Holo EX', '', '08/01/2006', '', '', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '91', 'Stage 1, EX', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('ex14-92', '[{\'name\': \'Extra Noise\', \'text\': \"As long as Exploud ex is your Active Pokémon, put 1 damage counter on each of your opponent\'s Pokémon-ex between turns.\", \'type\': \'Poké-Body\'}]', '', 'Mitsuhiro Arita', '[{\'name\': \'Derail\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'40\', \'text\': \'Discard a Special Energy card, if any, attached to the Defending Pokémon.\'}, {\'name\': \'Hyper Tail\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60+\', \'text\': \'If the Defending Pokémon has any Poké-Powers or Poké-Bodies, this attack does 60 damage plus 20 more damage.\'}]', 'Crystal Guardians', '3', 'Loudred', '', '', 'Third', '150', 'https://images.pokemoncard.io/images/ex14/ex14-92.png', 'unlimited: Legal', '', 'Exploud ex', '295', 'TPCI', 'Rare Holo EX', '', '08/01/2006', '', 'Colorless, Colorless, Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '92', 'Stage 2, EX', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('ex14-93', '[{\'name\': \'Hard Rock\', \'text\': \"As long as Groudon ex has 1 Energy or less attached to it, damage done to any of your Groudon ex in play by attacks is reduced by 20 (after applying Weakness and Resistance). You can\'t use more than 1 Hard Rock Poké-Body each turn.\", \'type\': \'Poké-Body\'}]', '', 'Takabon', '[{\'name\': \'Power Blast\', \'cost\': [\'Fighting\', \'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'100\', \'text\': \'Discard 2 Energy attached to Groudon ex.\'}]', 'Crystal Guardians', '2', '', '', '', 'Third', '100', 'https://images.pokemoncard.io/images/ex14/ex14-93.png', 'unlimited: Legal', '', 'Groudon ex', '383', 'TPCI', 'Rare Holo EX', '', '08/01/2006', '', 'Colorless, Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '93', 'Basic, EX', 'Pokémon', 'Fighting', 'type: Grass, value: ×2'),
('ex14-94', '[{\'name\': \'Star Light\', \'text\': \'As long as your opponent has any Pokémon-ex or Stage 2 Evolved Pokémon in play, Jirachi ex pays Colorless less Energy to use Shield Beam or Super Psy Bolt.\', \'type\': \'Poké-Body\'}]', '', 'Shizurow', '[{\'name\': \'Shield Beam\', \'cost\': [\'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \"During your opponent\'s next turn, your opponent can\'t use any Poké-Powers on his or her Pokémon.\"}, {\'name\': \'Super Psy Bolt\', \'cost\': [\'Psychic\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50\', \'text\': \'\'}]', 'Crystal Guardians', '1', '', '', '', 'Third', '90', 'https://images.pokemoncard.io/images/ex14/ex14-94.png', 'unlimited: Legal', '', 'Jirachi ex', '385', 'TPCI', 'Rare Holo EX', '', '08/01/2006', '', 'Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '94', 'Basic, EX', 'Pokémon', 'Psychic', ''),
('ex14-95', '[{\'name\': \'Flotation\', \'text\': \'As long as Kyogre ex has 1 Energy or less attached to it, the Retreat Cost for each of your Kyogre ex is 0.\', \'type\': \'Poké-Body\'}]', '', 'Yasuki Watanabe', '[{\'name\': \'Hydro Shot\', \'cost\': [\'Water\', \'Water\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'\', \'text\': \"Discard 2 Energy attached to Kyogre ex. Choose 1 of your opponent\'s Pokémon. This attack does 70 damage to that Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'Crystal Guardians', '2', '', '', '', 'Third', '100', 'https://images.pokemoncard.io/images/ex14/ex14-95.png', 'unlimited: Legal', '', 'Kyogre ex', '382', 'TPCI', 'Rare Holo EX', '', '08/01/2006', '', 'Colorless, Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '95', 'Basic, EX', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('ex14-96', '[{\'name\': \'Extra Liquid\', \'text\': \"Each player\'s Pokémon-ex can\'t use any Poké-Powers and pays Colorless more Energy to use its attacks. Each Pokémon can\'t be affected by more than 1 Extra Liquid Poké-Body.\", \'type\': \'Poké-Body\'}]', '', 'Shizurow', '[{\'name\': \'Power Revenge\', \'cost\': [\'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'60+\', \'text\': \'Does 60 damage plus 10 more damage for each Prize card your opponent has taken.\'}]', 'Crystal Guardians', '1', 'Grovyle', '', '', 'Third', '140', 'https://images.pokemoncard.io/images/ex14/ex14-96.png', 'unlimited: Legal', '', 'Sceptile ex δ', '254', 'TPCI', 'Rare Holo EX', '', '08/01/2006', 'type: Water, value: -30', 'Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '96', 'Stage 2, EX', 'Pokémon', 'Psychic', 'type: Grass, value: ×2'),
('ex14-97', '[{\'name\': \'Dark Eyes\', \'text\': \"After your opponent\'s Pokémon uses a Poké-Power, put 2 damage counters on that Pokémon.\", \'type\': \'Poké-Body\'}]', '', 'Ryo Ueda', '[{\'name\': \'Target Attack\', \'cost\': [\'Darkness\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'\', \'text\': \"Choose 1 of your opponent\'s Pokémon. This attack does 30 damage to that Pokémon. If that Pokémon already has any damage counters on it, this attack does 50 damage instead. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}, {\'name\': \'Blade Arms\', \'cost\': [\'Darkness\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'70\', \'text\': \'\'}]', 'Crystal Guardians', '', 'Nuzleaf', '', '', 'Third', '140', 'https://images.pokemoncard.io/images/ex14/ex14-97.png', 'unlimited: Legal', '', 'Shiftry ex', '275', 'TPCI', 'Rare Holo EX', '', '08/01/2006', 'type: Psychic, value: -30', '', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '97', 'Stage 2, EX', 'Pokémon', 'Darkness', 'type: Grass, value: ×2'),
('ex14-98', '[{\'name\': \'Energy Recycle\', \'text\': \"Once during your turn (before your attack), you may search your discard pile for 3 Energy cards and attach them to your Pokémon in any way you like. If you do, your turn ends. This power can\'t be used if Swampert ex is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Ryo Ueda', '[{\'name\': \'Ultra Pump\', \'cost\': [\'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60+\', \'text\': \"You may discard 2 cards from your hand. If you do, this attack does 60 damage plus 20 more damage and does 20 damage to 1 of your opponent\'s Benched Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'Crystal Guardians', '3', 'Marshtomp', '', '', 'Third', '150', 'https://images.pokemoncard.io/images/ex14/ex14-98.png', 'unlimited: Legal', '', 'Swampert ex', '260', 'TPCI', 'Rare Holo EX', '', '08/01/2006', '', 'Colorless, Colorless, Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '98', 'Stage 2, EX', 'Pokémon', 'Water', 'type: Grass, value: ×2'),
('ex14-99', '', '', 'Masakazu Fukuda', '[{\'name\': \'Psychic Select\', \'cost\': [\'Psychic\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Put any 1 card from your discard pile into your hand.\'}, {\'name\': \'Skill Copy\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'\', \'text\': \"Discard a Basic Pokémon or Evolution card from your hand. Choose 1 of that card\'s attacks. Skill Copy copies this attack. This attack does nothing if Alakazam Star doesn\'t have the Energy necessary to use that attack. (You must still do anything else required for that attack.) Alakazam Star performs that attack.\"}]', 'Crystal Guardians', '1', '', '', '', 'Third', '80', 'https://images.pokemoncard.io/images/ex14/ex14-99.png', 'unlimited: Legal', '', 'Alakazam ★', '65', 'TPCI', 'Rare Holo Star', '', '08/01/2006', '', 'Colorless', '[\"You can\'t have more than 1 Pokémon Star in your deck.\"]', 'EX', '99', 'Basic, Star', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2'),
('ex15-1', '[{\'name\': \'Holon Veil\', \'text\': \'Treat each Basic Pokémon and Evolution card in your deck, in your discard pile, in your hand, and in play as a Pokémon that has δ on its card.\', \'type\': \'Poké-Body\'}]', '', 'Kagemaru Himeno', '[{\'name\': \'Delta Circle\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'20+\', \'text\': \'Does 20 damage plus 10 more damage for each Pokémon you have in play that has δ on its card.\'}]', 'Dragon Frontiers', '2', 'Flaaffy', '', '', 'Third', '120', 'https://images.pokemoncard.io/images/ex15/ex15-1.png', 'unlimited: Legal', '', 'Ampharos δ', '181', 'TPCI', 'Rare Holo', '', '11/01/2006', '', 'Colorless, Colorless', '', 'EX', '1', 'Stage 2', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('ex15-10', '[{\'name\': \'Bedhead\', \'text\': \'As long as Snorlax remains Asleep between turns, put 2 damage counters on 1 of the Defending Pokémon.\', \'type\': \'Poké-Body\'}, {\'name\': \'Dozing\', \'text\': \"Once during your turn (before your attack), if Snorlax is your Active Pokémon, you may remove 2 damage counters from Snorlax and Snorlax is now Asleep. This power can\'t be used if Snorlax is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Masakazu Fukuda', '', 'Dragon Frontiers', '3', '', '', '', 'Third', '80', 'https://images.pokemoncard.io/images/ex15/ex15-10.png', 'unlimited: Legal', '', 'Snorlax δ', '143', 'TPCI', 'Rare Holo', '', '11/01/2006', '', 'Colorless, Colorless, Colorless', '', 'EX', '10', 'Basic', 'Pokémon', 'Grass', 'type: Fighting, value: ×2'),
('ex15-100', '', '', 'Masakazu Fukuda', '[{\'name\': \'Rotating Claws\', \'cost\': [\'Darkness\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'You may discard an Energy card attached to Charizard Star. If you do, search your discard pile for an Energy card (excluding the one you discarded) and attach it to Charizard Star.\'}, {\'name\': \'Dark Swirl\', \'cost\': [\'Darkness\', \'Darkness\', \'Darkness\', \'Darkness\', \'Colorless\'], \'convertedEnergyCost\': 5, \'damage\': \'150\', \'text\': \"Discard all Energy cards attached to Charizard Star and discard the top 3 cards from your opponent\'s deck.\"}]', 'Dragon Frontiers', '3', '', '', '', 'Third', '90', 'https://images.pokemoncard.io/images/ex15/ex15-100.png', 'unlimited: Legal', '', 'Charizard ★ δ', '6', 'TPCI', 'Rare Holo Star', '', '11/01/2006', '', 'Colorless, Colorless, Colorless', '[\"You can\'t have more than 1 Pokémon Star in your deck.\"]', 'EX', '100', 'Basic, Star', 'Pokémon', 'Darkness', 'type: Water, value: ×2'),
('ex15-101', '', '', 'Masakazu Fukuda', '[{\'name\': \'Mimicry\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Choose an attack on 1 of your opponent\'s Pokémon in play. Mimicry copies that attack. This attack does nothing if Mew Star doesn\'t have the Energy necessary to use that attack. (You must still do anything else required for that attack.) Mew Star performs that attack.\"}, {\'name\': \'Rainbow Wave\', \'cost\': [\'Water\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Choose 1 basic Energy card attached to Mew Star. This attack does 20 damage to each of your opponent\'s Pokémon that is the same type as the basic Energy card that you chose. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'Dragon Frontiers', '1', '', '', '', 'Third', '70', 'https://images.pokemoncard.io/images/ex15/ex15-101.png', 'unlimited: Legal', '', 'Mew ★ δ', '151', 'TPCI', 'Rare Holo Star', '', '11/01/2006', '', 'Colorless', '[\"You can\'t have more than 1 Pokémon Star in your deck.\"]', 'EX', '101', 'Basic, Star', 'Pokémon', 'Water', 'type: Psychic, value: ×2'),
('ex15-11', '', '', 'Kouki Saitou', '[{\'name\': \'Delta Copy\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'\', \'text\': \"Choose an attack on 1 of your opponent\'s Pokémon in play that has δ on its card. Delta Copy copies that attack except for its Energy cost. (You must still do anything else required for that attack.) Togetic performs that attack.\"}, {\'name\': \'Wave Splash\', \'cost\': [\'Water\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'\'}]', 'Dragon Frontiers', '', 'Togepi', 'Togekiss', '', 'Third', '60', 'https://images.pokemoncard.io/images/ex15/ex15-11.png', 'unlimited: Legal', '', 'Togetic δ', '176', 'TPCI', 'Rare Holo', '', '11/01/2006', 'type: Fighting, value: -30', '', '', 'EX', '11', 'Stage 1', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('ex15-12', '[{\'name\': \'Shady Move\', \'text\': \"Once during your turn (before your attack), if Typhlosion is your Active Pokémon, you may move 1 damage counter from either player\'s Pokémon to another Pokémon (yours or your opponent\'s). This power can\'t be used if Typhlosion is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Hisao Nakamura', '[{\'name\': \'Burning Ball\', \'cost\': [\'Psychic\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60\', \'text\': \'If Typhlosion has at least 2 Fire Energy attached to it, the Defending Pokémon is now Burned.\'}]', 'Dragon Frontiers', '1', 'Quilava', '', '', 'Third', '100', 'https://images.pokemoncard.io/images/ex15/ex15-12.png', 'unlimited: Legal', '', 'Typhlosion δ', '157', 'TPCI', 'Rare Holo', '', '11/01/2006', '', 'Colorless', '', 'EX', '12', 'Stage 2', 'Pokémon', 'Psychic', 'type: Water, value: ×2'),
('ex15-13', '', '', 'Hisao Nakamura', '[{\'name\': \'Burning Venom\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'The Defending Pokémon is now Burned and Poisoned.\'}, {\'name\': \'Strangle\', \'cost\': [\'Fire\', \'Fire\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50+\', \'text\': \'If the Defending Pokémon has δ on its card, this attack does 50 damage plus 30 more damage.\'}]', 'Dragon Frontiers', '1', 'Ekans', '', '', 'Third', '80', 'https://images.pokemoncard.io/images/ex15/ex15-13.png', 'unlimited: Legal', '', 'Arbok δ', '24', 'TPCI', 'Rare', '', '11/01/2006', '', 'Colorless', '', 'EX', '13', 'Stage 1', 'Pokémon', 'Fire', 'type: Psychic, value: ×2'),
('ex15-14', '[{\'name\': \'Solid Shell\', \'text\': \"Prevent all effects of attacks, including damage, done by your opponent\'s Pokémon to each of your Benched Pokémon that has δ on its card.\", \'type\': \'Poké-Body\'}]', '', 'Mitsuhiro Arita', '[{\'name\': \'Grind\', \'cost\': [\'Fighting\'], \'convertedEnergyCost\': 1, \'damage\': \'10+\', \'text\': \'Does 10 damage plus 10 more damage for each Energy attached to Cloyster.\'}]', 'Dragon Frontiers', '1', 'Shellder', '', '', 'Third', '70', 'https://images.pokemoncard.io/images/ex15/ex15-14.png', 'unlimited: Legal', '', 'Cloyster δ', '91', 'TPCI', 'Rare', '', '11/01/2006', '', 'Colorless', '', 'EX', '14', 'Stage 1', 'Pokémon', 'Fighting', 'type: Lightning, value: ×2'),
('ex15-15', '[{\'name\': \'Delta Protection\', \'text\': \"Any damage done to Dewgong by attacks from your opponent\'s Pokémon that has δ on its card is reduced by 40 (after applying Weakness and Resistance).\", \'type\': \'Poké-Body\'}]', '', 'Atsuko Nishida', '[{\'name\': \'Ice Beam\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Paralyzed.\'}, {\'name\': \'Surge\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40+\', \'text\': \'If Dewgong has at least 2 Water Energy attached to it, this attack does 40 damage plus 20 more damage.\'}]', 'Dragon Frontiers', '2', 'Seel', '', '', 'Third', '80', 'https://images.pokemoncard.io/images/ex15/ex15-15.png', 'unlimited: Legal', '', 'Dewgong δ', '87', 'TPCI', 'Rare', '', '11/01/2006', '', 'Colorless, Colorless', '', 'EX', '15', 'Stage 1', 'Pokémon', 'Colorless', 'type: Lightning, value: ×2'),
('ex15-16', '', '', 'Kagemaru Himeno', '[{\'name\': \'Sting Turn\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Paralyzed and switch Gligar with 1 of your Benched Pokémon.\'}, {\'name\': \'Tail Sting\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10+\', \'text\': \'If the Defending Pokémon is Pokémon-ex, this attack does 10 damage plus 10 more damage and the Defending Pokémon is now Poisoned.\'}]', 'Dragon Frontiers', '1', '', 'Gliscor', '', 'Third', '60', 'https://images.pokemoncard.io/images/ex15/ex15-16.png', 'unlimited: Legal', '', 'Gligar δ', '207', 'TPCI', 'Rare', '', '11/01/2006', '', 'Colorless', '', 'EX', '16', 'Basic', 'Pokémon', 'Lightning', 'type: Water, value: ×2'),
('ex15-17', '[{\'name\': \'Stages of Evolution\', \'text\': \'As long as Jynx is an Evolved Pokémon, you pay Colorless less to retreat your Fire and Psychic Pokémon.\', \'type\': \'Poké-Body\'}]', '', 'Ken Sugimori', '[{\'name\': \'Fire Punch\', \'cost\': [\'Fire\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'\'}]', 'Dragon Frontiers', '1', '', '', '', 'Third', '60', 'https://images.pokemoncard.io/images/ex15/ex15-17.png', 'unlimited: Legal', '', 'Jynx δ', '124', 'TPCI', 'Rare', '', '11/01/2006', '', 'Colorless', '', 'EX', '17', 'Basic', 'Pokémon', 'Fire', 'type: Psychic, value: ×2'),
('ex15-18', '[{\'name\': \'Prowl\', \'text\': \'Once during your turn, when you play Ledian from your hand to evolve 1 of your Pokémon, you may search your deck for any 1 card and put it into your hand. Shuffle your deck afterward.\', \'type\': \'Poké-Power\'}]', '', 'Hajime Kusajima', '[{\'name\': \'Metal Star\', \'cost\': [\'Metal\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'If Ledian has a Pokémon Tool card attached to it, draw 3 cards.\'}]', 'Dragon Frontiers', '', 'Ledyba', '', '', 'Third', '70', 'https://images.pokemoncard.io/images/ex15/ex15-18.png', 'unlimited: Legal', '', 'Ledian δ', '166', 'TPCI', 'Rare', '', '11/01/2006', '', '', '', 'EX', '18', 'Stage 1', 'Pokémon', 'Metal', 'type: Fire, value: ×2'),
('ex15-19', '', '', 'Masakazu Fukuda', '[{\'name\': \'Lap Up\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Draw 2 cards.\'}, {\'name\': \'Delta Mind\', \'cost\': [\'Psychic\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Put 1 damage counter on 1 of your opponent\'s Pokémon. If that Pokémon has δ on its card, put 3 damage counters instead.\"}]', 'Dragon Frontiers', '1', '', 'Lickilicky', '', 'Third', '60', 'https://images.pokemoncard.io/images/ex15/ex15-19.png', 'unlimited: Legal', '', 'Lickitung δ', '108', 'TPCI', 'Rare', '', '11/01/2006', '', 'Colorless', '', 'EX', '19', 'Basic', 'Pokémon', 'Psychic', 'type: Fighting, value: ×2'),
('ex15-2', '[{\'name\': \'Battle Aura\', \'text\': \'Each of your Pokémon that has δ on its card does 10 more damage to the Defending Pokémon (before applying Weakness and Resistance).\', \'type\': \'Poké-Body\'}]', '', 'Kouki Saitou', '[{\'name\': \'Drag Off\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \"Before doing damage, you may choose 1 of your opponent\'s Benched Pokémon and switch it with 1 of the Defending Pokémon. Your opponent chooses the Defending Pokémon to switch.\"}, {\'name\': \'Sharp Fang\', \'cost\': [\'Lightning\', \'Lightning\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60\', \'text\': \'\'}]', 'Dragon Frontiers', '2', 'Croconaw', '', '', 'Third', '120', 'https://images.pokemoncard.io/images/ex15/ex15-2.png', 'unlimited: Legal', '', 'Feraligatr δ', '160', 'TPCI', 'Rare Holo', '', '11/01/2006', '', 'Colorless, Colorless', '', 'EX', '2', 'Stage 2', 'Pokémon', 'Lightning', 'type: Lightning, value: ×2'),
('ex15-20', '[{\'name\': \'Power Circulation\', \'text\': \"Once during your turn (before your attack), you may search your discard pile for a basic Energy card, show it to your opponent, and put it on top of your deck. If you do, put 1 damage counter on Mantine. This power can\'t be used if Mantine is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Sumiyoshi Kizuki', '[{\'name\': \'Spiral Drain\', \'cost\': [\'Lightning\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'Remove 1 damage counter from Mantine.\'}]', 'Dragon Frontiers', '1', '', '', '', 'Third', '50', 'https://images.pokemoncard.io/images/ex15/ex15-20.png', 'unlimited: Legal', '', 'Mantine δ', '226', 'TPCI', 'Rare', '', '11/01/2006', '', 'Colorless', '', 'EX', '20', 'Basic', 'Pokémon', 'Lightning', 'type: Lightning, value: ×2'),
('ex15-21', '[{\'name\': \'Dig Up\', \'text\': \'Once during your turn, when you play Quagsire from your hand to evolve 1 of your Pokémon, you may search your discard pile for up to 2 Pokémon Tool cards, show them to your opponent, and put them into your hand.\', \'type\': \'Poké-Power\'}]', '', 'Sachiko Adachi', '[{\'name\': \'Pump Out\', \'cost\': [\'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50+\', \'text\': \'If Quagsire has a Pokémon Tool card attached to it, this attack does 50 damage plus 20 more damage.\'}]', 'Dragon Frontiers', '1', 'Wooper', '', '', 'Third', '80', 'https://images.pokemoncard.io/images/ex15/ex15-21.png', 'unlimited: Legal', '', 'Quagsire δ', '195', 'TPCI', 'Rare', '', '11/01/2006', '', 'Colorless', '', 'EX', '21', 'Stage 1', 'Pokémon', 'Grass', 'type: Grass, value: ×2'),
