('ex16-11', '[{\'name\': \'Overzealous\', \'text\': \"If your opponent has any Pokémon-ex in play, each of Machamp\'s attacks does 30 more damage to the Defending Pokémon.\", \'type\': \'Poké-Body\'}]', '', 'Ken Sugimori', '[{\'name\': \'Brick Smash\', \'cost\': [\'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'40\', \'text\': \"This attack\'s damage isn\'t affected by Resistance, Poké-Powers, Poké-Bodies, or any other effects on the Defending Pokémon.\"}, {\'name\': \'Cross Chop\', \'cost\': [\'Fighting\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'60+\', \'text\': \'Flip a coin. If heads, this attack does 60 damage plus 30 more damage.\'}]', 'Power Keepers', '2', 'Machoke', '', '', 'Third', '120', 'https://images.pokemoncard.io/images/ex16/ex16-11.png', 'unlimited: Legal', '', 'Machamp', '68', 'TPCI', 'Rare Holo', '', '02/02/2007', '', 'Colorless, Colorless', '', 'EX', '11', 'Stage 2', 'Pokémon', 'Fighting', 'type: Psychic, value: ×2'),
('ex16-12', '', '', 'Hajime Kusajima', '[{\'name\': \'Plasma\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'Search your discard pile for a Lightning Energy card and attach it to Raichu.\'}, {\'name\': \'Thunderbolt\', \'cost\': [\'Lightning\', \'Lightning\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'100\', \'text\': \'Discard all Energy cards attached to Raichu.\'}]', 'Power Keepers', '1', 'Pikachu', '', '', 'Third', '70', 'https://images.pokemoncard.io/images/ex16/ex16-12.png', 'unlimited: Legal', '', 'Raichu', '26', 'TPCI', 'Rare Holo', '', '02/02/2007', '', 'Colorless', '', 'EX', '12', 'Stage 1', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
('ex16-13', '[{\'name\': \'Lazy\', \'text\': \"As long as Slaking is your Active Pokémon, your opponent\'s Pokémon can\'t use any Poké-Powers.\", \'type\': \'Poké-Body\'}]', '', 'Midori Harada', '[{\'name\': \'Critical Move\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'100\', \'text\': \"Discard a basic Energy card attached to Slaking or this attack does nothing. Slaking can\'t attack during your next turn.\"}]', 'Power Keepers', '3', 'Vigoroth', '', '', 'Third', '120', 'https://images.pokemoncard.io/images/ex16/ex16-13.png', 'unlimited: Legal', '', 'Slaking', '289', 'TPCI', 'Rare Holo', '', '02/02/2007', '', 'Colorless, Colorless, Colorless', '', 'EX', '13', 'Stage 2', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('ex16-14', '', '', 'Ken Sugimori', '[{\'name\': \'Dark Mind\', \'cost\': [\'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \"Does 20 damage to 1 of your opponent\'s Benched Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}, {\'name\': \'Mysterious Light\', \'cost\': [\'Psychic\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50\', \'text\': \"If Phoebe\'s Stadium is in play, the Defending Pokémon is now Confused.\"}]', 'Power Keepers', '2', 'Duskull', 'Dusknoir', '', 'Third', '80', 'https://images.pokemoncard.io/images/ex16/ex16-14.png', 'unlimited: Legal', '', 'Dusclops', '356', 'TPCI', 'Rare', '', '02/02/2007', 'type: Fighting, value: -30', 'Colorless, Colorless', '', 'EX', '14', 'Stage 1', 'Pokémon', 'Psychic', 'type: Darkness, value: ×2'),
('ex16-15', '[{\'name\': \'Energy Grounding\', \'text\': \"Once during your opponent\'s turn, when any of your Pokémon is Knocked Out by your opponent\'s attacks, you may use this power. Choose a basic Energy card discarded from the Knocked Out Pokémon and attach it to Lanturn. You can\'t use more than 1 Energy Grounding Poké-Power each turn.\", \'type\': \'Poké-Power\'}]', '', 'Midori Harada', '[{\'name\': \'Lightning Strike\', \'cost\': [\'Lightning\', \'Lightning\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50\', \'text\': \"You may discard all Lightning Energy attached to Lanturn. If you do, this attack\'s base damage is 90 instead of 50.\"}]', 'Power Keepers', '2', 'Chinchou', '', '', 'Third', '80', 'https://images.pokemoncard.io/images/ex16/ex16-15.png', 'unlimited: Legal', '', 'Lanturn', '171', 'TPCI', 'Rare', '', '02/02/2007', '', 'Colorless, Colorless', '', 'EX', '15', 'Stage 1', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
('ex16-16', '[{\'name\': \'Magnetic Field\', \'text\': \"Once during your turn (before your attack), if you have basic Energy cards in your discard pile, you may discard any 1 card from your hand. Then search for up to 2 basic Energy cards from your discard pile, show them to your opponent, and put them into your hand. You can\'t return the card you first discarded to your hand in this way. This power can\'t be used if Magneton is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Masakazu Fukuda', '[{\'name\': \'Magnetic Force\', \'cost\': [\'Lightning\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'10×\', \'text\': \'Does 10 damage times the amount of Energy attached to all of your Pokémon (including Magneton).\'}]', 'Power Keepers', '1', 'Magnemite', 'Magnezone', '', 'Third', '70', 'https://images.pokemoncard.io/images/ex16/ex16-16.png', 'unlimited: Legal', '', 'Magneton', '82', 'TPCI', 'Rare', '', '02/02/2007', 'type: Metal, value: -30', 'Colorless', '', 'EX', '16', 'Stage 1', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
('ex16-17', '', '', 'Ken Sugimori', '[{\'name\': \'Call for Family\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Search your deck for a Basic Pokémon and put it onto your Bench. Shuffle your deck afterward.\'}, {\'name\': \'Pull Away\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'If your opponent has 5 or more cards in his or her hand, your opponent discards a number of cards until your opponent has 4 cards left in his or her hand.\'}]', 'Power Keepers', '1', '', '', '', 'Third', '60', 'https://images.pokemoncard.io/images/ex16/ex16-17.png', 'unlimited: Legal', '', 'Mawile', '303', 'TPCI', 'Rare', '', '02/02/2007', 'type: Grass, value: -30', 'Colorless', '', 'EX', '17', 'Basic', 'Pokémon', 'Metal', 'type: Fire, value: ×2'),
('ex16-18', '', '', 'Midori Harada', '[{\'name\': \'Plunder\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'Before doing damage, discard all Trainer cards attached to the Defending Pokémon.\'}, {\'name\': \'Dark Burst\', \'cost\': [\'Darkness\', \'Darkness\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50+\', \'text\': \"If Sidney\'s Stadium is in play, this attack does 50 damage plus 20 more damage.\"}]', 'Power Keepers', '', 'Poochyena', '', '', 'Third', '70', 'https://images.pokemoncard.io/images/ex16/ex16-18.png', 'unlimited: Legal', '', 'Mightyena', '262', 'TPCI', 'Rare', '', '02/02/2007', 'type: Psychic, value: -30', '', '', 'EX', '18', 'Stage 1', 'Pokémon', 'Darkness', 'type: Fighting, value: ×2'),
('ex16-19', '[{\'name\': \'Safeguard\', \'text\': \"Prevent all effects of attacks, including damage, done to Ninetales by your opponent\'s Pokémon-ex.\", \'type\': \'Poké-Body\'}]', '', 'Tomoaki Imakuni', '[{\'name\': \'Quick Attack\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20+\', \'text\': \'Flip a coin. If heads, this attack does 20 damage plus 20 more damage.\'}, {\'name\': \"Will-o\'-the-wisp\", \'cost\': [\'Fire\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50\', \'text\': \'\'}]', 'Power Keepers', '1', 'Vulpix', '', '', 'Third', '70', 'https://images.pokemoncard.io/images/ex16/ex16-19.png', 'unlimited: Legal', '', 'Ninetales', '38', 'TPCI', 'Rare', '', '02/02/2007', '', 'Colorless', '', 'EX', '19', 'Stage 1', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('ex16-2', '[{\'name\': \'Synergy Effect\', \'text\': \"If Drake\'s Stadium is in play, remove 1 damage counter from Altaria between turns.\", \'type\': \'Poké-Body\'}]', '', 'Ken Sugimori', '[{\'name\': \'Surprise\', \'cost\': [\'Water\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \"Choose 1 card from your opponent\'s hand without looking. Look at the card you chose, then have your opponent shuffle that card into his or her deck.\"}, {\'name\': \'Gust\', \'cost\': [\'Lightning\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50\', \'text\': \'\'}]', 'Power Keepers', '1', 'Swablu', '', '', 'Third', '80', 'https://images.pokemoncard.io/images/ex16/ex16-2.png', 'unlimited: Legal', '', 'Altaria', '334', 'TPCI', 'Rare Holo', '', '02/02/2007', 'type: Grass, value: -30, type: Fighting, value: -30', 'Colorless', '', 'EX', '2', 'Stage 1', 'Pokémon', 'Colorless', 'type: Colorless, value: ×2'),
('ex16-20', '', '', 'Ken Sugimori', '[{\'name\': \'Pull Down\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'If your opponent has any Evolved Pokémon in play, remove the highest Stage Evolution card from each of them and put those cards back into his or her hand.\'}, {\'name\': \'Hydrocannon\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30+\', \'text\': \"Does 30 damage plus 20 more damage for each Water Energy attached to Omastar but not used to pay for this attack\'s Energy cost. You can\'t add more than 40 damage in this way.\"}]', 'Power Keepers', '2', 'Omanyte', '', '', 'Third', '110', 'https://images.pokemoncard.io/images/ex16/ex16-20.png', 'unlimited: Legal', '', 'Omastar', '139', 'TPCI', 'Rare', '', '02/02/2007', '', 'Colorless, Colorless', '', 'EX', '20', 'Stage 2', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('ex16-21', '[{\'name\': \'Baby Evolution\', \'text\': \'Once during your turn (before your attack), you may put Pikachu from your hand onto Pichu (this counts as evolving Pichu) and remove all damage counters from Pichu.\', \'type\': \'Poké-Power\'}]', '', 'Ken Sugimori', '[{\'name\': \'Cry for Help\', \'cost\': [\'Lightning\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Search your deck for a Lightning Pokémon (excluding Pokémon-ex), show it to your opponent, and put it into your hand. Shuffle your deck afterward.\'}]', 'Power Keepers', '1', '', 'Pikachu', '', 'Third', '50', 'https://images.pokemoncard.io/images/ex16/ex16-21.png', 'unlimited: Legal', '', 'Pichu', '172', 'TPCI', 'Rare', '', '02/02/2007', '', 'Colorless', '', 'EX', '21', 'Basic', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
('ex16-22', '[{\'name\': \'Synergy Effect\', \'text\': \"If Phoebe\'s Stadium is in play, prevent all damage done to Sableye by attacks from your opponent\'s Pokémon-ex.\", \'type\': \'Poké-Body\'}]', '', 'Ken Sugimori', '[{\'name\': \'Down Draw\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Draw 2 cards from the bottom of your deck.\'}, {\'name\': \'Feint Attack\', \'cost\': [\'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'\', \'text\': \"Choose 1 of your opponent\'s Pokémon. This attack does 20 damage to that Pokémon. This attack\'s damage isn\'t affected by Weakness, Resistance, Poké-Powers, Poké-Bodies, or any other effects on that Pokémon.\"}]', 'Power Keepers', '1', '', '', '', 'Third', '60', 'https://images.pokemoncard.io/images/ex16/ex16-22.png', 'unlimited: Legal', '', 'Sableye', '302', 'TPCI', 'Rare', '', '02/02/2007', 'type: Colorless, value: -30', 'Colorless', '', 'EX', '22', 'Basic', 'Pokémon', 'Psychic', ''),
('ex16-23', '', '', 'Midori Harada', '[{\'name\': \'Sharp Fang\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'\'}, {\'name\': \'Toxic\', \'cost\': [\'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'\', \'text\': \'The Defending Pokémon is now Poisoned. Put 2 damage counters instead of 1 on the Defending Pokémon between turns.\'}]', 'Power Keepers', '1', '', '', '', 'Third', '70', 'https://images.pokemoncard.io/images/ex16/ex16-23.png', 'unlimited: Legal', '', 'Seviper', '336', 'TPCI', 'Rare', '', '02/02/2007', '', 'Colorless', '', 'EX', '23', 'Basic', 'Pokémon', 'Grass', 'type: Psychic, value: ×2'),
