('ex16-51', '', '', 'Ken Sugimori', '[{\'name\': \'Fast Evolution\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Search your deck for an Evolution card, show it to your opponent, and put it into your hand. Shuffle your deck afterward.\'}, {\'name\': \'Double Scratch\', \'cost\': [\'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20×\', \'text\': \'Flip 2 coins. This attack does 20 damage times the number of heads.\'}]', 'Power Keepers', '2', 'Mysterious Fossil', 'Kabutops', '', 'Third', '60', 'https://images.pokemoncard.io/images/ex16/ex16-51.png', 'unlimited: Legal', '', 'Kabuto', '140', 'TPCI', 'Common', '', '02/02/2007', '', 'Colorless, Colorless', '', 'EX', '51', 'Stage 1', 'Pokémon', 'Fighting', 'type: Grass, value: ×2'),
('ex16-52', '', '', 'Hajime Kusajima', '[{\'name\': \'Surprise\', \'cost\': [\'Grass\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \"Choose 1 card from your opponent\'s hand without looking. Look at the card you chose, then have your opponent shuffle that card into his or her deck.\"}, {\'name\': \'Acid\', \'cost\': [\'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40\', \'text\': \"The Defending Pokémon can\'t retreat during your opponent\'s next turn.\"}]', 'Power Keepers', '2', 'Root Fossil', 'Cradily', '', 'Third', '80', 'https://images.pokemoncard.io/images/ex16/ex16-52.png', 'unlimited: Legal', '', 'Lileep', '345', 'TPCI', 'Common', '', '02/02/2007', '', 'Colorless, Colorless', '', 'EX', '52', 'Stage 1', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('ex16-53', '', '', 'Ken Sugimori', '[{\'name\': \'Smash Punch\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'20\', \'text\': \'Flip a coin. If tails, this attack does nothing.\'}, {\'name\': \'Submission\', \'cost\': [\'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'Machop does 10 damage to itself.\'}]', 'Power Keepers', '1', '', 'Machoke', '', 'Third', '50', 'https://images.pokemoncard.io/images/ex16/ex16-53.png', 'unlimited: Legal', '', 'Machop', '66', 'TPCI', 'Common', '', '02/02/2007', '', 'Colorless', '', 'EX', '53', 'Basic', 'Pokémon', 'Fighting', 'type: Psychic, value: ×2'),
('ex16-54', '', '', 'Hajime Kusajima', '[{\'name\': \'Ram\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'\'}, {\'name\': \'Spark\', \'cost\': [\'Lightning\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \"Does 10 damage to 1 of your opponent\'s Benched Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'Power Keepers', '1', '', 'Magneton', '', 'Third', '50', 'https://images.pokemoncard.io/images/ex16/ex16-54.png', 'unlimited: Legal', '', 'Magnemite', '81', 'TPCI', 'Common', '', '02/02/2007', 'type: Metal, value: -30', 'Colorless', '', 'EX', '54', 'Basic', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
('ex16-55', '', '', 'Midori Harada', '[{\'name\': \'Psyshock\', \'cost\': [\'Psychic\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Paralyzed.\'}, {\'name\': \'Cross Chop\', \'cost\': [\'Fighting\'], \'convertedEnergyCost\': 1, \'damage\': \'10+\', \'text\': \'Flip a coin. If heads, this attack does 10 damage plus 10 more damage.\'}]', 'Power Keepers', '1', '', 'Medicham', '', 'Third', '40', 'https://images.pokemoncard.io/images/ex16/ex16-55.png', 'unlimited: Legal', '', 'Meditite', '307', 'TPCI', 'Common', '', '02/02/2007', '', 'Colorless', '', 'EX', '55', 'Basic', 'Pokémon', 'Fighting', 'type: Psychic, value: ×2'),
('ex16-56', '', '', 'Ken Sugimori', '[{\'name\': \'Influence\', \'cost\': [\'Water\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Search your deck for Omanyte, Kabuto, Aerodactyl, Lileep, or Anorith and put up to 2 of them onto your Bench. Shuffle your deck afterward. Treat the new Benched Pokémon as Basic Pokémon.\'}, {\'name\': \'Mud Shot\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'\'}]', 'Power Keepers', '1', 'Mysterious Fossil', 'Omastar', '', 'Third', '70', 'https://images.pokemoncard.io/images/ex16/ex16-56.png', 'unlimited: Legal', '', 'Omanyte', '138', 'TPCI', 'Common', '', '02/02/2007', '', 'Colorless', '', 'EX', '56', 'Stage 1', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('ex16-57', '', '', 'Kagemaru Himeno', '[{\'name\': \'Charge\', \'cost\': [\'Lightning\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Search your discard pile for a Lightning Energy card and attach it to Pikachu.\'}, {\'name\': \'Slam\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20×\', \'text\': \'Flip 2 coins. This attack does 20 damage times the number of heads.\'}]', 'Power Keepers', '1', '', 'Raichu', '', 'Third', '40', 'https://images.pokemoncard.io/images/ex16/ex16-57.png', 'unlimited: Legal', '', 'Pikachu', '25', 'TPCI', 'Common', '', '02/02/2007', '', 'Colorless', '', 'EX', '57', 'Basic', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
