('ex16-59', '', '', 'Midori Harada', '[{\'name\': \'Slap\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'\'}, {\'name\': \'Teleportation Burst\', \'cost\': [\'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'Switch Ralts with 1 of your Benched Pokémon.\'}]', 'Power Keepers', '1', '', 'Kirlia', '', 'Third', '50', 'https://images.pokemoncard.io/images/ex16/ex16-59.png', 'unlimited: Legal', '', 'Ralts', '280', 'TPCI', 'Common', '', '02/02/2007', '', 'Colorless', '', 'EX', '59', 'Basic', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2'),
('ex16-6', '', '', 'Ken Sugimori', '[{\'name\': \'Combustion\', \'cost\': [\'Fire\'], \'convertedEnergyCost\': 1, \'damage\': \'30\', \'text\': \'\'}, {\'name\': \'Bursting Inferno\', \'cost\': [\'Fire\', \'Fire\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'50\', \'text\': \'Each Defending Pokémon is now Burned.\'}]', 'Power Keepers', '2', 'Charmeleon', '', '', 'Third', '120', 'https://images.pokemoncard.io/images/ex16/ex16-6.png', 'unlimited: Legal', '', 'Charizard', '6', 'TPCI', 'Rare Holo', '', '02/02/2007', '', 'Colorless, Colorless', '', 'EX', '6', 'Stage 2', 'Pokémon', 'Fire', 'type: Water, value: ×2');
