('ex16-62', '', '', 'Tomokazu Komiya', '[{\'name\': \'Tail Whip\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Flip a coin. If heads, the Defending Pokémon can\'t attack during your opponent\'s next turn.\"}, {\'name\': \'Tackle\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'\'}]', 'Power Keepers', '1', '', 'Delcatty', '', 'Third', '50', 'https://images.pokemoncard.io/images/ex16/ex16-62.png', 'unlimited: Legal', '', 'Skitty', '300', 'TPCI', 'Common', '', '02/02/2007', '', 'Colorless', '', 'EX', '62', 'Basic', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('ex16-63', '', '', 'Tomokazu Komiya', '[{\'name\': \'Amnesia\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Choose 1 of the Defending Pokémon\'s attacks. That Pokémon can\'t use that attack during your opponent\'s next turn.\"}, {\'name\': \'Scratch\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'\'}]', 'Power Keepers', '1', '', 'Vigoroth', '', 'Third', '40', 'https://images.pokemoncard.io/images/ex16/ex16-63.png', 'unlimited: Legal', '', 'Slakoth', '287', 'TPCI', 'Common', '', '02/02/2007', '', 'Colorless', '', 'EX', '63', 'Basic', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('ex16-64', '', '', 'Ken Sugimori', '[{\'name\': \'Pebble Throw\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Choose 1 of your opponent\'s Benched Pokémon. This attack does 10 damage to that Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}, {\'name\': \'Double Headbutt\', \'cost\': [\'Water\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20×\', \'text\': \'Flip 2 coins. This attack does 20 damage times the number of heads.\'}]', 'Power Keepers', '1', '', 'Glalie, Froslass', '', 'Third', '50', 'https://images.pokemoncard.io/images/ex16/ex16-64.png', 'unlimited: Legal', '', 'Snorunt', '361', 'TPCI', 'Common', '', '02/02/2007', '', 'Colorless', '', 'EX', '64', 'Basic', 'Pokémon', 'Water', 'type: Metal, value: ×2'),
('ex16-65', '', '', 'Ken Sugimori', '[{\'name\': \'Defense Curl\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Flip a coin. If heads, prevent all damage done to Spheal during your opponent\'s next turn.\"}, {\'name\': \'Aurora Beam\', \'cost\': [\'Water\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'\'}]', 'Power Keepers', '1', '', 'Sealeo', '', 'Third', '40', 'https://images.pokemoncard.io/images/ex16/ex16-65.png', 'unlimited: Legal', '', 'Spheal', '363', 'TPCI', 'Common', '', '02/02/2007', '', 'Colorless', '', 'EX', '65', 'Basic', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
