('ex16-67', '', '', 'Mitsuhiro Arita', '[{\'name\': \'Super Singe\', \'cost\': [\'Fire\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Burned.\'}]', 'Power Keepers', '1', '', 'Combusken', '', 'Third', '50', 'https://images.pokemoncard.io/images/ex16/ex16-67.png', 'unlimited: Legal', '', 'Torchic', '255', 'TPCI', 'Common', '', '02/02/2007', '', 'Colorless', '', 'EX', '67', 'Basic', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('ex16-68', '', '', 'Sachiko Adachi', '[{\'name\': \'Surprise Attack\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'20\', \'text\': \'Flip a coin. If tails, this attack does nothing.\'}]', 'Power Keepers', '1', '', 'Vibrava', '', 'Third', '50', 'https://images.pokemoncard.io/images/ex16/ex16-68.png', 'unlimited: Legal', '', 'Trapinch', '328', 'TPCI', 'Common', '', '02/02/2007', '', 'Colorless', '', 'EX', '68', 'Basic', 'Pokémon', 'Fighting', 'type: Grass, value: ×2'),
('ex16-69', '', '', 'Ken Sugimori', '[{\'name\': \'Confuse Ray\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Confused.\'}, {\'name\': \'Ember\', \'cost\': [\'Fire\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'Discard a Fire Energy attached to Vulpix.\'}]', 'Power Keepers', '1', '', 'Ninetales', '', 'Third', '50', 'https://images.pokemoncard.io/images/ex16/ex16-69.png', 'unlimited: Legal', '', 'Vulpix', '37', 'TPCI', 'Common', '', '02/02/2007', '', 'Colorless', '', 'EX', '69', 'Basic', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('ex16-7', '[{\'name\': \'Evolutionary Call\', \'text\': \'Once during your turn, when you play Cradily from your hand to evolve 1 of your Pokémon, you may search your deck for up to 3 in any combination of Basic Pokémon or Evolution cards. Show them to your opponent and put them into your hand. Shuffle your deck afterward.\', \'type\': \'Poké-Power\'}]', '', 'Ken Sugimori', '[{\'name\': \'Poison Ring\', \'cost\': [\'Grass\', \'Grass\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50\', \'text\': \"The Defending Pokémon is now Poisoned. The Defending Pokémon can\'t retreat during your opponent\'s next turn.\"}]', 'Power Keepers', '2', 'Lileep', '', '', 'Third', '110', 'https://images.pokemoncard.io/images/ex16/ex16-7.png', 'unlimited: Legal', '', 'Cradily', '346', 'TPCI', 'Rare Holo', '', '02/02/2007', '', 'Colorless, Colorless', '', 'EX', '7', 'Stage 2', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('ex16-70', '[{\'name\': \'Baby Evolution\', \'text\': \'Once during your turn (before your attack), you may put Wobbuffet from your hand onto Wynaut (this counts as evolving Wynaut) and remove all damage counters from Wynaut.\', \'type\': \'Poké-Power\'}]', '', 'Ken Sugimori', '[{\'name\': \'Flail\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10×\', \'text\': \'Does 10 damage times the number of damage counters on Wynaut.\'}]', 'Power Keepers', '1', '', 'Wobbuffet', '', 'Third', '50', 'https://images.pokemoncard.io/images/ex16/ex16-70.png', 'unlimited: Legal', '', 'Wynaut', '360', 'TPCI', 'Common', '', '02/02/2007', '', 'Colorless', '', 'EX', '70', 'Basic', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2'),
('ex16-71', '', '', 'Midori Harada', '', 'Power Keepers', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex16/ex16-71.png', 'unlimited: Legal', '', 'Battle Frontier', '', 'TPCI', 'Uncommon', '', '02/02/2007', '', '', '[\"This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can\'t play this card.\", \"Each player\'s Colorless Evolved Pokémon, Darkness Evolved Pokémon, and Metal Evolved Pokémon can\'t use any Poké-Powers or Poké-Bodies.\"]', 'EX', '71', 'Stadium', 'Trainer', '', ''),
('ex16-72', '', '', 'Ryo Ueda', '', 'Power Keepers', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex16/ex16-72.png', 'unlimited: Legal', '', 'Drakes Stadium', '', 'TPCI', 'Uncommon', '', '02/02/2007', '', '', '[\"This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can\'t play this card.\", \"Any damage done to Colorless Active Pokémon (both yours and your opponent\'s) by an opponent\'s attack is reduced by 10 (after applying Weakness and Resistance).\"]', 'EX', '72', 'Stadium', 'Trainer', '', ''),
('ex16-73', '', '', 'Zu-Ka', '', 'Power Keepers', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex16/ex16-73.png', 'unlimited: Legal, expanded: Legal', '', 'Energy Recycle System', '', 'TPCI', 'Uncommon', '', '02/02/2007', '', '', '[\'Search your discard pile for basic Energy cards. You may either show 1 basic Energy card to your opponent and put it into your hand, or show 3 basic Energy cards to your opponent and shuffle them into your deck.\']', 'EX', '73', 'Item', 'Trainer', '', ''),
('ex16-74', '', '', 'Keiji Kinebuchi', '', 'Power Keepers', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex16/ex16-74.png', 'unlimited: Legal', '', 'Energy Removal 2', '', 'TPCI', 'Uncommon', '', '02/02/2007', '', '', '[\"Flip a coin. If heads, choose 1 Energy card attached to 1 of your opponent\'s Pokémon and discard it.\"]', 'EX', '74', 'Item', 'Trainer', '', ''),
('ex16-75', '', '', 'Ken Ikuji', '', 'Power Keepers', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex16/ex16-75.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Energy Switch', '', 'TPCI', 'Uncommon', '', '02/02/2007', '', '', '[\'Move a basic Energy card attached to 1 of your Pokémon to another of your Pokémon.\']', 'EX', '75', 'Item', 'Trainer', '', ''),
('ex16-76', '', '', 'Ryo Ueda', '', 'Power Keepers', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex16/ex16-76.png', 'unlimited: Legal', '', 'Glacias Stadium', '', 'TPCI', 'Uncommon', '', '02/02/2007', '', '', '[\"This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can\'t play this card.\", \"Each player\'s Water Pokémon (excluding Pokémon-ex) has no Weakness.\"]', 'EX', '76', 'Stadium', 'Trainer', '', ''),
('ex16-77', '', '', 'Nakaoka', '', 'Power Keepers', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex16/ex16-77.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Great Ball', '', 'TPCI', 'Uncommon', '', '02/02/2007', '', '', '[\'Search your deck for a Basic Pokémon (excluding Pokémon-ex) and put it onto your Bench. Shuffle your deck afterward.\']', 'EX', '77', 'Item', 'Trainer', '', ''),
('ex16-78', '', '', 'Keiji Kinebuchi', '', 'Power Keepers', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex16/ex16-78.png', 'unlimited: Legal', '', 'Master Ball', '', 'TPCI', 'Uncommon', '', '02/02/2007', '', '', '[\'Look at the top 7 cards from your deck. Choose a Basic Pokémon or Evolution card from those cards, show it to your opponent, and put it into your hand. Put the other 6 cards back on top of your deck. Shuffle your deck afterward.\']', 'EX', '78', 'Item', 'Trainer', '', ''),
('ex16-79', '', '', 'Ryo Ueda', '', 'Power Keepers', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex16/ex16-79.png', 'unlimited: Legal', '', 'Phoebes Stadium', '', 'TPCI', 'Uncommon', '', '02/02/2007', '', '', '[\"This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can\'t play this card.\", \'Each player pays ColorlessColorless less to retreat his or her Psychic Pokémon.\']', 'EX', '79', 'Stadium', 'Trainer', '', ''),
('ex16-8', '[{\'name\': \'Energy Draw\', \'text\': \"Once during your turn (before your attack), you may discard 1 Energy card from your hand. Then draw up to 3 cards from your deck. This power can\'t be used if Delcatty is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Masakazu Fukuda', '[{\'name\': \'Max Energy Source\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10×\', \'text\': \'Does 10 damage times the amount of Energy attached to all of your Active Pokémon.\'}]', 'Power Keepers', '1', 'Skitty', '', '', 'Third', '70', 'https://images.pokemoncard.io/images/ex16/ex16-8.png', 'unlimited: Legal', '', 'Delcatty', '301', 'TPCI', 'Rare Holo', '', '02/02/2007', '', 'Colorless', '', 'EX', '8', 'Stage 1', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('ex16-80', '', '', 'Ken Sugimori', '', 'Power Keepers', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex16/ex16-80.png', 'unlimited: Legal', '', 'Professor Birch', '', 'TPCI', 'Uncommon', '', '02/02/2007', '', '', '[\'You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.\', \'Draw cards from your deck until you have 6 cards in your hand.\']', 'EX', '80', 'Supporter', 'Trainer', '', ''),
('ex16-81', '', '', 'Ken Sugimori', '', 'Power Keepers', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex16/ex16-81.png', 'unlimited: Legal', '', 'Scott', '', 'TPCI', 'Uncommon', '', '02/02/2007', '', '', '[\'You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.\', \'Search your deck for up to 3 cards in any combination of Supporter cards and Stadium cards, show them to your opponent, and put them into your hand. Shuffle your deck afterward.\']', 'EX', '81', 'Supporter', 'Trainer', '', ''),
('ex16-82', '', '', 'Ryo Ueda', '', 'Power Keepers', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex16/ex16-82.png', 'unlimited: Legal', '', 'Sidneys Stadium', '', 'TPCI', 'Uncommon', '', '02/02/2007', '', '', '[\"This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can\'t play this card.\", \"Each player\'s Darkness Pokémon can\'t be Asleep, Confused, or Paralyzed.\"]', 'EX', '82', 'Stadium', 'Trainer', '', ''),
('ex16-83', '', '', 'Ken Sugimori', '', 'Power Keepers', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex16/ex16-83.png', 'unlimited: Legal', '', 'Stevens Advice', '', 'TPCI', 'Uncommon', '', '02/02/2007', '', '', '[\'You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.\', \"Draw a number of cards up to the number of your opponent\'s Pokémon in play.\", \"If you have 7 or more cards (including this one) in your hand, you can\'t play this card.\"]', 'EX', '83', 'Supporter', 'Trainer', '', ''),
('ex16-84', '[{\'name\': \'Jagged Stone\', \'text\': \"If Claw Fossil is your Active Pokémon and is damaged by an opponent\'s attack (even if Claw Fossil is Knocked Out), put 1 damage counter on the Attacking Pokémon.\", \'type\': \'Poké-Body\'}]', '', 'Ryo Ueda', '', 'Power Keepers', '', '', '', '', 'Third', '40', 'https://images.pokemoncard.io/images/ex16/ex16-84.png', 'unlimited: Legal', '', 'Claw Fossil', '', 'TPCI', 'Common', '', '02/02/2007', '', '', '[\"Play Claw Fossil as if it were a Basic Pokémon. While in play Claw Fossil counts as a Colorless Pokémon (as well as a Trainer card). Claw Fossil has no attacks of its own, can\'t retreat, and can\'t be affected by any Special Conditions. If Claw Fossil is Knocked Out, it doesn\'t count as a Knocked Out Pokémon. (Discard it anyway.) At any time during your turn before your attack, you may discard Claw Fossil from play.\"]', 'EX', '84', 'Item', 'Trainer', '', ''),
('ex16-85', '', '', 'Ryo Ueda', '', 'Power Keepers', '', '', '', '', 'Third', '50', 'https://images.pokemoncard.io/images/ex16/ex16-85.png', 'unlimited: Legal', '', 'Mysterious Fossil', '', 'TPCI', 'Common', '', '02/02/2007', '', '', '[\"Play Mysterious Fossil as if it were a Basic Pokémon. While in play, Mysterious Fossil counts as a Colorless Pokémon (as well as a Trainer card). Mysterious Fossil has no attacks of its own, can\'t retreat, and can\'t be affected by any Special Conditions. If Mysterious Fossil is Knocked Out, it doesn\'t count as a Knocked Out Pokémon. (Discard it anyway.) At any time during your turn before your attack, you may discard Mysterious Fossil from play.\"]', 'EX', '85', 'Item', 'Trainer', '', ''),
('ex16-86', '[{\'name\': \'Spongy Stone\', \'text\': \'At any time between turns, remove 1 damage counter from Root Fossil.\', \'type\': \'Poké-Body\'}]', '', 'Ryo Ueda', '', 'Power Keepers', '', '', '', '', 'Third', '40', 'https://images.pokemoncard.io/images/ex16/ex16-86.png', 'unlimited: Legal', '', 'Root Fossil', '', 'TPCI', 'Common', '', '02/02/2007', '', '', '[\"Play Root Fossil as if it were a Basic Pokémon. While in play, Root Fossil counts as a Colorless Pokémon (as well as a Trainer card). Root Fossil has no attacks of its own, can\'t retreat, and can\'t be affected by any Special Conditions. If Root Fossil is Knocked Out, it doesn\'t count as a Knocked Out Pokémon. (Discard it anyway.) At any time during your turn before your attack, you may discard Root Fossil from play.\"]', 'EX', '86', 'Item', 'Trainer', '', ''),
('ex16-87', '', '', 'Milky Isobe', '', 'Power Keepers', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex16/ex16-87.png', 'unlimited: Legal', '', 'Darkness Energy', '', 'TPCI', 'Rare', '', '02/02/2007', '', '', '[\"If the Pokémon Darkness Energy is attached to attacks, the attack does 10 more damage to the Active Pokémon (before applying Weakness and Resistance). Ignore this effect unless the Attacking Pokémon is Darkness or has Dark in its name. Darkness Energy provides Darkness Energy. (Doesn\'t count as a basic Energy card.)\"]', 'EX', '87', 'Special', 'Energy', '', ''),
('ex16-88', '', '', 'Milky Isobe', '', 'Power Keepers', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex16/ex16-88.png', 'unlimited: Legal', '', 'Metal Energy', '', 'TPCI', 'Rare', '', '02/02/2007', '', '', '[\"Damage done by attacks to the Pokémon that Metal Energy is attached to is reduced by 10 (after applying Weakness and Resistance). Ignore this effect if the Pokémon that Metal Energy is attached to isn\'t Metal. Metal Energy provides Metal Energy. (Doesn\'t count as a basic Energy card.)\"]', 'EX', '88', 'Special', 'Energy', '', ''),
('ex16-89', '', '', 'Takumi Akabane', '', 'Power Keepers', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex16/ex16-89.png', 'unlimited: Legal', '', 'Multi Energy', '', 'TPCI', 'Rare', '', '02/02/2007', '', '', '[\'Attach Multi Energy to 1 of your Pokémon. While in play, Multi Energy provides every type of Energy but provides only 1 Energy at a time. (Has no effect other than providing Energy.) Multi Energy provides Colorless Energy when attached to a Pokémon that already has Special Energy cards attached to it.\']', 'EX', '89', 'Special', 'Energy', '', ''),
('ex16-9', '[{\'name\': \'Psy Shadow\', \'text\': \"Once during your turn (before your attack), you may search your deck for a Psychic Energy card and attach it to 1 of your Pokémon. Put 2 damage counters on that Pokémon. Shuffle your deck afterward. This power can\'t be used if Gardevoir is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Midori Harada', '[{\'name\': \'Energy Burst\', \'cost\': [\'Psychic\'], \'convertedEnergyCost\': 1, \'damage\': \'10×\', \'text\': \'Does 10 damage times the total amount of Energy attached to Gardevoir and the Defending Pokémon.\'}]', 'Power Keepers', '2', 'Kirlia', '', '', 'Third', '100', 'https://images.pokemoncard.io/images/ex16/ex16-9.png', 'unlimited: Legal', '', 'Gardevoir', '282', 'TPCI', 'Rare Holo', '', '02/02/2007', '', 'Colorless, Colorless', '', 'EX', '9', 'Stage 2', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2'),
('ex16-90', '', '', 'Shin-ichi Yoshikawa', '', 'Power Keepers', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex16/ex16-90.png', 'unlimited: Legal', '', 'Cyclone Energy', '', 'TPCI', 'Uncommon', '', '02/02/2007', '', '', '[\"Cyclone Energy provides Colorless Energy. When you attach this card from your hand to your Active Pokémon, switch 1 of the Defending Pokémon with 1 of your opponent\'s Benched Pokémon. Your opponent chooses the Benched Pokémon to switch.\"]', 'EX', '90', 'Special', 'Energy', '', ''),
('ex16-91', '', '', 'Shin-ichi Yoshikawa', '', 'Power Keepers', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex16/ex16-91.png', 'unlimited: Legal, expanded: Legal', '', 'Warp Energy', '', 'TPCI', 'Uncommon', '', '02/02/2007', '', '', '[\'Warp Energy provides Colorless Energy. When you attach this card from your hand to your Active Pokémon, switch that Pokémon with 1 of your Benched Pokémon.\']', 'EX', '91', 'Special', 'Energy', '', ''),
('ex16-92', '[{\'name\': \'Cursed Eyes\', \'text\': \"Once during your turn, when you put Absol ex from your hand onto your Bench, you may move 3 damage counters from 1 of your opponent\'s Pokémon to another of his or her Pokémon.\", \'type\': \'Poké-Power\'}]', '', 'Ryo Ueda', '[{\'name\': \'Psychic Pulse\', \'cost\': [\'Darkness\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \"Does 10 damage to each of your opponent\'s Benched Pokémon that has any damage counters on it. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'Power Keepers', '1', '', '', '', 'Third', '100', 'https://images.pokemoncard.io/images/ex16/ex16-92.png', 'unlimited: Legal', '', 'Absol ex', '359', 'TPCI', 'Rare Holo EX', '', '02/02/2007', 'type: Psychic, value: -30', 'Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '92', 'Basic, EX', 'Pokémon', 'Darkness', 'type: Fighting, value: ×2'),
('ex16-93', '[{\'name\': \'Type Shift\', \'text\': \"Once during your turn (before your attack), you may use this power. Claydol ex\'s type is Fighting until the end of your turn.\", \'type\': \'Poké-Power\'}]', '', 'Ryo Ueda', '[{\'name\': \'Psychic Boom\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20+\', \'text\': \'Does 20 damage plus 10 more damage for each Energy attached to the Defending Pokémon.\'}, {\'name\': \'Shadow Crush\', \'cost\': [\'Psychic\', \'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60\', \'text\': \'You may discard a Psychic Energy card attached to Claydol ex. If you do, discard an Energy card attached to the Defending Pokémon.\'}]', 'Power Keepers', '2', 'Baltoy', '', '', 'Third', '120', 'https://images.pokemoncard.io/images/ex16/ex16-93.png', 'unlimited: Legal', '', 'Claydol ex', '344', 'TPCI', 'Rare Holo EX', '', '02/02/2007', '', 'Colorless, Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '93', 'Stage 1, EX', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2'),
('ex16-94', '[{\'name\': \'Psychic Protector\', \'text\': \"If Flygon ex is damaged by an opponent\'s attack, you may discard up to 4 cards from your hand. If you do, any damage done to Flygon ex is reduced by 10 for each card you discarded.\", \'type\': \'Poké-Body\'}]', '', 'Mitsuhiro Arita', '[{\'name\': \'Slashing Strike\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'70\', \'text\': \"Flip a coin. If tails, Flygon ex can\'t use Slashing Strike during your next turn.\"}]', 'Power Keepers', '', 'Vibrava', '', '', 'Third', '150', 'https://images.pokemoncard.io/images/ex16/ex16-94.png', 'unlimited: Legal', '', 'Flygon ex', '330', 'TPCI', 'Rare Holo EX', '', '02/02/2007', 'type: Lightning, value: -30, type: Fighting, value: -30', '', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '94', 'Stage 2, EX', 'Pokémon', 'Colorless', 'type: Colorless, value: ×2'),
('ex16-95', '[{\'name\': \'Magnetic Redraw\', \'text\': \"Once during your turn (before your attack), if Metagross ex is your Active Pokémon, you may use this power. Each player shuffles his or her hand into his or her deck. Then, each player draws 4 cards. This power can\'t be used if Metagross ex is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Ryo Ueda', '[{\'name\': \'Scanblast\', \'cost\': [\'Metal\', \'Metal\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'70\', \'text\': \"Does 70 damage to each of your opponent\'s Benched Pokémon that has the same name as the Defending Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'Power Keepers', '4', 'Metang', '', '', 'Third', '150', 'https://images.pokemoncard.io/images/ex16/ex16-95.png', 'unlimited: Legal', '', 'Metagross ex', '376', 'TPCI', 'Rare Holo EX', '', '02/02/2007', 'type: Grass, value: -30', 'Colorless, Colorless, Colorless, Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '95', 'Stage 2, EX', 'Pokémon', 'Metal', 'type: Fire, value: ×2'),
('ex16-96', '', '', 'Mitsuhiro Arita', '[{\'name\': \'Volcanic Flame\', \'cost\': [\'Fire\', \'Fire\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'150\', \'text\': \'Discard the top 5 cards from your deck.\'}, {\'name\': \'Hydro Wave\', \'cost\': [\'Water\', \'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'\', \'text\': \"Discard all Water Energy attached to Salamence ex. This attack does 30 damage to each of your opponent\'s Benched Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'Power Keepers', '2', 'Shelgon', '', '', 'Third', '160', 'https://images.pokemoncard.io/images/ex16/ex16-96.png', 'unlimited: Legal', '', 'Salamence ex', '373', 'TPCI', 'Rare Holo EX', '', '02/02/2007', 'type: Fire, value: -30, type: Fighting, value: -30', 'Colorless, Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '96', 'Stage 2, EX', 'Pokémon', 'Colorless', 'type: Colorless, value: ×2'),
('ex16-97', '', '', 'Ryo Ueda', '[{\'name\': \'Skill Hack\', \'cost\': [\'Darkness\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Look at your opponent\'s hand and choose a Basic Pokémon or Evolution card you find there. Choose 1 of that Pokémon\'s attacks. Skill Hack copies that attack except for its Energy cost. (You must still do anything else required for that attack.) (No matter what type that Pokémon is, Shiftry ex\'s type is still Darkness.) Shiftry ex performs that attack.\"}, {\'name\': \'Dirge\', \'cost\': [\'Darkness\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60\', \'text\': \"Does 60 damage to each of your opponent\'s Benched Pokémon that has the same name as the Defending Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'Power Keepers', '1', 'Nuzleaf', '', '', 'Third', '140', 'https://images.pokemoncard.io/images/ex16/ex16-97.png', 'unlimited: Legal', '', 'Shiftry ex', '275', 'TPCI', 'Rare Holo EX', '', '02/02/2007', 'type: Psychic, value: -30', 'Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '97', 'Stage 2, EX', 'Pokémon', 'Darkness', 'type: Grass, value: ×2'),
('ex16-98', '[{\'name\': \'Metal Gravity\', \'text\': \"If your opponent\'s Active Pokémon retreats and has 40 or more remaining HP, put 3 damage counters on that Pokémon. You can\'t use more than 1 Metal Gravity Poké-Body each turn.\", \'type\': \'Poké-Body\'}]', '', 'Ryo Ueda', '[{\'name\': \'Whirlwind\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'Your opponent switches the Defending Pokémon with 1 of his or her Benched Pokémon.\'}, {\'name\': \'Razor Wing\', \'cost\': [\'Metal\', \'Metal\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60\', \'text\': \'\'}]', 'Power Keepers', '1', '', '', '', 'Third', '100', 'https://images.pokemoncard.io/images/ex16/ex16-98.png', 'unlimited: Legal', '', 'Skarmory ex', '227', 'TPCI', 'Rare Holo EX', '', '02/02/2007', 'type: Grass, value: -30', 'Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '98', 'Basic, EX', 'Pokémon', 'Metal', 'type: Fire, value: ×2'),
('ex16-99', '[{\'name\': \'Chilling Breath\', \'text\': \"Once during your turn, when you play Walrein ex from your hand to evolve 1 of your Pokémon, you may use this power. Your opponent can\'t play any Trainer cards from his or her hand during your opponent\'s next turn.\", \'type\': \'Poké-Power\'}]', '', 'Ryo Ueda', '[{\'name\': \'Wreck\', \'cost\': [\'Water\', \'Water\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'70+\', \'text\': \'If there is any Stadium card in play, this attack does 70 damage plus 20 more damage. Discard that Stadium card.\'}]', 'Power Keepers', '3', 'Sealeo', '', '', 'Third', '150', 'https://images.pokemoncard.io/images/ex16/ex16-99.png', 'unlimited: Legal', '', 'Walrein ex', '365', 'TPCI', 'Rare Holo EX', '', '02/02/2007', '', 'Colorless, Colorless, Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '99', 'Stage 2, EX', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('ex2-1', '[{\'name\': \'Primal Veil\', \'text\': \"As long as Armaldo is your Active Pokémon, each player can\'t play any Supporter Cards.\", \'type\': \'Poké-Body\'}]', '', 'Mitsuhiro Arita', '[{\'name\': \'Blade Arms\', \'cost\': [\'Fighting\', \'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60\', \'text\': \'\'}]', 'Sandstorm', '3', 'Anorith', '', '', 'Third', '120', 'https://images.pokemoncard.io/images/ex2/ex2-1.png', 'unlimited: Legal', '', 'Armaldo', '348', 'TPCI', 'Rare Holo', '', '9/18/2003', '', 'Colorless, Colorless, Colorless', '', 'EX', '1', 'Stage 2', 'Pokémon', 'Fighting', 'type: Grass, value: ×2'),
('ex2-10', '', '', 'Hajime Kusajima', '[{\'name\': \'Supernatural\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Look at your opponent\'s hand. You may use the effect of a Supporter card you find there as the effect of this attack. (The Supporter card remains in your opponent\'s hand.)\"}, {\'name\': \'Dark Bind\', \'cost\': [\'Darkness\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'You may discard a Darkness Energy card attached to Sableye. If you do, the Defending Pokémon is now Paralyzed.\'}]', 'Sandstorm', '1', '', '', '', 'Third', '60', 'https://images.pokemoncard.io/images/ex2/ex2-10.png', 'unlimited: Legal', '', 'Sableye', '302', 'TPCI', 'Rare Holo', '', '9/18/2003', '', 'Colorless', '', 'EX', '10', 'Basic', 'Pokémon', 'Darkness', 'type: Fighting, value: ×2'),
('ex2-100', '', '', 'Ryo Ueda', '[{\'name\': \'Super Deep Dive\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"If you don\'t have any Benched Pokémon, this attack does nothing. Remove 3 damage counters from Wailord ex. Switch Wailord ex with 1 of your Benched Pokémon.\"}, {\'name\': \'Dwindling Wave\', \'cost\': [\'Water\', \'Water\', \'Water\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'100-\', \'text\': \'Does 100 damage minus 10 damage for each damage counter on Wailord ex.\'}]', 'Sandstorm', '5', 'Wailmer', '', '', 'Third', '200', 'https://images.pokemoncard.io/images/ex2/ex2-100.png', 'unlimited: Legal', '', 'Wailord ex', '321', 'TPCI', 'Rare Holo EX', '', '9/18/2003', '', 'Colorless, Colorless, Colorless, Colorless, Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '100', 'Stage 1, EX', 'Pokémon', 'Water', 'type: Grass, value: ×2, type: Lightning, value: ×2'),
('ex2-11', '', '', 'Hajime Kusajima', '[{\'name\': \'Deadly Poison\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'You may discard a Grass Energy card attached to Seviper. If you do, the Defending Pokémon is now Poisoned.\'}, {\'name\': \'Extra Poison\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'If the Defending Pokémon is Pokémon-ex, the Defending Pokémon is now Asleep and Poisoned.\'}]', 'Sandstorm', '2', '', '', '', 'Third', '80', 'https://images.pokemoncard.io/images/ex2/ex2-11.png', 'unlimited: Legal', '', 'Seviper', '336', 'TPCI', 'Rare Holo', '', '9/18/2003', '', 'Colorless, Colorless', '', 'EX', '11', 'Basic', 'Pokémon', 'Grass', 'type: Psychic, value: ×2'),
('ex2-12', '[{\'name\': \'Fan Away\', \'text\': \"Once during your turn (before your attack), you may flip a coin. If heads, return 1 Energy card attached to the Defending Pokémon to your opponent\'s hand. This power can\'t be used if Shiftry is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Atsuko Nishida', '[{\'name\': \'Light Touch Throw\', \'cost\': [\'Grass\', \'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'80-\', \'text\': \'Does 80 damage minus 10 damage for each Energy attached to the Defending Pokémon.\'}]', 'Sandstorm', '2', 'Nuzleaf', '', '', 'Third', '120', 'https://images.pokemoncard.io/images/ex2/ex2-12.png', 'unlimited: Legal', '', 'Shiftry', '275', 'TPCI', 'Rare Holo', '', '9/18/2003', '', 'Colorless, Colorless', '', 'EX', '12', 'Stage 2', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('ex2-13', '[{\'name\': \'Solar Eclipse\', \'text\': \"Once during your turn (before your attack), if Lunatone is in play, you may use this power. Until the end of your turn, Solrock\'s type is Fire. This power can\'t be used if Solrock is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Hajime Kusajima', '[{\'name\': \'Cosmic Draw\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'If your opponent has any Evolved Pokémon in play, draw 3 cards.\'}, {\'name\': \'Solar Blast\', \'cost\': [\'Fighting\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40\', \'text\': \'\'}]', 'Sandstorm', '1', '', '', '', 'Third', '70', 'https://images.pokemoncard.io/images/ex2/ex2-13.png', 'unlimited: Legal', '', 'Solrock', '338', 'TPCI', 'Rare Holo', '', '9/18/2003', '', 'Colorless', '', 'EX', '13', 'Basic', 'Pokémon', 'Fighting', 'type: Grass, value: ×2'),
('ex2-14', '[{\'name\': \'Poison Resistance\', \'text\': \"Zangoose can\'t be Poisoned.\", \'type\': \'Poké-Body\'}]', '', 'Kagemaru Himeno', '[{\'name\': \'Target Slash\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10+\', \'text\': \'If the Defending Pokémon is Seviper, this attack does 10 damage plus 30 more damage.\'}, {\'name\': \'Super Slash\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'30+\', \'text\': \'If the Defending Pokémon is an Evolved Pokémon, this attack does 30 damage plus 30 more damage.\'}]', 'Sandstorm', '1', '', '', '', 'Third', '70', 'https://images.pokemoncard.io/images/ex2/ex2-14.png', 'unlimited: Legal', '', 'Zangoose', '335', 'TPCI', 'Rare Holo', '', '9/18/2003', '', 'Colorless', '', 'EX', '14', 'Basic', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('ex2-15', '[{\'name\': \'Fire Veil\', \'text\': \"If Arcanine is your Active Pokémon and is damaged by an opponent\'s attack (even if Arcanine is Knocked Out), the Attacking Pokémon is now Burned.\", \'type\': \'Poké-Body\'}]', '', 'Hajime Kusajima', '[{\'name\': \'Burn Up\', \'cost\': [\'Fire\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60\', \'text\': \'Flip a coin. If tails, discard all Fire Energy cards attached to Arcanine.\'}]', 'Sandstorm', '1', 'Growlithe', '', '', 'Third', '80', 'https://images.pokemoncard.io/images/ex2/ex2-15.png', 'unlimited: Legal', '', 'Arcanine', '59', 'TPCI', 'Rare', '', '9/18/2003', '', 'Colorless', '', 'EX', '15', 'Stage 1', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('ex2-16', '', '', 'Mitsuhiro Arita', '[{\'name\': \'Confuse Ray\', \'cost\': [\'Psychic\'], \'convertedEnergyCost\': 1, \'damage\': \'20\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Confused.\'}, {\'name\': \'Energy Crush\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'20+\', \'text\': \"Does 20 more damage plus 10 more damage for each Energy attached to all of your opponent\'s Pokémon.\"}]', 'Sandstorm', '1', 'Eevee', '', '', 'Third', '80', 'https://images.pokemoncard.io/images/ex2/ex2-16.png', 'unlimited: Legal', '', 'Espeon', '196', 'TPCI', 'Rare', '', '9/18/2003', '', 'Colorless', '', 'EX', '16', 'Stage 1', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2'),
('ex2-17', '[{\'name\': \'Chaos Flash\', \'text\': \"Once during your turn (before your attack), if Golduck is your Active Pokémon, you may flip a coin. If heads, the Defending Pokémon (choose 1 if there are 2) is now Confused. This power can\'t be used if Golduck is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Hajime Kusajima', '[{\'name\': \'Special Blow\', \'cost\': [\'Water\', \'Psychic\'], \'convertedEnergyCost\': 2, \'damage\': \'30+\', \'text\': \'If the Defending Pokémon has any Special Energy cards attached to it, this attack does 30 damage plus 40 more damage.\'}]', 'Sandstorm', '1', 'Psyduck', '', '', 'Third', '70', 'https://images.pokemoncard.io/images/ex2/ex2-17.png', 'unlimited: Legal', '', 'Golduck', '55', 'TPCI', 'Rare', '', '9/18/2003', '', 'Colorless', '', 'EX', '17', 'Stage 1', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('ex2-18', '[{\'name\': \'Energy Variation\', \'text\': \"Kecleon\'s type is the same as every type of basic Energy card attached to Kecleon.\", \'type\': \'Poké-Body\'}]', '', 'Kagemaru Himeno', '[{\'name\': \'Double Scratch\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20×\', \'text\': \'Flip 2 coins. This attack does 20 damage times the number of heads.\'}]', 'Sandstorm', '1', '', '', '', 'Third', '60', 'https://images.pokemoncard.io/images/ex2/ex2-18.png', 'unlimited: Legal', '', 'Kecleon', '352', 'TPCI', 'Rare', '', '9/18/2003', '', 'Colorless', '', 'EX', '18', 'Basic', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('ex2-19', '', '', 'Kouki Saitou', '[{\'name\': \'Pull Down\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'If your opponent has any Evolved Pokémon in play, remove the highest Stage Evolution card from each of them and put those cards back into his or her hand.\'}, {\'name\': \'Hydrocannon\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30+\', \'text\': \"Does 30 damage plus 20 more damage for each Water Energy attached to Omastar but not used to pay for this attack\'s Energy cost. You can\'t add more than 40 damage in this way.\"}]', 'Sandstorm', '2', 'Omanyte', '', '', 'Third', '110', 'https://images.pokemoncard.io/images/ex2/ex2-19.png', 'unlimited: Legal', '', 'Omastar', '139', 'TPCI', 'Rare', '', '9/18/2003', '', 'Colorless, Colorless', '', 'EX', '19', 'Stage 2', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('ex2-2', '[{\'name\': \'Poison Payback\', \'text\': \"If Cacturne is your Active Pokémon and is damaged by an opponent\'s attack (even if Cacturne is Knocked Out), the Attacking Pokémon is now Poisoned.\", \'type\': \'Poké-Body\'}]', '', 'Atsuko Nishida', '[{\'name\': \'Feint Attack\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'\', \'text\': \"Choose 1 of your opponent\'s Pokémon. This attack does 40 damage to that Pokémon. This attack\'s damage isn\'t affected by Weakness, Resistance, Poké-Powers, Poké-Bodies or any other effects on that Pokémon.\"}]', 'Sandstorm', '1', 'Cacnea', '', '', 'Third', '80', 'https://images.pokemoncard.io/images/ex2/ex2-2.png', 'unlimited: Legal', '', 'Cacturne', '332', 'TPCI', 'Rare Holo', '', '9/18/2003', '', 'Colorless', '', 'EX', '2', 'Stage 1', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('ex2-20', '[{\'name\': \'Baby Evolution\', \'text\': \'Once during your turn (before your attack), you may put Pikachu from your hand onto Pichu (this counts as evolving Pichu) and remove all damage counters from Pichu.\', \'type\': \'Poké-Power\'}]', '', 'Naoyo Kimura', '[{\'name\': \'Energy Retrieval\', \'cost\': [\'Lightning\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Search your discard pile for up to 2 basic Energy cards and attach them to 1 of your Pokémon. Put 1 damage counter on that Pokémon for each Energy card attached in this way.\'}]', 'Sandstorm', '1', '', 'Pikachu', '', 'Third', '40', 'https://images.pokemoncard.io/images/ex2/ex2-20.png', 'unlimited: Legal', '', 'Pichu', '172', 'TPCI', 'Rare', '', '9/18/2003', '', 'Colorless', '', 'EX', '20', 'Basic', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
('ex2-21', '', '', 'Kouki Saitou', '[{\'name\': \'Sand Swirl\', \'cost\': [\'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'\', \'text\': \"Does 20 damage to each Defending Pokémon. The Defending Pokémon can\'t retreat until the end of your opponent\'s next turn.\"}, {\'name\': \'Earthquake\', \'cost\': [\'Fighting\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60\', \'text\': \"Does 10 damage to each of your Benched Pokémon. (Don\'t apply Weakness or Resistance for Benched Pokémon.)\"}]', 'Sandstorm', '', 'Sandshrew', '', '', 'Third', '70', 'https://images.pokemoncard.io/images/ex2/ex2-21.png', 'unlimited: Legal', '', 'Sandslash', '28', 'TPCI', 'Rare', '', '9/18/2003', '', '', '', 'EX', '21', 'Stage 1', 'Pokémon', 'Fighting', 'type: Grass, value: ×2'),
('ex2-22', '', '', 'Ken Sugimori', '[{\'name\': \'Feint Attack\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'\', \'text\': \"Choose 1 of your opponent\'s Pokémon. This attack does 40 damage to that Pokémon. This attack\'s damage isn\'t affected by Weakness, Resistance, Poké-Powers, Poké-Bodies, or any other effects on that Pokémon.\"}, {\'name\': \'Slash\', \'cost\': [\'Grass\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'60\', \'text\': \'\'}]', 'Sandstorm', '2', 'Nuzleaf', '', '', 'Third', '120', 'https://images.pokemoncard.io/images/ex2/ex2-22.png', 'unlimited: Legal', '', 'Shiftry', '275', 'TPCI', 'Rare', '', '9/18/2003', '', 'Colorless, Colorless', '', 'EX', '22', 'Stage 2', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('ex2-23', '', '', 'Midori Harada', '[{\'name\': \'Rage\', \'cost\': [\'Fighting\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'10+\', \'text\': \'Does 10 damage plus 10 more damage for each damage counter on Steelix.\'}, {\'name\': \'Spinning Tail\', \'cost\': [\'Metal\', \'Metal\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'\', \'text\': \"Does 20 damage to each of your opponent\'s Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'Sandstorm', '4', 'Onix', '', '', 'Third', '100', 'https://images.pokemoncard.io/images/ex2/ex2-23.png', 'unlimited: Legal', '', 'Steelix', '208', 'TPCI', 'Rare', '', '9/18/2003', 'type: Grass, value: -30', 'Colorless, Colorless, Colorless, Colorless', '', 'EX', '23', 'Stage 1', 'Pokémon', 'Metal', 'type: Fire, value: ×2'),
('ex2-24', '', '', 'Kagemaru Himeno', '[{\'name\': \'Confuse Ray\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Confused.\'}, {\'name\': \'Moon Impact\', \'cost\': [\'Darkness\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40\', \'text\': \'\'}]', 'Sandstorm', '1', 'Eevee', '', '', 'Third', '80', 'https://images.pokemoncard.io/images/ex2/ex2-24.png', 'unlimited: Legal', '', 'Umbreon', '197', 'TPCI', 'Rare', '', '9/18/2003', 'type: Psychic, value: -30', 'Colorless', '', 'EX', '24', 'Stage 1', 'Pokémon', 'Darkness', 'type: Fighting, value: ×2'),
('ex2-25', '', '', 'Hajime Kusajima', '[{\'name\': \'Aurora Beam\', \'cost\': [\'Water\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'\'}, {\'name\': \'Aqua Sonic\', \'cost\': [\'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50\', \'text\': \"This attack\'s damage is not affected by Resistance.\"}]', 'Sandstorm', '1', 'Eevee', '', '', 'Third', '70', 'https://images.pokemoncard.io/images/ex2/ex2-25.png', 'unlimited: Legal', '', 'Vaporeon', '134', 'TPCI', 'Rare', '', '9/18/2003', '', 'Colorless', '', 'EX', '25', 'Stage 1', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('ex2-26', '[{\'name\': \'Safeguard\', \'text\': \"Prevent all effects of attacks, including damage, done to Wobbuffet by your opponent\'s Pokémon-ex.\", \'type\': \'Poké-Body\'}]', '', 'Atsuko Nishida', '[{\'name\': \'Flip Over\', \'cost\': [\'Psychic\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50\', \'text\': \"Wobbuffet does 10 damage to itself, and don\'t apply Weakness and Resistance to this damage.\"}]', 'Sandstorm', '2', '', '', '', 'Third', '80', 'https://images.pokemoncard.io/images/ex2/ex2-26.png', 'unlimited: Legal', '', 'Wobbuffet', '202', 'TPCI', 'Rare', '', '9/18/2003', '', 'Colorless, Colorless', '', 'EX', '26', 'Basic', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2'),
