('ex2-30', '', '', 'Mitsuhiro Arita', '[{\'name\': \'Drizzle\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'If you have Water Energy cards in your hand, attach as many Water Energy cards as you like to any of your Active Pokémon.\'}, {\'name\': \'Max Bubbles\', \'cost\': [\'Water\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30×\', \'text\': \'Flip a coin for each Energy attached to all of your Active Pokémon. This attack does 30 damage times the number of heads.\'}]', 'Sandstorm', '1', 'Marill', '', '', 'Third', '70', 'https://images.pokemoncard.io/images/ex2/ex2-30.png', 'unlimited: Legal', '', 'Azumarill', '184', 'TPCI', 'Uncommon', '', '9/18/2003', '', 'Colorless', '', 'EX', '30', 'Stage 1', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('ex2-31', '[{\'name\': \'Baby Evolution\', \'text\': \'Once during your turn (before your attack), you may put Marill from your hand onto Azurill (this counts as evolving Azurill), and remove all damage counters from Azurill.\', \'type\': \'Poké-Power\'}]', '', 'Kagemaru Himeno', '[{\'name\': \'Jump Catch\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Search your deck for a Trainer card, show it to your opponent, and put it into your hand. Shuffle your deck afterward.\'}]', 'Sandstorm', '1', '', 'Marill', '', 'Third', '40', 'https://images.pokemoncard.io/images/ex2/ex2-31.png', 'unlimited: Legal', '', 'Azurill', '298', 'TPCI', 'Uncommon', '', '9/18/2003', '', 'Colorless', '', 'EX', '31', 'Basic', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('ex2-32', '', '', 'Midori Harada', '[{\'name\': \'Rapid Spin\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'Your opponent switches the Defending Pokémon with 1 of his or her Benched Pokémon, if any. You switch Baltoy with 1 of your Benched Pokémon, if any.\'}]', 'Sandstorm', '1', '', 'Claydol', '', 'Third', '50', 'https://images.pokemoncard.io/images/ex2/ex2-32.png', 'unlimited: Legal', '', 'Baltoy', '343', 'TPCI', 'Uncommon', '', '9/18/2003', '', 'Colorless', '', 'EX', '32', 'Basic', 'Pokémon', 'Fighting', 'type: Grass, value: ×2'),
('ex2-33', '', '', 'Atsuko Nishida', '[{\'name\': \'Super Poison Breath\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Each Defending Pokémon is now Poisoned.\'}, {\'name\': \'Sky Uppercut\', \'cost\': [\'Fighting\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50\', \'text\': \"This attack\'s damage is not affected by Resistance.\"}]', 'Sandstorm', '1', 'Shroomish', '', '', 'Third', '70', 'https://images.pokemoncard.io/images/ex2/ex2-33.png', 'unlimited: Legal', '', 'Breloom', '286', 'TPCI', 'Uncommon', '', '9/18/2003', '', 'Colorless', '', 'EX', '33', 'Stage 1', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('ex2-34', '', '', 'Midori Harada', '[{\'name\': \'Scratch\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'\'}, {\'name\': \'Ultra Energy Source\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'10×\', \'text\': \"Does 10 damage times the number of basic Energy cards attached to all of the Active Pokémon (both yours and your opponent\'s).\"}]', 'Sandstorm', '1', 'Skitty', '', '', 'Third', '80', 'https://images.pokemoncard.io/images/ex2/ex2-34.png', 'unlimited: Legal', '', 'Delcatty', '301', 'TPCI', 'Uncommon', '', '9/18/2003', '', 'Colorless', '', 'EX', '34', 'Stage 1', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('ex2-35', '', '', 'Kouki Saitou', '[{\'name\': \'Plasma\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'Flip a coin. If heads, search your discard pile for a Lightning Energy card and attach it to Electabuzz.\'}, {\'name\': \'Thunder Spear\', \'cost\': [\'Lightning\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'\', \'text\': \"Choose 1 of your opponent\'s Pokémon. This attack does 40 damage to that Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'Sandstorm', '1', '', 'Electivire', '', 'Third', '60', 'https://images.pokemoncard.io/images/ex2/ex2-35.png', 'unlimited: Legal', '', 'Electabuzz', '125', 'TPCI', 'Uncommon', '', '9/18/2003', 'type: Metal, value: -30', 'Colorless', '', 'EX', '35', 'Basic', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
('ex2-36', '[{\'name\': \'Baby Evolution\', \'text\': \'Once during your turn (before your attack), you may put Electabuzz from your hand onto Elekid (this counts as evolving Elekid) and remove all damage counters from Elekid.\', \'type\': \'Poké-Power\'}]', '', 'Kouki Saitou', '[{\'name\': \'Gather Energy\', \'cost\': [\'Lightning\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Search your deck for a basic Energy card and attach it to 1 of your Pokémon. Shuffle your deck afterward.\'}]', 'Sandstorm', '1', '', 'Electabuzz', '', 'Third', '40', 'https://images.pokemoncard.io/images/ex2/ex2-36.png', 'unlimited: Legal', '', 'Elekid', '239', 'TPCI', 'Uncommon', '', '9/18/2003', '', 'Colorless', '', 'EX', '36', 'Basic', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
('ex2-37', '', '', 'Aya Kusube', '[{\'name\': \'Double Wing Attack\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'\', \'text\': \'Does 20 damage to each Defending Pokémon.\'}, {\'name\': \'Rend\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'30+\', \'text\': \'If the Defending Pokémon has any damage counters on it, this attack does 30 damage plus 20 more damage.\'}]', 'Sandstorm', '', 'Spearow', '', '', 'Third', '70', 'https://images.pokemoncard.io/images/ex2/ex2-37.png', 'unlimited: Legal', '', 'Fearow', '22', 'TPCI', 'Uncommon', '', '9/18/2003', 'type: Fighting, value: -30', '', '', 'EX', '37', 'Stage 1', 'Pokémon', 'Colorless', 'type: Lightning, value: ×2'),
('ex2-38', '[{\'name\': \'Glowing Screen\', \'text\': \"As long as Volbeat is in play, any damage done to Illumise by attacks from Fighting Pokémon and Darkness Pokémon is reduced by 30. You can\'t reduce more than 30 damage even if there is more than 1 Volbeat in play.\", \'type\': \'Poké-Body\'}]', '', 'Kyoko Umemoto', '[{\'name\': \'Chaotic Noise\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Confused. If tails, the Defending Pokémon is now Asleep.\'}, {\'name\': \'Pester\', \'cost\': [\'Grass\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20+\', \'text\': \'If the Defending Pokémon is affected by a Special Condition, this attack does 20 damage plus 20 more damage.\'}]', 'Sandstorm', '1', '', '', '', 'Third', '60', 'https://images.pokemoncard.io/images/ex2/ex2-38.png', 'unlimited: Legal', '', 'Illumise', '314', 'TPCI', 'Uncommon', '', '9/18/2003', '', 'Colorless', '', 'EX', '38', 'Basic', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('ex2-39', '[{\'name\': \'Exoskeleton\', \'text\': \'Any damage done to Kabuto by attacks is reduced by 20 (after applying Weakness and Resistance).\', \'type\': \'Poké-Body\'}]', '', 'Atsuko Nishida', '[{\'name\': \'Team Assembly\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Search your deck for Omanyte, Kabuto, or any Basic Pokémon and put as many of them as you like onto your Bench. Shuffle your deck afterward. Treat the new Benched Pokémon as Basic Pokémon.\'}, {\'name\': \'Pierce\', \'cost\': [\'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'\'}]', 'Sandstorm', '2', 'Mysterious Fossil', 'Kabutops', '', 'Third', '60', 'https://images.pokemoncard.io/images/ex2/ex2-39.png', 'unlimited: Legal', '', 'Kabuto', '140', 'TPCI', 'Uncommon', '', '9/18/2003', '', 'Colorless, Colorless', '', 'EX', '39', 'Stage 1', 'Pokémon', 'Water', 'type: Grass, value: ×2'),
