('ex4-66', '', '', 'Shin-ichi Yoshikawa', '[{\'name\': \'Darkness Call\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Your opponent switches the Defending Pokémon with 1 of his or her Benched Pokémon, if any.\'}, {\'name\': \'Sharp Fang\', \'cost\': [\'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'\'}]', 'Team Magma vs Team Aqua', '1', '', 'Mightyena', '', 'Third', '50', 'https://images.pokemoncard.io/images/ex4/ex4-66.png', 'unlimited: Legal', '', 'Team Magmas Poochyena', '261', 'TPCI', 'Common', '', '03/01/2004', 'type: Psychic, value: -30', 'Colorless', '', 'EX', '66', 'Basic', 'Pokémon', 'Darkness', 'type: Fighting, value: ×2'),
('ex4-67', '', '', 'Yosuke Da Silva', '[{\'name\': \'Double Stab\', \'cost\': [\'Fighting\'], \'convertedEnergyCost\': 1, \'damage\': \'10×\', \'text\': \'Flip 2 coins. This attack does 10 damage times the number of heads.\'}, {\'name\': \'Second Strike\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'10+\', \'text\': \'If the Defending Pokémon already has at least 2 damage counters on it, this attack does 10 damage plus 20 more damage.\'}]', 'Team Magma vs Team Aqua', '1', '', 'Rhydon', '', 'Third', '50', 'https://images.pokemoncard.io/images/ex4/ex4-67.png', 'unlimited: Legal', '', 'Team Magmas Rhyhorn', '111', 'TPCI', 'Common', '', '03/01/2004', '', 'Colorless', '', 'EX', '67', 'Basic', 'Pokémon', 'Fighting', 'type: Grass, value: ×2'),
('ex4-68', '', '', 'Yosuke Da Silva', '[{\'name\': \'Ram\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'\'}, {\'name\': \'Knock Over\', \'cost\': [\'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'10\', \'text\': \'You may discard any Stadium card in play.\'}]', 'Team Magma vs Team Aqua', '2', '', 'Rhydon', '', 'Third', '60', 'https://images.pokemoncard.io/images/ex4/ex4-68.png', 'unlimited: Legal', '', 'Team Magmas Rhyhorn', '111', 'TPCI', 'Common', '', '03/01/2004', '', 'Colorless, Colorless', '', 'EX', '68', 'Basic', 'Pokémon', 'Fighting', 'type: Grass, value: ×2'),
('ex4-69', '', '', 'Ken Sugimori', '', 'Team Magma vs Team Aqua', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex4/ex4-69.png', 'unlimited: Legal', '', 'Team Aqua Schemer', '', 'TPCI', 'Common', '', '03/01/2004', '', '', '[\'You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.\', \'Discard any 1 Pokémon from your hand. Then draw 3 cards. If you discarded a Pokémon with Team Aqua in its name, draw 4 cards instead.\']', 'EX', '69', 'Supporter', 'Trainer', '', ''),
('ex4-7', '', '', 'Hiromichi Sugiyama', '[{\'name\': \'Crush\', \'cost\': [\'Fighting\'], \'convertedEnergyCost\': 1, \'damage\': \'30×\', \'text\': \"Flip a coin for each Energy attached to Team Magma\'s Aggron. This attack does 30 damage times the number of heads.\"}, {\'name\': \'Land Stream\', \'cost\': [\'Fighting\', \'Fighting\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'50+\', \'text\': \"You may discard any number of basic Energy cards attached to Team Magma\'s Aggron. If you do, this attack does 50 damage plus 20 more damage for each basic Energy card you discarded.\"}]', 'Team Magma vs Team Aqua', '2', 'Team Magmas Lairon', '', '', 'Third', '120', 'https://images.pokemoncard.io/images/ex4/ex4-7.png', 'unlimited: Legal', '', 'Team Magmas Aggron', '306', 'TPCI', 'Rare Holo', '', '03/01/2004', '', 'Colorless, Colorless', '[\'This Pokémon is both Fighting Darkness type.\']', 'EX', '7', 'Stage 2', 'Pokémon', 'Fighting, Darkness', 'type: Grass, value: ×2, type: Water, value: ×2'),
('ex4-70', '', '', 'Ken Sugimori', '', 'Team Magma vs Team Aqua', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex4/ex4-70.png', 'unlimited: Legal', '', 'Team Magma Schemer', '', 'TPCI', 'Common', '', '03/01/2004', '', '', '[\'You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.\', \'Discard any 1 Pokémon from your hand. Then draw 3 cards. If you discarded a Pokémon with Team Magma in its name, draw 4 cards instead.\']', 'EX', '70', 'Supporter', 'Trainer', '', ''),
('ex4-71', '', '', 'Ken Sugimori', '', 'Team Magma vs Team Aqua', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex4/ex4-71.png', 'unlimited: Legal', '', 'Archie', '', 'TPCI', 'Uncommon', '', '03/01/2004', '', '', '[\'You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.\', \'Search your deck for a Pokémon with Team Aqua in its name and put it onto your Bench. Shuffle your deck afterward. Treat the new Benched Pokémon as a Basic Pokémon. If it is a Stage 2 Pokémon, put 2 damage counters on that Pokémon.\']', 'EX', '71', 'Supporter', 'Trainer', '', ''),
('ex4-72', '', '', 'Big Mama Tagawa', '', 'Team Magma vs Team Aqua', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex4/ex4-72.png', 'unlimited: Legal', '', 'Dual Ball', '', 'TPCI', 'Uncommon', '', '03/01/2004', '', '', '[\'Flip 2 coins. For each heads, search your deck for a Basic Pokémon card, show it to your opponent, and put it into your hand. Shuffle your deck afterward.\']', 'EX', '72', 'Item', 'Trainer', '', ''),
('ex4-73', '', '', 'Ken Sugimori', '', 'Team Magma vs Team Aqua', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex4/ex4-73.png', 'unlimited: Legal', '', 'Maxie', '', 'TPCI', 'Uncommon', '', '03/01/2004', '', '', '[\'You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.\', \'Search your hand or discard pile for a Pokémon with Team Magma in its name and put it onto your Bench. Treat the new Benched Pokémon as a Basic Pokémon. If it is a Stage 2 Pokémon, put 2 damage counters on that Pokémon.\']', 'EX', '73', 'Supporter', 'Trainer', '', ''),
('ex4-74', '', '', 'Keiji Kinebuchi', '', 'Team Magma vs Team Aqua', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex4/ex4-74.png', 'unlimited: Legal', '', 'Strength Charm', '', 'TPCI', 'Uncommon', '', '03/01/2004', '', '', '[\"Attach Strength Charm to 1 of your Pokémon that doesn\'t already have a Pokémon Tool attached to it. If that Pokémon is Knocked Out, discard this card.\", \'Whenever an attack from the Pokémon that Strength Charm is attached to does damage to the Active Pokémon (after applying Weakness and Resistance), the attack does 10 more damage. At the end of the turn in which this happens, discard Strength Charm.\']', 'EX', '74', 'Pokémon Tool', 'Trainer', '', ''),
('ex4-75', '', '', 'Ryo Ueda', '', 'Team Magma vs Team Aqua', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex4/ex4-75.png', 'unlimited: Legal', '', 'Team Aqua Ball', '', 'TPCI', 'Uncommon', '', '03/01/2004', '', '', '[\'Flip a coin. If heads, search your deck for a Pokémon that has Team Aqua in its name, show it to your opponent, and put it into your hand. If tails, search your deck for a Basic Pokémon that has Team Aqua in its name, show it to your opponent and put it into your hand. Shuffle your deck afterward.\']', 'EX', '75', 'Item', 'Trainer', '', ''),
('ex4-76', '', '', 'Mitsuhiro Arita', '', 'Team Magma vs Team Aqua', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex4/ex4-76.png', 'unlimited: Legal', '', 'Team Aqua Belt', '', 'TPCI', 'Uncommon', '', '03/01/2004', '', '', '[\"Attach Team Aqua Belt to 1 of your Pokémon with Team Aqua in its name that doesn\'t already have a Pokémon Tool attached to it. If that Pokémon is Knocked Out, discard this card.\", \'At any time between turns, if the Pokémon Team Aqua Belt is attached to is your Active Pokémon, search your deck for a card that evolves from that Pokémon and put it on that Pokémon. (This counts as evolving that Pokémon.) Shuffle your deck afterward, then discard Team Aqua Belt.\']', 'EX', '76', 'Pokémon Tool', 'Trainer', '', ''),
('ex4-77', '', '', 'Ken Sugimori', '', 'Team Magma vs Team Aqua', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex4/ex4-77.png', 'unlimited: Legal', '', 'Team Aqua Conspirator', '', 'TPCI', 'Uncommon', '', '03/01/2004', '', '', '[\'You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.\', \'Search your deck for up to 2 in any combination of Basic Pokémon with Team Aqua in its name and basic Energy cards, show them to your opponent, and put them into your hand. Shuffle your deck afterward.\']', 'EX', '77', 'Supporter', 'Trainer', '', ''),
('ex4-78', '', '', 'Hiromichi Sugiyama', '', 'Team Magma vs Team Aqua', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex4/ex4-78.png', 'unlimited: Legal', '', 'Team Aqua Hideout', '', 'TPCI', 'Uncommon', '', '03/01/2004', '', '', '[\'This card stays in play when you play it. Discard this card if another Stadium card comes into play.\', \'Each Pokémon that does not have Team Aqua in its name pays Colorless more to retreat.\']', 'EX', '78', 'Stadium', 'Trainer', '', ''),
('ex4-79', '', '', 'Mitsuhiro Arita', '[{\'name\': \'Miracle\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'Choose 1 Special Condition. The Defending Pokémon is now affected by that Special Condition.\'}]', 'Team Magma vs Team Aqua', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex4/ex4-79.png', 'unlimited: Legal', '', 'Team Aqua Technical Machine 01', '', 'TPCI', 'Uncommon', '', '03/01/2004', '', '', '[\"Attach this card to 1 of your Pokémon that has Team Aqua in its name. That Pokémon may use this card\'s attack instead of its own. At the end of your turn, discard Team Aqua Technical Machine 01.\"]', 'EX', '79', 'Technical Machine', 'Trainer', '', ''),
('ex4-8', '[{\'name\': \'Magma Switch\', \'text\': \"Once during your turn (before your attack), you may move an Energy card attached to your Pokémon with Team Magma in its name to another of your Pokémon. This power can\'t be used if Team Magma\'s Claydol is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Zu-Ka', '[{\'name\': \'Dark Hand\', \'cost\': [\'Psychic\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40+\', \'text\': \'If you have more cards in your hand than your opponent, this attack does 40 damage plus 20 more damage.\'}]', 'Team Magma vs Team Aqua', '2', 'Team Magmas Baltoy', '', '', 'Third', '80', 'https://images.pokemoncard.io/images/ex4/ex4-8.png', 'unlimited: Legal', '', 'Team Magmas Claydol', '344', 'TPCI', 'Rare Holo', '', '03/01/2004', '', 'Colorless, Colorless', '[\'This Pokémon is both Psychic Darkness type.\']', 'EX', '8', 'Stage 1', 'Pokémon', 'Psychic, Darkness', 'type: Psychic, value: ×2'),
('ex4-80', '', '', 'Ryo Ueda', '', 'Team Magma vs Team Aqua', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex4/ex4-80.png', 'unlimited: Legal', '', 'Team Magma Ball', '', 'TPCI', 'Uncommon', '', '03/01/2004', '', '', '[\'Flip a coin. If heads, search your deck for a Pokémon that has Team Magma in its name, show it to your opponent, and put it into your hand. If tails, search your deck for a Basic Pokémon that has Team Magma in its name, show it to your opponent and put it into your hand. Shuffle your deck afterward.\']', 'EX', '80', 'Item', 'Trainer', '', ''),
('ex4-81', '', '', 'Mitsuhiro Arita', '', 'Team Magma vs Team Aqua', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex4/ex4-81.png', 'unlimited: Legal', '', 'Team Magma Belt', '', 'TPCI', 'Uncommon', '', '03/01/2004', '', '', '[\"Attach Team Magma Belt to 1 of your Pokémon with Team Magma in its name that doesn\'t already have a Pokémon Tool attached to it. If that Pokémon is Knocked Out, discard this card.\", \'At any time between turns, if the Pokémon Team Magma Belt is attached to is your Active Pokémon, search your deck for a card that evolves from that Pokémon and put it on that Pokémon. (This counts as evolving that Pokémon.) Shuffle your deck afterward, then discard Team Magma Belt.\']', 'EX', '81', 'Pokémon Tool', 'Trainer', '', ''),
('ex4-82', '', '', 'Ken Sugimori', '', 'Team Magma vs Team Aqua', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex4/ex4-82.png', 'unlimited: Legal', '', 'Team Magma Conspirator', '', 'TPCI', 'Uncommon', '', '03/01/2004', '', '', '[\'You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.\', \'Search your deck for up to 2 in any combination of Basic Pokémon with Team Magma in its name and basic Energy cards, show them to your opponent, and put them into your hand. Shuffle your deck afterward.\']', 'EX', '82', 'Supporter', 'Trainer', '', ''),
('ex4-83', '', '', 'Ken Ikuji', '', 'Team Magma vs Team Aqua', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex4/ex4-83.png', 'unlimited: Legal', '', 'Team Magma Hideout', '', 'TPCI', 'Uncommon', '', '03/01/2004', '', '', '[\'This card stays in play when you play it. Discard this card if another Stadium card comes into play.\', \"Whenever any player plays a Basic Pokémon that doesn\'t have Team Magma in its name from his or her hand, that player puts 1 damage counter on that Pokémon.\"]', 'EX', '83', 'Stadium', 'Trainer', '', ''),
('ex4-84', '', '', 'Mitsuhiro Arita', '[{\'name\': \'Crushing Magma\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \"Choose an Energy card attached to the Defending Pokémon and put that card at the bottom of your opponent\'s deck.\"}]', 'Team Magma vs Team Aqua', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex4/ex4-84.png', 'unlimited: Legal', '', 'Team Magma Technical Machine 01', '', 'TPCI', 'Uncommon', '', '03/01/2004', '', '', '[\"Attach this card to 1 of your Pokémon that has Team Magma in its name. That Pokémon may use this card\'s attack instead of its own. At the end of your turn, discard Team Magma Technical Machine 01.\"]', 'EX', '84', 'Technical Machine', 'Trainer', '', ''),
('ex4-85', '', '', 'Keiji Kinebuchi', '', 'Team Magma vs Team Aqua', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex4/ex4-85.png', 'unlimited: Legal', '', 'Warp Point', '', 'TPCI', 'Uncommon', '', '03/01/2004', '', '', '[\'Your opponent switches 1 of his or her Defending Pokémon with 1 of his or her Benched Pokémon, if any. You switch 1 of your Active Pokémon with 1 of your Benched Pokémon, if any.\']', 'EX', '85', 'Item', 'Trainer', '', ''),
('ex4-86', '', '', 'Takumi Akabane', '', 'Team Magma vs Team Aqua', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex4/ex4-86.png', 'unlimited: Legal', '', 'Aqua Energy', '', 'TPCI', 'Uncommon', '', '03/01/2004', '', '', '[\"Aqua Energy can be attached only to a Pokémon with Team Aqua in its name. Aqua Energy provides Water and Darkness Energy but provides 2 Energy at a time. (Doesn\'t count as a basic Energy card when not in play and has no other effect than providing Energy.) At the end of your turn, discard Aqua Energy.\"]', 'EX', '86', 'Special', 'Energy', '', ''),
('ex4-87', '', '', 'Takumi Akabane', '', 'Team Magma vs Team Aqua', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex4/ex4-87.png', 'unlimited: Legal', '', 'Magma Energy', '', 'TPCI', 'Uncommon', '', '03/01/2004', '', '', '[\"Magma Energy can be attached only to a Pokémon with Team Magma in its name. Magma Energy provides Fighting and /or Darkness Energy but provides 2 Energy at a time. (Doesn\'t count as a basic Energy card when not in play and has no other effect than providing Energy.) At the end of your turn, discard Magma Energy.\"]', 'EX', '87', 'Special', 'Energy', '', ''),
('ex4-88', '', '', 'Takumi Akabane', '', 'Team Magma vs Team Aqua', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex4/ex4-88.png', 'unlimited: Legal', '', 'Double Rainbow Energy', '', 'TPCI', 'Rare', '', '03/01/2004', '', '', '[\"Double Rainbow Energy can be attached only to an Evolved Pokémon (excluding Pokémon-ex). While in play, Double Rainbow Energy provides every type of Energy but provides 2 Energy at a time. (Doesn\'t count as a basic Energy when not in play and has no effect other than providing Energy.) Damage done to your opponent\'s Pokémon by the Pokémon Double Rainbow Energy is attached to is reduced by 10 (after applying Weakness and Resistance). When the Pokémon Double Rainbow Energy is attached to is no longer an Evolved Pokémon, discard Double Rainbow Energy.\"]', 'EX', '88', 'Special', 'Energy', '', ''),
('ex4-89', '', '', 'Hikaru Koike', '[{\'name\': \'Blaze Kick\', \'cost\': [\'Fire\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30+\', \'text\': \'Flip a coin. If heads, this attack does 30 damage plus 20 more damage. If tails, this attack does 30 damage and the Defending Pokémon is now Burned.\'}, {\'name\': \'Volcanic Ash\', \'cost\': [\'Fire\', \'Fire\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'\', \'text\': \"Discard 2 Fire Energy attached to Blaziken ex and then choose 1 of your opponent\'s Pokémon. This attack does 100 damage to that Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'Team Magma vs Team Aqua', '2', 'Combusken', '', '', 'Third', '150', 'https://images.pokemoncard.io/images/ex4/ex4-89.png', 'unlimited: Legal', '', 'Blaziken ex', '257', 'TPCI', 'Rare Holo EX', '', '03/01/2004', '', 'Colorless, Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '89', 'Stage 2, EX', 'Pokémon', 'Fire', 'type: Water, value: ×2, type: Psychic, value: ×2'),
('ex4-9', '[{\'name\': \'Power Saver\', \'text\': \"As long as the number of Pokémon in play (both yours and your opponent\'s) that has Team Magma in its name is 3 or less, Team Magma\'s Groudon can\'t attack.\", \'type\': \'Poké-Body\'}]', '', 'Kazuo Yazawa', '[{\'name\': \'Linear Attack\', \'cost\': [\'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'\', \'text\': \"Choose 1 of your opponent\'s Pokémon. This attack does 20 damage to that Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}, {\'name\': \'Pulverize\', \'cost\': [\'Fighting\', \'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50+\', \'text\': \'If the Defending Pokémon already has at least 2 damage counters on it, this attack does 50 damage plus 20 more damage.\'}]', 'Team Magma vs Team Aqua', '3', '', '', '', 'Third', '100', 'https://images.pokemoncard.io/images/ex4/ex4-9.png', 'unlimited: Legal', '', 'Team Magmas Groudon', '383', 'TPCI', 'Rare Holo', '', '03/01/2004', '', 'Colorless, Colorless, Colorless', '[\'This Pokémon is both Fighting Darkness type.\']', 'EX', '9', 'Basic', 'Pokémon', 'Fighting, Darkness', 'type: Grass, value: ×2'),
('ex4-90', '[{\'name\': \'Primal Vibes\', \'text\': \"As long as Cradily ex is your Active Pokémon, your opponent can\'t play a Pokémon from his or her hand to evolve his or her Active Pokémon.\", \'type\': \'Poké-Body\'}]', '', 'Ryo Ueda', '[{\'name\': \'Eerie Light\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'The Defending Pokémon is now Confused.\'}, {\'name\': \'Acidic Poison\', \'cost\': [\'Grass\', \'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'60\', \'text\': \'The Defending Pokémon is now Poisoned and Burned.\'}]', 'Team Magma vs Team Aqua', '2', 'Lileep', '', '', 'Third', '150', 'https://images.pokemoncard.io/images/ex4/ex4-90.png', 'unlimited: Legal', '', 'Cradily ex', '346', 'TPCI', 'Rare Holo EX', '', '03/01/2004', '', 'Colorless, Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '90', 'Stage 2, EX', 'Pokémon', 'Grass', 'type: Water, value: ×2, type: Fire, value: ×2'),
('ex4-91', '', '', 'Ryo Ueda', '[{\'name\': \'Searing Flame\', \'cost\': [\'Fire\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Burned.\'}, {\'name\': \'Bright Flame\', \'cost\': [\'Fire\', \'Fire\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'90\', \'text\': \'Discard 2 Energy attached to Entei ex.\'}]', 'Team Magma vs Team Aqua', '2', '', '', '', 'Third', '100', 'https://images.pokemoncard.io/images/ex4/ex4-91.png', 'unlimited: Legal', '', 'Entei ex', '244', 'TPCI', 'Rare Holo EX', '', '03/01/2004', '', 'Colorless, Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '91', 'Basic, EX', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('ex4-92', '', '', 'Ryo Ueda', '[{\'name\': \'Dazzle Blast\', \'cost\': [\'Lightning\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Confused.\'}, {\'name\': \'Lightning Tackle\', \'cost\': [\'Lightning\', \'Lightning\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'70\', \'text\': \'Flip a coin. If tails, Raikou ex does 20 damage to itself.\'}]', 'Team Magma vs Team Aqua', '2', '', '', '', 'Third', '100', 'https://images.pokemoncard.io/images/ex4/ex4-92.png', 'unlimited: Legal', '', 'Raikou ex', '243', 'TPCI', 'Rare Holo EX', '', '03/01/2004', '', 'Colorless, Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '92', 'Basic, EX', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2');
INSERT INTO `cards` (`id`, `abilities`, `ancient_trait`, `artist`, `attacks`, `card_set`, `converted`, `evolves_from`, `evolves_to`, `flavor_text`, `generation`, `hp`, `img`, `legalities`, `level`, `name`, `national_pokedex_numbers`, `publisher`, `rarity`, `regulation_mark`, `release_date`, `resistances`, `retreat_cost`, `rules`, `series`, `set_num`, `subtypes`, `supertype`, `types`, `weakness`) VALUES
('ex4-93', '', '', 'Hikaru Koike', '[{\'name\': \'Green Heal\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Remove 4 damage counters from each of your Pokémon that has Grass Energy attached. If that Pokémon has less than 4 damage counters, remove all of them.\'}, {\'name\': \'Poison Ring\', \'cost\': [\'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40\', \'text\': \"The Defending Pokémon is now Poisoned. The Defending Pokémon can\'t retreat until the end of your opponent\'s next turn.\"}, {\'name\': \'Slashing Strike\', \'cost\': [\'Grass\', \'Grass\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 5, \'damage\': \'100\', \'text\': \"Sceptile ex can\'t use Slashing Strike during your next turn.\"}]', 'Team Magma vs Team Aqua', '2', 'Grovyle', '', '', 'Third', '150', 'https://images.pokemoncard.io/images/ex4/ex4-93.png', 'unlimited: Legal', '', 'Sceptile ex', '254', 'TPCI', 'Rare Holo EX', '', '03/01/2004', 'type: Water, value: -30', 'Colorless, Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '93', 'Stage 2, EX', 'Pokémon', 'Grass', 'type: Grass, value: ×2, type: Fire, value: ×2'),
('ex4-94', '', '', 'Ryo Ueda', '[{\'name\': \'Energy Flip\', \'cost\': [\'Water\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Choose 1 of your opponent\'s Benched Pokémon. This attack does 10 damage to that Pokémon. You may move an Energy card attached to that Pokémon to another of your opponent\'s Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}, {\'name\': \'Reverse Stream\', \'cost\': [\'Water\', \'Water\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50+\', \'text\': \'You may return all basic Energy cards attached to Suicune ex to your hand. If you do, this attack does 50 damage plus 10 more damage for each basic Energy card you returned.\'}]', 'Team Magma vs Team Aqua', '2', '', '', '', 'Third', '100', 'https://images.pokemoncard.io/images/ex4/ex4-94.png', 'unlimited: Legal', '', 'Suicune ex', '245', 'TPCI', 'Rare Holo EX', '', '03/01/2004', '', 'Colorless, Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '94', 'Basic, EX', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('ex4-95', '', '', 'Hikaru Koike', '[{\'name\': \'Hyper Pump\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'20+\', \'text\': \"Does 20 damage plus 20 more damage for each basic Energy attached to Swampert ex but not used to pay for this attack\'s Energy cost. You can\'t add more than 80 damage in this way.\"}, {\'name\': \'Crushing Wave\', \'cost\': [\'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'\', \'text\': \"Choose 1 of your opponent\'s Pokémon. This attack does 40 damage to that Pokémon. After doing damage, flip a coin. If heads, your opponent discards an Energy card, if any, attached to that Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'Team Magma vs Team Aqua', '3', 'Marshtomp', '', '', 'Third', '150', 'https://images.pokemoncard.io/images/ex4/ex4-95.png', 'unlimited: Legal', '', 'Swampert ex', '260', 'TPCI', 'Rare Holo EX', '', '03/01/2004', '', 'Colorless, Colorless, Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '95', 'Stage 2, EX', 'Pokémon', 'Fighting', 'type: Grass, value: ×2'),
('ex4-96', '', '', 'Mitsuhiro Arita', '[{\'name\': \'Quick Attack\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'10+\', \'text\': \'Flip a coin. If heads, this attack does 10 damage plus 10 more damage.\'}, {\'name\': \'Feint Attack\', \'cost\': [\'Darkness\', \'Darkness\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'\', \'text\': \"Choose 1 of your opponent\'s Pokémon. This attack does 30 damage to that Pokémon. This attack\'s damage isn\'t affected by Weakness, Resistance, Poké-Powers, Poké-Bodies or any other effects on that Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'Team Magma vs Team Aqua', '1', '', '', '', 'Third', '70', 'https://images.pokemoncard.io/images/ex4/ex4-96.png', 'unlimited: Legal', '', 'Absol', '359', 'TPCI', 'Rare Secret', '', '03/01/2004', '', 'Colorless', '', 'EX', '96', 'Basic', 'Pokémon', 'Darkness', 'type: Fighting, value: ×2'),
('ex4-97', '', '', 'Mitsuhiro Arita', '[{\'name\': \'Hypnoblast\', \'cost\': [\'Psychic\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'The Defending Pokémon is now Asleep.\'}, {\'name\': \'Swift\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \"This attack\'s damage isn\'t affected by Weakness, Resistance, Poké-Powers, Poké-Bodies or any other effects on the Defending Pokémon.\"}]', 'Team Magma vs Team Aqua', '1', '', '', '', 'Third', '50', 'https://images.pokemoncard.io/images/ex4/ex4-97.png', 'unlimited: Legal', '', 'Jirachi', '385', 'TPCI', 'Rare Secret', '', '03/01/2004', '', 'Colorless', '', 'EX', '97', 'Basic', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2'),
('ex5-1', '', '', 'Midori Harada', '[{\'name\': \'Shadow Steal\', \'cost\': [\'Psychic\'], \'convertedEnergyCost\': 1, \'damage\': \'10+\', \'text\': \"Does 10 damage plus 20 more damage for each Special Energy card in your opponent\'s discard pile.\"}, {\'name\': \'Darkness Chant\', \'cost\': [\'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'\', \'text\': \"Count the number of Basic Pokémon or Evolution cards in your discard pile. Put that many damage counters on the Defending Pokémon. You can\'t put more than 6 damage counters on the Defending Pokémon in this way.\"}]', 'Hidden Legends', '1', 'Shuppet', '', '', 'Third', '70', 'https://images.pokemoncard.io/images/ex5/ex5-1.png', 'unlimited: Legal', '', 'Banette', '354', 'TPCI', 'Rare Holo', '', '06/01/2004', 'type: Fighting, value: -30', 'Colorless', '', 'EX', '1', 'Stage 1', 'Pokémon', 'Psychic', 'type: Darkness, value: ×2'),
('ex5-10', '', '', 'Atsuko Nishida', '[{\'name\': \'Meditate\', \'cost\': [\'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20+\', \'text\': \'Does 20 damage plus 10 more damage for each damage counter on the Defending Pokémon.\'}, {\'name\': \'Chakra Points\', \'cost\': [\'Fighting\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'10+\', \'text\': \"Does 10 damage plus 10 more damage for each card in your opponent\'s hand.\"}]', 'Hidden Legends', '1', 'Meditite', '', '', 'Third', '80', 'https://images.pokemoncard.io/images/ex5/ex5-10.png', 'unlimited: Legal', '', 'Medicham', '308', 'TPCI', 'Rare Holo', '', '06/01/2004', '', 'Colorless', '', 'EX', '10', 'Stage 1', 'Pokémon', 'Fighting', 'type: Psychic, value: ×2'),
('ex5-100', '[{\'name\': \'Block Dust\', \'text\': \"As long as Vileplume ex is your Active Pokémon, your opponent can\'t play any Trainer cards (except for Supporter cards) from his or her hand.\", \'type\': \'Poké-Body\'}]', '', 'Ryo Ueda', '[{\'name\': \'Special Formula\', \'cost\': [\'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Asleep and Poisoned. If tails, the Defending Pokémon is now Confused.\'}]', 'Hidden Legends', '2', 'Gloom', '', '', 'Third', '140', 'https://images.pokemoncard.io/images/ex5/ex5-100.png', 'unlimited: Legal', '', 'Vileplume ex', '45', 'TPCI', 'Rare Holo EX', '', '06/01/2004', '', 'Colorless, Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '100', 'Stage 2, EX', 'Pokémon', 'Grass', 'type: Psychic, value: ×2'),
('ex5-101', '', '', 'Ryo Ueda', '[{\'name\': \'Sleepy Song\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'Each Defending Pokémon is now Asleep.\'}, {\'name\': \'Do the Wave\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'30+\', \'text\': \'Does 30 damage plus 10 more damage for each of your Benched Pokémon.\'}]', 'Hidden Legends', '1', 'Jigglypuff', '', '', 'Third', '100', 'https://images.pokemoncard.io/images/ex5/ex5-101.png', 'unlimited: Legal', '', 'Wigglytuff ex', '40', 'TPCI', 'Rare Holo EX', '', '06/01/2004', '', 'Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '101', 'Stage 1, EX', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('ex5-102', '', '', 'Mitsuhiro Arita', '[{\'name\': \'Mud Shot\', \'cost\': [\'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'\'}, {\'name\': \'Earthquake\', \'cost\': [\'Fighting\', \'Fighting\', \'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'60\', \'text\': \"Does 10 damage to each of your Benched Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'Hidden Legends', '3', '', '', '', 'Third', '80', 'https://static.tcgcollector.com/content/images/16/08/d3/1608d3a2947047f8b6bb7ed9aa5e7adc9c089c809342b452c3c64e0cf9f57f62.jpg', 'unlimited: Legal', '', 'Groudon', '383', 'TPCI', 'Rare Secret', '', '06/01/2004', '', 'Colorless, Colorless, Colorless', '', 'EX', '102', 'Basic', 'Pokémon', 'Fighting', 'type: Grass, value: ×2'),
('ex5-11', '[{\'name\': \'Metal Juncture\', \'text\': \"As often as you like during your turn (before your attack), you may move a Metal Energy card attached to 1 of your Benched Pokémon to your Active Pokémon. This power can\'t be used if Metagross is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Kouki Saitou', '[{\'name\': \'Squared Attack\', \'cost\': [\'Psychic\', \'Metal\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'30×\', \'text\': \'Flip 4 coins. This attack does 30 damage times the number of heads.\'}]', 'Hidden Legends', '2', 'Metang', '', '', 'Third', '100', 'https://images.pokemoncard.io/images/ex5/ex5-11.png', 'unlimited: Legal', '', 'Metagross', '376', 'TPCI', 'Rare Holo', '', '06/01/2004', 'type: Psychic, value: -30', 'Colorless, Colorless', '[\'This Pokémon is both Psychic Metal type.\']', 'EX', '11', 'Stage 2', 'Pokémon', 'Psychic, Metal', 'type: Fire, value: ×2'),
('ex5-12', '[{\'name\': \'Healing Shower\', \'text\': \"Once during your turn, when you play Milotic from your hand to evolve 1 of your Pokémon, you may remove all damage counters from all of your Pokémon and your opponent\'s Pokémon (excluding Pokémon-ex).\", \'type\': \'Poké-Power\'}]', '', 'Atsuko Nishida', '[{\'name\': \'Wave Splash\', \'cost\': [\'Water\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'\'}, {\'name\': \'Distorted Wave\', \'cost\': [\'Water\', \'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'80\', \'text\': \'Before doing damage, remove 3 damage counters from the Defending Pokémon (all if there are less than 3).\'}]', 'Hidden Legends', '2', 'Feebas', '', '', 'Third', '100', 'https://images.pokemoncard.io/images/ex5/ex5-12.png', 'unlimited: Legal', '', 'Milotic', '350', 'TPCI', 'Rare Holo', '', '06/01/2004', '', 'Colorless, Colorless', '', 'EX', '12', 'Stage 1', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('ex5-13', '[{\'name\': \'Crust\', \'text\': \"Any damage done to Pinsir by attacks from your opponent\'s Basic Pokémon is reduced by 30 (after applying Weakness and Resistance).\", \'type\': \'Poké-Body\'}]', '', 'Hajime Kusajima', '[{\'name\': \'Sonicboom\', \'cost\': [\'Grass\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \"This attack\'s damage isn\'t affected by Weakness or Resistance.\"}]', 'Hidden Legends', '1', '', '', '', 'Third', '70', 'https://images.pokemoncard.io/images/ex5/ex5-13.png', 'unlimited: Legal', '', 'Pinsir', '127', 'TPCI', 'Rare Holo', '', '06/01/2004', '', 'Colorless', '', 'EX', '13', 'Basic', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('ex5-14', '', '', 'Hisao Nakamura', '[{\'name\': \'Push Aside\', \'cost\': [\'Darkness\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \"Look at your opponent\'s hand and choose 1 Basic Pokémon or Evolution card you find there. Your opponent puts it at the bottom of his or her deck.\"}, {\'name\': \'Supernatural Power\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40+\', \'text\': \'If you have the same number of cards in your hand as your opponent, this attack does 40 damage plus 40 more damage.\'}]', 'Hidden Legends', '2', 'Nuzleaf', '', '', 'Third', '110', 'https://images.pokemoncard.io/images/ex5/ex5-14.png', 'unlimited: Legal', '', 'Shiftry', '275', 'TPCI', 'Rare Holo', '', '06/01/2004', 'type: Psychic, value: -30', 'Colorless, Colorless', '', 'EX', '14', 'Stage 2', 'Pokémon', 'Darkness', 'type: Fighting, value: ×2'),
('ex5-15', '[{\'name\': \'Crush Draw\', \'text\': \"Once during your turn (before your attack), you may reveal the top card of your deck. If that card is a basic Energy card, attach it to 1 of your Pokémon. If not, put the card back on your deck. This power can\'t be used if Walrein is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Atsuko Nishida', '[{\'name\': \'Sheer Cold\', \'cost\': [\'Water\', \'Water\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50\', \'text\': \"Flip a coin. If heads, each Defending Pokémon can\'t attack during your opponent\'s next turn.\"}]', 'Hidden Legends', '3', 'Sealeo', '', '', 'Third', '120', 'https://images.pokemoncard.io/images/ex5/ex5-15.png', 'unlimited: Legal', '', 'Walrein', '365', 'TPCI', 'Rare Holo', '', '06/01/2004', '', 'Colorless, Colorless, Colorless', '', 'EX', '15', 'Stage 2', 'Pokémon', 'Water', 'type: Metal, value: ×2'),
('ex5-16', '[{\'name\': \'Heal Dance\', \'text\': \"Once during your turn (before your attack), you may remove 2 damage counters from 1 of your Pokémon. You can\'t use more than 1 Heal Dance Poké-Power each turn. This power can\'t be used if Bellossom is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Yuka Morii', '[{\'name\': \'Miracle Powder\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'Flip a coin. If heads, choose 1 Special Condition. The Defending Pokémon is now affected by that Special Condition.\'}, {\'name\': \'Solarbeam\', \'cost\': [\'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50\', \'text\': \'\'}]', 'Hidden Legends', '2', 'Gloom', '', '', 'Third', '100', 'https://images.pokemoncard.io/images/ex5/ex5-16.png', 'unlimited: Legal', '', 'Bellossom', '182', 'TPCI', 'Rare', '', '06/01/2004', 'type: Water, value: -30', 'Colorless, Colorless', '', 'EX', '16', 'Stage 2', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('ex5-17', '', '', 'Miki Tanaka', '[{\'name\': \'Chime\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Search your opponent\'s discard pile for a Supporter card and use the effect of that card as the effect of this attack. (The Supporter card remains in your opponent\'s discard pile.)\"}, {\'name\': \'Psychic Boom\', \'cost\': [\'Psychic\'], \'convertedEnergyCost\': 1, \'damage\': \'10×\', \'text\': \'Does 10 damage times the amount of Energy attached to the Defending Pokémon.\'}]', 'Hidden Legends', '1', '', '', '', 'Third', '60', 'https://images.pokemoncard.io/images/ex5/ex5-17.png', 'unlimited: Legal', '', 'Chimecho', '358', 'TPCI', 'Rare', '', '06/01/2004', '', 'Colorless', '', 'EX', '17', 'Basic', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2'),
('ex5-18', '', '', 'Kagemaru Himeno', '[{\'name\': \'Stun Needle\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Paralyzed.\'}, {\'name\': \'Mystic Water\', \'cost\': [\'Water\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20+\', \'text\': \'Does 20 damage plus 10 more damage for each Psychic Energy in play.\'}]', 'Hidden Legends', '', 'Clamperl', '', '', 'Third', '70', 'https://images.pokemoncard.io/images/ex5/ex5-18.png', 'unlimited: Legal', '', 'Gorebyss', '368', 'TPCI', 'Rare', '', '06/01/2004', '', '', '', 'EX', '18', 'Stage 1', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('ex5-19', '', '', 'Kagemaru Himeno', '[{\'name\': \'Bite\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'\'}, {\'name\': \'Dark Splash\', \'cost\': [\'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40+\', \'text\': \'Does 40 damage plus 10 more damage for each Darkness Pokémon in play.\'}]', 'Hidden Legends', '1', 'Clamperl', '', '', 'Third', '80', 'https://images.pokemoncard.io/images/ex5/ex5-19.png', 'unlimited: Legal', '', 'Huntail', '367', 'TPCI', 'Rare', '', '06/01/2004', '', 'Colorless', '', 'EX', '19', 'Stage 1', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('ex5-2', '[{\'name\': \'Primal Pull\', \'text\': \"As long as Claydol is your Active Pokémon, each player\'s Evolved Pokémon pays Colorless more Energy to use its attacks.\", \'type\': \'Poké-Body\'}]', '', 'Kyoko Umemoto', '[{\'name\': \'Muddy Eye\', \'cost\': [\'Psychic\'], \'convertedEnergyCost\': 1, \'damage\': \'10×\', \'text\': \'Does 10 damage times the number of basic Energy cards attached to Claydol and the Defending Pokémon.\'}]', 'Hidden Legends', '1', 'Baltoy', '', '', 'Third', '80', 'https://images.pokemoncard.io/images/ex5/ex5-2.png', 'unlimited: Legal', '', 'Claydol', '344', 'TPCI', 'Rare Holo', '', '06/01/2004', '', 'Colorless', '', 'EX', '2', 'Stage 1', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2'),
('ex5-20', '', '', 'Toshinao Aoki', '[{\'name\': \'Whirlwind\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'20\', \'text\': \'Your opponent switches the Defending Pokémon with 1 of his or her Benched Pokémon.\'}, {\'name\': \'Silver Wind\', \'cost\': [\'Grass\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'During your next turn, if an attack does damage to the Defending Pokémon (after applying Weakness and Resistance), that attack does 30 more damage.\'}]', 'Hidden Legends', '', 'Surskit', '', '', 'Third', '70', 'https://images.pokemoncard.io/images/ex5/ex5-20.png', 'unlimited: Legal', '', 'Masquerain', '284', 'TPCI', 'Rare', '', '06/01/2004', 'type: Fighting, value: -30', '', '', 'EX', '20', 'Stage 1', 'Pokémon', 'Grass', 'type: Lightning, value: ×2'),
('ex5-21', '', '', 'Mitsuhiro Arita', '[{\'name\': \'Metal Load\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Search your discard pile for a Metal Energy card and attach it to Metang.\'}, {\'name\': \'Metal Claw\', \'cost\': [\'Metal\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'\'}]', 'Hidden Legends', '2', 'Beldum', 'Metagross', '', 'Third', '80', 'https://images.pokemoncard.io/images/ex5/ex5-21.png', 'unlimited: Legal', '', 'Metang', '375', 'TPCI', 'Rare', '', '06/01/2004', 'type: Grass, value: -30', 'Colorless, Colorless', '', 'EX', '21', 'Stage 1', 'Pokémon', 'Metal', 'type: Fire, value: ×2'),
('ex5-22', '[{\'name\': \'Safeguard\', \'text\': \"Prevent all effects of attacks, including damage, done to Ninetales by your opponent\'s Pokémon-ex.\", \'type\': \'Poké-Body\'}]', '', 'Toshinao Aoki', '[{\'name\': \'Quick Attack\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20+\', \'text\': \'Flip a coin. If heads, this attack does 20 damage plus 20 more damage.\'}, {\'name\': \"Will-o\'-the-wisp\", \'cost\': [\'Fire\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50\', \'text\': \'\'}]', 'Hidden Legends', '1', 'Vulpix', '', '', 'Third', '70', 'https://images.pokemoncard.io/images/ex5/ex5-22.png', 'unlimited: Legal', '', 'Ninetales', '38', 'TPCI', 'Rare', '', '06/01/2004', '', 'Colorless', '', 'EX', '22', 'Stage 1', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('ex5-23', '[{\'name\': \'Temperamental Weather\', \'text\': \"Once during your turn (before your attack), you may search your deck for Castform, Sunny Castform, or Snow-cloud Castform and switch it with Rain Castform. (Any cards attached to Rain Castform, damage counters, Special Conditions, and effects on it are now on the new Pokémon.) Shuffle Rain Castform back into your deck. You can\'t use more than 1 Temperamental Weather Poké-Power each turn.\", \'type\': \'Poké-Power\'}]', '', 'Sumiyoshi Kizuki', '[{\'name\': \'Scattered Shower\', \'cost\': [\'Water\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Shuffle your hand into your deck. Draw up to 5 cards.\'}, {\'name\': \'Rainy Day Blues\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'If Low Pressure System is in play, the Defending Pokémon is now Confused.\'}]', 'Hidden Legends', '1', '', '', '', 'Third', '60', 'https://images.pokemoncard.io/images/ex5/ex5-23.png', 'unlimited: Legal', '', 'Rain Castform', '351', 'TPCI', 'Rare', '', '06/01/2004', '', 'Colorless', '', 'EX', '23', 'Basic', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('ex5-24', '[{\'name\': \'Deep Sleep\', \'text\': \'As long as Relicanth is your Active Pokémon, a player flips 2 coins for each of his or her Pokémon that is Asleep between turns. If either coin is tails, that Pokémon is still Asleep.\', \'type\': \'Poké-Body\'}]', '', 'Kagemaru Himeno', '[{\'name\': \'Yawn\', \'cost\': [\'Water\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Asleep.\'}]', 'Hidden Legends', '1', '', '', '', 'Third', '60', 'https://images.pokemoncard.io/images/ex5/ex5-24.png', 'unlimited: Legal', '', 'Relicanth', '369', 'TPCI', 'Rare', '', '06/01/2004', '', 'Colorless', '', 'EX', '24', 'Basic', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('ex5-25', '[{\'name\': \'Temperamental Weather\', \'text\': \"Once during your turn (before your attack), you may search your deck for Castform, Rain Castform, or Sunny Castform and switch it with Snow-cloud Castform. (Any cards attached to Snow-cloud Castform, damage counters, Special Conditions, and effects on it are now on the new Pokémon.) Shuffle Snow-cloud Castform back into your deck. You can\'t use more than 1 Temperamental Weather Poké-Power each turn.\", \'type\': \'Poké-Power\'}]', '', 'Sumiyoshi Kizuki', '[{\'name\': \'Flurries\', \'cost\': [\'Water\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Paralyzed. If tails, the Defending Pokémon is now Asleep.\'}, {\'name\': \'White Snow\', \'cost\': [\'Water\', \'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'50+\', \'text\': \'If Magnetic Storm is in play, this attack does 50 damage plus 20 more damage.\'}]', 'Hidden Legends', '2', '', '', '', 'Third', '70', 'https://images.pokemoncard.io/images/ex5/ex5-25.png', 'unlimited: Legal', '', 'Snow-cloud Castform', '351', 'TPCI', 'Rare', '', '06/01/2004', '', 'Colorless, Colorless', '', 'EX', '25', 'Basic', 'Pokémon', 'Water', 'type: Metal, value: ×2'),
('ex5-26', '[{\'name\': \'Temperamental Weather\', \'text\': \"Once during your turn (before your attack), you may search your deck for Castform, Rain Castform, or Snow-cloud Castform and switch it with Sunny Castform. (Any cards attached to Sunny Castform, damage counters, Special Conditions, and effects on it are now on the new Pokémon.) Shuffle Sunny Castform back into your deck. You can\'t use more than 1 Temperamental Weather Poké-Power each turn.\", \'type\': \'Poké-Power\'}]', '', 'Sumiyoshi Kizuki', '[{\'name\': \'Sunshine\', \'cost\': [\'Fire\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Search your discard pile for a Stadium card, show it to your opponent, and put it into your hand.\'}, {\'name\': \'Sunburn\', \'cost\': [\'Fire\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40\', \'text\': \'If High Pressure System is in play, the Defending Pokémon is now Burned.\'}]', 'Hidden Legends', '2', '', '', '', 'Third', '70', 'https://images.pokemoncard.io/images/ex5/ex5-26.png', 'unlimited: Legal', '', 'Sunny Castform', '351', 'TPCI', 'Rare', '', '06/01/2004', '', 'Colorless, Colorless', '', 'EX', '26', 'Basic', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('ex5-27', '', '', 'Kouki Saitou', '[{\'name\': \'Fruition\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Move 1 Energy card attached to Tropius to another of your Pokémon and remove 4 damage counters from that Pokémon (all if there are less than 4).\'}, {\'name\': \'Gust\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'\'}]', 'Hidden Legends', '1', '', '', '', 'Third', '80', 'https://images.pokemoncard.io/images/ex5/ex5-27.png', 'unlimited: Legal', '', 'Tropius', '357', 'TPCI', 'Rare', '', '06/01/2004', '', 'Colorless', '', 'EX', '27', 'Basic', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('ex5-28', '[{\'name\': \'Levitate\', \'text\': \"If Beldum has any Energy attached to it, Beldum\'s Retreat Cost is 0.\", \'type\': \'Poké-Body\'}]', '', 'Ken Sugimori', '[{\'name\': \'Tackle\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'\'}]', 'Hidden Legends', '2', '', 'Metang', '', 'Third', '50', 'https://images.pokemoncard.io/images/ex5/ex5-28.png', 'unlimited: Legal', '', 'Beldum', '374', 'TPCI', 'Uncommon', '', '06/01/2004', 'type: Grass, value: -30', 'Colorless, Colorless', '', 'EX', '28', 'Basic', 'Pokémon', 'Metal', 'type: Fire, value: ×2'),
('ex5-29', '[{\'name\': \'Magnetic Call\', \'text\': \"Once during your turn (before your attack), you may flip a coin. If heads, search your deck for a Metal Basic Pokémon and put it onto your Bench. Shuffle your deck afterward. This power can\'t be used if Beldum is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Mitsuhiro Arita', '[{\'name\': \'Metal Charge\', \'cost\': [\'Metal\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'Put 1 damage counter on Beldum.\'}]', 'Hidden Legends', '2', '', 'Metang', '', 'Third', '50', 'https://images.pokemoncard.io/images/ex5/ex5-29.png', 'unlimited: Legal', '', 'Beldum', '374', 'TPCI', 'Uncommon', '', '06/01/2004', 'type: Grass, value: -30', 'Colorless, Colorless', '', 'EX', '29', 'Basic', 'Pokémon', 'Metal', 'type: Fire, value: ×2'),
