('ex5-32', '', '', 'Naoyo Kimura', '[{\'name\': \'Coral Glow\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Draw a number of cards up to the number of your opponent\'s Basic Pokémon in play. (You can\'t have more than 10 cards in your hand in this way.)\"}, {\'name\': \'Surf\', \'cost\': [\'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40\', \'text\': \'\'}]', 'Hidden Legends', '1', '', 'Cursola', '', 'Third', '70', 'https://images.pokemoncard.io/images/ex5/ex5-32.png', 'unlimited: Legal', '', 'Corsola', '222', 'TPCI', 'Uncommon', '', '06/01/2004', '', 'Colorless', '', 'EX', '32', 'Basic', 'Pokémon', 'Water', 'type: Grass, value: ×2'),
('ex5-33', '[{\'name\': \'Fast Feet\', \'text\': \'Dodrio can retreat even when it is Asleep or Paralyzed.\', \'type\': \'Poké-Body\'}]', '', 'Miki Tanaka', '[{\'name\': \'Retaliate\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'10×\', \'text\': \'Does 10 damage times the number of damage counters on Dodrio.\'}, {\'name\': \'Slashing Strike\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'40\', \'text\': \"Flip a coin. If tails, Dodrio can\'t use Slashing Strike during your next turn.\"}]', 'Hidden Legends', '', 'Doduo', '', '', 'Third', '80', 'https://images.pokemoncard.io/images/ex5/ex5-33.png', 'unlimited: Legal', '', 'Dodrio', '85', 'TPCI', 'Uncommon', '', '06/01/2004', 'type: Fighting, value: -30', '', '', 'EX', '33', 'Stage 1', 'Pokémon', 'Colorless', 'type: Lightning, value: ×2'),
