('ex5-82', '', '', 'Tomokazu Komiya', '[{\'name\': \'Wail\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'Your opponent switches the Defending Pokémon with 1 of his or her Benched Pokémon.\'}]', 'Hidden Legends', '1', '', 'Loudred', '', 'Third', '50', 'https://images.pokemoncard.io/images/ex5/ex5-82.png', 'unlimited: Legal', '', 'Whismur', '293', 'TPCI', 'Common', '', '06/01/2004', '', 'Colorless', '', 'EX', '82', 'Basic', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('ex5-83', '', '', 'Midori Harada', '[{\'name\': \'Quick Turn\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10×\', \'text\': \'Flip 2 coins. This attack does 10 damage times the number of heads.\'}, {\'name\': \'Surprise\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Choose 1 card from your opponent\'s hand without looking. Look at the card you chose, then have your opponent shuffle that card into his or her deck.\"}]', 'Hidden Legends', '1', '', 'Golbat', '', 'Third', '50', 'https://images.pokemoncard.io/images/ex5/ex5-83.png', 'unlimited: Legal', '', 'Zubat', '41', 'TPCI', 'Common', '', '06/01/2004', '', 'Colorless', '', 'EX', '83', 'Basic', 'Pokémon', 'Grass', 'type: Psychic, value: ×2'),
('ex5-84', '', '', 'Mitsuhiro Arita', '[{\'name\': \'Ice Generator\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Discard all of your opponent\'s Trainer cards in play. If you do, prevent all effects, including damage, done to the Pokémon using this attack during your opponent\'s next turn.\"}]', 'Hidden Legends', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex5/ex5-84.png', 'unlimited: Legal', '', 'Ancient Technical Machine Ice', '', 'TPCI', 'Uncommon', '', '06/01/2004', '', '', '[\"Attach this card to 1 of your Evolved Pokémon (excluding Pokémon-ex and Pokémon that has an owner in its name) in play. That Pokémon may use this card\'s attack instead of its own. At the end of your turn, discard Ancient Technical Machine [Ice].\"]', 'EX', '84', 'Technical Machine', 'Trainer', '', ''),
('ex5-85', '', '', 'Mitsuhiro Arita', '[{\'name\': \'Stone Generator\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'If your opponent has any Evolved Pokémon in play, remove the highest Stage Evolution card from each of them and put those cards back into his or her hand.\'}]', 'Hidden Legends', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex5/ex5-85.png', 'unlimited: Legal', '', 'Ancient Technical Machine Rock', '', 'TPCI', 'Uncommon', '', '06/01/2004', '', '', '[\"Attach this card to 1 of your Evolved Pokémon (excluding Pokémon-ex and Pokémon that has an owner in its name) in play. That Pokémon may use this card\'s attack instead of its own. At the end of your turn, discard Ancient Technical Machine [Rock].\"]', 'EX', '85', 'Technical Machine', 'Trainer', '', ''),
('ex5-86', '', '', 'Mitsuhiro Arita', '[{\'name\': \'Steel Generator\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'\', \'text\': \"If the Defending Pokémon has a Poké-Power or Poké-Body, choose up to 2 basic Energy cards attached to 1 of your opponent\'s Pokémon and attach them to the Defending Pokémon.\"}]', 'Hidden Legends', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex5/ex5-86.png', 'unlimited: Legal', '', 'Ancient Technical Machine Steel', '', 'TPCI', 'Uncommon', '', '06/01/2004', '', '', '[\"Attach this card to 1 of your Evolved Pokémon (excluding Pokémon-ex and Pokémon that has an owner in its name) in play. That Pokémon may use this card\'s attack instead of its own. At the end of your turn, discard Ancient Technical Machine [Steel].\"]', 'EX', '86', 'Technical Machine', 'Trainer', '', ''),
('ex5-87', '', '', 'Ken Ikuji', '', 'Hidden Legends', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex5/ex5-87.png', 'unlimited: Legal', '', 'Ancient Tomb', '', 'TPCI', 'Uncommon', '', '06/01/2004', '', '', '[\'This card stays in play when you play it. Discard this card if another Stadium card comes into play.\', \"Don\'t apply Weakness for all Pokémon in play (excluding Pokémon-ex and Pokémon that has an owner in its name).\"]', 'EX', '87', 'Stadium', 'Trainer', '', ''),
('ex5-88', '', '', 'Shin-ichi Yoshikawa', '', 'Hidden Legends', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex5/ex5-88.png', 'unlimited: Legal', '', 'Desert Ruins', '', 'TPCI', 'Uncommon', '', '06/01/2004', '', '', '[\'This card stays in play when you play it. Discard this card if another Stadium card comes into play.\', \'At any time between turns, each player puts 1 damage counter on his or her Pokémon-ex with maximum HP of at least 100.\']', 'EX', '88', 'Stadium', 'Trainer', '', ''),
('ex5-89', '', '', 'Ken Ikuji', '', 'Hidden Legends', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex5/ex5-89.png', 'unlimited: Legal', '', 'Island Cave', '', 'TPCI', 'Uncommon', '', '06/01/2004', '', '', '[\'This card stays in play when you play it. Discard this card if another Stadium card comes into play.\', \'Whenever any player attaches an Energy card from his or her hand to Water Pokémon, Fighting Pokémon, or Metal Pokémon, remove any Special Conditions from that Pokémon.\']', 'EX', '89', 'Stadium', 'Trainer', '', ''),
('ex5-9', '[{\'name\': \'Overzealous\', \'text\': \"If your opponent has any Pokémon-ex in play, each of Machamp\'s attacks do 30 more damage to the Defending Pokémon.\", \'type\': \'Poké-Body\'}]', '', 'Hajime Kusajima', '[{\'name\': \'Brick Smash\', \'cost\': [\'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'40\', \'text\': \"This attack\'s damage isn\'t affected by Weakness, Resistance, Poké-Powers, Poké-Bodies, or any other effects on the Defending Pokémon.\"}, {\'name\': \'Cross Chop\', \'cost\': [\'Fighting\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'60+\', \'text\': \'Flip a coin. If heads, this attack does 60 damage plus 30 more damage.\'}]', 'Hidden Legends', '2', 'Machoke', '', '', 'Third', '120', 'https://images.pokemoncard.io/images/ex5/ex5-9.png', 'unlimited: Legal', '', 'Machamp', '68', 'TPCI', 'Rare Holo', '', '06/01/2004', '', 'Colorless, Colorless', '', 'EX', '9', 'Stage 2', 'Pokémon', 'Fighting', 'type: Psychic, value: ×2'),
('ex5-90', '', '', 'Ryo Ueda', '', 'Hidden Legends', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex5/ex5-90.png', 'unlimited: Legal', '', 'Life Herb', '', 'TPCI', 'Uncommon', '', '06/01/2004', '', '', '[\'Flip a coin. If heads, choose 1 of your Pokémon (excluding Pokémon-ex). Remove all Special Conditions and 6 damage counters from that Pokémon (all if there are less than 6).\']', 'EX', '90', 'Item', 'Trainer', '', ''),
('ex5-91', '', '', 'Shin-ichi Yoshikawa', '', 'Hidden Legends', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex5/ex5-91.png', 'unlimited: Legal', '', 'Magnetic Storm', '', 'TPCI', 'Uncommon', '', '06/01/2004', '', '', '[\'This card stays in play when you play it. Discard this card if another Stadium card comes into play.\', \"Any damage done by attacks from Psychic Pokémon and Fighting Pokémon (both yours and your opponent\'s) is not affected by Resistance.\"]', 'EX', '91', 'Stadium', 'Trainer', '', ''),
('ex5-92', '', '', 'Ken Sugimori', '', 'Hidden Legends', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex5/ex5-92.png', 'unlimited: Legal', '', 'Stevens Advice', '', 'TPCI', 'Uncommon', '', '06/01/2004', '', '', '[\'You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.\', \"Draw a number of cards up to the number of your opponent\'s Pokémon in play.\", \"If you have more than 7 cards (including this one) in your hand, you can\'t play this card.\"]', 'EX', '92', 'Supporter', 'Trainer', '', ''),
('ex5-93', '[{\'name\': \'Mark of Antiquity\', \'text\': \"As long as Groudon ex is your Active Pokémon, each player\'s Kyogre ex and Rayquaza ex can\'t attack.\", \'type\': \'Poké-Body\'}]', '', 'Hikaru Koike', '[{\'name\': \'Rock Tumble\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \"This attack\'s damage is not affected by Resistance.\"}, {\'name\': \'Crushing Mantle\', \'cost\': [\'Fighting\', \'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50+\', \'text\': \'You may discard from your hand as many Energy cards as you like. If you do, this attack does 50 damage plus 10 more damage for each Energy card you discarded.\'}]', 'Hidden Legends', '3', '', '', '', 'Third', '100', 'https://images.pokemoncard.io/images/ex5/ex5-93.png', 'unlimited: Legal', '', 'Groudon ex', '383', 'TPCI', 'Rare Holo EX', '', '06/01/2004', '', 'Colorless, Colorless, Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '93', 'Basic, EX', 'Pokémon', 'Fighting', 'type: Water, value: ×2'),
('ex5-94', '[{\'name\': \'Mark of Antiquity\', \'text\': \"As long as Kyogre ex is your Active Pokémon, each player\'s Groudon ex and Rayquaza ex can\'t attack.\", \'type\': \'Poké-Body\'}]', '', 'Hikaru Koike', '[{\'name\': \'Water Arrow\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'\', \'text\': \"Choose 1 of your opponent\'s Pokémon. This attack does 20 damage to that Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}, {\'name\': \'Super Tidal Wave\', \'cost\': [\'Water\', \'Water\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50+\', \'text\': \'You may show your hand to your opponent. If you do, this attack does 50 damage plus 10 more damage for each Energy card in your hand. After doing damage, shuffle the Energy cards back into your deck.\'}]', 'Hidden Legends', '3', '', '', '', 'Third', '100', 'https://images.pokemoncard.io/images/ex5/ex5-94.png', 'unlimited: Legal', '', 'Kyogre ex', '382', 'TPCI', 'Rare Holo EX', '', '06/01/2004', '', 'Colorless, Colorless, Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '94', 'Basic, EX', 'Pokémon', 'Water', 'type: Grass, value: ×2'),
('ex5-95', '', '', 'Mitsuhiro Arita', '[{\'name\': \'Metal Reversal\', \'cost\': [\'Metal\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'40\', \'text\': \"Before doing damage, you may choose 1 of your opponent\'s Benched Pokémon and switch it with 1 of the Defending Pokémon. Your opponent chooses the Defending Pokémon to switch. If you do, this attack does 40 damage to the new Defending Pokémon.\"}, {\'name\': \'Extra Comet Punch\', \'cost\': [\'Metal\', \'Metal\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'50+\', \'text\': \'During your next turn, Extra Comet Punch does 50 damage plus 50 more damage.\'}]', 'Hidden Legends', '4', 'Metang', '', '', 'Third', '150', 'https://images.pokemoncard.io/images/ex5/ex5-95.png', 'unlimited: Legal', '', 'Metagross ex', '376', 'TPCI', 'Rare Holo EX', '', '06/01/2004', 'type: Grass, value: -30', 'Colorless, Colorless, Colorless, Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '95', 'Stage 2, EX', 'Pokémon', 'Metal', 'type: Fighting, value: ×2, type: Fire, value: ×2'),
('ex5-96', '', '', 'Ryo Ueda', '[{\'name\': \'Intense Glare\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Switch 1 of your opponent\'s Benched Pokémon with 1 of the Defending Pokémon. Your opponent chooses the Defending Pokémon to switch. The new Defending Pokémon is now Burned and Confused.\"}, {\'name\': \'Fire Blast\', \'cost\': [\'Fire\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'100\', \'text\': \'Discard a Fire Energy attached to Ninetales ex.\'}]', 'Hidden Legends', '1', 'Vulpix', '', '', 'Third', '90', 'https://images.pokemoncard.io/images/ex5/ex5-96.png', 'unlimited: Legal', '', 'Ninetales ex', '38', 'TPCI', 'Rare Holo EX', '', '06/01/2004', '', 'Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '96', 'Stage 1, EX', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('ex5-97', '[{\'name\': \'Crystal Body\', \'text\': \'Prevent all effects of attacks, except damage, done to Regice ex by the Attacking Pokémon.\', \'type\': \'Poké-Body\'}]', '', 'Mitsuhiro Arita', '[{\'name\': \'Freeze Lock\', \'cost\': [\'Water\', \'Water\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60\', \'text\': \"Flip a coin. If heads, your opponent can\'t attach Energy cards from his or her hand to the Defending Pokémon during his or her next turn.\"}]', 'Hidden Legends', '2', '', '', '', 'Third', '90', 'https://images.pokemoncard.io/images/ex5/ex5-97.png', 'unlimited: Legal', '', 'Regice ex', '378', 'TPCI', 'Rare Holo EX', '', '06/01/2004', '', 'Colorless, Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '97', 'Basic, EX', 'Pokémon', 'Water', 'type: Metal, value: ×2'),
('ex5-98', '[{\'name\': \'Healing Stone\', \'text\': \'At any time between turns, remove 1 damage counter from Regirock ex.\', \'type\': \'Poké-Body\'}]', '', 'Mitsuhiro Arita', '[{\'name\': \'Tonnage\', \'cost\': [\'Fighting\', \'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60+\', \'text\': \'You may do 60 damage plus 20 more damage. If you do, Regirock ex does 30 damage to itself.\'}]', 'Hidden Legends', '3', '', '', '', 'Third', '100', 'https://images.pokemoncard.io/images/ex5/ex5-98.png', 'unlimited: Legal', '', 'Regirock ex', '377', 'TPCI', 'Rare Holo EX', '', '06/01/2004', '', 'Colorless, Colorless, Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '98', 'Basic, EX', 'Pokémon', 'Fighting', 'type: Water, value: ×2'),
