('ex6-102', '', '', 'Hiromichi Sugiyama', '', 'FireRed & LeafGreen', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex6/ex6-102.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Switch', '', 'TPCI', 'Common', '', '09/01/2004', '', '', '[\'Switch 1 of your Active Pokémon with 1 of your Benched Pokémon.\']', 'EX', '102', 'Item', 'Trainer', '', ''),
('ex6-103', '', '', 'Takumi Akabane', '', 'FireRed & LeafGreen', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex6/ex6-103.png', 'unlimited: Legal', '', 'Multi Energy', '', 'TPCI', 'Rare', '', '09/01/2004', '', '', '[\"Attach Multi Energy to 1 of your Pokémon. While in play, Multi Energy provides every type of Energy but provides only 1 Energy at a time. (Doesn\'t count as a basic Energy card when not in play.) Multi Energy provides Colorless Energy when attached to a Pokémon that already has Special Energy cards attached to it.\"]', 'EX', '103', 'Special', 'Energy', '', ''),
('ex6-104', '[{\'name\': \'Energy Rain\', \'text\': \"As often as you like during your turn (before your attack), you may attach a Water Energy card from your hand to 1 of your Pokémon. Put 1 damage counter on that Pokémon. This power can\'t be used if Blastoise ex is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Hikaru Koike', '[{\'name\': \'Hyper Whirlpool\', \'cost\': [\'Water\', \'Water\', \'Water\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'80\', \'text\': \'Flip a coin until you get tails. For each heads, your opponent discards an Energy card attached to the Defending Pokémon.\'}]', 'FireRed & LeafGreen', '3', 'Wartortle', '', '', 'Third', '150', 'https://images.pokemoncard.io/images/ex6/ex6-104.png', 'unlimited: Legal', '', 'Blastoise ex', '9', 'TPCI', 'Rare Holo EX', '', '09/01/2004', '', 'Colorless, Colorless, Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '104', 'Stage 2, EX', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('ex6-105', '[{\'name\': \'Energy Flame\', \'text\': \'All Energy attached to Charizard ex are Fire Energy instead of its usual type.\', \'type\': \'Poké-Body\'}]', '', 'Hiromichi Sugiyama', '[{\'name\': \'Slash\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50\', \'text\': \'\'}, {\'name\': \'Burn Down\', \'cost\': [\'Fire\', \'Fire\', \'Fire\', \'Fire\', \'Fire\'], \'convertedEnergyCost\': 5, \'damage\': \'200\', \'text\': \"Discard 5 Fire Energy attached to Charizard ex. This attack\'s damage isn\'t affected by Weakness, Resistance, Poké-Powers, Poké-Bodies, and any other effects on the Defending Pokémon.\"}]', 'FireRed & LeafGreen', '2', 'Charmeleon', '', '', 'Third', '160', 'https://images.pokemoncard.io/images/ex6/ex6-105.png', 'unlimited: Legal', '', 'Charizard ex', '6', 'TPCI', 'Rare Holo EX', '', '09/01/2004', '', 'Colorless, Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '105', 'Stage 2, EX', 'Pokémon', 'Fire', 'type: Water, value: ×2, type: Lightning, value: ×2'),
('ex6-106', '', '', 'Mitsuhiro Arita', '[{\'name\': \'Metronome\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'\', \'text\': \"Choose 1 of the Defending Pokémon\'s attacks. Metronome copies that attack except for its Energy cost. (You must still do anything else in order to use that attack.) (No matter what type that Pokémon is, Clefable ex\'s type is still Colorless.) Clefable ex performs that attack.\"}, {\'name\': \'Moon Impact\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'40\', \'text\': \'\'}]', 'FireRed & LeafGreen', '2', 'Clefairy', '', '', 'Third', '100', 'https://images.pokemoncard.io/images/ex6/ex6-106.png', 'unlimited: Legal', '', 'Clefable ex', '36', 'TPCI', 'Rare Holo EX', '', '09/01/2004', '', 'Colorless, Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '106', 'Stage 2, EX', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('ex6-107', '[{\'name\': \'Extra Energy Bomb\', \'text\': \"Once during your turn (before your attack), you may discard Electrode ex and all the cards attached to it (this counts as Knocking Out Electrode ex). If you do, search your discard pile for 5 Energy cards and attach them to any of your Pokémon (excluding Pokémon-ex) in any way you like. This power can\'t be used if Electrode ex is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Ryo Ueda', '[{\'name\': \'Crush and Burn\', \'cost\': [\'Lightning\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30+\', \'text\': \'You may discard as many Energy as you like attached to your Pokémon in play. If you do, this attack does 30 damage plus 20 more damage for each Energy you discarded.\'}]', 'FireRed & LeafGreen', '1', 'Voltorb', '', '', 'Third', '90', 'https://images.pokemoncard.io/images/ex6/ex6-107.png', 'unlimited: Legal', '', 'Electrode ex', '101', 'TPCI', 'Rare Holo EX', '', '09/01/2004', '', 'Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '107', 'Stage 1, EX', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
('ex6-108', '', '', 'Mitsuhiro Arita', '[{\'name\': \'Poltergeist\', \'cost\': [\'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'40+\', \'text\': \"Look at your opponent\'s hand. This attack does 40 damage plus 10 more damage for each Trainer card in your opponent\'s hand.\"}, {\'name\': \'Prize Count\', \'cost\': [\'Psychic\', \'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60+\', \'text\': \'If you have more Prize cards left than your opponent, this attack does 60 damage plus 40 more damage.\'}]', 'FireRed & LeafGreen', '2', 'Haunter', '', '', 'Third', '150', 'https://images.pokemoncard.io/images/ex6/ex6-108.png', 'unlimited: Legal', '', 'Gengar ex', '94', 'TPCI', 'Rare Holo EX', '', '09/01/2004', 'type: Fighting, value: -30, type: Colorless, value: -30', 'Colorless, Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '108', 'Stage 2, EX', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2, type: Darkness, value: ×2'),
('ex6-109', '', '', 'Hikaru Koike', '[{\'name\': \'Twister\', \'cost\': [\'Water\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'40\', \'text\': \'Flip 2 coins. For each heads, choose 1 Energy attached to the Defending Pokémon, if any, and discard it. If both are tails, this attack does nothing.\'}, {\'name\': \'Dragon Rage\', \'cost\': [\'Water\', \'Water\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 5, \'damage\': \'100\', \'text\': \'\'}]', 'FireRed & LeafGreen', '3', 'Magikarp', '', '', 'Third', '130', 'https://images.pokemoncard.io/images/ex6/ex6-109.png', 'unlimited: Legal', '', 'Gyarados ex', '130', 'TPCI', 'Rare Holo EX', '', '09/01/2004', '', 'Colorless, Colorless, Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '109', 'Stage 1, EX', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('ex6-11', '[{\'name\': \'Spiral\', \'text\': \"As long as Poliwrath is your Active Pokémon, your opponent\'s Confused Pokémon can\'t retreat.\", \'type\': \'Poké-Body\'}]', '', 'Ken Sugimori', '[{\'name\': \'Split Spiral Punch\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'The Defending Pokémon is now Confused.\'}, {\'name\': \'Mega Throw\', \'cost\': [\'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50+\', \'text\': \'If the Defending Pokémon is Pokémon-ex, this attack does 50 damage plus 30 more damage.\'}]', 'FireRed & LeafGreen', '2', 'Poliwhirl', '', '', 'Third', '120', 'https://images.pokemoncard.io/images/ex6/ex6-11.png', 'unlimited: Legal', '', 'Poliwrath', '62', 'TPCI', 'Rare Holo', '', '09/01/2004', '', 'Colorless, Colorless', '', 'EX', '11', 'Stage 2', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('ex6-110', '[{\'name\': \'Magic Odds\', \'text\': \"If Mr. Mime ex would be damaged by an attack, prevent that attack\'s damage done to Mr. Mime ex if that damage is 10, 30, 50, 70, 90, 110, 130, 150, or 170.\", \'type\': \'Poké-Body\'}]', '', 'Ryo Ueda', '[{\'name\': \'Breakdown\', \'cost\': [\'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'\', \'text\': \"Count the number of cards in your opponent\'s hand. Put that many damage counters on the Defending Pokémon.\"}]', 'FireRed & LeafGreen', '1', '', '', '', 'Third', '80', 'https://images.pokemoncard.io/images/ex6/ex6-110.png', 'unlimited: Legal', '', 'Mr. Mime ex', '122', 'TPCI', 'Rare Holo EX', '', '09/01/2004', '', 'Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '110', 'Basic, EX', 'Pokémon', 'Psychic', ''),
('ex6-111', '[{\'name\': \'Magic Evens\', \'text\': \"If Mr. Mime ex would be damaged by an attack, prevent that attack\'s damage done to Mr. Mime ex if that damage is 20, 40, 60, 80, 100, 120, 140, 160, or 180.\", \'type\': \'Poké-Body\'}]', '', 'Ryo Ueda', '[{\'name\': \'Breakdown\', \'cost\': [\'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'\', \'text\': \"Count the number of cards in your opponent\'s hand. Put that many damage counters on the Defending Pokémon.\"}]', 'FireRed & LeafGreen', '1', '', '', '', 'Third', '80', 'https://images.pokemoncard.io/images/ex6/ex6-111.png', 'unlimited: Legal', '', 'Mr. Mime ex', '122', 'TPCI', 'Rare Holo EX', '', '09/01/2004', '', 'Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '111', 'Basic, EX', 'Pokémon', 'Psychic', ''),
('ex6-112', '[{\'name\': \'Energy Trans\', \'text\': \"As often as you like during your turn (before your attack), move a Grass Energy card attached to 1 of your Pokémon to another of your Pokémon. This power can\'t be used if Venusaur ex is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Ryo Ueda', '[{\'name\': \'Pollen Hazard\', \'cost\': [\'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'20\', \'text\': \'The Defending Pokémon is now Poisoned, Burned, and Confused.\'}, {\'name\': \'Solarbeam\', \'cost\': [\'Grass\', \'Grass\', \'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 5, \'damage\': \'90\', \'text\': \'\'}]', 'FireRed & LeafGreen', '3', 'Ivysaur', '', '', 'Third', '150', 'https://images.pokemoncard.io/images/ex6/ex6-112.png', 'unlimited: Legal', '', 'Venusaur ex', '3', 'TPCI', 'Rare Holo EX', '', '09/01/2004', '', 'Colorless, Colorless, Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '112', 'Stage 2, EX', 'Pokémon', 'Grass', 'type: Psychic, value: ×2, type: Fire, value: ×2'),
('ex6-113', '', '', 'Ken Sugimori', '[{\'name\': \'Flare\', \'cost\': [\'Fire\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'\'}, {\'name\': \'Rage\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'10+\', \'text\': \'Does 10 damage plus 10 more damage for each damage counter on Charmander.\'}]', 'FireRed & LeafGreen', '1', '', 'Charmeleon', '', 'Third', '50', 'https://images.pokemoncard.io/images/ex6/ex6-113.png', 'unlimited: Legal', '', 'Charmander', '4', 'TPCI', 'Rare Secret', '', '09/01/2004', '', 'Colorless', '', 'EX', '113', 'Basic', 'Pokémon', 'Fire', 'type: Water, value: ×2');
INSERT INTO `cards` (`id`, `abilities`, `ancient_trait`, `artist`, `attacks`, `card_set`, `converted`, `evolves_from`, `evolves_to`, `flavor_text`, `generation`, `hp`, `img`, `legalities`, `level`, `name`, `national_pokedex_numbers`, `publisher`, `rarity`, `regulation_mark`, `release_date`, `resistances`, `retreat_cost`, `rules`, `series`, `set_num`, `subtypes`, `supertype`, `types`, `weakness`) VALUES
('ex6-114', '[{\'name\': \'Legendary Ascent\', \'text\': \'Once during your turn, when you put Articuno ex from your hand onto your Bench, you may switch 1 of your Active Pokémon with Articuno ex. If you do, you may also move any number of basic Water Energy cards attached to your Pokémon to Articuno ex.\', \'type\': \'Poké-Power\'}]', '', 'Ryo Ueda', '[{\'name\': \'Cold Crush\', \'cost\': [\'Water\', \'Water\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50\', \'text\': \'You may discard an Energy card attached to Articuno ex. If you do, your opponent discards an Energy card attached to the Defending Pokémon.\'}]', 'FireRed & LeafGreen', '2', '', '', '', 'Third', '110', 'https://images.pokemoncard.io/images/ex6/ex6-114.png', 'unlimited: Legal', '', 'Articuno ex', '144', 'TPCI', 'Rare Secret', '', '09/01/2004', '', 'Colorless, Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '114', 'Basic, EX', 'Pokémon', 'Water', 'type: Metal, value: ×2'),
('ex6-115', '[{\'name\': \'Legendary Ascent\', \'text\': \'Once during your turn, when you put Moltres ex from your hand onto your Bench, you may switch 1 of your Active Pokémon with Moltres ex. If you do, you may also move any number of basic Fire Energy cards attached to your Pokémon to Moltres ex.\', \'type\': \'Poké-Power\'}]', '', 'Ryo Ueda', '[{\'name\': \'Crushing Flames\', \'cost\': [\'Fire\', \'Fire\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60\', \'text\': \'You may discard an Energy card attached to Moltres ex. If you do, the Defending Pokémon is now Confused.\'}]', 'FireRed & LeafGreen', '2', '', '', '', 'Third', '110', 'https://images.pokemoncard.io/images/ex6/ex6-115.png', 'unlimited: Legal', '', 'Moltres ex', '146', 'TPCI', 'Rare Secret', '', '09/01/2004', '', 'Colorless, Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '115', 'Basic, EX', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('ex6-116', '[{\'name\': \'Legendary Ascent\', \'text\': \'Once during your turn, when you put Zapdos ex from your hand onto your Bench, you may switch 1 of your Active Pokémon with Zapdos ex. If you do, you may also move any number of basic Lightning Energy cards attached to your Pokémon to Zapdos ex.\', \'type\': \'Poké-Power\'}]', '', 'Ryo Ueda', '[{\'name\': \'Electron Crush\', \'cost\': [\'Lightning\', \'Lightning\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50+\', \'text\': \'You may discard an Energy card attached to Zapdos ex. If you do, this attack does 50 damage plus 20 more damage.\'}]', 'FireRed & LeafGreen', '2', '', '', '', 'Third', '110', 'https://images.pokemoncard.io/images/ex6/ex6-116.png', 'unlimited: Legal', '', 'Zapdos ex', '145', 'TPCI', 'Rare Secret', '', '09/01/2004', '', 'Colorless, Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '116', 'Basic, EX', 'Pokémon', 'Lightning', 'type: Lightning, value: ×2'),
('ex6-12', '', '', 'Midori Harada', '[{\'name\': \'Recharge\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Search your deck for up to 2 Lightning Energy cards and attach them to Raichu. Shuffle your deck afterward.\'}, {\'name\': \'Thunder Reflection\', \'cost\': [\'Lightning\', \'Lightning\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50\', \'text\': \'You may move any number of Lightning Energy cards attached to Raichu to another of your Pokémon.\'}]', 'FireRed & LeafGreen', '1', 'Pikachu', '', '', 'Third', '80', 'https://images.pokemoncard.io/images/ex6/ex6-12.png', 'unlimited: Legal', '', 'Raichu', '26', 'TPCI', 'Rare Holo', '', '09/01/2004', '', 'Colorless', '', 'EX', '12', 'Stage 1', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
('ex6-13', '[{\'name\': \'Fiery Aura\', \'text\': \'As long as Rapidash is your Active Pokémon, put 4 damage counters instead of 2 on Burned Pokémon between turns.\', \'type\': \'Poké-Body\'}]', '', 'Ken Sugimori', '[{\'name\': \'Searing Flame\', \'cost\': [\'Fire\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'10\', \'text\': \'The Defending Pokémon is now Burned.\'}, {\'name\': \'Rear Kick\', \'cost\': [\'Fire\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40\', \'text\': \'\'}]', 'FireRed & LeafGreen', '1', 'Ponyta', '', '', 'Third', '80', 'https://images.pokemoncard.io/images/ex6/ex6-13.png', 'unlimited: Legal', '', 'Rapidash', '78', 'TPCI', 'Rare Holo', '', '09/01/2004', '', 'Colorless', '', 'EX', '13', 'Stage 1', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('ex6-14', '[{\'name\': \'Strange Behavior\', \'text\': \"As often as you like during your turn (before your attack), you may move 1 damage counter from 1 of your Pokémon to Slowbro as long as you don\'t Knock Out Slowbro. This power can\'t be used if Slowbro is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Yuka Morii', '[{\'name\': \'Psyshock\', \'cost\': [\'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Paralyzed.\'}]', 'FireRed & LeafGreen', '1', 'Slowpoke', '', '', 'Third', '60', 'https://images.pokemoncard.io/images/ex6/ex6-14.png', 'unlimited: Legal', '', 'Slowbro', '80', 'TPCI', 'Rare Holo', '', '09/01/2004', '', 'Colorless', '', 'EX', '14', 'Stage 1', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2'),
('ex6-15', '[{\'name\': \'Rest Up\', \'text\': \'If Snorlax remains Asleep between turns, remove 2 damage counters from Snorlax (remove 1 if there is only 1).\', \'type\': \'Poké-Body\'}]', '', 'Kagemaru Himeno', '[{\'name\': \'Collapse\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'Snorlax is now Asleep.\'}, {\'name\': \'Toss and Turn\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'30+\', \'text\': \'If Snorlax is Asleep, this attack does 30 damage plus 30 more damage. (This attack can be used even if Snorlax is Asleep.)\'}]', 'FireRed & LeafGreen', '3', '', '', '', 'Third', '90', 'https://images.pokemoncard.io/images/ex6/ex6-15.png', 'unlimited: Legal', '', 'Snorlax', '143', 'TPCI', 'Rare Holo', '', '09/01/2004', '', 'Colorless, Colorless, Colorless', '', 'EX', '15', 'Basic', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('ex6-16', '', '', 'Masakazu Fukuda', '[{\'name\': \'Knock Over\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'You may discard any Stadium card in play.\'}, {\'name\': \'Rampage\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'20+\', \'text\': \'Does 20 damage plus 10 more damage for each damage counter on Tauros. After doing damage, flip a coin. If tails, Tauros is now Confused.\'}]', 'FireRed & LeafGreen', '1', '', '', '', 'Third', '70', 'https://images.pokemoncard.io/images/ex6/ex6-16.png', 'unlimited: Legal', '', 'Tauros', '128', 'TPCI', 'Rare Holo', '', '09/01/2004', '', 'Colorless', '', 'EX', '16', 'Basic', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('ex6-17', '[{\'name\': \'Acid Sampler\', \'text\': \'As long as Victreebel is your Active Pokémon, put 1 damage counter on each Defending Pokémon between turns. Acid Sampler stops working if your other Active Pokémon is not a Victreebel.\', \'type\': \'Poké-Body\'}]', '', 'Tomokazu Komiya', '[{\'name\': \'Acid\', \'cost\': [\'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50\', \'text\': \"The Defending Pokémon can\'t retreat until the end of your opponent\'s next turn.\"}]', 'FireRed & LeafGreen', '2', 'Weepinbell', '', '', 'Third', '110', 'https://images.pokemoncard.io/images/ex6/ex6-17.png', 'unlimited: Legal', '', 'Victreebel', '71', 'TPCI', 'Rare Holo', '', '09/01/2004', '', 'Colorless, Colorless', '', 'EX', '17', 'Stage 2', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('ex6-18', '', '', 'Ken Sugimori', '[{\'name\': \'Flare\', \'cost\': [\'Fire\'], \'convertedEnergyCost\': 1, \'damage\': \'20\', \'text\': \'\'}, {\'name\': \'Heat Tackle\', \'cost\': [\'Fire\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'70\', \'text\': \'Arcanine does 10 damage to itself.\'}]', 'FireRed & LeafGreen', '2', 'Growlithe', '', '', 'Third', '90', 'https://images.pokemoncard.io/images/ex6/ex6-18.png', 'unlimited: Legal', '', 'Arcanine', '59', 'TPCI', 'Rare', '', '09/01/2004', '', 'Colorless, Colorless', '', 'EX', '18', 'Stage 1', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('ex6-19', '', '', 'Miki Tanaka', '[{\'name\': \'Sing\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'The Defending Pokémon is now Asleep.\'}, {\'name\': \'Egg Surprise\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'\', \'text\': \'Flip a coin. If heads, Chansey does 50 damage to the Defending Pokémon. If tails, remove 5 damage counters from Chansey. (All if there are less than 5.)\'}]', 'FireRed & LeafGreen', '2', '', 'Blissey', '', 'Third', '90', 'https://images.pokemoncard.io/images/ex6/ex6-19.png', 'unlimited: Legal', '', 'Chansey', '113', 'TPCI', 'Rare', '', '09/01/2004', '', 'Colorless, Colorless', '', 'EX', '19', 'Basic', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
