('ex6-97', '', '', 'Hiromichi Sugiyama', '', 'FireRed & LeafGreen', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex6/ex6-97.png', 'unlimited: Legal', '', 'Pokémon Reversal', '', 'TPCI', 'Uncommon', '', '09/01/2004', '', '', '[\"Flip a coin. If heads, choose 1 of your opponent\'s Benched Pokémon and switch it with 1 of the Defending Pokémon. Your opponent chooses the Defending Pokémon to switch.\"]', 'EX', '97', 'Item', 'Trainer', '', ''),
('ex6-98', '', '', 'Ken Sugimori', '', 'FireRed & LeafGreen', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex6/ex6-98.png', 'unlimited: Legal', '', 'Prof. Oaks Research', '', 'TPCI', 'Uncommon', '', '09/01/2004', '', '', '[\'You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.\', \'Shuffle your hand into your deck, then draw 5 cards.\']', 'EX', '98', 'Supporter', 'Trainer', '', ''),
