('ex7-18', '[{\'name\': \'Poison Payback\', \'text\': \"If Dark Sandslash is your Active Pokémon and is damaged by an opponent\'s attack (even if Dark Sandslash is Knocked Out), the Attacking Pokémon is now Poisoned.\", \'type\': \'Poké-Body\'}]', '', 'Masakazu Fukuda', '[{\'name\': \'Swift\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50\', \'text\': \"This attack\'s damage isn\'t affected by Weakness, Resistance, Poké-Powers, Poké-Bodies, or any other effects on the Defending Pokémon.\"}]', 'Team Rocket Returns', '', 'Sandshrew', '', '', 'Third', '70', 'https://images.pokemoncard.io/images/ex7/ex7-18.png', 'unlimited: Legal', '', 'Dark Sandslash', '28', 'TPCI', 'Rare', '', '11/01/2004', '', '', '[\'This Pokémon is both Fighting Darkness type.\']', 'EX', '18', 'Stage 1', 'Pokémon', 'Fighting, Darkness', 'type: Grass, value: ×2'),
('ex7-19', '', '', 'Nakaoka', '[{\'name\': \'Grind\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10+\', \'text\': \'Does 10 damage plus 10 more damage for each Energy attached to Dark Tyranitar.\'}, {\'name\': \'Spinning Tail\', \'cost\': [\'Darkness\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'\', \'text\': \"Does 20 damage to each of your opponent\'s Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}, {\'name\': \'Bite Off\', \'cost\': [\'Darkness\', \'Darkness\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 5, \'damage\': \'70+\', \'text\': \'If the Defending Pokémon is Pokémon-ex, this attack does 70 damage plus 50 more damage.\'}]', 'Team Rocket Returns', '2', 'Dark Pupitar', '', '', 'Third', '120', 'https://images.pokemoncard.io/images/ex7/ex7-19.png', 'unlimited: Legal', '', 'Dark Tyranitar', '248', 'TPCI', 'Rare', '', '11/01/2004', 'type: Psychic, value: -30', 'Colorless, Colorless', '', 'EX', '19', 'Stage 2', 'Pokémon', 'Darkness', 'type: Fighting, value: ×2'),
('ex7-2', '[{\'name\': \'Darkest Impulse\', \'text\': \"As long as Dark Ampharos is in play, whenever your opponent plays an Evolution card from his or her hand to evolve 1 of his or her Pokémon, put 2 damage counters on that Pokémon. You can\'t use more than 1 Darkest Impulse Poké-Body each turn.\", \'type\': \'Poké-Body\'}]', '', 'Emi Miwa', '[{\'name\': \'Ram\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'\'}, {\'name\': \'Shock Bolt\', \'cost\': [\'Lightning\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'70\', \'text\': \'Discard all Lightning Energy attached to Dark Ampharos.\'}]', 'Team Rocket Returns', '2', 'Dark Flaaffy', '', '', 'Third', '120', 'https://images.pokemoncard.io/images/ex7/ex7-2.png', 'unlimited: Legal', '', 'Dark Ampharos', '181', 'TPCI', 'Rare Holo', '', '11/01/2004', '', 'Colorless, Colorless', '[\'This Pokémon is both Lightning Darkness type.\']', 'EX', '2', 'Stage 2', 'Pokémon', 'Lightning, Darkness', 'type: Fighting, value: ×2'),
('ex7-20', '[{\'name\': \'Sand Damage\', \'text\': \"As long as Dark Tyranitar is your Active Pokémon, put 1 damage counter on each of your opponent\'s Benched Basic Pokémon between turns. You can\'t use more than 1 Sand Damage Poké-Body between turns.\", \'type\': \'Poké-Body\'}]', '', 'Kyoko Koizumi', '[{\'name\': \'Second Strike\', \'cost\': [\'Fighting\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50+\', \'text\': \'If the Defending Pokémon already has at least 2 damage counters on it, this attack does 50 damage plus 20 more damage.\'}]', 'Team Rocket Returns', '3', 'Dark Pupitar', '', '', 'Third', '120', 'https://images.pokemoncard.io/images/ex7/ex7-20.png', 'unlimited: Legal', '', 'Dark Tyranitar', '248', 'TPCI', 'Rare', '', '11/01/2004', '', 'Colorless, Colorless, Colorless', '[\'This Pokémon is both Fighting Darkness type.\']', 'EX', '20', 'Stage 2', 'Pokémon', 'Fighting, Darkness', 'type: Grass, value: ×2'),
('ex7-21', '[{\'name\': \'Gift Exchange\', \'text\': \"Once during your turn (before your attack), if Delibird is your Active Pokémon, you may shuffle 1 card from your hand into your deck. Then, draw a card. This power can\'t be used if Delibird is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Yuka Morii', '[{\'name\': \'Souvenir\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'\', \'text\': \'Flip 3 coins. If 1 of them is heads, put 4 damage counters on the Defending Pokémon. If 2 of them are heads, remove 1 damage counter from the Defending Pokémon. If all of them are heads, put 10 damage counters on the Defending Pokémon. If all of them are tails, remove all damage counters from the Defending Pokémon.\'}]', 'Team Rocket Returns', '1', '', '', '', 'Third', '70', 'https://images.pokemoncard.io/images/ex7/ex7-21.png', 'unlimited: Legal', '', 'Delibird', '225', 'TPCI', 'Rare', '', '11/01/2004', '', 'Colorless', '', 'EX', '21', 'Basic', 'Pokémon', 'Water', 'type: Metal, value: ×2'),
('ex7-22', '', '', 'Yuka Morii', '[{\'name\': \'Quick Change\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Choose up to 3 cards in your hand and put them on top of your deck. Then, search your deck for that many cards and put them into your hand. Shuffle your deck afterward.\'}, {\'name\': \'Quick Tail Smash\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'Before doing damage, you may flip a coin. If heads, this attack does 80 damage instead. If tails, this attack does nothing.\'}]', 'Team Rocket Returns', '1', 'Sentret', '', '', 'Third', '80', 'https://images.pokemoncard.io/images/ex7/ex7-22.png', 'unlimited: Legal', '', 'Furret', '162', 'TPCI', 'Rare', '', '11/01/2004', '', 'Colorless', '', 'EX', '22', 'Stage 1', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('ex7-23', '[{\'name\': \'Powder Protection\', \'text\': \'Any damage done to Ledian by attacks from Pokémon that has an owner in its name is reduced by 40.\', \'type\': \'Poké-Body\'}]', '', 'Kagemaru Himeno', '[{\'name\': \'Split Spiral Punch\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Confused.\'}, {\'name\': \'Tackle\', \'cost\': [\'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50\', \'text\': \'\'}]', 'Team Rocket Returns', '1', 'Ledyba', '', '', 'Third', '70', 'https://images.pokemoncard.io/images/ex7/ex7-23.png', 'unlimited: Legal', '', 'Ledian', '166', 'TPCI', 'Rare', '', '11/01/2004', '', 'Colorless', '', 'EX', '23', 'Stage 1', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('ex7-24', '[{\'name\': \'Baby Evolution\', \'text\': \'Once during your turn (before your attack), you may put Magmar from your hand onto Magby (this counts as evolving Magby), and remove all damage counters from Magby.\', \'type\': \'Poké-Power\'}]', '', 'Yukiko Baba', '[{\'name\': \'Detour\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'If you have a Supporter card in play, use the effect on that card as the effect of this attack.\'}]', 'Team Rocket Returns', '1', '', 'Magmar', '', 'Third', '50', 'https://images.pokemoncard.io/images/ex7/ex7-24.png', 'unlimited: Legal', '', 'Magby', '240', 'TPCI', 'Rare', '', '11/01/2004', '', 'Colorless', '', 'EX', '24', 'Basic', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('ex7-25', '[{\'name\': \'Dark Spell\', \'text\': \"Once during your turn (before your attack), if Misdreavus is your Active Pokémon, you may flip a coin. If heads, put 1 damage counter on 1 of your opponent\'s Pokémon. This power can\'t be used if Misdreavus is affected by a Special Condition or if your other Active Pokémon is not Misdreavus.\", \'type\': \'Poké-Power\'}]', '', 'Aya Kusube', '[{\'name\': \'Hide in Shadows\', \'cost\': [\'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'Switch Misdreavus with 1 of your Benched Pokémon.\'}]', 'Team Rocket Returns', '1', '', 'Mismagius', '', 'Third', '60', 'https://images.pokemoncard.io/images/ex7/ex7-25.png', 'unlimited: Legal', '', 'Misdreavus', '200', 'TPCI', 'Rare', '', '11/01/2004', 'type: Fighting, value: -30', 'Colorless', '', 'EX', '25', 'Basic', 'Pokémon', 'Psychic', 'type: Darkness, value: ×2'),
('ex7-26', '[{\'name\': \'Saturation\', \'text\': \'When you attach a Water Energy card from your hand to Quagsire, remove all Special Conditions and 2 damage counters from Quagsire.\', \'type\': \'Poké-Body\'}]', '', 'Miki Tanaka', '[{\'name\': \'Hyper Pump\', \'cost\': [\'Water\'], \'convertedEnergyCost\': 1, \'damage\': \'20+\', \'text\': \"Does 20 damage plus 20 more damage for each basic Energy card attached to Quagsire but not used to pay for this attack\'s Energy cost. You can\'t add more than 60 damage in this way.\"}]', 'Team Rocket Returns', '2', 'Wooper', '', '', 'Third', '80', 'https://images.pokemoncard.io/images/ex7/ex7-26.png', 'unlimited: Legal', '', 'Quagsire', '195', 'TPCI', 'Rare', '', '11/01/2004', '', 'Colorless, Colorless', '', 'EX', '26', 'Stage 1', 'Pokémon', 'Water', 'type: Grass, value: ×2');
INSERT INTO `cards` (`id`, `abilities`, `ancient_trait`, `artist`, `attacks`, `card_set`, `converted`, `evolves_from`, `evolves_to`, `flavor_text`, `generation`, `hp`, `img`, `legalities`, `level`, `name`, `national_pokedex_numbers`, `publisher`, `rarity`, `regulation_mark`, `release_date`, `resistances`, `retreat_cost`, `rules`, `series`, `set_num`, `subtypes`, `supertype`, `types`, `weakness`) VALUES
('ex7-27', '[{\'name\': \'Spiny\', \'text\': \"If Qwilfish is your Active Pokémon and is damaged by an opponent\'s attack (even if Qwilfish is Knocked Out), flip a coin until you get tails. For each heads, put 1 damage counter on the Attacking Pokémon.\", \'type\': \'Poké-Body\'}]', '', 'Aya Kusube', '[{\'name\': \'Stun Poison\', \'cost\': [\'Water\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'10\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Paralyzed and Poisoned.\'}]', 'Team Rocket Returns', '1', '', '', '', 'Third', '60', 'https://images.pokemoncard.io/images/ex7/ex7-27.png', 'unlimited: Legal', '', 'Qwilfish', '211', 'TPCI', 'Rare', '', '11/01/2004', '', 'Colorless', '', 'EX', '27', 'Basic', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('ex7-28', '', '', 'Tomokazu Komiya', '[{\'name\': \'Quick Charge\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Search your deck for up to 4 different types of basic Energy cards, show them to your opponent, and put them into your hand. Shuffle your deck afterward.\'}, {\'name\': \'Swift\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'20\', \'text\': \"This attack\'s damage isn\'t affected by Weakness, Resistance, Poké-Powers, Poké-Bodies, or any other effects on the Defending Pokémon.\"}]', 'Team Rocket Returns', '1', '', 'Yanmega', '', 'Third', '70', 'https://images.pokemoncard.io/images/ex7/ex7-28.png', 'unlimited: Legal', '', 'Yanma', '193', 'TPCI', 'Rare', '', '11/01/2004', 'type: Fighting, value: -30', 'Colorless', '', 'EX', '28', 'Basic', 'Pokémon', 'Grass', 'type: Lightning, value: ×2'),
('ex7-29', '', '', 'Nakaoka', '[{\'name\': \'Swallow Up\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'10+\', \'text\': \"Before doing damage, count the remaining HP of the Defending Pokémon and Dark Arbok. If the Defending Pokémon has fewer remaining HP than Dark Arbok\'s, this attack does 10 damage plus 30 more damage.\"}, {\'name\': \'Extra Poison\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'If the Defending Pokémon is Pokémon-ex, the Defending Pokémon is now Asleep and Poisoned.\'}]', 'Team Rocket Returns', '1', 'Ekans', '', '', 'Third', '90', 'https://images.pokemoncard.io/images/ex7/ex7-29.png', 'unlimited: Legal', '', 'Dark Arbok', '24', 'TPCI', 'Uncommon', '', '11/01/2004', '', 'Colorless', '[\'This Pokémon is both Grass Darkness type.\']', 'EX', '29', 'Stage 1', 'Pokémon', 'Grass, Darkness', 'type: Psychic, value: ×2'),
('ex7-3', '[{\'name\': \'Black Beam\', \'text\': \"Once during your turn (before your attack), if Dark Crobat is your Active Pokémon, you may choose 1 of the Defending Pokémon. That Pokémon is now Poisoned. This power can\'t be used if Dark Crobat is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Kyoko Koizumi', '[{\'name\': \'Dark Drain\', \'cost\': [\'Grass\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'\', \'text\': \"Does 10 damage to each of your opponent\'s Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.) Remove from Dark Crobat a number of damage counters equal to the number of your opponent\'s Pokémon in play.\"}, {\'name\': \'Skill Dive\', \'cost\': [\'Grass\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'\', \'text\': \"Does 30 damage to 1 of your opponent\'s Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'Team Rocket Returns', '1', 'Dark Golbat', '', '', 'Third', '90', 'https://images.pokemoncard.io/images/ex7/ex7-3.png', 'unlimited: Legal', '', 'Dark Crobat', '169', 'TPCI', 'Rare Holo', '', '11/01/2004', 'type: Fighting, value: -30', 'Colorless', '[\'This Pokémon is both Grass Darkness type.\']', 'EX', '3', 'Stage 2', 'Pokémon', 'Grass, Darkness', 'type: Lightning, value: ×2'),
('ex7-30', '', '', 'Kyoko Koizumi', '[{\'name\': \'Super Poison Breath\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Each Defending Pokémon is now Poisoned.\'}, {\'name\': \'Breaking Impact\', \'cost\': [\'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'\', \'text\': \"Choose 1 of your opponent\'s Pokémon. This attack does 20 damage for each Colorless Energy in that Pokémon\'s Retreat Cost (after applying effects to the Retreat Cost). (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'Team Rocket Returns', '1', 'Spinarak', '', '', 'Third', '70', 'https://images.pokemoncard.io/images/ex7/ex7-30.png', 'unlimited: Legal', '', 'Dark Ariados', '168', 'TPCI', 'Uncommon', '', '11/01/2004', '', 'Colorless', '[\'This Pokémon is both Grass Darkness type.\']', 'EX', '30', 'Stage 1', 'Pokémon', 'Grass, Darkness', 'type: Fire, value: ×2'),
('ex7-31', '[{\'name\': \'Evolutionary Light\', \'text\': \"Once during your turn (before your attack), if Dark Dragonair is your Active Pokémon, you may search your deck for an Evolution card. Show it to your opponent and put it into your hand. Shuffle your deck afterward. This power can\'t be used if Dark Dragonair is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Emi Miwa', '[{\'name\': \'Dragon Rage\', \'cost\': [\'Water\', \'Lightning\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'\'}]', 'Team Rocket Returns', '1', 'Dratini', 'Dragonite', '', 'Third', '70', 'https://images.pokemoncard.io/images/ex7/ex7-31.png', 'unlimited: Legal', '', 'Dark Dragonair', '148', 'TPCI', 'Uncommon', '', '11/01/2004', 'type: Grass, value: -30, type: Fighting, value: -30', 'Colorless', '', 'EX', '31', 'Stage 1', 'Pokémon', 'Darkness', 'type: Colorless, value: ×2'),
('ex7-32', '', '', 'Tomoaki Imakuni', '[{\'name\': \'Double Tackle\', \'cost\': [\'Water\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'\', \'text\': \'Does 20 damage to each Defending Pokémon.\'}, {\'name\': \'Crushing Blow\', \'cost\': [\'Lightning\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40\', \'text\': \'Flip a coin. If heads, discard an Energy card attached to the Defending Pokémon.\'}]', 'Team Rocket Returns', '1', 'Dratini', 'Dragonite', '', 'Third', '80', 'https://images.pokemoncard.io/images/ex7/ex7-32.png', 'unlimited: Legal', '', 'Dark Dragonair', '148', 'TPCI', 'Uncommon', '', '11/01/2004', 'type: Grass, value: -30, type: Fighting, value: -30', 'Colorless', '', 'EX', '32', 'Stage 1', 'Pokémon', 'Darkness', 'type: Colorless, value: ×2'),
('ex7-33', '', '', 'Masakazu Fukuda', '[{\'name\': \'Thunder Slash\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \"If the Defending Pokémon is a Basic Pokémon, the Defending Pokémon is now Paralyzed. Dark Flaaffy can\'t use Thunder Slash during your next turn.\"}, {\'name\': \'Headbutt\', \'cost\': [\'Lightning\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'\'}]', 'Team Rocket Returns', '1', 'Mareep', 'Ampharos', '', 'Third', '80', 'https://images.pokemoncard.io/images/ex7/ex7-33.png', 'unlimited: Legal', '', 'Dark Flaaffy', '180', 'TPCI', 'Uncommon', '', '11/01/2004', '', 'Colorless', '[\'This Pokémon is both Lightning Darkness type.\']', 'EX', '33', 'Stage 1', 'Pokémon', 'Lightning, Darkness', 'type: Fighting, value: ×2'),
('ex7-34', '', '', 'Masakazu Fukuda', '[{\'name\': \'Night Ambush\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Does 30 damage to 1 of your opponent\'s Pokémon. Dark Golbat can\'t attack during your next turn. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'Team Rocket Returns', '', 'Zubat', 'Crobat', '', 'Third', '70', 'https://images.pokemoncard.io/images/ex7/ex7-34.png', 'unlimited: Legal', '', 'Dark Golbat', '42', 'TPCI', 'Uncommon', '', '11/01/2004', '', '', '[\'This Pokémon is both Grass Darkness type.\']', 'EX', '34', 'Stage 1', 'Pokémon', 'Grass, Darkness', 'type: Psychic, value: ×2'),
('ex7-35', '', '', 'Nakaoka', '[{\'name\': \'Darkness Shield\', \'cost\': [\'Water\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \"Flip a coin. If heads, prevent all effects of an attack, including damage, done to each of your Active Pokémon during your opponent\'s next turn.\"}, {\'name\': \'Cold Crush\', \'cost\': [\'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40\', \'text\': \'You may discard an Energy card attached to Dark Golduck. If you do, discard an Energy attached to the Defending Pokémon.\'}]', 'Team Rocket Returns', '1', 'Psyduck', '', '', 'Third', '70', 'https://images.pokemoncard.io/images/ex7/ex7-35.png', 'unlimited: Legal', '', 'Dark Golduck', '55', 'TPCI', 'Uncommon', '', '11/01/2004', '', 'Colorless', '[\'This Pokémon is both Water Darkness type.\']', 'EX', '35', 'Stage 1', 'Pokémon', 'Water, Darkness', 'type: Lightning, value: ×2'),
('ex7-36', '[{\'name\': \'Dark Scale\', \'text\': \"If Dark Gyarados is your Active Pokémon and is Knocked Out by an opponent\'s attack, put 3 damage counters on the Attacking Pokémon.\", \'type\': \'Poké-Body\'}]', '', 'Nakaoka', '[{\'name\': \'Sharp Fang\', \'cost\': [\'Water\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'\'}, {\'name\': \'Dark Streak\', \'cost\': [\'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40\', \'text\': \'Flip a coin. If heads, each Defending Pokémon is now Paralyzed.\'}]', 'Team Rocket Returns', '2', 'Magikarp', '', '', 'Third', '80', 'https://images.pokemoncard.io/images/ex7/ex7-36.png', 'unlimited: Legal', '', 'Dark Gyarados', '130', 'TPCI', 'Uncommon', '', '11/01/2004', 'type: Fighting, value: -30', 'Colorless, Colorless', '[\'This Pokémon is both Water Darkness type.\']', 'EX', '36', 'Stage 1', 'Pokémon', 'Water, Darkness', 'type: Lightning, value: ×2'),
('ex7-37', '[{\'name\': \'Fire Breath\', \'text\': \"Once during your turn (before your attack), if Dark Houndoom is your Active Pokémon, you may flip a coin. If heads, the Defending Pokémon (choose 1 if there are 2) is now Burned. This power can\'t be used if Dark Houndoom is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Nakaoka', '[{\'name\': \'Fire Payback\', \'cost\': [\'Fire\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40+\', \'text\': \'If you have less Benched Pokémon than your opponent, this attack does 40 damage plus 20 more damage.\'}]', 'Team Rocket Returns', '1', 'Houndour', '', '', 'Third', '70', 'https://images.pokemoncard.io/images/ex7/ex7-37.png', 'unlimited: Legal', '', 'Dark Houndoom', '229', 'TPCI', 'Uncommon', '', '11/01/2004', '', 'Colorless', '[\'This Pokémon is both Fire Darkness type.\']', 'EX', '37', 'Stage 1', 'Pokémon', 'Fire, Darkness', 'type: Water, value: ×2'),
('ex7-38', '', '', 'Nakaoka', '[{\'name\': \'Energy Press\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10+\', \'text\': \'Does 10 damage plus 10 more damage for each basic Energy card attached to all of your Active Pokémon.\'}, {\'name\': \'Linear Attack\', \'cost\': [\'Fighting\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'\', \'text\': \"Choose 1 of your opponent\'s Pokémon. This attack does 40 damage to that Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'Team Rocket Returns', '2', 'Slugma', '', '', 'Third', '80', 'https://images.pokemoncard.io/images/ex7/ex7-38.png', 'unlimited: Legal', '', 'Dark Magcargo', '219', 'TPCI', 'Uncommon', '', '11/01/2004', '', 'Colorless, Colorless', '[\'This Pokémon is both Fire Darkness type.\']', 'EX', '38', 'Stage 1', 'Pokémon', 'Fire, Darkness', 'type: Water, value: ×2'),
('ex7-39', '', '', 'Emi Miwa', '[{\'name\': \'Magnetic Lines\', \'cost\': [\'Lightning\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \"If your opponent has at least 2 Pokémon in play, move a basic Energy card from the Defending Pokémon to another of your opponent\'s Pokémon.\"}, {\'name\': \'Poison Pulse\', \'cost\': [\'Lightning\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40\', \'text\': \'The Defending Pokémon is now Poisoned.\'}]', 'Team Rocket Returns', '1', 'Magnemite', 'Magnezone', '', 'Third', '70', 'https://images.pokemoncard.io/images/ex7/ex7-39.png', 'unlimited: Legal', '', 'Dark Magneton', '82', 'TPCI', 'Uncommon', '', '11/01/2004', '', 'Colorless', '[\'This Pokémon is both Lightning Darkness type.\']', 'EX', '39', 'Stage 1', 'Pokémon', 'Lightning, Darkness', 'type: Fighting, value: ×2'),
('ex7-4', '[{\'name\': \'Darkness Navigation\', \'text\': \"Once during your turn (before your attack), if Dark Electrode has no Energy attached to it, you may search your deck for a Darkness or Dark Metal Energy and attach it to Dark Electrode. Shuffle your deck afterward. This power can\'t be used if Dark Electrode is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Kouki Saitou', '[{\'name\': \'Energy Bomb\', \'cost\': [\'Lightning\'], \'convertedEnergyCost\': 1, \'damage\': \'30\', \'text\': \'You may move all Energy cards attached to Dark Electrode to your Benched Pokémon in any way you like.\'}]', 'Team Rocket Returns', '1', 'Voltorb', '', '', 'Third', '70', 'https://images.pokemoncard.io/images/ex7/ex7-4.png', 'unlimited: Legal', '', 'Dark Electrode', '101', 'TPCI', 'Rare Holo', '', '11/01/2004', '', 'Colorless', '[\'This Pokémon is both Lightning Darkness type.\']', 'EX', '4', 'Stage 1', 'Pokémon', 'Lightning, Darkness', 'type: Fighting, value: ×2'),
('ex7-40', '', '', 'Tomoaki Imakuni', '[{\'name\': \'Explosive Evolution\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Flip a coin. If heads, this attack does 10 damage to each of your opponent\'s Pokémon. (Don\'t apply Weakness and Resistance.) Then, search your deck for a card that evolves from Dark Pupitar and put it on Dark Pupitar. (This counts as evolving Dark Pupitar.) Shuffle your deck afterward.\"}, {\'name\': \'Double Tackle\', \'cost\': [\'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'\', \'text\': \'Does 20 damage to each Defending Pokémon.\'}]', 'Team Rocket Returns', '1', 'Larvitar', 'Tyranitar', '', 'Third', '70', 'https://images.pokemoncard.io/images/ex7/ex7-40.png', 'unlimited: Legal', '', 'Dark Pupitar', '247', 'TPCI', 'Uncommon', '', '11/01/2004', '', 'Colorless', '[\'This Pokémon is both Fighting Darkness type.\']', 'EX', '40', 'Stage 1', 'Pokémon', 'Fighting, Darkness', 'type: Grass, value: ×2'),
('ex7-41', '', '', 'Emi Miwa', '[{\'name\': \'Dark Streak\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'Flip a coin. If heads, each Defending Pokémon is now Paralyzed.\'}, {\'name\': \'Rock Tumble\', \'cost\': [\'Fighting\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40\', \'text\': \"This attack\'s damage is not affected by Resistance.\"}]', 'Team Rocket Returns', '2', 'Larvitar', 'Tyranitar', '', 'Third', '80', 'https://images.pokemoncard.io/images/ex7/ex7-41.png', 'unlimited: Legal', '', 'Dark Pupitar', '247', 'TPCI', 'Uncommon', '', '11/01/2004', '', 'Colorless, Colorless', '[\'This Pokémon is both Fighting Darkness type.\']', 'EX', '41', 'Stage 1', 'Pokémon', 'Fighting, Darkness', 'type: Grass, value: ×2'),
('ex7-42', '[{\'name\': \'Methane Leak\', \'text\': \'As long as Dark Weezing is your Active Pokémon, put 1 damage counter on each Pokémon that remains Poisoned between turns.\', \'type\': \'Poké-Body\'}]', '', 'Mitsuhiro Arita', '[{\'name\': \'Smog\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'The Defending Pokémon is now Poisoned.\'}, {\'name\': \'Darkness Charge\', \'cost\': [\'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50\', \'text\': \'Put 2 damage counters on Dark Weezing.\'}]', 'Team Rocket Returns', '2', 'Koffing', '', '', 'Third', '80', 'https://images.pokemoncard.io/images/ex7/ex7-42.png', 'unlimited: Legal', '', 'Dark Weezing', '110', 'TPCI', 'Uncommon', '', '11/01/2004', '', 'Colorless, Colorless', '[\'This Pokémon is both Grass Darkness type.\']', 'EX', '42', 'Stage 1', 'Pokémon', 'Grass, Darkness', 'type: Psychic, value: ×2'),
('ex7-43', '[{\'name\': \'Crust\', \'text\': \"Any damage done to Heracross by attacks from your opponent\'s Basic Pokémon is reduced by 20 (after applying Weakness and Resistance).\", \'type\': \'Poké-Body\'}]', '', 'Tomokazu Komiya', '[{\'name\': \'Get Even\', \'cost\': [\'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20+\', \'text\': \'If you have more Prize cards left than your opponent, this attack does 20 damage plus 10 more damage for each Prize card more than your opponent.\'}]', 'Team Rocket Returns', '1', '', '', '', 'Third', '70', 'https://images.pokemoncard.io/images/ex7/ex7-43.png', 'unlimited: Legal', '', 'Heracross', '214', 'TPCI', 'Uncommon', '', '11/01/2004', '', 'Colorless', '', 'EX', '43', 'Basic', 'Pokémon', 'Fighting', 'type: Psychic, value: ×2'),
('ex7-44', '', '', 'Yukiko Baba', '[{\'name\': \'Dump and Draw\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Discard up to 2 Energy cards from your hand. Then, draw 2 cards for each Energy card you discarded.\'}, {\'name\': \'Flame Tail\', \'cost\': [\'Fire\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40\', \'text\': \'\'}]', 'Team Rocket Returns', '1', '', 'Magmortar', '', 'Third', '70', 'https://images.pokemoncard.io/images/ex7/ex7-44.png', 'unlimited: Legal', '', 'Magmar', '126', 'TPCI', 'Uncommon', '', '11/01/2004', '', 'Colorless', '', 'EX', '44', 'Basic', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('ex7-45', '[{\'name\': \'Ripples\', \'text\': \"Once during your turn (before your attack), you may remove 1 damage counter from 1 of your Pokémon (excluding Mantine). This power can\'t be used if Mantine is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Miki Tanaka', '[{\'name\': \'Aqua Slash\', \'cost\': [\'Water\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \"Mantine can\'t attack during your next turn.\"}]', 'Team Rocket Returns', '1', '', '', '', 'Third', '70', 'https://images.pokemoncard.io/images/ex7/ex7-45.png', 'unlimited: Legal', '', 'Mantine', '226', 'TPCI', 'Uncommon', '', '11/01/2004', '', 'Colorless', '', 'EX', '45', 'Basic', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('ex7-46', '', '', 'Mitsuhiro Arita', '[{\'name\': \'Snatch and Run\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Search your deck for a Pokémon Tool card or Rocket\'s Secret Machine card, show it to your opponent, and put it into your hand. If you do, you may switch Rocket\'s Meowth with 1 of your Benched Pokémon. Shuffle your deck afterward.\"}, {\'name\': \'Miraculous Comeback\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'10×\', \'text\': \"Flip a coin for each Pokémon in play (both yours and your opponent\'s). This attack does 10 damage times the number of heads. Rocket\'s Meowth does 10 damage times the number of tails to itself.\"}]', 'Team Rocket Returns', '1', '', 'Persian', '', 'Third', '60', 'https://images.pokemoncard.io/images/ex7/ex7-46.png', 'unlimited: Legal', '', 'Rockets Meowth', '52', 'TPCI', 'Uncommon', '', '11/01/2004', '', 'Colorless', '', 'EX', '46', 'Basic', 'Pokémon', 'Darkness', 'type: Fighting, value: ×2'),
