('ex7-71', '[{\'name\': \'Scramble\', \'text\': \'As long as your opponent has any Pokémon-ex as his or her Active Pokémon, the Retreat Cost for Rattata is 0.\', \'type\': \'Poké-Body\'}]', '', 'Aya Kusube', '[{\'name\': \'Fury Swipes\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10×\', \'text\': \'Flip 3 coins. This attack does 10 damage times the number of heads.\'}]', 'Team Rocket Returns', '1', '', 'Raticate', '', 'Third', '40', 'https://images.pokemoncard.io/images/ex7/ex7-71.png', 'unlimited: Legal', '', 'Rattata', '19', 'TPCI', 'Common', '', '11/01/2004', '', 'Colorless', '', 'EX', '71', 'Basic', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('ex7-72', '', '', 'Naoyo Kimura', '[{\'name\': \'Call for Family\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Search your deck for a Basic Pokémon and put it onto your Bench. Shuffle your deck afterward.\'}, {\'name\': \'Snarl\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Flip a coin. If heads, this attack does 10 damage to the Defending Pokémon. If tails, the Defending Pokémon is now Paralyzed.\'}]', 'Team Rocket Returns', '1', '', 'Raticate', '', 'Third', '40', 'https://images.pokemoncard.io/images/ex7/ex7-72.png', 'unlimited: Legal', '', 'Rattata', '19', 'TPCI', 'Common', '', '11/01/2004', '', 'Colorless', '', 'EX', '72', 'Basic', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('ex7-73', '', '', 'Midori Harada', '[{\'name\': \'Energy Draw\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Flip a coin. If heads, search your deck for a basic Energy card and attach it to Remoraid. Shuffle your deck afterward.\'}, {\'name\': \'Razor Fin\', \'cost\': [\'Water\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'\'}]', 'Team Rocket Returns', '1', '', 'Octillery', '', 'Third', '50', 'https://images.pokemoncard.io/images/ex7/ex7-73.png', 'unlimited: Legal', '', 'Remoraid', '223', 'TPCI', 'Common', '', '11/01/2004', '', 'Colorless', '', 'EX', '73', 'Basic', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('ex7-74', '', '', 'Atsuko Nishida', '[{\'name\': \'Rear Kick\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'\'}, {\'name\': \'Swift\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \"This attack\'s damage isn\'t affected by Weakness, Resistance, Poké-Powers, Poké-Bodies, or any other effects on the Defending Pokémon.\"}]', 'Team Rocket Returns', '1', '', 'Sandslash', '', 'Third', '50', 'https://images.pokemoncard.io/images/ex7/ex7-74.png', 'unlimited: Legal', '', 'Sandshrew', '27', 'TPCI', 'Common', '', '11/01/2004', '', 'Colorless', '', 'EX', '74', 'Basic', 'Pokémon', 'Fighting', 'type: Grass, value: ×2'),
('ex7-75', '', '', 'Yuka Morii', '[{\'name\': \'Friend Search\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Look at the top 5 cards of your deck. Choose a Basic Pokémon or Evolution card you find there, show it to your opponent, and put it into your hand. Put the other 4 cards back on top of your deck. Shuffle your deck afterward.\'}, {\'name\': \'Surprise Attack\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'20\', \'text\': \'Flip a coin. If tails, this attack does nothing.\'}]', 'Team Rocket Returns', '1', '', 'Furret', '', 'Third', '50', 'https://images.pokemoncard.io/images/ex7/ex7-75.png', 'unlimited: Legal', '', 'Sentret', '161', 'TPCI', 'Common', '', '11/01/2004', '', 'Colorless', '', 'EX', '75', 'Basic', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('ex7-76', '[{\'name\': \'Dense\', \'text\': \"Any damage done to Slowpoke by attacks from your opponent\'s Evolved Pokémon is reduced by 10 (after applying Weakness and Resistance).\", \'type\': \'Poké-Body\'}]', '', 'Atsuko Nishida', '[{\'name\': \'Bite\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'\'}]', 'Team Rocket Returns', '1', '', 'Slowbro, Slowking', '', 'Third', '50', 'https://images.pokemoncard.io/images/ex7/ex7-76.png', 'unlimited: Legal', '', 'Slowpoke', '79', 'TPCI', 'Common', '', '11/01/2004', '', 'Colorless', '', 'EX', '76', 'Basic', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2'),
('ex7-77', '', '', 'Kouki Saitou', '[{\'name\': \'Singe\', \'cost\': [\'Fire\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Burned.\'}, {\'name\': \'Heat Tackle\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'Slugma does 10 damage to itself.\'}]', 'Team Rocket Returns', '2', '', 'Magcargo', '', 'Third', '50', 'https://images.pokemoncard.io/images/ex7/ex7-77.png', 'unlimited: Legal', '', 'Slugma', '218', 'TPCI', 'Common', '', '11/01/2004', '', 'Colorless, Colorless', '', 'EX', '77', 'Basic', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('ex7-78', '', '', 'Yuka Morii', '[{\'name\': \'Collect\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Draw a card.\'}, {\'name\': \'Rising Lunge\', \'cost\': [\'Grass\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20+\', \'text\': \'Flip a coin. If heads, this attack does 20 damage plus 10 more damage.\'}]', 'Team Rocket Returns', '1', '', 'Ariados', '', 'Third', '50', 'https://images.pokemoncard.io/images/ex7/ex7-78.png', 'unlimited: Legal', '', 'Spinarak', '167', 'TPCI', 'Common', '', '11/01/2004', '', 'Colorless', '', 'EX', '78', 'Basic', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('ex7-79', '', '', 'Tomokazu Komiya', '[{\'name\': \'Tackle\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'\'}, {\'name\': \'Rest\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'\', \'text\': \'Remove all Special Conditions and all damage counters from Swinub. Swinub is now Asleep.\'}]', 'Team Rocket Returns', '1', '', 'Piloswine', '', 'Third', '50', 'https://images.pokemoncard.io/images/ex7/ex7-79.png', 'unlimited: Legal', '', 'Swinub', '220', 'TPCI', 'Common', '', '11/01/2004', '', 'Colorless', '', 'EX', '79', 'Basic', 'Pokémon', 'Fighting', 'type: Grass, value: ×2'),
('ex7-8', '', '', 'Mitsuhiro Arita', '[{\'name\': \'Black Suction Cups\', \'cost\': [\'Water\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Does 10 damage to each Defending Pokémon. Flip a coin. If heads, each Defending Pokémon is now Paralyzed.\'}, {\'name\': \'Ink Blast\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30+\', \'text\': \"Does 30 damage plus 10 more damage for each Energy attached to Dark Octillery but not used to pay for this attack\'s Energy cost. You can\'t add more than 20 damage in this way.\"}]', 'Team Rocket Returns', '1', 'Remoraid', '', '', 'Third', '70', 'https://images.pokemoncard.io/images/ex7/ex7-8.png', 'unlimited: Legal', '', 'Dark Octillery', '224', 'TPCI', 'Rare Holo', '', '11/01/2004', '', 'Colorless', '[\'This Pokémon is both Water Darkness type.\']', 'EX', '8', 'Stage 1', 'Pokémon', 'Water, Darkness', 'type: Lightning, value: ×2'),
('ex7-80', '', '', 'Sachiko Adachi', '[{\'name\': \'Psycho Waves\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Discard an Energy card attached to Voltorb. The Defending Pokémon is now Confused.\'}, {\'name\': \'Thunder Wave\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Paralyzed.\'}]', 'Team Rocket Returns', '1', '', 'Electrode', '', 'Third', '40', 'https://images.pokemoncard.io/images/ex7/ex7-80.png', 'unlimited: Legal', '', 'Voltorb', '100', 'TPCI', 'Common', '', '11/01/2004', '', 'Colorless', '', 'EX', '80', 'Basic', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
('ex7-81', '[{\'name\': \'Saturation\', \'text\': \'When you attach a Water Energy card from your hand to Wooper, remove all Special Conditions and 1 damage counter from Wooper.\', \'type\': \'Poké-Body\'}]', '', 'Kouki Saitou', '[{\'name\': \'Wave Splash\', \'cost\': [\'Water\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'\'}]', 'Team Rocket Returns', '1', '', 'Quagsire', '', 'Third', '50', 'https://images.pokemoncard.io/images/ex7/ex7-81.png', 'unlimited: Legal', '', 'Wooper', '194', 'TPCI', 'Common', '', '11/01/2004', '', 'Colorless', '', 'EX', '81', 'Basic', 'Pokémon', 'Water', 'type: Grass, value: ×2'),
('ex7-82', '', '', 'Miki Tanaka', '[{\'name\': \'Dark Streak\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Flip a coin. If heads, each Defending Pokémon is now Paralyzed.\'}, {\'name\': \'Ambush\', \'cost\': [\'Grass\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20+\', \'text\': \'Flip a coin. If heads, this attack does 20 damage plus 10 more damage.\'}]', 'Team Rocket Returns', '1', '', 'Golbat', '', 'Third', '50', 'https://images.pokemoncard.io/images/ex7/ex7-82.png', 'unlimited: Legal', '', 'Zubat', '41', 'TPCI', 'Common', '', '11/01/2004', '', 'Colorless', '', 'EX', '82', 'Basic', 'Pokémon', 'Grass', 'type: Psychic, value: ×2'),
('ex7-83', '', '', 'Ken Sugimori', '', 'Team Rocket Returns', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex7/ex7-83.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Copycat', '', 'TPCI', 'Uncommon', '', '11/01/2004', '', '', '[\'You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.\', \"Shuffle your hand into your deck. Then, count the number of cards in your opponent\'s hand and draw that many cards.\"]', 'EX', '83', 'Supporter', 'Trainer', '', '');
INSERT INTO `cards` (`id`, `abilities`, `ancient_trait`, `artist`, `attacks`, `card_set`, `converted`, `evolves_from`, `evolves_to`, `flavor_text`, `generation`, `hp`, `img`, `legalities`, `level`, `name`, `national_pokedex_numbers`, `publisher`, `rarity`, `regulation_mark`, `release_date`, `resistances`, `retreat_cost`, `rules`, `series`, `set_num`, `subtypes`, `supertype`, `types`, `weakness`) VALUES
('ex7-84', '', '', 'Katsura Tabata', '', 'Team Rocket Returns', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex7/ex7-84.png', 'unlimited: Legal', '', 'Pokémon Retriever', '', 'TPCI', 'Uncommon', '', '11/01/2004', '', '', '[\'Search your discard pile for Basic Pokémon and Evolution cards. You may either show 1 Basic Pokémon or Evolution card to your opponent and put it into your hand, or show a combination of 3 Basic Pokémon or Evolution cards to your opponent and shuffle them into your deck.\']', 'EX', '84', 'Rockets Secret Machine', 'Trainer', '', ''),
('ex7-85', '', '', 'Katsura Tabata', '', 'Team Rocket Returns', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex7/ex7-85.png', 'unlimited: Legal', '', 'Pow! Hand Extension', '', 'TPCI', 'Uncommon', '', '11/01/2004', '', '', '[\'You may use this card only if you have more Prize cards left than your opponent.\', \"Move 1 Energy card attached to the Defending Pokémon to another of your opponent\'s Pokémon. Or, switch 1 of your opponent\'s Benched Pokémon with 1 of the Defending Pokémon. Your opponent chooses the Defending Pokémon to switch.\"]', 'EX', '85', 'Rockets Secret Machine', 'Trainer', '', ''),
('ex7-86', '', '', 'Ken Sugimori', '', 'Team Rocket Returns', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex7/ex7-86.png', 'unlimited: Legal', '', 'Rockets Admin.', '', 'TPCI', 'Uncommon', '', '11/01/2004', '', '', '[\'You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.\', \'Each player shuffles his or her hand into his or her deck. Then, each player counts his or her Prize cards left and draws up to that many cards. (You draw your cards first.)\']', 'EX', '86', 'Supporter', 'Trainer', '', ''),
('ex7-87', '', '', 'Ryo Ueda', '', 'Team Rocket Returns', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex7/ex7-87.png', 'unlimited: Legal', '', 'Rockets Hideout', '', 'TPCI', 'Uncommon', '', '11/01/2004', '', '', '[\'This card stays in play when you play it. Discard this card if another Stadium card comes into play.\', \"Each Pokémon with Dark or Rocket\'s in its name (both yours and your opponent\'s) gets +20 HP.\"]', 'EX', '87', 'Stadium', 'Trainer', '', ''),
('ex7-88', '', '', 'Ken Sugimori', '', 'Team Rocket Returns', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex7/ex7-88.png', 'unlimited: Legal', '', 'Rockets Mission', '', 'TPCI', 'Uncommon', '', '11/01/2004', '', '', '[\'You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.\', \"Discard a card from your hand. Then, draw 3 cards. If you discarded a Pokémon that has Dark or Rocket\'s in its name, draw 4 cards instead.\"]', 'EX', '88', 'Supporter', 'Trainer', '', ''),
('ex7-89', '', '', 'Ryo Ueda', '', 'Team Rocket Returns', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex7/ex7-89.png', 'unlimited: Legal', '', 'Rockets Poké Ball', '', 'TPCI', 'Uncommon', '', '11/01/2004', '', '', '[\'Search your deck for a Pokémon with Dark in its name, show it to your opponent, and put it into your hand. Shuffle your deck afterward.\']', 'EX', '89', 'Item', 'Trainer', '', ''),
('ex7-9', '[{\'name\': \'Cunning\', \'text\': \"Once during your turn (before your attack), you may look at the top card of your opponent\'s deck. Then, you may shuffle his or her deck. This power can\'t be used if Dark Slowking is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Kouki Saitou', '[{\'name\': \'Litter\', \'cost\': [\'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20+\', \'text\': \"You may discard a combination of up to 2 Pokémon Tool cards and Rocket\'s Secret Machine cards from your hand. If you do, this attack does 20 damage plus 30 more damage for each card you discarded.\"}]', 'Team Rocket Returns', '1', 'Slowpoke', '', '', 'Third', '80', 'https://images.pokemoncard.io/images/ex7/ex7-9.png', 'unlimited: Legal', '', 'Dark Slowking', '199', 'TPCI', 'Rare Holo', '', '11/01/2004', '', 'Colorless', '[\'This Pokémon is both Psychic Darkness type.\']', 'EX', '9', 'Stage 1', 'Pokémon', 'Psychic, Darkness', 'type: Grass, value: ×2'),
('ex7-90', '', '', 'Ryo Ueda', '[{\'name\': \'Feint Attack\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Does 20 damage to 1 of your opponent\'s Pokémon. This attack\'s damage isn\'t affected by Weakness, Resistance, Poké-Powers, Poké-Bodies, or any other effects on that Pokémon.\"}]', 'Team Rocket Returns', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex7/ex7-90.png', 'unlimited: Legal', '', 'Rockets Tricky Gym', '', 'TPCI', 'Uncommon', '', '11/01/2004', '', '', '[\'This card stays in play when you play it. Discard this card if another Stadium card comes into play.\', \"Each Pokémon with Dark or Rocket\'s in its name (both yours and your opponent\'s) can use attacks on this card instead of its own.\"]', 'EX', '90', 'Stadium', 'Trainer', '', ''),
('ex7-91', '', '', 'Katsura Tabata', '', 'Team Rocket Returns', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex7/ex7-91.png', 'unlimited: Legal', '', 'Surprise! Time Machine', '', 'TPCI', 'Uncommon', '', '11/01/2004', '', '', '[\'Choose 1 of your Evolved Pokémon, remove the highest Stage Evolution card from it, and shuffle it into your deck (this counts as devolving that Pokémon). If that Pokémon remains in play, search your deck for an Evolution card that evolves from that Pokémon and put it onto that Pokémon (this counts as evolving that Pokémon). Shuffle your deck afterward.\']', 'EX', '91', 'Rockets Secret Machine', 'Trainer', '', ''),
('ex7-92', '', '', 'Katsura Tabata', '', 'Team Rocket Returns', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex7/ex7-92.png', 'unlimited: Legal', '', 'Swoop! Teleporter', '', 'TPCI', 'Uncommon', '', '11/01/2004', '', '', '[\'Search your deck for a Basic Pokémon (excluding Pokémon-ex) and switch it with 1 of your Basic Pokémon (excluding Pokémon-ex) in play. (Any cards attached to that Pokémon, damage counters, Special Conditions, and effects on it are now on the new Pokémon.) Place the first Basic Pokémon in the discard pile. Shuffle your deck afterward.\']', 'EX', '92', 'Rockets Secret Machine', 'Trainer', '', ''),
('ex7-93', '', '', 'Katsura Tabata', '', 'Team Rocket Returns', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex7/ex7-93.png', 'unlimited: Legal', '', 'Venture Bomb', '', 'TPCI', 'Uncommon', '', '11/01/2004', '', '', '[\"Flip a coin. If heads, put 1 damage counter on 1 of your opponent\'s Pokémon. If tails, put 1 damage counter on 1 of your Pokémon.\"]', 'EX', '93', 'Rockets Secret Machine', 'Trainer', '', ''),
('ex7-94', '', '', 'Takumi Akabane', '', 'Team Rocket Returns', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex7/ex7-94.png', 'unlimited: Legal', '', 'Dark Metal Energy', '', 'TPCI', 'Uncommon', '', '11/01/2004', '', '', '[\"Attach Dark Metal Energy to 1 of your Pokémon. While in play, Dark Metal Energy provides Darkness Energy and Metal Energy, but provides only 1 Energy at a time. (Doesn\'t count as a basic Energy card when not in play and has no effect other than providing Energy.)\"]', 'EX', '94', 'Special', 'Energy', '', ''),
('ex7-95', '', '', 'Takumi Akabane', '', 'Team Rocket Returns', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex7/ex7-95.png', 'unlimited: Legal', '', 'R Energy', '', 'TPCI', 'Uncommon', '', '11/01/2004', '', '', '[\"R Energy can be attached only to a Pokémon that has Dark or Rocket\'s in its name. While in play, R Energy provides 2 Darkness Energy. (Doesn\'t count as a basic Energy card.) If the Pokémon R Energy is attached to attacks, the attack does 10 more damage to the Active Pokémon (before applying Weakness and Resistance). When your turn ends, discard R Energy.\"]', 'EX', '95', 'Special', 'Energy', '', ''),
('ex7-96', '[{\'name\': \'Darkness Veil\', \'text\': \"As long as Rocket\'s Articuno ex has any Darkness Energy attached to it, prevent all effects, except damage, by an opponent\'s attack done to Rocket\'s Articuno ex.\", \'type\': \'Poké-Body\'}]', '', 'Ryo Ueda', '[{\'name\': \'Freeze Solid\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \"Search your discard pile for a Water Energy card and attach it to Rocket\'s Articuno ex.\"}, {\'name\': \'Ice Wing\', \'cost\': [\'Water\', \'Water\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50\', \'text\': \'\'}]', 'Team Rocket Returns', '1', '', '', '', 'Third', '100', 'https://images.pokemoncard.io/images/ex7/ex7-96.png', 'unlimited: Legal', '', 'Rockets Articuno ex', '144', 'TPCI', 'Rare Holo EX', '', '11/01/2004', '', 'Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '96', 'Basic, EX', 'Pokémon', 'Darkness', 'type: Metal, value: ×2'),
('ex7-97', '[{\'name\': \'Dark Condition\', \'text\': \"As long as Rocket\'s Entei ex has any Darkness Energy attached to it, Rocket\'s Entei ex has no Weakness.\", \'type\': \'Poké-Body\'}]', '', 'Ryo Ueda', '[{\'name\': \'Energy Link\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \"Search your discard pile for an Energy card and attach it to Rocket\'s Entei ex.\"}, {\'name\': \'Volcanic Ash\', \'cost\': [\'Fire\', \'Fire\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'\', \'text\': \"Discard 2 Energy attached to Rocket\'s Entei ex and then choose 1 of your opponent\'s Pokémon. This attack does 60 damage to that Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'Team Rocket Returns', '1', '', '', '', 'Third', '100', 'https://images.pokemoncard.io/images/ex7/ex7-97.png', 'unlimited: Legal', '', 'Rockets Entei ex', '244', 'TPCI', 'Rare Holo EX', '', '11/01/2004', '', 'Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '97', 'Basic, EX', 'Pokémon', 'Darkness', 'type: Water, value: ×2'),
('ex7-98', '[{\'name\': \'Strikes Back\', \'text\': \"If Rocket\'s Hitmonchan ex is your Active Pokémon and is damaged by an opponent\'s attack (even if Rocket\'s Hitmonchan ex is Knocked Out), put 2 damage counters on the Attacking Pokémon.\", \'type\': \'Poké-Body\'}]', '', 'Mitsuhiro Arita', '[{\'name\': \'Mach Punch\', \'cost\': [\'Fighting\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \"Does 10 damage to 1 of your opponent\'s Benched Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}, {\'name\': \'Magnum Punch\', \'cost\': [\'Fighting\', \'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60\', \'text\': \'\'}]', 'Team Rocket Returns', '1', '', '', '', 'Third', '100', 'https://images.pokemoncard.io/images/ex7/ex7-98.png', 'unlimited: Legal', '', 'Rockets Hitmonchan ex', '107', 'TPCI', 'Rare Holo EX', '', '11/01/2004', '', 'Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '98', 'Basic, EX', 'Pokémon', 'Darkness', 'type: Psychic, value: ×2'),
('ex7-99', '', '', 'Mitsuhiro Arita', '[{\'name\': \'Darkness Switch\', \'cost\': [\'Psychic\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Discard an Energy card attached to Rocket\'s Mewtwo ex, and then switch all damage counters on Rocket\'s Mewtwo ex with those on the Defending Pokémon. (If an effect of this attack is prevented, this attack does nothing.)\"}, {\'name\': \'Hypnoblast\', \'cost\': [\'Psychic\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Asleep.\'}, {\'name\': \'Psyburn\', \'cost\': [\'Psychic\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'70\', \'text\': \'\'}]', 'Team Rocket Returns', '2', '', '', '', 'Third', '100', 'https://images.pokemoncard.io/images/ex7/ex7-99.png', 'unlimited: Legal', '', 'Rockets Mewtwo ex', '150', 'TPCI', 'Rare Holo EX', '', '11/01/2004', '', 'Colorless, Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '99', 'Basic, EX', 'Pokémon', 'Darkness', 'type: Psychic, value: ×2'),
('ex8-1', '[{\'name\': \'Safeguard\', \'text\': \"Prevent all effects of attacks, including damage, done to Altaria by your opponent\'s Pokémon-ex.\", \'type\': \'Poké-Body\'}]', '', 'Kyoko Umemoto', '[{\'name\': \'Double Wing Attack\', \'cost\': [\'Lightning\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Does 20 Damage to each Defending Pokémon.\'}, {\'name\': \'Dive\', \'cost\': [\'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50\', \'text\': \'\'}]', 'Deoxys', '1', 'Swablu', '', '', 'Third', '70', 'https://images.pokemoncard.io/images/ex8/ex8-1.png', 'unlimited: Legal', '', 'Altaria', '334', 'TPCI', 'Rare Holo', '', '02/01/2005', 'type: Fighting, value: -30', 'Colorless', '', 'EX', '1', 'Stage 1', 'Pokémon', 'Colorless', 'type: Lightning, value: ×2'),
('ex8-10', '[{\'name\': \'Swing Dance\', \'text\': \"Once during your turn (before your attack), you may draw a card. This power can\'t be used if Ludicolo is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Atsuko Nishida', '[{\'name\': \'Healing Steps\', \'cost\': [\'Water\'], \'convertedEnergyCost\': 1, \'damage\': \'30\', \'text\': \'You may discard as many cards as you like from your hand. If you do, remove that many damage counters from Ludicolo.\'}, {\'name\': \'Circular Steps\', \'cost\': [\'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'10×\', \'text\': \"Does 10 damage times the number of Pokémon in play (both yours and your opponent\'s), excluding Ludicolo.\"}]', 'Deoxys', '2', 'Lombre', '', '', 'Third', '100', 'https://images.pokemoncard.io/images/ex8/ex8-10.png', 'unlimited: Legal', '', 'Ludicolo', '272', 'TPCI', 'Rare Holo', '', '02/01/2005', '', 'Colorless, Colorless', '', 'EX', '10', 'Stage 2', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('ex8-100', '[{\'name\': \'Commanding Aura\', \'text\': \"As long as Hariyama ex is your Active Pokémon, your opponent can\'t play any Stadium cards from his or her hand.\", \'type\': \'Poké-Body\'}]', '', 'Ryo Ueda', '[{\'name\': \'Knock Off\', \'cost\': [\'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'40\', \'text\': \"Choose 1 card from your opponent\'s hand without looking and discard it.\"}, {\'name\': \'Pivot Throw\', \'cost\': [\'Fighting\', \'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'80\', \'text\': \"During your opponent\'s next turn, any damage done to Hariyama ex by attacks is increased by 10 (before applying Weakness and Resistance).\"}]', 'Deoxys', '2', 'Makuhita', '', '', 'Third', '110', 'https://images.pokemoncard.io/images/ex8/ex8-100.png', 'unlimited: Legal', '', 'Hariyama ex', '297', 'TPCI', 'Rare Holo EX', '', '02/01/2005', '', 'Colorless, Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '100', 'Stage 1, EX', 'Pokémon', 'Fighting', 'type: Psychic, value: ×2'),
('ex8-101', '', '', 'Hikaru Koike', '[{\'name\': \'Disconnect\', \'cost\': [\'Lightning\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'40\', \'text\': \"Your opponent can\'t play any Trainer cards (except for Supporter cards) from his or her hand during your opponent\'s next turn.\"}, {\'name\': \'Mega Shot\', \'cost\': [\'Lightning\', \'Lightning\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'\', \'text\': \"Discard all Lightning Energy attached to Manectric ex and then choose 1 of your opponent\'s Pokémon. This attack does 80 damage to that Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'Deoxys', '1', 'Electrike', '', '', 'Third', '100', 'https://images.pokemoncard.io/images/ex8/ex8-101.png', 'unlimited: Legal', '', 'Manectric ex', '310', 'TPCI', 'Rare Holo EX', '', '02/01/2005', 'type: Metal, value: -30', 'Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '101', 'Stage 1, EX', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
('ex8-102', '[{\'name\': \'Dragon Boost\', \'text\': \'Once during your turn, when you put Rayquaza ex from your hand onto your Bench, you may move any number of basic Energy cards attached to your Pokémon to Rayquaza ex.\', \'type\': \'Poké-Power\'}]', '', 'Shin-ichi Yoshikawa', '[{\'name\': \'Spiral Blast\', \'cost\': [\'Fire\', \'Lightning\'], \'convertedEnergyCost\': 2, \'damage\': \'20×\', \'text\': \'Does 20 damage for each basic Energy card attached to Rayquaza ex.\'}]', 'Deoxys', '2', '', '', '', 'Third', '100', 'https://images.pokemoncard.io/images/ex8/ex8-102.png', 'unlimited: Legal', '', 'Rayquaza ex', '384', 'TPCI', 'Rare Holo EX', '', '02/01/2005', 'type: Water, value: -30, type: Fighting, value: -30', 'Colorless, Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '102', 'Basic, EX', 'Pokémon', 'Colorless', 'type: Colorless, value: ×2'),
