('ex8-108', '[{\'name\': \'Lightning Burst\', \'text\': \"Whenever you attach a Darkness Energy card from your hand to Rocket\'s Raikou ex, you may choose 1 of the Defending Pokémon and switch it with 1 of your opponent\'s Benched Pokémon. Your opponent chooses the Benched Pokémon to switch. This power can\'t be used if Rocket\'s Raikou ex is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Ryo Ueda', '[{\'name\': \'Thunderous Blow\', \'cost\': [\'Lightning\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40+\', \'text\': \"Does 40 damage plus 10 more damage for each Lightning Energy attached to Rocket\'s Raikou ex.\"}]', 'Deoxys', '2', '', '', '', 'Third', '100', 'https://images.pokemoncard.io/images/ex8/ex8-108.png', 'unlimited: Legal', '', 'Rockets Raikou ex', '243', 'TPCI', 'Rare Secret', '', '02/01/2005', '', 'Colorless, Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '108', 'Basic, EX', 'Pokémon', 'Darkness', 'type: Fighting, value: ×2'),
('ex8-11', '[{\'name\': \'Super Connectivity\', \'text\': \"Once during your turn (before your attack), you may search your discard pile for a Psychic or Metal Energy card and attach it to your Active Pokémon. Then, put 1 damage counter on that Pokémon. This power can\'t be used if Metagross is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Hisao Nakamura', '[{\'name\': \'Link Blast\', \'cost\': [\'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'70\', \'text\': \"If Metagross and the Defending Pokémon have a different amount of Energy attached to them, this attack\'s base damage is 40 instead of 70.\"}]', 'Deoxys', '2', 'Metang', '', '', 'Third', '100', 'https://images.pokemoncard.io/images/ex8/ex8-11.png', 'unlimited: Legal', '', 'Metagross', '376', 'TPCI', 'Rare Holo', '', '02/01/2005', '', 'Colorless, Colorless', '', 'EX', '11', 'Stage 2', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2'),
