('ex8-2', '[{\'name\': \'Hunch\', \'text\': \"As long as Beautifly\'s remaining HP is 40 or less, Beautifly does 40 more damage to the Defending Pokémon (before applying Weakness and Resistance).\", \'type\': \'Poké-Body\'}]', '', 'Kagemaru Himeno', '[{\'name\': \'Luring Antenna\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'20\', \'text\': \"Before doing damage, you may choose 1 of your opponent\'s Benched Pokémon and switch it with 1 of the Defending Pokémon. If you do, this attack does 20 damage to the new Defending Pokémon. Your opponent chooses the Defending Pokémon to switch.\"}, {\'name\': \'Cutting Wind\', \'cost\': [\'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50\', \'text\': \'\'}]', 'Deoxys', '1', 'Silcoon', '', '', 'Third', '100', 'https://images.pokemoncard.io/images/ex8/ex8-2.png', 'unlimited: Legal', '', 'Beautifly', '267', 'TPCI', 'Rare Holo', '', '02/01/2005', '', 'Colorless', '', 'EX', '2', 'Stage 2', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('ex8-20', '[{\'name\': \'Smooth Over\', \'text\': \"Once during your turn (before your attack), you may search your deck for a card. Shuffle your deck, then put that card on top of your deck. This power can\'t be used if Magcargo is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Midori Harada', '[{\'name\': \'Knock Over\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'You may discard any Stadium card in play.\'}, {\'name\': \'Combustion\', \'cost\': [\'Fire\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50\', \'text\': \'\'}]', 'Deoxys', '3', 'Slugma', '', '', 'Third', '80', 'https://images.pokemoncard.io/images/ex8/ex8-20.png', 'unlimited: Legal', '', 'Magcargo', '219', 'TPCI', 'Rare', '', '02/01/2005', '', 'Colorless, Colorless, Colorless', '', 'EX', '20', 'Stage 1', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('ex8-21', '', '', 'Tomokazu Komiya', '[{\'name\': \'Bay Dance\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'During your next turn, if any of your current Active Pokémon does damage to any Defending Pokémon, the attack does 30 more damage (before applying Weakness and Resistance).\'}, {\'name\': \'Aqua Sonic\', \'cost\': [\'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50\', \'text\': \"This attack\'s damage is not affected by Resistance.\"}]', 'Deoxys', '1', 'Wingull', '', '', 'Third', '70', 'https://images.pokemoncard.io/images/ex8/ex8-21.png', 'unlimited: Legal', '', 'Pelipper', '279', 'TPCI', 'Rare', '', '02/01/2005', 'type: Fighting, value: -30', 'Colorless', '', 'EX', '21', 'Stage 1', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('ex8-22', '[{\'name\': \'Dragon Aura\', \'text\': \"As long as Rayquaza has any basic Fire Energy cards and any basic Lightning Energy cards attached to it, prevent all effects, except damage, by an opponent\'s attack done to Rayquaza.\", \'type\': \'Poké-Body\'}]', '', 'Hiromichi Sugiyama', '[{\'name\': \'Tumbling Attack\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20+\', \'text\': \'Flip a coin. If heads, this attack does 20 damage plus 20 more damage.\'}]', 'Deoxys', '1', '', '', '', 'Third', '80', 'https://images.pokemoncard.io/images/ex8/ex8-22.png', 'unlimited: Legal', '', 'Rayquaza', '384', 'TPCI', 'Rare', '', '02/01/2005', '', 'Colorless', '', 'EX', '22', 'Basic', 'Pokémon', 'Colorless', 'type: Colorless, value: ×2'),
('ex8-23', '[{\'name\': \'Night Vision\', \'text\': \"Once during your turn (before your attack), if Sableye is your Active Pokémon, you may look at your opponent\'s hand. This power can\'t be used if Sableye is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Aya Kusube', '[{\'name\': \'Slash\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'\'}, {\'name\': \'Limitation\', \'cost\': [\'Darkness\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Your opponent can\'t play any Supporter Cards from his or her hand during your opponent\'s next turn.\"}]', 'Deoxys', '1', '', '', '', 'Third', '60', 'https://images.pokemoncard.io/images/ex8/ex8-23.png', 'unlimited: Legal', '', 'Sableye', '302', 'TPCI', 'Rare', '', '02/01/2005', 'type: Colorless, value: -30', 'Colorless', '', 'EX', '23', 'Basic', 'Pokémon', 'Darkness', ''),
('ex8-24', '', '', 'Atsuko Nishida', '[{\'name\': \'Triple Breach\', \'cost\': [\'Water\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Choose 3 of your opponent\'s Pokémon. This attack does 10 damage to each of those Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}, {\'name\': \'Rend\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30+\', \'text\': \'If the Defending Pokémon already has any damage counters on it, this attack does 30 damage plus 20 more damage.\'}]', 'Deoxys', '', 'Goldeen', '', '', 'Third', '70', 'https://images.pokemoncard.io/images/ex8/ex8-24.png', 'unlimited: Legal', '', 'Seaking', '119', 'TPCI', 'Rare', '', '02/01/2005', '', '', '', 'EX', '24', 'Stage 1', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('ex8-25', '[{\'name\': \'Fan Action\', \'text\': \"Once during your turn (before your attack), you may switch 1 of the Defending Pokémon with 1 of your opponent\'s Benched Pokémon. Your opponent chooses the Benched Pokémon to switch. This power can\'t be used if Shiftry is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Kouki Saitou', '[{\'name\': \'Stadium Power\', \'cost\': [\'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50+\', \'text\': \'If there is any Stadium card in play, this attack does 50 damage plus 20 more damage.\'}]', 'Deoxys', '1', 'Nuzleaf', '', '', 'Third', '110', 'https://images.pokemoncard.io/images/ex8/ex8-25.png', 'unlimited: Legal', '', 'Shiftry', '275', 'TPCI', 'Rare', '', '02/01/2005', '', 'Colorless', '', 'EX', '25', 'Stage 2', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('ex8-26', '[{\'name\': \'Metallic Lift\', \'text\': \'If Skarmory has any Metal Energy attached to it, the Retreat Cost for Skarmory is 0.\', \'type\': \'Poké-Body\'}]', '', 'Kouki Saitou', '[{\'name\': \'Spearhead\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Draw a card.\'}, {\'name\': \'Heavy Metal\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'10+\', \'text\': \'Flip a coin for each Metal Energy attached to Skarmory. This attack does 10 damage plus 20 more damage for each heads.\'}]', 'Deoxys', '1', '', '', '', 'Third', '70', 'https://images.pokemoncard.io/images/ex8/ex8-26.png', 'unlimited: Legal', '', 'Skarmory', '227', 'TPCI', 'Rare', '', '02/01/2005', 'type: Fighting, value: -30', 'Colorless', '', 'EX', '26', 'Basic', 'Pokémon', 'Metal', 'type: Lightning, value: ×2'),
('ex8-27', '[{\'name\': \'Tropical Motion\', \'text\': \"As long as Tropius is your Active Pokémon, your opponent\'s Active Pokémon have no Resistance.\", \'type\': \'Poké-Body\'}]', '', 'Miki Tanaka', '[{\'name\': \'Miracle Blow\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Flip a coin. If heads, choose 1 Special Condition. The Defending Pokémon is now affected by that Special Condition.\'}, {\'name\': \'Stomp\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'40+\', \'text\': \'Flip a coin. If heads, this attack does 40 damage plus 20 more damage.\'}]', 'Deoxys', '1', '', '', '', 'Third', '80', 'https://images.pokemoncard.io/images/ex8/ex8-27.png', 'unlimited: Legal', '', 'Tropius', '357', 'TPCI', 'Rare', '', '02/01/2005', '', 'Colorless', '', 'EX', '27', 'Basic', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('ex8-28', '', '', 'Miki Tanaka', '[{\'name\': \'Raging Tremble\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Flip a coin. If heads, this attack does 10 damage for each damage counter on Whiscash to each Defending Pokémon. If tails, this attack does 10 damage for each damage counter on Whiscash to the Defending Pokémon.\'}, {\'name\': \'Dwindling Wave\', \'cost\': [\'Fighting\', \'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'70-\', \'text\': \'Does 70 damage minus 10 damage for each damage counter on Whiscash.\'}]', 'Deoxys', '2', 'Barboach', '', '', 'Third', '90', 'https://images.pokemoncard.io/images/ex8/ex8-28.png', 'unlimited: Legal', '', 'Whiscash', '340', 'TPCI', 'Rare', '', '02/01/2005', '', 'Colorless, Colorless', '', 'EX', '28', 'Stage 1', 'Pokémon', 'Fighting', 'type: Grass, value: ×2'),
('ex8-29', '[{\'name\': \'Mirror Coat\', \'text\': \"If Xatu is Burned or Poisoned by an opponent\'s attack (even if Xatu is Knocked Out), the Attacking Pokémon is now affected by the same Special Conditions (1 if there is only 1).\", \'type\': \'Poké-Body\'}]', '', 'Yuka Morii', '[{\'name\': \'Dazzle Dance\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Each Defending Pokémon is now Confused.\'}, {\'name\': \'Psyloop\', \'cost\': [\'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30+\', \'text\': \'Does 30 damage plus 30 more damage for each Trainer card your opponent has in play.\'}]', 'Deoxys', '', 'Natu', '', '', 'Third', '70', 'https://images.pokemoncard.io/images/ex8/ex8-29.png', 'unlimited: Legal', '', 'Xatu', '178', 'TPCI', 'Rare', '', '02/01/2005', 'type: Fighting, value: -30', '', '', 'EX', '29', 'Stage 1', 'Pokémon', 'Psychic', 'type: Lightning, value: ×2'),
('ex8-3', '', '', 'Hajime Kusajima', '[{\'name\': \'Leaf Poison\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'20\', \'text\': \'If Breloom has any Grass Energy attached to it, the Defending Pokémon is now Poisoned.\'}, {\'name\': \'Hustle Punch\', \'cost\': [\'Fighting\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'70-\', \'text\': \"During your next turn, Hustle Punch attack\'s base damage is 50 instead of 70.\"}]', 'Deoxys', '1', 'Shroomish', '', '', 'Third', '80', 'https://images.pokemoncard.io/images/ex8/ex8-3.png', 'unlimited: Legal', '', 'Breloom', '286', 'TPCI', 'Rare Holo', '', '02/01/2005', '', 'Colorless', '', 'EX', '3', 'Stage 1', 'Pokémon', 'Fighting', 'type: Psychic, value: ×2'),
('ex8-30', '', '', 'Yuka Morii', '[{\'name\': \'Spinning Horn\', \'cost\': [\'Fighting\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Does 10 damage to each of your opponent\'s Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}, {\'name\': \'Rock Hurl\', \'cost\': [\'Fighting\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50\', \'text\': \"This attack\'s damage is not affected by Resistance.\"}]', 'Deoxys', '1', 'Phanpy', '', '', 'Third', '80', 'https://images.pokemoncard.io/images/ex8/ex8-30.png', 'unlimited: Legal', '', 'Donphan', '232', 'TPCI', 'Uncommon', '', '02/01/2005', '', 'Colorless', '', 'EX', '30', 'Stage 1', 'Pokémon', 'Fighting', 'type: Grass, value: ×2'),
