('ex8-77', '', '', 'Yukiko Baba', '[{\'name\': \'Rapid Spin\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'Your opponent switches the Defending Pokémon with 1 of his or her Benched Pokémon, if any. You switch Staryu with 1 of your Benched Pokémon, if any.\'}]', 'Deoxys', '1', '', 'Starmie', '', 'Third', '50', 'https://images.pokemoncard.io/images/ex8/ex8-77.png', 'unlimited: Legal', '', 'Staryu', '120', 'TPCI', 'Common', '', '02/01/2005', '', 'Colorless', '', 'EX', '77', 'Basic', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('ex8-78', '', '', 'Mitsuhiro Arita', '[{\'name\': \'Agility\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \"Flip a coin. If heads, prevent all effects of an attack, including damage, done to Surskit during your opponent\'s next turn.\"}]', 'Deoxys', '1', '', 'Masquerain', '', 'Third', '50', 'https://images.pokemoncard.io/images/ex8/ex8-78.png', 'unlimited: Legal', '', 'Surskit', '283', 'TPCI', 'Common', '', '02/01/2005', '', 'Colorless', '', 'EX', '78', 'Basic', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('ex8-79', '[{\'name\': \'Fluff\', \'text\': \"Whenever Swablu would be damaged or affected by an opponent\'s attack and already has at least 1 damage counter on it, flip a coin. If heads, prevent all effects of that attack, including damage, done to Swablu.\", \'type\': \'Poké-Body\'}]', '', 'Kyoko Umemoto', '[{\'name\': \'Peck\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'\'}]', 'Deoxys', '1', '', 'Altaria', '', 'Third', '40', 'https://images.pokemoncard.io/images/ex8/ex8-79.png', 'unlimited: Legal', '', 'Swablu', '333', 'TPCI', 'Common', '', '02/01/2005', 'type: Fighting, value: -30', 'Colorless', '', 'EX', '79', 'Basic', 'Pokémon', 'Colorless', 'type: Lightning, value: ×2'),
('ex8-8', '', '', 'Hisao Nakamura', '[{\'name\': \'Dragon Spark\', \'cost\': [\'Water\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"This attack does 10 damage to each of your opponent\'s Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}, {\'name\': \'Full Retaliation\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20×\', \'text\': \'Does 20 damage times the number of damage counters on all of your Magikarp.\'}, {\'name\': \'Pulverize\', \'cost\': [\'Water\', \'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'50+\', \'text\': \'If the Defending Pokémon already has at least 2 damage counters on it, this attack does 50 damage plus 50 more damage.\'}]', 'Deoxys', '2', 'Magikarp', '', '', 'Third', '90', 'https://images.pokemoncard.io/images/ex8/ex8-8.png', 'unlimited: Legal', '', 'Gyarados', '130', 'TPCI', 'Rare Holo', '', '02/01/2005', '', 'Colorless, Colorless', '', 'EX', '8', 'Stage 1', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('ex8-80', '', '', 'Midori Harada', '[{\'name\': \'Fly\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \"Flip a coin. If tails, this attack does nothing. If heads, prevent all effects of an attack, including damage, done to Taillow during your opponent\'s next turn.\"}]', 'Deoxys', '1', '', 'Swellow', '', 'Third', '40', 'https://images.pokemoncard.io/images/ex8/ex8-80.png', 'unlimited: Legal', '', 'Taillow', '276', 'TPCI', 'Common', '', '02/01/2005', 'type: Fighting, value: -30', 'Colorless', '', 'EX', '80', 'Basic', 'Pokémon', 'Colorless', 'type: Lightning, value: ×2'),
('ex8-81', '', '', 'Tomokazu Komiya', '[{\'name\': \'Quick Attack\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'10+\', \'text\': \'Flip a coin. If heads, this attack does 10 damage plus 10 more damage.\'}]', 'Deoxys', '1', '', 'Pelipper', '', 'Third', '50', 'https://images.pokemoncard.io/images/ex8/ex8-81.png', 'unlimited: Legal', '', 'Wingull', '278', 'TPCI', 'Common', '', '02/01/2005', 'type: Fighting, value: -30', 'Colorless', '', 'EX', '81', 'Basic', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('ex8-82', '', '', 'Kagemaru Himeno', '[{\'name\': \'Ascension\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Search your deck for a card that evolves from Wurmple and put it on Wurmple. (This counts as evolving Wurmple.) Shuffle your deck afterward.\'}, {\'name\': \'Miracle Essence\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Flip a coin. If heads, choose 1 Special Condition. Each Defending Pokémon is now affected by that Special Condition.\'}]', 'Deoxys', '1', '', 'Silcoon, Cascoon', '', 'Third', '50', 'https://images.pokemoncard.io/images/ex8/ex8-82.png', 'unlimited: Legal', '', 'Wurmple', '265', 'TPCI', 'Common', '', '02/01/2005', '', 'Colorless', '', 'EX', '82', 'Basic', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('ex8-83', '[{\'name\': \'Self-control\', \'text\': \"Zubat can\'t be Paralyzed.\", \'type\': \'Poké-Body\'}]', '', 'Sachiko Adachi', '[{\'name\': \'Bite\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'\'}]', 'Deoxys', '1', '', 'Golbat', '', 'Third', '50', 'https://images.pokemoncard.io/images/ex8/ex8-83.png', 'unlimited: Legal', '', 'Zubat', '41', 'TPCI', 'Common', '', '02/01/2005', '', 'Colorless', '', 'EX', '83', 'Basic', 'Pokémon', 'Grass', 'type: Psychic, value: ×2'),
('ex8-84', '', '', 'Keiji Kinebuchi', '', 'Deoxys', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex8/ex8-84.png', 'unlimited: Legal', '', 'Balloon Berry', '', 'TPCI', 'Uncommon', '', '02/01/2005', '', '', '[\"Attach Balloon Berry to 1 of your Pokémon that doesn\'t already have a Pokémon Tool attached to it. If that Pokémon is Knocked Out, discard this card.\", \"As long as Balloon Berry is attached to a Pokémon, that Pokémon\'s Retreat Cost is 0. When this Pokémon retreats, discard Balloon Berry.\"]', 'EX', '84', 'Pokémon Tool', 'Trainer', '', ''),
('ex8-85', '', '', 'Jungo Suzuki', '', 'Deoxys', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex8/ex8-85.png', 'unlimited: Legal', '', 'Crystal Shard', '', 'TPCI', 'Uncommon', '', '02/01/2005', '', '', '[\"Attach Crystal Shard to 1 of your Pokémon that doesn\'t already have a Pokémon Tool attached to it. If that Pokémon is Knocked Out, discard this card.\", \"As long as this card is attached to a Pokémon, that Pokémon\'s type is Colorless. If that Pokémon attacks, discard this card at the end of the turn.\"]', 'EX', '85', 'Pokémon Tool', 'Trainer', '', ''),
('ex8-86', '', '', 'Keiji Kinebuchi', '', 'Deoxys', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex8/ex8-86.png', 'unlimited: Legal', '', 'Energy Charge', '', 'TPCI', 'Uncommon', '', '02/01/2005', '', '', '[\'Flip a coin. If heads, search your discard pile for 2 Energy cards (1 if there is only 1), show them to your opponent, and shuffle them into your deck.\']', 'EX', '86', 'Item', 'Trainer', '', ''),
('ex8-87', '', '', 'Ken Sugimori', '', 'Deoxys', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex8/ex8-87.png', 'unlimited: Legal', '', 'Lady Outing', '', 'TPCI', 'Uncommon', '', '02/01/2005', '', '', '[\'You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.\', \'Search your deck for up to 3 different types of basic Energy cards, show them to your opponent, and put them into your hand. Shuffle your deck afterward.\']', 'EX', '87', 'Supporter', 'Trainer', '', ''),
('ex8-88', '', '', 'Keiji Kinebuchi', '', 'Deoxys', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex8/ex8-88.png', 'unlimited: Legal', '', 'Master Ball', '', 'TPCI', 'Uncommon', '', '02/01/2005', '', '', '[\'Look at the top 7 cards from your deck. Choose a Basic Pokémon or Evolution card from those cards, show it to your opponent, and put it into your hand. Put the other 6 cards back on top of your deck. Shuffle your deck afterward.\']', 'EX', '88', 'Item', 'Trainer', '', ''),
('ex8-89', '', '', 'Ryo Ueda', '', 'Deoxys', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex8/ex8-89.png', 'unlimited: Legal', '', 'Meteor Falls', '', 'TPCI', 'Uncommon', '', '02/01/2005', '', '', '[\'This card stays in play when you play it. Discard this card if another Stadium card comes into play.\', \"Each player\'s Active Evolved Pokémon (excluding Pokémon-ex) can use any attack from its Basic Pokémon or its Stage 1 Evolution card. (You still have to pay for that attack\'s Energy cost.)\"]', 'EX', '89', 'Stadium', 'Trainer', '', ''),
('ex8-9', '[{\'name\': \'Wishing Star\', \'text\': \"Once during your turn (before your attack), if Jirachi is your Active Pokémon, you may look at the top 5 cards of your deck, choose 1 of them, and put it into your hand. Shuffle your deck afterward. Jirachi and your other Active Pokémon, if any, are now Asleep. This power can\'t be used if Jirachi is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Sumiyoshi Kizuki', '[{\'name\': \'Metallic Blow\', \'cost\': [\'Metal\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20+\', \'text\': \'If the Defending Pokémon has any Poké-Bodies, this attack does 20 damage plus 30 more damage.\'}]', 'Deoxys', '1', '', '', '', 'Third', '60', 'https://images.pokemoncard.io/images/ex8/ex8-9.png', 'unlimited: Legal', '', 'Jirachi', '385', 'TPCI', 'Rare Holo', '', '02/01/2005', 'type: Grass, value: -30', 'Colorless', '', 'EX', '9', 'Basic', 'Pokémon', 'Metal', 'type: Fire, value: ×2'),
('ex8-90', '', '', 'Ken Sugimori', '', 'Deoxys', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex8/ex8-90.png', 'unlimited: Legal', '', 'Professor Cozmos Discovery', '', 'TPCI', 'Uncommon', '', '02/01/2005', '', '', '[\'You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.\', \'Flip a coin. If heads, draw the bottom 3 cards of your deck. If tails, draw the top 2 cards of your deck.\']', 'EX', '90', 'Supporter', 'Trainer', '', ''),
('ex8-91', '', '', 'Ryo Ueda', '', 'Deoxys', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex8/ex8-91.png', 'unlimited: Legal', '', 'Space Center', '', 'TPCI', 'Uncommon', '', '02/01/2005', '', '', '[\'This card stays in play when you play it. Discard this card if another Stadium card comes into play.\', \"Ignore Poké-Bodies for all Basic Pokémon in play (both yours and your opponent\'s) (excluding Pokémon-ex and Pokémon that has an owner in its name).\"]', 'EX', '91', 'Stadium', 'Trainer', '', ''),
('ex8-92', '', '', 'Keiji Kinebuchi', '', 'Deoxys', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex8/ex8-92.png', 'unlimited: Legal', '', 'Strength Charm', '', 'TPCI', 'Uncommon', '', '02/01/2005', '', '', '[\"Attach Strength Charm to 1 of your Pokémon that doesn\'t already have a Pokémon Tool attached to it. If that Pokémon is Knocked Out, discard this card.\", \'Whenever an attack from the Pokémon that Strength Charm is attached to does damage to the Active Pokémon, the attack does 10 more damage (before applying Weakness and Resistance). Discard Strength Charm at the end of the turn in which this Pokémon attacks.\']', 'EX', '92', 'Pokémon Tool', 'Trainer', '', ''),
('ex8-93', '', '', 'Shin-ichi Yoshikawa', '', 'Deoxys', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex8/ex8-93.png', 'unlimited: Legal', '', 'Boost Energy', '', 'TPCI', 'Uncommon', '', '02/01/2005', '', '', '[\"Boost Energy can be attached only to an Evolved Pokémon. Discard Boost Energy at the end of the turn it was attached. Boost Energy provides ColorlessColorlessColorless Energy. The Pokémon Boost Energy is attached to can\'t retreat. If the Pokémon Boost Energy is attached to isn\'t an Evolved Pokémon, discard Boost Energy.\"]', 'EX', '93', 'Special', 'Energy', '', ''),
('ex8-94', '', '', 'Takumi Akabane', '', 'Deoxys', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex8/ex8-94.png', 'unlimited: Legal', '', 'Heal Energy', '', 'TPCI', 'Uncommon', '', '02/01/2005', '', '', '[\'Heal Energy provides Colorless Energy. When you attach this card from your hand to 1 of your Pokémon, remove 1 damage counter and all Special Conditions from that Pokémon. If Heal Energy is attached to Pokémon-ex, Heal Energy has no effect other than providing Energy.\']', 'EX', '94', 'Special', 'Energy', '', ''),
('ex8-95', '', '', 'Takumi Akabane', '', 'Deoxys', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex8/ex8-95.png', 'unlimited: Legal', '', 'Scramble Energy', '', 'TPCI', 'Uncommon', '', '02/01/2005', '', '', '[\"Scramble Energy can be attached only to an Evolved Pokémon (excluding Pokémon-ex). Scramble Energy provides Colorless Energy. While in play, if you have more Prize cards left than your opponent, Scramble Energy provides every type of Energy but provides only 3 in any combination at a time. If the Pokémon Scramble Energy is attached to isn\'t an Evolved Pokémon (or evolves into Pokémon-ex), discard Scramble Energy.\"]', 'EX', '95', 'Special', 'Energy', '', ''),
('ex8-96', '[{\'name\': \'Distortion\', \'text\': \"Once during your turn (before your attack), if Crobat ex is your Active Pokémon, you may put 1 damage counter on 1 of your opponent\'s Pokémon. This power can\'t be used if Crobat ex is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Ryo Ueda', '[{\'name\': \'Cross Attack\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20×\', \'text\': \'Flip 4 coins. This attack does 20 damage times the number of heads. If you get 2 or more heads, the Defending Pokémon is now Confused.\'}, {\'name\': \'Pester\', \'cost\': [\'Grass\', \'Grass\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60+\', \'text\': \'If the Defending Pokémon is affected by a Special Condition, this attack does 60 damage plus 40 more damage.\'}]', 'Deoxys', '', 'Golbat', '', '', 'Third', '130', 'https://images.pokemoncard.io/images/ex8/ex8-96.png', 'unlimited: Legal', '', 'Crobat ex', '169', 'TPCI', 'Rare Holo EX', '', '02/01/2005', 'type: Fighting, value: -30', '', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '96', 'Stage 2, EX', 'Pokémon', 'Grass', 'type: Lightning, value: ×2'),
('ex8-97', '[{\'name\': \'Form Change\', \'text\': \"Once during your turn (before your attack), you may search your deck for another Deoxys ex and switch it with Deoxys ex. (Any cards attached to Deoxys ex, damage counters, Special Conditions, and effects on it are now on the new Pokémon.) If you do, put Deoxys ex on top of your deck. Shuffle your deck afterward. You can\'t use more than 1 Form Change Poké-Power each turn.\", \'type\': \'Poké-Power\'}]', '', 'Mitsuhiro Arita', '[{\'name\': \'Energy Burst\', \'cost\': [\'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'10+\', \'text\': \'Does 10 damage plus 10 more damage for each Energy attached to Deoxys ex and the Defending Pokémon.\'}]', 'Deoxys', '1', '', '', '', 'Third', '100', 'https://images.pokemoncard.io/images/ex8/ex8-97.png', 'unlimited: Legal', '', 'Deoxys ex', '386', 'TPCI', 'Rare Holo EX', '', '02/01/2005', '', 'Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '97', 'Basic, EX', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2'),
('ex8-98', '[{\'name\': \'Form Change\', \'text\': \"Once during your turn (before your attack), you may search your deck for another Deoxys ex and switch it with Deoxys ex. (Any cards attached to Deoxys ex, damage counters, Special Conditions, and effects on it are now on the new Pokémon.) If you do, put Deoxys ex on top of your deck. Shuffle your deck afterward. You can\'t use more than 1 Form Change Poké-Power each turn.\", \'type\': \'Poké-Power\'}]', '', 'Mitsuhiro Arita', '[{\'name\': \'Psyburst\', \'cost\': [\'Psychic\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50+\', \'text\': \'You may discard 2 Energy attached to Deoxys ex. If you do, this attack does 50 damage plus 20 more damage for each Energy attached to the Defending Pokémon.\'}]', 'Deoxys', '2', '', '', '', 'Third', '110', 'https://images.pokemoncard.io/images/ex8/ex8-98.png', 'unlimited: Legal', '', 'Deoxys ex', '386', 'TPCI', 'Rare Holo EX', '', '02/01/2005', '', 'Colorless, Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '98', 'Basic, EX', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2'),
('ex8-99', '[{\'name\': \'Form Change\', \'text\': \"Once during your turn (before your attack), you may search your deck for another Deoxys ex and switch it with Deoxys ex. (Any cards attached to Deoxys ex, damage counters, Special Conditions, and effects on it are now on the new Pokémon.) If you do, put Deoxys ex on top of your deck. Shuffle your deck afterward. You can\'t use more than 1 Form Change Poké-Power each turn.\", \'type\': \'Poké-Power\'}]', '', 'Mitsuhiro Arita', '[{\'name\': \'Psychic Shield\', \'cost\': [\'Psychic\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50\', \'text\': \"Prevent all effects of attacks, including damage, done to Deoxys ex by your opponent\'s Pokémon-ex during your opponent\'s next turn.\"}]', 'Deoxys', '2', '', '', '', 'Third', '90', 'https://images.pokemoncard.io/images/ex8/ex8-99.png', 'unlimited: Legal', '', 'Deoxys ex', '386', 'TPCI', 'Rare Holo EX', '', '02/01/2005', '', 'Colorless, Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '99', 'Basic, EX', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2'),
('ex9-1', '[{\'name\': \'Blaze\', \'text\': \"As long as Blaziken\'s remaining HP is 40 or less, Blaziken does 40 more damage to the Defending Pokémon (before applying Weakness and Resistance).\", \'type\': \'Poké-Body\'}]', '', 'Midori Harada', '[{\'name\': \'Searing Flame\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'The Defending Pokémon is now Burned.\'}, {\'name\': \'Damage Burn\', \'cost\': [\'Fire\', \'Fire\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50+\', \'text\': \'If the Defending Pokémon already has any damage counters on it, this attack does 50 damage plus 20 more damage.\'}]', 'Emerald', '2', 'Combusken', '', '', 'Third', '110', 'https://images.pokemoncard.io/images/ex9/ex9-1.png', 'unlimited: Legal', '', 'Blaziken', '257', 'TPCI', 'Rare Holo', '', '05/01/2005', '', 'Colorless, Colorless', '', 'EX', '1', 'Stage 2', 'Pokémon', 'Fire', 'type: Water, value: ×2');
