INSERT INTO `cards` (`id`, `abilities`, `ancient_trait`, `artist`, `attacks`, `card_set`, `converted`, `evolves_from`, `evolves_to`, `flavor_text`, `generation`, `hp`, `img`, `legalities`, `level`, `name`, `national_pokedex_numbers`, `publisher`, `rarity`, `regulation_mark`, `release_date`, `resistances`, `retreat_cost`, `rules`, `series`, `set_num`, `subtypes`, `supertype`, `types`, `weakness`) VALUES
('ex9-74', '', '', 'Yuka Morii', '[{\'name\': \'Gnaw\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'\'}, {\'name\': \'Body Slam\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'10\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Paralyzed.\'}]', 'Emerald', '1', '', 'Linoone', '', 'Third', '40', 'https://images.pokemoncard.io/images/ex9/ex9-74.png', 'unlimited: Legal', '', 'Zigzagoon', '263', 'TPCI', 'Common', '', '05/01/2005', '', 'Colorless', '', 'EX', '74', 'Basic', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('ex9-75', '', '', 'Midori Harada', '', 'Emerald', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex9/ex9-75.png', 'unlimited: Legal', '', 'Battle Frontier', '', 'TPCI', 'Uncommon', '', '05/01/2005', '', '', '[\'This card stays in play when you play it. Discard this card if another Stadium card comes into play.\', \"Each player\'s Colorless Evolved Pokémon, Darkness Evolved Pokémon, and Metal Evolved Pokémon can\'t use any Poké-Powers or Poké-Bodies.\"]', 'EX', '75', 'Stadium', 'Trainer', '', ''),
('ex9-76', '', '', 'Ryo Ueda', '', 'Emerald', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex9/ex9-76.png', 'unlimited: Legal', '', 'Double Full Heal', '', 'TPCI', 'Uncommon', '', '05/01/2005', '', '', '[\'Remove all Special Conditions from each of your Active Pokémon.\']', 'EX', '76', 'Item', 'Trainer', '', ''),
('ex9-77', '', '', 'Ken Sugimori', '', 'Emerald', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex9/ex9-77.png', 'unlimited: Legal', '', 'Lanettes Net Search', '', 'TPCI', 'Uncommon', '', '05/01/2005', '', '', '[\'You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.\', \'Search your deck for up to 3 different types of Basic Pokémon cards (excluding Baby Pokémon), show them to your opponent, and put them into your hand. Shuffle your deck afterward.\']', 'EX', '77', 'Supporter', 'Trainer', '', ''),
('ex9-78', '', '', 'Kazuo Yazawa', '', 'Emerald', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex9/ex9-78.png', 'unlimited: Legal, expanded: Legal', '', 'Lum Berry', '', 'TPCI', 'Uncommon', '', '05/01/2005', '', '', '[\"Attach Lum Berry to 1 of your Pokémon that doesn\'t already have a Pokémon Tool attached to it. If that Pokémon is Knocked Out, discard this card.\", \'At any time between turns, if the Pokémon this card is attached to is affected by any Special Conditions, remove all of them. Then, discard Lum Berry.\']', 'EX', '78', 'Pokémon Tool', 'Trainer', '', ''),
('ex9-79', '', '', 'Ken Sugimori', '', 'Emerald', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex9/ex9-79.png', 'unlimited: Legal', '', 'Mr. Stones Project', '', 'TPCI', 'Uncommon', '', '05/01/2005', '', '', '[\'You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.\', \'Search your deck for up to 2 Basic cards, show them to your opponent, and put them into your hand. Shuffle your deck afterward. Or, search your discard pile for up to 2 Basic cards, show them to your opponent, and put them into your hand.\']', 'EX', '79', 'Supporter', 'Trainer', '', ''),
('ex9-8', '', '', 'Kagemaru Himeno', '[{\'name\': \'Surf\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'20\', \'text\': \'\'}, {\'name\': \'Super Hypno Wave\', \'cost\': [\'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Asleep.\'}]', 'Emerald', '2', 'Feebas', '', '', 'Third', '90', 'https://images.pokemoncard.io/images/ex9/ex9-8.png', 'unlimited: Legal', '', 'Milotic', '350', 'TPCI', 'Rare Holo', '', '05/01/2005', '', 'Colorless, Colorless', '', 'EX', '8', 'Stage 1', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('ex9-80', '', '', 'Kazuo Yazawa', '', 'Emerald', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex9/ex9-80.png', 'unlimited: Legal', '', 'Oran Berry', '', 'TPCI', 'Uncommon', '', '05/01/2005', '', '', '[\"Attach Oran Berry to 1 of your Pokémon that doesn\'t already have a Pokémon Tool attached to it. If that Pokémon is Knocked Out, discard this card.\", \'At any time between turns, if the Pokémon this card is attached to has at least 2 damage counters on it, remove 2 damage counters from it. Then, discard Oran Berry.\']', 'EX', '80', 'Pokémon Tool', 'Trainer', '', ''),
('ex9-81', '', '', 'Katsura Tabata', '', 'Emerald', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex9/ex9-81.png', 'unlimited: Legal', '', 'PokéNav', '', 'TPCI', 'Uncommon', '', '05/01/2005', '', '', '[\'Look at the top 3 cards of your deck, and choose a Basic Pokémon, Evolution card, or Energy card. Show it to your opponent and put it into your hand. Put the 2 other cards back on top of your deck in any order.\']', 'EX', '81', 'Item', 'Trainer', '', ''),
('ex9-82', '', '', 'Ken Sugimori', '', 'Emerald', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex9/ex9-82.png', 'unlimited: Legal', '', 'Professor Birch', '', 'TPCI', 'Uncommon', '', '05/01/2005', '', '', '[\'You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.\', \'Draw cards from your deck until you have 6 cards in your hand.\']', 'EX', '82', 'Supporter', 'Trainer', '', ''),
('ex9-83', '', '', 'Ryo Ueda', '', 'Emerald', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex9/ex9-83.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Rare Candy', '', 'TPCI', 'Uncommon', '', '05/01/2005', '', '', '[\'Choose 1 of your Basic Pokémon in play. If you have a Stage 1 or Stage 2 card that evolves from that Pokémon in your hand, put that card on the Basic Pokémon. (This counts as evolving that Pokémon.)\']', 'EX', '83', 'Item', 'Trainer', '', ''),
('ex9-84', '', '', 'Ken Sugimori', '', 'Emerald', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex9/ex9-84.png', 'unlimited: Legal', '', 'Scott', '', 'TPCI', 'Uncommon', '', '05/01/2005', '', '', '[\'You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.\', \'Search your deck for up to 3 cards in any combination of Supporter cards and Stadium cards, show them to your opponent, and put them into your hand. Shuffle your deck afterward.\']', 'EX', '84', 'Supporter', 'Trainer', '', ''),
('ex9-85', '', '', 'Ken Sugimori', '', 'Emerald', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex9/ex9-85.png', 'unlimited: Legal', '', 'Wallys Training', '', 'TPCI', 'Uncommon', '', '05/01/2005', '', '', '[\'You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.\', \'Search your deck for a card that evolves from your Active Pokémon (choose 1 if there are 2) and put it on your Active Pokémon. (This counts as evolving that Pokémon.) Shuffle your deck afterward.\']', 'EX', '85', 'Supporter', 'Trainer', '', ''),
('ex9-86', '', '', 'Milky Isobe', '', 'Emerald', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex9/ex9-86.png', 'unlimited: Legal', '', 'Darkness Energy', '', 'TPCI', 'Rare', '', '05/01/2005', '', '', '[\"If the Pokémon Darkness Energy is attached to attacks, the attack does 10 more damage to the Active Pokémon (before applying Weakness and Resistance). Ignore this effect unless the Attacking Pokémon is Darkness or has Dark in its name. Darkness Energy provides Darkness Energy. (Doesn\'t count as a Basic card.)\"]', 'EX', '86', 'Special', 'Energy', '', ''),
('ex9-87', '', '', 'Takumi Akabane', '', 'Emerald', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex9/ex9-87.png', 'unlimited: Legal', '', 'Double Rainbow Energy', '', 'TPCI', 'Rare', '', '05/01/2005', '', '', '[\"Double Rainbow Energy can be attached only to an Evolved Pokémon (excluding Pokémon-ex). While in play, Double Rainbow Energy provides every type of Energy but provides 2 Energy at a time. (Has no effect other than providing Energy.) Damage done to your opponent\'s Pokémon by the Pokémon Double Rainbow Energy is attached to is reduced by 10 (before applying Weakness and Resistance). When the Pokémon Double Rainbow Energy is attached to is no longer an Evolved Pokémon, discard Double Rainbow Energy.\"]', 'EX', '87', 'Special', 'Energy', '', ''),
('ex9-88', '', '', 'Milky Isobe', '', 'Emerald', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex9/ex9-88.png', 'unlimited: Legal', '', 'Metal Energy', '', 'TPCI', 'Rare', '', '05/01/2005', '', '', '[\"Damage done by attacks to the Pokémon that Metal Energy is attached to is reduced by 10 (after applying Weakness and Resistance). Ignore this effect if the Pokémon that Metal Energy is attached to isn\'t Metal. Metal Energy provides Metal Energy. (Doesn\'t count as a Basic card.)\"]', 'EX', '88', 'Special', 'Energy', '', ''),
('ex9-89', '', '', 'Takumi Akabane', '', 'Emerald', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/ex9/ex9-89.png', 'unlimited: Legal', '', 'Multi Energy', '', 'TPCI', 'Rare', '', '05/01/2005', '', '', '[\'Attach Multi Energy to 1 of your Pokémon. While in play, Multi Energy provides every type of Energy but provides only 1 Energy at a time. (Has no effect other than providing Energy.) Multi Energy provides Colorless Energy when attached to a Pokémon that already has Special Energy cards attached to it.\']', 'EX', '89', 'Special', 'Energy', '', ''),
('ex9-9', '', '', 'Kouki Saitou', '[{\'name\': \'Dragon Dance\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'\', \'text\': \'During your next turn, if any of your current Active Pokémon does damage to any Defending Pokémon, the attack does 30 more damage (before applying Weakness and Resistance).\'}, {\'name\': \'Dragon Claw\', \'cost\': [\'Fire\', \'Lightning\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40\', \'text\': \'\'}]', 'Emerald', '2', '', '', '', 'Third', '80', 'https://images.pokemoncard.io/images/ex9/ex9-9.png', 'unlimited: Legal', '', 'Rayquaza', '384', 'TPCI', 'Rare Holo', '', '05/01/2005', '', 'Colorless, Colorless', '', 'EX', '9', 'Basic', 'Pokémon', 'Colorless', 'type: Colorless, value: ×2'),
('ex9-90', '[{\'name\': \'Mist\', \'text\': \"Any damage done to Altaria ex by attacks from Stage 2 Evolved Pokémon (both yours and your opponent\'s) is reduced by 30 (after applying Weakness and Resistance).\", \'type\': \'Poké-Body\'}]', '', 'Ryo Ueda', '[{\'name\': \'Dive\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'20\', \'text\': \'\'}, {\'name\': \'Dragon Mist\', \'cost\': [\'Water\', \'Lightning\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'70\', \'text\': \"This attack\'s damage isn\'t affected by Resistance, Poké-Powers, Poké-Bodies, or any other effects on the Defending Pokémon.\"}]', 'Emerald', '1', 'Swablu', '', '', 'Third', '100', 'https://images.pokemoncard.io/images/ex9/ex9-90.png', 'unlimited: Legal', '', 'Altaria ex', '334', 'TPCI', 'Rare Holo EX', '', '05/01/2005', '', 'Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '90', 'Stage 1, EX', 'Pokémon', 'Colorless', ''),
('ex9-91', '[{\'name\': \'Cursed Glare\', \'text\': \"As long as Cacturne ex is your Active Pokémon, your opponent can\'t attach any Special Energy cards (except for Darkness and Metal Energy cards) from his or her hand to his or her Active Pokémon.\", \'type\': \'Poké-Body\'}]', '', 'Hikaru Koike', '[{\'name\': \'Psybeam\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'20\', \'text\': \'The Defending Pokémon is now Confused.\'}, {\'name\': \'Spike Rend\', \'cost\': [\'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50+\', \'text\': \'If the Defending Pokémon already has any damage counters on it, this attack does 50 damage plus 20 more damage.\'}]', 'Emerald', '1', 'Cacnea', '', '', 'Third', '110', 'https://images.pokemoncard.io/images/ex9/ex9-91.png', 'unlimited: Legal', '', 'Cacturne ex', '332', 'TPCI', 'Rare Holo EX', '', '05/01/2005', '', 'Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '91', 'Stage 1, EX', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('ex9-92', '[{\'name\': \'Magma Armor\', \'text\': \"Camerupt ex can\'t be Asleep or Paralyzed.\", \'type\': \'Poké-Body\'}]', '', 'Ryo Ueda', '[{\'name\': \'Searing Flame\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'The Defending Pokémon is now Burned.\'}, {\'name\': \'Eruption\', \'cost\': [\'Fire\', \'Fire\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60+\', \'text\': \'Each player discards the top card of his or her deck. This attack does 60 damage plus 20 more damage for each Energy card discarded in this way.\'}]', 'Emerald', '2', 'Numel', '', '', 'Third', '120', 'https://images.pokemoncard.io/images/ex9/ex9-92.png', 'unlimited: Legal', '', 'Camerupt ex', '323', 'TPCI', 'Rare Holo EX', '', '05/01/2005', '', 'Colorless, Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '92', 'Stage 1, EX', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('ex9-93', '[{\'name\': \'Form Change\', \'text\': \"Once during your turn (before your attack), you may search your deck for another Deoxys ex and switch it with Deoxys ex. (Any cards attached to Deoxys ex, damage counters, Special Conditions, and effects on it are now on the new Pokémon.) If you do, put Deoxys ex on top of your deck. Shuffle your deck afterward. You can\'t use more than 1 Form Change Poké-Power each turn.\", \'type\': \'Poké-Power\'}]', '', 'Mitsuhiro Arita', '[{\'name\': \'Fastwave\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50\', \'text\': \"This attack\'s damage isn\'t affected by Resistance, Poké-Powers, Poké-Bodies, or any other effects on the Defending Pokémon.\"}]', 'Emerald', '1', '', '', '', 'Third', '110', 'https://images.pokemoncard.io/images/ex9/ex9-93.png', 'unlimited: Legal', '', 'Deoxys ex', '386', 'TPCI', 'Rare Holo EX', '', '05/01/2005', '', 'Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '93', 'Basic, EX', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2'),
