('ex9-95', '[{\'name\': \'Wise Aura\', \'text\': \"As long as Medicham ex is your Active Pokémon, each Pokémon (excluding Pokémon-ex) (both yours and your opponent\'s) can\'t use any Poké-Powers.\", \'type\': \'Poké-Body\'}]', '', 'Hikaru Koike', '[{\'name\': \'Pure Power\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'\', \'text\': \"Put 3 damage counters on your opponent\'s Pokémon in any way you like.\"}, {\'name\': \'Sky Kick\', \'cost\': [\'Fighting\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60+\', \'text\': \'If the Defending Pokémon has Fighting Resistance, this attack does 60 damage plus 40 more damage.\'}]', 'Emerald', '1', 'Meditite', '', '', 'Third', '110', 'https://images.pokemoncard.io/images/ex9/ex9-95.png', 'unlimited: Legal', '', 'Medicham ex', '308', 'TPCI', 'Rare Holo EX', '', '05/01/2005', '', 'Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '95', 'Stage 1, EX', 'Pokémon', 'Fighting', 'type: Psychic, value: ×2'),
('ex9-96', '[{\'name\': \'Mystic Scale\', \'text\': \"As long as Milotic ex is in play, each player can\'t play any Technical Machine cards from his or her hand. Discard all Technical Machine cards in play (both yours and your opponent\'s).\", \'type\': \'Poké-Body\'}]', '', 'Ryo Ueda', '[{\'name\': \'Gentle Wrap\', \'cost\': [\'Water\'], \'convertedEnergyCost\': 1, \'damage\': \'30\', \'text\': \"The Defending Pokémon can\'t retreat during your opponent\'s next turn.\"}, {\'name\': \'Reflect Energy\', \'cost\': [\'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'70\', \'text\': \'Move 1 basic Energy card attached to Milotic ex to 1 of your Benched Pokémon.\'}]', 'Emerald', '2', 'Feebas', '', '', 'Third', '130', 'https://images.pokemoncard.io/images/ex9/ex9-96.png', 'unlimited: Legal', '', 'Milotic ex', '350', 'TPCI', 'Rare Holo EX', '', '05/01/2005', '', 'Colorless, Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '96', 'Stage 1, EX', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('ex9-97', '[{\'name\': \'Rai-shield\', \'text\': \"Damage done to any of your Raichu ex in play by attacks from your opponent\'s Pokémon-ex is reduced by 30 (after applying Weakness and Resistance). You can\'t use more than 1 Rai-shield Poké-Body each turn.\", \'type\': \'Poké-Body\'}]', '', 'Mitsuhiro Arita', '[{\'name\': \'Power Short\', \'cost\': [\'Lightning\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'\', \'text\': \"Choose 1 of your opponent\'s Pokémon. This attack does 30 damage to that Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.) If that Pokémon has Poké-Powers, this attack does 30 damage plus 20 more damage.\"}, {\'name\': \'Pika Bolt\', \'cost\': [\'Lightning\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'70\', \'text\': \'\'}]', 'Emerald', '', 'Pikachu', '', '', 'Third', '100', 'https://images.pokemoncard.io/images/ex9/ex9-97.png', 'unlimited: Legal', '', 'Raichu ex', '26', 'TPCI', 'Rare Holo EX', '', '05/01/2005', '', '', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'EX', '97', 'Stage 1, EX', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
