('g1-RC25', '', '', 'Aya Kusube', '[{\'name\': \'Warble\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Search your deck for up to 2 Fletchling, reveal them, and put them into your hand. Shuffle your deck afterward.\'}]', 'Generations', '1', '', 'Fletchinder', 'Little friends, thanks for always helping me look so cute!', 'Sixth', '40', 'https://images.pokemoncard.io/images/g1/g1-RC25.png', 'unlimited: Legal, expanded: Legal', '', 'Fletchling', '661', 'TPCI', 'Common', '', '2/22/2016', 'type: Fighting, value: -20', 'Colorless', '', 'XY', 'RC25', 'Basic', 'Pokémon', 'Colorless', 'type: Lightning, value: ×2'),
('g1-RC26', '', '', 'Aya Kusube', '', 'Generations', '', '', '', '', 'Sixth', '', 'https://images.pokemoncard.io/images/g1/g1-RC26.png', 'unlimited: Legal, expanded: Legal', '', 'Floral Crown', '', 'TPCI', 'Common', '', '2/22/2016', '', '', '[\"Attach a Pokémon Tool to 1 of your Pokémon that doesn\'t already have a Pokémon Tool attached to it.\", \"At the end of your opponent\'s turn, heal 20 damage from the Basic Pokémon this card is attached to.\", \'You may play as many Item cards as you like during your turn (before your attack).\']', 'XY', 'RC26', 'Pokémon Tool', 'Trainer', '', ''),
('g1-RC27', '', '', 'Megumi Mizutani', '', 'Generations', '', '', '', '', 'Sixth', '', 'https://images.pokemoncard.io/images/g1/g1-RC27.png', 'unlimited: Legal, expanded: Legal', '', 'Wally', '', 'TPCI', 'Uncommon', '', '2/22/2016', '', '', '[\'Search your deck for a card that evolves from 1 of your Pokémon (excluding Pokémon-EX) and put it onto that Pokémon. (This counts as evolving that Pokémon.) Shuffle your deck afterward. You can use this card during your first turn or on a Pokémon that was put into play this turn.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'XY', 'RC27', 'Supporter', 'Trainer', '', '');
INSERT INTO `cards` (`id`, `abilities`, `ancient_trait`, `artist`, `attacks`, `card_set`, `converted`, `evolves_from`, `evolves_to`, `flavor_text`, `generation`, `hp`, `img`, `legalities`, `level`, `name`, `national_pokedex_numbers`, `publisher`, `rarity`, `regulation_mark`, `release_date`, `resistances`, `retreat_cost`, `rules`, `series`, `set_num`, `subtypes`, `supertype`, `types`, `weakness`) VALUES
('g1-RC28', '[{\'name\': \'Flash Fire\', \'text\': \'Once during your turn (before your attack), you may move a Fire Energy from 1 of your Pokémon to this Pokémon.\', \'type\': \'Ability\'}]', '', 'kirisAki', '[{\'name\': \'Blaze Ball\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50+\', \'text\': \'This attack does 20 more damage for each Fire Energy attached to this Pokémon.\'}]', 'Generations', '2', '', '', '', 'Sixth', '170', 'https://images.pokemoncard.io/images/g1/g1-RC28.png', 'unlimited: Legal, expanded: Legal', '', 'Flareon-EX', '136', 'TPCI', 'Rare Ultra', '', '2/22/2016', '', 'Colorless, Colorless', '[\'Pokémon-EX rule: When a Pokémon-EX has been Knocked Out, your opponent takes 2 Prize cards.\']', 'XY', 'RC28', 'Basic, EX', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('g1-RC29', '', '', 'Kagemaru Himeno', '[{\'name\': \'Nuzzle\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Flip a coin. If heads, your opponent\'s Active Pokémon is now Paralyzed.\"}, {\'name\': \'Quick Attack\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20+\', \'text\': \'Flip a coin. If heads, this attack does 10 more damage.\'}]', 'Generations', '1', '', 'Raichu', 'A yellow body is proof of good health. If you touch its bright-red cheeks, youll see its shining, smiling face!', 'Sixth', '60', 'https://images.pokemoncard.io/images/g1/g1-RC29.png', 'unlimited: Legal, expanded: Legal', '', 'Pikachu', '25', 'TPCI', 'Rare Ultra', '', '2/22/2016', 'type: Metal, value: -20', 'Colorless', '', 'XY', 'RC29', 'Basic', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
('g1-RC3', '', '', 'Akira Komayama', '[{\'name\': \'Playful\', \'cost\': [\'Fire\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20×\', \'text\': \'Flip a coin. If heads, this attack does 20 damage times the number of damage counters on this Pokémon.\'}]', 'Generations', '2', '', 'Charmeleon', 'My Charmander is so rambunctious! I wonder if we can become good friends?', 'Sixth', '70', 'https://images.pokemoncard.io/images/g1/g1-RC3.png', 'unlimited: Legal, expanded: Legal', '', 'Charmander', '4', 'TPCI', 'Common', '', '2/22/2016', '', 'Colorless, Colorless', '', 'XY', 'RC3', 'Basic', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('g1-RC30', '', '', 'Mizue', '[{\'name\': \'Life Leap\', \'cost\': [\'Fairy\'], \'convertedEnergyCost\': 1, \'damage\': \'20\', \'text\': \"Heal from this Pokémon the same amount of damage you did to your opponent\'s Active Pokémon.\"}, {\'name\': \'Shining Wind\', \'cost\': [\'Fairy\', \'Fairy\', \'Fairy\'], \'convertedEnergyCost\': 3, \'damage\': \'100\', \'text\': \"During your opponent\'s next turn, this Pokémon has no Weakness.\"}]', 'Generations', '2', '', 'M Gardevoir-EX', '', 'Sixth', '170', 'https://images.pokemoncard.io/images/g1/g1-RC30.png', 'unlimited: Legal, expanded: Legal', '', 'Gardevoir-EX', '282', 'TPCI', 'Rare Ultra', '', '2/22/2016', 'type: Darkness, value: -20', 'Colorless, Colorless', '[\'Pokémon-EX rule: When a Pokémon-EX has been Knocked Out, your opponent takes 2 Prize cards.\']', 'XY', 'RC30', 'Basic, EX', 'Pokémon', 'Fairy', 'type: Metal, value: ×2'),
('g1-RC31', '', '', 'Megumi Mizutani', '[{\'name\': \'Brilliant Arrow\', \'cost\': [\'Fairy\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'30×\', \'text\': \'This attack does 30 damage times the amount of Fairy Energy attached to all of your Pokémon.\'}]', 'Generations', '2', 'Gardevoir-EX', '', '', 'Sixth', '210', 'https://images.pokemoncard.io/images/g1/g1-RC31.png', 'unlimited: Legal, expanded: Legal', '', 'M Gardevoir-EX', '282', 'TPCI', 'Rare Ultra', '', '2/22/2016', 'type: Darkness, value: -20', 'Colorless, Colorless', '[\'Mega Evolution rule: When 1 of your Pokémon becomes a Mega Evolution Pokémon, your turn ends.\', \'Pokémon-EX rule: When a Pokémon-EX has been Knocked Out, your opponent takes 2 Prize cards.\']', 'XY', 'RC31', 'MEGA, EX', 'Pokémon', 'Fairy', 'type: Metal, value: ×2'),
('g1-RC32', '', '', 'Kanako Eo', '[{\'name\': \'Dress Up\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30+\', \'text\': \'If this Pokémon has a Pokémon Tool card attached to it, this attack does 30 more damage.\'}, {\'name\': \'Precious Ribbon\', \'cost\': [\'Fairy\', \'Fairy\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'100\', \'text\': \'Move a Fairy Energy from this Pokémon to 1 of your Benched Pokémon. If you do, heal 50 damage from that Pokémon.\'}]', 'Generations', '2', '', '', '', 'Sixth', '170', 'https://images.pokemoncard.io/images/g1/g1-RC32.png', 'unlimited: Legal, expanded: Legal', '', 'Sylveon-EX', '700', 'TPCI', 'Rare Ultra', '', '2/22/2016', 'type: Darkness, value: -20', 'Colorless, Colorless', '[\'Pokémon-EX rule: When a Pokémon-EX has been Knocked Out, your opponent takes 2 Prize cards.\']', 'XY', 'RC32', 'Basic, EX', 'Pokémon', 'Fairy', 'type: Metal, value: ×2'),
('g1-RC4', '', '', 'Akira Komayama', '[{\'name\': \'Call for Support\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Search your deck for a Supporter card, reveal it, and put it into your hand. Shuffle your deck afterward.\'}, {\'name\': \'Slash\', \'cost\': [\'Fire\', \'Fire\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'80\', \'text\': \'\'}]', 'Generations', '2', 'Charmander', 'Charizard', 'My precious friend who is always with me. I have so many things I want to tell you.', 'Sixth', '90', 'https://images.pokemoncard.io/images/g1/g1-RC4.png', 'unlimited: Legal, expanded: Legal', '', 'Charmeleon', '5', 'TPCI', 'Common', '', '2/22/2016', '', 'Colorless, Colorless', '', 'XY', 'RC4', 'Stage 1', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('g1-RC5', '', '', 'Akira Komayama', '[{\'name\': \'Recall\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Choose 1 of this Pokémon\'s attacks from its previous Evolutions and use it as this attack.\"}, {\'name\': \'Combustion Blast\', \'cost\': [\'Fire\', \'Fire\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'130\', \'text\': \"This Pokémon can\'t use Combustion Blast during your next turn.\"}]', 'Generations', '3', 'Charmeleon', '', 'No matter what happens, if we stick together, we can get past it. Forever and ever.', 'Sixth', '160', 'https://images.pokemoncard.io/images/g1/g1-RC5.png', 'unlimited: Legal, expanded: Legal', '', 'Charizard', '6', 'TPCI', 'Uncommon', '', '2/22/2016', '', 'Colorless, Colorless, Colorless', '', 'XY', 'RC5', 'Stage 2', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('g1-RC6', '[{\'name\': \'Flash Fire\', \'text\': \'Once during your turn (before your attack), you may move a Fire Energy from 1 of your Pokémon to this Pokémon.\', \'type\': \'Ability\'}]', '', 'Atsuko Nishida', '[{\'name\': \'Blaze Ball\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50+\', \'text\': \'This attack does 20 more damage for each Fire Energy attached to this Pokémon.\'}]', 'Generations', '2', '', '', '', 'Sixth', '170', 'https://images.pokemoncard.io/images/g1/g1-RC6.png', 'unlimited: Legal, expanded: Legal', '', 'Flareon-EX', '136', 'TPCI', 'Rare Holo EX', '', '2/22/2016', '', 'Colorless, Colorless', '[\'Pokémon-EX rule: When a Pokémon-EX has been Knocked Out, your opponent takes 2 Prize cards.\']', 'XY', 'RC6', 'Basic, EX', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('g1-RC7', '', '', 'MAHOU', '[{\'name\': \'Icy Snow\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'\'}]', 'Generations', '1', '', 'Glalie, Froslass', 'What a delicious-looking snowman! I think Ill sneak a bite. Its OK…no ones looking, right?', 'Sixth', '50', 'https://images.pokemoncard.io/images/g1/g1-RC7.png', 'unlimited: Legal, expanded: Legal', '', 'Snorunt', '361', 'TPCI', 'Common', '', '2/22/2016', '', 'Colorless', '', 'XY', 'RC7', 'Basic', 'Pokémon', 'Water', 'type: Metal, value: ×2'),
('g1-RC8', '[{\'name\': \'Drag Along\', \'text\': \"If this Pokémon is your Active Pokémon and is Knocked Out by damage from an opponent\'s attack, flip a coin. If heads, the Attacking Pokémon is Knocked Out.\", \'type\': \'Ability\'}]', '', 'Shin Nagasawa', '[{\'name\': \'Snowy Drop\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'\', \'text\': \"Put 4 damage counters on your opponent\'s Pokémon in any way you like.\"}]', 'Generations', '2', 'Snorunt', '', 'Spring is already here, so goodbye…', 'Sixth', '90', 'https://images.pokemoncard.io/images/g1/g1-RC8.png', 'unlimited: Legal, expanded: Legal', '', 'Froslass', '478', 'TPCI', 'Uncommon', '', '2/22/2016', '', 'Colorless, Colorless', '', 'XY', 'RC8', 'Stage 1', 'Pokémon', 'Water', 'type: Metal, value: ×2'),
('g1-RC9', '', '', 'Aya Kusube', '[{\'name\': \'Circle Circuit\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20×\', \'text\': \'This attack does 20 damage times the number of Pokémon on your Bench.\'}, {\'name\': \'Thunderbolt\', \'cost\': [\'Lightning\', \'Lightning\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'100\', \'text\': \'Discard all Energy attached to this Pokémon.\'}]', 'Generations', '', 'Pikachu', '', 'The plan for today is to do nothing. My awesome tail is all curled up, and my ears are tired, too.', 'Sixth', '90', 'https://images.pokemoncard.io/images/g1/g1-RC9.png', 'unlimited: Legal, expanded: Legal', '', 'Raichu', '26', 'TPCI', 'Common', '', '2/22/2016', 'type: Metal, value: -20', '', '', 'XY', 'RC9', 'Stage 1', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
('gym1-1', '', '', 'Ken Sugimori', '[{\'name\': \'Phoenix Flame\', \'cost\': [\'Fire\', \'Fire\', \'Fire\', \'Fire\', \'Fire\'], \'convertedEnergyCost\': 5, \'damage\': \'90\', \'text\': \"Flip a coin. If tails, shuffle Blaine\'s Moltres and all cards attached to it into your deck (after doing damage).\"}]', 'Gym Heroes', '3', '', '', '', 'First', '90', 'https://images.pokemoncard.io/images/gym1/gym1-1.png', 'unlimited: Legal', '44', 'Blaines Moltres', '146', 'WOTC', 'Rare Holo', '', '8/14/2000', 'type: Fighting, value: -30', 'Colorless, Colorless, Colorless', '', 'Gym', '1', 'Basic', 'Pokémon', 'Fire', ''),
('gym1-10', '[{\'name\': \'Flee\', \'text\': \"If an attack does damage to Misty\'s Tentacruel while it\'s your Active Pokémon, you may switch it with 1 of your Benched Pokémon, which prevents all other effects of that attack on Misty\'s Tentacruel. This power can\'t be used if Misty\'s Tentacruel is already Asleep, Confused, or Paralyzed.\", \'type\': \'Pokémon Power\'}]', '', 'Ken Sugimori', '[{\'name\': \'Jellyfish Poison\', \'cost\': [\'Water\', \'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'30\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Poisoned. If tails, the Defending Pokémon is now Confused.\'}]', 'Gym Heroes', '', 'Mistys Tentacool', '', '', 'First', '70', 'https://images.pokemoncard.io/images/gym1/gym1-10.png', 'unlimited: Legal', '30', 'Mistys Tentacruel', '73', 'WOTC', 'Rare Holo', '', '8/14/2000', '', '', '', 'Gym', '10', 'Stage 1', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('gym1-100', '', '', 'Ken Sugimori', '', 'Gym Heroes', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym1/gym1-100.png', 'unlimited: Legal', '', 'Erika', '', 'WOTC', 'Rare', '', '8/14/2000', '', '', '[\'You may draw up to 3 cards, then your opponent may draw up to 3 cards.\']', 'Gym', '100', '', 'Trainer', '', ''),
('gym1-101', '', '', 'Ken Sugimori', '', 'Gym Heroes', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym1/gym1-101.png', 'unlimited: Legal', '', 'Lt. Surge', '', 'WOTC', 'Rare', '', '8/14/2000', '', '', '[\"You can play this card only if you have at least 1 Basic Pokémon card in your hand. Put a Basic Pokémon card from your hand into play as your Active Pokémon. Put your old Active Pokémon onto your Bench. (You can\'t play this card if your Bench is full.)\"]', 'Gym', '101', '', 'Trainer', '', ''),
('gym1-102', '', '', 'Ken Sugimori', '', 'Gym Heroes', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym1/gym1-102.png', 'unlimited: Legal', '', 'Misty', '', 'WOTC', 'Rare', '', '8/14/2000', '', '', '[\"Discard 2 of the other cards in your hand in order to play this card. If this turn\'s attack does damage to the Defending Pokémon (after applying Weakness and Resistance), and if the attacking Pokémon has Misty in its name, the attack does 20 more damage to the Defending Pokémon.\"]', 'Gym', '102', '', 'Trainer', '', ''),
('gym1-103', '', '', 'Keiji Kinebuchi', '', 'Gym Heroes', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym1/gym1-103.png', 'unlimited: Legal', '', 'No Removal Gym', '', 'WOTC', 'Rare', '', '8/14/2000', '', '', '[\'This card stays in play when you play it. Discard this card if another Stadium card comes into play.\', \'A player must discard 2 cards from his or her hand in order to play an Energy Removal or Super Energy Removal card.\']', 'Gym', '103', 'Stadium', 'Trainer', '', ''),
('gym1-104', '', '', 'Keiji Kinebuchi', '', 'Gym Heroes', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym1/gym1-104.png', 'unlimited: Legal', '', 'The Rockets Training Gym', '', 'WOTC', 'Rare', '', '8/14/2000', '', '', '[\'This card stays in play when you play it. Discard this card if another Stadium card comes into play.\', \'Each player pays Colorless more to retreat his or her Active Pokémon.\']', 'Gym', '104', 'Stadium', 'Trainer', '', ''),
('gym1-105', '', '', 'Ken Sugimori', '', 'Gym Heroes', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym1/gym1-105.png', 'unlimited: Legal', '', 'Blaines Last Resort', '', 'WOTC', 'Uncommon', '', '8/14/2000', '', '', '[\"You can\'t play this card if you have any cards in your hand other than Blaine\'s Last Resort. Show your hand to your opponent, then draw 5 cards.\"]', 'Gym', '105', '', 'Trainer', '', ''),
('gym1-106', '', '', 'Ken Sugimori', '', 'Gym Heroes', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym1/gym1-106.png', 'unlimited: Legal', '', 'Brocks Training Method', '', 'WOTC', 'Uncommon', '', '8/14/2000', '', '', '[\'Search your deck for a Basic Pokémon or Evolution card with Brock in its name. Show that card to your opponent, then put it into your hand. Shuffle your deck afterward.\']', 'Gym', '106', '', 'Trainer', '', ''),
('gym1-107', '', '', 'Keiji Kinebuchi', '', 'Gym Heroes', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym1/gym1-107.png', 'unlimited: Legal', '', 'Celadon City Gym', '', 'WOTC', 'Uncommon', '', '8/14/2000', '', '', '[\'This card stays in play when you play it. Discard this card if another Stadium card comes into play.\', \"During each player\'s turn, that player may choose to discard an Energy card attached to 1 of his or her Pokémon with Erika in its name. If that player does so, that Pokémon is no longer Asleep, Confused, Paralyzed, or Poisoned.\"]', 'Gym', '107', 'Stadium', 'Trainer', '', ''),
('gym1-108', '', '', 'Keiji Kinebuchi', '', 'Gym Heroes', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym1/gym1-108.png', 'unlimited: Legal', '', 'Cerulean City Gym', '', 'WOTC', 'Uncommon', '', '8/14/2000', '', '', '[\'This card stays in play when you play it. Discard this card if another Stadium card comes into play.\', \'Each player pays Colorless less to retreat his or her Pokémon if it has Misty in its name.\']', 'Gym', '108', 'Stadium', 'Trainer', '', ''),
('gym1-109', '', '', 'Ken Sugimori', '', 'Gym Heroes', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym1/gym1-109.png', 'unlimited: Legal', '', 'Erikas Maids', '', 'WOTC', 'Uncommon', '', '8/14/2000', '', '', '[\'Trade 2 of the other cards in your hand for up to 2 Basic Pokémon and/or Evolution cards with Erika in their names from your deck. Show those cards to your opponent, then put them into your hand. Shuffle your deck afterward.\']', 'Gym', '109', '', 'Trainer', '', ''),
('gym1-11', '', '', 'Ken Sugimori', '[{\'name\': \'Crosscounter\', \'cost\': [\'Fighting\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"If an attack does damage to Rocket\'s Hitmonchan during your opponent\'s next turn (even if Rocket\'s Hitmonchan is Knocked Out), flip a coin. If heads, Rocket\'s Hitmonchan attacks your opponent\'s Active Pokémon for double that amount of damage. (If Rocket\'s Hitmonchan takes 20 damage, it does 40 damage to that Pokémon.)\"}, {\'name\': \'Magnum Punch\', \'cost\': [\'Fighting\', \'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50\', \'text\': \'\'}]', 'Gym Heroes', '1', '', '', '', 'First', '60', 'https://images.pokemoncard.io/images/gym1/gym1-11.png', 'unlimited: Legal', '29', 'Rockets Hitmonchan', '107', 'WOTC', 'Rare Holo', '', '8/14/2000', '', 'Colorless', '', 'Gym', '11', 'Basic', 'Pokémon', 'Fighting', 'type: Psychic, value: ×2'),
('gym1-110', '', '', 'Ken Sugimori', '', 'Gym Heroes', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym1/gym1-110.png', 'unlimited: Legal', '', 'Erikas Perfume', '', 'WOTC', 'Uncommon', '', '8/14/2000', '', '', '[\"Look at your opponent\'s hand. If he or she has any Basic Pokémon cards there, you may put any number of them onto your opponent\'s Bench (as long as there\'s room).\"]', 'Gym', '110', '', 'Trainer', '', ''),
('gym1-111', '', '', 'Ken Sugimori', '', 'Gym Heroes', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym1/gym1-111.png', 'unlimited: Legal', '', 'Good Manners', '', 'WOTC', 'Uncommon', '', '8/14/2000', '', '', '[\"In order to play this card, you can\'t have any Basic Pokémon cards in your hand. Show your hand to your opponent, then search your deck for a Basic Pokémon card, show it to your opponent, and put it into your hand. Shuffle your deck afterward.\"]', 'Gym', '111', '', 'Trainer', '', ''),
('gym1-112', '', '', 'Ken Sugimori', '', 'Gym Heroes', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym1/gym1-112.png', 'unlimited: Legal', '', 'Lt. Surges Treaty', '', 'WOTC', 'Uncommon', '', '8/14/2000', '', '', '[\'Your opponent chooses 1 of the following: everyone chooses 1 of his or her own Prizes and put it into his or her hand, or you draw a card.\']', 'Gym', '112', '', 'Trainer', '', ''),
('gym1-113', '', '', 'Ken Sugimori', '', 'Gym Heroes', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym1/gym1-113.png', 'unlimited: Legal', '', 'Minion of Team Rocket', '', 'WOTC', 'Uncommon', '', '8/14/2000', '', '', '[\"Flip 2 coins. If both of them are heads, choose 1 of your opponent\'s Benched Pokémon and return it and all cards attached to it to his or her hand. If 1 or both of them are tails, your turn ends immediately (you can\'t attack this turn).\"]', 'Gym', '113', '', 'Trainer', '', ''),
('gym1-114', '', '', 'Ken Sugimori', '', 'Gym Heroes', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym1/gym1-114.png', 'unlimited: Legal', '', 'Mistys Wrath', '', 'WOTC', 'Uncommon', '', '8/14/2000', '', '', '[\'Look at the top 7 cards of your deck. Choose 2 of those cards and put them into your hand. Discard the rest.\']', 'Gym', '114', '', 'Trainer', '', ''),
('gym1-115', '', '', 'Keiji Kinebuchi', '', 'Gym Heroes', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym1/gym1-115.png', 'unlimited: Legal', '', 'Pewter City Gym', '', 'WOTC', 'Uncommon', '', '8/14/2000', '', '', '[\'This card stays in play when you play it. Discard this card if another Stadium card comes into play.\', \"Don\'t apply Resistance to any attacks made by Pokémon with Brock in their names.\"]', 'Gym', '115', 'Stadium', 'Trainer', '', ''),
('gym1-116', '', '', 'Sumiyoshi Kizuki', '', 'Gym Heroes', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym1/gym1-116.png', 'unlimited: Legal', '', 'Recall', '', 'WOTC', 'Uncommon', '', '8/14/2000', '', '', '[\"For your attack this turn, your Active Pokémon can use any attack from its Basic Pokémon card or any Evolution card attached to it. (You still have to pay for that attack\'s Energy cost.)\"]', 'Gym', '116', '', 'Trainer', '', ''),
('gym1-117', '', '', 'Ken Sugimori', '', 'Gym Heroes', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym1/gym1-117.png', 'unlimited: Legal', '', 'Sabrinas ESP', '', 'WOTC', 'Uncommon', '', '8/14/2000', '', '', '[\"Attach Sabrina\'s ESP to 1 of your Pokémon with Sabrina in its name. At the end of your turn, discard Sabrina\'s ESP. If that Pokémon uses and attack that involves flipping coins, Sabrina\'s ESP lets you re-flip those coins once. If you do, re-flip all the coins.\"]', 'Gym', '117', '', 'Trainer', '', ''),
('gym1-118', '', '', 'Ken Sugimori', '', 'Gym Heroes', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym1/gym1-118.png', 'unlimited: Legal', '', 'Secret Mission', '', 'WOTC', 'Uncommon', '', '8/14/2000', '', '', '[\"Look at your opponent\'s hand. Then, you may discard as many other cards as you want from your hand and draw that many cards.\"]', 'Gym', '118', '', 'Trainer', '', ''),
('gym1-119', '', '', 'Sumiyoshi Kizuki', '', 'Gym Heroes', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym1/gym1-119.png', 'unlimited: Legal', '', 'Tickling Machine', '', 'WOTC', 'Uncommon', '', '8/14/2000', '', '', '[\"Flip a coin. If heads, your opponent sets aside all the cards in his or her hand face down. Nobody may look at those cards. At the end of your opponent\'s next turn, your opponent puts those cards back into his or her hand. If tails, your turn ends immediately (you can\'t attack this turn).\"]', 'Gym', '119', 'Rockets Secret Machine', 'Trainer', '', ''),
('gym1-12', '[{\'name\': \'Rebirth\', \'text\': \"When Rocket\'s Moltres is Knocked Out, you may return it to your hand after discarding it. This power can\'t be used if Rocket\'s Moltres is Asleep, Confused, or Paralyzed when it is Knocked Out.\", \'type\': \'Pokémon Power\'}]', '', 'Ken Sugimori', '[{\'name\': \'Fire Wall\', \'cost\': [\'Fire\', \'Fire\', \'Fire\'], \'convertedEnergyCost\': 3, \'damage\': \'40\', \'text\': \"If an attack does damage to Rocket\'s Moltres during your opponent\'s next turn (even if Rocket\'s Moltres is Knocked Out), Rocket\'s Moltres attacks your opponent\'s Active Pokémon for 10 damage. (Apply Weakness and Resistance.)\"}]', 'Gym Heroes', '2', '', '', '', 'First', '60', 'https://images.pokemoncard.io/images/gym1/gym1-12.png', 'unlimited: Legal', '26', 'Rockets Moltres', '146', 'WOTC', 'Rare Holo', '', '8/14/2000', 'type: Fighting, value: -30', 'Colorless, Colorless', '', 'Gym', '12', 'Basic', 'Pokémon', 'Fire', ''),
('gym1-120', '', '', 'Keiji Kinebuchi', '', 'Gym Heroes', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym1/gym1-120.png', 'unlimited: Legal', '', 'Vermilion City Gym', '', 'WOTC', 'Uncommon', '', '8/14/2000', '', '', '[\'This card stays in play when you play it. Discard this card if another Stadium card comes into play.\', \"Whenever a player attacks with a Pokémon with Lt. Surge in its name, he or she may flip a coin. If heads, and if that Pokémon\'s attack does damage to the Defending Pokémon (after applying Weakness and Resistance), that attack does 10 more damage to the Defending Pokémon. If tails, the attacking Pokémon does 10 damage to itself in addition to whatever its attack usually does.\"]', 'Gym', '120', 'Stadium', 'Trainer', '', ''),
('gym1-121', '', '', 'Ken Sugimori', '', 'Gym Heroes', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym1/gym1-121.png', 'unlimited: Legal', '', 'Blaines Gamble', '', 'WOTC', 'Common', '', '8/14/2000', '', '', '[\'Discard any number of other cards from your hand, then flip a coin. If heads, draw twice that many cards.\']', 'Gym', '121', '', 'Trainer', '', ''),
('gym1-122', '', '', 'Keiji Kinebuchi', '', 'Gym Heroes', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym1/gym1-122.png', 'unlimited: Legal', '', 'Energy Flow', '', 'WOTC', 'Common', '', '8/14/2000', '', '', '[\'For each of your Pokémon, you may return any number of Energy cards attached to it to your hand.\']', 'Gym', '122', '', 'Trainer', '', ''),
('gym1-123', '', '', 'Ken Sugimori', '', 'Gym Heroes', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym1/gym1-123.png', 'unlimited: Legal', '', 'Mistys Duel', '', 'WOTC', 'Common', '', '8/14/2000', '', '', '[\"You and your opponent play a game of Rock-Paper-Scissors. The winner shuffles his or her hand into his or her deck and draws a new hand of 5 cards. (If you don\'t know how to play Rock-Paper-Scissors, flip a coin to decide who\'s the winner.)\"]', 'Gym', '123', '', 'Trainer', '', ''),
('gym1-124', '', '', 'Keiji Kinebuchi', '', 'Gym Heroes', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym1/gym1-124.png', 'unlimited: Legal', '', 'Narrow Gym', '', 'WOTC', 'Common', '', '8/14/2000', '', '', '[\'This card stays in play when you play it. Discard this card if another Stadium card comes into play.\', \'No player may have more than 4 Pokémon on his or her Bench. When this card is played, if a player has 5 Pokémon on his or her Bench, that player chooses 1 of them and returns it and all cards attached to it to his or her hand. (If both players have to return a Pokémon, your opponent returns a Pokémon first.)\']', 'Gym', '124', 'Stadium', 'Trainer', '', ''),
('gym1-125', '', '', 'Ken Sugimori', '', 'Gym Heroes', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym1/gym1-125.png', 'unlimited: Legal', '', 'Sabrinas Gaze', '', 'WOTC', 'Common', '', '8/14/2000', '', '', '[\'Each player shuffles his or her hand into his or her deck and draws a new hand of the same number of cards.\']', 'Gym', '125', '', 'Trainer', '', ''),
('gym1-126', '', '', 'Keiji Kinebuchi', '', 'Gym Heroes', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym1/gym1-126.png', 'unlimited: Legal', '', 'Trash Exchange', '', 'WOTC', 'Common', '', '8/14/2000', '', '', '[\'Count the number of cards in your discard pile and shuffle them into your deck. Then discard that many cards from the top of your deck.\']', 'Gym', '126', '', 'Trainer', '', ''),
('gym1-127', '', '', 'Keiji Kinebuchi', '', 'Gym Heroes', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym1/gym1-127.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Fighting Energy', '', 'WOTC', '', '', '8/14/2000', '', '', '', 'Gym', '127', 'Basic', 'Energy', '', ''),
('gym1-128', '', '', 'Keiji Kinebuchi', '', 'Gym Heroes', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym1/gym1-128.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Fire Energy', '', 'WOTC', '', '', '8/14/2000', '', '', '', 'Gym', '128', 'Basic', 'Energy', '', ''),
