('gym1-81', '', '', 'Ken Sugimori', '[{\'name\': \'Charge\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Take 1 Lightning Energy card from your discard pile and attach it to Lt. Surge\'s Pikachu.\"}, {\'name\': \'Lightning Tail\', \'cost\': [\'Lightning\', \'Lightning\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Paralyzed.\'}]', 'Gym Heroes', '1', '', 'Raichu', '', 'First', '50', 'https://images.pokemoncard.io/images/gym1/gym1-81.png', 'unlimited: Legal', '15', 'Lt. Surges Pikachu', '25', 'WOTC', 'Common', '', '8/14/2000', '', 'Colorless', '', 'Gym', '81', 'Basic', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
('gym1-82', '', '', 'Ken Sugimori', '[{\'name\': \'Focus Energy\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"During your next turn, Lt. Surge\'s Rattata\'s Gnaw attack\'s base damage is doubled.\"}, {\'name\': \'Gnaw\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'\'}]', 'Gym Heroes', '1', '', 'Raticate', '', 'First', '40', 'https://images.pokemoncard.io/images/gym1/gym1-82.png', 'unlimited: Legal', '10', 'Lt. Surges Rattata', '19', 'WOTC', 'Common', '', '8/14/2000', 'type: Psychic, value: -30', 'Colorless', '', 'Gym', '82', 'Basic', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('gym1-83', '', '', 'Atsuko Nishida', '[{\'name\': \'Whirlwind\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'If your opponent has any Benched Pokémon, he or she chooses 1 of them and switches it with the Defending Pokémon. (Do the damage before switching the Pokémon.)\'}, {\'name\': \'Razor Wind\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'40\', \'text\': \'Flip a coin. If tails, this attack does nothing.\'}]', 'Gym Heroes', '', '', 'Fearow', '', 'First', '50', 'https://images.pokemoncard.io/images/gym1/gym1-83.png', 'unlimited: Legal', '17', 'Lt. Surges Spearow', '21', 'WOTC', 'Common', '', '8/14/2000', 'type: Fighting, value: -30', '', '', 'Gym', '83', 'Basic', 'Pokémon', 'Colorless', 'type: Lightning, value: ×2'),
('gym1-84', '', '', 'Ken Sugimori', '[{\'name\': \'Spin Ball\', \'cost\': [\'Lightning\'], \'convertedEnergyCost\': 1, \'damage\': \'20×\', \'text\': \'Flip 1 coin. This attack does 20 damage times the number of heads.\'}, {\'name\': \'Double Spin\', \'cost\': [\'Lightning\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20×\', \'text\': \'Flip 2 coins. This attack does 20 damage times the number of heads.\'}]', 'Gym Heroes', '1', '', 'Electrode', '', 'First', '40', 'https://images.pokemoncard.io/images/gym1/gym1-84.png', 'unlimited: Legal', '12', 'Lt. Surges Voltorb', '100', 'WOTC', 'Common', '', '8/14/2000', '', 'Colorless', '', 'Gym', '84', 'Basic', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
('gym1-85', '', '', 'Atsuko Nishida', '[{\'name\': \'Fury Attack\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10×\', \'text\': \'Flip 2 coins. This attack does 10 damage times the number of heads.\'}, {\'name\': \'Supersonic\', \'cost\': [\'Water\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Confused.\'}]', 'Gym Heroes', '1', '', 'Seaking', '', 'First', '40', 'https://images.pokemoncard.io/images/gym1/gym1-85.png', 'unlimited: Legal', '22', 'Mistys Goldeen', '118', 'WOTC', 'Common', '', '8/14/2000', '', 'Colorless', '', 'Gym', '85', 'Basic', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('gym1-86', '', '', 'Ken Sugimori', '[{\'name\': \'Tackle\', \'cost\': [\'Water\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'\'}, {\'name\': \'Smokescreen\', \'cost\': [\'Water\', \'Water\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \"If the Defending Pokémon tries to attack during your opponent\'s next turn, your opponent flips a coin. If tails, that attack does nothing.\"}]', 'Gym Heroes', '', '', 'Seadra', '', 'First', '40', 'https://images.pokemoncard.io/images/gym1/gym1-86.png', 'unlimited: Legal', '10', 'Mistys Horsea', '116', 'WOTC', 'Common', '', '8/14/2000', '', '', '', 'Gym', '86', 'Basic', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('gym1-87', '', '', 'Ken Sugimori', '[{\'name\': \'Hypnotic Stare\', \'cost\': [\'Water\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Paralyzed. If tails, the Defending Pokémon is now Asleep.\'}, {\'name\': \'Tail Rap\', \'cost\': [\'Water\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20×\', \'text\': \'Flip 2 coins. This attack does 20 damage times the number of heads.\'}]', 'Gym Heroes', '1', '', 'Poliwhirl', '', 'First', '50', 'https://images.pokemoncard.io/images/gym1/gym1-87.png', 'unlimited: Legal', '15', 'Mistys Poliwag', '60', 'WOTC', 'Common', '', '8/14/2000', '', 'Colorless', '', 'Gym', '87', 'Basic', 'Pokémon', 'Water', 'type: Grass, value: ×2'),
('gym1-88', '', '', 'Atsuko Nishida', '[{\'name\': \'Aurora Beam\', \'cost\': [\'Water\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'\'}]', 'Gym Heroes', '1', '', 'Dewgong', '', 'First', '60', 'https://images.pokemoncard.io/images/gym1/gym1-88.png', 'unlimited: Legal', '20', 'Mistys Seel', '86', 'WOTC', 'Common', '', '8/14/2000', '', 'Colorless', '', 'Gym', '88', 'Basic', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('gym1-89', '', '', 'Ken Sugimori', '[{\'name\': \'Tackle\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'\'}, {\'name\': \'Clamp\', \'cost\': [\'Water\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Paralyzed. If tails, this attack does nothing (not even damage).\'}]', 'Gym Heroes', '1', '', 'Cloyster', '', 'First', '40', 'https://images.pokemoncard.io/images/gym1/gym1-89.png', 'unlimited: Legal', '10', 'Mistys Shellder', '90', 'WOTC', 'Common', '', '8/14/2000', '', 'Colorless', '', 'Gym', '89', 'Basic', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('gym1-9', '', '', 'Atsuko Nishida', '[{\'name\': \'Tail Snap\', \'cost\': [\'Water\'], \'convertedEnergyCost\': 1, \'damage\': \'20\', \'text\': \'\'}, {\'name\': \'Knockout Needle\', \'cost\': [\'Water\', \'Water\', \'Water\'], \'convertedEnergyCost\': 3, \'damage\': \'30+\', \'text\': \'Flip 2 coins. If both of them are heads, this attack does 30 damage plus 60 more damage. If 1 or both of them are tails, this attack does 30 damage.\'}]', 'Gym Heroes', '1', 'Mistys Horsea', 'Kingdra', '', 'First', '70', 'https://images.pokemoncard.io/images/gym1/gym1-9.png', 'unlimited: Legal', '30', 'Mistys Seadra', '117', 'WOTC', 'Rare Holo', '', '8/14/2000', '', 'Colorless', '', 'Gym', '9', 'Stage 1', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('gym1-90', '', '', 'Ken Sugimori', '[{\'name\': \'Swift\', \'cost\': [\'Water\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \"This attack\'s damage isn\'t affected by Weakness, Resistance, Pokémon Powers, or any other effects on the Defending Pokémon.\"}]', 'Gym Heroes', '1', '', 'Starmie', '', 'First', '50', 'https://images.pokemoncard.io/images/gym1/gym1-90.png', 'unlimited: Legal', '20', 'Mistys Staryu', '120', 'WOTC', 'Common', '', '8/14/2000', '', 'Colorless', '', 'Gym', '90', 'Basic', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('gym1-91', '', '', 'Ken Sugimori', '[{\'name\': \'Energy Loop\', \'cost\': [\'Psychic\'], \'convertedEnergyCost\': 1, \'damage\': \'20\', \'text\': \"Return a Psychic Energy card attached to Sabrina\'s Abra to your hand in order to use this attack.\"}]', 'Gym Heroes', '', '', 'Kadabra', '', 'First', '40', 'https://images.pokemoncard.io/images/gym1/gym1-91.png', 'unlimited: Legal', '11', 'Sabrinas Abra', '63', 'WOTC', 'Common', '', '8/14/2000', '', '', '', 'Gym', '91', 'Basic', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2'),
('gym1-92', '', '', 'Atsuko Nishida', '[{\'name\': \'Suggestion\', \'cost\': [\'Psychic\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Flip a coin. If heads, the Defending Pokémon can\'t attack during your opponent\'s next turn.\"}, {\'name\': \'Headbutt\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'\'}]', 'Gym Heroes', '1', '', 'Hypno', '', 'First', '50', 'https://images.pokemoncard.io/images/gym1/gym1-92.png', 'unlimited: Legal', '15', 'Sabrinas Drowzee', '96', 'WOTC', 'Common', '', '8/14/2000', '', 'Colorless', '', 'Gym', '92', 'Basic', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2'),
('gym1-93', '', '', 'Ken Sugimori', '[{\'name\': \'Spook\', \'cost\': [\'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \"The Defending Pokémon can\'t retreat during your opponent\'s next turn.\"}]', 'Gym Heroes', '1', '', 'Haunter', '', 'First', '50', 'https://images.pokemoncard.io/images/gym1/gym1-93.png', 'unlimited: Legal', '16', 'Sabrinas Gastly', '92', 'WOTC', 'Common', '', '8/14/2000', 'type: Fighting, value: -30', 'Colorless', '', 'Gym', '93', 'Basic', 'Pokémon', 'Psychic', ''),
('gym1-94', '', '', 'Ken Sugimori', '[{\'name\': \'Sleight of Hand\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Choose up to 3 cards from your hand and put them on top of your deck. Then search your deck for that many basic Energy cards. Show those cards to your opponent, then put them into your hand. Shuffle your deck afterward.\'}, {\'name\': \'Slap\', \'cost\': [\'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'\'}]', 'Gym Heroes', '1', '', '', '', 'First', '50', 'https://images.pokemoncard.io/images/gym1/gym1-94.png', 'unlimited: Legal', '20', 'Sabrinas Mr. Mime', '122', 'WOTC', 'Common', '', '8/14/2000', '', 'Colorless', '', 'Gym', '94', 'Basic', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2'),
('gym1-95', '', '', 'Ken Sugimori', '[{\'name\': \'Lazy Attack\', \'cost\': [\'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \"Sabrina\'s Slowpoke is now Asleep (after doing damage).\"}]', 'Gym Heroes', '1', '', 'Slowbro, Slowking', '', 'First', '50', 'https://images.pokemoncard.io/images/gym1/gym1-95.png', 'unlimited: Legal', '15', 'Sabrinas Slowpoke', '79', 'WOTC', 'Common', '', '8/14/2000', '', 'Colorless', '', 'Gym', '95', 'Basic', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2'),
('gym1-96', '', '', 'Ken Sugimori', '[{\'name\': \'Poison Antennae\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'The Defending Pokémon is now Poisoned.\'}, {\'name\': \'Removal Beam\', \'cost\': [\'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'If the Defending Pokémon has any Energy cards attached to it, flip a coin. If heads, choose 1 of those Energy cards and discard it.\'}]', 'Gym Heroes', '1', '', 'Venomoth', '', 'First', '40', 'https://images.pokemoncard.io/images/gym1/gym1-96.png', 'unlimited: Legal', '13', 'Sabrinas Venonat', '48', 'WOTC', 'Common', '', '8/14/2000', '', 'Colorless', '', 'Gym', '96', 'Basic', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('gym1-97', '', '', 'Ken Sugimori', '', 'Gym Heroes', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym1/gym1-97.png', 'unlimited: Legal', '', 'Blaines Quiz #1', '', 'WOTC', 'Rare', '', '8/14/2000', '', '', '[\'Put a Basic Pokémon or Evolution card from your hand face down in front of you and tell your opponent its name. Your opponent guesses the length of that Pokémon. Flip the card over. If your opponent guessed right, he or she draws 2 cards. If your opponent guessed wrong, you draw 2 cards. Either way, return the card to your hand.\']', 'Gym', '97', '', 'Trainer', '', ''),
('gym1-98', '', '', 'Ken Sugimori', '', 'Gym Heroes', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym1/gym1-98.png', 'unlimited: Legal', '', 'Brock', '', 'WOTC', 'Rare', '', '8/14/2000', '', '', '[\'Remove 1 damage counter from each of your Pokémon that has any damage counters on it.\']', 'Gym', '98', '', 'Trainer', '', ''),
('gym1-99', '', '', 'Ken Sugimori', '', 'Gym Heroes', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym1/gym1-99.png', 'unlimited: Legal', '', 'Charity', '', 'WOTC', 'Rare', '', '8/14/2000', '', '', '[\'Attach Charity to your Active Pokémon. Unless that Pokémon gets Knocked Out, return Charity to your hand at the end of your turn. If that Pokémon attacks and does damage to the Defending Pokémon, you may reduce that damage by any amount (rounded to the nearest 10).\']', 'Gym', '99', '', 'Trainer', '', ''),
('gym2-1', '', '', 'Ken Sugimori', '[{\'name\': \'Heat Tackle\', \'cost\': [\'Fire\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40\', \'text\': \"Blaine\'s Arcanine does 10 damage to itself.\"}, {\'name\': \'Firestorm\', \'cost\': [\'Fire\', \'Fire\', \'Fire\', \'Fire\'], \'convertedEnergyCost\': 4, \'damage\': \'120\', \'text\': \"Discard 3 Fire Energy cards attached to Blaine\'s Arcanine in order to use this attack.\"}]', 'Gym Challenge', '3', 'Blaines Growlithe', '', '', 'First', '90', 'https://images.pokemoncard.io/images/gym2/gym2-1.png', 'unlimited: Legal', '42', 'Blaines Arcanine', '59', 'WOTC', 'Rare Holo', '', '10/16/2000', '', 'Colorless, Colorless, Colorless', '', 'Gym', '1', 'Stage 1', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('gym2-10', '', '', 'Ken Sugimori', '[{\'name\': \'Giant Growth\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Flip a coin. If heads, Koga\'s Ditto\'s maximum HP is now 80 and Koga\'s Ditto\'s Pound attack\'s base damage is 30 instead of 10. (Benching Koga\'s Ditto ends this effect.)\"}, {\'name\': \'Pound\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'\'}]', 'Gym Challenge', '1', '', '', '', 'First', '40', 'https://images.pokemoncard.io/images/gym2/gym2-10.png', 'unlimited: Legal', '12', 'Kogas Ditto', '132', 'WOTC', 'Rare Holo', '', '10/16/2000', 'type: Psychic, value: -30', 'Colorless', '', 'Gym', '10', 'Basic', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2');
INSERT INTO `cards` (`id`, `abilities`, `ancient_trait`, `artist`, `attacks`, `card_set`, `converted`, `evolves_from`, `evolves_to`, `flavor_text`, `generation`, `hp`, `img`, `legalities`, `level`, `name`, `national_pokedex_numbers`, `publisher`, `rarity`, `regulation_mark`, `release_date`, `resistances`, `retreat_cost`, `rules`, `series`, `set_num`, `subtypes`, `supertype`, `types`, `weakness`) VALUES
('gym2-100', '', '', 'Ken Sugimori', '', 'Gym Challenge', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym2/gym2-100.png', 'unlimited: Legal', '', 'Blaine', '', 'WOTC', 'Rare', '', '10/16/2000', '', '', '[\'During this turn, instead of attaching your free Energy card, you may instead attach 2 Fire Energy cards to 1 of your Pokémon with Blaine in its name. (Playing additional copies of this card this turn has no effect.)\']', 'Gym', '100', '', 'Trainer', '', ''),
('gym2-101', '', '', 'Ken Sugimori', '', 'Gym Challenge', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym2/gym2-101.png', 'unlimited: Legal', '', 'Brocks Protection', '', 'WOTC', 'Rare', '', '10/16/2000', '', '', '[\"Attach Brock\'s Protection to 1 of your Pokémon with Brock in its name. Energy cards attached to that Pokémon can\'t be removed by your opponent\'s attacks or Trainer cards. (This doesn\'t stop the rest of the attack or Trainer card from working normally.)\"]', 'Gym', '101', '', 'Trainer', '', ''),
('gym2-102', '', '', 'Keiji Kinebuchi', '', 'Gym Challenge', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym2/gym2-102.png', 'unlimited: Legal', '', 'Chaos Gym', '', 'WOTC', 'Rare', '', '10/16/2000', '', '', '[\'This card stays in play after being played. Discard this card if another Stadium card comes into play.\', \"Whenever a player plays a Trainer card other than a Stadium card, he or she flips a coin. If heads, that player plays that card normally. If tails, the player can\'t play that card. If the card isn\'t put into play, the player\'s opponent may use that card instead, if he or she does everything required in order to play that card (like discarding cards). Either way, the card goes to its owner\'s discard pile.\"]', 'Gym', '102', 'Stadium', 'Trainer', '', ''),
('gym2-103', '', '', 'Ken Sugimori', '', 'Gym Challenge', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym2/gym2-103.png', 'unlimited: Legal', '', 'Erikas Kindness', '', 'WOTC', 'Rare', '', '10/16/2000', '', '', '[\"Remove 2 damage counters from each Pokémon (yours and your opponent\'s) with any damage counters on it. If a Pokémon has just 1 damage counter, remove it.\"]', 'Gym', '103', '', 'Trainer', '', ''),
('gym2-104', '', '', 'Ken Sugimori', '', 'Gym Challenge', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym2/gym2-104.png', 'unlimited: Legal', '', 'Giovanni', '', 'WOTC', 'Rare', '', '10/16/2000', '', '', '[\'Choose 1 of your Pokémon in play with Giovanni in its name. For the rest of your turn, you may evolve that Pokémon even if you just played or evolved it this turn or if this is your first turn. This effect also applies to the Pokémon it evolves into.\']', 'Gym', '104', '', 'Trainer', '', ''),
('gym2-105', '', '', 'Ken Sugimori', '', 'Gym Challenge', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym2/gym2-105.png', 'unlimited: Legal', '', 'Giovannis Last Resort', '', 'WOTC', 'Rare', '', '10/16/2000', '', '', '[\'Remove all damage counters from 1 of your Pokémon with Giovanni in its name. Then discard your hand.\']', 'Gym', '105', '', 'Trainer', '', ''),
('gym2-106', '', '', 'Ken Sugimori', '', 'Gym Challenge', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym2/gym2-106.png', 'unlimited: Legal', '', 'Koga', '', 'WOTC', 'Rare', '', '10/16/2000', '', '', '[\'If an attack from a Pokémon with Koga in its name does damage to a Defending Pokémon this turn, that Pokémon is then Poisoned.\']', 'Gym', '106', '', 'Trainer', '', ''),
('gym2-107', '', '', 'Ken Sugimori', '', 'Gym Challenge', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym2/gym2-107.png', 'unlimited: Legal', '', 'Lt. Surges Secret Plan', '', 'WOTC', 'Rare', '', '10/16/2000', '', '', '[\"Put 1 card from your hand face down onto your Bench. (You can\'t play this card if your Bench is full.) Treat that card as a Basic Pokémon as long as it\'s face down. Flip the card if either player needs to know what it is in order to use an attack, a Pokémon Power, or a Trainer card. Flip the card if it ever uses an attack or Pokémon Power, evolves, retreats, is damaged by an attack, or is otherwise affected by an attack. At any time during your turn, you may flip the card over. When you flip that card over, if it isn\'t a Basic Pokémon, discard it and all cards attached to it.\"]', 'Gym', '107', '', 'Trainer', '', ''),
('gym2-108', '', '', 'Ken Sugimori', '', 'Gym Challenge', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym2/gym2-108.png', 'unlimited: Legal', '', 'Mistys Wish', '', 'WOTC', 'Rare', '', '10/16/2000', '', '', '[\'Look at 1 of your Prize cards. Then, ask your opponent if you may switch that card with 1 of the cards in your hand. If your opponent accepts and if you have any other cards in your hand, switch those cards. If your opponent declines, return the Prize card face down and draw a card.\']', 'Gym', '108', '', 'Trainer', '', ''),
('gym2-109', '', '', 'Keiji Kinebuchi', '', 'Gym Challenge', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym2/gym2-109.png', 'unlimited: Legal', '', 'Resistance Gym', '', 'WOTC', 'Rare', '', '10/16/2000', '', '', '[\'This card stays in play after being played. Discard this card if another Stadium card comes into play.\', \"Each Pokémon\'s Resistance is reduced by 20. (If a Pokémon\'s Resistance is -30, it becomes -10.)\"]', 'Gym', '109', 'Stadium', 'Trainer', '', ''),
('gym2-11', '', '', 'Ken Sugimori', '[{\'name\': \'Kerzap\', \'cost\': [\'Lightning\', \'Lightning\'], \'convertedEnergyCost\': 2, \'damage\': \'20+\', \'text\': \"Flip a coin. If heads, this attack does 20 damage plus 30 more damage to the Defending Pokémon and discard all Lightning Energy cards attached to Lt. Surge\'s Raichu. If tails, this attack does 20 damage.\"}, {\'name\': \'Thundertackle\', \'cost\': [\'Lightning\', \'Lightning\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'40\', \'text\': \"Flip a coin. If heads, the Defending Pokémon is now Paralyzed. If tails, Lt. Surge\'s Raichu does 20 damage to itself.\"}]', 'Gym Challenge', '2', 'Lt. Surges Pikachu', '', '', 'First', '80', 'https://images.pokemoncard.io/images/gym2/gym2-11.png', 'unlimited: Legal', '38', 'Lt. Surges Raichu', '26', 'WOTC', 'Rare Holo', '', '10/16/2000', '', 'Colorless, Colorless', '', 'Gym', '11', 'Stage 1', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
('gym2-110', '', '', 'Ken Sugimori', '', 'Gym Challenge', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym2/gym2-110.png', 'unlimited: Legal', '', 'Sabrina', '', 'WOTC', 'Rare', '', '10/16/2000', '', '', '[\'Take all Energy cards attached to 1 of your Pokémon with Sabrina in its name and attach them to another 1 of your Pokémon with Sabrina in its name.\']', 'Gym', '110', '', 'Trainer', '', ''),
('gym2-111', '', '', 'Ken Sugimori', '', 'Gym Challenge', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym2/gym2-111.png', 'unlimited: Legal', '', 'Blaines Quiz #2', '', 'WOTC', 'Uncommon', '', '10/16/2000', '', '', '[\'Put a card from your hand face down in front of you. Your opponent guesses whether it is an Energy card, a Trainer card, or a Pokémon (Basic or Evolution) card. Flip the card over. If your opponent guessed right, he or she draws 2 cards. If your opponent guessed wrong, you draw 2 cards. Either way, return the card to your hand.\']', 'Gym', '111', '', 'Trainer', '', ''),
('gym2-112', '', '', 'Ken Sugimori', '', 'Gym Challenge', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym2/gym2-112.png', 'unlimited: Legal', '', 'Blaines Quiz #3', '', 'WOTC', 'Uncommon', '', '10/16/2000', '', '', '[\'Put a Basic or Evolution card from your hand face down in front of you and tell your opponent the name of an attack of that card. Your opponent guesses the name of that card. Flip the card over. If your opponent guessed right, he or she draws 3 cards. If your opponent guessed wrong, you draw 3 cards. Either way, return the card to your hand.\']', 'Gym', '112', '', 'Trainer', '', ''),
('gym2-113', '', '', 'Keiji Kinebuchi', '', 'Gym Challenge', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym2/gym2-113.png', 'unlimited: Legal', '', 'Cinnabar City Gym', '', 'WOTC', 'Uncommon', '', '10/16/2000', '', '', '[\'This card stays in play after being played. Discard this card if another Stadium card comes into play.\', \'Ignore Weakness when a Water Pokémon does damage to a Pokémon with Blaine in its name.\']', 'Gym', '113', 'Stadium', 'Trainer', '', ''),
('gym2-114', '', '', 'Keiji Kinebuchi', '', 'Gym Challenge', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym2/gym2-114.png', 'unlimited: Legal', '', 'Fuchsia City Gym', '', 'WOTC', 'Uncommon', '', '10/16/2000', '', '', '[\'This card stays in play after being played. Discard this card if another Stadium card comes into play.\', \"Once during each player\'s turn (before attacking), that player may flip a coin. If heads, that player may shuffle 1 of his or her Pokémon in play with Koga in its name and any cards attached to it into his or her deck.\"]', 'Gym', '114', 'Stadium', 'Trainer', '', ''),
('gym2-115', '', '', 'Sumiyoshi Kizuki', '', 'Gym Challenge', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym2/gym2-115.png', 'unlimited: Legal', '', 'Kogas Ninja Trick', '', 'WOTC', 'Uncommon', '', '10/16/2000', '', '', '[\"Attach Koga\'s Ninja Trick to your Active Pokémon with Koga in its name. If this Pokémon goes to your Bench, discard this card. When your opponent attacks, you may switch this Pokémon with 1 of your Benched Pokémon (before damage or other effects of attacks).\"]', 'Gym', '115', '', 'Trainer', '', ''),
('gym2-116', '', '', 'Keiji Kinebuchi', '', 'Gym Challenge', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym2/gym2-116.png', 'unlimited: Legal', '', 'Master Ball', '', 'WOTC', 'Uncommon', '', '10/16/2000', '', '', '[\'Look at 7 cards from the top of your deck. You may choose a Basic Pokémon or Evolution card from those cards, show it to your opponent, then put it into your hand. Shuffle the rest into your deck.\']', 'Gym', '116', '', 'Trainer', '', ''),
('gym2-117', '', '', 'Hikaru Koike', '', 'Gym Challenge', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym2/gym2-117.png', 'unlimited: Legal', '', 'Max Revive', '', 'WOTC', 'Uncommon', '', '10/16/2000', '', '', '[\"Discard 2 Energy cards from your hand in order to put 1 Basic Pokémon from your discard pile onto your Bench. (You can\'t play Max Revive if your Bench is full.)\"]', 'Gym', '117', '', 'Trainer', '', ''),
('gym2-118', '', '', 'Ken Sugimori', '', 'Gym Challenge', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym2/gym2-118.png', 'unlimited: Legal', '', 'Mistys Tears', '', 'WOTC', 'Uncommon', '', '10/16/2000', '', '', '[\'Discard 1 of the other cards in your hand in order to search your deck for up to 2 Water Energy cards. Show those cards to your opponent, then put them into your hand. Shuffle your deck afterward.\']', 'Gym', '118', '', 'Trainer', '', ''),
('gym2-119', '', '', 'Keiji Kinebuchi', '', 'Gym Challenge', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym2/gym2-119.png', 'unlimited: Legal', '', 'Rockets Minefield Gym', '', 'WOTC', 'Uncommon', '', '10/16/2000', '', '', '[\'This card stays in play after being played. Discard this card if another Stadium card comes into play.\', \'Whenever a player puts a Basic Pokémon onto his or her Bench from his or her hand, he or she flips a coin. If tails, put damage counters on that Pokémon.\']', 'Gym', '119', 'Stadium', 'Trainer', '', ''),
('gym2-12', '', '', 'Ken Sugimori', '[{\'name\': \'Electro Beam\', \'cost\': [\'Water\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'40\', \'text\': \"Flip a coin. If tails, discard all Energy cards attached to Misty\'s Golduck.\"}, {\'name\': \'Super Removal\', \'cost\': [\'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'\', \'text\': \"Flip a coin. If heads, choose 1 Energy card attached to each of your opponent\'s Pokémon that has any Energy cards and discard those Energy cards.\"}]', 'Gym Challenge', '1', 'Mistys Psyduck', '', '', 'First', '70', 'https://images.pokemoncard.io/images/gym2/gym2-12.png', 'unlimited: Legal', '32', 'Mistys Golduck', '55', 'WOTC', 'Rare Holo', '', '10/16/2000', '', 'Colorless', '', 'Gym', '12', 'Stage 1', 'Pokémon', 'Water', 'type: Grass, value: ×2'),
('gym2-120', '', '', 'Ken Sugimori', '', 'Gym Challenge', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym2/gym2-120.png', 'unlimited: Legal', '', 'Rockets Secret Experiment', '', 'WOTC', 'Uncommon', '', '10/16/2000', '', '', '[\"Flip a coin. If heads, search your deck for any card and put it into your hand. Shuffle your deck afterward. If tails, you can\'t play Trainer cards until the end of your next turn.\"]', 'Gym', '120', '', 'Trainer', '', ''),
('gym2-121', '', '', 'Ken Sugimori', '', 'Gym Challenge', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym2/gym2-121.png', 'unlimited: Legal', '', 'Sabrinas Psychic Control', '', 'WOTC', 'Uncommon', '', '10/16/2000', '', '', '[\"Flip a coin. If heads, choose a Trainer card in your opponent\'s discard pile that isn\'t put in play (like PlusPower or Mysterious Fossil). You may use that card as if it were in your hand, if you do everything required in order to play that card (like discarding cards). The card stays in your opponent\'s discard pile.\"]', 'Gym', '121', '', 'Trainer', '', ''),
('gym2-122', '', '', 'Keiji Kinebuchi', '', 'Gym Challenge', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym2/gym2-122.png', 'unlimited: Legal', '', 'Saffron City Gym', '', 'WOTC', 'Uncommon', '', '10/16/2000', '', '', '[\'This card stays in play after being played. Discard this card if another Stadium card comes into play.\', \'As often as each player like during his or her turn (before attacking), that player may return 1 basic Energy card attached to 1 of his or her Pokémon with Sabrina in its name to his or her hand.\']', 'Gym', '122', 'Stadium', 'Trainer', '', ''),
('gym2-123', '', '', 'Keiji Kinebuchi', '', 'Gym Challenge', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym2/gym2-123.png', 'unlimited: Legal', '', 'Viridian City Gym', '', 'WOTC', 'Uncommon', '', '10/16/2000', '', '', '[\'This card stays in play after being played. Discard this card if another Stadium card comes into play.\', \'Whenever a Pokémon with Giovanni in its name evolves, its owner removes 2 damage counters from that Pokémon (or 1 if it only has 1).\']', 'Gym', '123', 'Stadium', 'Trainer', '', ''),
('gym2-124', '', '', 'Ken Sugimori', '', 'Gym Challenge', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym2/gym2-124.png', 'unlimited: Legal', '', 'Fervor', '', 'WOTC', 'Common', '', '10/16/2000', '', '', '[\'Show the top 3 cards of your deck to all players. Put any Fire Energy cards there into your hand and discard the rest.\']', 'Gym', '124', '', 'Trainer', '', ''),
('gym2-125', '', '', 'Keiji Kinebuchi', '', 'Gym Challenge', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym2/gym2-125.png', 'unlimited: Legal', '', 'Transparent Walls', '', 'WOTC', 'Common', '', '10/16/2000', '', '', '[\"Until the end of your opponent\'s next turn, prevent all damage from attacks done to your Benched Pokémon. (Any other effects of attacks still happen.)\"]', 'Gym', '125', '', 'Trainer', '', ''),
('gym2-126', '', '', 'Keiji Kinebuchi', '', 'Gym Challenge', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym2/gym2-126.png', 'unlimited: Legal', '', 'Warp Point', '', 'WOTC', 'Common', '', '10/16/2000', '', '', '[\'If your opponent has any Benched Pokémon, he or she chooses 1 of them and switches it with his or her Active Pokémon, then, if you have any Benched Pokémon, you switch 1 of them with your Active Pokémon.\']', 'Gym', '126', '', 'Trainer', '', ''),
('gym2-127', '', '', 'Keiji Kinebuchi', '', 'Gym Challenge', '', '', '', '', 'First', '', 'https://images.pokemoncard.io/images/gym2/gym2-127.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Fighting Energy', '', 'WOTC', '', '', '10/16/2000', '', '', '', 'Gym', '127', 'Basic', 'Energy', '', ''),
