('gym2-48', '', '', 'Ken Sugimori', '[{\'name\': \'Smokescreen\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \"If the Defending Pokémon tries to attack during your opponent\'s next turn, your opponent flips a coin. If tails, that attack does nothing.\"}, {\'name\': \'Obscuring Gas\', \'cost\': [\'Grass\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \"Flip a coin. If heads, shuffle Koga\'s Koffing and all cards attached to it into your deck (after doing damage).\"}]', 'Gym Challenge', '1', '', 'Weezing', '', 'First', '50', 'https://images.pokemoncard.io/images/gym2/gym2-48.png', 'unlimited: Legal', '15', 'Kogas Koffing', '109', 'WOTC', 'Uncommon', '', '10/16/2000', '', 'Colorless', '', 'Gym', '48', 'Basic', 'Pokémon', 'Grass', 'type: Psychic, value: ×2'),
('gym2-49', '', '', 'Atsuko Nishida', '[{\'name\': \'Messenger\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Put Koga\'s Pidgey and all cards attached to it on top of your deck. Then search your deck for any Basic Pokémon or Evolution card not named Koga\'s Pidgey. Show that card to your opponent, then put it into your hand. Shuffle your deck afterward.\"}, {\'name\': \'Wing Attack\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'\'}]', 'Gym Challenge', '1', '', 'Pidgeotto', '', 'First', '40', 'https://images.pokemoncard.io/images/gym2/gym2-49.png', 'unlimited: Legal', '9', 'Kogas Pidgey', '16', 'WOTC', 'Uncommon', '', '10/16/2000', 'type: Fighting, value: -30', 'Colorless', '', 'Gym', '49', 'Basic', 'Pokémon', 'Colorless', 'type: Lightning, value: ×2'),
('gym2-5', '', '', 'Ken Sugimori', '[{\'name\': \'Summon Storm\', \'cost\': [\'Water\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Flip 2 coins. If both of them are heads, this attack does 20 damage to each other Pokémon (even your own). Don\'t apply Weakness and Resistance for this attack.\"}, {\'name\': \'Dragon Tornado\', \'cost\': [\'Water\', \'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'40\', \'text\': \"Unless this attack Knocks Out the Defending Pokémon, choose 1 of your opponent\'s Benched Pokémon and switch it with the Defending Pokémon.\"}]', 'Gym Challenge', '3', 'Giovannis Magikarp', '', '', 'First', '90', 'https://images.pokemoncard.io/images/gym2/gym2-5.png', 'unlimited: Legal', '40', 'Giovannis Gyarados', '130', 'WOTC', 'Rare Holo', '', '10/16/2000', 'type: Fighting, value: -30', 'Colorless, Colorless, Colorless', '', 'Gym', '5', 'Stage 1', 'Pokémon', 'Water', 'type: Grass, value: ×2'),
('gym2-50', '', '', 'Ken Sugimori', '[{\'name\': \'Spontaneous Explosion\', \'cost\': [\'Grass\', \'Grass\'], \'convertedEnergyCost\': 2, \'damage\': \'10+\', \'text\': \"Flip a coin. If heads, this attack does 10 damage plus 30 more damage and Koga\'s Weezing does 30 damage to itself; if tails, this attack does 10 damage.\"}, {\'name\': \'Toxic Cloud\', \'cost\': [\'Grass\', \'Grass\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'20\', \'text\': \"Flip a coin. If heads, this Defending Pokémon is now Poisoned. It now takes 20 Poison damage instead of 10 after each player\'s turn (even if it was already Poisoned).\"}]', 'Gym Challenge', '2', 'Kogas Koffing', '', '', 'First', '70', 'https://images.pokemoncard.io/images/gym2/gym2-50.png', 'unlimited: Legal', '31', 'Kogas Weezing', '110', 'WOTC', 'Uncommon', '', '10/16/2000', '', 'Colorless, Colorless', '', 'Gym', '50', 'Stage 1', 'Pokémon', 'Grass', 'type: Psychic, value: ×2'),
('gym2-51', '', '', 'Ken Sugimori', '[{\'name\': \'Surprise\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Look at a random card from your opponent\'s hand. Your opponent shuffles that card into his or her deck.\"}, {\'name\': \'Scratch\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'\'}]', 'Gym Challenge', '1', '', 'Vaporeon, Jolteon, Flareon, Sylveon, Espeon, Umbreon, Leafeon, Glaceon', '', 'First', '40', 'https://images.pokemoncard.io/images/gym2/gym2-51.png', 'unlimited: Legal', '10', 'Lt. Surges Eevee', '133', 'WOTC', 'Uncommon', '', '10/16/2000', 'type: Psychic, value: -30', 'Colorless', '', 'Gym', '51', 'Basic', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('gym2-52', '[{\'name\': \'Shock Blast\', \'text\': \"If Lt. Surge\'s Electrode is your Active Pokémon and gets damaged (even if it\'s Knocked Out), flip a coin. If tails, this power does 20 damage to each Active Pokémon. This power works even if Lt. Surge\'s Electrode is already Asleep, Confused, or Paralyzed when it takes damage.\", \'type\': \'Pokémon Power\'}]', '', 'Ken Sugimori', '[{\'name\': \'Power Ball\', \'cost\': [\'Lightning\', \'Lightning\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'30+\', \'text\': \'Flip 3 coins. This attack does 30 damage plus 10 more damage for each heads.\'}]', 'Gym Challenge', '2', 'Lt. Surges Voltorb', '', '', 'First', '70', 'https://images.pokemoncard.io/images/gym2/gym2-52.png', 'unlimited: Legal', '33', 'Lt. Surges Electrode', '101', 'WOTC', 'Uncommon', '', '10/16/2000', '', 'Colorless, Colorless', '', 'Gym', '52', 'Stage 1', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
('gym2-53', '', '', 'Ken Sugimori', '[{\'name\': \'Focus Energy\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"During your next turn, Lt. Surge\'s Raticate\'s Double-edge attack\'s damage (base damage and damage to itself) is doubled.\"}, {\'name\': \'Double-edge\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'40\', \'text\': \"Lt. Surge\'s Raticate does 20 damage to itself.\"}]', 'Gym Challenge', '1', 'Lt. Surges Rattata', '', '', 'First', '60', 'https://images.pokemoncard.io/images/gym2/gym2-53.png', 'unlimited: Legal', '33', 'Lt. Surges Raticate', '20', 'WOTC', 'Uncommon', '', '10/16/2000', 'type: Psychic, value: -30', 'Colorless', '', 'Gym', '53', 'Stage 1', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('gym2-54', '', '', 'Ken Sugimori', '[{\'name\': \'Ice Throw\', \'cost\': [\'Water\', \'Water\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \"If the Defending Pokémon is Fighting, this attack\'s base damage is doubled.\"}, {\'name\': \'Take Down\', \'cost\': [\'Water\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'60\', \'text\': \"Misty\'s Dewgong does 20 damage to itself.\"}]', 'Gym Challenge', '2', 'Mistys Seel', '', '', 'First', '80', 'https://images.pokemoncard.io/images/gym2/gym2-54.png', 'unlimited: Legal', '40', 'Mistys Dewgong', '87', 'WOTC', 'Uncommon', '', '10/16/2000', '', 'Colorless, Colorless', '', 'Gym', '54', 'Stage 1', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('gym2-55', '', '', 'Ken Sugimori', '[{\'name\': \'Nightmare\', \'cost\': [\'Psychic\', \'Psychic\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'The Defending Pokémon is now Asleep.\'}, {\'name\': \'Shadow Attack\', \'cost\': [\'Psychic\', \'Psychic\', \'Psychic\'], \'convertedEnergyCost\': 3, \'damage\': \'\', \'text\': \"Flip a coin. If heads, and if your opponent has any Benched Pokémon, choose 1 of them and this attack does 30 damage to it. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'Gym Challenge', '', 'Sabrinas Gastly', 'Gengar', '', 'First', '70', 'https://images.pokemoncard.io/images/gym2/gym2-55.png', 'unlimited: Legal', '29', 'Sabrinas Haunter', '93', 'WOTC', 'Uncommon', '', '10/16/2000', 'type: Fighting, value: -30', '', '', 'Gym', '55', 'Stage 1', 'Pokémon', 'Psychic', ''),
('gym2-56', '', '', 'Ken Sugimori', '[{\'name\': \'Invigorate\', \'cost\': [\'Psychic\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Choose 1 Basic Pokémon in any player\'s discard pile. Put it onto that player\'s Bench. Put a number of damage counters on that Pokémon equal to half its HP (rounded down to the nearest 10). (You can\'t put a Pokémon on a Bench that\'s full.)\"}, {\'name\': \'Pendulum Curse\', \'cost\': [\'Psychic\', \'Psychic\'], \'convertedEnergyCost\': 2, \'damage\': \'20×\', \'text\': \'Flip a number of coins equal to the number of damage counters on the Defending Pokémon. This attack does 20 damage times the number of heads.\'}]', 'Gym Challenge', '2', 'Sabrinas Drowzee', '', '', 'First', '70', 'https://images.pokemoncard.io/images/gym2/gym2-56.png', 'unlimited: Legal', '31', 'Sabrinas Hypno', '97', 'WOTC', 'Uncommon', '', '10/16/2000', '', 'Colorless, Colorless', '', 'Gym', '56', 'Stage 1', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2'),
('gym2-57', '', '', 'Atsuko Nishida', '[{\'name\': \'Helping Hand\', \'cost\': [\'Psychic\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Choose 1 of your opponent\'s Pokémon. Remove any number of damage counters from that Pokémon, then draw that many cards.\"}, {\'name\': \'Hug\', \'cost\': [\'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \"Flip a coin. If heads, the Defending Pokémon can\'t retreat during your opponent\'s next turn.\"}]', 'Gym Challenge', '1', '', '', '', 'First', '60', 'https://images.pokemoncard.io/images/gym2/gym2-57.png', 'unlimited: Legal', '21', 'Sabrinas Jynx', '124', 'WOTC', 'Uncommon', '', '10/16/2000', '', 'Colorless', '', 'Gym', '57', 'Basic', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2'),
('gym2-58', '', '', 'Ken Sugimori', '[{\'name\': \'Life Drain\', \'cost\': [\'Psychic\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Flip a coin. If heads, put a number of damage counters on the Defending Pokémon so that its remaining HP are 10.\'}, {\'name\': \'Psyshot\', \'cost\': [\'Psychic\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'30\', \'text\': \'\'}]', 'Gym Challenge', '1', 'Sabrinas Abra', 'Alakazam', '', 'First', '70', 'https://images.pokemoncard.io/images/gym2/gym2-58.png', 'unlimited: Legal', '41', 'Sabrinas Kadabra', '64', 'WOTC', 'Uncommon', '', '10/16/2000', '', 'Colorless', '', 'Gym', '58', 'Stage 1', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2'),
('gym2-59', '', '', 'Ken Sugimori', '[{\'name\': \'Magic Darts\', \'cost\': [\'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'\', \'text\': \"Choose 1 of your opponent\'s Pokémon and flip 3 coins. This attack does 10 damage times the number of heads to that Pokémon. Don\'t apply Weakness and Resistance for this attack.\"}]', 'Gym Challenge', '1', '', '', '', 'First', '60', 'https://images.pokemoncard.io/images/gym2/gym2-59.png', 'unlimited: Legal', '30', 'Sabrinas Mr. Mime', '122', 'WOTC', 'Uncommon', '', '10/16/2000', '', 'Colorless', '', 'Gym', '59', 'Basic', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2'),
('gym2-6', '[{\'name\': \'Fortitude\', \'text\': \"If Giovanni\'s Machamp would be Knocked Out by an opponent\'s attack, flip a coin. If heads, Giovanni\'s Machamp is not Knocked Out and its remaining HP become 10 instead. This power can\'t be used if Giovanni\'s Machamp is already Asleep, Confused, or Paralyzed.\", \'type\': \'Pokémon Power\'}]', '', 'Ken Sugimori', '[{\'name\': \'Hurricane Punch\', \'cost\': [\'Fighting\', \'Fighting\', \'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'30×\', \'text\': \'Flip 4 coins. This attack does 30 damage times the number of heads.\'}]', 'Gym Challenge', '3', 'Giovannis Machoke', '', '', 'First', '100', 'https://images.pokemoncard.io/images/gym2/gym2-6.png', 'unlimited: Legal', '50', 'Giovannis Machamp', '68', 'WOTC', 'Rare Holo', '', '10/16/2000', '', 'Colorless, Colorless, Colorless', '', 'Gym', '6', 'Stage 2', 'Pokémon', 'Fighting', 'type: Psychic, value: ×2'),
