('gym2-61', '', '', 'Ken Sugimori', '[{\'name\': \'Wild Kick\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'20\', \'text\': \'Flip a coin. If tails, this attack does nothing.\'}, {\'name\': \'Retaliate\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'10×\', \'text\': \"Does 10 damage times the number of damage counters on Blaine\'s Doduo.\"}]', 'Gym Challenge', '', '', 'Dodrio', '', 'First', '50', 'https://images.pokemoncard.io/images/gym2/gym2-61.png', 'unlimited: Legal', '17', 'Blaines Doduo', '84', 'WOTC', 'Common', '', '10/16/2000', 'type: Fighting, value: -30', '', '', 'Gym', '61', 'Basic', 'Pokémon', 'Colorless', 'type: Lightning, value: ×2'),
('gym2-62', '', '', 'Ken Sugimori', '[{\'name\': \'Stoke\', \'cost\': [\'Fire\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Search your deck for a Fire Energy card and attach it to Blaine\'s Growlithe. Shuffle your deck afterward.\"}, {\'name\': \'Body Slam\', \'cost\': [\'Fire\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'20\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Paralyzed.\'}]', 'Gym Challenge', '1', '', 'Arcanine', '', 'First', '60', 'https://images.pokemoncard.io/images/gym2/gym2-62.png', 'unlimited: Legal', '20', 'Blaines Growlithe', '58', 'WOTC', 'Common', '', '10/16/2000', '', 'Colorless', '', 'Gym', '62', 'Basic', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
