('hgss2-54', '', '', 'Hideaki Hakozaki', '[{\'name\': \'Sharpshooting\', \'cost\': [\'Psychic\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Choose 1 of your opponent\'s Pokémon. This attack does 10 damage to that Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'Unleashed', '1', '', 'Mismagius', 'It likes playing mischievous tricks such as screaming and wailing to startle people at night.', 'Fourth', '50', 'https://images.pokemoncard.io/images/hgss2/hgss2-54.png', 'unlimited: Legal', '', 'Misdreavus', '200', 'TPCI', 'Common', '', '05/12/2010', 'type: Colorless, value: -20', 'Colorless', '', 'HeartGold & SoulSilver', '54', 'Basic', 'Pokémon', 'Psychic', 'type: Darkness, value: ×2'),
('hgss2-55', '', '', 'sui', '[{\'name\': \'Peck\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'\'}, {\'name\': \'Teleport\', \'cost\': [\'Psychic\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Switch Natu with 1 of your Benched Pokémon.\'}]', 'Unleashed', '1', '', 'Xatu', 'It usually forages for food on the ground but may, on rare occasions, hop onto branches to peck at shoots.', 'Fourth', '50', 'https://images.pokemoncard.io/images/hgss2/hgss2-55.png', 'unlimited: Legal', '', 'Natu', '177', 'TPCI', 'Common', '', '05/12/2010', 'type: Fighting, value: -20', 'Colorless', '', 'HeartGold & SoulSilver', '55', 'Basic', 'Pokémon', 'Psychic', 'type: Lightning, value: ×2'),
