('hgss2-71', '', '', 'Kouki Saitou', '', 'Unleashed', '', '', '', '', 'Fourth', '', 'https://images.pokemoncard.io/images/hgss2/hgss2-71.png', 'unlimited: Legal', '', 'Cheerleaders Cheer', '', 'TPCI', 'Uncommon', '', '05/12/2010', '', '', '[\'You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.\', \'Draw 3 cards. Your opponent may draw a card.\']', 'HeartGold & SoulSilver', '71', 'Supporter', 'Trainer', '', ''),
('hgss2-72', '', '', 'Takashi Yamaguchi', '', 'Unleashed', '', '', '', '', 'Fourth', '', 'https://images.pokemoncard.io/images/hgss2/hgss2-72.png', 'unlimited: Legal', '', 'Dual Ball', '', 'TPCI', 'Uncommon', '', '05/12/2010', '', '', '[\'Flip 2 coins. For each heads, search your deck for a Basic Pokémon, show it to your opponent, and put it into your hand. If you do, shuffle your deck afterward.\']', 'HeartGold & SoulSilver', '72', 'Item', 'Trainer', '', ''),
('hgss2-73', '', '', 'Kouki Saitou', '', 'Unleashed', '', '', '', '', 'Fourth', '', 'https://images.pokemoncard.io/images/hgss2/hgss2-73.png', 'unlimited: Legal', '', 'Emcees Chatter', '', 'TPCI', 'Uncommon', '', '05/12/2010', '', '', '[\'You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.\', \'Flip a coin. If heads, draw 3 cards. If tails, draw 2 cards.\']', 'HeartGold & SoulSilver', '73', 'Supporter', 'Trainer', '', ''),
('hgss2-74', '', '', 'Wataru Kawahara', '', 'Unleashed', '', '', '', '', 'Fourth', '', 'https://images.pokemoncard.io/images/hgss2/hgss2-74.png', 'unlimited: Legal', '', 'Energy Returner', '', 'TPCI', 'Uncommon', '', '05/12/2010', '', '', '[\'Search your discard pile for 4 basic Energy cards, show them to your opponent, and shuffle them into your deck.\']', 'HeartGold & SoulSilver', '74', 'Item', 'Trainer', '', ''),
('hgss2-75', '', '', 'Kouki Saitou', '', 'Unleashed', '', '', '', '', 'Fourth', '', 'https://images.pokemoncard.io/images/hgss2/hgss2-75.png', 'unlimited: Legal', '', 'Engineers Adjustments', '', 'TPCI', 'Uncommon', '', '05/12/2010', '', '', '[\'You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.\', \'Discard an Energy card from your hand. Then, draw 4 cards.\']', 'HeartGold & SoulSilver', '75', 'Supporter', 'Trainer', '', ''),
('hgss2-76', '', '', 'Wataru Kawahara', '', 'Unleashed', '', '', '', '', 'Fourth', '', 'https://images.pokemoncard.io/images/hgss2/hgss2-76.png', 'unlimited: Legal', '', 'Good Rod', '', 'TPCI', 'Uncommon', '', '05/12/2010', '', '', '[\'Flip a coin. If heads, search your discard pile for a Pokémon, show it to your opponent, and put it on top of your deck. If tails, search your discard pile for a Trainer card, show it to your opponent, and put it on top of your deck.\']', 'HeartGold & SoulSilver', '76', 'Item', 'Trainer', '', ''),
('hgss2-77', '', '', 'Kouki Saitou', '', 'Unleashed', '', '', '', '', 'Fourth', '', 'https://images.pokemoncard.io/images/hgss2/hgss2-77.png', 'unlimited: Legal', '', 'Interviewers Questions', '', 'TPCI', 'Uncommon', '', '05/12/2010', '', '', '[\'You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.\', \'Look at the top 8 cards of your deck. Choose as many Energy cards as you like, show them to your opponent, and put them into your hand. Shuffle the other cards back into your deck.\']', 'HeartGold & SoulSilver', '77', 'Supporter', 'Trainer', '', ''),
('hgss2-78', '', '', 'Kouki Saitou', '', 'Unleashed', '', '', '', '', 'Fourth', '', 'https://images.pokemoncard.io/images/hgss2/hgss2-78.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Judge', '', 'TPCI', 'Uncommon', '', '05/12/2010', '', '', '[\'You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.\', \'Each player shuffles his or her hand into his or her deck and draws 4 cards.\']', 'HeartGold & SoulSilver', '78', 'Supporter', 'Trainer', '', ''),
('hgss2-79', '', '', 'Hideaki Hakozaki', '', 'Unleashed', '', '', '', '', 'Fourth', '', 'https://images.pokemoncard.io/images/hgss2/hgss2-79.png', 'unlimited: Legal, expanded: Legal', '', 'Life Herb', '', 'TPCI', 'Uncommon', '', '05/12/2010', '', '', '[\'Flip a coin. If heads, choose 1 of your Pokémon, and remove all Special Conditions and 6 damage counters from that Pokémon (all if there are less than 6).\']', 'HeartGold & SoulSilver', '79', 'Item', 'Trainer', '', ''),
('hgss2-8', '[{\'name\': \'Celebration Wind\', \'text\': \'Once during your turn, when you put Shaymin from your hand onto your Bench, you may move as many Energy cards attached to your Pokémon as you like to any of your other Pokémon.\', \'type\': \'Poké-Power\'}]', '', 'Hideaki Hakozaki', '[{\'name\': \'Energy Bloom\', \'cost\': [\'Grass\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'Remove 3 damage counters from each of your Pokémon that has any Energy attached to it.\'}]', 'Unleashed', '1', '', '', 'The blooming of Gracidea flowers confers the power of flight upon it. Feelings of gratitude are the message it delivers.', 'Fourth', '70', 'https://images.pokemoncard.io/images/hgss2/hgss2-8.png', 'unlimited: Legal', '', 'Shaymin', '492', 'TPCI', 'Rare Holo', '', '05/12/2010', 'type: Fighting, value: -20', 'Colorless', '', 'HeartGold & SoulSilver', '8', 'Basic', 'Pokémon', 'Grass', 'type: Fire, value: ×2');
INSERT INTO `cards` (`id`, `abilities`, `ancient_trait`, `artist`, `attacks`, `card_set`, `converted`, `evolves_from`, `evolves_to`, `flavor_text`, `generation`, `hp`, `img`, `legalities`, `level`, `name`, `national_pokedex_numbers`, `publisher`, `rarity`, `regulation_mark`, `release_date`, `resistances`, `retreat_cost`, `rules`, `series`, `set_num`, `subtypes`, `supertype`, `types`, `weakness`) VALUES
('hgss2-80', '', '', 'Takashi Yamaguchi', '', 'Unleashed', '', '', '', '', 'Fourth', '', 'https://images.pokemoncard.io/images/hgss2/hgss2-80.png', 'unlimited: Legal, expanded: Legal', '', 'PlusPower', '', 'TPCI', 'Uncommon', '', '05/12/2010', '', '', '[\'Attach PlusPower to 1 of your Pokémon. Discard this card at the end of your turn.\', \'If the Pokémon PlusPower is attached to attacks, the attack does 10 more damage to the Defending Pokémon (before applying Weakness and Resistance).\']', 'HeartGold & SoulSilver', '80', 'Item', 'Trainer', '', ''),
('hgss2-81', '', '', 'Hideaki Hakozaki', '', 'Unleashed', '', '', '', '', 'Fourth', '', 'https://images.pokemoncard.io/images/hgss2/hgss2-81.png', 'unlimited: Legal', '', 'Pokémon Circulator', '', 'TPCI', 'Uncommon', '', '05/12/2010', '', '', '[\'Your opponent switches his or her Active Pokémon with 1 of his or her Benched Pokémon.\']', 'HeartGold & SoulSilver', '81', 'Item', 'Trainer', '', ''),
('hgss2-82', '', '', 'Noriko Hotta', '', 'Unleashed', '', '', '', '', 'Fourth', '', 'https://images.pokemoncard.io/images/hgss2/hgss2-82.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Rare Candy', '', 'TPCI', 'Uncommon', '', '05/12/2010', '', '', '[\'Choose 1 of your Basic Pokémon in play. If you have a Stage 1 or Stage 2 card that evolves from that Pokémon in your hand, put that card on the Basic Pokémon. (This counts as evolving that Pokémon.) If you choose a Stage 2 Pokémon in your hand, put that Pokémon on the Basic Pokémon instead of on a Stage 1 Pokémon.\']', 'HeartGold & SoulSilver', '82', 'Item', 'Trainer', '', ''),
('hgss2-83', '', '', 'Wataru Kawahara', '', 'Unleashed', '', '', '', '', 'Fourth', '', 'https://images.pokemoncard.io/images/hgss2/hgss2-83.png', 'unlimited: Legal', '', 'Super Scoop Up', '', 'TPCI', 'Uncommon', '', '05/12/2010', '', '', '[\'Flip a coin. If heads, return 1 of your Pokémon and all cards attached to it to your hand.\']', 'HeartGold & SoulSilver', '83', 'Item', 'Trainer', '', ''),
('hgss2-84', '', '', 'Hideaki Hakozaki', '[{\'name\': \'Severe Poison\', \'cost\': [\'Psychic\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'The Defending Pokémon is now Poisoned. Put 4 damage counters instead of 1 on that Pokémon between turns.\'}, {\'name\': \'Skill Dive\', \'cost\': [\'Psychic\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Choose 1 of your opponent\'s Pokémon. This attack does 30 damage to that Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'Unleashed', '', 'Golbat', '', '', 'Fourth', '130', 'https://images.pokemoncard.io/images/hgss2/hgss2-84.png', 'unlimited: Legal', '', 'Crobat', '169', 'TPCI', 'Rare Prime', '', '05/12/2010', 'type: Fighting, value: -20', '', '', 'HeartGold & SoulSilver', '84', 'Stage 2, Prime', 'Pokémon', 'Psychic', 'type: Lightning, value: ×2'),
('hgss2-85', '[{\'name\': \'Spray Splash\', \'text\': \"Once during your turn (before your attack), you may put 1 damage counter on 1 of your opponent\'s Pokémon. This power can\'t be used if Kingdra is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Hideaki Hakozaki', '[{\'name\': \'Dragon Steam\', \'cost\': [\'Water\'], \'convertedEnergyCost\': 1, \'damage\': \'60\', \'text\': \"If your opponent has any Fire Pokémon in play, this attack\'s base damage is 20 instead of 60.\"}]', 'Unleashed', '1', 'Seadra', '', '', 'Fourth', '130', 'https://images.pokemoncard.io/images/hgss2/hgss2-85.png', 'unlimited: Legal', '', 'Kingdra', '230', 'TPCI', 'Rare Prime', '', '05/12/2010', '', 'Colorless', '', 'HeartGold & SoulSilver', '85', 'Stage 2, Prime', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('hgss2-86', '[{\'name\': \'Underwater Dive\', \'text\': \"Once during your turn (before your attack), you may use this power. Lanturn\'s type is Water until the end of your turn. This power can\'t be used if Lanturn is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Hideaki Hakozaki', '[{\'name\': \'Powerful Spark\', \'cost\': [\'Lightning\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40+\', \'text\': \'Does 40 damage plus 10 more damage for each Energy attached to all of your Pokémon.\'}]', 'Unleashed', '2', 'Chinchou', '', '', 'Fourth', '110', 'https://images.pokemoncard.io/images/hgss2/hgss2-86.png', 'unlimited: Legal', '', 'Lanturn', '171', 'TPCI', 'Rare Prime', '', '05/12/2010', '', 'Colorless, Colorless', '', 'HeartGold & SoulSilver', '86', 'Stage 1, Prime', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
('hgss2-87', '[{\'name\': \'Perfect Metal\', \'text\': \"Steelix can\'t be affected by any Special Conditions\", \'type\': \'Poké-Body\'}]', '', 'Wataru Kawahara', '[{\'name\': \'Energy Stream\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'Search your discard pile for an Energy card and attach it to Steelix.\'}, {\'name\': \'Gaia Crush\', \'cost\': [\'Metal\', \'Metal\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 5, \'damage\': \'100\', \'text\': \'You may discard any Stadium card in play.\'}]', 'Unleashed', '4', 'Onix', '', '', 'Fourth', '140', 'https://images.pokemoncard.io/images/hgss2/hgss2-87.png', 'unlimited: Legal', '', 'Steelix', '208', 'TPCI', 'Rare Prime', '', '05/12/2010', 'type: Psychic, value: -20', 'Colorless, Colorless, Colorless, Colorless', '', 'HeartGold & SoulSilver', '87', 'Stage 1, Prime', 'Pokémon', 'Metal', 'type: Fire, value: ×2'),
('hgss2-88', '', '', 'Wataru Kawahara', '[{\'name\': \'Darkness Howl\', \'cost\': [\'Darkness\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"This attack does 20 damage to each Pokémon in play (both yours and your opponent\'s) (excluding any Darkness Pokémon). (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}, {\'name\': \'Power Claw\', \'cost\': [\'Darkness\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60\', \'text\': \"This attack\'s damage isn\'t affected by Poké-Powers, Poké-Bodies, or any other effects on the Defending Pokémon.\"}, {\'name\': \'Megaton Tail\', \'cost\': [\'Darkness\', \'Darkness\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'120\', \'text\': \'Discard the top 3 cards of your deck.\'}]', 'Unleashed', '3', 'Pupitar', '', '', 'Fourth', '160', 'https://images.pokemoncard.io/images/hgss2/hgss2-88.png', 'unlimited: Legal', '', 'Tyranitar', '248', 'TPCI', 'Rare Prime', '', '05/12/2010', 'type: Psychic, value: -20', 'Colorless, Colorless, Colorless', '', 'HeartGold & SoulSilver', '88', 'Stage 2, Prime', 'Pokémon', 'Darkness', 'type: Fighting, value: ×2'),
('hgss2-89', '[{\'name\': \'Berserk\', \'text\': \"If Ursaring has any damage counters on it, each of Ursaring\'s attacks does 60 more damage (before applying Weakness and Resistance).\", \'type\': \'Poké-Body\'}]', '', 'Wataru Kawahara', '[{\'name\': \'Hammer Arm\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'30\', \'text\': \"Discard the top card from your opponent\'s deck.\"}, {\'name\': \'Megaton Lariat\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'60\', \'text\': \'\'}]', 'Unleashed', '3', 'Teddiursa', '', '', 'Fourth', '110', 'https://images.pokemoncard.io/images/hgss2/hgss2-89.png', 'unlimited: Legal', '', 'Ursaring', '217', 'TPCI', 'Rare Prime', '', '05/12/2010', '', 'Colorless, Colorless, Colorless', '', 'HeartGold & SoulSilver', '89', 'Stage 1, Prime', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('hgss2-9', '', '', 'Sachiko Adachi', '[{\'name\': \'Push Over\', \'cost\': [\'Fighting\'], \'convertedEnergyCost\': 1, \'damage\': \'20×\', \'text\': \'Does 20 damage times the amount of Fighting Energy attached to Sudowoodo.\'}, {\'name\': \'Rumble\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40\', \'text\': \"The Defending Pokémon can\'t retreat during your opponent\'s next turn.\"}]', 'Unleashed', '2', '', '', 'It disguises itself as a tree to avoid attack. It hates water, so it will disappear if it starts raining.', 'Fourth', '90', 'https://images.pokemoncard.io/images/hgss2/hgss2-9.png', 'unlimited: Legal', '', 'Sudowoodo', '185', 'TPCI', 'Rare Holo', '', '05/12/2010', '', 'Colorless, Colorless', '', 'HeartGold & SoulSilver', '9', 'Basic', 'Pokémon', 'Fighting', 'type: Water, value: ×2'),
('hgss2-90', '', '', 'Shinji Higuchi + Sachiko Eba', '[{\'name\': \'Detonation Spin\', \'cost\': [\'Fire\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'90\', \'text\': \'Discard a Fire Energy attached to Entei & Raikou LEGEND.\'}, {\'name\': \'Thunder Fall\', \'cost\': [\'Lightning\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'\', \'text\': \"Discard all Energy attached to Entei & Raikou LEGEND. This attack does 80 damage to each Pokémon that has any Poké-Powers (both yours and your opponent\'s). This attack\'s damage isn\'t affected by Weakness or Resistance.\"}]', 'Unleashed', '', '', '', '', 'Fourth', '140', 'https://images.pokemoncard.io/images/hgss2/hgss2-90.png', 'unlimited: Legal', '', 'Entei & Raikou LEGEND', '243, 244', 'TPCI', 'LEGEND', '', '05/12/2010', '', '', '[\'Put this card from your hand onto your Bench only with the other half of Entei & Raikou LEGEND.\', \'When this Pokémon has been Knocked Out, your opponent takes 2 Prize cards.\']', 'HeartGold & SoulSilver', '90', 'LEGEND', 'Pokémon', 'Fire, Lightning', 'type: Water, value: ×2'),
('hgss2-91', '', '', 'Shinji Higuchi + Sachiko Eba', '[{\'name\': \'Detonation Spin\', \'cost\': [\'Fire\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'90\', \'text\': \'Discard a Fire Energy attached to Entei & Raikou LEGEND.\'}, {\'name\': \'Thunder Fall\', \'cost\': [\'Lightning\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'\', \'text\': \"Discard all Energy attached to Entei & Raikou LEGEND. This attack does 80 damage to each Pokémon that has any Poké-Powers (both yours and your opponent\'s). This attack\'s damage isn\'t affected by Weakness or Resistance.\"}]', 'Unleashed', '', '', '', '', 'Fourth', '140', 'https://images.pokemoncard.io/images/hgss2/hgss2-91.png', 'unlimited: Legal', '', 'Entei & Raikou LEGEND', '243, 244', 'TPCI', 'LEGEND', '', '05/12/2010', '', '', '[\'Put this card from your hand onto your Bench only with the other half of Entei & Raikou LEGEND.\', \'When this Pokémon has been Knocked Out, your opponent takes 2 Prize cards.\']', 'HeartGold & SoulSilver', '91', 'LEGEND', 'Pokémon', 'Fire, Lightning', 'type: Water, value: ×2, type: Fighting, value: ×2'),
('hgss2-92', '', '', 'Shinji Higuchi + Noriko Takaya', '[{\'name\': \'Thunderbolt Spear\', \'cost\': [\'Lightning\', \'Lightning\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'150\', \'text\': \"Raikou & Suicune LEGEND does 50 damage to itself and don\'t apply Weakness to this damage.\"}, {\'name\': \'Aurora Gain\', \'cost\': [\'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50\', \'text\': \'Remove 5 damage counters from Raikou & Suicune LEGEND.\'}]', 'Unleashed', '1', '', '', '', 'Fourth', '160', 'https://images.pokemoncard.io/images/hgss2/hgss2-92.png', 'unlimited: Legal', '', 'Raikou & Suicune LEGEND', '243, 245', 'TPCI', 'LEGEND', '', '05/12/2010', '', 'Colorless', '[\'Put this card from your hand onto your Bench only with the other half of Raikou & Suicune LEGEND.\', \'When this Pokémon has been Knocked Out, your opponent takes 2 Prize cards.\']', 'HeartGold & SoulSilver', '92', 'LEGEND', 'Pokémon', 'Lightning, Water', 'type: Fighting, value: ×2, type: Lightning, value: ×2'),
('hgss2-93', '', '', 'Shinji Higuchi + Noriko Takaya', '[{\'name\': \'Thunderbolt Spear\', \'cost\': [\'Lightning\', \'Lightning\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'150\', \'text\': \"Raikou & Suicune LEGEND does 50 damage to itself and don\'t apply Weakness to this damage.\"}, {\'name\': \'Aurora Gain\', \'cost\': [\'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50\', \'text\': \'Remove 5 damage counters from Raikou & Suicune LEGEND.\'}]', 'Unleashed', '1', '', '', '', 'Fourth', '160', 'https://images.pokemoncard.io/images/hgss2/hgss2-93.png', 'unlimited: Legal', '', 'Raikou & Suicune LEGEND', '243, 245', 'TPCI', 'LEGEND', '', '05/12/2010', '', 'Colorless', '[\'Put this card from your hand onto your Bench only with the other half of Raikou & Suicune LEGEND.\', \'When this Pokémon has been Knocked Out, your opponent takes 2 Prize cards.\']', 'HeartGold & SoulSilver', '93', 'LEGEND', 'Pokémon', 'Lightning, Water', 'type: Fighting, value: ×2, type: Lightning, value: ×2'),
('hgss2-94', '', '', 'Shinji Higuchi + Sachiko Eba', '[{\'name\': \'Torrent Blade\', \'cost\': [\'Water\', \'Water\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'\', \'text\': \"Return 2 Water Energy attached to Suicune & Entei LEGEND to your hand. Choose 1 of your opponent\'s Benched Pokémon. This attack does 100 damage to that Pokémon. (Don\'t apply Weakness or Resistance for Benched Pokémon.)\"}, {\'name\': \'Bursting Inferno\', \'cost\': [\'Fire\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'80\', \'text\': \'The Defending Pokémon is now Burned.\'}]', 'Unleashed', '1', '', '', '', 'Fourth', '160', 'https://images.pokemoncard.io/images/hgss2/hgss2-94.png', 'unlimited: Legal', '', 'Suicune & Entei LEGEND', '244, 245', 'TPCI', 'LEGEND', '', '05/12/2010', '', 'Colorless', '[\'Put this card from your hand onto your Bench only with the other half of Suicune & Entei LEGEND.\', \'When this Pokémon has been Knocked Out, your opponent takes 2 Prize cards.\']', 'HeartGold & SoulSilver', '94', 'LEGEND', 'Pokémon', 'Water, Fire', 'type: Lightning, value: ×2, type: Water, value: ×2'),
('hgss2-95', '', '', 'Shinji Higuchi + Sachiko Eba', '[{\'name\': \'Torrent Blade\', \'cost\': [\'Water\', \'Water\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'\', \'text\': \"Return 2 Water Energy attached to Suicune & Entei LEGEND to your hand. Choose 1 of your opponent\'s Benched Pokémon. This attack does 100 damage to that Pokémon. (Don\'t apply Weakness or Resistance for Benched Pokémon.)\"}, {\'name\': \'Bursting Inferno\', \'cost\': [\'Fire\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'80\', \'text\': \'The Defending Pokémon is now Burned.\'}]', 'Unleashed', '1', '', '', '', 'Fourth', '160', 'https://images.pokemoncard.io/images/hgss2/hgss2-95.png', 'unlimited: Legal', '', 'Suicune & Entei LEGEND', '244, 245', 'TPCI', 'LEGEND', '', '05/12/2010', '', 'Colorless', '[\'Put this card from your hand onto your Bench only with the other half of Suicune & Entei LEGEND.\', \'When this Pokémon has been Knocked Out, your opponent takes 2 Prize cards.\']', 'HeartGold & SoulSilver', '95', 'LEGEND', 'Pokémon', 'Water, Fire', 'type: Lightning, value: ×2, type: Water, value: ×2'),
('hgss2-TWO', '', '', 'Milky Isobe', '', 'Unleashed', '', '', '', '', 'Fourth', '', 'https://images.pokemoncard.io/images/hgss2/hgss2-TWO.png', 'unlimited: Legal', '', 'Alph Lithograph', '', 'TPCI', 'Rare Secret', '', '05/12/2010', '', '', '[\'Shuffle your deck!\']', 'HeartGold & SoulSilver', 'TWO', 'Item', 'Trainer', '', ''),
('hgss3-1', '[{\'name\': \'Hustle Step\', \'text\': \"Once during your turn (before your attack), you may remove 1 damage counter from each of your Pokémon. This power can\'t be used if Bellossom is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Mitsuhiro Arita', '[{\'name\': \"Dance \'til Dawn\", \'cost\': [\'Grass\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30×\', \'text\': \'Flip 3 coins. This attack does 30 damage times the number of heads. Bellossom is now Asleep.\'}]', 'Undaunted', '1', 'Gloom', '', 'Bellossom gather at times and seem to dance. They say that the dance is a ritual to summon the sun.', 'Fourth', '110', 'https://images.pokemoncard.io/images/hgss3/hgss3-1.png', 'unlimited: Legal', '', 'Bellossom', '182', 'TPCI', 'Rare Holo', '', '8/18/2010', 'type: Water, value: -20', 'Colorless', '', 'HeartGold & SoulSilver', '1', 'Stage 2', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('hgss3-10', '', '', 'Mitsuhiro Arita', '[{\'name\': \'Moonlight Fang\', \'cost\': [\'Darkness\'], \'convertedEnergyCost\': 1, \'damage\': \'30\', \'text\': \"During your opponent\'s next turn, prevent all effects, including damage, done to Umbreon by attacks from your opponent\'s Pokémon that has any Poké-Powers or Poké-Bodies.\"}, {\'name\': \'Quick Blow\', \'cost\': [\'Darkness\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30+\', \'text\': \'Flip a coin. If heads, this attack does 30 damage plus 30 damage.\'}]', 'Undaunted', '1', 'Eevee', '', 'When agitated, this Pokémon protects itself by spraying poisonous sweat from its pores.', 'Fourth', '90', 'https://images.pokemoncard.io/images/hgss3/hgss3-10.png', 'unlimited: Legal', '', 'Umbreon', '197', 'TPCI', 'Rare Holo', '', '8/18/2010', 'type: Psychic, value: -20', 'Colorless', '', 'HeartGold & SoulSilver', '10', 'Stage 1', 'Pokémon', 'Darkness', 'type: Fighting, value: ×2'),
('hgss3-11', '[{\'name\': \'Retreat Aid\', \'text\': \"As long as Dodrio is on your Bench, your Active Pokémon\'s Retreat Cost is ColorlessColorless less.\", \'type\': \'Poké-Body\'}]', '', 'Yukiko Baba', '[{\'name\': \'Incessant Peck\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20+\', \'text\': \'Flip a coin until you get tails. This attack does 20 damage plus 20 more damage for each heads.\'}]', 'Undaunted', '1', 'Doduo', '', 'It collects data and plans three times as wisely, but it may think too much and fall into a state of immobility.', 'Fourth', '80', 'https://images.pokemoncard.io/images/hgss3/hgss3-11.png', 'unlimited: Legal', '', 'Dodrio', '85', 'TPCI', 'Rare', '', '8/18/2010', 'type: Fighting, value: -20', 'Colorless', '', 'HeartGold & SoulSilver', '11', 'Stage 1', 'Pokémon', 'Colorless', 'type: Lightning, value: ×2'),
('hgss3-12', '', '', 'Kagemaru Himeno', '[{\'name\': \'Balloon Tackle\', \'cost\': [\'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'60\', \'text\': \'Drifblim does 20 damage to itself.\'}, {\'name\': \'Take Away\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'\', \'text\': \'Shuffle Drifblim and all cards attached to it back into your deck. Then, your opponent shuffles the Defending Pokémon and all cards attached to it into his or her deck. (You choose your new Active Pokémon first.)\'}]', 'Undaunted', '', 'Drifloon', '', 'It can generate and release gas within its body. Thats how it can control the altitude of its drift.', 'Fourth', '90', 'https://images.pokemoncard.io/images/hgss3/hgss3-12.png', 'unlimited: Legal', '', 'Drifblim', '426', 'TPCI', 'Rare', '', '8/18/2010', 'type: Colorless, value: -20', '', '', 'HeartGold & SoulSilver', '12', 'Stage 1', 'Pokémon', 'Psychic', 'type: Darkness, value: ×2'),
