('np-36', '', '', 'Sumiyoshi Kizuki', '', 'Nintendo Black Star Promos', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/np/np-36.png', 'unlimited: Legal', '', 'Tropical Tidal Wave', '', 'TPCI', 'Promo', '', '10/01/2003', '', '', '[\'Flip a coin. If heads, discard all Trainer cards your opponent has in play. If tails, discard all Trainer cards (excluding Supporter cards) you have in play.\']', 'NP', '36', 'Item', 'Trainer', '', ''),
('np-37', '[{\'name\': \'Frenzy\', \'text\': \"As long as your opponent has Groudon, Groudon ex, Rayquaza, or Rayquaza ex in play. Kyogre ex\'s attacks do 40 more damage to the Defending Pokémon (before applying Weakness and Resistance).\", \'type\': \'Poké-Body\'}]', '', 'Ryo Ueda', '[{\'name\': \'Aqua Supply\', \'cost\': [\'Water\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'You may attach a basic Energy card from your hand to 1 of your Pokémon.\'}, {\'name\': \'Tsunami\', \'cost\': [\'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40\', \'text\': \"Does 10 damage to each of your opponent\'s Benched Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'Nintendo Black Star Promos', '2', '', '', '', 'Third', '100', 'https://images.pokemoncard.io/images/np/np-37.png', 'unlimited: Legal', '', 'Kyogre ex', '382', 'TPCI', 'Promo', '', '10/01/2003', '', 'Colorless, Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'NP', '37', 'Basic, EX', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('np-38', '[{\'name\': \'Frenzy\', \'text\': \"As long as your opponent has Kyogre, Kyogre ex, Rayquaza, or Rayquaza ex in play, Groudon ex\'s attacks do 40 more damage to the Defending Pokémon (before applying Weakness and Resistance).\", \'type\': \'Poké-Body\'}]', '', 'Ryo Ueda', '[{\'name\': \'Mix-Up\', \'cost\': [\'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'Flip a coin. If heads, your opponent discards the top card from his or her deck.\'}, {\'name\': \'Earthquake\', \'cost\': [\'Fighting\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60\', \'text\': \"Does 10 damage to each of your Benched Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'Nintendo Black Star Promos', '2', '', '', '', 'Third', '100', 'https://images.pokemoncard.io/images/np/np-38.png', 'unlimited: Legal', '', 'Groudon ex', '383', 'TPCI', 'Promo', '', '10/01/2003', '', 'Colorless, Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'NP', '38', 'Basic, EX', 'Pokémon', 'Fighting', 'type: Water, value: ×2'),
('np-39', '[{\'name\': \'Frenzy\', \'text\': \"As long as your opponent has Kyogre, Kyogre ex, Groudon, or Groudon ex in play, Rayquaza ex\'s attacks do 40 damage to the Defending Pokémon (before applying Weakness and Resistance).\", \'type\': \'Poké-Body\'}]', '', 'Ryo Ueda', '[{\'name\': \'Dragon Bind\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Paralyzed.\'}, {\'name\': \'Twister\', \'cost\': [\'Fire\', \'Lightning\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50\', \'text\': \'Flip 2 coins. If both are tails, this attack does nothing. For each heads, discard an Energy attached to the Defending Pokémon.\'}]', 'Nintendo Black Star Promos', '1', '', '', '', 'Third', '100', 'https://images.pokemoncard.io/images/np/np-39.png', 'unlimited: Legal', '', 'Rayquaza ex', '384', 'TPCI', 'Promo', '', '10/01/2003', 'type: Water, value: -30', 'Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'NP', '39', 'Basic, EX', 'Pokémon', 'Colorless', 'type: Colorless, value: ×2'),
('np-4', '', '', 'Midori Harada', '[{\'name\': \'Poison Breath\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'\', \'text\': \'The Defending Pokémon is now Poisoned.\'}, {\'name\': \'Swift\', \'cost\': [\'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'30\', \'text\': \"This attack\'s damage isn\'t affected by Weakness, Resistance, Poké-Powers, Poké-Bodies, or any other effects on the Defending Pokémon.\"}]', 'Nintendo Black Star Promos', '1', 'Treecko', 'Sceptile', '', 'Third', '70', 'https://images.pokemoncard.io/images/np/np-4.png', 'unlimited: Legal', '', 'Grovyle', '253', 'TPCI', 'Promo', '', '10/01/2003', 'type: Water, value: -30', 'Colorless', '', 'NP', '4', 'Stage 1', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('np-40', '', '', 'Masakazu Fukuda', '[{\'name\': \'Psywave\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10×\', \'text\': \'Does 10 damage times the amount of Energy attached to the Defending Pokémon.\'}, {\'name\': \'Devolution Beam\', \'cost\': [\'Psychic\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Flip a coin. If heads, choose 1 of either player\'s Evolved Pokémon, remove the highest stage Evolution card from that Pokémon, and put it into that player\'s hand.\"}]', 'Nintendo Black Star Promos', '1', '', '', '', 'Third', '50', 'https://images.pokemoncard.io/images/np/np-40.png', 'unlimited: Legal', '', 'Mew', '151', 'TPCI', 'Promo', '', '10/01/2003', '', 'Colorless', '', 'NP', '40', 'Basic', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2'),
