('pgo-71', '', '', 'MUGENUP', '[{\'name\': \'Growing Tall\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Flip a coin. If heads, search your deck for up to 5 Grass Energy cards and attach them to your Pokémon in any way you like. Then, shuffle your deck.\'}, {\'name\': \'Head Swing\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'\', \'text\': \"This attack does 30 damage to 1 of your opponent\'s Pokémon for each Grass Energy attached to this Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'Pokémon GO', '3', '', '', '', 'Eighth', '240', 'https://images.pokemoncard.io/images/pgo/pgo-71.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Alolan Exeggutor V', '103', 'TPCI', 'Rare Ultra', 'F', '07/01/2022', '', 'Colorless, Colorless, Colorless', '[\'V rule: When your Pokémon V is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sword & Shield', '71', 'Basic, V', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('pgo-72', '', '', 'N-DESIGN Inc.', '[{\'name\': \'Super Psy Bolt\', \'cost\': [\'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'50\', \'text\': \'\'}, {\'name\': \'Transfer Break\', \'cost\': [\'Psychic\', \'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'160\', \'text\': \'Move an Energy from this Pokémon to 1 of your Benched Pokémon.\'}]', 'Pokémon GO', '2', '', '', '', 'Eighth', '220', 'https://images.pokemoncard.io/images/pgo/pgo-72.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Mewtwo V', '150', 'TPCI', 'Rare Ultra', 'F', '07/01/2022', 'type: Fighting, value: -30', 'Colorless, Colorless', '[\'V rule: When your Pokémon V is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sword & Shield', '72', 'Basic, V', 'Pokémon', 'Psychic', 'type: Darkness, value: ×2'),
('pgo-73', '', '', 'Ayaka Yoshida', '[{\'name\': \'Counter\', \'cost\': [\'Fighting\'], \'convertedEnergyCost\': 1, \'damage\': \'20+\', \'text\': \"If this Pokémon was damaged by an attack during your opponent\'s last turn, this attack does that much more damage.\"}, {\'name\': \'Dynamic Punch\', \'cost\': [\'Fighting\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'90+\', \'text\': \"Flip a coin. If heads, this attack does 90 more damage, and your opponent\'s Active Pokémon is now Confused.\"}]', 'Pokémon GO', '3', '', '', '', 'Eighth', '230', 'https://images.pokemoncard.io/images/pgo/pgo-73.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Conkeldurr V', '534', 'TPCI', 'Rare Ultra', 'F', '07/01/2022', '', 'Colorless, Colorless, Colorless', '[\'V rule: When your Pokémon V is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sword & Shield', '73', 'Basic, V', 'Pokémon', 'Fighting', 'type: Psychic, value: ×2'),
