('pgo-88', '', '', 'ORBITALLINK Inc.', '', 'Pokémon GO', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/pgo/pgo-88.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Lure Module', '', 'TPCI', 'Rare Secret', 'F', '07/01/2022', '', '', '[\'Each player reveals the top 3 cards of their deck and puts all Pokémon they find there into their hand. Then, each player shuffles the other cards back into their deck.\', \'You may play any number of Item cards during your turn.\']', 'Sword & Shield', '88', 'Item', 'Trainer', '', ''),
('pgo-9', '', '', 'Shiburingaru', '[{\'name\': \'Scratch\', \'cost\': [\'Fire\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'\'}, {\'name\': \'Flamethrower\', \'cost\': [\'Fire\', \'Fire\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'100\', \'text\': \'Discard a Fire Energy from this Pokémon.\'}]', 'Pokémon GO', '2', 'Charmander', 'Charizard', 'It has a barbaric nature. In battle, it whips its fiery tail around and slashes away with sharp claws.', 'Eighth', '90', 'https://images.pokemoncard.io/images/pgo/pgo-9.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Charmeleon', '5', 'TPCI', 'Uncommon', 'F', '07/01/2022', '', 'Colorless, Colorless', '', 'Sword & Shield', '9', 'Stage 1', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
