('pl2-6', '', '', 'Atsuko Nishida', '[{\'name\': \'Sleep Inducer\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Switch the Defending Pokémon with 1 of your opponent\'s Benched Pokémon. The new Defending Pokémon is now Asleep.\"}, {\'name\': \'Wake-Up Slap\', \'cost\': [\'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30+\', \'text\': \'If the Defending Pokémon is affected by any Special Conditions, this attack does 30 damage plus 20 more damage. Then, remove all Special Conditions from the Defending Pokémon.\'}]', 'Rising Rivals', '1', '', '', '', 'Fourth', '70', 'https://images.pokemoncard.io/images/pl2/pl2-6.png', 'unlimited: Legal', '44', 'Froslass GL', '478', 'TPCI', 'Rare Holo', '', '5/16/2009', '', 'Colorless', '', 'Platinum', '6', 'Basic, SP', 'Pokémon', 'Water', 'type: Metal, value: ×2'),
('pl2-60', '', '', 'Masakazu Fukuda', '[{\'name\': \'Tackle\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'\'}, {\'name\': \'Fire Tail Slap\', \'cost\': [\'Fire\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'40\', \'text\': \'Flip a coin. If tails, discard a Fire Energy attached to Flareon .\'}]', 'Rising Rivals', '1', '', '', '', 'Fourth', '70', 'https://images.pokemoncard.io/images/pl2/pl2-60.png', 'unlimited: Legal', '55', 'Flareon E4', '136', 'TPCI', 'Common', '', '5/16/2009', '', 'Colorless', '', 'Platinum', '60', 'Basic, SP', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('pl2-61', '', '', 'Ryota Saito', '[{\'name\': \'Shell Scatter\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"This attack does 10 damage to each of your opponent\'s Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.) Forretress G can\'t use Shell Scatter during your next turn.\"}, {\'name\': \'Bomb Risk\', \'cost\': [\'Metal\', \'Metal\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'80\', \'text\': \"Does 10 damage to each Benched Pokémon (both yours and your opponent\'s). (Don\'t apply Weakness and Resistance for Benched Pokémon.) Flip a coin. If tails, Forretress G does 80 damage to itself.\"}]', 'Rising Rivals', '2', '', '', '', 'Fourth', '80', 'https://images.pokemoncard.io/images/pl2/pl2-61.png', 'unlimited: Legal', '35', 'Forretress G', '205', 'TPCI', 'Common', '', '5/16/2009', 'type: Psychic, value: -20', 'Colorless, Colorless', '', 'Platinum', '61', 'Basic, SP', 'Pokémon', 'Metal', 'type: Fire, value: ×2');
