('pl4-82', '', '', 'Ryo Ueda', '', 'Arceus', '', '', '', '', 'Fourth', '', 'https://images.pokemoncard.io/images/pl4/pl4-82.png', 'unlimited: Legal', '', 'Beginning Door', '', 'TPCI', 'Uncommon', '', '11/04/2009', '', '', '[\'Search your deck for Arceus, show it to your opponent, and put it into your hand. Shuffle your deck afterward.\']', 'Platinum', '82', 'Item', 'Trainer', '', ''),
('pl4-83', '', '', 'Wataru Kawahara', '', 'Arceus', '', '', '', '', 'Fourth', '', 'https://images.pokemoncard.io/images/pl4/pl4-83.png', 'unlimited: Legal', '', 'Bench Shield', '', 'TPCI', 'Uncommon', '', '11/04/2009', '', '', '[\"Attach Bench Shield to 1 of your Pokémon that doesn\'t already have a Pokémon Tool attached to it. If that Pokémon is Knocked Out, discard this card.\", \"As long as the Pokémon this card is attached to is on your Bench, prevent all damage done to that Pokémon by attacks (both yours and your opponent\'s).\"]', 'Platinum', '83', 'Pokémon Tool', 'Trainer', '', ''),
('pl4-84', '', '', 'Ryo Ueda', '', 'Arceus', '', '', '', '', 'Fourth', '', 'https://images.pokemoncard.io/images/pl4/pl4-84.png', 'unlimited: Legal', '', 'Buffer Piece', '', 'TPCI', 'Uncommon', '', '11/04/2009', '', '', '[\"Attach Buffer Piece to 1 of your Pokémon that doesn\'t already have a Pokémon Tool attached to it. If that Pokémon is Knocked Out, discard this card.\", \"Any damage done to the Pokémon this card is attached to by an opponent\'s attack is reduced by 20 (after applying Weakness and Resistance). At the end of your opponent\'s turn after you played Buffer Piece, discard Buffer Piece.\"]', 'Platinum', '84', 'Pokémon Tool', 'Trainer', '', ''),
('pl4-85', '', '', 'Kanako Eo', '', 'Arceus', '', '', '', '', 'Fourth', '', 'https://images.pokemoncard.io/images/pl4/pl4-85.png', 'unlimited: Legal', '', 'Department Store Girl', '', 'TPCI', 'Uncommon', '', '11/04/2009', '', '', '[\'You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.\', \'Search your deck for up to 3 Pokémon Tool cards, show them to your opponent, and put them into your hand. Shuffle your deck afterward.\']', 'Platinum', '85', 'Supporter', 'Trainer', '', ''),
('pl4-86', '', '', 'Ryo Ueda', '', 'Arceus', '', '', '', '', 'Fourth', '', 'https://images.pokemoncard.io/images/pl4/pl4-86.png', 'unlimited: Legal', '', 'Energy Restore', '', 'TPCI', 'Uncommon', '', '11/04/2009', '', '', '[\"Flip 3 coins. For each heads, put a basic Energy card from your discard pile into your hand. If you don\'t have that many basic Energy cards in your discard pile, put all of them into your hand.\"]', 'Platinum', '86', 'Item', 'Trainer', '', ''),
('pl4-87', '', '', 'Wataru Kawahara', '', 'Arceus', '', '', '', '', 'Fourth', '', 'https://images.pokemoncard.io/images/pl4/pl4-87.png', 'unlimited: Legal', '', 'Expert Belt', '', 'TPCI', 'Uncommon', '', '11/04/2009', '', '', '[\"Attach Expert Belt to 1 of your Pokémon that doesn\'t already have a Pokémon Tool attached to it. If that Pokémon is Knocked Out, discard this card.\", \"The Pokémon this card is attached to gets +20 HP and that Pokémon\'s attacks do 20 more damage to your opponent\'s Active Pokémon (before applying Weakness and Resistance). When the Pokémon this card is attached to is Knocked Out, your opponent takes 1 more Prize card.\"]', 'Platinum', '87', 'Pokémon Tool', 'Trainer', '', ''),
('pl4-88', '', '', 'Nobuyuki Fujimoto', '', 'Arceus', '', '', '', '', 'Fourth', '', 'https://images.pokemoncard.io/images/pl4/pl4-88.png', 'unlimited: Legal, expanded: Legal', '', 'Lucky Egg', '', 'TPCI', 'Uncommon', '', '11/04/2009', '', '', '[\"Attach Lucky Egg to 1 of your Pokémon that doesn\'t already have a Pokémon Tool attached to it. If that Pokémon is Knocked Out, discard this card.\", \"When the Pokémon this card is attached to is Knocked Out by damage from an opponent\'s attack, draw cards until you have 7 cards in your hand.\"]', 'Platinum', '88', 'Pokémon Tool', 'Trainer', '', ''),
('pl4-89', '[{\'name\': \'Hard Amber\', \'text\': \"As long as Old Amber is on your Bench, prevent all damage done to Old Amber by attacks (both yours and your opponent\'s).\", \'type\': \'Poké-Body\'}]', '', 'Ryo Ueda', '', 'Arceus', '', '', '', '', 'Fourth', '50', 'https://images.pokemoncard.io/images/pl4/pl4-89.png', 'unlimited: Legal', '', 'Old Amber', '', 'TPCI', 'Common', '', '11/04/2009', '', '', '[\"Play Old Amber as if it were a Colorless Basic Pokémon. (Old Amber counts as a Trainer card as well, but if Old Amber is Knocked Out, this counts as a Knocked Out Pokémon.) Old Amber can\'t be affected by any Special Conditions and can\'t retreat. At any time during your turn before your attack, you may discard Old Amber from play. (This doesn\'t count as a Knocked Out Pokémon.)\"]', 'Platinum', '89', 'Item', 'Trainer', '', ''),
('pl4-9', '', '', 'Aya Kusube', '[{\'name\': \'Damage Roller\', \'cost\': [\'Psychic\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Put damage counters on the Defending Pokémon until the Defending Pokémon has the same remaining HP as Swalot. (If the Defending Pokémon has the same or less remaining HP as Swalot, this attack does nothing.)\'}, {\'name\': \'Entangle Tackle\', \'cost\': [\'Psychic\', \'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50+\', \'text\': \"You may do 50 damage plus 30 more damage. If you do, this attack does 30 damage to 1 of your Pokémon, and don\'t apply Weakness and Resistance to this damage.\"}]', 'Arceus', '3', 'Gulpin', '', 'It swallows anything whole. It sweats toxic fluids from its follicles to douse foes.', 'Fourth', '100', 'https://images.pokemoncard.io/images/pl4/pl4-9.png', 'unlimited: Legal', '40', 'Swalot', '317', 'TPCI', 'Rare Holo', '', '11/04/2009', '', 'Colorless, Colorless, Colorless', '', 'Platinum', '9', 'Stage 1', 'Pokémon', 'Psychic', 'type: Psychic, value: +20'),
('pl4-90', '', '', 'Ken Sugimori', '', 'Arceus', '', '', '', '', 'Fourth', '', 'https://images.pokemoncard.io/images/pl4/pl4-90.png', 'unlimited: Legal', '', 'Professor Oaks Visit', '', 'TPCI', 'Uncommon', '', '11/04/2009', '', '', '[\'You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.\', \'Draw 3 cards. Then, choose a card from your hand and put it on the bottom of your deck.\']', 'Platinum', '90', 'Supporter', 'Trainer', '', ''),
('pl4-91', '', '', 'Yusuke Ishikawa', '', 'Arceus', '', '', '', '', 'Fourth', '', 'https://images.pokemoncard.io/images/pl4/pl4-91.png', 'unlimited: Legal', '', 'Ultimate Zone', '', 'TPCI', 'Uncommon', '', '11/04/2009', '', '', '[\"This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can\'t play this card.\", \"During each player\'s turn, the player may move an Energy card attached to 1 of his or her Benched Pokémon to his or her Active Arceus as often as he or she likes.\"]', 'Platinum', '91', 'Stadium', 'Trainer', '', ''),
('pl4-92', '[{\'name\': \'Rock Reaction\', \'text\': \'When you attach a Fighting Energy card from your hand to Dome Fossil (excluding effects of attacks or Poké-Powers), search your deck for a card that evolves from Dome Fossil and put it onto Dome Fossil (this counts as evolving Dome Fossil). Shuffle your deck afterward.\', \'type\': \'Poké-Body\'}]', '', 'Ryo Ueda', '', 'Arceus', '', '', '', '', 'Fourth', '50', 'https://images.pokemoncard.io/images/pl4/pl4-92.png', 'unlimited: Legal', '', 'Dome Fossil', '', 'TPCI', 'Common', '', '11/04/2009', '', '', '[\"Play Dome Fossil as if it were a Colorless Basic Pokémon. (Dome Fossil counts as a Trainer card as well, but if Dome Fossil is Knocked Out, this counts as a Knocked Out Pokémon.) Dome Fossil can\'t be affected by any Special Conditions and can\'t retreat. At any time during your turn before your attack, you may discard Dome Fossil from play. (This doesn\'t count as a Knocked Out Pokémon.)\"]', 'Platinum', '92', 'Item', 'Trainer', '', ''),
('pl4-93', '[{\'name\': \'Aqua Reaction\', \'text\': \'When you attach a Water Energy card from your hand to Helix Fossil (excluding effects of attacks or Poké-Powers), search your deck for a card that evolves from Helix Fossil and put it onto Helix Fossil (this counts as evolving Helix Fossil). Shuffle your deck afterward.\', \'type\': \'Poké-Body\'}]', '', 'Ryo Ueda', '', 'Arceus', '', '', '', '', 'Fourth', '50', 'https://images.pokemoncard.io/images/pl4/pl4-93.png', 'unlimited: Legal', '', 'Helix Fossil', '', 'TPCI', 'Common', '', '11/04/2009', '', '', '[\"Play Helix Fossil as if it were a Colorless Basic Pokémon. (Helix Fossil counts as a Trainer card as well, but if Helix Fossil is Knocked Out, this counts as a Knocked Out Pokémon.) Helix Fossil can\'t be affected by any Special Conditions and can\'t retreat. At any time during your turn before your attack, you may discard Helix Fossil from play. (This doesn\'t count as a Knocked Out Pokémon.)\"]', 'Platinum', '93', 'Item', 'Trainer', '', ''),
('pl4-94', '[{\'name\': \'Multi-type\', \'text\': \"Arceus LV. X\'s type is the same type as its previous Level.\", \'type\': \'Poké-Body\'}, {\'name\': \'Omniscient\', \'text\': \'Arceus can use the attacks of all Arceus you have in play as its own. (You still need the necessary Energy to use each attack.)\', \'type\': \'Poké-Body\'}]', '', 'Shizurow', '', 'Arceus', '1', 'Arceus', '', '', 'Fourth', '120', 'https://images.pokemoncard.io/images/pl4/pl4-94.png', 'unlimited: Legal', 'X', 'Arceus LV.X', '493', 'TPCI', 'Rare Holo LV.X', '', '11/04/2009', '', 'Colorless', '[\'You may have as many of this card in your deck as you like.\', \'Put this card onto your Active Arceus. Arceus LV.X can use any attack, Poké-Power, or Poké-Body from its previous level.\']', 'Platinum', '94', 'Level-Up', 'Pokémon', 'Colorless', ''),
('pl4-95', '[{\'name\': \'Multitype\', \'text\': \"Arceus LV.X\'s type is the same as its previous Level.\", \'type\': \'Poké-Body\'}]', '', 'Ryo Ueda', '[{\'name\': \'Meteor Blast\', \'cost\': [\'Grass\', \'Fire\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'100\', \'text\': \"Flip a coin. If tails, this attack\'s base damage is 50 instead of 100.\"}]', 'Arceus', '1', 'Arceus', '', '', 'Fourth', '120', 'https://images.pokemoncard.io/images/pl4/pl4-95.png', 'unlimited: Legal', 'X', 'Arceus LV.X', '493', 'TPCI', 'Rare Holo LV.X', '', '11/04/2009', '', 'Colorless', '[\'You may have as many of this card in your deck as you like.\', \'Put this card onto your Active Arceus. Arceus LV.X can use any attack, Poké-Power, or Poké-Body from its previous level.\']', 'Platinum', '95', 'Level-Up', 'Pokémon', 'Colorless', ''),
('pl4-96', '[{\'name\': \'Multitype\', \'text\': \"Arceus LV.X\'s type is the same type as its previous Level.\", \'type\': \'Poké-Body\'}]', '', 'Ryo Ueda', '[{\'name\': \'Psychic Bolt\', \'cost\': [\'Lightning\', \'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'100\', \'text\': \'Discard a Lightning Energy and a Psychic Energy attached to Arceus.\'}]', 'Arceus', '1', 'Arceus', '', '', 'Fourth', '120', 'https://images.pokemoncard.io/images/pl4/pl4-96.png', 'unlimited: Legal', 'X', 'Arceus LV.X', '493', 'TPCI', 'Rare Holo LV.X', '', '11/04/2009', '', 'Colorless', '[\'You may have as many of this card in your deck as you like.\', \'Put this card onto your Active Arceus. Arceus LV.X can use any attack, Poké-Power, or Poké-Body from its previous level.\']', 'Platinum', '96', 'Level-Up', 'Pokémon', 'Colorless', ''),
('pl4-97', '[{\'name\': \'Level-Down\', \'text\': \"Once during your turn (before your attack), you may choose 1 of your opponent\'s Pokémon LV.X. Remove the Level-Up card from that Pokémon and have your opponent shuffle that card into his or her deck. The power can\'t be used if Gengar is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Shizurow', '[{\'name\': \'Compound Pain\', \'cost\': [\'Psychic\', \'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'\', \'text\': \"This attack does 30 damage to each of your opponent\'s Pokémon that already has any damage counters on it. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'Arceus', '', 'Gengar', '', '', 'Fourth', '140', 'https://images.pokemoncard.io/images/pl4/pl4-97.png', 'unlimited: Legal', 'X', 'Gengar LV.X', '94', 'TPCI', 'Rare Holo LV.X', '', '11/04/2009', 'type: Colorless, value: -20', '', '[\'Put this card onto your Active Gengar. Gengar LV.X can use any attack, Poké-Power, or Poké-Body from its previous level.\']', 'Platinum', '97', 'Level-Up', 'Pokémon', 'Psychic', 'type: Darkness, value: ×2'),
('pl4-98', '[{\'name\': \'Double Fall\', \'text\': \"Once during your turn (before your attack), when you put Salamence LV.X from your hand onto your Active Salamence, you may use this power. For each of your opponent\'s Pokémon that is Knocked Out by damage from Salamence\'s attacks this turn, take 1 more Prize card.\", \'type\': \'Poké-Power\'}]', '', 'Ryo Ueda', '[{\'name\': \'Steam Blast\', \'cost\': [\'Fire\', \'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'100\', \'text\': \'Discard an Energy card attached to Salamence.\'}]', 'Arceus', '2', 'Salamence', '', '', 'Fourth', '160', 'https://images.pokemoncard.io/images/pl4/pl4-98.png', 'unlimited: Legal', 'X', 'Salamence LV.X', '373', 'TPCI', 'Rare Holo LV.X', '', '11/04/2009', 'type: Fighting, value: -20', 'Colorless, Colorless', '[\'Put this card onto your Active Salamence. Salamence LV.X can use any attack, Poké-Power, or Poké-Body from its previous level.\']', 'Platinum', '98', 'Level-Up', 'Pokémon', 'Colorless', 'type: Colorless, value: ×2'),
('pl4-99', '[{\'name\': \'Healing Growth\', \'text\': \"Once during your turn (before your attack), you may flip a coin. If heads, remove 4 damage counters from 1 of your Pokémon. This power can\'t be used if Tangrowth is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Ryo Ueda', '[{\'name\': \'Big Growth\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Search your discard pile for as many Grass Energy cards as you like and attach them to your Pokémon in any way you like.\'}]', 'Arceus', '3', 'Tangrowth', '', '', 'Fourth', '130', 'https://images.pokemoncard.io/images/pl4/pl4-99.png', 'unlimited: Legal', 'X', 'Tangrowth LV.X', '465', 'TPCI', 'Rare Holo LV.X', '', '11/04/2009', 'type: Water, value: -20', 'Colorless, Colorless, Colorless', '[\'Put this card onto your Active Tangrowth. Tangrowth LV.X can use any attack, Poké-Power, or Poké-Body from its previous level.\']', 'Platinum', '99', 'Level-Up', 'Pokémon', 'Grass', 'type: Fire, value: ×2');
INSERT INTO `cards` (`id`, `abilities`, `ancient_trait`, `artist`, `attacks`, `card_set`, `converted`, `evolves_from`, `evolves_to`, `flavor_text`, `generation`, `hp`, `img`, `legalities`, `level`, `name`, `national_pokedex_numbers`, `publisher`, `rarity`, `regulation_mark`, `release_date`, `resistances`, `retreat_cost`, `rules`, `series`, `set_num`, `subtypes`, `supertype`, `types`, `weakness`) VALUES
('pl4-AR1', '', '', 'kawayoo', '[{\'name\': \'Prize Count\', \'cost\': [\'Darkness\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20+\', \'text\': \'If you have more Prize cards left than your opponent, this attack does 20 damage plus 60 more damage.\'}]', 'Arceus', '1', '', '', 'It is told in mythology that this Pokémon was born before the universe even existed.', 'Fourth', '70', 'https://images.pokemoncard.io/images/pl4/pl4-AR1.png', 'unlimited: Legal', '100', 'Arceus', '493', 'TPCI', 'Rare', '', '11/04/2009', 'type: Psychic, value: -20', 'Colorless', '[\'You may have as many of this card in your deck as you like.\']', 'Platinum', 'AR1', 'Basic', 'Pokémon', 'Darkness', 'type: Fighting, value: ×2'),
('pl4-AR2', '', '', 'Shin Nagasawa', '[{\'name\': \'Leaf Refresh\', \'cost\': [\'Grass\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'Remove 3 damage counters from each of your Benched Pokémon.\'}]', 'Arceus', '2', '', '', 'It is said to have emerged from an egg in a place where there was nothing, then shaped the world.', 'Fourth', '90', 'https://images.pokemoncard.io/images/pl4/pl4-AR2.png', 'unlimited: Legal', '100', 'Arceus', '493', 'TPCI', 'Rare', '', '11/04/2009', 'type: Water, value: -20', 'Colorless, Colorless', '[\'You may have as many of this card in your deck as you like.\']', 'Platinum', 'AR2', 'Basic', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('pl4-AR3', '', '', 'Wataru Kawahara', '[{\'name\': \'Bright Flame\', \'cost\': [\'Fire\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'80\', \'text\': \'Flip a coin. If tails, discard 2 Energy attached to Arceus.\'}]', 'Arceus', '1', '', '', 'It is described in mythology as the Pokémon that shaped the universe with its 1,000 arms.', 'Fourth', '80', 'https://images.pokemoncard.io/images/pl4/pl4-AR3.png', 'unlimited: Legal', '100', 'Arceus', '493', 'TPCI', 'Rare', '', '11/04/2009', '', 'Colorless', '[\'You may have as many of this card in your deck as you like.\']', 'Platinum', 'AR3', 'Basic', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('pl4-AR4', '', '', 'Kouki Saitou', '[{\'name\': \'Fastwave\', \'cost\': [\'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50\', \'text\': \"This attack\'s damage isn\'t affected by Resistance, Poké-Powers, Poké-Bodies, or any other effects on the Defending Pokémon.\"}]', 'Arceus', '2', '', '', 'It is told in mythology that this Pokémon was born before the universe even existed.', 'Fourth', '90', 'https://images.pokemoncard.io/images/pl4/pl4-AR4.png', 'unlimited: Legal', '100', 'Arceus', '493', 'TPCI', 'Rare', '', '11/04/2009', '', 'Colorless, Colorless', '[\'You may have as many of this card in your deck as you like.\']', 'Platinum', 'AR4', 'Basic', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('pl4-AR5', '', '', 'Mitsuhiro Arita', '[{\'name\': \'Ripple Swell\', \'cost\': [], \'convertedEnergyCost\': 0, \'damage\': \'\', \'text\': \'If you have 6 Arceus in play and each of them is a different type, search your deck for up to 6 basic Energy cards. Attach each of those Energy cards to a different Pokémon you have in play. Shuffle your deck afterward.\'}, {\'name\': \'Sky Spear\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'\', \'text\': \"Choose 1 of your opponent\'s Pokémon. This attack does 80 damage to that Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.) Remove all Energy cards attached to Arceus and put them in the Lost Zone.\"}]', 'Arceus', '1', '', '', 'It is said to have emerged from an egg in a place where there was nothing, then shaped the world.', 'Fourth', '80', 'https://images.pokemoncard.io/images/pl4/pl4-AR5.png', 'unlimited: Legal', '100', 'Arceus', '493', 'TPCI', 'Rare', '', '11/04/2009', '', 'Colorless', '[\'You may have as many of this card in your deck as you like.\']', 'Platinum', 'AR5', 'Basic', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('pl4-AR6', '', '', 'Wataru Kawahara', '[{\'name\': \'Lightning Turn\', \'cost\': [\'Lightning\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'Switch Arceus with 1 of your Benched Pokémon.\'}]', 'Arceus', '1', '', '', 'It is described in mythology as the Pokémon that shaped the universe with its 1,000 arms.', 'Fourth', '70', 'https://images.pokemoncard.io/images/pl4/pl4-AR6.png', 'unlimited: Legal', '100', 'Arceus', '493', 'TPCI', 'Rare', '', '11/04/2009', 'type: Metal, value: -20', 'Colorless', '[\'You may have as many of this card in your deck as you like.\']', 'Platinum', 'AR6', 'Basic', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
('pl4-AR7', '', '', 'Kagemaru Himeno', '[{\'name\': \'Mind Bend\', \'cost\': [\'Psychic\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40\', \'text\': \'The Defending Pokémon is now Confused.\'}]', 'Arceus', '1', '', '', 'It is told in mythology that this Pokémon was born before the universe even existed.', 'Fourth', '80', 'https://images.pokemoncard.io/images/pl4/pl4-AR7.png', 'unlimited: Legal', '100', 'Arceus', '493', 'TPCI', 'Rare', '', '11/04/2009', '', 'Colorless', '[\'You may have as many of this card in your deck as you like.\']', 'Platinum', 'AR7', 'Basic', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2'),
('pl4-AR8', '', '', 'Hajime Kusajima', '[{\'name\': \'Break Ground\', \'cost\': [\'Fighting\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60\', \'text\': \"Does 10 damage to each of your Benched Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'Arceus', '2', '', '', 'It is said to have emerged from an egg in a place where there was nothing, then shaped the world.', 'Fourth', '80', 'https://images.pokemoncard.io/images/pl4/pl4-AR8.png', 'unlimited: Legal', '100', 'Arceus', '493', 'TPCI', 'Rare', '', '11/04/2009', 'type: Lightning, value: -20', 'Colorless, Colorless', '[\'You may have as many of this card in your deck as you like.\']', 'Platinum', 'AR8', 'Basic', 'Pokémon', 'Fighting', 'type: Water, value: ×2'),
('pl4-AR9', '', '', 'TOKIYA', '[{\'name\': \'Metal Barrier\', \'cost\': [\'Metal\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40\', \'text\': \"Prevent all effects of attacks, including damage, done to Arceus by Pokémon LV.X during your opponent\'s next turn.\"}]', 'Arceus', '2', '', '', 'It is described in mythology as the Pokémon that shaped the universe with its 1,000 arms.', 'Fourth', '90', 'https://images.pokemoncard.io/images/pl4/pl4-AR9.png', 'unlimited: Legal', '100', 'Arceus', '493', 'TPCI', 'Rare', '', '11/04/2009', 'type: Psychic, value: -20', 'Colorless, Colorless', '[\'You may have as many of this card in your deck as you like.\']', 'Platinum', 'AR9', 'Basic', 'Pokémon', 'Metal', 'type: Fire, value: ×2'),
('pl4-SH10', '[{\'name\': \'Star Barrier\', \'text\': \'As long as Bagon has any Energy attached to it, Bagon has no Weakness.\', \'type\': \'Poké-Body\'}]', '', 'Naoyo Kimura', '[{\'name\': \'Dragon Rage\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'40\', \'text\': \'Flip 2 coins. If either of them is tails, this attack does nothing.\'}]', 'Arceus', '1', '', 'Shelgon', 'Dreaming of one day flying, it practices by leaping off cliffs every day.', 'Fourth', '50', 'https://images.pokemoncard.io/images/pl4/pl4-SH10.png', 'unlimited: Legal', '15', 'Bagon', '371', 'TPCI', 'Rare', '', '11/04/2009', '', 'Colorless', '', 'Platinum', 'SH10', 'Basic', 'Pokémon', 'Colorless', 'type: Colorless, value: +10'),
('pl4-SH11', '[{\'name\': \'Star Barrier\', \'text\': \'As long as Ponyta has any Energy attached to it, Ponyta has no Weakness.\', \'type\': \'Poké-Body\'}]', '', 'Kanako Eo', '[{\'name\': \'Blue Fire\', \'cost\': [\'Fire\', \'Fire\'], \'convertedEnergyCost\': 2, \'damage\': \'50\', \'text\': \'Discard all Fire Energy attached to Ponyta.\'}]', 'Arceus', '1', '', 'Rapidash', 'As a newborn, it can barely stand. However, through galloping, its legs are made tougher and faster.', 'Fourth', '60', 'https://images.pokemoncard.io/images/pl4/pl4-SH11.png', 'unlimited: Legal', '17', 'Ponyta', '77', 'TPCI', 'Rare', '', '11/04/2009', '', 'Colorless', '', 'Platinum', 'SH11', 'Basic', 'Pokémon', 'Fire', 'type: Water, value: +10'),
('pl4-SH12', '[{\'name\': \'Star Barrier\', \'text\': \'As long as Shinx has any Energy attached to it, Shinx has no Weakness.\', \'type\': \'Poké-Body\'}]', '', 'sui', '[{\'name\': \'Payback\', \'cost\': [\'Lightning\'], \'convertedEnergyCost\': 1, \'damage\': \'10+\', \'text\': \'If your opponent has only 1 Prize card left, this attack does 10 damage plus 30 more damage.\'}]', 'Arceus', '1', '', 'Luxio', 'The extension and contraction of its muscles generates electricity. It glows when in trouble.', 'Fourth', '50', 'https://images.pokemoncard.io/images/pl4/pl4-SH12.png', 'unlimited: Legal', '11', 'Shinx', '403', 'TPCI', 'Rare', '', '11/04/2009', 'type: Metal, value: -20', 'Colorless', '', 'Platinum', 'SH12', 'Basic', 'Pokémon', 'Lightning', 'type: Fighting, value: +10'),
('pop1-1', '', '', 'Katsura Tabata', '[{\'name\': \'Fire Punch\', \'cost\': [\'Fire\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'40\', \'text\': \'\'}, {\'name\': \'Double Kick\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50×\', \'text\': \'Flip 2 coins. This attack does 50 damage times the number of heads.\'}]', 'POP Series 1', '2', 'Combusken', '', '', 'Third', '110', 'https://images.pokemoncard.io/images/pop1/pop1-1.png', 'unlimited: Legal', '', 'Blaziken', '257', 'TPCI', 'Rare', '', '09/01/2004', '', 'Colorless, Colorless', '', 'POP', '1', 'Stage 2', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
