('pop2-8', '', '', 'Ken Sugimori', '', 'POP Series 2', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/pop2/pop2-8.png', 'unlimited: Legal', '', 'Mr. Brineys Compassion', '', 'TPCI', 'Uncommon', '', '08/01/2005', '', '', '[\'You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.\', \'Choose 1 of your Pokémon in play (excluding Pokémon-ex). Return that Pokémon and all cards attached to it to your hand.\']', 'POP', '8', 'Supporter', 'Trainer', '', ''),
('pop2-9', '', '', 'Big Mama Tagawa', '[{\'name\': \'Paralyzing Gaze\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'The Defending Pokémon is now Paralyzed.\'}]', 'POP Series 2', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/pop2/pop2-9.png', 'unlimited: Legal', '', 'Multi Technical Machine 01', '', 'TPCI', 'Uncommon', '', '08/01/2005', '', '', '[\"Attach this card to 1 of your Pokémon in play. That Pokémon may use this card\'s attack instead of its own. At the end of your turn, discard Multi Technical Machine 01.\"]', 'POP', '9', 'Technical Machine', 'Trainer', '', ''),
('pop3-1', '', '', 'Mitsuhiro Arita', '[{\'name\': \'Smash Turn\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'After your attack, you may switch Blastoise with 1 of your Benched Pokémon.\'}, {\'name\': \'Rocket Tackle\', \'cost\': [\'Water\', \'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'60\', \'text\': \"Blastoise does 10 damage to itself. Flip a coin. If heads, prevent all damage done to Blastoise by attacks during your opponent\'s next turn.\"}]', 'POP Series 3', '2', 'Wartortle', '', '', 'Third', '120', 'https://images.pokemoncard.io/images/pop3/pop3-1.png', 'unlimited: Legal', '', 'Blastoise', '9', 'TPCI', 'Rare', '', '04/01/2006', '', 'Colorless, Colorless', '', 'POP', '1', 'Stage 2', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('pop3-10', '', '', 'Ken Ikuji', '', 'POP Series 3', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/pop3/pop3-10.png', 'unlimited: Legal', '', 'High Pressure System', '', 'TPCI', 'Uncommon', '', '04/01/2006', '', '', '[\"This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can\'t play this card.\", \'Each player pays Colorless less to retreat his or her Fire and Water Pokémon.\']', 'POP', '10', 'Stadium', 'Trainer', '', ''),
('pop3-11', '', '', 'Shin-ichi Yoshikawa', '', 'POP Series 3', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/pop3/pop3-11.png', 'unlimited: Legal', '', 'Low Pressure System', '', 'TPCI', 'Uncommon', '', '04/01/2006', '', '', '[\"This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can\'t play this card.\", \"Each Grass and Lightning Pokémon in play (both yours and your opponent\'s) gets +10 HP.\"]', 'POP', '11', 'Stadium', 'Trainer', '', ''),
('pop3-12', '[{\'name\': \'Duplicate\', \'text\': \"Once during your turn (before your attack), you may search your deck for another Ditto and switch it with Ditto. (Any cards attached to Ditto, damage counters, Special Conditions, and effects on it are now on the new Pokémon.) If you do, put Ditto on top of your deck. Shuffle your deck afterward. You can\'t use more than 1 Duplicate Poké-Power each turn.\", \'type\': \'Poké-Power\'}]', '', 'Yuka Morii', '[{\'name\': \'Psybeam\', \'cost\': [\'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Confused.\'}]', 'POP Series 3', '1', '', '', '', 'Third', '60', 'https://images.pokemoncard.io/images/pop3/pop3-12.png', 'unlimited: Legal', '', 'Ditto', '132', 'TPCI', 'Common', '', '04/01/2006', '', 'Colorless', '', 'POP', '12', 'Basic', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2'),
('pop3-13', '', '', 'Masakazu Fukuda', '[{\'name\': \'Tackle\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'\'}, {\'name\': \'Take Down\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'Eevee does 10 damage to itself.\'}]', 'POP Series 3', '1', '', 'Vaporeon, Jolteon, Flareon, Sylveon, Espeon, Umbreon, Leafeon, Glaceon', '', 'Third', '50', 'https://images.pokemoncard.io/images/pop3/pop3-13.png', 'unlimited: Legal', '', 'Eevee', '133', 'TPCI', 'Common', '', '04/01/2006', '', 'Colorless', '', 'POP', '13', 'Basic', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('pop3-14', '', '', 'Midori Harada', '[{\'name\': \'Gouge\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10+\', \'text\': \'Flip a coin. If heads, this attack does 10 damage plus 10 more damage.\'}, {\'name\': \'Poisonpowder\', \'cost\': [\'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40\', \'text\': \'The Defending Pokémon is now Poisoned.\'}]', 'POP Series 3', '1', 'Bulbasaur', 'Venusaur', '', 'Third', '70', 'https://images.pokemoncard.io/images/pop3/pop3-14.png', 'unlimited: Legal', '', 'Ivysaur', '2', 'TPCI', 'Common', '', '04/01/2006', '', 'Colorless', '', 'POP', '14', 'Stage 1', 'Pokémon', 'Grass', 'type: Psychic, value: ×2'),
