('pop3-16', '', '', 'Kagemaru Himeno', '[{\'name\': \'Bustle\', \'cost\': [\'Lightning\', \'Lightning\'], \'convertedEnergyCost\': 2, \'damage\': \'20×\', \'text\': \'Flip 2 coins. This attack does 20 damage times the number of heads. If either coin is heads, the Defending Pokémon is now Confused.\'}]', 'POP Series 3', '1', '', 'Pikachu', '', 'Third', '60', 'https://images.pokemoncard.io/images/pop3/pop3-16.png', 'unlimited: Legal', '', 'Pichu Bros.', '172', 'TPCI', 'Common', '', '04/01/2006', '', 'Colorless', '', 'POP', '16', 'Basic', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
('pop3-17', '[{\'name\': \'Golden Wing\', \'text\': \"If Ho-Oh ex would be Knocked Out by damage from an opponent\'s attack, you may move up to 2 Energy attached to Ho-Oh ex to your Pokémon in any way you like.\", \'type\': \'Poké-Power\'}]', '', 'Mitsuhiro Arita', '[{\'name\': \'Rainbow Burn\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'10+\', \'text\': \'Does 10 damage plus 20 more damage for each type of basic Energy card attached to Ho-Oh ex.\'}]', 'POP Series 3', '2', '', '', '', 'Third', '110', 'https://images.pokemoncard.io/images/pop3/pop3-17.png', 'unlimited: Legal', '', 'Ho-Oh ex', '250', 'TPCI', 'Rare', '', '04/01/2006', '', 'Colorless, Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'POP', '17', 'Basic, EX', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
