('pop4-14', '[{\'name\': \'Shell Retreat\', \'text\': \"As long as Squirtle has any Energy cards attached to it, damage done to Squirtle by an opponent\'s attack is reduced by 10 (after applying Weakness and Resistance).\", \'type\': \'Poké-Body\'}]', '', 'Atsuko Nishida', '[{\'name\': \'Tackle\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'\'}]', 'POP Series 4', '1', '', 'Wartortle', '', 'Third', '50', 'https://images.pokemoncard.io/images/pop4/pop4-14.png', 'unlimited: Legal', '', 'Squirtle', '7', 'TPCI', 'Common', '', '08/01/2006', '', 'Colorless', '', 'POP', '14', 'Basic', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('pop4-15', '', '', 'Masakazu Fukuda', '[{\'name\': \'Pound\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'\'}, {\'name\': \'Shining Claws\', \'cost\': [\'Psychic\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Confused.\'}]', 'POP Series 4', '1', '', 'Grovyle', '', 'Third', '40', 'https://images.pokemoncard.io/images/pop4/pop4-15.png', 'unlimited: Legal', '', 'Treecko δ', '252', 'TPCI', 'Common', '', '08/01/2006', 'type: Water, value: -30', 'Colorless', '', 'POP', '15', 'Basic', 'Pokémon', 'Psychic', 'type: Fire, value: ×2'),
('pop4-16', '', '', 'Kagemaru Himeno', '[{\'name\': \'Nap\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Remove 2 damage counters from Wobbuffet.\'}, {\'name\': \'Expand\', \'cost\': [\'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \"During your opponent\'s next turn, any damage done to Wobbuffet is reduced by 20 (after applying Weakness and Resistance).\"}]', 'POP Series 4', '2', '', '', '', 'Third', '80', 'https://images.pokemoncard.io/images/pop4/pop4-16.png', 'unlimited: Legal', '', 'Wobbuffet', '202', 'TPCI', 'Common', '', '08/01/2006', '', 'Colorless, Colorless', '', 'POP', '16', 'Basic', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2'),
('pop4-17', '[{\'name\': \'Form Change\', \'text\': \"Once during your turn (before your attack), you may search your deck for another Deoxys ex and switch it with Deoxys ex. (Any cards attached to Deoxys ex, damage counters, Special Conditions, and effects on it are now on the new Pokémon.) If you do, put Deoxys ex on top of your deck. Shuffle your deck afterward. You can\'t use more than 1 Form Change Poké-Power each turn.\", \'type\': \'Poké-Power\'}]', '', 'Hiromichi Sugiyama', '[{\'name\': \'Fastwave\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50\', \'text\': \"This attack\'s damage isn\'t affected by Resistance, Poké-Powers, Poké-Bodies, or any other effects on the Defending Pokémon.\"}]', 'POP Series 4', '1', '', '', '', 'Third', '110', 'https://images.pokemoncard.io/images/pop4/pop4-17.png', 'unlimited: Legal', '', 'Deoxys ex', '386', 'TPCI', 'Rare', '', '08/01/2006', '', 'Colorless', '[\'When Pokémon-ex has been Knocked Out, your opponent takes 2 Prize cards.\']', 'POP', '17', 'Basic, EX', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2'),
('pop4-2', '[{\'name\': \'Form Change\', \'text\': \"Once during your turn (before your attack), you may search your deck for another Deoxys and switch it with Deoxys. (Any cards attached to Deoxys, damage counters, Special Conditions, and effects on it are now on the new Pokémon.) If you do, put Deoxys on top of your deck. Shuffle your deck afterward. You can\'t use more than 1 Form Change Poké-Power each turn.\", \'type\': \'Poké-Power\'}]', '', 'Kouki Saitou', '[{\'name\': \'Crystal Laser\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \"During your next turn, Deoxys\'s attacks do 40 more damage to the Defending Pokémon (before applying Weakness and Resistance).\"}]', 'POP Series 4', '1', '', '', '', 'Third', '70', 'https://images.pokemoncard.io/images/pop4/pop4-2.png', 'unlimited: Legal', '', 'Deoxys δ', '386', 'TPCI', 'Rare', '', '08/01/2006', '', 'Colorless', '', 'POP', '2', 'Basic', 'Pokémon', 'Colorless', 'type: Psychic, value: ×2'),
('pop4-3', '[{\'name\': \'Levitate\', \'text\': \'As long as Flygon has any Energy attached to it, the Retreat Cost for Flygon is 0.\', \'type\': \'Poké-Body\'}]', '', 'Hisao Nakamura', '[{\'name\': \'Bite\', \'cost\': [\'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'\'}, {\'name\': \'Sand Pit\', \'cost\': [\'Fighting\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'70\', \'text\': \"The Defending Pokémon can\'t retreat during your opponent\'s next turn.\"}]', 'POP Series 4', '2', 'Vibrava', '', '', 'Third', '120', 'https://images.pokemoncard.io/images/pop4/pop4-3.png', 'unlimited: Legal', '', 'Flygon', '330', 'TPCI', 'Rare', '', '08/01/2006', '', 'Colorless, Colorless', '', 'POP', '3', 'Stage 2', 'Pokémon', 'Fighting', 'type: Water, value: ×2'),
('pop4-4', '[{\'name\': \'Reactive Barrier\', \'text\': \"As long as Mew has any React Energy cards attached to it, prevent all effects, excluding damage, done to Mew by attacks from your opponent\'s Pokémon.\", \'type\': \'Poké-Body\'}]', '', 'Nakaoka', '[{\'name\': \'Psyshock\', \'cost\': [\'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'Flip a coin. If heads, the Defending Pokémon is now Paralyzed.\'}]', 'POP Series 4', '1', '', '', '', 'Third', '70', 'https://images.pokemoncard.io/images/pop4/pop4-4.png', 'unlimited: Legal', '', 'Mew', '151', 'TPCI', 'Rare', '', '08/01/2006', '', 'Colorless', '', 'POP', '4', 'Basic', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2'),
('pop4-5', '[{\'name\': \'Energy Trans\', \'text\': \"As often as you like during your turn (before your attack), move a Grass Energy card attached to 1 of your Pokémon to another of your Pokémon. This power can\'t be used if Sceptile is affected by a Special Condition.\", \'type\': \'Poké-Power\'}]', '', 'Atsuko Nishida', '[{\'name\': \'Tail Rap\', \'cost\': [\'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50×\', \'text\': \'Flip 2 coins. This attack does 50 damage times the number of heads.\'}]', 'POP Series 4', '3', 'Grovyle', '', '', 'Third', '100', 'https://images.pokemoncard.io/images/pop4/pop4-5.png', 'unlimited: Legal', '', 'Sceptile', '254', 'TPCI', 'Rare', '', '08/01/2006', 'type: Water, value: -30', 'Colorless, Colorless, Colorless', '', 'POP', '5', 'Stage 2', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('pop4-6', '', '', 'Mitsuhiro Arita', '[{\'name\': \'Smokescreen\', \'cost\': [\'Fire\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \"If the Defending Pokémon tries to attack during your opponent\'s next turn, your opponent flips a coin. If tails, that attack does nothing.\"}, {\'name\': \'Sky Uppercut\', \'cost\': [\'Fire\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40\', \'text\': \"This attack\'s damage isn\'t affected by Resistance.\"}]', 'POP Series 4', '1', 'Torchic', 'Blaziken', '', 'Third', '70', 'https://images.pokemoncard.io/images/pop4/pop4-6.png', 'unlimited: Legal', '', 'Combusken', '256', 'TPCI', 'Uncommon', '', '08/01/2006', '', 'Colorless', '', 'POP', '6', 'Stage 1', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('pop4-7', '', '', 'Mitsuhiro Arita', '[{\'name\': \'Quick Attack\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10+\', \'text\': \'Flip a coin. If heads, this attack does 10 damage plus 10 more damage.\'}, {\'name\': \'Blot\', \'cost\': [\'Grass\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'Remove 2 damage counters from Grovyle.\'}]', 'POP Series 4', '1', 'Treecko', 'Sceptile', '', 'Third', '70', 'https://images.pokemoncard.io/images/pop4/pop4-7.png', 'unlimited: Legal', '', 'Grovyle', '253', 'TPCI', 'Uncommon', '', '08/01/2006', 'type: Water, value: -30', 'Colorless', '', 'POP', '7', 'Stage 1', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('pop4-8', '', '', 'Takumi Akabane', '', 'POP Series 4', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/pop4/pop4-8.png', 'unlimited: Legal', '', 'Heal Energy', '', 'TPCI', 'Uncommon', '', '08/01/2006', '', '', '[\'Heal Energy provides Colorless Energy. When you attach this card from your hand to 1 of your Pokémon, remove 1 damage counter and all Special Conditions from that Pokémon. If Heal Energy is attached to Pokémon-ex, Heal Energy has no effect other than providing Energy.\']', 'POP', '8', 'Special', 'Energy', '', ''),
('pop4-9', '', '', 'Ken Sugimori', '', 'POP Series 4', '', '', '', '', 'Third', '', 'https://images.pokemoncard.io/images/pop4/pop4-9.png', 'unlimited: Legal', '', 'Pokémon Fan Club', '', 'TPCI', 'Uncommon', '', '08/01/2006', '', '', '[\'You can play only one Supporter card each turn. When you play this card, put it next to your Active Pokémon. When your turn ends, discard this card.\', \'Search your deck for up to 2 Basic Pokémon and put them onto your Bench. Shuffle your deck afterward.\']', 'POP', '9', 'Supporter', 'Trainer', '', ''),
