('sm1-146', '', '', 'Sanosuke Sakuma', '', 'Sun & Moon', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm1/sm1-146.png', 'unlimited: Legal, expanded: Legal', '', 'Ilima', '', 'TPCI', 'Rare Ultra', '', '02/03/2017', '', '', '[\'Each player shuffles their hand into their deck and flips a coin. If heads, that player draws 6 cards. If tails, they draw 3 cards.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '146', 'Supporter', 'Trainer', '', ''),
('sm1-147', '', '', 'Megumi Mizutani', '', 'Sun & Moon', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm1/sm1-147.png', 'unlimited: Legal, expanded: Legal', '', 'Lillie', '', 'TPCI', 'Rare Ultra', '', '02/03/2017', '', '', '[\"Draw cards until you have 6 cards in your hand. If it\'s your first turn, draw cards until you have 8 cards in your hand.\", \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '147', 'Supporter', 'Trainer', '', ''),
('sm1-148', '', '', 'Megumi Mizutani', '', 'Sun & Moon', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm1/sm1-148.png', 'unlimited: Legal, expanded: Legal', '', 'Professor Kukui', '', 'TPCI', 'Rare Ultra', '', '02/03/2017', '', '', '[\"Draw 2 cards. During this turn, your Pokémon\'s attacks do 20 more damage to your opponent\'s Active Pokémon (before applying Weakness and Resistance).\", \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '148', 'Supporter', 'Trainer', '', ''),
('sm1-149', '', '', 'Sanosuke Sakuma', '', 'Sun & Moon', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm1/sm1-149.png', 'unlimited: Legal, expanded: Legal', '', 'Team Skull Grunt', '', 'TPCI', 'Rare Ultra', '', '02/03/2017', '', '', '[\'Your opponent reveals their hand. Discard 2 Energy cards from it.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '149', 'Supporter', 'Trainer', '', ''),
