('sm10-183', '', '', 'aky CG Works', '', 'Unbroken Bonds', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm10/sm10-183.png', 'unlimited: Legal, expanded: Legal', '', 'Power Plant', '', 'TPCI', 'Uncommon', '', '05/03/2019', '', '', '[\"Pokémon-GX and Pokémon-EX in play (both yours and your opponent\'s) have no Abilities.\", \"This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can\'t play this card.\"]', 'Sun & Moon', '183', 'Stadium', 'Trainer', '', ''),
('sm10-184', '', '', 'Megumi Mizutani', '', 'Unbroken Bonds', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm10/sm10-184.png', 'unlimited: Legal, expanded: Legal', '', 'Reds Challenge', '', 'TPCI', 'Rare Holo', '', '05/03/2019', '', '', '[\'You can play this card only if you discard 2 other cards from your hand.\', \'Search your deck for a card and put it into your hand. Then, shuffle your deck.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '184', 'Supporter', 'Trainer', '', ''),
