('sm10-186', '', '', 'Ryo Ueda', '', 'Unbroken Bonds', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm10/sm10-186.png', 'unlimited: Legal, expanded: Legal', '', 'Stealthy Hood', '', 'TPCI', 'Uncommon', '', '05/03/2019', '', '', '[\"Attach a Pokémon Tool to 1 of your Pokémon that doesn\'t already have a Pokémon Tool attached to it.\", \"Prevent all effects of your opponent\'s Abilities done to the Pokémon this card is attached to. Remove any such existing effects.\", \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '186', 'Pokémon Tool', 'Trainer', '', ''),
('sm10-187', '', '', 'Ryo Ueda', '', 'Unbroken Bonds', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm10/sm10-187.png', 'unlimited: Legal, expanded: Legal', '', 'Surprise Box', '', 'TPCI', 'Uncommon', '', '05/03/2019', '', '', '[\"Put a card from your opponent\'s discard pile into their hand.\", \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '187', 'Item', 'Trainer', '', ''),
('sm10-188', '', '', 'Masakazu Fukuda', '', 'Unbroken Bonds', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm10/sm10-188.png', 'unlimited: Legal, expanded: Legal', '', 'Ultra Forest Kartenvoy', '', 'TPCI', 'Uncommon', '', '05/03/2019', '', '', '[\"During this turn, damage from your Ultra Beasts\' attacks isn\'t affected by any effects on your opponent\'s Active Pokémon.\", \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '188', 'Supporter', 'Trainer', '', ''),
('sm10-189', '', '', 'Hitoshi Ariga', '', 'Unbroken Bonds', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm10/sm10-189.png', 'unlimited: Legal, expanded: Legal', '', 'Welder', '', 'TPCI', 'Uncommon', '', '05/03/2019', '', '', '[\'Attach up to 2 Fire Energy cards from your hand to 1 of your Pokémon. If you do, draw 3 cards.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '189', 'Supporter', 'Trainer', '', ''),
('sm10-189a', '', '', 'Hitoshi Ariga', '', 'Unbroken Bonds', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm10/sm10-189a.png', 'unlimited: Legal, expanded: Legal', '', 'Welder', '', 'TPCI', 'Uncommon', '', '05/03/2019', '', '', '[\'Attach up to 2 Fire Energy cards from your hand to 1 of your Pokémon. If you do, draw 3 cards.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '189a', 'Supporter', 'Trainer', '', ''),
('sm10-19', '', '', 'Shin Nagasawa', '[{\'name\': \'Big Cut\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'10+\', \'text\': \'If you have exactly 4 Prize cards remaining, this attack does 120 more damage.\'}, {\'name\': \'False Swipe\', \'cost\': [\'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'\', \'text\': \"Flip a coin. If heads, put damage counters on your opponent\'s Active Pokémon until its remaining HP is 10.\"}]', 'Unbroken Bonds', '', '', '', 'This Ultra Beasts body, which is as thin as paper, is like a sharpened sword.', 'Seventh', '70', 'https://images.pokemoncard.io/images/sm10/sm10-19.png', 'unlimited: Legal, expanded: Legal', '', 'Kartana', '798', 'TPCI', 'Rare Holo', '', '05/03/2019', '', '', '', 'Sun & Moon', '19', 'Basic, Ultra Beast', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('sm10-190', '', '', '', '', 'Unbroken Bonds', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm10/sm10-190.png', 'unlimited: Legal, expanded: Legal', '', 'Triple Acceleration Energy', '', 'TPCI', 'Uncommon', '', '05/03/2019', '', '', '[\'This card can only be attached to Evolution Pokémon. If this card is attached to 1 of your Pokémon, discard it at the end of the turn.\', \'This card provides ColorlessColorlessColorless Energy only while it is attached to an Evolution Pokémon.\', \'If this card is attached to anything other than an Evolution Pokémon, discard this card.\']', 'Sun & Moon', '190', 'Special', 'Energy', '', ''),
('sm10-191', '', '', 'aky CG Works', '[{\'name\': \'Jet Punch\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'30\', \'text\': \"This attack does 30 damage to 1 of your opponent\'s Benched Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}, {\'name\': \'Elegant Sole\', \'cost\': [\'Grass\', \'Grass\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'190\', \'text\': \"During your next turn, this Pokémon\'s Elegant Sole attack\'s base damage is 60.\"}, {\'name\': \'Beast Game-GX\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'50\', \'text\': \"If your opponent\'s Pokémon is Knocked Out by damage from this attack, take 1 more Prize card. If this Pokémon has at least 7 extra Energy attached to it (in addition to this attack\'s cost), take 3 more Prize cards instead. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Unbroken Bonds', '2', '', '', '', 'Seventh', '260', 'https://images.pokemoncard.io/images/sm10/sm10-191.png', 'unlimited: Legal, expanded: Legal', '', 'Pheromosa & Buzzwole-GX', '794, 795', 'TPCI', 'Rare Ultra', '', '05/03/2019', '', 'Colorless, Colorless', '[\'TAG TEAM rule: When your TAG TEAM is Knocked Out, your opponent takes 3 Prize cards.\']', 'Sun & Moon', '191', 'Basic, TAG TEAM, GX, Ultra Beast', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
