('sm10-193', '', '', '5ban Graphics', '[{\'name\': \'Shinobi Mastery\', \'cost\': [\'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'110+\', \'text\': \"If you played Koga\'s Trap from your hand during this turn, this attack does 90 more damage. If you played Janine from your hand during this turn, prevent all damage done to this Pokémon by attacks from Basic Pokémon during your opponent\'s next turn.\"}, {\'name\': \'Ten-Card Return-GX\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'60\', \'text\': \"Shuffle your hand into your deck. Then, draw 10 cards. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Unbroken Bonds', '1', 'Venonat', '', '', 'Seventh', '200', 'https://images.pokemoncard.io/images/sm10/sm10-193.png', 'unlimited: Legal, expanded: Legal', '', 'Venomoth-GX', '49', 'TPCI', 'Rare Ultra', '', '05/03/2019', '', 'Colorless', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', '193', 'Stage 1, GX', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('sm10-194', '', '', 'aky CG Works', '[{\'name\': \'Outrage\', \'cost\': [\'Fire\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30+\', \'text\': \'This attack does 10 more damage for each damage counter on this Pokémon.\'}, {\'name\': \'Flare Strike\', \'cost\': [\'Fire\', \'Fire\', \'Fire\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'230\', \'text\': \"This Pokémon can\'t use Flare Strike during your next turn.\"}, {\'name\': \'Double Blaze-GX\', \'cost\': [\'Fire\', \'Fire\', \'Fire\'], \'convertedEnergyCost\': 3, \'damage\': \'200+\', \'text\': \"If this Pokémon has at least 3 extra Fire Energy attached to it (in addition to this attack\'s cost), this attack does 100 more damage, and this attack\'s damage isn\'t affected by any effects on your opponent\'s Active Pokémon. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Unbroken Bonds', '3', '', '', '', 'Seventh', '270', 'https://images.pokemoncard.io/images/sm10/sm10-194.png', 'unlimited: Legal, expanded: Legal', '', 'Reshiram & Charizard-GX', '6, 643', 'TPCI', 'Rare Ultra', '', '05/03/2019', '', 'Colorless, Colorless, Colorless', '[\'TAG TEAM rule: When your TAG TEAM is Knocked Out, your opponent takes 3 Prize cards.\']', 'Sun & Moon', '194', 'Basic, TAG TEAM, GX', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('sm10-195', '[{\'name\': \'Dedechange\', \'text\': \"When you play this Pokémon from your hand onto your Bench during your turn, you may discard your hand and draw 6 cards. You can\'t use more than 1 Dedechange Ability each turn.\", \'type\': \'Ability\'}]', '', '5ban Graphics', '[{\'name\': \'Static Shock\', \'cost\': [\'Lightning\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'50\', \'text\': \'\'}, {\'name\': \'Tingly Return-GX\', \'cost\': [\'Lightning\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'50\', \'text\': \"Your opponent\'s Active Pokémon is now Paralyzed. Put this Pokémon and all cards attached to it into your hand. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Unbroken Bonds', '1', '', '', '', 'Seventh', '160', 'https://images.pokemoncard.io/images/sm10/sm10-195.png', 'unlimited: Legal, expanded: Legal', '', 'Dedenne-GX', '702', 'TPCI', 'Rare Ultra', '', '05/03/2019', 'type: Metal, value: -20', 'Colorless', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', '195', 'Basic, GX', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
