('sm10-231', '', '', 'Yoshinobu Saito', '', 'Unbroken Bonds', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm10/sm10-231.png', 'unlimited: Legal, expanded: Legal', '', 'Fire Crystal', '', 'TPCI', 'Rare Secret', '', '05/03/2019', '', '', '[\'Put 3 Fire Energy cards from your discard pile into your hand.\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '231', 'Item', 'Trainer', '', ''),
('sm10-232', '', '', 'Studio Bora Inc.', '', 'Unbroken Bonds', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm10/sm10-232.png', 'unlimited: Legal, expanded: Legal', '', 'Metal Core Barrier', '', 'TPCI', 'Rare Secret', '', '05/03/2019', '', '', '[\"Attach a Pokémon Tool to 1 of your Pokémon that doesn\'t already have a Pokémon Tool attached to it.\", \"If this card is attached to 1 of your Pokémon, discard it at the end of your opponent\'s turn.\", \"The Metal Pokémon this card is attached to takes 70 less damage from your opponent\'s attacks (after applying Weakness and Resistance).\", \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '232', 'Pokémon Tool', 'Trainer', '', ''),
('sm10-233', '', '', 'Studio Bora Inc.', '', 'Unbroken Bonds', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm10/sm10-233.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Pokégear 3.0', '', 'TPCI', 'Rare Secret', '', '05/03/2019', '', '', '[\'Look at the top 7 cards of your deck. You may reveal a Supporter card you find there and put it into your hand. Shuffle the other cards back into your deck.\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '233', 'Item', 'Trainer', '', ''),
