('sm11-193', '', '', 'Ryo Ueda', '', 'Unified Minds', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm11/sm11-193.png', 'unlimited: Legal, expanded: Legal', '', 'Dark City', '', 'TPCI', 'Uncommon', '', '08/02/2019', '', '', '[\"Basic Darkness Pokémon in play (both yours and your opponent\'s) have no Retreat Cost.\", \"This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can\'t play this card.\"]', 'Sun & Moon', '193', 'Stadium', 'Trainer', '', ''),
('sm11-194', '', '', 'Toyste Beach', '', 'Unified Minds', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm11/sm11-194.png', 'unlimited: Legal, expanded: Legal', '', 'Ear-Ringing Bell', '', 'TPCI', 'Uncommon', '', '08/02/2019', '', '', '[\"Attach a Pokémon Tool to 1 of your Pokémon that doesn\'t already have a Pokémon Tool attached to it.\", \"If the Pokémon this card is attached to is your Active Pokémon and is damaged by an opponent\'s attack (even if that Pokémon is Knocked Out), the Attacking Pokémon is now Confused.\", \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '194', 'Pokémon Tool', 'Trainer', '', ''),
('sm11-195', '', '', 'aky CG Works', '[{\'name\': \'Speeding Skystrike-GX\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'180\', \'text\': \"Prevent all effects of attacks, including damage, done to this Pokémon during your opponent\'s next turn. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Unified Minds', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm11/sm11-195.png', 'unlimited: Legal, expanded: Legal', '', 'Flyinium Z: Air Slash', '', 'TPCI', 'Uncommon', '', '08/02/2019', '', '', '[\"Attach a Pokémon Tool to 1 of your Pokémon that doesn\'t already have a Pokémon Tool attached to it.\", \'If the Pokémon this card is attached to has the Air Slash attack, it can use the GX attack on this card. (You still need the necessary Energy to use this attack.)\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '195', 'Pokémon Tool', 'Trainer', '', ''),
('sm11-196', '', '', 'Studio Bora Inc.', '', 'Unified Minds', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm11/sm11-196.png', 'unlimited: Legal, expanded: Legal', '', 'Giant Bomb', '', 'TPCI', 'Uncommon', '', '08/02/2019', '', '', '[\"Attach a Pokémon Tool to 1 of your Pokémon that doesn\'t already have a Pokémon Tool attached to it.\", \"If this card is attached to 1 of your Pokémon, discard it at the end of your opponent\'s turn.\", \"If the Pokémon this card is attached to is your Active Pokémon and takes 180 or more damage from an opponent\'s attack (even if this Pokémon is Knocked Out), put 10 damage counters on the Attacking Pokémon.\", \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '196', 'Pokémon Tool', 'Trainer', '', ''),
('sm11-197', '', '', '5ban Graphics', '', 'Unified Minds', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm11/sm11-197.png', 'unlimited: Legal, expanded: Legal', '', 'Giant Hearth', '', 'TPCI', 'Uncommon', '', '08/02/2019', '', '', '[\"Once during each player\'s turn, that player may discard a card from their hand. If they do, that player searches their deck for up to 2 Fire Energy cards, reveals them, and puts them into their hand. Then, that player shuffles their deck.\", \"This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can\'t play this card.\"]', 'Sun & Moon', '197', 'Stadium', 'Trainer', '', ''),
('sm11-198', '', '', 'Yoshinobu Saito', '', 'Unified Minds', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm11/sm11-198.png', 'unlimited: Legal, expanded: Legal', '', 'Great Potion', '', 'TPCI', 'Uncommon', '', '08/02/2019', '', '', '[\'Heal 50 damage from your Active Pokémon-GX.\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '198', 'Item', 'Trainer', '', ''),
('sm11-199', '', '', 'kodama', '', 'Unified Minds', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm11/sm11-199.png', 'unlimited: Legal, expanded: Legal', '', 'Grimsley', '', 'TPCI', 'Uncommon', '', '08/02/2019', '', '', '[\"Move up to 3 damage counters from 1 of your opponent\'s Pokémon to another of their Pokémon.\", \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '199', 'Supporter', 'Trainer', '', ''),
('sm11-2', '', '', 'Eri Yamaki', '[{\'name\': \'Tackle\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'\'}, {\'name\': \'Cutting Wind\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'\'}]', 'Unified Minds', '1', '', 'Yanmega', 'Its eyes can see 360 degrees without moving its head. It wont miss prey—even those behind it.', 'Seventh', '70', 'https://images.pokemoncard.io/images/sm11/sm11-2.png', 'unlimited: Legal, expanded: Legal', '', 'Yanma', '193', 'TPCI', 'Common', '', '08/02/2019', '', 'Colorless', '', 'Sun & Moon', '2', 'Basic', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('sm11-20', '', '', 'TOKIYA', '[{\'name\': \'Sea Creeper Net\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Search your deck for a Basic Pokémon and put it onto your Bench. Then, shuffle your deck.\'}, {\'name\': \'Spinning Attack\', \'cost\': [\'Grass\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'40\', \'text\': \'\'}]', 'Unified Minds', '1', '', '', 'It wraps its prey in green seaweed and sucks away their vitality. It only likes to go after big prey like Wailord.', 'Seventh', '100', 'https://images.pokemoncard.io/images/sm11/sm11-20.png', 'unlimited: Legal, expanded: Legal', '', 'Dhelmise', '781', 'TPCI', 'Uncommon', '', '08/02/2019', '', 'Colorless', '', 'Sun & Moon', '20', 'Basic', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('sm11-200', '', '', 'Ken Sugimori', '', 'Unified Minds', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm11/sm11-200.png', 'unlimited: Legal, expanded: Legal', '', 'Hapu', '', 'TPCI', 'Uncommon', '', '08/02/2019', '', '', '[\'Look at the top 6 cards of your deck and put 2 of them into your hand. Discard the other cards.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '200', 'Supporter', 'Trainer', '', ''),
('sm11-201', '', '', 'Yoshinobu Saito', '', 'Unified Minds', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm11/sm11-201.png', 'unlimited: Legal, expanded: Legal', '', 'Karate Belt', '', 'TPCI', 'Uncommon', '', '08/02/2019', '', '', '[\"Attach a Pokémon Tool to 1 of your Pokémon that doesn\'t already have a Pokémon Tool attached to it.\", \'If you have more Prize cards remaining than your opponent, the attacks of the Pokémon this card is attached to cost Fighting less.\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '201', 'Pokémon Tool', 'Trainer', '', ''),
('sm11-202', '', '', 'Hideki Ishikawa', '', 'Unified Minds', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm11/sm11-202.png', 'unlimited: Legal, expanded: Legal', '', 'Mistys Favor', '', 'TPCI', 'Uncommon', '', '08/02/2019', '', '', '[\'Search your deck for up to 3 Supporter cards, reveal them, and put them into your hand. Then, shuffle your deck.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '202', 'Supporter', 'Trainer', '', ''),
('sm11-203', '', '', '5ban Graphics', '[{\'name\': \'Barreling Blitz-GX\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'200+\', \'text\': \"Flip a coin until you get tails. This attack does 40 more damage for each heads. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Unified Minds', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm11/sm11-203.png', 'unlimited: Legal, expanded: Legal', '', 'Normalium Z: Tackle', '', 'TPCI', 'Uncommon', '', '08/02/2019', '', '', '[\"Attach a Pokémon Tool to 1 of your Pokémon that doesn\'t already have a Pokémon Tool attached to it.\", \'If the Pokémon this card is attached to has the Tackle attack, it can use the GX attack on this card. (You still need the necessary Energy to use this attack.)\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '203', 'Pokémon Tool', 'Trainer', '', ''),
('sm11-204', '', '', 'Hitoshi Ariga', '', 'Unified Minds', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm11/sm11-204.png', 'unlimited: Legal, expanded: Legal', '', 'Poké Maniac', '', 'TPCI', 'Uncommon', '', '08/02/2019', '', '', '[\'Search your deck for up to 3 Pokémon that have a Retreat Cost of exactly 4, reveal them, and put them into your hand. Then, shuffle your deck.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '204', 'Supporter', 'Trainer', '', ''),
('sm11-205', '', '', 'aky CG Works', '', 'Unified Minds', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm11/sm11-205.png', 'unlimited: Legal, expanded: Legal', '', 'Pokémon Research Lab', '', 'TPCI', 'Uncommon', '', '08/02/2019', '', '', '[\"Once during each player\'s turn, that player may search their deck for up to 2 Pokémon that evolve from Unidentified Fossil, put those Pokémon onto their Bench, and shuffle their deck. If a player searches their deck in this way, their turn ends.\", \"This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can\'t play this card.\"]', 'Sun & Moon', '205', 'Stadium', 'Trainer', '', ''),
('sm11-206', '', '', 'sadaji', '', 'Unified Minds', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm11/sm11-206.png', 'unlimited: Legal, expanded: Banned', '', 'Reset Stamp', '', 'TPCI', 'Uncommon', '', '08/02/2019', '', '', '[\'Your opponent shuffles their hand into their deck and draws a card for each of their remaining Prize cards.\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '206', 'Item', 'Trainer', '', ''),
('sm11-206a', '', '', 'OOYAMA', '', 'Unified Minds', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm11/sm11-206a.png', 'unlimited: Legal, expanded: Banned', '', 'Reset Stamp', '', 'TPCI', 'Uncommon', '', '08/02/2019', '', '', '[\'Your opponent shuffles their hand into their deck and draws a card for each of their remaining Prize cards.\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '206a', 'Item', 'Trainer', '', ''),
('sm11-207', '', '', 'Ryo Ueda', '', 'Unified Minds', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm11/sm11-207.png', 'unlimited: Legal, expanded: Legal', '', 'Slumbering Forest', '', 'TPCI', 'Uncommon', '', '08/02/2019', '', '', '[\'If a Pokémon is Asleep, its owner flips 2 coins instead of 1 for that Special Condition between turns. If either of them is tails, that Pokémon is still Asleep.\', \"This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can\'t play this card.\"]', 'Sun & Moon', '207', 'Stadium', 'Trainer', '', ''),
('sm11-208', '', '', 'Yoshinobu Saito', '', 'Unified Minds', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm11/sm11-208.png', 'unlimited: Legal, expanded: Legal', '', 'Stadium Nav', '', 'TPCI', 'Uncommon', '', '08/02/2019', '', '', '[\'Flip 2 coins. For each heads, search your deck for a Stadium card, reveal it, and put it into your hand. Then, shuffle your deck.\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '208', 'Item', 'Trainer', '', ''),
('sm11-209', '', '', 'Yoshinobu Saito', '', 'Unified Minds', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm11/sm11-209.png', 'unlimited: Legal, expanded: Legal', '', 'Tag Switch', '', 'TPCI', 'Uncommon', '', '08/02/2019', '', '', '[\'Move up to 2 Energy from 1 of your TAG TEAM Pokémon to another of your Pokémon.\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '209', 'Item', 'Trainer', '', ''),
('sm11-21', '', '', 'Hiroki Asanuma', '[{\'name\': \'Smoke Bomb\', \'cost\': [\'Fire\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \"If the Defending Pokémon tries to attack during your opponent\'s next turn, your opponent flips a coin. If tails, that attack doesn\'t happen.\"}]', 'Unified Minds', '2', '', 'Magmortar', 'Its entire body is burning. When it breathes, the temperature rises. When it sneezes, flames shoot out!', 'Seventh', '80', 'https://images.pokemoncard.io/images/sm11/sm11-21.png', 'unlimited: Legal, expanded: Legal', '', 'Magmar', '126', 'TPCI', 'Common', '', '08/02/2019', '', 'Colorless, Colorless', '', 'Sun & Moon', '21', 'Basic', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('sm11-210', '', '', 'Toyste Beach', '', 'Unified Minds', '', '', '', '', 'Seventh', '60', 'https://images.pokemoncard.io/images/sm11/sm11-210.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Unidentified Fossil', '', 'TPCI', 'Uncommon', '', '08/02/2019', '', '', '[\'Play this card as if it were a 60-HP Colorless Basic Pokémon. At any time during your turn (before your attack), you may discard this card from play.\', \"This card can\'t retreat.\", \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '210', 'Item', 'Trainer', '', '');
