('sm11-211', '', '', 'sadaji', '', 'Unified Minds', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm11/sm11-211.png', 'unlimited: Legal, expanded: Legal', '', 'U-Turn Board', '', 'TPCI', 'Uncommon', '', '08/02/2019', '', '', '[\"Attach a Pokémon Tool to 1 of your Pokémon that doesn\'t already have a Pokémon Tool attached to it.\", \'The Retreat Cost of the Pokémon this card is attached to is Colorless less.\', \'If this card is discarded from play, put it into your hand instead of the discard pile.\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '211', 'Pokémon Tool', 'Trainer', '', ''),
('sm11-212', '', '', '', '', 'Unified Minds', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm11/sm11-212.png', 'unlimited: Legal, expanded: Legal', '', 'Recycle Energy', '', 'TPCI', 'Uncommon', '', '08/02/2019', '', '', '[\'This card provides Colorless Energy.\', \'If this card is discarded from play, put it into your hand instead of the discard pile.\']', 'Sun & Moon', '212', 'Special', 'Energy', '', ''),
('sm11-213', '', '', '', '', 'Unified Minds', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm11/sm11-213.png', 'unlimited: Legal, expanded: Legal', '', 'Weakness Guard Energy', '', 'TPCI', 'Uncommon', '', '08/02/2019', '', '', '[\'This card provides Colorless Energy.\', \'The Pokémon this card is attached to has no Weakness.\']', 'Sun & Moon', '213', 'Special', 'Energy', '', ''),
('sm11-214', '', '', 'ConceptLab', '[{\'name\': \'Super Growth\', \'cost\': [], \'convertedEnergyCost\': 0, \'damage\': \'\', \'text\': \'Search your deck for a card that evolves from 1 of your Grass Pokémon and put it onto that Pokémon to evolve it. If that Pokémon is now a Stage 1 Pokémon, search your deck for a Stage 2 Pokémon that evolves from that Pokémon and put it onto that Pokémon to evolve it. Then, shuffle your deck.\'}, {\'name\': \'Calming Hurricane\', \'cost\': [\'Grass\', \'Grass\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'150\', \'text\': \'Heal 30 damage from this Pokémon.\'}, {\'name\': \'Tropical Hour-GX\', \'cost\': [\'Grass\', \'Grass\', \'Grass\'], \'convertedEnergyCost\': 3, \'damage\': \'200\', \'text\': \"If this Pokémon has at least 3 extra Energy attached to it (in addition to this attack\'s cost), your opponent shuffles all Energy from all of their Pokémon into their deck. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Unified Minds', '3', '', 'Dartrix', '', 'Seventh', '270', 'https://images.pokemoncard.io/images/sm11/sm11-214.png', 'unlimited: Legal, expanded: Legal', '', 'Rowlet & Alolan Exeggutor-GX', '103, 722', 'TPCI', 'Rare Ultra', '', '08/02/2019', '', 'Colorless, Colorless, Colorless', '[\'TAG TEAM rule: When your TAG TEAM is Knocked Out, your opponent takes 3 Prize cards.\']', 'Sun & Moon', '214', 'Basic, TAG TEAM, GX', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('sm11-215', '', '', 'Naoyo Kimura', '[{\'name\': \'Super Growth\', \'cost\': [], \'convertedEnergyCost\': 0, \'damage\': \'\', \'text\': \'Search your deck for a card that evolves from 1 of your Grass Pokémon and put it onto that Pokémon to evolve it. If that Pokémon is now a Stage 1 Pokémon, search your deck for a Stage 2 Pokémon that evolves from that Pokémon and put it onto that Pokémon to evolve it. Then, shuffle your deck.\'}, {\'name\': \'Calming Hurricane\', \'cost\': [\'Grass\', \'Grass\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'150\', \'text\': \'Heal 30 damage from this Pokémon.\'}, {\'name\': \'Tropical Hour-GX\', \'cost\': [\'Grass\', \'Grass\', \'Grass\'], \'convertedEnergyCost\': 3, \'damage\': \'200\', \'text\': \"If this Pokémon has at least 3 extra Energy attached to it (in addition to this attack\'s cost), your opponent shuffles all Energy from all of their Pokémon into their deck. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Unified Minds', '3', '', 'Dartrix', '', 'Seventh', '270', 'https://images.pokemoncard.io/images/sm11/sm11-215.png', 'unlimited: Legal, expanded: Legal', '', 'Rowlet & Alolan Exeggutor-GX', '103, 722', 'TPCI', 'Rare Ultra', '', '08/02/2019', '', 'Colorless, Colorless, Colorless', '[\'TAG TEAM rule: When your TAG TEAM is Knocked Out, your opponent takes 3 Prize cards.\']', 'Sun & Moon', '215', 'Basic, TAG TEAM, GX', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('sm11-216', '[{\'name\': \'Burning Road\', \'text\': \'Once during your turn, when this Pokémon moves from your Bench to become your Active Pokémon, you may move any number of Fire Energy from your other Pokémon to it.\', \'type\': \'Ability\'}]', '', 'ConceptLab', '[{\'name\': \'Steaming Stomp\', \'cost\': [\'Fire\', \'Fire\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'130\', \'text\': \'\'}, {\'name\': \'Hot Burn-GX\', \'cost\': [\'Fire\'], \'convertedEnergyCost\': 1, \'damage\': \'50×\', \'text\': \"This attack does 50 damage times the amount of Fire Energy attached to this Pokémon. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Unified Minds', '3', '', '', '', 'Seventh', '190', 'https://images.pokemoncard.io/images/sm11/sm11-216.png', 'unlimited: Legal, expanded: Legal', '', 'Heatran-GX', '485', 'TPCI', 'Rare Ultra', '', '08/02/2019', '', 'Colorless, Colorless, Colorless', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', '216', 'Basic, GX', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('sm11-217', '', '', 'ConceptLab', '[{\'name\': \'Ditch and Splash\', \'cost\': [\'Water\', \'Water\'], \'convertedEnergyCost\': 2, \'damage\': \'40×\', \'text\': \'Discard any number of Supporter cards from your hand. This attack does 40 damage for each card you discarded in this way.\'}, {\'name\': \'Thrilling Times-GX\', \'cost\': [\'Water\', \'Water\'], \'convertedEnergyCost\': 2, \'damage\': \'10+\', \'text\': \"Flip a coin. If heads, this attack does 100 more damage. If this Pokémon has at least 6 extra Water Energy attached to it (in addition to this attack\'s cost), flip 10 coins instead, and this attack does 100 more damage for each heads. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Unified Minds', '2', '', 'Slowbro, Slowking', '', 'Seventh', '250', 'https://images.pokemoncard.io/images/sm11/sm11-217.png', 'unlimited: Legal, expanded: Legal', '', 'Slowpoke & Psyduck-GX', '54, 79', 'TPCI', 'Rare Ultra', '', '08/02/2019', '', 'Colorless, Colorless', '[\'TAG TEAM rule: When your TAG TEAM is Knocked Out, your opponent takes 3 Prize cards.\']', 'Sun & Moon', '217', 'Basic, TAG TEAM, GX', 'Pokémon', 'Water', 'type: Grass, value: ×2'),
('sm11-218', '', '', 'Miki Tanaka', '[{\'name\': \'Ditch and Splash\', \'cost\': [\'Water\', \'Water\'], \'convertedEnergyCost\': 2, \'damage\': \'40×\', \'text\': \'Discard any number of Supporter cards from your hand. This attack does 40 damage for each card you discarded in this way.\'}, {\'name\': \'Thrilling Times-GX\', \'cost\': [\'Water\', \'Water\'], \'convertedEnergyCost\': 2, \'damage\': \'10+\', \'text\': \"Flip a coin. If heads, this attack does 100 more damage. If this Pokémon has at least 6 extra Water Energy attached to it (in addition to this attack\'s cost), flip 10 coins instead, and this attack does 100 more damage for each heads. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Unified Minds', '2', '', 'Slowbro, Slowking', '', 'Seventh', '250', 'https://images.pokemoncard.io/images/sm11/sm11-218.png', 'unlimited: Legal, expanded: Legal', '', 'Slowpoke & Psyduck-GX', '54, 79', 'TPCI', 'Rare Ultra', '', '08/02/2019', '', 'Colorless, Colorless', '[\'TAG TEAM rule: When your TAG TEAM is Knocked Out, your opponent takes 3 Prize cards.\']', 'Sun & Moon', '218', 'Basic, TAG TEAM, GX', 'Pokémon', 'Water', 'type: Grass, value: ×2'),
('sm11-219', '[{\'name\': \'Pure Heart\', \'text\': \"Prevent all effects of attacks, including damage, done to this Pokémon by your opponent\'s Pokémon-GX or Pokémon-EX.\", \'type\': \'Ability\'}]', '', 'ConceptLab', '[{\'name\': \'Sonic Edge\', \'cost\': [\'Water\', \'Water\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'110\', \'text\': \"This attack\'s damage isn\'t affected by any effects on your opponent\'s Active Pokémon.\"}, {\'name\': \'Resolute Blade-GX\', \'cost\': [\'Water\', \'Water\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50×\', \'text\': \"This attack does 50 damage for each of your opponent\'s Benched Pokémon. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Unified Minds', '2', '', '', '', 'Seventh', '170', 'https://images.pokemoncard.io/images/sm11/sm11-219.png', 'unlimited: Legal, expanded: Legal', '', 'Keldeo-GX', '647', 'TPCI', 'Rare Ultra', '', '08/02/2019', '', 'Colorless, Colorless', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', '219', 'Basic, GX', 'Pokémon', 'Water', 'type: Grass, value: ×2'),
('sm11-22', '', '', 'KEIICHIRO ITO', '[{\'name\': \'Smoke Bomb\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'50\', \'text\': \"If the Defending Pokémon tries to attack during your opponent\'s next turn, your opponent flips a coin. If tails, that attack doesn\'t happen.\"}, {\'name\': \'Flamethrower\', \'cost\': [\'Fire\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'120\', \'text\': \'Discard an Energy from this Pokémon.\'}]', 'Unified Minds', '3', 'Magmar', '', 'There are still quite a few factories that rely on the flames provided by Magmortar to process metals.', 'Seventh', '130', 'https://images.pokemoncard.io/images/sm11/sm11-22.png', 'unlimited: Legal, expanded: Legal', '', 'Magmortar', '467', 'TPCI', 'Rare', '', '08/02/2019', '', 'Colorless, Colorless, Colorless', '', 'Sun & Moon', '22', 'Stage 1', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
