('sm11-240', '[{\'name\': \'Pure Heart\', \'text\': \"Prevent all effects of attacks, including damage, done to this Pokémon by your opponent\'s Pokémon-GX or Pokémon-EX.\", \'type\': \'Ability\'}]', '', 'ConceptLab', '[{\'name\': \'Sonic Edge\', \'cost\': [\'Water\', \'Water\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'110\', \'text\': \"This attack\'s damage isn\'t affected by any effects on your opponent\'s Active Pokémon.\"}, {\'name\': \'Resolute Blade-GX\', \'cost\': [\'Water\', \'Water\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50×\', \'text\': \"This attack does 50 damage for each of your opponent\'s Benched Pokémon. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Unified Minds', '2', '', '', '', 'Seventh', '170', 'https://images.pokemoncard.io/images/sm11/sm11-240.png', 'unlimited: Legal, expanded: Legal', '', 'Keldeo-GX', '647', 'TPCI', 'Rare Rainbow', '', '08/02/2019', '', 'Colorless, Colorless', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', '240', 'Basic, GX', 'Pokémon', 'Water', 'type: Grass, value: ×2'),
('sm11-241', '', '', 'ConceptLab', '[{\'name\': \'Tandem Shock\', \'cost\': [\'Lightning\', \'Lightning\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'80+\', \'text\': \"If this Pokémon was on the Bench and became your Active Pokémon this turn, this attack does 80 more damage, and your opponent\'s Active Pokémon is now Paralyzed.\"}, {\'name\': \'Lightning Ride-GX\', \'cost\': [\'Lightning\', \'Lightning\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'150+\', \'text\': \"Switch this Pokémon with 1 of your Benched Pokémon. If this Pokémon has at least 2 extra Lightning Energy attached to it (in addition to this attack\'s cost), this attack does 100 more damage. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Unified Minds', '2', '', '', '', 'Seventh', '260', 'https://images.pokemoncard.io/images/sm11/sm11-241.png', 'unlimited: Legal, expanded: Legal', '', 'Raichu & Alolan Raichu-GX', '26', 'TPCI', 'Rare Rainbow', '', '08/02/2019', 'type: Metal, value: -20', 'Colorless, Colorless', '[\'TAG TEAM rule: When your TAG TEAM is Knocked Out, your opponent takes 3 Prize cards.\']', 'Sun & Moon', '241', 'Basic, TAG TEAM, GX', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
('sm11-242', '[{\'name\': \'Perfection\', \'text\': \'This Pokémon can use the attacks of any Pokémon-GX or Pokémon-EX on your Bench or in your discard pile. (You still need the necessary Energy to use each attack.)\', \'type\': \'Ability\'}]', '', '5ban Graphics', '[{\'name\': \'Miraculous Duo-GX\', \'cost\': [\'Psychic\', \'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'200\', \'text\': \"If this Pokémon has at least 1 extra Energy attached to it (in addition to this attack\'s cost), heal all damage from all of your Pokémon. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Unified Minds', '2', '', '', '', 'Seventh', '270', 'https://images.pokemoncard.io/images/sm11/sm11-242.png', 'unlimited: Legal, expanded: Legal', '', 'Mewtwo & Mew-GX', '150, 151', 'TPCI', 'Rare Rainbow', '', '08/02/2019', '', 'Colorless, Colorless', '[\'TAG TEAM rule: When your TAG TEAM is Knocked Out, your opponent takes 3 Prize cards.\']', 'Sun & Moon', '242', 'Basic, TAG TEAM, GX', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2'),
('sm11-243', '[{\'name\': \'Power Bind\', \'text\': \"If you have 4 or fewer Pokémon in play, this Pokémon can\'t attack.\", \'type\': \'Ability\'}]', '', 'ConceptLab', '[{\'name\': \'Tag Purge\', \'cost\': [\'Psychic\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'120\', \'text\': \"During your opponent\'s next turn, prevent all damage done to this Pokémon by attacks from TAG TEAM Pokémon.\"}, {\'name\': \'Clear Vision-GX\', \'cost\': [\'Psychic\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"For the rest of this game, your opponent can\'t use any GX attacks. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Unified Minds', '', '', '', '', 'Seventh', '170', 'https://images.pokemoncard.io/images/sm11/sm11-243.png', 'unlimited: Legal, expanded: Legal', '', 'Latios-GX', '381', 'TPCI', 'Rare Rainbow', '', '08/02/2019', '', '', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', '243', 'Basic, GX', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2'),
('sm11-244', '[{\'name\': \'Primal Winds\', \'text\': \"As long as this Pokémon is your Active Pokémon, your opponent\'s Basic Pokémon\'s attacks cost Colorless more.\", \'type\': \'Ability\'}]', '', 'ConceptLab', '[{\'name\': \'Boulder Crush\', \'cost\': [\'Fighting\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'120\', \'text\': \'\'}, {\'name\': \'Wild Dive-GX\', \'cost\': [\'Fighting\'], \'convertedEnergyCost\': 1, \'damage\': \'50×\', \'text\': \"This attack does 50 damage times the amount of Energy attached to your opponent\'s Active Pokémon. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Unified Minds', '', 'Unidentified Fossil', '', '', 'Seventh', '210', 'https://images.pokemoncard.io/images/sm11/sm11-244.png', 'unlimited: Legal, expanded: Legal', '', 'Aerodactyl-GX', '142', 'TPCI', 'Rare Rainbow', '', '08/02/2019', '', '', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', '244', 'Stage 1, GX', 'Pokémon', 'Fighting', 'type: Grass, value: ×2'),
('sm11-245', '', '', '5ban Graphics', '[{\'name\': \'Greedy Crush\', \'cost\': [\'Darkness\', \'Darkness\', \'Darkness\', \'Darkness\', \'Colorless\'], \'convertedEnergyCost\': 5, \'damage\': \'210\', \'text\': \"If your opponent\'s Pokémon-GX or Pokémon-EX is Knocked Out by damage from this attack, take 1 more Prize card.\"}, {\'name\': \'Gigafall-GX\', \'cost\': [\'Darkness\', \'Darkness\', \'Darkness\', \'Darkness\', \'Colorless\'], \'convertedEnergyCost\': 5, \'damage\': \'250\', \'text\': \"If this Pokémon has at least 5 extra Energy attached to it (in addition to this attack\'s cost), discard the top 15 cards of your opponent\'s deck. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Unified Minds', '4', '', '', '', 'Seventh', '280', 'https://images.pokemoncard.io/images/sm11/sm11-245.png', 'unlimited: Legal, expanded: Legal', '', 'Mega Sableye & Tyranitar-GX', '248, 302', 'TPCI', 'Rare Rainbow', '', '08/02/2019', 'type: Psychic, value: -20', 'Colorless, Colorless, Colorless, Colorless', '[\'TAG TEAM rule: When your TAG TEAM is Knocked Out, your opponent takes 3 Prize cards.\']', 'Sun & Moon', '245', 'Basic, TAG TEAM, GX', 'Pokémon', 'Darkness', 'type: Fighting, value: ×2'),
('sm11-246', '[{\'name\': \'Captivating Wink\', \'text\': \'When you play this Pokémon from your hand onto your Bench during your turn, you may have your opponent reveal their hand and put any number of Basic Pokémon you find there onto their Bench.\', \'type\': \'Ability\'}]', '', 'ConceptLab', '[{\'name\': \'Wily Bite\', \'cost\': [\'Metal\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'10+\', \'text\': \"This attack does 30 more damage for each of your opponent\'s Benched Pokémon.\"}, {\'name\': \'Big Eater-GX\', \'cost\': [\'Metal\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'\', \'text\': \"Your opponent reveals their hand. Discard all Supporter cards you find there. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Unified Minds', '1', '', '', '', 'Seventh', '170', 'https://images.pokemoncard.io/images/sm11/sm11-246.png', 'unlimited: Legal, expanded: Legal', '', 'Mawile-GX', '303', 'TPCI', 'Rare Rainbow', '', '08/02/2019', 'type: Psychic, value: -20', 'Colorless', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', '246', 'Basic, GX', 'Pokémon', 'Metal', 'type: Fire, value: ×2'),
('sm11-247', '', '', 'aky CG Works', '[{\'name\': \'Linear Attack\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"This attack does 40 damage to 1 of your opponent\'s Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}, {\'name\': \'Calamitous Slash\', \'cost\': [\'Psychic\', \'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'160+\', \'text\': \"If your opponent\'s Active Pokémon already has any damage counters on it, this attack does 80 more damage.\"}, {\'name\': \'GG End-GX\', \'cost\': [\'Psychic\', \'Psychic\', \'Fighting\'], \'convertedEnergyCost\': 3, \'damage\': \'\', \'text\': \"Discard 1 of your opponent\'s Pokémon and all cards attached to it. If this Pokémon has at least 3 extra Fighting Energy attached to it (in addition to this attack\'s cost), discard 2 of your opponent\'s Pokémon instead. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Unified Minds', '3', '', '', '', 'Seventh', '270', 'https://images.pokemoncard.io/images/sm11/sm11-247.png', 'unlimited: Legal, expanded: Legal', '', 'Garchomp & Giratina-GX', '445, 487', 'TPCI', 'Rare Rainbow', '', '08/02/2019', '', 'Colorless, Colorless, Colorless', '[\'TAG TEAM rule: When your TAG TEAM is Knocked Out, your opponent takes 3 Prize cards.\']', 'Sun & Moon', '247', 'Basic, TAG TEAM, GX', 'Pokémon', 'Dragon', 'type: Fairy, value: ×2'),
('sm11-248', '', '', 'ConceptLab', '[{\'name\': \'Dragon Claw\', \'cost\': [\'Water\', \'Lightning\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'130\', \'text\': \'\'}, {\'name\': \'Sky Judgment\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 5, \'damage\': \'270\', \'text\': \'Discard 3 Energy from this Pokémon.\'}, {\'name\': \'Mach Delivery-GX\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"You may discard any number of cards from your hand until you have 9 or fewer. Draw cards until you have 10 cards in your hand. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Unified Minds', '2', 'Dragonair', '', '', 'Seventh', '250', 'https://images.pokemoncard.io/images/sm11/sm11-248.png', 'unlimited: Legal, expanded: Legal', '', 'Dragonite-GX', '149', 'TPCI', 'Rare Rainbow', '', '08/02/2019', '', 'Colorless, Colorless', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', '248', 'Stage 2, GX', 'Pokémon', 'Dragon', 'type: Fairy, value: ×2'),
('sm11-249', '[{\'name\': \'Ultra Conversion\', \'text\': \'Once during your turn (before your attack), you may discard an Ultra Beast card from your hand. If you do, draw 3 cards.\', \'type\': \'Ability\'}]', '', 'ConceptLab', '[{\'name\': \'Venom Shot\', \'cost\': [\'Psychic\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'\', \'text\': \"Discard 2 Energy from this Pokémon. This attack does 170 damage to 1 of your opponent\'s Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}, {\'name\': \'Injection-GX\', \'cost\': [\'Lightning\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Add a card from your opponent\'s discard pile to their Prize cards face down. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Unified Minds', '1', 'Poipole', '', '', 'Seventh', '210', 'https://images.pokemoncard.io/images/sm11/sm11-249.png', 'unlimited: Legal, expanded: Legal', '', 'Naganadel-GX', '804', 'TPCI', 'Rare Rainbow', '', '08/02/2019', '', 'Colorless', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', '249', 'Stage 1, GX, Ultra Beast', 'Pokémon', 'Dragon', 'type: Fairy, value: ×2'),
('sm11-25', '[{\'name\': \'Burning Road\', \'text\': \'Once during your turn, when this Pokémon moves from your Bench to become your Active Pokémon, you may move any number of Fire Energy from your other Pokémon to it.\', \'type\': \'Ability\'}]', '', 'PLANETA Tsuji', '[{\'name\': \'Steaming Stomp\', \'cost\': [\'Fire\', \'Fire\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'130\', \'text\': \'\'}, {\'name\': \'Hot Burn-GX\', \'cost\': [\'Fire\'], \'convertedEnergyCost\': 1, \'damage\': \'50×\', \'text\': \"This attack does 50 damage times the amount of Fire Energy attached to this Pokémon. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Unified Minds', '3', '', '', '', 'Seventh', '190', 'https://images.pokemoncard.io/images/sm11/sm11-25.png', 'unlimited: Legal, expanded: Legal', '', 'Heatran-GX', '485', 'TPCI', 'Rare Holo GX', '', '08/02/2019', '', 'Colorless, Colorless, Colorless', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', '25', 'Basic, GX', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('sm11-250', '', '', '5ban Graphics', '', 'Unified Minds', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm11/sm11-250.png', 'unlimited: Legal, expanded: Legal', '', 'Cherish Ball', '', 'TPCI', 'Rare Secret', '', '08/02/2019', '', '', '[\'Search your deck for a Pokémon-GX, reveal it, and put it into your hand. Then, shuffle your deck.\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '250', 'Item', 'Trainer', '', ''),
('sm11-251', '', '', 'Studio Bora Inc.', '', 'Unified Minds', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm11/sm11-251.png', 'unlimited: Legal, expanded: Legal', '', 'Giant Bomb', '', 'TPCI', 'Rare Secret', '', '08/02/2019', '', '', '[\"Attach a Pokémon Tool to 1 of your Pokémon that doesn\'t already have a Pokémon Tool attached to it.\", \"If this card is attached to 1 of your Pokémon, discard it at the end of your opponent\'s turn.\", \"If the Pokémon this card is attached to is your Active Pokémon and takes 180 or more damage from an opponent\'s attack (even if this Pokémon is Knocked Out), put 10 damage counters on the Attacking Pokémon.\", \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '251', 'Pokémon Tool', 'Trainer', '', ''),
('sm11-252', '', '', 'Yoshinobu Saito', '', 'Unified Minds', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm11/sm11-252.png', 'unlimited: Legal, expanded: Legal', '', 'Karate Belt', '', 'TPCI', 'Rare Secret', '', '08/02/2019', '', '', '[\"Attach a Pokémon Tool to 1 of your Pokémon that doesn\'t already have a Pokémon Tool attached to it.\", \'If you have more Prize cards remaining than your opponent, the attacks of the Pokémon this card is attached to cost Fighting less.\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '252', 'Pokémon Tool', 'Trainer', '', ''),
('sm11-253', '', '', 'sadaji', '', 'Unified Minds', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm11/sm11-253.png', 'unlimited: Legal, expanded: Banned', '', 'Reset Stamp', '', 'TPCI', 'Rare Secret', '', '08/02/2019', '', '', '[\'Your opponent shuffles their hand into their deck and draws a card for each of their remaining Prize cards.\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '253', 'Item', 'Trainer', '', ''),
('sm11-254', '', '', 'Yoshinobu Saito', '', 'Unified Minds', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm11/sm11-254.png', 'unlimited: Legal, expanded: Legal', '', 'Tag Switch', '', 'TPCI', 'Rare Secret', '', '08/02/2019', '', '', '[\'Move up to 2 Energy from 1 of your TAG TEAM Pokémon to another of your Pokémon.\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '254', 'Item', 'Trainer', '', ''),
('sm11-255', '', '', 'sadaji', '', 'Unified Minds', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm11/sm11-255.png', 'unlimited: Legal, expanded: Legal', '', 'U-Turn Board', '', 'TPCI', 'Rare Secret', '', '08/02/2019', '', '', '[\"Attach a Pokémon Tool to 1 of your Pokémon that doesn\'t already have a Pokémon Tool attached to it.\", \'The Retreat Cost of the Pokémon this card is attached to is Colorless less.\', \'If this card is discarded from play, put it into your hand instead of the discard pile.\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '255', 'Pokémon Tool', 'Trainer', '', ''),
('sm11-256', '', '', '5ban Graphics', '', 'Unified Minds', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm11/sm11-256.png', 'unlimited: Legal, expanded: Legal', '', 'Viridian Forest', '', 'TPCI', 'Rare Secret', '', '08/02/2019', '', '', '[\"Once during each player\'s turn, that player may discard a card from their hand. If they do, that player searches their deck for a basic Energy card, reveals it, and puts it into their hand. Then, that player shuffles their deck.\", \"This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can\'t play this card.\"]', 'Sun & Moon', '256', 'Stadium', 'Trainer', '', ''),
('sm11-257', '', '', '', '', 'Unified Minds', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm11/sm11-257.png', 'unlimited: Legal, expanded: Legal', '', 'Recycle Energy', '', 'TPCI', 'Rare Secret', '', '08/02/2019', '', '', '[\'This card provides Colorless Energy.\', \'If this card is discarded from play, put it into your hand instead of the discard pile.\']', 'Sun & Moon', '257', 'Special', 'Energy', '', ''),
('sm11-258', '', '', '', '', 'Unified Minds', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm11/sm11-258.png', 'unlimited: Legal, expanded: Legal', '', 'Weakness Guard Energy', '', 'TPCI', 'Rare Secret', '', '08/02/2019', '', '', '[\'This card provides Colorless Energy.\', \'The Pokémon this card is attached to has no Weakness.\']', 'Sun & Moon', '258', 'Special', 'Energy', '', '');
