('sm12-254', '', '', 'Hideki Ishikawa', '[{\'name\': \'Cosmic Burn\', \'cost\': [\'Psychic\', \'Psychic\', \'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'230\', \'text\': \"This Pokémon can\'t use Cosmic Burn during your next turn.\"}, {\'name\': \'Light of the Protector-GX\', \'cost\': [\'Psychic\', \'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'200\', \'text\': \"If you played Lillie\'s Full Force from your hand during this turn, prevent all effects of attacks, including damage, done to each of your Pokémon during your opponent\'s next turn. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Cosmic Eclipse', '2', '', '', '', 'Seventh', '270', 'https://images.pokemoncard.io/images/sm12/sm12-254.png', 'unlimited: Legal, expanded: Legal', '', 'Solgaleo & Lunala-GX', '791, 792', 'TPCI', 'Rare Rainbow', '', '11/01/2019', '', 'Colorless, Colorless', '[\'TAG TEAM rule: When your TAG TEAM is Knocked Out, your opponent takes 3 Prize cards.\']', 'Sun & Moon', '254', 'Basic, TAG TEAM, GX', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2'),
('sm12-255', '[{\'name\': \'Dance of Tribute\', \'text\': \"Once during your turn (before your attack), if any of your Pokémon were Knocked Out during your opponent\'s last turn, you may draw 3 cards. You can\'t use more than 1 Dance of Tribute Ability each turn.\", \'type\': \'Ability\'}]', '', 'PLANETA Tsuji', '[{\'name\': \'Razor Wing\', \'cost\': [\'Psychic\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'80\', \'text\': \'\'}, {\'name\': \'Strafe-GX\', \'cost\': [\'Psychic\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'100\', \'text\': \"Switch this Pokémon with 1 of your Benched Pokémon. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Cosmic Eclipse', '1', '', '', '', 'Seventh', '170', 'https://images.pokemoncard.io/images/sm12/sm12-255.png', 'unlimited: Legal, expanded: Legal', '', 'Oricorio-GX', '741', 'TPCI', 'Rare Rainbow', '', '11/01/2019', 'type: Fighting, value: -20', 'Colorless', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', '255', 'Basic, GX', 'Pokémon', 'Psychic', 'type: Darkness, value: ×2'),
('sm12-256', '[{\'name\': \'Dusty Defense\', \'text\': \"As long as this Pokémon is your Active Pokémon, all of your Pokémon take 30 less damage from your opponent\'s attacks (after applying Weakness and Resistance).\", \'type\': \'Ability\'}]', '', 'PLANETA Tsuji', '[{\'name\': \'Desert Hurricane\', \'cost\': [\'Fighting\', \'Fighting\', \'Fighting\'], \'convertedEnergyCost\': 3, \'damage\': \'120+\', \'text\': \'If there is any Stadium card in play, this attack does 120 more damage. Then, discard that Stadium card.\'}, {\'name\': \'Sonic Edge-GX\', \'cost\': [\'Fighting\', \'Fighting\', \'Fighting\'], \'convertedEnergyCost\': 3, \'damage\': \'220\', \'text\': \"This attack\'s damage isn\'t affected by any effects on your opponent\'s Active Pokémon. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Cosmic Eclipse', '2', 'Vibrava', '', '', 'Seventh', '240', 'https://images.pokemoncard.io/images/sm12/sm12-256.png', 'unlimited: Legal, expanded: Legal', '', 'Flygon-GX', '330', 'TPCI', 'Rare Rainbow', '', '11/01/2019', '', 'Colorless, Colorless', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', '256', 'Stage 2, GX', 'Pokémon', 'Fighting', 'type: Grass, value: ×2'),
('sm12-257', '[{\'name\': \'Smug Face\', \'text\': \"Prevent all effects of attacks, including damage, done to this Pokémon by your opponent\'s TAG TEAM Pokémon and Ultra Beasts, and by your opponent\'s Pokémon that have any Special Energy attached to them.\", \'type\': \'Ability\'}]', '', 'PLANETA Tsuji', '[{\'name\': \'Claw Slash\', \'cost\': [\'Darkness\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'120\', \'text\': \'\'}, {\'name\': \'Stalking Claws-GX\', \'cost\': [\'Darkness\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'\', \'text\': \"This attack does 120 damage to 1 of your opponent\'s Pokémon. This damage isn\'t affected by Weakness, Resistance, or any other effects on that Pokémon. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Cosmic Eclipse', '2', 'Alolan Meowth', '', '', 'Seventh', '200', 'https://images.pokemoncard.io/images/sm12/sm12-257.png', 'unlimited: Legal, expanded: Legal', '', 'Alolan Persian-GX', '53', 'TPCI', 'Rare Rainbow', '', '11/01/2019', 'type: Psychic, value: -20', 'Colorless, Colorless', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', '257', 'Stage 1, GX', 'Pokémon', 'Darkness', 'type: Fighting, value: ×2'),
('sm12-258', '', '', '5ban Graphics', '[{\'name\': \'Ultimate Ray\', \'cost\': [\'Water\', \'Metal\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'150\', \'text\': \'Search your deck for up to 3 basic Energy cards and attach them to your Pokémon in any way you like. Then, shuffle your deck.\'}, {\'name\': \'Altered Creation-GX\', \'cost\': [\'Metal\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"For the rest of this game, your Pokémon\'s attacks do 30 more damage to your opponent\'s Active Pokémon (before applying Weakness and Resistance). If this Pokémon has at least 1 extra Water Energy attached to it (in addition to this attack\'s cost), when your opponent\'s Active Pokémon is Knocked Out by damage from those attacks, take 1 more Prize card. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Cosmic Eclipse', '3', '', '', '', 'Seventh', '280', 'https://images.pokemoncard.io/images/sm12/sm12-258.png', 'unlimited: Legal, expanded: Legal', '', 'Arceus & Dialga & Palkia-GX', '483, 484, 493', 'TPCI', 'Rare Rainbow', '', '11/01/2019', '', 'Colorless, Colorless, Colorless', '[\'TAG TEAM rule: When your TAG TEAM is Knocked Out, your opponent takes 3 Prize cards.\']', 'Sun & Moon', '258', 'Basic, TAG TEAM, GX', 'Pokémon', 'Dragon', 'type: Fairy, value: ×2'),
('sm12-259', '', '', 'Naoki Saito', '[{\'name\': \'Fabled Flarebolts\', \'cost\': [\'Fire\', \'Lightning\'], \'convertedEnergyCost\': 2, \'damage\': \'90×\', \'text\': \'Discard up to 3 in any combination of basic Fire and basic Lightning Energy cards from your Benched Pokémon. This attack does 90 damage for each card you discarded in this way.\'}, {\'name\': \'Cross Break-GX\', \'cost\': [\'Fire\', \'Fire\', \'Lightning\', \'Lightning\'], \'convertedEnergyCost\': 4, \'damage\': \'\', \'text\': \"This attack does 170 damage to 1 of your opponent\'s Benched Pokémon. If you played N\'s Resolve from your hand during this turn, this attack also does 170 damage to 1 of your opponent\'s other Benched Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.) (You can\'t use more than 1 GX attack in a game.)\"}]', 'Cosmic Eclipse', '3', '', '', '', 'Seventh', '270', 'https://images.pokemoncard.io/images/sm12/sm12-259.png', 'unlimited: Legal, expanded: Legal', '', 'Reshiram & Zekrom-GX', '643, 644', 'TPCI', 'Rare Rainbow', '', '11/01/2019', '', 'Colorless, Colorless, Colorless', '[\'TAG TEAM rule: When your TAG TEAM is Knocked Out, your opponent takes 3 Prize cards.\']', 'Sun & Moon', '259', 'Basic, TAG TEAM, GX', 'Pokémon', 'Dragon', 'type: Fairy, value: ×2'),
('sm12-26', '', '', 'Ken Sugimori', '[{\'name\': \'Singe\', \'cost\': [\'Fire\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Your opponent\'s Active Pokémon is now Burned.\"}]', 'Cosmic Eclipse', '3', '', 'Magcargo', 'A common sight in volcanic areas, it slowly slithers around in a constant search for warm places.', 'Seventh', '80', 'https://images.pokemoncard.io/images/sm12/sm12-26.png', 'unlimited: Legal, expanded: Legal', '', 'Slugma', '218', 'TPCI', 'Common', '', '11/01/2019', '', 'Colorless, Colorless, Colorless', '', 'Sun & Moon', '26', 'Basic', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('sm12-260', '[{\'name\': \'Violent Appetite\', \'text\': \'Once during your turn (before your attack), you may discard a Pokémon from your hand. If you do, heal 60 damage from this Pokémon.\', \'type\': \'Ability\'}]', '', '5ban Graphics', '[{\'name\': \'Jet Pierce\', \'cost\': [\'Psychic\', \'Darkness\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'180\', \'text\': \'\'}, {\'name\': \'Chaotic Order-GX\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Turn all of your Prize cards face up. (Those Prize cards remain face up for the rest of the game.) If this Pokémon has at least 1 extra Psychic Energy and 1 extra Darkness Energy attached to it (in addition to this attack\'s cost), take 2 Prize cards. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Cosmic Eclipse', '3', '', '', '', 'Seventh', '280', 'https://images.pokemoncard.io/images/sm12/sm12-260.png', 'unlimited: Legal, expanded: Legal', '', 'Naganadel & Guzzlord-GX', '799, 804', 'TPCI', 'Rare Rainbow', '', '11/01/2019', '', 'Colorless, Colorless, Colorless', '[\'TAG TEAM rule: When your TAG TEAM is Knocked Out, your opponent takes 3 Prize cards.\']', 'Sun & Moon', '260', 'Basic, TAG TEAM, GX, Ultra Beast', 'Pokémon', 'Dragon', 'type: Fairy, value: ×2'),
('sm12-261', '', '', 'aky CG Works', '[{\'name\': \'Jumping Balloon\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60+\', \'text\': \"This attack does 60 more damage for each of your opponent\'s Pokémon-GX and Pokémon-EX in play.\"}, {\'name\': \'Puffy Smashers-GX\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Your opponent\'s Active Pokémon is now Asleep. If this Pokémon has at least 4 extra Energy attached to it (in addition to this attack\'s cost), this attack does 200 damage to 1 of your opponent\'s Benched Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.) (You can\'t use more than 1 GX attack in a game.)\"}]', 'Cosmic Eclipse', '1', '', 'Wigglytuff', '', 'Seventh', '240', 'https://images.pokemoncard.io/images/sm12/sm12-261.png', 'unlimited: Legal, expanded: Legal', '', 'Mega Lopunny & Jigglypuff-GX', '39, 428', 'TPCI', 'Rare Rainbow', '', '11/01/2019', '', 'Colorless', '[\'TAG TEAM rule: When your TAG TEAM is Knocked Out, your opponent takes 3 Prize cards.\']', 'Sun & Moon', '261', 'Basic, TAG TEAM, GX', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('sm12-262', '[{\'name\': \'Disk Reload\', \'text\': \'Once during your turn (before your attack), you may draw cards until you have 5 cards in your hand.\', \'type\': \'Ability\'}]', '', 'Megumi Mizutani', '[{\'name\': \'Brave Buddies\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'50+\', \'text\': \'If you played a Supporter card from your hand during this turn, this attack does 70 more damage.\'}, {\'name\': \'Silver Knight-GX\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'\', \'text\': \"If your opponent\'s Active Pokémon is an Ultra Beast, it is Knocked Out. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Cosmic Eclipse', '2', 'Type: Null', '', '', 'Seventh', '210', 'https://images.pokemoncard.io/images/sm12/sm12-262.png', 'unlimited: Legal, expanded: Legal', '', 'Silvally-GX', '773', 'TPCI', 'Rare Rainbow', '', '11/01/2019', '', 'Colorless, Colorless', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', '262', 'Stage 1, GX', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('sm12-263', '', '', '5ban Graphics', '', 'Cosmic Eclipse', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm12/sm12-263.png', 'unlimited: Legal, expanded: Legal', '', 'Giant Hearth', '', 'TPCI', 'Rare Secret', '', '11/01/2019', '', '', '[\"Once during each player\'s turn, that player may discard a card from their hand. If they do, that player searches their deck for up to 2 Fire Energy cards, reveals them, and puts them into their hand. Then, that player shuffles their deck.\", \"This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can\'t play this card.\"]', 'Sun & Moon', '263', 'Stadium', 'Trainer', '', ''),
('sm12-264', '', '', 'Studio Bora Inc.', '', 'Cosmic Eclipse', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm12/sm12-264.png', 'unlimited: Legal, expanded: Legal', '', 'Great Catcher', '', 'TPCI', 'Rare Secret', '', '11/01/2019', '', '', '[\'You can play this card only if you discard 2 other cards from your hand.\', \"Switch 1 of your opponent\'s Benched Pokémon-GX or Pokémon-EX with their Active Pokémon.\", \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '264', 'Item', 'Trainer', '', ''),
('sm12-265', '', '', 'sadaji', '', 'Cosmic Eclipse', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm12/sm12-265.png', 'unlimited: Legal, expanded: Banned', '', 'Island Challenge Amulet', '', 'TPCI', 'Rare Secret', '', '11/01/2019', '', '', '[\"Attach a Pokémon Tool to 1 of your Pokémon that doesn\'t already have a Pokémon Tool attached to it.\", \"The Pokémon-GX or Pokémon-EX this card is attached to gets -100 HP, and when it is Knocked Out by damage from an opponent\'s attack, that player takes 1 fewer Prize card.\", \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '265', 'Pokémon Tool', 'Trainer', '', ''),
('sm12-266', '', '', 'Eske Yoshinob', '', 'Cosmic Eclipse', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm12/sm12-266.png', 'unlimited: Legal, expanded: Legal', '', 'Lanas Fishing Rod', '', 'TPCI', 'Rare Secret', '', '11/01/2019', '', '', '[\'Shuffle a Pokémon and a Pokémon Tool card from your discard pile into your deck.\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '266', 'Item', 'Trainer', '', ''),
('sm12-267', '', '', 'Studio Bora Inc.', '', 'Cosmic Eclipse', '', '', '', '', 'Seventh', '30', 'https://images.pokemoncard.io/images/sm12/sm12-267.png', 'unlimited: Legal, expanded: Legal', '', 'Lillies Poké Doll', '', 'TPCI', 'Rare Secret', '', '11/01/2019', '', '', '[\'Play this card as if it were a 30-HP Colorless Basic Pokémon. At any time during your turn (before your attack), if this Pokémon is your Active Pokémon, you may discard all cards from it and put it on the bottom of your deck.\', \"This card can\'t retreat. If this card is Knocked Out, your opponent can\'t take any Prize cards for it.\", \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '267', 'Item', 'Trainer', '', ''),
('sm12-268', '', '', '5ban Graphics', '', 'Cosmic Eclipse', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm12/sm12-268.png', 'unlimited: Legal, expanded: Legal', '', 'Martial Arts Dojo', '', 'TPCI', 'Rare Secret', '', '11/01/2019', '', '', '[\"The attacks of non-Ultra Beast Pokémon that have any basic Fighting Energy attached to them (both yours and your opponent\'s) do 10 more damage to the opponent\'s Active Pokémon (before applying Weakness and Resistance). If the attacking player has more Prize cards remaining than their opponent, those attacks do 40 more damage instead.\", \"This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can\'t play this card.\"]', 'Sun & Moon', '268', 'Stadium', 'Trainer', '', ''),
('sm12-269', '', '', 'aky CG Works', '', 'Cosmic Eclipse', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm12/sm12-269.png', 'unlimited: Legal, expanded: Legal', '', 'Power Plant', '', 'TPCI', 'Rare Secret', '', '11/01/2019', '', '', '[\"Pokémon-GX and Pokémon-EX in play (both yours and your opponent\'s) have no Abilities.\", \"This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can\'t play this card.\"]', 'Sun & Moon', '269', 'Stadium', 'Trainer', '', ''),
('sm12-27', '', '', 'Miki Tanaka', '[{\'name\': \'Stomp Off\', \'cost\': [\'Fire\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Discard the top 2 cards of your opponent\'s deck.\"}, {\'name\': \'Flamethrower\', \'cost\': [\'Fire\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'80\', \'text\': \'Discard an Energy from this Pokémon.\'}]', 'Cosmic Eclipse', '3', 'Slugma', '', 'Its brittle shell occasionally spouts intense flames that circulate throughout its body.', 'Seventh', '120', 'https://images.pokemoncard.io/images/sm12/sm12-27.png', 'unlimited: Legal, expanded: Legal', '', 'Magcargo', '219', 'TPCI', 'Rare', '', '11/01/2019', '', 'Colorless, Colorless, Colorless', '', 'Sun & Moon', '27', 'Stage 1', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('sm12-270', '', '', 'Toyste Beach', '', 'Cosmic Eclipse', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm12/sm12-270.png', 'unlimited: Legal, expanded: Legal', '', 'Tag Call', '', 'TPCI', 'Rare Secret', '', '11/01/2019', '', '', '[\'Search your deck for up to 2 TAG TEAM cards, reveal them, and put them into your hand. Then, shuffle your deck.\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '270', 'Item', 'Trainer', '', ''),
('sm12-271', '', '', '', '', 'Cosmic Eclipse', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm12/sm12-271.png', 'unlimited: Legal, expanded: Legal', '', 'Draw Energy', '', 'TPCI', 'Rare Secret', '', '11/01/2019', '', '', '[\'This card provides Colorless Energy.\', \'When you attach this card from your hand to a Pokémon, draw a card.\']', 'Sun & Moon', '271', 'Special', 'Energy', '', ''),
('sm12-28', '', '', 'Shin Nagasawa', '[{\'name\': \'Rally Back\', \'cost\': [\'Fire\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30+\', \'text\': \"If any of your Pokémon were Knocked Out by damage from an opponent\'s attack during their last turn, this attack does 90 more damage.\"}, {\'name\': \'Fire Mane\', \'cost\': [\'Fire\', \'Fire\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'100\', \'text\': \'\'}]', 'Cosmic Eclipse', '2', '', '', 'A Pokémon that races across the land. It is said that one is born every time a new volcano appears.', 'Seventh', '130', 'https://images.pokemoncard.io/images/sm12/sm12-28.png', 'unlimited: Legal, expanded: Legal', '', 'Entei', '244', 'TPCI', 'Rare', '', '11/01/2019', '', 'Colorless, Colorless', '', 'Sun & Moon', '28', 'Basic', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('sm12-29', '', '', '313', '[{\'name\': \'Fire Fling\', \'cost\': [\'Fire\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Put 4 Fire Energy cards from your discard pile into your hand.\'}, {\'name\': \'Kindle\', \'cost\': [\'Fire\', \'Fire\', \'Fire\'], \'convertedEnergyCost\': 3, \'damage\': \'100\', \'text\': \"Discard an Energy from this Pokémon. If you do, discard an Energy from your opponent\'s Active Pokémon.\"}]', 'Cosmic Eclipse', '2', '', '', 'You can tell how its feeling by the smoke spouting from its shell. Tremendous velocity is a sign of good health.', 'Seventh', '110', 'https://images.pokemoncard.io/images/sm12/sm12-29.png', 'unlimited: Legal, expanded: Legal', '', 'Torkoal', '324', 'TPCI', 'Uncommon', '', '11/01/2019', '', 'Colorless, Colorless', '', 'Sun & Moon', '29', 'Basic', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('sm12-3', '', '', 'sui', '[{\'name\': \'Sleep Powder\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'20\', \'text\': \"Your opponent\'s Active Pokémon is now Asleep.\"}]', 'Cosmic Eclipse', '2', 'Oddish', 'Vileplume, Bellossom', 'Smells incredibly foul! However, around one out of a thousand people enjoy sniffing its nose-bending stink.', 'Seventh', '80', 'https://images.pokemoncard.io/images/sm12/sm12-3.png', 'unlimited: Legal, expanded: Legal', '', 'Gloom', '44', 'TPCI', 'Uncommon', '', '11/01/2019', '', 'Colorless, Colorless', '', 'Sun & Moon', '3', 'Stage 1', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('sm12-30', '[{\'name\': \'Victory Heal\', \'text\': \'Once during your turn (before your attack), you may heal 20 damage from 1 of your Benched Pokémon.\', \'type\': \'Ability\'}]', '', 'Saya Tsuruta', '[{\'name\': \'Combustion\', \'cost\': [\'Fire\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'\'}]', 'Cosmic Eclipse', '1', '', '', 'This Pokémon brings victory. It is said that Trainers with Victini always win, regardless of the type of encounter.', 'Seventh', '70', 'https://images.pokemoncard.io/images/sm12/sm12-30.png', 'unlimited: Legal, expanded: Legal', '', 'Victini', '494', 'TPCI', 'Rare Holo', '', '11/01/2019', '', 'Colorless', '', 'Sun & Moon', '30', 'Basic', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('sm12-31', '', '', 'Mina Nakai', '[{\'name\': \'Live Coal\', \'cost\': [\'Fire\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'\'}, {\'name\': \'Rollout\', \'cost\': [\'Fire\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40\', \'text\': \'\'}]', 'Cosmic Eclipse', '2', '', 'Pignite', 'It can deftly dodge its foes attacks while shooting fireballs from its nose. It roasts berries before it eats them.', 'Seventh', '80', 'https://images.pokemoncard.io/images/sm12/sm12-31.png', 'unlimited: Legal, expanded: Legal', '', 'Tepig', '498', 'TPCI', 'Common', '', '11/01/2019', '', 'Colorless, Colorless', '', 'Sun & Moon', '31', 'Basic', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('sm12-32', '', '', 'Naoyo Kimura', '[{\'name\': \'Tackle\', \'cost\': [\'Fire\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'\'}, {\'name\': \'Heat Crash\', \'cost\': [\'Fire\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60\', \'text\': \'\'}]', 'Cosmic Eclipse', '4', 'Tepig', 'Emboar', 'The more it eats, the more fuel it has to make the fire in its stomach stronger. This fills it with even more power.', 'Seventh', '110', 'https://images.pokemoncard.io/images/sm12/sm12-32.png', 'unlimited: Legal, expanded: Legal', '', 'Pignite', '499', 'TPCI', 'Uncommon', '', '11/01/2019', '', 'Colorless, Colorless, Colorless, Colorless', '', 'Sun & Moon', '32', 'Stage 1', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('sm12-33', '[{\'name\': \'Explosive Fire Dance\', \'text\': \'When you play this Pokémon from your hand to evolve 1 of your Pokémon during your turn, you may look at the top 8 cards of your deck and attach any number of basic Energy cards you find there to your Pokémon in any way you like. Shuffle the other cards back into your deck.\', \'type\': \'Ability\'}]', '', 'kawayoo', '[{\'name\': \'Heat Blast\', \'cost\': [\'Fire\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'160\', \'text\': \'\'}]', 'Cosmic Eclipse', '4', 'Pignite', '', 'It can throw a fire punch by setting its fists on fire with its fiery chin. It cares deeply about its friends.', 'Seventh', '170', 'https://images.pokemoncard.io/images/sm12/sm12-33.png', 'unlimited: Legal, expanded: Legal', '', 'Emboar', '500', 'TPCI', 'Rare', '', '11/01/2019', '', 'Colorless, Colorless, Colorless, Colorless', '', 'Sun & Moon', '33', 'Stage 2', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('sm12-34', '', '', 'Akira Komayama', '[{\'name\': \'Ram\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'\'}, {\'name\': \'Combustion\', \'cost\': [\'Fire\', \'Fire\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50\', \'text\': \'\'}]', 'Cosmic Eclipse', '3', '', 'Volcarona', 'When battling opponents, it sprays fire from its five horns. The max temperature of the flames can reach nearly 5,500 degrees Fahrenheit.', 'Seventh', '80', 'https://images.pokemoncard.io/images/sm12/sm12-34.png', 'unlimited: Legal, expanded: Legal', '', 'Larvesta', '636', 'TPCI', 'Uncommon', '', '11/01/2019', '', 'Colorless, Colorless, Colorless', '', 'Sun & Moon', '34', 'Basic', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('sm12-35', '[{\'name\': \'Flaming Shot\', \'text\': \"Once during your turn (before your attack), you may discard a Fire Energy card from your hand. If you do, put 2 damage counters on 1 of your opponent\'s Pokémon.\", \'type\': \'Ability\'}]', '', 'Hiroyuki Yamamoto', '[{\'name\': \'Backfire\', \'cost\': [\'Fire\', \'Fire\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'160\', \'text\': \'Put 2 Fire Energy attached to this Pokémon into your hand.\'}, {\'name\': \'Massive Heat Wave-GX\', \'cost\': [\'Fire\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Discard an Energy from each of your opponent\'s Pokémon. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Cosmic Eclipse', '3', 'Larvesta', '', '', 'Seventh', '210', 'https://images.pokemoncard.io/images/sm12/sm12-35.png', 'unlimited: Legal, expanded: Legal', '', 'Volcarona-GX', '637', 'TPCI', 'Rare Holo GX', '', '11/01/2019', '', 'Colorless, Colorless, Colorless', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', '35', 'Stage 1, GX', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('sm12-36', '', '', 'HYOGONOSUKE', '[{\'name\': \'Tackle\', \'cost\': [\'Fire\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'\'}, {\'name\': \'Flame Tail\', \'cost\': [\'Fire\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'\'}]', 'Cosmic Eclipse', '2', '', 'Pyroar', 'When theyre young, they live with a pride. Once theyre able to hunt prey on their own, theyre kicked out and have to make their own way.', 'Seventh', '70', 'https://images.pokemoncard.io/images/sm12/sm12-36.png', 'unlimited: Legal, expanded: Legal', '', 'Litleo', '667', 'TPCI', 'Common', '', '11/01/2019', '', 'Colorless, Colorless', '', 'Sun & Moon', '36', 'Basic', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('sm12-37', '', '', 'KEIICHIRO ITO', '[{\'name\': \'Swirling Inferno\', \'cost\': [\'Fire\', \'Fire\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'70\', \'text\': \"Discard all Pokémon Tool cards and Special Energy from each of your opponent\'s Pokémon.\"}, {\'name\': \'Heat Blast\', \'cost\': [\'Fire\', \'Fire\', \'Fire\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'140\', \'text\': \'\'}]', 'Cosmic Eclipse', '2', 'Litleo', '', 'The males are usually lazy, but when attacked by a strong foe, a male will protect its friends with no regard for its own safety.', 'Seventh', '130', 'https://images.pokemoncard.io/images/sm12/sm12-37.png', 'unlimited: Legal, expanded: Legal', '', 'Pyroar', '668', 'TPCI', 'Uncommon', '', '11/01/2019', '', 'Colorless, Colorless', '', 'Sun & Moon', '37', 'Stage 1', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('sm12-38', '', '', 'Mitsuhiro Arita', '[{\'name\': \'Splash Maker\', \'cost\': [\'Water\', \'Water\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'150\', \'text\': \'You may attach up to 3 Water Energy cards from your hand to your Pokémon in any way you like. If you do, heal 50 damage from those Pokémon for each card you attached to them in this way.\'}, {\'name\': \'Bubble Launcher-GX\', \'cost\': [\'Water\', \'Water\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'100+\', \'text\': \"Your opponent\'s Active Pokémon is now Paralyzed. If this Pokémon has at least 3 extra Water Energy attached to it (in addition to this attack\'s cost), this attack does 150 more damage. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Cosmic Eclipse', '3', '', 'Prinplup', '', 'Seventh', '270', 'https://images.pokemoncard.io/images/sm12/sm12-38.png', 'unlimited: Legal, expanded: Legal', '', 'Blastoise & Piplup-GX', '9, 393', 'TPCI', 'Rare Holo GX', '', '11/01/2019', '', 'Colorless, Colorless, Colorless', '[\'TAG TEAM rule: When your TAG TEAM is Knocked Out, your opponent takes 3 Prize cards.\']', 'Sun & Moon', '38', 'Basic, TAG TEAM, GX', 'Pokémon', 'Water', 'type: Grass, value: ×2'),
('sm12-39', '[{\'name\': \'Snowed In\', \'text\': \"As long as this Pokémon is on your Bench, prevent all damage done to this Pokémon by attacks (both yours and your opponent\'s).\", \'type\': \'Ability\'}]', '', 'nagimiso', '[{\'name\': \'Gnaw\', \'cost\': [], \'convertedEnergyCost\': 0, \'damage\': \'10\', \'text\': \'\'}]', 'Cosmic Eclipse', '1', '', 'Ninetales', 'If you carelessly approach it because its cute, the boss of the pack, Ninetales, will appear and freeze you.', 'Seventh', '60', 'https://images.pokemoncard.io/images/sm12/sm12-39.png', 'unlimited: Legal, expanded: Legal', '', 'Alolan Vulpix', '37', 'TPCI', 'Common', '', '11/01/2019', '', 'Colorless', '', 'Sun & Moon', '39', 'Basic', 'Pokémon', 'Water', 'type: Metal, value: ×2'),
('sm12-4', '[{\'name\': \'Fragrant Flower Garden\', \'text\': \'Once during your turn (before your attack), you may heal 30 damage from each of your Pokémon.\', \'type\': \'Ability\'}]', '', 'Kagemaru Himeno', '[{\'name\': \'Massive Bloom\', \'cost\': [\'Grass\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'180-\', \'text\': \'This attack does 10 less damage for each damage counter on this Pokémon.\'}, {\'name\': \'Allergic Explosion-GX\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'50\', \'text\': \"Your opponent\'s Active Pokémon is now Burned, Paralyzed, and Poisoned. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Cosmic Eclipse', '2', 'Gloom', '', '', 'Seventh', '240', 'https://images.pokemoncard.io/images/sm12/sm12-4.png', 'unlimited: Legal, expanded: Legal', '', 'Vileplume-GX', '45', 'TPCI', 'Rare Holo GX', '', '11/01/2019', '', 'Colorless, Colorless', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', '4', 'Stage 2, GX', 'Pokémon', 'Grass', 'type: Fire, value: ×2');
INSERT INTO `cards` (`id`, `abilities`, `ancient_trait`, `artist`, `attacks`, `card_set`, `converted`, `evolves_from`, `evolves_to`, `flavor_text`, `generation`, `hp`, `img`, `legalities`, `level`, `name`, `national_pokedex_numbers`, `publisher`, `rarity`, `regulation_mark`, `release_date`, `resistances`, `retreat_cost`, `rules`, `series`, `set_num`, `subtypes`, `supertype`, `types`, `weakness`) VALUES
('sm12-40', '', '', 'sui', '[{\'name\': \'Scratch\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'\'}, {\'name\': \'Confusion Wave\', \'cost\': [\'Water\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'Both Active Pokémon are now Confused.\'}]', 'Cosmic Eclipse', '1', '', 'Golduck', 'Using psychokinesis gives it a headache, so it normally passes the time spacing out and doing as little as possible.', 'Seventh', '60', 'https://images.pokemoncard.io/images/sm12/sm12-40.png', 'unlimited: Legal, expanded: Legal', '', 'Psyduck', '54', 'TPCI', 'Common', '', '11/01/2019', '', 'Colorless', '', 'Sun & Moon', '40', 'Basic', 'Pokémon', 'Water', 'type: Grass, value: ×2'),
('sm12-41', '', '', 'Shigenori Negishi', '[{\'name\': \'Scratch\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'30\', \'text\': \'\'}, {\'name\': \'Energy Loop\', \'cost\': [\'Water\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'80\', \'text\': \'Put an Energy attached to this Pokémon into your hand.\'}]', 'Cosmic Eclipse', '1', 'Psyduck', '', 'Even fast-swimming fish Pokémon can be disabled by Golduck. It brings them to a standstill and seizes them.', 'Seventh', '110', 'https://images.pokemoncard.io/images/sm12/sm12-41.png', 'unlimited: Legal, expanded: Legal', '', 'Golduck', '55', 'TPCI', 'Uncommon', '', '11/01/2019', '', 'Colorless', '', 'Sun & Moon', '41', 'Stage 1', 'Pokémon', 'Water', 'type: Grass, value: ×2'),
('sm12-42', '[{\'name\': \'Vitality Cheer\', \'text\': \"Your Pokémon-GX in play that evolve from Eevee get +60 HP. You can\'t apply more than 1 Vitality Cheer Ability at a time.\", \'type\': \'Ability\'}]', '', 'sui', '[{\'name\': \'Refreshing Rain\', \'cost\': [\'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60\', \'text\': \'Heal 30 damage from each of your Pokémon.\'}]', 'Cosmic Eclipse', '2', 'Eevee', '', 'Clean, clear waters are its usual habitat. When its about to be attacked by an invading enemy, it dives into the water to hide.', 'Seventh', '110', 'https://images.pokemoncard.io/images/sm12/sm12-42.png', 'unlimited: Legal, expanded: Legal', '', 'Vaporeon', '134', 'TPCI', 'Uncommon', '', '11/01/2019', '', 'Colorless, Colorless', '', 'Sun & Moon', '42', 'Stage 1', 'Pokémon', 'Water', 'type: Grass, value: ×2'),
('sm12-43', '', '', 'ryoma uratsuka', '[{\'name\': \'Agility\', \'cost\': [\'Darkness\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \"Flip a coin. If heads, prevent all effects of attacks, including damage, done to this Pokémon during your opponent\'s next turn.\"}]', 'Cosmic Eclipse', '1', '', 'Weavile', 'They will cooperate to steal eggs from the nests of bird Pokémon, but fights break out to determine which one gets to eat the eggs.', 'Seventh', '70', 'https://images.pokemoncard.io/images/sm12/sm12-43.png', 'unlimited: Legal, expanded: Legal', '', 'Sneasel', '215', 'TPCI', 'Common', '', '11/01/2019', '', 'Colorless', '', 'Sun & Moon', '43', 'Basic', 'Pokémon', 'Water', 'type: Metal, value: ×2'),
('sm12-44', '', '', 'MAHOU', '[{\'name\': \'Nasty Plot\', \'cost\': [\'Darkness\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Search your deck for up to 2 cards and put them into your hand. Then, shuffle your deck.\'}, {\'name\': \'Slashing Claw\', \'cost\': [\'Darkness\', \'Darkness\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'110\', \'text\': \'\'}]', 'Cosmic Eclipse', '', 'Sneasel', '', 'One Weavile will trip a Sandshrew and flip it over, and then another Weavile will deal the finishing blow with its sharp claws.', 'Seventh', '90', 'https://images.pokemoncard.io/images/sm12/sm12-44.png', 'unlimited: Legal, expanded: Legal', '', 'Weavile', '461', 'TPCI', 'Rare', '', '11/01/2019', '', '', '', 'Sun & Moon', '44', 'Stage 1', 'Pokémon', 'Water', 'type: Metal, value: ×2'),
('sm12-45', '', '', 'Tomokazu Komiya', '[{\'name\': \'Wave Splash\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'\'}]', 'Cosmic Eclipse', '3', '', 'Wailord', 'It swims along with its mouth open and swallows down seawater along with its food. It sprays excess water out of its nostrils.', 'Seventh', '120', 'https://images.pokemoncard.io/images/sm12/sm12-45.png', 'unlimited: Legal, expanded: Legal', '', 'Wailmer', '320', 'TPCI', 'Common', '', '11/01/2019', '', 'Colorless, Colorless, Colorless', '', 'Sun & Moon', '45', 'Basic', 'Pokémon', 'Water', 'type: Grass, value: ×2'),
('sm12-46', '', '', 'Kyoko Umemoto', '[{\'name\': \'Heavy Impact\', \'cost\': [\'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'90\', \'text\': \'\'}, {\'name\': \'Hydro Splash\', \'cost\': [\'Water\', \'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'140\', \'text\': \'\'}]', 'Cosmic Eclipse', '4', 'Wailmer', '', 'They eat so many fish Pokémon that when Wailord become too numerous, fishermen have to chase them off.', 'Seventh', '200', 'https://images.pokemoncard.io/images/sm12/sm12-46.png', 'unlimited: Legal, expanded: Legal', '', 'Wailord', '321', 'TPCI', 'Rare', '', '11/01/2019', '', 'Colorless, Colorless, Colorless, Colorless', '', 'Sun & Moon', '46', 'Stage 1', 'Pokémon', 'Water', 'type: Grass, value: ×2'),
('sm12-47', '', '', 'sowsow', '[{\'name\': \'Continuous Headbutt\', \'cost\': [\'Water\'], \'convertedEnergyCost\': 1, \'damage\': \'20×\', \'text\': \'Flip a coin until you get tails. This attack does 20 damage for each heads.\'}]', 'Cosmic Eclipse', '2', '', 'Glalie, Froslass', 'It feeds mainly on ice and snow. Its only able to survive in a limited number of places in the warm Alola region.', 'Seventh', '60', 'https://images.pokemoncard.io/images/sm12/sm12-47.png', 'unlimited: Legal, expanded: Legal', '', 'Snorunt', '361', 'TPCI', 'Common', '', '11/01/2019', '', 'Colorless, Colorless', '', 'Sun & Moon', '47', 'Basic', 'Pokémon', 'Water', 'type: Metal, value: ×2'),
('sm12-48', '', '', 'Uta', '[{\'name\': \'Ice Fang\', \'cost\': [\'Water\'], \'convertedEnergyCost\': 1, \'damage\': \'30\', \'text\': \"Flip a coin. If heads, your opponent\'s Active Pokémon is now Paralyzed, and discard an Energy from that Pokémon.\"}, {\'name\': \'Frosty Typhoon\', \'cost\': [\'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'120\', \'text\': \"This Pokémon can\'t use Frosty Typhoon during your next turn.\"}]', 'Cosmic Eclipse', '3', 'Snorunt', 'Froslass', 'It freezes its prey and chews them whole. However, it prefers to eat Pokémon like Vanillite that are already frozen.', 'Seventh', '120', 'https://images.pokemoncard.io/images/sm12/sm12-48.png', 'unlimited: Legal, expanded: Legal', '', 'Glalie', '362', 'TPCI', 'Rare', '', '11/01/2019', '', 'Colorless, Colorless, Colorless', '', 'Sun & Moon', '48', 'Stage 1', 'Pokémon', 'Water', 'type: Metal, value: ×2'),
('sm12-49', '', '', 'sui', '[{\'name\': \'Rollout\', \'cost\': [\'Water\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'\'}, {\'name\': \'Icy Snow\', \'cost\': [\'Water\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'\'}]', 'Cosmic Eclipse', '2', '', 'Sealeo', 'They cant swim well yet, and they move much faster by rolling. When theyre happy, they clap fins.', 'Seventh', '60', 'https://images.pokemoncard.io/images/sm12/sm12-49.png', 'unlimited: Legal, expanded: Legal', '', 'Spheal', '363', 'TPCI', 'Common', '', '11/01/2019', '', 'Colorless, Colorless', '', 'Sun & Moon', '49', 'Basic', 'Pokémon', 'Water', 'type: Metal, value: ×2'),
('sm12-5', '', '', 'otumami', '[{\'name\': \'Toxic\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Your opponent\'s Active Pokémon is now Poisoned. Put 2 damage counters instead of 1 on that Pokémon between turns.\"}]', 'Cosmic Eclipse', '2', '', 'Tangrowth', 'Many writhing vines cover it, so its true identity remains unknown. The blue vines grow its whole life long.', 'Seventh', '70', 'https://images.pokemoncard.io/images/sm12/sm12-5.png', 'unlimited: Legal, expanded: Legal', '', 'Tangela', '114', 'TPCI', 'Common', '', '11/01/2019', '', 'Colorless, Colorless', '', 'Sun & Moon', '5', 'Basic', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('sm12-50', '', '', 'SATOSHI NAKAI', '[{\'name\': \'Body Slam\', \'cost\': [\'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'30\', \'text\': \"Flip a coin. If heads, your opponent\'s Active Pokémon is now Paralyzed.\"}]', 'Cosmic Eclipse', '2', '', 'Sealeo', 'They cant swim well yet, and they move much faster by rolling. When theyre happy, they clap fins.', 'Seventh', '70', 'https://images.pokemoncard.io/images/sm12/sm12-50.png', 'unlimited: Legal, expanded: Legal', '', 'Spheal', '363', 'TPCI', 'Common', '', '11/01/2019', '', 'Colorless, Colorless', '', 'Sun & Moon', '50', 'Basic', 'Pokémon', 'Water', 'type: Metal, value: ×2'),
('sm12-51', '', '', 'miki kudo', '[{\'name\': \'Rollout\', \'cost\': [\'Water\'], \'convertedEnergyCost\': 1, \'damage\': \'20\', \'text\': \'\'}, {\'name\': \'Ice Ball\', \'cost\': [\'Water\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'90\', \'text\': \'\'}]', 'Cosmic Eclipse', '3', 'Spheal', 'Walrein', 'It has a very sensitive nose. It touches new things with its nose to examine them.', 'Seventh', '100', 'https://images.pokemoncard.io/images/sm12/sm12-51.png', 'unlimited: Legal, expanded: Legal', '', 'Sealeo', '364', 'TPCI', 'Uncommon', '', '11/01/2019', '', 'Colorless, Colorless, Colorless', '', 'Sun & Moon', '51', 'Stage 1', 'Pokémon', 'Water', 'type: Metal, value: ×2'),
('sm12-52', '', '', 'Ayaka Yoshida', '[{\'name\': \'Cold Snap\', \'cost\': [\'Water\'], \'convertedEnergyCost\': 1, \'damage\': \'60\', \'text\': \"Your opponent can\'t play any Trainer cards from their hand during their next turn. If 1 of your Pokémon used Cold Snap during your last turn, this attack can\'t be used.\"}, {\'name\': \'Blizzard\', \'cost\': [\'Water\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'120\', \'text\': \"This attack does 10 damage to each of your opponent\'s Benched Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'Cosmic Eclipse', '4', 'Sealeo', '', 'It shatters ice with its big tusks. Its thick blubber repels not only the cold, but also enemy attacks.', 'Seventh', '160', 'https://images.pokemoncard.io/images/sm12/sm12-52.png', 'unlimited: Legal, expanded: Legal', '', 'Walrein', '365', 'TPCI', 'Rare', '', '11/01/2019', '', 'Colorless, Colorless, Colorless, Colorless', '', 'Sun & Moon', '52', 'Stage 2', 'Pokémon', 'Water', 'type: Metal, value: ×2'),
('sm12-53', '', '', 'kawayoo', '[{\'name\': \'High Water\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Attach 2 Water Energy cards from your discard pile to 1 of your Pokémon.\'}, {\'name\': \'Swirling Waves\', \'cost\': [\'Water\', \'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'130\', \'text\': \'Discard an Energy from this Pokémon.\'}]', 'Cosmic Eclipse', '3', '', '', 'A mythical Pokémon said to have swelled the seas with rain and tidal waves. It battled with Groudon.', 'Seventh', '130', 'https://images.pokemoncard.io/images/sm12/sm12-53.png', 'unlimited: Legal, expanded: Legal', '', 'Kyogre', '382', 'TPCI', 'Rare', '', '11/01/2019', '', 'Colorless, Colorless, Colorless', '', 'Sun & Moon', '53', 'Basic', 'Pokémon', 'Water', 'type: Grass, value: ×2'),
('sm12-54', '', '', 'Suwama Chiaki', '[{\'name\': \'Bubble Hold\', \'cost\': [\'Water\', \'Water\', \'Water\'], \'convertedEnergyCost\': 3, \'damage\': \'80\', \'text\': \"If the Defending Pokémon is a Basic Pokémon, it can\'t attack during your opponent\'s next turn.\"}]', 'Cosmic Eclipse', '1', '', 'Prinplup', 'It doesnt like to be taken care of. Its difficult to bond with since it wont listen to its Trainer.', 'Seventh', '60', 'https://images.pokemoncard.io/images/sm12/sm12-54.png', 'unlimited: Legal, expanded: Legal', '', 'Piplup', '393', 'TPCI', 'Common', '', '11/01/2019', '', 'Colorless', '', 'Sun & Moon', '54', 'Basic', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('sm12-55', '', '', 'Hasuno', '[{\'name\': \'Water Drip\', \'cost\': [\'Water\'], \'convertedEnergyCost\': 1, \'damage\': \'20\', \'text\': \'\'}, {\'name\': \'Direct Dive\', \'cost\': [\'Water\', \'Water\', \'Water\'], \'convertedEnergyCost\': 3, \'damage\': \'\', \'text\': \"Discard all Energy from this Pokémon. This attack does 100 damage to 1 of your opponent\'s Benched Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'Cosmic Eclipse', '2', 'Piplup', 'Empoleon', 'It lives alone, away from others. Apparently, every one of them believes it is the most important.', 'Seventh', '80', 'https://images.pokemoncard.io/images/sm12/sm12-55.png', 'unlimited: Legal, expanded: Legal', '', 'Prinplup', '394', 'TPCI', 'Uncommon', '', '11/01/2019', '', 'Colorless, Colorless', '', 'Sun & Moon', '55', 'Stage 1', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('sm12-56', '', '', 'Masakazu Fukuda', '[{\'name\': \'Recall\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Choose an attack from 1 of this Pokémon\'s previous Evolutions and use it as this attack.\"}, {\'name\': \'Aquafall\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'130\', \'text\': \'Discard all Energy from this Pokémon.\'}]', 'Cosmic Eclipse', '2', 'Prinplup', '', 'It swims as fast as a jet boat. The edges of its wings are sharp and can slice apart drifting ice.', 'Seventh', '160', 'https://images.pokemoncard.io/images/sm12/sm12-56.png', 'unlimited: Legal, expanded: Legal', '', 'Empoleon', '395', 'TPCI', 'Rare', '', '11/01/2019', '', 'Colorless, Colorless', '', 'Sun & Moon', '56', 'Stage 2', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('sm12-57', '[{\'name\': \'Whirlpool Suction\', \'text\': \'Once during your turn (before your attack), if this Pokémon is on your Bench, you may have your opponent switch their Active Pokémon with 1 of their Benched Pokémon. If you do, discard all cards attached to this Pokémon and put it on the bottom of your deck.\', \'type\': \'Ability\'}]', '', 'AKIRA EGAWA', '[{\'name\': \'Rain Splash\', \'cost\': [\'Water\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'\'}]', 'Cosmic Eclipse', '1', '', '', 'When the water warms, they inflate the flotation sac on their heads and drift languidly on the sea in packs.', 'Seventh', '70', 'https://images.pokemoncard.io/images/sm12/sm12-57.png', 'unlimited: Legal, expanded: Legal', '', 'Phione', '489', 'TPCI', 'Rare', '', '11/01/2019', '', 'Colorless', '', 'Sun & Moon', '57', 'Basic', 'Pokémon', 'Water', 'type: Grass, value: ×2'),
('sm12-58', '', '', 'Asako Ito', '[{\'name\': \'Flail Around\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10×\', \'text\': \'Flip 3 coins. This attack does 10 damage for each heads.\'}]', 'Cosmic Eclipse', '1', '', 'Palpitoad', 'By vibrating its cheeks, it emits sound waves imperceptible to humans and warns others of danger.', 'Seventh', '60', 'https://images.pokemoncard.io/images/sm12/sm12-58.png', 'unlimited: Legal, expanded: Legal', '', 'Tympole', '535', 'TPCI', 'Common', '', '11/01/2019', '', 'Colorless', '', 'Sun & Moon', '58', 'Basic', 'Pokémon', 'Water', 'type: Grass, value: ×2'),
('sm12-59', '', '', 'Yumi', '[{\'name\': \'Aerial Ace\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'10+\', \'text\': \'Flip a coin. If heads, this attack does 30 more damage.\'}]', 'Cosmic Eclipse', '1', '', 'Swanna', 'When attacked, it uses its feathers to splash water, escaping under cover of the spray.', 'Seventh', '60', 'https://images.pokemoncard.io/images/sm12/sm12-59.png', 'unlimited: Legal, expanded: Legal', '', 'Ducklett', '580', 'TPCI', 'Common', '', '11/01/2019', 'type: Fighting, value: -20', 'Colorless', '', 'Sun & Moon', '59', 'Basic', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('sm12-6', '', '', 'nagimiso', '[{\'name\': \'Grass Knot\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'10+\', \'text\': \"This attack does 30 more damage for each Colorless in your opponent\'s Active Pokémon\'s Retreat Cost.\"}, {\'name\': \'Slam\', \'cost\': [\'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'80×\', \'text\': \'Flip 2 coins. This attack does 80 damage for each heads.\'}]', 'Cosmic Eclipse', '3', 'Tangela', '', 'It ensnares prey by extending arms made of vines. Losing arms to predators does not trouble it.', 'Seventh', '140', 'https://images.pokemoncard.io/images/sm12/sm12-6.png', 'unlimited: Legal, expanded: Legal', '', 'Tangrowth', '465', 'TPCI', 'Uncommon', '', '11/01/2019', '', 'Colorless, Colorless, Colorless', '', 'Sun & Moon', '6', 'Stage 1', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
