('sm2-126', '', '', 'Ken Sugimori', '', 'Guardians Rising', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm2/sm2-126.png', 'unlimited: Legal, expanded: Legal', '', 'Hala', '', 'TPCI', 'Uncommon', '', '05/05/2017', '', '', '[\'Shuffle your hand into your deck. If you have used your GX attack, draw 7 cards. If not, draw 4 cards.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '126', 'Supporter', 'Trainer', '', ''),
('sm2-127', '', '', 'Ken Sugimori', '', 'Guardians Rising', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm2/sm2-127.png', 'unlimited: Legal, expanded: Legal', '', 'Mallow', '', 'TPCI', 'Uncommon', '', '05/05/2017', '', '', '[\'Search your deck for 2 cards, shuffle your deck, and put those cards on top of your deck in any order.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '127', 'Supporter', 'Trainer', '', ''),
('sm2-128', '', '', 'Toyste Beach', '', 'Guardians Rising', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm2/sm2-128.png', 'unlimited: Legal, expanded: Legal', '', 'Max Potion', '', 'TPCI', 'Uncommon', '', '05/05/2017', '', '', '[\'Heal all damage from 1 of your Pokémon. If you do, discard all Energy from that Pokémon.\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '128', 'Item', 'Trainer', '', ''),
