('sm3-113', '', '', 'Eske Yoshinob', '', 'Burning Shadows', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm3/sm3-113.png', 'unlimited: Legal, expanded: Legal', '', 'Bodybuilding Dumbbells', '', 'TPCI', 'Uncommon', '', '08/05/2017', '', '', '[\"Attach a Pokémon Tool to 1 of your Pokémon that doesn\'t already have a Pokémon Tool attached to it.\", \'The Stage 1 Pokémon this card is attached to gets +40 HP.\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '113', 'Pokémon Tool', 'Trainer', '', ''),
('sm3-114', '', '', 'Toyste Beach', '', 'Burning Shadows', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm3/sm3-114.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Escape Rope', '', 'TPCI', 'Uncommon', '', '08/05/2017', '', '', '[\"Each player switches their Active Pokémon with 1 of their Benched Pokémon. Your opponent switches first. (If a player does not have a Benched Pokémon, that player doesn\'t switch Pokémon.)\", \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '114', 'Item', 'Trainer', '', ''),
('sm3-115', '', '', 'Ken Sugimori', '', 'Burning Shadows', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm3/sm3-115.png', 'unlimited: Legal, expanded: Legal', '', 'Guzma', '', 'TPCI', 'Uncommon', '', '08/05/2017', '', '', '[\"Switch 1 of your opponent\'s Benched Pokémon with their Active Pokémon. If you do, switch your Active Pokémon with 1 of your Benched Pokémon.\", \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '115', 'Supporter', 'Trainer', '', ''),
