('sm3-116', '', '', 'Ken Sugimori', '', 'Burning Shadows', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm3/sm3-116.png', 'unlimited: Legal, expanded: Legal', '', 'Kiawe', '', 'TPCI', 'Uncommon', '', '08/05/2017', '', '', '[\'Search your deck for up to 4 Fire Energy cards and attach them to 1 of your Pokémon. Then, shuffle your deck. Your turn ends.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '116', 'Supporter', 'Trainer', '', ''),
('sm3-116a', '', '', 'Masakazu Fukuda', '', 'Burning Shadows', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm3/sm3-116a.png', 'unlimited: Legal, expanded: Legal', '', 'Kiawe', '', 'TPCI', 'Uncommon', '', '08/05/2017', '', '', '[\'Search your deck for up to 4 Fire Energy cards and attach them to 1 of your Pokémon. Then, shuffle your deck. Your turn ends.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '116a', 'Supporter', 'Trainer', '', ''),
('sm3-117', '', '', 'Ken Sugimori', '', 'Burning Shadows', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm3/sm3-117.png', 'unlimited: Legal, expanded: Legal', '', 'Lana', '', 'TPCI', 'Uncommon', '', '08/05/2017', '', '', '[\'Heal 50 damage from each of your Pokémon that has any Water Energy attached to it.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '117', 'Supporter', 'Trainer', '', ''),
