('sm3-119', '', '', 'Ken Sugimori', '', 'Burning Shadows', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm3/sm3-119.png', 'unlimited: Legal, expanded: Legal', '', 'Olivia', '', 'TPCI', 'Uncommon', '', '08/05/2017', '', '', '[\'Search your deck for up to 2 Pokémon-GX, reveal them, and put them into your hand. Then, shuffle your deck.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '119', 'Supporter', 'Trainer', '', ''),
('sm3-12', '', '', 'Shigenori Negishi', '[{\'name\': \'Vine Whip\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'\'}]', 'Burning Shadows', '1', '', 'Simisage', 'It shares the leaf on its head with weary-looking Pokémon. These leaves are known to relieve stress.', 'Seventh', '70', 'https://images.pokemoncard.io/images/sm3/sm3-12.png', 'unlimited: Legal, expanded: Legal', '', 'Pansage', '511', 'TPCI', 'Common', '', '08/05/2017', '', 'Colorless', '', 'Sun & Moon', '12', 'Basic', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
