('sm3-121', '', '', '5ban Graphics', '', 'Burning Shadows', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm3/sm3-121.png', 'unlimited: Legal, expanded: Legal', '', 'Po Town', '', 'TPCI', 'Uncommon', '', '08/05/2017', '', '', '[\'Whenever any player plays a Pokémon from their hand to evolve 1 of their Pokémon, put 3 damage counters on that Pokémon.\', \"This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can\'t play this card.\"]', 'Sun & Moon', '121', 'Stadium', 'Trainer', '', ''),
('sm3-122', '', '', '5ban Graphics', '', 'Burning Shadows', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm3/sm3-122.png', 'unlimited: Legal, expanded: Legal', '', 'Rotom Dex Poké Finder Mode', '', 'TPCI', 'Uncommon', '', '08/05/2017', '', '', '[\'Look at the top 4 cards of your deck and put them back in any order or shuffle them into your deck.\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '122', 'Item', 'Trainer', '', ''),
('sm3-123', '', '', 'Ken Sugimori', '', 'Burning Shadows', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm3/sm3-123.png', 'unlimited: Legal, expanded: Legal', '', 'Sophocles', '', 'TPCI', 'Uncommon', '', '08/05/2017', '', '', '[\'Discard 2 cards from your hand. If you do, draw 4 cards.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '123', 'Supporter', 'Trainer', '', ''),
