('sm3-125', '', '', 'Toyste Beach', '', 'Burning Shadows', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm3/sm3-125.png', 'unlimited: Legal, expanded: Legal', '', 'Tormenting Spray', '', 'TPCI', 'Uncommon', '', '08/05/2017', '', '', '[\"Choose a random card from your opponent\'s hand. Your opponent reveals that card. If it\'s a Supporter card, discard it.\", \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '125', 'Item', 'Trainer', '', ''),
('sm3-126', '', '', 'Ayaka Yoshida', '', 'Burning Shadows', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm3/sm3-126.png', 'unlimited: Legal, expanded: Legal', '', 'Weakness Policy', '', 'TPCI', 'Uncommon', '', '08/05/2017', '', '', '[\"Attach a Pokémon Tool to 1 of your Pokémon that doesn\'t already have a Pokémon Tool attached to it.\", \'The Pokémon this card is attached to has no Weakness.\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '126', 'Pokémon Tool', 'Trainer', '', ''),
('sm3-127', '', '', 'take', '', 'Burning Shadows', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm3/sm3-127.png', 'unlimited: Legal, expanded: Legal', '', 'Wicke', '', 'TPCI', 'Uncommon', '', '08/05/2017', '', '', '[\'Each player counts the cards in their hand, shuffles those cards into their deck, then draws that many cards.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '127', 'Supporter', 'Trainer', '', ''),
('sm3-128', '', '', 'Toyste Beach', '', 'Burning Shadows', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm3/sm3-128.png', 'unlimited: Legal, expanded: Legal', '', 'Wishful Baton', '', 'TPCI', 'Uncommon', '', '08/05/2017', '', '', '[\"Attach a Pokémon Tool to 1 of your Pokémon that doesn\'t already have a Pokémon Tool attached to it.\", \"If the Pokémon this card is attached to is your Active Pokémon and is Knocked Out by damage from an opponent\'s attack, move up to 3 basic Energy cards from that Pokémon to 1 of your Benched Pokémon.\", \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '128', 'Pokémon Tool', 'Trainer', '', ''),
('sm3-129', '', '', '5ban Graphics', '[{\'name\': \'First Impression\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'30+\', \'text\': \'If this Pokémon was on the Bench and became your Active Pokémon this turn, this attack does 90 more damage.\'}, {\'name\': \'Armor Press\', \'cost\': [\'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'100\', \'text\': \"During your opponent\'s next turn, this Pokémon takes 20 less damage from attacks (after applying Weakness and Resistance).\"}, {\'name\': \'Crossing Cut-GX\', \'cost\': [\'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'150\', \'text\': \"Switch this Pokémon with 1 of your Benched Pokémon. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Burning Shadows', '3', 'Wimpod', '', '', 'Seventh', '210', 'https://images.pokemoncard.io/images/sm3/sm3-129.png', 'unlimited: Legal, expanded: Legal', '', 'Golisopod-GX', '768', 'TPCI', 'Rare Ultra', '', '08/05/2017', '', 'Colorless, Colorless, Colorless', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', '129', 'Stage 1, GX', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
