('sm3-138', '', '', '5ban Graphics', '[{\'name\': \'Chemical Breath\', \'cost\': [\'Darkness\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'10+\', \'text\': \"This attack does 70 more damage for each Special Condition affecting your opponent\'s Active Pokémon.\"}, {\'name\': \'Crunch\', \'cost\': [\'Darkness\', \'Darkness\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'120\', \'text\': \"Discard an Energy attached to your opponent\'s Active Pokémon.\"}, {\'name\': \'Tri Hazard-GX\', \'cost\': [], \'convertedEnergyCost\': 0, \'damage\': \'\', \'text\': \"Switch 1 of your opponent\'s Benched Pokémon with their Active Pokémon. The new Active Pokémon is now Burned, Paralyzed, and Poisoned. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Burning Shadows', '4', 'Alolan Grimer', '', '', 'Seventh', '220', 'https://images.pokemoncard.io/images/sm3/sm3-138.png', 'unlimited: Legal, expanded: Legal', '', 'Alolan Muk-GX', '89', 'TPCI', 'Rare Ultra', '', '08/05/2017', 'type: Psychic, value: -20', 'Colorless, Colorless, Colorless, Colorless', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', '138', 'Stage 1, GX', 'Pokémon', 'Darkness', 'type: Fighting, value: ×2'),
('sm3-139', '[{\'name\': \'Restoration\', \'text\': \'Once during your turn (before your attack), if this Pokémon is in your discard pile, you may put it onto your Bench. Then, attach a Darkness Energy card from your discard pile to this Pokémon.\', \'type\': \'Ability\'}]', '', '5ban Graphics', '[{\'name\': \'Dark Cleave\', \'cost\': [\'Darkness\', \'Darkness\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'130\', \'text\': \"This attack\'s damage isn\'t affected by Resistance.\"}, {\'name\': \'Dead End-GX\', \'cost\': [\'Darkness\', \'Darkness\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'\', \'text\': \"If your opponent\'s Active Pokémon is affected by a Special Condition, that Pokémon is Knocked Out. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Burning Shadows', '2', '', '', '', 'Seventh', '180', 'https://images.pokemoncard.io/images/sm3/sm3-139.png', 'unlimited: Legal, expanded: Legal', '', 'Darkrai-GX', '491', 'TPCI', 'Rare Ultra', '', '08/05/2017', 'type: Psychic, value: -20', 'Colorless, Colorless', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', '139', 'Basic, GX', 'Pokémon', 'Darkness', 'type: Fighting, value: ×2'),
