('sm3-141', '', '', '5ban Graphics', '[{\'name\': \'Distort\', \'cost\': [\'Darkness\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'50\', \'text\': \"Your opponent can\'t play any Item cards from their hand during their next turn.\"}, {\'name\': \'Sonic Volume\', \'cost\': [\'Psychic\', \'Darkness\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'120\', \'text\': \"Your opponent can\'t play any Special Energy cards from their hand during their next turn.\"}, {\'name\': \'Boomburst-GX\', \'cost\': [\'Psychic\', \'Darkness\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'\', \'text\': \"This attack does 50 damage to each of your opponent\'s Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.) (You can\'t use more than 1 GX attack in a game.)\"}]', 'Burning Shadows', '', 'Noibat', '', '', 'Seventh', '200', 'https://images.pokemoncard.io/images/sm3/sm3-141.png', 'unlimited: Legal, expanded: Legal', '', 'Noivern-GX', '715', 'TPCI', 'Rare Ultra', '', '08/05/2017', '', '', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', '141', 'Stage 1, GX', 'Pokémon', 'Dragon', 'type: Fairy, value: ×2'),
('sm3-142', '', '', 'Megumi Mizutani', '', 'Burning Shadows', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm3/sm3-142.png', 'unlimited: Legal, expanded: Legal', '', 'Acerola', '', 'TPCI', 'Rare Ultra', '', '08/05/2017', '', '', '[\'Put 1 of your Pokémon that has any damage counters on it and all cards attached to it into your hand.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '142', 'Supporter', 'Trainer', '', ''),
('sm3-143', '', '', 'Masakazu Fukuda', '', 'Burning Shadows', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm3/sm3-143.png', 'unlimited: Legal, expanded: Legal', '', 'Guzma', '', 'TPCI', 'Rare Ultra', '', '08/05/2017', '', '', '[\"Switch 1 of your opponent\'s Benched Pokémon with their Active Pokémon. If you do, switch your Active Pokémon with 1 of your Benched Pokémon.\", \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '143', 'Supporter', 'Trainer', '', ''),
('sm3-144', '', '', 'Naoki Saito', '', 'Burning Shadows', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm3/sm3-144.png', 'unlimited: Legal, expanded: Legal', '', 'Kiawe', '', 'TPCI', 'Rare Ultra', '', '08/05/2017', '', '', '[\'Search your deck for up to 4 Fire Energy cards and attach them to 1 of your Pokémon. Then, shuffle your deck. Your turn ends.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '144', 'Supporter', 'Trainer', '', ''),
('sm3-145', '', '', 'Sanosuke Sakuma', '', 'Burning Shadows', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm3/sm3-145.png', 'unlimited: Legal, expanded: Legal', '', 'Plumeria', '', 'TPCI', 'Rare Ultra', '', '08/05/2017', '', '', '[\"Discard 2 cards from your hand. If you do, discard an Energy attached to 1 of your opponent\'s Pokémon.\", \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '145', 'Supporter', 'Trainer', '', ''),
('sm3-146', '', '', 'Sanosuke Sakuma', '', 'Burning Shadows', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm3/sm3-146.png', 'unlimited: Legal, expanded: Legal', '', 'Sophocles', '', 'TPCI', 'Rare Ultra', '', '08/05/2017', '', '', '[\'Discard 2 cards from your hand. If you do, draw 4 cards.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '146', 'Supporter', 'Trainer', '', ''),
('sm3-147', '', '', 'Naoki Saito', '', 'Burning Shadows', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm3/sm3-147.png', 'unlimited: Legal, expanded: Legal', '', 'Wicke', '', 'TPCI', 'Rare Ultra', '', '08/05/2017', '', '', '[\'Each player counts the cards in their hand, shuffles those cards into their deck, then draws that many cards.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '147', 'Supporter', 'Trainer', '', ''),
