('sm5-139', '[{\'name\': \'Breath of the Leaves\', \'text\': \'If this Pokémon is your Active Pokémon, once during your turn (before your attack), you may heal 50 damage from 1 of your Pokémon that has any Energy attached to it.\', \'type\': \'Ability\'}]', '', '5ban Graphics', '[{\'name\': \'Solar Beam\', \'cost\': [\'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'110\', \'text\': \'\'}, {\'name\': \'Grand Bloom-GX\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"For each of your Benched Basic Pokémon, search your deck for a card that evolves from that Pokémon and put it onto that Pokémon to evolve it. Then, shuffle your deck. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Ultra Prism', '2', 'Eevee', '', '', 'Seventh', '200', 'https://images.pokemoncard.io/images/sm5/sm5-139.png', 'unlimited: Legal, expanded: Legal', '', 'Leafeon-GX', '470', 'TPCI', 'Rare Ultra', '', '02/02/2018', '', 'Colorless, Colorless', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', '139', 'Stage 1, GX', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('sm5-14', '[{\'name\': \'Roto Motor\', \'text\': \"If you have 9 or more Pokémon Tool cards in your discard pile, ignore all Energy in the attack cost of each of this Pokémon\'s attacks.\", \'type\': \'Ability\'}]', '', 'kawayoo', '[{\'name\': \'Special Mow\', \'cost\': [\'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60\', \'text\': \"Discard a Special Energy from your opponent\'s Active Pokémon.\"}]', 'Ultra Prism', '1', '', '', 'Its body is composed of plasma. It is known to infiltrate electronic devices and wreak havoc.', 'Seventh', '90', 'https://images.pokemoncard.io/images/sm5/sm5-14.png', 'unlimited: Legal, expanded: Legal', '', 'Mow Rotom', '479', 'TPCI', 'Rare', '', '02/02/2018', '', 'Colorless', '', 'Sun & Moon', '14', 'Basic', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('sm5-140', '', '', '5ban Graphics', '[{\'name\': \'Fast Raid\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'30\', \'text\': \'If you go first, you can use this attack on your first turn.\'}, {\'name\': \'Cruel Spike\', \'cost\': [\'Grass\', \'Grass\'], \'convertedEnergyCost\': 2, \'damage\': \'60\', \'text\': \"Your opponent\'s Active Pokémon is now Confused.\"}, {\'name\': \'Beauty-GX\', \'cost\': [\'Grass\', \'Grass\'], \'convertedEnergyCost\': 2, \'damage\': \'50×\', \'text\': \"This attack does 50 damage for each Prize card your opponent has taken. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Ultra Prism', '1', '', '', '', 'Seventh', '170', 'https://images.pokemoncard.io/images/sm5/sm5-140.png', 'unlimited: Legal, expanded: Legal', '', 'Pheromosa-GX', '795', 'TPCI', 'Rare Ultra', '', '02/02/2018', '', 'Colorless', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', '140', 'Basic, GX, Ultra Beast', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('sm5-141', '[{\'name\': \'Freezing Gaze\', \'text\': \"As long as this Pokémon is your Active Pokémon, your opponent\'s Pokémon-GX and Pokémon-EX in play, in their hand, and in their discard pile have no Abilities, except for Freezing Gaze.\", \'type\': \'Ability\'}]', '', '5ban Graphics', '[{\'name\': \'Frost Bullet\', \'cost\': [\'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'90\', \'text\': \"This attack does 30 damage to 1 of your opponent\'s Benched Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}, {\'name\': \'Polar Spear-GX\', \'cost\': [\'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50×\', \'text\': \"This attack does 50 damage for each damage counter on your opponent\'s Active Pokémon. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Ultra Prism', '2', 'Eevee', '', '', 'Seventh', '200', 'https://images.pokemoncard.io/images/sm5/sm5-141.png', 'unlimited: Legal, expanded: Legal', '', 'Glaceon-GX', '471', 'TPCI', 'Rare Ultra', '', '02/02/2018', '', 'Colorless, Colorless', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', '141', 'Stage 1, GX', 'Pokémon', 'Water', 'type: Metal, value: ×2'),
