('sm5-160', '[{\'name\': \'Flashing Head\', \'text\': \"Prevent all damage done to this Pokémon by attacks from your opponent\'s Pokémon that have any Special Energy attached to them.\", \'type\': \'Ability\'}]', '', '5ban Graphics', '[{\'name\': \'Rumbling Wires\', \'cost\': [\'Lightning\', \'Lightning\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'100\', \'text\': \"Discard the top card of your opponent\'s deck.\"}, {\'name\': \'Lighting-GX\', \'cost\': [\'Lightning\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Your opponent reveals their hand. Add a card you find there to their Prize cards face down. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Ultra Prism', '2', '', '', '', 'Seventh', '180', 'https://images.pokemoncard.io/images/sm5/sm5-160.png', 'unlimited: Legal, expanded: Legal', '', 'Xurkitree-GX', '796', 'TPCI', 'Rare Rainbow', '', '02/02/2018', 'type: Metal, value: -20', 'Colorless, Colorless', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', '160', 'Basic, GX, Ultra Beast', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
('sm5-161', '[{\'name\': \'Invasion\', \'text\': \'Once during your turn (before your attack), if this Pokémon is on your Bench, you may switch it with your Active Pokémon.\', \'type\': \'Ability\'}]', '', '5ban Graphics', '[{\'name\': \'Dark Flash\', \'cost\': [\'Psychic\', \'Psychic\', \'Psychic\'], \'convertedEnergyCost\': 3, \'damage\': \'120\', \'text\': \"This attack\'s damage isn\'t affected by Resistance.\"}, {\'name\': \"Moon\'s Eclipse-GX\", \'cost\': [\'Psychic\', \'Psychic\', \'Psychic\'], \'convertedEnergyCost\': 3, \'damage\': \'180\', \'text\': \"You can use this attack only if you have more Prize cards remaining than your opponent. Prevent all effects of attacks, including damage, done to this Pokémon during your opponent\'s next turn. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Ultra Prism', '2', '', '', '', 'Seventh', '180', 'https://images.pokemoncard.io/images/sm5/sm5-161.png', 'unlimited: Legal, expanded: Legal', '', 'Dawn Wings Necrozma-GX', '800', 'TPCI', 'Rare Rainbow', '', '02/02/2018', 'type: Fighting, value: -20', 'Colorless, Colorless', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', '161', 'Basic, GX, Ultra Beast', 'Pokémon', 'Psychic', 'type: Darkness, value: ×2'),
('sm5-162', '', '', '5ban Graphics', '[{\'name\': \'Rocket Fall\', \'cost\': [\'Metal\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'30+\', \'text\': \"This attack does 30 more damage for each Colorless in your opponent\'s Active Pokémon\'s Retreat Cost.\"}, {\'name\': \'Moon Press\', \'cost\': [\'Metal\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'130\', \'text\': \'\'}, {\'name\': \'Blaster-GX\', \'cost\': [\'Metal\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'180\', \'text\': \"Turn all of your Prize cards face up. (Those Prize cards remain face up for the rest of the game.) (You can\'t use more than 1 GX attack in a game.)\"}]', 'Ultra Prism', '4', '', '', '', 'Seventh', '200', 'https://images.pokemoncard.io/images/sm5/sm5-162.png', 'unlimited: Legal, expanded: Legal', '', 'Celesteela-GX', '797', 'TPCI', 'Rare Rainbow', '', '02/02/2018', 'type: Fighting, value: -20', 'Colorless, Colorless, Colorless, Colorless', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', '162', 'Basic, GX, Ultra Beast', 'Pokémon', 'Metal', 'type: Lightning, value: ×2'),
('sm5-163', '', '', '5ban Graphics', '[{\'name\': \'Claw Slash\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60\', \'text\': \'\'}, {\'name\': \'Meteor Tempest\', \'cost\': [\'Metal\', \'Metal\', \'Metal\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'220\', \'text\': \'Discard 3 Energy from this Pokémon.\'}, {\'name\': \"Sun\'s Eclipse-GX\", \'cost\': [\'Metal\', \'Metal\', \'Metal\'], \'convertedEnergyCost\': 3, \'damage\': \'250\', \'text\': \"You can use this attack only if you have more Prize cards remaining than your opponent. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Ultra Prism', '3', '', '', '', 'Seventh', '190', 'https://images.pokemoncard.io/images/sm5/sm5-163.png', 'unlimited: Legal, expanded: Legal', '', 'Dusk Mane Necrozma-GX', '800', 'TPCI', 'Rare Rainbow', '', '02/02/2018', 'type: Psychic, value: -20', 'Colorless, Colorless, Colorless', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', '163', 'Basic, GX, Ultra Beast', 'Pokémon', 'Metal', 'type: Fire, value: ×2'),
('sm5-164', '', '', '5ban Graphics', '[{\'name\': \'Overclock\', \'cost\': [\'Metal\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Draw cards until you have 6 cards in your hand.\'}, {\'name\': \'Shred\', \'cost\': [\'Metal\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'80\', \'text\': \"This attack\'s damage isn\'t affected by any effects on your opponent\'s Active Pokémon.\"}, {\'name\': \'Timeless-GX\', \'cost\': [\'Metal\', \'Metal\', \'Metal\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 5, \'damage\': \'150\', \'text\': \"Take another turn after this one. (Skip the between-turns step.) (You can\'t use more than 1 GX attack in a game.)\"}]', 'Ultra Prism', '3', '', '', '', 'Seventh', '180', 'https://images.pokemoncard.io/images/sm5/sm5-164.png', 'unlimited: Legal, expanded: Legal', '', 'Dialga-GX', '483', 'TPCI', 'Rare Rainbow', '', '02/02/2018', '', 'Colorless, Colorless, Colorless', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', '164', 'Basic, GX', 'Pokémon', 'Dragon', 'type: Fairy, value: ×2'),
('sm5-165', '', '', '5ban Graphics', '[{\'name\': \'Spatial Control\', \'cost\': [\'Water\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Move any number of Energy from your Benched Pokémon to this Pokémon.\'}, {\'name\': \'Hydro Pressure\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60+\', \'text\': \'This attack does 20 more damage times the amount of Water Energy attached to this Pokémon.\'}, {\'name\': \'Zero Vanish-GX\', \'cost\': [\'Water\', \'Water\', \'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 5, \'damage\': \'150\', \'text\': \"Shuffle all Energy from each of your opponent\'s Pokémon into their deck. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Ultra Prism', '3', '', '', '', 'Seventh', '180', 'https://images.pokemoncard.io/images/sm5/sm5-165.png', 'unlimited: Legal, expanded: Legal', '', 'Palkia-GX', '484', 'TPCI', 'Rare Rainbow', '', '02/02/2018', '', 'Colorless, Colorless, Colorless', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', '165', 'Basic, GX', 'Pokémon', 'Dragon', 'type: Fairy, value: ×2'),
('sm5-166', '', '', 'Yoshinobu Saito', '', 'Ultra Prism', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm5/sm5-166.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Crushing Hammer', '', 'TPCI', 'Rare Secret', '', '02/02/2018', '', '', '[\"Flip a coin. If heads, discard an Energy from 1 of your opponent\'s Pokémon.\", \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '166', 'Item', 'Trainer', '', ''),
('sm5-167', '', '', 'Toyste Beach', '', 'Ultra Prism', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm5/sm5-167.png', 'unlimited: Legal, expanded: Legal', '', 'Escape Board', '', 'TPCI', 'Rare Secret', '', '02/02/2018', '', '', '[\"Attach a Pokémon Tool to 1 of your Pokémon that doesn\'t already have a Pokémon Tool attached to it.\", \"The Retreat Cost of the Pokémon this card is attached to is Colorless less, and it can retreat even if it\'s Asleep or Paralyzed.\", \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '167', 'Pokémon Tool', 'Trainer', '', ''),
('sm5-168', '', '', 'Toyste Beach', '', 'Ultra Prism', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm5/sm5-168.png', 'unlimited: Legal, expanded: Legal', '', 'Missing Clover', '', 'TPCI', 'Rare Secret', '', '02/02/2018', '', '', '[\'You may play 4 Missing Clover cards at once.\\n• If you played 1 card, look at the top card of your deck.\\n• If you played 4 cards, take a Prize card. (This effect works one time for 4 cards.)\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '168', 'Item', 'Trainer', '', ''),
('sm5-169', '', '', 'Toyste Beach', '', 'Ultra Prism', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm5/sm5-169.png', 'unlimited: Legal, expanded: Legal', '', 'Peeking Red Card', '', 'TPCI', 'Rare Secret', '', '02/02/2018', '', '', '[\'Your opponent reveals their hand. You may have your opponent count the cards in their hand, shuffle those cards into their deck, then draw that many cards.\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '169', 'Item', 'Trainer', '', ''),
('sm5-17', '[{\'name\': \'Water Bubble\', \'text\': \"Prevent all damage done to this Pokémon by attacks from your opponent\'s Fire Pokémon.\", \'type\': \'Ability\'}]', '', 'Shin Nagasawa', '[{\'name\': \'Aqua Edge\', \'cost\': [\'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'70\', \'text\': \'\'}]', 'Ultra Prism', '2', 'Dewpider', '', 'It delivers headbutts with the water bubble on its head. Small Pokémon get sucked into the bubble, where they drown.', 'Seventh', '100', 'https://images.pokemoncard.io/images/sm5/sm5-17.png', 'unlimited: Legal, expanded: Legal', '', 'Araquanid', '752', 'TPCI', 'Rare', '', '02/02/2018', '', 'Colorless, Colorless', '', 'Sun & Moon', '17', 'Stage 1', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('sm5-170', '', '', '', '', 'Ultra Prism', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm5/sm5-170.png', 'unlimited: Legal, expanded: Legal', '', 'Unit Energy GrassFireWater', '', 'TPCI', 'Rare Secret', '', '02/02/2018', '', '', '[\'This card provides Colorless Energy.\', \'While this card is attached to a Pokémon, it provides Grass, Fire, and Water Energy but provides only 1 Energy at a time.\']', 'Sun & Moon', '170', 'Special', 'Energy', '', ''),
('sm5-171', '', '', '', '', 'Ultra Prism', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm5/sm5-171.png', 'unlimited: Legal, expanded: Legal', '', 'Unit Energy LightningPsychicMetal', '', 'TPCI', 'Rare Secret', '', '02/02/2018', '', '', '[\'This card provides Colorless Energy.\', \'While this card is attached to a Pokémon, it provides Lightning, Psychic, and Metal Energy but provides only 1 Energy at a time.\']', 'Sun & Moon', '171', 'Special', 'Energy', '', ''),
('sm5-172', '[{\'name\': \'Psychic Transfer\', \'text\': \'As often as you like during your turn (before your attack), you may move a Psychic Energy from 1 of your Pokémon to another of your Pokémon.\', \'type\': \'Ability\'}]', '', '5ban Graphics', '[{\'name\': \'Moongeist Beam\', \'cost\': [\'Psychic\', \'Psychic\', \'Psychic\', \'Psychic\'], \'convertedEnergyCost\': 4, \'damage\': \'120\', \'text\': \"The Defending Pokémon can\'t be healed during your opponent\'s next turn.\"}, {\'name\': \'Lunar Fall-GX\', \'cost\': [\'Psychic\', \'Psychic\', \'Psychic\'], \'convertedEnergyCost\': 3, \'damage\': \'\', \'text\': \"Knock Out 1 of your opponent\'s Basic Pokémon that isn\'t a Pokémon-GX. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Ultra Prism', '2', 'Cosmoem', '', '', 'Seventh', '250', 'https://images.pokemoncard.io/images/sm5/sm5-172.png', 'unlimited: Legal, expanded: Legal', '', 'Lunala-GX', '792', 'TPCI', 'Rare Secret', '', '02/02/2018', 'type: Fighting, value: -20', 'Colorless, Colorless', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', '172', 'Stage 2, GX', 'Pokémon', 'Psychic', 'type: Darkness, value: ×2');
