('sm6-108', '', '', 'Sanosuke Sakuma', '', 'Forbidden Light', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm6/sm6-108.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Judge', '', 'TPCI', 'Uncommon', '', '05/04/2018', '', '', '[\'Each player shuffles their hand into their deck and draws 4 cards.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '108', 'Supporter', 'Trainer', '', ''),
('sm6-109', '', '', 'Yusuke Ohmura', '', 'Forbidden Light', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm6/sm6-109.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Lady', '', 'TPCI', 'Uncommon', '', '05/04/2018', '', '', '[\'Search your deck for up to 4 basic Energy cards, reveal them, and put them into your hand. Then, shuffle your deck.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '109', 'Supporter', 'Trainer', '', ''),
('sm6-11', '', '', 'Hitoshi Ariga', '[{\'name\': \'High Jump Kick\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'20\', \'text\': \'\'}, {\'name\': \'White Ray\', \'cost\': [\'Grass\', \'Grass\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'90+\', \'text\': \'If you have only 1 Prize card remaining, this attack does 90 more damage.\'}]', 'Forbidden Light', '', '', '', 'One of the Ultra Beasts. It refuses to touch anything, perhaps because it senses some uncleanness in this world.', 'Seventh', '110', 'https://images.pokemoncard.io/images/sm6/sm6-11.png', 'unlimited: Legal, expanded: Legal', '', 'Pheromosa', '795', 'TPCI', 'Rare Holo', '', '05/04/2018', '', '', '', 'Sun & Moon', '11', 'Basic, Ultra Beast', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('sm6-110', '', '', 'Hitoshi Ariga', '', 'Forbidden Light', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm6/sm6-110.png', 'unlimited: Legal, expanded: Legal', '', 'Lysandre ◇', '', 'TPCI', 'Rare Prism Star', '', '05/04/2018', '', '', '[\"For each of your Fire Pokémon in play, put a card from your opponent\'s discard pile in the Lost Zone.\", \'You may play only 1 Supporter card during your turn (before your attack).\', \"◇ (Prism Star) Rule: You can\'t have more than 1 ◇ card with the same name in your deck. If a ◇ card would go to the discard pile, put it in the Lost Zone instead.\"]', 'Sun & Moon', '110', 'Supporter, Prism Star', 'Trainer', '', ''),
('sm6-111', '', '', 'Ryo Ueda', '', 'Forbidden Light', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm6/sm6-111.png', 'unlimited: Legal, expanded: Legal', '', 'Lysandre Labs', '', 'TPCI', 'Uncommon', '', '05/04/2018', '', '', '[\"Pokémon Tool cards in play (both yours and your opponent\'s) have no effect.\", \"This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can\'t play this card.\"]', 'Sun & Moon', '111', 'Stadium', 'Trainer', '', ''),
('sm6-112', '', '', 'Toyste Beach', '', 'Forbidden Light', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm6/sm6-112.png', 'unlimited: Legal, expanded: Legal', '', 'Metal Frying Pan', '', 'TPCI', 'Uncommon', '', '05/04/2018', '', '', '[\"Attach a Pokémon Tool to 1 of your Pokémon that doesn\'t already have a Pokémon Tool attached to it.\", \"The Metal Pokémon this card is attached to takes 30 less damage from your opponent\'s attacks (after applying Weakness and Resistance) and has no Weakness.\", \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '112', 'Pokémon Tool', 'Trainer', '', ''),
('sm6-112a', '', '', 'Ryo Ueda', '', 'Forbidden Light', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm6/sm6-112a.png', 'unlimited: Legal, expanded: Legal', '', 'Metal Frying Pan', '', 'TPCI', 'Uncommon', '', '05/04/2018', '', '', '[\"Attach a Pokémon Tool to 1 of your Pokémon that doesn\'t already have a Pokémon Tool attached to it.\", \"The Metal Pokémon this card is attached to takes 30 less damage from your opponent\'s attacks (after applying Weakness and Resistance) and has no Weakness.\", \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '112a', 'Pokémon Tool', 'Trainer', '', ''),
('sm6-113', '', '', 'Eske Yoshinob', '', 'Forbidden Light', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm6/sm6-113.png', 'unlimited: Legal, expanded: Legal', '', 'Mysterious Treasure', '', 'TPCI', 'Uncommon', '', '05/04/2018', '', '', '[\'Discard a card from your hand. If you do, search your deck for a Psychic or Dragon Pokémon, reveal it, and put it into your hand. Then, shuffle your deck.\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '113', 'Item', 'Trainer', '', ''),
('sm6-113a', '', '', 'Eske Yoshinob', '', 'Forbidden Light', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm6/sm6-113a.png', 'unlimited: Legal, expanded: Legal', '', 'Mysterious Treasure', '', 'TPCI', 'Uncommon', '', '05/04/2018', '', '', '[\'Discard a card from your hand. If you do, search your deck for a Psychic or Dragon Pokémon, reveal it, and put it into your hand. Then, shuffle your deck.\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '113a', 'Item', 'Trainer', '', ''),
('sm6-114', '', '', 'Megumi Mizutani', '', 'Forbidden Light', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm6/sm6-114.png', 'unlimited: Legal, expanded: Legal', '', 'Ultra Recon Squad', '', 'TPCI', 'Uncommon', '', '05/04/2018', '', '', '[\'Discard up to 2 Ultra Beast cards from your hand. Draw 3 cards for each card you discarded in this way.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '114', 'Supporter', 'Trainer', '', ''),
('sm6-115', '', '', '5ban Graphics', '', 'Forbidden Light', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm6/sm6-115.png', 'unlimited: Legal, expanded: Legal', '', 'Ultra Space', '', 'TPCI', 'Uncommon', '', '05/04/2018', '', '', '[\"Once during each player\'s turn, that player may search their deck for an Ultra Beast card, reveal it, put it into their hand, and shuffle their deck.\", \"This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can\'t play this card.\"]', 'Sun & Moon', '115', 'Stadium', 'Trainer', '', ''),
('sm6-116', '', '', 'Toyste Beach', '', 'Forbidden Light', '', '', '', '', 'Seventh', '60', 'https://images.pokemoncard.io/images/sm6/sm6-116.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Unidentified Fossil', '', 'TPCI', 'Uncommon', '', '05/04/2018', '', '', '[\'Play this card as if it were a 60-HP Colorless Basic Pokémon. At any time during your turn (before your attack), you may discard this card from play.\', \"This card can\'t retreat.\", \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '116', 'Item', 'Trainer', '', ''),
('sm6-117', '', '', '', '', 'Forbidden Light', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm6/sm6-117.png', 'unlimited: Legal, expanded: Legal', '', 'Beast Energy ◇', '', 'TPCI', 'Rare Prism Star', '', '05/04/2018', '', '', '[\'This card provides Colorless Energy.\', \"While this card is attached to an Ultra Beast, it provides every type of Energy but provides only 1 Energy at a time. The attacks of the Ultra Beast this card is attached to do 30 more damage to your opponent\'s Active Pokémon (before applying Weakness and Resistance).\", \"◇ (Prism Star) Rule: You can\'t have more than 1 ◇ card with the same name in your deck. If a ◇ card would go to the discard pile, put it in the Lost Zone instead.\"]', 'Sun & Moon', '117', 'Special, Prism Star', 'Energy', '', ''),
('sm6-118', '', '', '', '', 'Forbidden Light', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm6/sm6-118.png', 'unlimited: Legal, expanded: Legal', '', 'Unit Energy FightingDarknessFairy', '', 'TPCI', 'Uncommon', '', '05/04/2018', '', '', '[\'This card provides Colorless Energy.\', \'While this card is attached to a Pokémon, it provides Fighting, Darkness, and Fairy Energy but provides only 1 Energy at a time.\']', 'Sun & Moon', '118', 'Special', 'Energy', '', ''),
