('sm6-12', '', '', 'Suwama Chiaki', '[{\'name\': \'Limbo Limbo\', \'cost\': [], \'convertedEnergyCost\': 0, \'damage\': \'\', \'text\': \'Search your deck for up to 2 basic Energy cards and attach them to your Pokémon in any way you like. Then, shuffle your deck.\'}, {\'name\': \'Alolan Club\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20×\', \'text\': \'This attack does 20 damage for each of your Pokémon in play that has Alolan in its name.\'}]', 'Forbidden Light', '2', 'Cubone', '', 'Its custom is to mourn its lost companions. Mounds of dirt by the side of the road mark the graves of the Marowak.', 'Seventh', '120', 'https://images.pokemoncard.io/images/sm6/sm6-12.png', 'unlimited: Legal, expanded: Legal', '', 'Alolan Marowak', '105', 'TPCI', 'Rare', '', '05/04/2018', '', 'Colorless, Colorless', '', 'Sun & Moon', '12', 'Stage 1', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('sm6-120', '[{\'name\': \'Shuriken Flurry\', \'text\': \"When you play this Pokémon from your hand to evolve 1 of your Pokémon during your turn, you may put 3 damage counters on 1 of your opponent\'s Pokémon.\", \'type\': \'Ability\'}]', '', '5ban Graphics', '[{\'name\': \'Haze Slash\', \'cost\': [\'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'110\', \'text\': \'You may shuffle this Pokémon and all cards attached to it into your deck.\'}, {\'name\': \'Shadowy Hunter-GX\', \'cost\': [\'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'\', \'text\': \"This attack does 130 damage to 1 of your opponent\'s Benched Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.) (You can\'t use more than 1 GX attack in a game.)\"}]', 'Forbidden Light', '2', 'Frogadier', '', '', 'Seventh', '230', 'https://images.pokemoncard.io/images/sm6/sm6-120.png', 'unlimited: Legal, expanded: Legal', '', 'Greninja-GX', '658', 'TPCI', 'Rare Ultra', '', '05/04/2018', '', 'Colorless, Colorless', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', '120', 'Stage 2, GX', 'Pokémon', 'Water', 'type: Grass, value: ×2'),
('sm6-121', '', '', '5ban Graphics', '[{\'name\': \'Beast Raid\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'20×\', \'text\': \'This attack does 20 damage for each of your Ultra Beasts in play.\'}, {\'name\': \'Jet Needle\', \'cost\': [\'Psychic\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'110\', \'text\': \"This attack\'s damage isn\'t affected by Weakness or Resistance.\"}, {\'name\': \'Stinger-GX\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'\', \'text\': \"Both players shuffle their Prize cards into their decks. Then, each player puts the top 3 cards of their deck face down as their Prize cards. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Forbidden Light', '1', 'Poipole', '', '', 'Seventh', '210', 'https://images.pokemoncard.io/images/sm6/sm6-121.png', 'unlimited: Legal, expanded: Legal', '', 'Naganadel-GX', '804', 'TPCI', 'Rare Ultra', '', '05/04/2018', '', 'Colorless', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', '121', 'Stage 1, GX, Ultra Beast', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2'),
('sm6-122', '', '', '5ban Graphics', '[{\'name\': \'Aura Strike\', \'cost\': [\'Fighting\'], \'convertedEnergyCost\': 1, \'damage\': \'30+\', \'text\': \'If this Pokémon evolved from Riolu during this turn, this attack does 90 more damage.\'}, {\'name\': \'Cyclone Kick\', \'cost\': [\'Fighting\', \'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'130\', \'text\': \'\'}, {\'name\': \'Cantankerous Beatdown-GX\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30×\', \'text\': \"This attack does 30 damage for each damage counter on this Pokémon. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Forbidden Light', '2', 'Riolu', '', '', 'Seventh', '210', 'https://images.pokemoncard.io/images/sm6/sm6-122.png', 'unlimited: Legal, expanded: Legal', '', 'Lucario-GX', '448', 'TPCI', 'Rare Ultra', '', '05/04/2018', '', 'Colorless, Colorless', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', '122', 'Stage 1, GX', 'Pokémon', 'Fighting', 'type: Psychic, value: ×2');
