('sm7-125', '', '', 'Ryo Ueda', '', 'Celestial Storm', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm7/sm7-125.png', 'unlimited: Legal, expanded: Legal', '', 'Beast Ball', '', 'TPCI', 'Uncommon', '', '08/03/2018', '', '', '[\"Look at your face-down Prize cards. You may reveal an Ultra Beast card you find there, put it into your hand, and put this Beast Ball in its place. (If you don\'t reveal an Ultra Beast card, put this card in the discard pile.) Then, shuffle your face-down Prize cards.\", \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '125', 'Item', 'Trainer', '', ''),
('sm7-126', '', '', 'Ken Sugimori', '', 'Celestial Storm', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm7/sm7-126.png', 'unlimited: Legal, expanded: Legal', '', 'Bills Maintenance', '', 'TPCI', 'Uncommon', '', '08/03/2018', '', '', '[\'Shuffle a card from your hand into your deck. If you do, draw 3 cards.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '126', 'Supporter', 'Trainer', '', ''),
('sm7-127', '', '', 'Ken Sugimori', '', 'Celestial Storm', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm7/sm7-127.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Copycat', '', 'TPCI', 'Uncommon', '', '08/03/2018', '', '', '[\"Shuffle your hand into your deck. Then, draw a card for each card in your opponent\'s hand.\", \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '127', 'Supporter', 'Trainer', '', ''),
('sm7-128', '', '', 'Zu-Ka', '', 'Celestial Storm', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm7/sm7-128.png', 'unlimited: Legal, expanded: Legal', '', 'Energy Recycle System', '', 'TPCI', 'Uncommon', '', '08/03/2018', '', '', '[\'Choose 1:\\n• Put a basic Energy card from your discard pile into your hand.\\n• Shuffle 3 basic Energy cards from your discard pile into your deck.\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '128', 'Item', 'Trainer', '', ''),
('sm7-129', '', '', 'Ken Ikuji', '', 'Celestial Storm', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm7/sm7-129.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Energy Switch', '', 'TPCI', 'Uncommon', '', '08/03/2018', '', '', '[\'Move a basic Energy from 1 of your Pokémon to another of your Pokémon.\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '129', 'Item', 'Trainer', '', ''),
('sm7-13', '', '', 'Ken Sugimori', '[{\'name\': \'Pound\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'20\', \'text\': \'\'}, {\'name\': \'Clear the Room\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'\', \'text\': \'Your opponent reveals their hand. Choose a Supporter card you find there. Your opponent shuffles that card into their deck.\'}]', 'Celestial Storm', '2', 'Seedot', 'Shiftry', 'It lives deep in forests. With the leaf on its head, it makes a flute whose song makes listeners uneasy.', 'Seventh', '90', 'https://images.pokemoncard.io/images/sm7/sm7-13.png', 'unlimited: Legal, expanded: Legal', '', 'Nuzleaf', '274', 'TPCI', 'Uncommon', '', '08/03/2018', '', 'Colorless, Colorless', '', 'Sun & Moon', '13', 'Stage 1', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('sm7-130', '', '', 'Masakazu Fukuda', '', 'Celestial Storm', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm7/sm7-130.png', 'unlimited: Legal, expanded: Legal', '', 'Fisherman', '', 'TPCI', 'Uncommon', '', '08/03/2018', '', '', '[\'Put 4 basic Energy cards from your discard pile into your hand.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '130', 'Supporter', 'Trainer', '', ''),
('sm7-131', '', '', 'Katsura Tabata', '', 'Celestial Storm', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm7/sm7-131.png', 'unlimited: Legal, expanded: Legal', '', 'Friend Ball', '', 'TPCI', 'Uncommon', '', '08/03/2018', '', '', '[\"Search your deck for a Pokémon with the same type as 1 of your opponent\'s Pokémon in play, reveal it, and put it into your hand. Then, shuffle your deck.\", \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '131', 'Item', 'Trainer', '', ''),
('sm7-132', '', '', 'TOKIYA', '', 'Celestial Storm', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm7/sm7-132.png', 'unlimited: Legal, expanded: Legal', '', 'Hau', '', 'TPCI', 'Uncommon', '', '08/03/2018', '', '', '[\'Draw 3 cards.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '132', 'Supporter', 'Trainer', '', ''),
('sm7-133', '', '', 'Naoki Saito', '', 'Celestial Storm', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm7/sm7-133.png', 'unlimited: Legal, expanded: Legal', '', 'Hiker', '', 'TPCI', 'Uncommon', '', '08/03/2018', '', '', '[\"Look at the top 5 cards of either player\'s deck and choose 1 of them. That player shuffles the other cards back into their deck. Then, put the card you chose on top of that deck.\", \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '133', 'Supporter', 'Trainer', '', ''),
('sm7-134', '', '', 'Yoshinobu Saito', '', 'Celestial Storm', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm7/sm7-134.png', 'unlimited: Legal, expanded: Legal', '', 'Hustle Belt', '', 'TPCI', 'Uncommon', '', '08/03/2018', '', '', '[\"Attach a Pokémon Tool to 1 of your Pokémon that doesn\'t already have a Pokémon Tool attached to it.\", \"If the Pokémon this card is attached to has 30 HP or less remaining and has any damage counters on it, its attacks do 60 more damage to your opponent\'s Active Pokémon (before applying Weakness and Resistance).\", \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '134', 'Pokémon Tool', 'Trainer', '', ''),
('sm7-135', '', '', 'Ayaka Yoshida', '', 'Celestial Storm', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm7/sm7-135.png', 'unlimited: Legal, expanded: Legal', '', 'Last Chance Potion', '', 'TPCI', 'Uncommon', '', '08/03/2018', '', '', '[\'Heal 120 damage from 1 of your Pokémon that has 30 HP or less remaining.\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '135', 'Item', 'Trainer', '', ''),
('sm7-136', '', '', 'Ryo Ueda', '', 'Celestial Storm', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm7/sm7-136.png', 'unlimited: Legal, expanded: Legal', '', 'Life Herb', '', 'TPCI', 'Uncommon', '', '08/03/2018', '', '', '[\'Flip a coin. If heads, heal 60 damage and remove all Special Conditions from 1 of your Pokémon.\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '136', 'Item', 'Trainer', '', ''),
('sm7-137', '', '', 'Megumi Mizutani', '', 'Celestial Storm', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm7/sm7-137.png', 'unlimited: Legal, expanded: Legal', '', 'Lisia', '', 'TPCI', 'Uncommon', '', '08/03/2018', '', '', '[\'Search your deck for up to 2 ◇ (Prism Star) cards, reveal them, and put them into your hand. Then, shuffle your deck.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '137', 'Supporter', 'Trainer', '', ''),
('sm7-138', '', '', 'Katsura Tabata', '', 'Celestial Storm', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm7/sm7-138.png', 'unlimited: Legal, expanded: Legal', '', 'Lure Ball', '', 'TPCI', 'Uncommon', '', '08/03/2018', '', '', '[\'Flip 3 coins. For each heads, put an Evolution Pokémon from your discard pile into your hand.\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '138', 'Item', 'Trainer', '', ''),
('sm7-139', '', '', 'Ken Sugimori', '', 'Celestial Storm', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm7/sm7-139.png', 'unlimited: Legal, expanded: Legal', '', 'The Masked Royal', '', 'TPCI', 'Uncommon', '', '08/03/2018', '', '', '[\'Attach a basic Energy card from your hand to one of your Stage 2 Grass, Fire, or Water Pokémon.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '139', 'Supporter', 'Trainer', '', ''),
('sm7-14', '', '', 'PLANETA Igarashi', '[{\'name\': \'Perplex\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'40\', \'text\': \"Your opponent\'s Active Pokémon is now Confused.\"}, {\'name\': \'Extrasensory\', \'cost\': [\'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'90+\', \'text\': \'If you have the same number of cards in your hand as your opponent, this attack does 90 more damage.\'}, {\'name\': \'Den of Iniquity-GX\', \'cost\': [\'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'\', \'text\': \"Choose 1 of your opponent\'s Pokémon. Your opponent shuffles that Pokémon and all cards attached to it into their deck. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Celestial Storm', '2', 'Nuzleaf', '', '', 'Seventh', '240', 'https://images.pokemoncard.io/images/sm7/sm7-14.png', 'unlimited: Legal, expanded: Legal', '', 'Shiftry-GX', '275', 'TPCI', 'Rare Holo GX', '', '08/03/2018', '', 'Colorless, Colorless', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', '14', 'Stage 2, GX', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('sm7-140', '', '', 'Katsura Tabata', '', 'Celestial Storm', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm7/sm7-140.png', 'unlimited: Legal, expanded: Legal', '', 'PokéNav', '', 'TPCI', 'Uncommon', '', '08/03/2018', '', '', '[\'Look at the top 3 cards of your deck. You may reveal a Pokémon or Energy card you find there and put it into your hand. Put the other cards back in any order.\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '140', 'Item', 'Trainer', '', ''),
('sm7-141', '', '', 'Eske Yoshinob', '', 'Celestial Storm', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm7/sm7-141.png', 'unlimited: Legal, expanded: Legal', '', 'Rainbow Brush', '', 'TPCI', 'Uncommon', '', '08/03/2018', '', '', '[\'Choose an Energy card attached to 1 of your Pokémon. Search your deck for a basic Energy card and switch it with that card. Shuffle the first Energy card into your deck.\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '141', 'Item', 'Trainer', '', ''),
('sm7-142', '', '', 'Ryo Ueda', '', 'Celestial Storm', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm7/sm7-142.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Rare Candy', '', 'TPCI', 'Uncommon', '', '08/03/2018', '', '', '[\"Choose 1 of your Basic Pokémon in play. If you have a Stage 2 card in your hand that evolves from that Pokémon, put that card onto the Basic Pokémon to evolve it. You can\'t use this card during your first turn or on a Basic Pokémon that was put into play this turn.\", \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '142', 'Item', 'Trainer', '', ''),
('sm7-143', '', '', '5ban Graphics', '', 'Celestial Storm', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm7/sm7-143.png', 'unlimited: Legal, expanded: Legal', '', 'Shrine of Punishment', '', 'TPCI', 'Uncommon', '', '08/03/2018', '', '', '[\"Between turns, put 1 damage counter on each Pokémon-GX and Pokémon-EX (both yours and your opponent\'s).\", \"This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can\'t play this card.\"]', 'Sun & Moon', '143', 'Stadium', 'Trainer', '', ''),
('sm7-144', '', '', 'Ryo Ueda', '', 'Celestial Storm', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm7/sm7-144.png', 'unlimited: Legal, expanded: Legal', '', 'Sky Pillar', '', 'TPCI', 'Uncommon', '', '08/03/2018', '', '', '[\"Prevent all effects of the opponent\'s attacks, including damage, done to Benched Pokémon (both yours and your opponent\'s).\", \"This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can\'t play this card.\"]', 'Sun & Moon', '144', 'Stadium', 'Trainer', '', ''),
('sm7-145', '', '', 'Hitoshi Ariga', '', 'Celestial Storm', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm7/sm7-145.png', 'unlimited: Legal, expanded: Legal', '', 'Stevens Resolve', '', 'TPCI', 'Rare Holo', '', '08/03/2018', '', '', '[\'Search your deck for up to 3 cards and put them into your hand. Then, shuffle your deck. Your turn ends.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '145', 'Supporter', 'Trainer', '', ''),
('sm7-146', '', '', 'Keiji Kinebuchi', '', 'Celestial Storm', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm7/sm7-146.png', 'unlimited: Legal, expanded: Legal', '', 'Super Scoop Up', '', 'TPCI', 'Uncommon', '', '08/03/2018', '', '', '[\'Flip a coin. If heads, put 1 of your Pokémon and all cards attached to it into your hand.\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '146', 'Item', 'Trainer', '', ''),
('sm7-147', '', '', 'Hiromichi Sugiyama', '', 'Celestial Storm', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm7/sm7-147.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Switch', '', 'TPCI', 'Uncommon', '', '08/03/2018', '', '', '[\'Switch your Active Pokémon with 1 of your Benched Pokémon.\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '147', 'Item', 'Trainer', '', ''),
('sm7-148', '', '', 'Megumi Mizutani', '', 'Celestial Storm', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm7/sm7-148.png', 'unlimited: Legal, expanded: Legal', '', 'Tate & Liza', '', 'TPCI', 'Uncommon', '', '08/03/2018', '', '', '[\'Choose 1:\\n• Shuffle your hand into your deck then draw 5 cards.\\n• Switch your Active Pokémon with 1 of your Benched Pokémon.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '148', 'Supporter', 'Trainer', '', ''),
('sm7-148a', '', '', 'You Iribi', '', 'Celestial Storm', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm7/sm7-148a.png', 'unlimited: Legal, expanded: Legal', '', 'Tate & Liza', '', 'TPCI', 'Uncommon', '', '08/03/2018', '', '', '[\'Choose 1:\\n• Shuffle your hand into your deck then draw 5 cards.\\n• Switch your Active Pokémon with 1 of your Benched Pokémon.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '148a', 'Supporter', 'Trainer', '', ''),
('sm7-149', '', '', 'Ken Sugimori', '', 'Celestial Storm', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm7/sm7-149.png', 'unlimited: Legal, expanded: Legal', '', 'TV Reporter', '', 'TPCI', 'Uncommon', '', '08/03/2018', '', '', '[\"Draw 3 cards. Then, discard a card from your hand. If you have no cards in your deck, you can\'t play this card.\", \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '149', 'Supporter', 'Trainer', '', ''),
('sm7-15', '', '', 'Ken Sugimori', '[{\'name\': \'Bubble\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Flip a coin. If heads, your opponent\'s Active Pokémon is now Paralyzed.\"}]', 'Celestial Storm', '1', '', 'Masquerain', 'When this Pokémon senses danger, a sweet fluid oozes from the tip of its head. The taste of it disgusts bird Pokémon.', 'Seventh', '50', 'https://images.pokemoncard.io/images/sm7/sm7-15.png', 'unlimited: Legal, expanded: Legal', '', 'Surskit', '283', 'TPCI', 'Common', '', '08/03/2018', '', 'Colorless', '', 'Sun & Moon', '15', 'Basic', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('sm7-150', '', '', 'Kagemaru Himeno', '', 'Celestial Storm', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm7/sm7-150.png', 'unlimited: Legal, expanded: Legal', '', 'Underground Expedition', '', 'TPCI', 'Uncommon', '', '08/03/2018', '', '', '[\'Look at the bottom 4 cards of your deck and put 2 of them into your hand. Put the other cards back on the bottom of your deck in any order.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '150', 'Supporter', 'Trainer', '', ''),
('sm7-151', '', '', '', '', 'Celestial Storm', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm7/sm7-151.png', 'unlimited: Legal, expanded: Legal', '', 'Rainbow Energy', '', 'TPCI', 'Uncommon', '', '08/03/2018', '', '', '[\'This card provides Colorless Energy. While in play, this card provides every type of Energy but provides only 1 Energy at a time. When you attach this card from your hand to 1 of your Pokémon, put 1 damage counter on that Pokémon.\']', 'Sun & Moon', '151', 'Special', 'Energy', '', ''),
('sm7-152', '', '', 'PLANETA Igarashi', '[{\'name\': \'Perplex\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'40\', \'text\': \"Your opponent\'s Active Pokémon is now Confused.\"}, {\'name\': \'Extrasensory\', \'cost\': [\'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'90+\', \'text\': \'If you have the same number of cards in your hand as your opponent, this attack does 90 more damage.\'}, {\'name\': \'Den of Iniquity-GX\', \'cost\': [\'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'\', \'text\': \"Choose 1 of your opponent\'s Pokémon. Your opponent shuffles that Pokémon and all cards attached to it into their deck. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Celestial Storm', '2', 'Nuzleaf', '', '', 'Seventh', '240', 'https://images.pokemoncard.io/images/sm7/sm7-152.png', 'unlimited: Legal, expanded: Legal', '', 'Shiftry-GX', '275', 'TPCI', 'Rare Ultra', '', '08/03/2018', '', 'Colorless, Colorless', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', '152', 'Stage 2, GX', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('sm7-153', '', '', '5ban Graphics', '[{\'name\': \'Slash\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'60\', \'text\': \'\'}, {\'name\': \'Explosive Kick\', \'cost\': [\'Fire\', \'Fire\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'210\', \'text\': \'Discard 2 Fire Energy from this Pokémon.\'}, {\'name\': \'Blaze Out-GX\', \'cost\': [\'Fire\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Discard 2 Energy from your opponent\'s Pokémon. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Celestial Storm', '1', 'Combusken', '', '', 'Seventh', '240', 'https://images.pokemoncard.io/images/sm7/sm7-153.png', 'unlimited: Legal, expanded: Legal', '', 'Blaziken-GX', '257', 'TPCI', 'Rare Ultra', '', '08/03/2018', '', 'Colorless', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', '153', 'Stage 2, GX', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('sm7-154', '[{\'name\': \'Legendary Ascent\', \'text\': \'When you play this Pokémon from your hand onto your Bench during your turn, you may switch it with your Active Pokémon. If you do, move any number of Water Energy from your other Pokémon to this Pokémon.\', \'type\': \'Ability\'}]', '', '5ban Graphics', '[{\'name\': \'Ice Wing\', \'cost\': [\'Water\', \'Water\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'130\', \'text\': \'\'}, {\'name\': \'Cold Crush-GX\', \'cost\': [\'Water\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Discard all Energy from both Active Pokémon. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Celestial Storm', '2', '', '', '', 'Seventh', '170', 'https://images.pokemoncard.io/images/sm7/sm7-154.png', 'unlimited: Legal, expanded: Legal', '', 'Articuno-GX', '144', 'TPCI', 'Rare Ultra', '', '08/03/2018', '', 'Colorless, Colorless', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', '154', 'Basic, GX', 'Pokémon', 'Water', 'type: Metal, value: ×2');
INSERT INTO `cards` (`id`, `abilities`, `ancient_trait`, `artist`, `attacks`, `card_set`, `converted`, `evolves_from`, `evolves_to`, `flavor_text`, `generation`, `hp`, `img`, `legalities`, `level`, `name`, `national_pokedex_numbers`, `publisher`, `rarity`, `regulation_mark`, `release_date`, `resistances`, `retreat_cost`, `rules`, `series`, `set_num`, `subtypes`, `supertype`, `types`, `weakness`) VALUES
('sm7-155', '[{\'name\': \'Extra Energy Bomb\', \'text\': \'Once during your turn (before your attack), you may attach 5 Energy cards from your discard pile to your Pokémon, except Pokémon-GX or Pokémon-EX, in any way you like. If you do, this Pokémon is Knocked Out.\', \'type\': \'Ability\'}]', '', '5ban Graphics', '[{\'name\': \'Electro Ball\', \'cost\': [\'Lightning\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'50\', \'text\': \'\'}, {\'name\': \'Crush and Burn-GX\', \'cost\': [\'Lightning\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30+\', \'text\': \"Discard any amount of Energy from your Pokémon. This attack does 50 more damage for each card you discarded in this way. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Celestial Storm', '1', 'Voltorb', '', '', 'Seventh', '190', 'https://images.pokemoncard.io/images/sm7/sm7-155.png', 'unlimited: Legal, expanded: Legal', '', 'Electrode-GX', '101', 'TPCI', 'Rare Ultra', '', '08/03/2018', 'type: Metal, value: -20', 'Colorless', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', '155', 'Stage 1, GX', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
('sm7-156', '[{\'name\': \'Magic Evens\', \'text\': \"Prevent all damage done to this Pokémon by your opponent\'s attacks if that damage is exactly 20, 40, 60, 80, 100, 120, 140, 160, 180, 200, 220, 240, or 260.\", \'type\': \'Ability\'}]', '', '5ban Graphics', '[{\'name\': \'Breakdown\', \'cost\': [\'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'\', \'text\': \"For each card in your opponent\'s hand, put 1 damage counter on their Active Pokémon.\"}, {\'name\': \'Life Trick-GX\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Heal all damage from this Pokémon. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Celestial Storm', '2', '', '', '', 'Seventh', '150', 'https://images.pokemoncard.io/images/sm7/sm7-156.png', 'unlimited: Legal, expanded: Legal', '', 'Mr. Mime-GX', '122', 'TPCI', 'Rare Ultra', '', '08/03/2018', '', 'Colorless, Colorless', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', '156', 'Basic, GX', 'Pokémon', 'Psychic', ''),
('sm7-157', '[{\'name\': \'Shady Move\', \'text\': \'Once during your turn (before your attack), if this Pokémon is your Active Pokémon, you may move 1 damage counter from 1 Pokémon to another Pokémon.\', \'type\': \'Ability\'}]', '', '5ban Graphics', '[{\'name\': \'Shadow Chant\', \'cost\': [\'Psychic\'], \'convertedEnergyCost\': 1, \'damage\': \'30+\', \'text\': \"This attack does 10 more damage for each Supporter card in your discard pile. You can\'t add more than 100 damage in this way.\"}, {\'name\': \'Tomb Hunt-GX\', \'cost\': [\'Psychic\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Put 3 cards from your discard pile into your hand. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Celestial Storm', '1', 'Shuppet', '', '', 'Seventh', '190', 'https://images.pokemoncard.io/images/sm7/sm7-157.png', 'unlimited: Legal, expanded: Legal', '', 'Banette-GX', '354', 'TPCI', 'Rare Ultra', '', '08/03/2018', 'type: Fighting, value: -20', 'Colorless', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', '157', 'Stage 1, GX', 'Pokémon', 'Psychic', 'type: Darkness, value: ×2'),
('sm7-158', '[{\'name\': \'Danger Perception\', \'text\': \"If this Pokémon\'s remaining HP is 100 or less, its attacks do 80 more damage to your opponent\'s Active Pokémon (before applying Weakness and Resistance).\", \'type\': \'Ability\'}]', '', '5ban Graphics', '[{\'name\': \'Steel Wing\', \'cost\': [\'Metal\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'80\', \'text\': \"During your opponent\'s next turn, this Pokémon takes 30 less damage from attacks (after applying Weakness and Resistance).\"}, {\'name\': \'Cross-Cut-GX\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'100+\', \'text\': \"If your opponent\'s Active Pokémon is an Evolution Pokémon, this attack does 100 more damage. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Celestial Storm', '1', 'Scyther', '', '', 'Seventh', '210', 'https://images.pokemoncard.io/images/sm7/sm7-158.png', 'unlimited: Legal, expanded: Legal', '', 'Scizor-GX', '212', 'TPCI', 'Rare Ultra', '', '08/03/2018', 'type: Psychic, value: -20', 'Colorless', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', '158', 'Stage 1, GX', 'Pokémon', 'Metal', 'type: Fire, value: ×2'),
('sm7-159', '[{\'name\': \'Ultra Wall\', \'text\': \"Your Ultra Beasts take 10 less damage from your opponent\'s attacks (after applying Weakness and Resistance).\", \'type\': \'Ability\'}]', '', '5ban Graphics', '[{\'name\': \'Gigaton Stomp\', \'cost\': [\'Metal\', \'Metal\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'120\', \'text\': \'\'}, {\'name\': \'Assembly-GX\', \'cost\': [\'Metal\', \'Metal\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50+\', \'text\': \"This attack does 50 more damage for each Prize card you have taken. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Celestial Storm', '3', '', '', '', 'Seventh', '180', 'https://images.pokemoncard.io/images/sm7/sm7-159.png', 'unlimited: Legal, expanded: Legal', '', 'Stakataka-GX', '805', 'TPCI', 'Rare Ultra', '', '08/03/2018', 'type: Psychic, value: -20', 'Colorless, Colorless, Colorless', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', '159', 'Basic, GX, Ultra Beast', 'Pokémon', 'Metal', 'type: Fire, value: ×2'),
('sm7-16', '', '', 'Yukiko Baba', '[{\'name\': \'Surprising Pattern\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Discard all Special Energy from each of your opponent\'s Pokémon.\"}, {\'name\': \'Hurricane Wing\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40×\', \'text\': \'Flip 4 coins. This attack does 40 damage for each heads.\'}]', 'Celestial Storm', '1', 'Surskit', '', 'Its wings and antennae dont cope well with moisture. After a rain, it faces sunward to dry off.', 'Seventh', '90', 'https://images.pokemoncard.io/images/sm7/sm7-16.png', 'unlimited: Legal, expanded: Legal', '', 'Masquerain', '284', 'TPCI', 'Uncommon', '', '08/03/2018', '', 'Colorless', '', 'Sun & Moon', '16', 'Stage 1', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('sm7-160', '[{\'name\': \'Stormy Winds\', \'text\': \'When you play this Pokémon from your hand onto your Bench during your turn, you may discard the top 3 cards of your deck. If you do, attach a basic Energy card from your discard pile to this Pokémon.\', \'type\': \'Ability\'}]', '', '5ban Graphics', '[{\'name\': \'Dragon Break\', \'cost\': [\'Grass\', \'Lightning\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'30×\', \'text\': \'This attack does 30 damage times the amount of basic Grass and basic Lightning Energy attached to your Pokémon.\'}, {\'name\': \'Tempest-GX\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Discard your hand and draw 10 cards. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Celestial Storm', '3', '', '', '', 'Seventh', '180', 'https://images.pokemoncard.io/images/sm7/sm7-160.png', 'unlimited: Legal, expanded: Legal', '', 'Rayquaza-GX', '384', 'TPCI', 'Rare Ultra', '', '08/03/2018', '', 'Colorless, Colorless, Colorless', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', '160', 'Basic, GX', 'Pokémon', 'Dragon', 'type: Fairy, value: ×2'),
('sm7-161', '', '', 'Kagemaru Himeno', '', 'Celestial Storm', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm7/sm7-161.png', 'unlimited: Legal, expanded: Legal', '', 'Apricorn Maker', '', 'TPCI', 'Rare Ultra', '', '08/03/2018', '', '', '[\'Search your deck for up to 2 Item cards that have the word \"Ball\" in their name, reveal them, and put them into your hand. Then, shuffle your deck.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '161', 'Supporter', 'Trainer', '', ''),
('sm7-162', '', '', 'Sanosuke Sakuma', '', 'Celestial Storm', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm7/sm7-162.png', 'unlimited: Legal, expanded: Legal', '', 'Bills Maintenance', '', 'TPCI', 'Rare Ultra', '', '08/03/2018', '', '', '[\'Shuffle a card from your hand into your deck. If you do, draw 3 cards.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '162', 'Supporter', 'Trainer', '', ''),
('sm7-163', '', '', 'Megumi Mizutani', '', 'Celestial Storm', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm7/sm7-163.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Copycat', '', 'TPCI', 'Rare Ultra', '', '08/03/2018', '', '', '[\"Shuffle your hand into your deck. Then, draw a card for each card in your opponent\'s hand.\", \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '163', 'Supporter', 'Trainer', '', ''),
('sm7-164', '', '', 'Naoki Saito', '', 'Celestial Storm', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm7/sm7-164.png', 'unlimited: Legal, expanded: Legal', '', 'Lisia', '', 'TPCI', 'Rare Ultra', '', '08/03/2018', '', '', '[\'Search your deck for up to 2 ◇ (Prism Star) cards, reveal them, and put them into your hand. Then, shuffle your deck.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '164', 'Supporter', 'Trainer', '', ''),
('sm7-165', '', '', 'Hitoshi Ariga', '', 'Celestial Storm', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm7/sm7-165.png', 'unlimited: Legal, expanded: Legal', '', 'Stevens Resolve', '', 'TPCI', 'Rare Ultra', '', '08/03/2018', '', '', '[\'Search your deck for up to 3 cards and put them into your hand. Then, shuffle your deck. Your turn ends.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '165', 'Supporter', 'Trainer', '', ''),
('sm7-166', '', '', 'Hideki Ishikawa', '', 'Celestial Storm', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm7/sm7-166.png', 'unlimited: Legal, expanded: Legal', '', 'Tate & Liza', '', 'TPCI', 'Rare Ultra', '', '08/03/2018', '', '', '[\'Choose 1:\\n• Shuffle your hand into your deck then draw 5 cards.\\n• Switch your Active Pokémon with 1 of your Benched Pokémon.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '166', 'Supporter', 'Trainer', '', ''),
('sm7-167', '', '', 'nagimiso', '', 'Celestial Storm', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm7/sm7-167.png', 'unlimited: Legal, expanded: Legal', '', 'TV Reporter', '', 'TPCI', 'Rare Ultra', '', '08/03/2018', '', '', '[\"Draw 3 cards. Then, discard a card from your hand. If you have no cards in your deck, you can\'t play this card.\", \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '167', 'Supporter', 'Trainer', '', ''),
('sm7-168', '', '', 'Kagemaru Himeno', '', 'Celestial Storm', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm7/sm7-168.png', 'unlimited: Legal, expanded: Legal', '', 'Underground Expedition', '', 'TPCI', 'Rare Ultra', '', '08/03/2018', '', '', '[\'Look at the bottom 4 cards of your deck and put 2 of them into your hand. Put the other cards back on the bottom of your deck in any order.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '168', 'Supporter', 'Trainer', '', ''),
('sm7-169', '', '', 'PLANETA Igarashi', '[{\'name\': \'Perplex\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'40\', \'text\': \"Your opponent\'s Active Pokémon is now Confused.\"}, {\'name\': \'Extrasensory\', \'cost\': [\'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'90+\', \'text\': \'If you have the same number of cards in your hand as your opponent, this attack does 90 more damage.\'}, {\'name\': \'Den of Iniquity-GX\', \'cost\': [\'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'\', \'text\': \"Choose 1 of your opponent\'s Pokémon. Your opponent shuffles that Pokémon and all cards attached to it into their deck. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Celestial Storm', '2', 'Nuzleaf', '', '', 'Seventh', '240', 'https://images.pokemoncard.io/images/sm7/sm7-169.png', 'unlimited: Legal, expanded: Legal', '', 'Shiftry-GX', '275', 'TPCI', 'Rare Rainbow', '', '08/03/2018', '', 'Colorless, Colorless', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', '169', 'Stage 2, GX', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
