('sm8-223', '[{\'name\': \'Lost Out\', \'text\': \"If your opponent\'s Pokémon is Knocked Out by damage from this Pokémon\'s attacks, put that Pokémon and all cards attached to it in the Lost Zone instead of the discard pile.\", \'type\': \'Ability\'}]', '', '5ban Graphics', '[{\'name\': \'Dusty Ruckus\', \'cost\': [\'Darkness\', \'Darkness\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'130\', \'text\': \"This attack does 30 damage to each of your opponent\'s Benched Basic Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}, {\'name\': \'Lay the Smackdown-GX\', \'cost\': [\'Darkness\', \'Darkness\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'220\', \'text\': \"This attack\'s damage isn\'t affected by any effects on your opponent\'s Active Pokémon. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Lost Thunder', '3', 'Pupitar', '', '', 'Seventh', '250', 'https://images.pokemoncard.io/images/sm8/sm8-223.png', 'unlimited: Legal, expanded: Legal', '', 'Tyranitar-GX', '248', 'TPCI', 'Rare Rainbow', '', '11/02/2018', 'type: Psychic, value: -20', 'Colorless, Colorless, Colorless', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', '223', 'Stage 2, GX', 'Pokémon', 'Darkness', 'type: Fighting, value: ×2'),
('sm8-224', '[{\'name\': \'Double Drive\', \'text\': \'This Pokémon may have up to 2 Pokémon Tool cards attached to it. If it loses this Ability, discard Pokémon Tool cards from it until only 1 remains.\', \'type\': \'Ability\'}]', '', 'Yoshinobu Saito', '[{\'name\': \'Burst Shot\', \'cost\': [\'Metal\', \'Metal\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'130\', \'text\': \'\'}, {\'name\': \'Break Buster-GX\', \'cost\': [\'Metal\', \'Metal\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'190\', \'text\': \"This attack\'s damage isn\'t affected by Resistance. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Lost Thunder', '2', '', '', '', 'Seventh', '180', 'https://images.pokemoncard.io/images/sm8/sm8-224.png', 'unlimited: Legal, expanded: Legal', '', 'Genesect-GX', '649', 'TPCI', 'Rare Rainbow', '', '11/02/2018', 'type: Psychic, value: -20', 'Colorless, Colorless', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', '224', 'Basic, GX', 'Pokémon', 'Metal', 'type: Fire, value: ×2'),
('sm8-225', '[{\'name\': \'Mysterious Guidance\', \'text\': \'When you play this Pokémon from your hand to evolve 1 of your Pokémon during your turn, you may search your deck for up to 2 Item cards, reveal them, and put them into your hand. Then, shuffle your deck.\', \'type\': \'Ability\'}]', '', '5ban Graphics', '[{\'name\': \'Snowy Wind\', \'cost\': [\'Fairy\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'70\', \'text\': \"This attack does 30 damage to 1 of your opponent\'s Benched Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}, {\'name\': \'Sublimation-GX\', \'cost\': [\'Fairy\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'\', \'text\': \"If your opponent\'s Active Pokémon is an Ultra Beast, it is Knocked Out. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Lost Thunder', '2', 'Alolan Vulpix', '', '', 'Seventh', '200', 'https://images.pokemoncard.io/images/sm8/sm8-225.png', 'unlimited: Legal, expanded: Legal', '', 'Alolan Ninetales-GX', '38', 'TPCI', 'Rare Rainbow', '', '11/02/2018', 'type: Darkness, value: -20', 'Colorless, Colorless', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', '225', 'Stage 1, GX', 'Pokémon', 'Fairy', 'type: Metal, value: ×2'),
('sm8-226', '', '', '5ban Graphics', '[{\'name\': \'Perplex\', \'cost\': [\'Fairy\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Your opponent\'s Active Pokémon is now Confused.\"}, {\'name\': \"Let\'s Snuggle & Fall\", \'cost\': [\'Fairy\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'10+\', \'text\': \"This attack does 30 more damage for each damage counter on your opponent\'s Active Pokémon.\"}, {\'name\': \'Dream Fear-GX\', \'cost\': [\'Fairy\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Choose 1 of your opponent\'s Benched Pokémon. Your opponent shuffles that Pokémon and all cards attached to it into their deck. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Lost Thunder', '1', '', '', '', 'Seventh', '170', 'https://images.pokemoncard.io/images/sm8/sm8-226.png', 'unlimited: Legal, expanded: Legal', '', 'Mimikyu-GX', '778', 'TPCI', 'Rare Rainbow', '', '11/02/2018', '', 'Colorless', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', '226', 'Basic, GX', 'Pokémon', 'Fairy', ''),
('sm8-227', '', '', 'PLANETA Igarashi', '[{\'name\': \'Psychic\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'30+\', \'text\': \"This attack does 30 more damage times the amount of Energy attached to your opponent\'s Active Pokémon.\"}, {\'name\': \'Pelagic Blade\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'170\', \'text\': \"This Pokémon can\'t use Pelagic Blade during your next turn.\"}, {\'name\': \'Lost Purge-GX\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'\', \'text\': \"Put your opponent\'s Active Pokémon and all cards attached to it in the Lost Zone. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Lost Thunder', '2', '', '', '', 'Seventh', '190', 'https://images.pokemoncard.io/images/sm8/sm8-227.png', 'unlimited: Legal, expanded: Legal', '', 'Lugia-GX', '249', 'TPCI', 'Rare Rainbow', '', '11/02/2018', 'type: Fighting, value: -20', 'Colorless, Colorless', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', '227', 'Basic, GX', 'Pokémon', 'Colorless', 'type: Lightning, value: ×2');
