('sm8-228', '', '', 'Yoshinobu Saito', '', 'Lost Thunder', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm8/sm8-228.png', 'unlimited: Legal, expanded: Legal', '', 'Adventure Bag', '', 'TPCI', 'Rare Secret', '', '11/02/2018', '', '', '[\'Search your deck for up to 2 Pokémon Tool cards, reveal them, and put them into your hand. Then, shuffle your deck.\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '228', 'Item', 'Trainer', '', ''),
('sm8-229', '', '', 'Eske Yoshinob', '', 'Lost Thunder', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm8/sm8-229.png', 'unlimited: Legal, expanded: Legal', '', 'Choice Helmet', '', 'TPCI', 'Rare Secret', '', '11/02/2018', '', '', '[\"Attach a Pokémon Tool to 1 of your Pokémon that doesn\'t already have a Pokémon Tool attached to it.\", \"The Pokémon this card is attached to takes 30 less damage from the attacks of your opponent\'s Pokémon-GX and Pokémon-EX (after applying Weakness and Resistance).\", \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '229', 'Pokémon Tool', 'Trainer', '', ''),
('sm8-23', '', '', 'kirisAki', '[{\'name\': \'Ram\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'\'}]', 'Lost Thunder', '1', '', 'Silcoon, Cascoon', 'It lives among the tall grass and in forests. It repels attacks by raising up the spikes on its rear.', 'Seventh', '60', 'https://images.pokemoncard.io/images/sm8/sm8-23.png', 'unlimited: Legal, expanded: Legal', '', 'Wurmple', '265', 'TPCI', 'Common', '', '11/02/2018', '', 'Colorless', '', 'Sun & Moon', '23', 'Basic', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('sm8-230', '', '', 'Toyste Beach', '', 'Lost Thunder', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm8/sm8-230.png', 'unlimited: Legal, expanded: Legal', '', 'Counter Gain', '', 'TPCI', 'Rare Secret', '', '11/02/2018', '', '', '[\"Attach a Pokémon Tool to 1 of your Pokémon that doesn\'t already have a Pokémon Tool attached to it.\", \'If you have more Prize cards remaining than your opponent, the attacks of the Pokémon this card is attached to cost Colorless less.\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '230', 'Pokémon Tool', 'Trainer', '', ''),
('sm8-231', '', '', 'Toyste Beach', '', 'Lost Thunder', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm8/sm8-231.png', 'unlimited: Legal, expanded: Legal', '', 'Custom Catcher', '', 'TPCI', 'Rare Secret', '', '11/02/2018', '', '', '[\"You may play 2 Custom Catcher cards at once.\\n• If you played 1 card, draw cards until you have 3 cards in your hand.\\n• If you played 2 cards, switch 1 of your opponent\'s Benched Pokémon with their Active Pokémon. (This effects works one time for 2 cards.)\", \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '231', 'Item', 'Trainer', '', ''),
('sm8-232', '', '', 'Eske Yoshinob', '', 'Lost Thunder', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm8/sm8-232.png', 'unlimited: Legal, expanded: Legal', '', 'Electropower', '', 'TPCI', 'Rare Secret', '', '11/02/2018', '', '', '[\"During this turn, your Lightning Pokémon\'s attacks do 30 more damage to your opponent\'s Active Pokémon (before applying Weakness and Resistance).\", \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '232', 'Item', 'Trainer', '', ''),
('sm8-233', '', '', '5ban Graphics', '', 'Lost Thunder', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm8/sm8-233.png', 'unlimited: Legal, expanded: Legal', '', 'Lost Blender', '', 'TPCI', 'Rare Secret', '', '11/02/2018', '', '', '[\'Put 2 cards from your hand in the Lost Zone. If you do, draw a card.\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '233', 'Item', 'Trainer', '', ''),
('sm8-234', '', '', 'Ryo Ueda', '', 'Lost Thunder', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm8/sm8-234.png', 'unlimited: Legal, expanded: Legal', '', 'Net Ball', '', 'TPCI', 'Rare Secret', '', '11/02/2018', '', '', '[\'Search your deck for a Basic Grass Pokémon or a Grass Energy card, reveal it, and put it into your hand. Then, shuffle your deck.\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '234', 'Item', 'Trainer', '', ''),
('sm8-235', '', '', 'Ayaka Yoshida', '', 'Lost Thunder', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm8/sm8-235.png', 'unlimited: Legal, expanded: Legal', '', 'Spell Tag', '', 'TPCI', 'Rare Secret', '', '11/02/2018', '', '', '[\"Attach a Pokémon Tool to 1 of your Pokémon that doesn\'t already have a Pokémon Tool attached to it.\", \"When the Psychic Pokémon this card is attached to is Knocked Out by damage from an opponent\'s attack, put 4 damage counters on your opponent\'s Pokémon in any way you like.\", \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '235', 'Pokémon Tool', 'Trainer', '', ''),
('sm8-236', '', '', 'Yoshinobu Saito', '', 'Lost Thunder', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm8/sm8-236.png', 'unlimited: Legal, expanded: Legal', '', 'Wait and See Hammer', '', 'TPCI', 'Rare Secret', '', '11/02/2018', '', '', '[\'You can use this card only if you go second, and only on your first turn.\', \"Discard an Energy from 1 of your opponent\'s Pokémon.\", \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '236', 'Item', 'Trainer', '', ''),
('sm8-24', '', '', 'Mina Nakai', '[{\'name\': \'Poison Sting\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Your opponent\'s Active Pokémon is now Poisoned.\"}]', 'Lost Thunder', '1', '', 'Silcoon, Cascoon', 'It lives among the tall grass and in forests. It repels attacks by raising up the spikes on its rear.', 'Seventh', '60', 'https://images.pokemoncard.io/images/sm8/sm8-24.png', 'unlimited: Legal, expanded: Legal', '', 'Wurmple', '265', 'TPCI', 'Common', '', '11/02/2018', '', 'Colorless', '', 'Sun & Moon', '24', 'Basic', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('sm8-25', '', '', 'Satoshi Shirai', '[{\'name\': \'Cocoon Collector\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Search your deck for up to 4 in any combination of Silcoon and Cascoon and put them onto your Bench. Then, shuffle your deck.\'}, {\'name\': \'Rolling Tackle\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'20\', \'text\': \'\'}]', 'Lost Thunder', '3', 'Wurmple', 'Beautifly', 'It drinks dew that collects on its silk and waits for evolution. Its hard cocoon repels attacks.', 'Seventh', '80', 'https://images.pokemoncard.io/images/sm8/sm8-25.png', 'unlimited: Legal, expanded: Legal', '', 'Silcoon', '266', 'TPCI', 'Uncommon', '', '11/02/2018', '', 'Colorless, Colorless, Colorless', '', 'Sun & Moon', '25', 'Stage 1', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('sm8-26', '', '', '313', '[{\'name\': \'Skill Dive\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"This attack does 50 damage to 1 of your opponent\'s Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}, {\'name\': \'Butterfly Edge\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'30\', \'text\': \"If your opponent\'s Pokémon is Knocked Out by damage from this attack, prevent all effects of attacks, including damage, done to this Pokémon during your opponent\'s next turn.\"}]', 'Lost Thunder', '1', 'Silcoon', '', 'It has an aggressive nature. It stabs prey with its long, narrow mouth to drain the preys fluids.', 'Seventh', '130', 'https://images.pokemoncard.io/images/sm8/sm8-26.png', 'unlimited: Legal, expanded: Legal', '', 'Beautifly', '267', 'TPCI', 'Rare', '', '11/02/2018', '', 'Colorless', '', 'Sun & Moon', '26', 'Stage 2', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('sm8-27', '', '', 'Aya Kusube', '[{\'name\': \'Cocoon Collector\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Search your deck for up to 4 in any combination of Silcoon and Cascoon and put them onto your Bench. Then, shuffle your deck.\'}, {\'name\': \'Ram\', \'cost\': [\'Grass\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'\'}]', 'Lost Thunder', '2', 'Wurmple', 'Dustox', 'It never forgets any attack it endured while in the cocoon. After evolution, it seeks payback.', 'Seventh', '70', 'https://images.pokemoncard.io/images/sm8/sm8-27.png', 'unlimited: Legal, expanded: Legal', '', 'Cascoon', '268', 'TPCI', 'Uncommon', '', '11/02/2018', '', 'Colorless, Colorless', '', 'Sun & Moon', '27', 'Stage 1', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('sm8-28', '[{\'name\': \'Hazardous Evolution\', \'text\': \"When you play this Pokémon from your hand to evolve 1 of your Pokémon during your turn, you may leave your opponent\'s Active Pokémon Paralyzed and Poisoned. If you do, put 3 damage counters instead of 1 on that Pokémon between turns.\", \'type\': \'Ability\'}]', '', 'Midori Harada', '[{\'name\': \'Gust\', \'cost\': [\'Grass\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'70\', \'text\': \'\'}]', 'Lost Thunder', '2', 'Cascoon', '', 'It violently flutters its wings to scatter toxic dust when attacked. It becomes active after sunset.', 'Seventh', '140', 'https://images.pokemoncard.io/images/sm8/sm8-28.png', 'unlimited: Legal, expanded: Legal', '', 'Dustox', '269', 'TPCI', 'Rare', '', '11/02/2018', '', 'Colorless, Colorless', '', 'Sun & Moon', '28', 'Stage 2', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('sm8-29', '', '', 'SATOSHI NAKAI', '[{\'name\': \'Fury Swipes\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10×\', \'text\': \'Flip 3 coins. This attack does 10 damage for each heads.\'}]', 'Lost Thunder', '1', '', 'Ninjask', 'It can sometimes live underground for more than 10 years. It absorbs nutrients from the roots of trees.', 'Seventh', '40', 'https://images.pokemoncard.io/images/sm8/sm8-29.png', 'unlimited: Legal, expanded: Legal', '', 'Nincada', '290', 'TPCI', 'Common', '', '11/02/2018', '', 'Colorless', '', 'Sun & Moon', '29', 'Basic', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('sm8-3', '', '', 'Kouki Saitou', '[{\'name\': \'Fury Cutter\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'10+\', \'text\': \'Flip 3 coins. If 1 of them is heads, this attack does 20 more damage. If 2 of them are heads, this attack does 50 more damage. If all of them are heads, this attack does 70 more damage.\'}]', 'Lost Thunder', '1', '', 'Scizor', 'While young, they live together deep in the mountains, training themselves in how to fight with their scythes and move at high speeds.', 'Seventh', '80', 'https://images.pokemoncard.io/images/sm8/sm8-3.png', 'unlimited: Legal, expanded: Legal', '', 'Scyther', '123', 'TPCI', 'Common', '', '11/02/2018', '', 'Colorless', '', 'Sun & Moon', '3', 'Basic', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('sm8-30', '[{\'name\': \'Molting\', \'text\': \'When you play this Pokémon from your hand to evolve 1 of your Pokémon during your turn, you may put a Shedinja from your discard pile onto your Bench.\', \'type\': \'Ability\'}]', '', 'kirisAki', '[{\'name\': \'X-Scissor\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'40+\', \'text\': \'Flip a coin. If heads, this attack does 40 more damage.\'}]', 'Lost Thunder', '', 'Nincada', 'Shedinja', 'Because it moves so quickly, it sometimes becomes unseeable. It congregates around tree sap.', 'Seventh', '80', 'https://images.pokemoncard.io/images/sm8/sm8-30.png', 'unlimited: Legal, expanded: Legal', '', 'Ninjask', '291', 'TPCI', 'Uncommon', '', '11/02/2018', '', '', '', 'Sun & Moon', '30', 'Stage 1', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('sm8-31', '', '', 'Akira Komayama', '[{\'name\': \'Bee March\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Search your deck for up to 3 Combee and put them onto your Bench. Then, shuffle your deck.\'}]', 'Lost Thunder', '1', '', 'Vespiquen', 'It collects and delivers honey to its colony. At night, they cluster to form a beehive and sleep.', 'Seventh', '40', 'https://images.pokemoncard.io/images/sm8/sm8-31.png', 'unlimited: Legal, expanded: Legal', '', 'Combee', '415', 'TPCI', 'Common', '', '11/02/2018', '', 'Colorless', '', 'Sun & Moon', '31', 'Basic', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('sm8-32', '', '', 'chibi', '[{\'name\': \'Commanding Queen\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'120\', \'text\': \'If you have 4 or fewer Grass Pokémon on your Bench, this attack does nothing.\'}]', 'Lost Thunder', '2', 'Combee', '', 'Its abdomen is a honeycomb for grubs. It raises its grubs on honey collected by Combee.', 'Seventh', '120', 'https://images.pokemoncard.io/images/sm8/sm8-32.png', 'unlimited: Legal, expanded: Legal', '', 'Vespiquen', '416', 'TPCI', 'Uncommon', '', '11/02/2018', '', 'Colorless, Colorless', '', 'Sun & Moon', '32', 'Stage 1', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('sm8-33', '[{\'name\': \'Floral Heal\', \'text\': \'Once during your turn (before your attack), you may heal 20 damage from your Active Grass Pokémon.\', \'type\': \'Ability\'}]', '', 'Sekio', '[{\'name\': \'Ram\', \'cost\': [\'Grass\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'\'}]', 'Lost Thunder', '1', '', '', 'The blooming of Gracidea flowers confers the power of flight upon it. Feelings of gratitude are the message it delivers.', 'Seventh', '70', 'https://images.pokemoncard.io/images/sm8/sm8-33.png', 'unlimited: Legal, expanded: Legal', '', 'Shaymin', '492', 'TPCI', 'Rare Holo', '', '11/02/2018', '', 'Colorless', '', 'Sun & Moon', '33', 'Basic', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
