('sm9-171', '', '', '5ban Graphics', '[{\'name\': \'Cheer Up\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Attach an Energy card from your hand to 1 of your Pokémon.\'}, {\'name\': \'Dump Truck Press\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'120+\', \'text\': \"If your opponent\'s Active Pokémon is an Evolution Pokémon, this attack does 120 more damage.\"}, {\'name\': \'Megaton Friends-GX\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'210\', \'text\': \"If this Pokémon has at least 1 extra Energy attached to it (in addition to this attack\'s cost), draw cards until you have 10 cards in your hand. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Team Up', '4', '', 'Vaporeon, Jolteon, Flareon, Sylveon, Espeon, Umbreon, Leafeon, Glaceon', '', 'Seventh', '270', 'https://images.pokemoncard.io/images/sm9/sm9-171.png', 'unlimited: Legal, expanded: Legal', '', 'Eevee & Snorlax-GX', '133, 143', 'TPCI', 'Rare Ultra', '', '02/01/2019', '', 'Colorless, Colorless, Colorless, Colorless', '[\'TAG TEAM rule: When your TAG TEAM is Knocked Out, your opponent takes 3 Prize cards.\']', 'Sun & Moon', '171', 'Basic, TAG TEAM, GX', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('sm9-172', '', '', 'Naoki Saito', '', 'Team Up', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm9/sm9-172.png', 'unlimited: Legal, expanded: Legal', '', 'Brocks Grit', '', 'TPCI', 'Rare Ultra', '', '02/01/2019', '', '', '[\'Shuffle 6 in any combination of Pokémon and basic Energy cards from your discard pile into your deck.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '172', 'Supporter', 'Trainer', '', ''),
('sm9-173', '', '', 'Kagemaru Himeno', '', 'Team Up', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm9/sm9-173.png', 'unlimited: Legal, expanded: Legal', '', 'Dana', '', 'TPCI', 'Rare Ultra', '', '02/01/2019', '', '', '[\"You can play this card only if your opponent\'s Active Pokémon is a Stage 2 Pokémon.\", \'Search your deck for up to 2 cards and put them into your hand. Then, shuffle your deck.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '173', 'Supporter', 'Trainer', '', ''),
('sm9-174', '', '', 'Sanosuke Sakuma', '', 'Team Up', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm9/sm9-174.png', 'unlimited: Legal, expanded: Legal', '', 'Erikas Hospitality', '', 'TPCI', 'Rare Ultra', '', '02/01/2019', '', '', '[\'You can play this card only if you have 4 or fewer other cards in your hand.\', \"Draw a card for each of your opponent\'s Pokémon in play.\", \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '174', 'Supporter', 'Trainer', '', ''),
('sm9-175', '', '', 'Kagemaru Himeno', '', 'Team Up', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm9/sm9-175.png', 'unlimited: Legal, expanded: Legal', '', 'Evelyn', '', 'TPCI', 'Rare Ultra', '', '02/01/2019', '', '', '[\"You can play this card only if your opponent\'s Active Pokémon is a Stage 1 Pokémon.\", \'Draw 4 cards.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '175', 'Supporter', 'Trainer', '', ''),
('sm9-176', '', '', 'Megumi Mizutani', '', 'Team Up', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm9/sm9-176.png', 'unlimited: Legal, expanded: Legal', '', 'Ingo & Emmet', '', 'TPCI', 'Rare Ultra', '', '02/01/2019', '', '', '[\'Look at the top card of your deck, and then choose 1:\\n• Discard your hand and draw 5 cards.\\n• Discard your hand and draw 5 cards from the bottom of your deck.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '176', 'Supporter', 'Trainer', '', ''),
('sm9-177', '', '', 'Hideki Ishikawa', '', 'Team Up', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm9/sm9-177.png', 'unlimited: Legal, expanded: Legal', '', 'Jasmine', '', 'TPCI', 'Rare Ultra', '', '02/01/2019', '', '', '[\"Search your deck for a Metal Pokémon, reveal it, and put it into your hand. If you go second and it\'s your first turn, search for 5 Metal Pokémon instead of 1. Then, shuffle your deck.\", \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '177', 'Supporter', 'Trainer', '', ''),
('sm9-178', '', '', 'Kagemaru Himeno', '', 'Team Up', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm9/sm9-178.png', 'unlimited: Legal, expanded: Legal', '', 'Morgan', '', 'TPCI', 'Rare Ultra', '', '02/01/2019', '', '', '[\'You can play this card only if you discard Dana, Evelyn, and Nita from your hand.\', \'Look at the top 12 cards of your deck and attach any number of Energy cards you find there to your Pokémon in any way you like. Shuffle the other cards back into your deck.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '178', 'Supporter', 'Trainer', '', ''),
('sm9-179', '', '', 'Hitoshi Ariga', '', 'Team Up', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm9/sm9-179.png', 'unlimited: Legal, expanded: Legal', '', 'Nanu', '', 'TPCI', 'Rare Ultra', '', '02/01/2019', '', '', '[\'Choose a Basic Darkness Pokémon in your discard pile. Switch it with 1 of your Pokémon in play. Any attached cards, damage counters, Special Conditions, turns in play, and any other effects remain on the new Pokémon.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '179', 'Supporter', 'Trainer', '', ''),
('sm9-18', '', '', 'Shigenori Negishi', '[{\'name\': \'Searing Flame\', \'cost\': [\'Fire\'], \'convertedEnergyCost\': 1, \'damage\': \'20\', \'text\': \"Your opponent\'s Active Pokémon is now Burned.\"}, {\'name\': \'Agility\', \'cost\': [\'Fire\', \'Fire\'], \'convertedEnergyCost\': 2, \'damage\': \'60\', \'text\': \"Flip a coin. If heads, prevent all effects of attacks, including damage, done to this Pokémon during your opponent\'s next turn.\"}]', 'Team Up', '1', 'Ponyta', '', 'Very competitive, this Pokémon will chase anything that moves fast in the hopes of racing it.', 'Seventh', '100', 'https://images.pokemoncard.io/images/sm9/sm9-18.png', 'unlimited: Legal, expanded: Legal', '', 'Rapidash', '78', 'TPCI', 'Uncommon', '', '02/01/2019', '', 'Colorless', '', 'Sun & Moon', '18', 'Stage 1', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('sm9-180', '', '', 'Kagemaru Himeno', '', 'Team Up', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm9/sm9-180.png', 'unlimited: Legal, expanded: Legal', '', 'Nita', '', 'TPCI', 'Rare Ultra', '', '02/01/2019', '', '', '[\"You can play this card only if your opponent\'s Active Pokémon is a Basic Pokémon.\", \"Put an Energy from your opponent\'s Active Pokémon on top of their deck.\", \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '180', 'Supporter', 'Trainer', '', '');
