('sm9-181', '', '', 'Hitoshi Ariga', '', 'Team Up', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm9/sm9-181.png', 'unlimited: Legal, expanded: Legal', '', 'Sabrinas Suggestion', '', 'TPCI', 'Rare Ultra', '', '02/01/2019', '', '', '[\'Your opponent reveals their hand. You may choose a Supporter card you find there and use the effect of that card as the effect of this card.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', '181', 'Supporter', 'Trainer', '', ''),
('sm9-182', '', '', '5ban Graphics', '[{\'name\': \'Pollen Hazard\', \'cost\': [\'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50\', \'text\': \"Your opponent\'s Active Pokémon is now Burned, Confused, and Poisoned.\"}, {\'name\': \'Solar Beam\', \'cost\': [\'Grass\', \'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'150\', \'text\': \'\'}, {\'name\': \'Evergreen-GX\', \'cost\': [\'Grass\', \'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'180\', \'text\': \"Heal all damage from this Pokémon. If this Pokémon has at least 1 extra Grass Energy attached to it (in addition to this attack\'s cost), shuffle all cards from your discard pile into your deck. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Team Up', '4', '', '', '', 'Seventh', '270', 'https://images.pokemoncard.io/images/sm9/sm9-182.png', 'unlimited: Legal, expanded: Legal', '', 'Celebi & Venusaur-GX', '3, 251', 'TPCI', 'Rare Rainbow', '', '02/01/2019', '', 'Colorless, Colorless, Colorless, Colorless', '[\'TAG TEAM rule: When your TAG TEAM is Knocked Out, your opponent takes 3 Prize cards.\']', 'Sun & Moon', '182', 'Basic, TAG TEAM, GX', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('sm9-183', '', '', '5ban Graphics', '[{\'name\': \'Super Splash\', \'cost\': [\'Water\', \'Water\', \'Water\', \'Water\', \'Water\'], \'convertedEnergyCost\': 5, \'damage\': \'180\', \'text\': \'\'}, {\'name\': \'Towering Splash-GX\', \'cost\': [\'Water\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \"If this Pokémon has at least 7 extra Water Energy attached to it (in addition to this attack\'s cost), this attack does 100 damage to each of your opponent\'s Benched Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.) (You can\'t use more than 1 GX attack in a game.)\"}]', 'Team Up', '4', '', 'Gyarados', '', 'Seventh', '300', 'https://images.pokemoncard.io/images/sm9/sm9-183.png', 'unlimited: Legal, expanded: Legal', '', 'Magikarp & Wailord-GX', '129, 321', 'TPCI', 'Rare Rainbow', '', '02/01/2019', '', 'Colorless, Colorless, Colorless, Colorless', '[\'TAG TEAM rule: When your TAG TEAM is Knocked Out, your opponent takes 3 Prize cards.\']', 'Sun & Moon', '183', 'Basic, TAG TEAM, GX', 'Pokémon', 'Water', 'type: Grass, value: ×2'),
('sm9-184', '', '', '5ban Graphics', '[{\'name\': \'Full Blitz\', \'cost\': [\'Lightning\', \'Lightning\', \'Lightning\'], \'convertedEnergyCost\': 3, \'damage\': \'150\', \'text\': \'Search your deck for up to 3 Lightning Energy cards and attach them to 1 of your Pokémon. Then, shuffle your deck.\'}, {\'name\': \'Tag Bolt-GX\', \'cost\': [\'Lightning\', \'Lightning\', \'Lightning\'], \'convertedEnergyCost\': 3, \'damage\': \'200\', \'text\': \"If this Pokémon has at least 3 extra Lightning Energy attached to it (in addition to this attack\'s cost), this attack does 170 damage to 1 of your opponent\'s Benched Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.) (You can\'t use more than 1 GX attack in a game.)\"}]', 'Team Up', '3', '', 'Raichu', '', 'Seventh', '240', 'https://images.pokemoncard.io/images/sm9/sm9-184.png', 'unlimited: Legal, expanded: Legal', '', 'Pikachu & Zekrom-GX', '25, 644', 'TPCI', 'Rare Rainbow', '', '02/01/2019', 'type: Metal, value: -20', 'Colorless, Colorless, Colorless', '[\'TAG TEAM rule: When your TAG TEAM is Knocked Out, your opponent takes 3 Prize cards.\']', 'Sun & Moon', '184', 'Basic, TAG TEAM, GX', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
('sm9-185', '', '', '5ban Graphics', '[{\'name\': \'Power Recharge\', \'cost\': [\'Lightning\'], \'convertedEnergyCost\': 1, \'damage\': \'30\', \'text\': \'Put all Electropower cards from your discard pile into your hand.\'}, {\'name\': \'Impact Bolt\', \'cost\': [\'Lightning\', \'Lightning\'], \'convertedEnergyCost\': 2, \'damage\': \'150\', \'text\': \'Discard all Lightning Energy from this Pokémon.\'}, {\'name\': \'Electrical-GX\', \'cost\': [\'Lightning\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Search your deck for up to 7 Pokémon, reveal them, and put them into your hand. Then, shuffle your deck. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Team Up', '3', 'Flaaffy', '', '', 'Seventh', '240', 'https://images.pokemoncard.io/images/sm9/sm9-185.png', 'unlimited: Legal, expanded: Legal', '', 'Ampharos-GX', '181', 'TPCI', 'Rare Rainbow', '', '02/01/2019', 'type: Metal, value: -20', 'Colorless, Colorless, Colorless', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', '185', 'Stage 2, GX', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
('sm9-186', '', '', '5ban Graphics', '[{\'name\': \'Poltergeist\', \'cost\': [\'Psychic\', \'Psychic\'], \'convertedEnergyCost\': 2, \'damage\': \'50×\', \'text\': \'Your opponent reveals their hand. This attack does 50 damage for each Trainer card you find there.\'}, {\'name\': \'Horror House-GX\', \'cost\': [\'Psychic\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Your opponent can\'t play any cards from their hand during their next turn. If this Pokémon has at least 1 extra Psychic Energy attached to it (in addition to this attack\'s cost), each player draws cards until they have 7 cards in their hand. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Team Up', '2', '', '', '', 'Seventh', '240', 'https://images.pokemoncard.io/images/sm9/sm9-186.png', 'unlimited: Legal, expanded: Legal', '', 'Gengar & Mimikyu-GX', '94, 778', 'TPCI', 'Rare Rainbow', '', '02/01/2019', 'type: Fighting, value: -20', 'Colorless, Colorless', '[\'TAG TEAM rule: When your TAG TEAM is Knocked Out, your opponent takes 3 Prize cards.\']', 'Sun & Moon', '186', 'Basic, TAG TEAM, GX', 'Pokémon', 'Psychic', 'type: Darkness, value: ×2'),
('sm9-187', '', '', '5ban Graphics', '[{\'name\': \'Rogue Ring\', \'cost\': [\'Darkness\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Search your deck for up to 2 cards and put them into your hand. Then, shuffle your deck.\'}, {\'name\': \'Dark Strike\', \'cost\': [\'Darkness\', \'Darkness\', \'Darkness\'], \'convertedEnergyCost\': 3, \'damage\': \'160\', \'text\': \"This Pokémon can\'t use Dark Strike during your next turn.\"}, {\'name\': \'Devilish Hands-GX\', \'cost\': [\'Darkness\', \'Darkness\', \'Darkness\'], \'convertedEnergyCost\': 3, \'damage\': \'\', \'text\': \"Choose 1 of your opponent\'s Pokémon-GX or Pokémon-EX 6 times. (You can choose the same Pokémon more than once.) For each time you chose a Pokémon, do 30 damage to it. This damage isn\'t affected by Weakness or Resistance. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Team Up', '3', '', '', '', 'Seventh', '190', 'https://images.pokemoncard.io/images/sm9/sm9-187.png', 'unlimited: Legal, expanded: Legal', '', 'Hoopa-GX', '720', 'TPCI', 'Rare Rainbow', '', '02/01/2019', 'type: Psychic, value: -20', 'Colorless, Colorless, Colorless', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', '187', 'Basic, GX', 'Pokémon', 'Darkness', 'type: Fighting, value: ×2'),
('sm9-188', '[{\'name\': \'Scar Charge\', \'text\': \'Once during your turn (before your attack), you may put 3 damage counters on this Pokémon. If you do, search your deck for up to 3 Darkness Energy cards and attach them to this Pokémon. Then, shuffle your deck.\', \'type\': \'Ability\'}]', '', '5ban Graphics', '[{\'name\': \'Crushing Punch\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'130\', \'text\': \"Discard a Special Energy from your opponent\'s Active Pokémon.\"}, {\'name\': \'Darkest Tornado-GX\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'10+\', \'text\': \"This attack does 50 more damage for each damage counter on this Pokémon. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Team Up', '3', 'Torracat', '', '', 'Seventh', '250', 'https://images.pokemoncard.io/images/sm9/sm9-188.png', 'unlimited: Legal, expanded: Legal', '', 'Incineroar-GX', '727', 'TPCI', 'Rare Rainbow', '', '02/01/2019', 'type: Psychic, value: -20', 'Colorless, Colorless, Colorless', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', '188', 'Stage 2, GX', 'Pokémon', 'Darkness', 'type: Fighting, value: ×2'),
('sm9-189', '[{\'name\': \'Metal Symbol\', \'text\': \"Each of your Pokémon that has any Metal Energy attached to it can\'t be affected by any Special Conditions. Remove any Special Conditions affecting those Pokémon.\", \'type\': \'Ability\'}]', '', '5ban Graphics', '[{\'name\': \'Dueling Saber\', \'cost\': [\'Metal\', \'Metal\'], \'convertedEnergyCost\': 2, \'damage\': \'50+\', \'text\': \'If there is any Stadium card in play, this attack does 60 more damage.\'}, {\'name\': \'Iron Rule-GX\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"During your opponent\'s next turn, their Pokémon can\'t attack. (This includes Pokémon that come into play on that turn.) (You can\'t use more than 1 GX attack in a game.)\"}]', 'Team Up', '1', '', '', '', 'Seventh', '170', 'https://images.pokemoncard.io/images/sm9/sm9-189.png', 'unlimited: Legal, expanded: Legal', '', 'Cobalion-GX', '638', 'TPCI', 'Rare Rainbow', '', '02/01/2019', 'type: Psychic, value: -20', 'Colorless', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', '189', 'Basic, GX', 'Pokémon', 'Metal', 'type: Fire, value: ×2'),
('sm9-19', '', '', 'Shin Nagasawa', '[{\'name\': \'Top Burner\', \'cost\': [\'Fire\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Discard all Fire Energy from this Pokémon. Then, discard a card from the top of your opponent\'s deck for each Energy you discarded in this way.\"}, {\'name\': \'Fire Spin\', \'cost\': [\'Fire\', \'Fire\', \'Fire\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'180\', \'text\': \'Discard 3 Energy from this Pokémon.\'}]', 'Team Up', '2', '', '', 'It is said to be the legendary bird Pokémon of fire. Every flap of its wings creates a dazzling flare of flames.', 'Seventh', '120', 'https://images.pokemoncard.io/images/sm9/sm9-19.png', 'unlimited: Legal, expanded: Legal', '', 'Moltres', '146', 'TPCI', 'Rare Holo', '', '02/01/2019', 'type: Fighting, value: -20', 'Colorless, Colorless', '', 'Sun & Moon', '19', 'Basic', 'Pokémon', 'Fire', 'type: Lightning, value: ×2'),
('sm9-190', '', '', '5ban Graphics', '[{\'name\': \'Buster Purge\', \'cost\': [\'Water\', \'Psychic\', \'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'240\', \'text\': \'Discard 3 Energy from this Pokémon.\'}, {\'name\': \'Aero Unit-GX\', \'cost\': [\'Psychic\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Attach 5 basic Energy cards from your discard pile to your Pokémon in any way you like. If this Pokémon has at least 1 extra Energy attached to it (in addition to this attack\'s cost), prevent all effects of attacks, including damage, done to it during your opponent\'s next turn. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Team Up', '1', '', '', '', 'Seventh', '250', 'https://images.pokemoncard.io/images/sm9/sm9-190.png', 'unlimited: Legal, expanded: Legal', '', 'Latias & Latios-GX', '380, 381', 'TPCI', 'Rare Rainbow', '', '02/01/2019', '', 'Colorless', '[\'TAG TEAM rule: When your TAG TEAM is Knocked Out, your opponent takes 3 Prize cards.\']', 'Sun & Moon', '190', 'Basic, TAG TEAM, GX', 'Pokémon', 'Dragon', 'type: Fairy, value: ×2'),
('sm9-191', '', '', '5ban Graphics', '[{\'name\': \'Cheer Up\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Attach an Energy card from your hand to 1 of your Pokémon.\'}, {\'name\': \'Dump Truck Press\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'120+\', \'text\': \"If your opponent\'s Active Pokémon is an Evolution Pokémon, this attack does 120 more damage.\"}, {\'name\': \'Megaton Friends-GX\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'210\', \'text\': \"If this Pokémon has at least 1 extra Energy attached to it (in addition to this attack\'s cost), draw cards until you have 10 cards in your hand. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Team Up', '4', '', 'Vaporeon, Jolteon, Flareon, Sylveon, Espeon, Umbreon, Leafeon, Glaceon', '', 'Seventh', '270', 'https://images.pokemoncard.io/images/sm9/sm9-191.png', 'unlimited: Legal, expanded: Legal', '', 'Eevee & Snorlax-GX', '133, 143', 'TPCI', 'Rare Rainbow', '', '02/01/2019', '', 'Colorless, Colorless, Colorless, Colorless', '[\'TAG TEAM rule: When your TAG TEAM is Knocked Out, your opponent takes 3 Prize cards.\']', 'Sun & Moon', '191', 'Basic, TAG TEAM, GX', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('sm9-192', '', '', 'Toyste Beach', '', 'Team Up', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm9/sm9-192.png', 'unlimited: Legal, expanded: Legal', '', 'Dangerous Drill', '', 'TPCI', 'Rare Secret', '', '02/01/2019', '', '', '[\'You can play this card only if you discard a Darkness Pokémon from your hand.\', \"Discard a Pokémon Tool or Special Energy card from 1 of your opponent\'s Pokémon, or discard any Stadium card in play.\", \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '192', 'Item', 'Trainer', '', ''),
('sm9-193', '', '', 'Eske Yoshinob', '', 'Team Up', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm9/sm9-193.png', 'unlimited: Legal, expanded: Legal', '', 'Electrocharger', '', 'TPCI', 'Rare Secret', '', '02/01/2019', '', '', '[\'Flip 2 coins. For each heads, shuffle an Electropower card from your discard pile into your deck.\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '193', 'Item', 'Trainer', '', ''),
('sm9-194', '', '', 'Ayaka Yoshida', '', 'Team Up', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm9/sm9-194.png', 'unlimited: Legal, expanded: Legal', '', 'Judge Whistle', '', 'TPCI', 'Rare Secret', '', '02/01/2019', '', '', '[\'Choose 1:\\n• Draw a card\\n• Put a Judge card from your discard pile into your hand.\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '194', 'Item', 'Trainer', '', ''),
('sm9-195', '', '', 'Yoshinobu Saito', '', 'Team Up', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm9/sm9-195.png', 'unlimited: Legal, expanded: Legal', '', 'Metal Goggles', '', 'TPCI', 'Rare Secret', '', '02/01/2019', '', '', '[\"Attach a Pokémon Tool to 1 of your Pokémon that doesn\'t already have a Pokémon Tool attached to it.\", \"The Metal Pokémon this card is attached to takes 30 less damage from your opponent\'s attacks (after applying Weakness and Resistance), and your opponent\'s attacks and Abilities can\'t put damage counters on it.\", \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '195', 'Pokémon Tool', 'Trainer', '', ''),
('sm9-196', '', '', 'Ayaka Yoshida', '', 'Team Up', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sm9/sm9-196.png', 'unlimited: Legal, expanded: Legal', '', 'Pokémon Communication', '', 'TPCI', 'Rare Secret', '', '02/01/2019', '', '', '[\'Reveal a Pokémon from your hand and put it into your deck. If you do, search your deck for a Pokémon, reveal it, and put it into your hand. Then, shuffle your deck.\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'Sun & Moon', '196', 'Item', 'Trainer', '', ''),
('sm9-2', '', '', 'Shibuzoh.', '[{\'name\': \'Tangle Drag\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Switch 1 of your opponent\'s Benched Pokémon with their Active Pokémon.\"}, {\'name\': \'Bug Bite\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'\'}]', 'Team Up', '1', '', 'Kakuna', 'Often found in forests and grasslands. It has a sharp, toxic barb of around two inches on top of its head.', 'Seventh', '40', 'https://images.pokemoncard.io/images/sm9/sm9-2.png', 'unlimited: Legal, expanded: Legal', '', 'Weedle', '13', 'TPCI', 'Common', '', '02/01/2019', '', 'Colorless', '', 'Sun & Moon', '2', 'Basic', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('sm9-20', '', '', 'sui', '[{\'name\': \'Fasten Claws\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10+\', \'text\': \'Flip a coin. If heads, this attack does 10 more damage.\'}]', 'Team Up', '1', '', 'Torracat', 'It doesnt allow its emotions to be easily seen. Earning its trust takes time. It prefers solitude.', 'Seventh', '60', 'https://images.pokemoncard.io/images/sm9/sm9-20.png', 'unlimited: Legal, expanded: Legal', '', 'Litten', '725', 'TPCI', 'Common', '', '02/01/2019', '', 'Colorless', '', 'Sun & Moon', '20', 'Basic', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('sm9-21', '', '', 'Sanosuke Sakuma', '[{\'name\': \'Roar\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Your opponent switches their Active Pokémon with 1 of their Benched Pokémon.\'}, {\'name\': \'Claw Slash\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60\', \'text\': \'\'}]', 'Team Up', '2', 'Litten', 'Incineroar', 'It boasts powerful front legs. With a single punch, it can bend an iron bar right over.', 'Seventh', '90', 'https://images.pokemoncard.io/images/sm9/sm9-21.png', 'unlimited: Legal, expanded: Legal', '', 'Torracat', '726', 'TPCI', 'Uncommon', '', '02/01/2019', '', 'Colorless, Colorless', '', 'Sun & Moon', '21', 'Stage 1', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('sm9-22', '[{\'name\': \'Floating Shell\', \'text\': \'If you have a Stadium card in play, this Pokémon has no Retreat Cost.\', \'type\': \'Ability\'}]', '', 'sui', '[{\'name\': \'Water Gun\', \'cost\': [\'Water\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'\'}]', 'Team Up', '1', '', 'Wartortle', 'It shelters itself in its shell, then strikes back with spouts of water at every opportunity.', 'Seventh', '50', 'https://images.pokemoncard.io/images/sm9/sm9-22.png', 'unlimited: Legal, expanded: Legal', '', 'Squirtle', '7', 'TPCI', 'Common', '', '02/01/2019', '', 'Colorless', '', 'Sun & Moon', '22', 'Basic', 'Pokémon', 'Water', 'type: Grass, value: ×2'),
('sm9-23', '', '', 'HYOGONOSUKE', '[{\'name\': \'Tackle\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'\'}, {\'name\': \'Rain Splash\', \'cost\': [\'Water\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'\'}]', 'Team Up', '1', '', 'Wartortle', 'It shelters itself in its shell, then strikes back with spouts of water at every opportunity.', 'Seventh', '70', 'https://images.pokemoncard.io/images/sm9/sm9-23.png', 'unlimited: Legal, expanded: Legal', '', 'Squirtle', '7', 'TPCI', 'Common', '', '02/01/2019', '', 'Colorless', '', 'Sun & Moon', '23', 'Basic', 'Pokémon', 'Water', 'type: Grass, value: ×2'),
('sm9-24', '', '', 'Misa Tsutsui', '[{\'name\': \'Tackle\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'\'}, {\'name\': \'Waterfall\', \'cost\': [\'Water\', \'Water\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'70\', \'text\': \'\'}]', 'Team Up', '2', 'Squirtle', 'Blastoise', 'When tapped, this Pokémon will pull in its head, but its tail will still stick out a little bit.', 'Seventh', '90', 'https://images.pokemoncard.io/images/sm9/sm9-24.png', 'unlimited: Legal, expanded: Legal', '', 'Wartortle', '8', 'TPCI', 'Uncommon', '', '02/01/2019', '', 'Colorless, Colorless', '', 'Sun & Moon', '24', 'Stage 1', 'Pokémon', 'Water', 'type: Grass, value: ×2'),
('sm9-25', '[{\'name\': \'Powerful Squall\', \'text\': \'Once during your turn (before your attack), you may look at the top 6 cards of your deck and attach any number of Water Energy cards you find there to your Pokémon in any way you like. Shuffle the other cards back into your deck.\', \'type\': \'Ability\'}]', '', 'Hitoshi Ariga', '[{\'name\': \'Hydro Tackle\', \'cost\': [\'Water\', \'Water\', \'Water\'], \'convertedEnergyCost\': 3, \'damage\': \'150\', \'text\': \'This Pokémon does 30 damage to itself.\'}]', 'Team Up', '3', 'Wartortle', '', 'It crushes its foe under its heavy body to cause fainting. In a pinch, it will withdraw inside its shell.', 'Seventh', '160', 'https://images.pokemoncard.io/images/sm9/sm9-25.png', 'unlimited: Legal, expanded: Legal', '', 'Blastoise', '9', 'TPCI', 'Rare', '', '02/01/2019', '', 'Colorless, Colorless, Colorless', '', 'Sun & Moon', '25', 'Stage 2', 'Pokémon', 'Water', 'type: Grass, value: ×2'),
('sm9-26', '', '', 'Kouki Saitou', '[{\'name\': \'Headache\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \"Flip a coin. If heads, your opponent can\'t play any Trainer cards from their hand during their next turn.\"}]', 'Team Up', '2', '', 'Golduck', 'Using psychokinesis gives it a headache, so it normally passes the time spacing out and doing as little as possible.', 'Seventh', '60', 'https://images.pokemoncard.io/images/sm9/sm9-26.png', 'unlimited: Legal, expanded: Legal', '', 'Psyduck', '54', 'TPCI', 'Common', '', '02/01/2019', '', 'Colorless, Colorless', '', 'Sun & Moon', '26', 'Basic', 'Pokémon', 'Water', 'type: Grass, value: ×2'),
('sm9-27', '', '', 'Masakazu Fukuda', '[{\'name\': \'Amnesia\', \'cost\': [\'Water\'], \'convertedEnergyCost\': 1, \'damage\': \'20\', \'text\': \"Choose 1 of your opponent\'s Active Pokémon\'s attacks. That Pokémon can\'t use that attack during your opponent\'s next turn.\"}, {\'name\': \'Swim\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'90\', \'text\': \"If any of your opponent\'s Pokémon have any Water Energy attached to them, you may do 90 damage to 1 of your opponent\'s Benched Pokémon instead of their Active Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'Team Up', '1', 'Psyduck', '', 'Even fast-swimming fish Pokémon can be disabled by Golduck. It brings them to a standstill and seizes them.', 'Seventh', '110', 'https://images.pokemoncard.io/images/sm9/sm9-27.png', 'unlimited: Legal, expanded: Legal', '', 'Golduck', '55', 'TPCI', 'Uncommon', '', '02/01/2019', '', 'Colorless', '', 'Sun & Moon', '27', 'Stage 1', 'Pokémon', 'Water', 'type: Grass, value: ×2'),
