('sma-SV67', '[{\'name\': \'Twilight Eyes\', \'text\': \"When you play this Pokémon from your hand to evolve 1 of your Pokémon during your turn, you may discard an Energy attached to your opponent\'s Active Pokémon.\", \'type\': \'Ability\'}]', '', '5ban Graphics', '[{\'name\': \'Accelerock\', \'cost\': [\'Fighting\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'120\', \'text\': \'\'}, {\'name\': \'Splintered Shards-GX\', \'cost\': [\'Fighting\'], \'convertedEnergyCost\': 1, \'damage\': \'30×\', \'text\': \"This attack does 30 damage for each Energy card in your opponent\'s discard pile. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Shiny Vault', '2', 'Rockruff', '', '', 'Seventh', '200', 'https://images.pokemoncard.io/images/sma/sma-SV67.png', 'unlimited: Legal, expanded: Legal', '', 'Lycanroc-GX', '745', 'TPCI', 'Rare Shiny GX', '', '8/23/2019', '', 'Colorless, Colorless', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', 'SV67', 'Stage 1, GX', 'Pokémon', 'Fighting', 'type: Grass, value: ×2'),
('sma-SV68', '', '', '5ban Graphics', '[{\'name\': \'Jet Punch\', \'cost\': [\'Fighting\'], \'convertedEnergyCost\': 1, \'damage\': \'30\', \'text\': \"This attack does 30 damage to 1 of your opponent\'s Benched Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}, {\'name\': \'Knuckle Impact\', \'cost\': [\'Fighting\', \'Fighting\', \'Fighting\'], \'convertedEnergyCost\': 3, \'damage\': \'160\', \'text\': \"This Pokémon can\'t attack during your next turn.\"}, {\'name\': \'Absorption-GX\', \'cost\': [\'Fighting\', \'Fighting\', \'Fighting\'], \'convertedEnergyCost\': 3, \'damage\': \'40×\', \'text\': \"This attack does 40 damage for each of your remaining Prize cards. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Shiny Vault', '2', '', '', '', 'Seventh', '190', 'https://images.pokemoncard.io/images/sma/sma-SV68.png', 'unlimited: Legal, expanded: Legal', '', 'Buzzwole-GX', '794', 'TPCI', 'Rare Shiny GX', '', '8/23/2019', '', 'Colorless, Colorless', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', 'SV68', 'Basic, GX, Ultra Beast', 'Pokémon', 'Fighting', 'type: Psychic, value: ×2'),
('sma-SV69', '', '', '5ban Graphics', '[{\'name\': \'Strafe\', \'cost\': [\'Darkness\'], \'convertedEnergyCost\': 1, \'damage\': \'30\', \'text\': \'You may switch this Pokémon with 1 of your Benched Pokémon.\'}, {\'name\': \'Shadow Bullet\', \'cost\': [\'Darkness\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'90\', \'text\': \"This attack does 30 damage to 1 of your opponent\'s Benched Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}, {\'name\': \'Dark Call-GX\', \'cost\': [\'Darkness\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'\', \'text\': \"Discard 2 Energy from your opponent\'s Pokémon. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Shiny Vault', '2', 'Eevee', '', '', 'Seventh', '200', 'https://images.pokemoncard.io/images/sma/sma-SV69.png', 'unlimited: Legal, expanded: Legal', '', 'Umbreon-GX', '197', 'TPCI', 'Rare Shiny GX', '', '8/23/2019', 'type: Psychic, value: -20', 'Colorless, Colorless', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', 'SV69', 'Stage 1, GX', 'Pokémon', 'Darkness', 'type: Fighting, value: ×2'),
('sma-SV7', '[{\'name\': \'Burning Fighter\', \'text\': \'When you play this Pokémon from your hand to evolve 1 of your Pokémon during your turn, you may discard the top 5 cards of your deck. If any of those cards are Fire Energy cards, attach them to this Pokémon.\', \'type\': \'Ability\'}]', '', 'nagimiso', '[{\'name\': \'Flamethrower\', \'cost\': [\'Fire\', \'Fire\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'80\', \'text\': \'Discard an Energy from this Pokémon.\'}]', 'Shiny Vault', '2', 'Charmander', 'Charizard', 'When it swings its burning tail, it elevates the air temperature to unbearably high levels.', 'Seventh', '80', 'https://images.pokemoncard.io/images/sma/sma-SV7.png', 'unlimited: Legal, expanded: Legal', '', 'Charmeleon', '5', 'TPCI', 'Rare Shiny', '', '8/23/2019', '', 'Colorless, Colorless', '', 'Sun & Moon', 'SV7', 'Stage 1', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('sma-SV70', '[{\'name\': \'Restoration\', \'text\': \'Once during your turn (before your attack), if this Pokémon is in your discard pile, you may put it onto your Bench. Then, attach a Darkness Energy card from your discard pile to this Pokémon.\', \'type\': \'Ability\'}]', '', '5ban Graphics', '[{\'name\': \'Dark Cleave\', \'cost\': [\'Darkness\', \'Darkness\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'130\', \'text\': \"This attack\'s damage isn\'t affected by Resistance.\"}, {\'name\': \'Dead End-GX\', \'cost\': [\'Darkness\', \'Darkness\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'\', \'text\': \"If your opponent\'s Active Pokémon is affected by a Special Condition, that Pokémon is Knocked Out. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Shiny Vault', '2', '', '', '', 'Seventh', '180', 'https://images.pokemoncard.io/images/sma/sma-SV70.png', 'unlimited: Legal, expanded: Legal', '', 'Darkrai-GX', '491', 'TPCI', 'Rare Shiny GX', '', '8/23/2019', 'type: Psychic, value: -20', 'Colorless, Colorless', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', 'SV70', 'Basic, GX', 'Pokémon', 'Darkness', 'type: Fighting, value: ×2'),
('sma-SV71', '', '', '5ban Graphics', '[{\'name\': \'Eat Sloppily\', \'cost\': [\'Darkness\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Discard the top 5 cards of your deck. If any of those cards are Energy cards, attach them to this Pokémon.\'}, {\'name\': \'Tyrannical Hole\', \'cost\': [\'Darkness\', \'Darkness\', \'Darkness\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 5, \'damage\': \'180\', \'text\': \'\'}, {\'name\': \'Glutton-GX\', \'cost\': [\'Darkness\', \'Darkness\', \'Darkness\', \'Darkness\', \'Darkness\'], \'convertedEnergyCost\': 5, \'damage\': \'100\', \'text\': \"If your opponent\'s Pokémon is Knocked Out by damage from this attack, take 2 more Prize cards. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Shiny Vault', '4', '', '', '', 'Seventh', '210', 'https://images.pokemoncard.io/images/sma/sma-SV71.png', 'unlimited: Legal, expanded: Legal', '', 'Guzzlord-GX', '799', 'TPCI', 'Rare Shiny GX', '', '8/23/2019', 'type: Psychic, value: -20', 'Colorless, Colorless, Colorless, Colorless', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', 'SV71', 'Basic, GX, Ultra Beast', 'Pokémon', 'Darkness', 'type: Fighting, value: ×2'),
