('sma-SV8', '', '', 'Kouki Saitou', '[{\'name\': \'Beacon\', \'cost\': [], \'convertedEnergyCost\': 0, \'damage\': \'\', \'text\': \'Search your deck for up to 2 Pokémon, reveal them, and put them into your hand. Then, shuffle your deck.\'}, {\'name\': \'Icy Snow\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'\'}]', 'Shiny Vault', '1', '', 'Ninetales', 'It exhales air colder than -58 degrees Fahrenheit. Elderly people in Alola call this Pokémon by an older name—Keokeo.', 'Seventh', '60', 'https://images.pokemoncard.io/images/sma/sma-SV8.png', 'unlimited: Legal, expanded: Legal', '', 'Alolan Vulpix', '37', 'TPCI', 'Rare Shiny', '', '8/23/2019', '', 'Colorless', '', 'Sun & Moon', 'SV8', 'Basic', 'Pokémon', 'Water', 'type: Metal, value: ×2'),
('sma-SV80', '', '', '5ban Graphics', '[{\'name\': \'Righteous Edge\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'20\', \'text\': \"Discard a Special Energy from your opponent\'s Active Pokémon.\"}, {\'name\': \'Berserk\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'80+\', \'text\': \'If your Benched Pokémon have any damage counters on them, this attack does 70 more damage.\'}, {\'name\': \'Big Wheel-GX\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Shuffle your hand into your deck. Then, draw 10 cards. (You can\'t use more than 1 GX attack in a game.)\"}]', 'Shiny Vault', '2', '', '', '', 'Seventh', '180', 'https://images.pokemoncard.io/images/sma/sma-SV80.png', 'unlimited: Legal, expanded: Legal', '', 'Drampa-GX', '780', 'TPCI', 'Rare Shiny GX', '', '8/23/2019', '', 'Colorless, Colorless', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', 'SV80', 'Basic, GX', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('sma-SV81', '', '', 'take', '', 'Shiny Vault', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sma/sma-SV81.png', 'unlimited: Legal, expanded: Legal', '', 'Aether Foundation Employee', '', 'TPCI', 'Rare Ultra', '', '8/23/2019', '', '', '[\'Put 3 Pokémon that have \"Alolan\" in their names from your discard pile into your hand.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', 'SV81', 'Supporter', 'Trainer', '', ''),
('sma-SV82', '', '', 'Yusuke Ohmura', '', 'Shiny Vault', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sma/sma-SV82.png', 'unlimited: Legal, expanded: Legal', '', 'Cynthia', '', 'TPCI', 'Rare Ultra', '', '8/23/2019', '', '', '[\'Shuffle your hand into your deck. Then, draw 6 cards.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', 'SV82', 'Supporter', 'Trainer', '', ''),
('sma-SV83', '', '', 'Masakazu Fukuda', '', 'Shiny Vault', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sma/sma-SV83.png', 'unlimited: Legal, expanded: Legal', '', 'Fisherman', '', 'TPCI', 'Rare Ultra', '', '8/23/2019', '', '', '[\'Put 4 basic Energy cards from your discard pile into your hand.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', 'SV83', 'Supporter', 'Trainer', '', ''),
('sma-SV84', '', '', 'Hitoshi Ariga', '', 'Shiny Vault', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sma/sma-SV84.png', 'unlimited: Legal, expanded: Legal', '', 'Guzma', '', 'TPCI', 'Rare Ultra', '', '8/23/2019', '', '', '[\"Switch 1 of your opponent\'s Benched Pokémon with their Active Pokémon. If you do, switch your Active Pokémon with 1 of your Benched Pokémon.\", \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', 'SV84', 'Supporter', 'Trainer', '', ''),
('sma-SV85', '', '', 'Naoki Saito', '', 'Shiny Vault', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sma/sma-SV85.png', 'unlimited: Legal, expanded: Legal', '', 'Hiker', '', 'TPCI', 'Rare Ultra', '', '8/23/2019', '', '', '[\"Look at the top 5 cards of either player\'s deck and choose 1 of them. That player shuffles the other cards back into their deck. Then, put the card you chose on top of that deck.\", \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', 'SV85', 'Supporter', 'Trainer', '', ''),
('sma-SV86', '', '', 'Kanako Eo', '', 'Shiny Vault', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sma/sma-SV86.png', 'unlimited: Legal, expanded: Legal', '', 'Lady', '', 'TPCI', 'Rare Ultra', '', '8/23/2019', '', '', '[\'Search your deck for up to 4 basic Energy cards, reveal them, and put them into your hand. Then, shuffle your deck.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', 'SV86', 'Supporter', 'Trainer', '', ''),
('sma-SV87', '', '', '5ban Graphics', '', 'Shiny Vault', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sma/sma-SV87.png', 'unlimited: Legal, expanded: Legal', '', 'Aether Paradise Conservation Area', '', 'TPCI', 'Rare Secret', '', '8/23/2019', '', '', '[\"Basic Grass and Basic Lightning Pokémon (both yours and your opponent\'s) take 30 less damage from the opponent\'s attacks (after applying Weakness and Resistance).\", \"This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can\'t play this card.\"]', 'Sun & Moon', 'SV87', 'Stadium', 'Trainer', '', ''),
('sma-SV88', '', '', '5ban Graphics', '', 'Shiny Vault', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sma/sma-SV88.png', 'unlimited: Legal, expanded: Legal', '', 'Brooklet Hill', '', 'TPCI', 'Rare Secret', '', '8/23/2019', '', '', '[\"Once during each player\'s turn, that player may search their deck for a Basic Water Pokémon or Basic Fighting Pokémon and, put it onto their Bench, and shuffle their deck.\", \"This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can\'t play this card.\"]', 'Sun & Moon', 'SV88', 'Stadium', 'Trainer', '', ''),
('sma-SV89', '', '', '5ban Graphics', '', 'Shiny Vault', '', '', '', '', 'Seventh', '', 'https://images.pokemoncard.io/images/sma/sma-SV89.png', 'unlimited: Legal, expanded: Legal', '', 'Mt. Coronet', '', 'TPCI', 'Rare Secret', '', '8/23/2019', '', '', '[\"Once during each player\'s turn, that player may put 2 Metal Energy cards from their discard pile into their hand.\", \"This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can\'t play this card.\"]', 'Sun & Moon', 'SV89', 'Stadium', 'Trainer', '', ''),
