('smp-SM244', '', '', 'Shibuzoh.', '[{\'name\': \'Yank Out\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Discard random cards from your opponent\'s hand until they have 5 cards in their hand.\"}, {\'name\': \'Tail Smash\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'Flip a coin. If tails, this attack does nothing.\'}]', 'SM Black Star Promos', '1', '', 'Ambipom', 'As it did more and more with its tail, its hands became clumsy. It makes its nest high in the treetops.', 'Seventh', '60', 'https://images.pokemoncard.io/images/smp/smp-SM244.png', 'unlimited: Legal, expanded: Legal', '', 'Aipom', '190', 'TPCI', 'Promo', '', '02/03/2017', '', 'Colorless', '', 'Sun & Moon', 'SM244', 'Basic', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('smp-SM245', '', '', 'NC Empire', '[{\'name\': \'Psybeam\', \'cost\': [\'Psychic\'], \'convertedEnergyCost\': 1, \'damage\': \'20\', \'text\': \"Your opponent\'s Active Pokémon is now Confused.\"}, {\'name\': \'Nonahex\', \'cost\': [\'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'\', \'text\': \"If your opponent\'s Active Pokémon has exactly 9 damage counters on it, that Pokémon is Knocked Out.\"}]', 'SM Black Star Promos', '1', 'Misdreavus', '', 'Feared for its wrath and the curses it spreads, this Pokémon will also, on a whim, cast spells that help people.', 'Seventh', '90', 'https://static.tcgcollector.com/content/images/79/1a/92/791a92b03191f535f33ce47c7d92efd735fb4fda1c7ebaf041bd448fe959ffe2.jpg', 'unlimited: Legal, expanded: Legal', '', 'Mismagius', '429', 'TPCI', 'Promo', '', '02/03/2017', 'type: Fighting, value: -20', 'Colorless', '', 'Sun & Moon', 'SM245', 'Stage 1', 'Pokémon', 'Psychic', 'type: Darkness, value: ×2'),
('smp-SM246', '', '', 'Ryuta Fuse', '', 'SM Black Star Promos', '', '', '', '', 'Seventh', '', 'https://static.tcgcollector.com/content/images/79/1a/92/791a92b03191f535f33ce47c7d92efd735fb4fda1c7ebaf041bd448fe959ffe2.jpg', 'unlimited: Legal, expanded: Legal', '', 'Sabrina & Brycen', '', 'TPCI', 'Promo', '', '02/03/2017', '', '', '[\'Search your deck for up to 2 basic Energy cards, reveal them, and put them into your hand. Then, shuffle your deck.\', \'When you play this card, you may discard 5 other cards from your hand. If you do, you may also search for up to 3 Pokémon of different types in this way.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'Sun & Moon', 'SM246', 'Supporter, TAG TEAM', 'Trainer', '', '');
INSERT INTO `cards` (`id`, `abilities`, `ancient_trait`, `artist`, `attacks`, `card_set`, `converted`, `evolves_from`, `evolves_to`, `flavor_text`, `generation`, `hp`, `img`, `legalities`, `level`, `name`, `national_pokedex_numbers`, `publisher`, `rarity`, `regulation_mark`, `release_date`, `resistances`, `retreat_cost`, `rules`, `series`, `set_num`, `subtypes`, `supertype`, `types`, `weakness`) VALUES
('smp-SM247', '', '', 'aky CG Works', '[{\'name\': \'Outrage\', \'cost\': [\'Fire\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30+\', \'text\': \'This attack does 10 more damage for each damage counter on this Pokémon.\'}, {\'name\': \'Flare Strike\', \'cost\': [\'Fire\', \'Fire\', \'Fire\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'230\', \'text\': \"This Pokémon can\'t use Flare Strike during your next turn.\"}, {\'name\': \'Double Blaze-GX\', \'cost\': [\'Fire\', \'Fire\', \'Fire\'], \'convertedEnergyCost\': 3, \'damage\': \'200+\', \'text\': \"If this Pokémon has at least 3 extra Fire Energy attached to it (in addition to this attack\'s cost), this attack does 100 more damage, and this attack\'s damage isn\'t affected by any effects on your opponent\'s Active Pokémon. (You can\'t use more than 1 GX attack in a game.)\"}]', 'SM Black Star Promos', '3', '', '', '', 'Seventh', '270', 'https://static.tcgcollector.com/content/images/5d/13/9d/5d139deaecc45d91dd0ea37fdeac4369fbd6f0bc98c840ef5ea652db0ebe73d9.jpg', 'unlimited: Legal, expanded: Legal', '', 'Reshiram & Charizard-GX', '6, 643', 'TPCI', 'Promo', '', '02/03/2017', '', 'Colorless, Colorless, Colorless', '[\'TAG TEAM rule: When your TAG TEAM is Knocked Out, your opponent takes 3 Prize cards.\']', 'Sun & Moon', 'SM247', 'Basic, TAG TEAM, GX', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('smp-SM248', '', '', '5ban Graphics', '[{\'name\': \'Full Blitz\', \'cost\': [\'Lightning\', \'Lightning\', \'Lightning\'], \'convertedEnergyCost\': 3, \'damage\': \'150\', \'text\': \'Search your deck for up to 3 Lightning Energy cards and attach them to 1 of your Pokemon. Then, shuffle your deck.\'}, {\'name\': \'Tag Bolt-GX\', \'cost\': [\'Lightning\', \'Lightning\', \'Lightning\'], \'convertedEnergyCost\': 3, \'damage\': \'200\', \'text\': \"If this Pokemon has at least 3 extra Lightning Energy attached to it (in addition to this attack\'s cost), this attack does 170 damage to 1 of your opponent\'s Benched Pokemon. (Don\'t apply Weakness and Resistance for Benched Pokemon.) (You can\'t use more than 1 GX attack in a game.)\"}]', 'SM Black Star Promos', '3', '', '', '', 'Seventh', '240', 'https://images.pokemoncard.io/images/smp/smp-SM248.png', 'unlimited: Legal, expanded: Legal', '', 'Pikachu & Zekrom-GX', '25, 644', 'TPCI', 'Promo', '', '02/03/2017', 'type: Metal, value: -20', 'Colorless, Colorless, Colorless', '[\'TAG TEAM rule: When your TAG TEAM is Knocked Out, your opponent takes 3 Prize cards.\']', 'Sun & Moon', 'SM248', 'Basic, TAG TEAM, GX', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
('smp-SM25', '[{\'name\': \'Sunny Day\', \'text\': \"The attacks of your Grass Pokémon and Fire Pokémon do 20 more damage to your opponent\'s Active Pokémon (before applying Weakness and Resistance).\", \'type\': \'Ability\'}]', '', 'Mitsuhiro Arita', '[{\'name\': \'Solar Beam\', \'cost\': [\'Grass\', \'Grass\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'80\', \'text\': \'\'}]', 'SM Black Star Promos', '2', 'Fomantis', '', 'It requires a lot of effort to maintain Lurantiss vivid coloring, but some collectors enjoy this work and treat it as their hobby.', 'Seventh', '100', 'https://images.pokemoncard.io/images/smp/smp-SM25.png', 'unlimited: Legal, expanded: Legal', '', 'Lurantis', '754', 'TPCI', 'Promo', '', '02/03/2017', '', 'Colorless, Colorless', '', 'Sun & Moon', 'SM25', 'Stage 1', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('smp-SM26', '[{\'name\': \'Queenly Majesty\', \'text\': \'When you play this Pokémon from your hand to evolve 1 of your Pokémon during your turn, you may have your opponent reveal their hand. Then, discard a card from it.\', \'type\': \'Ability\'}]', '', 'Naoki Saito', '[{\'name\': \'Trop Kick\', \'cost\': [\'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'80\', \'text\': \'Heal 20 damage and remove all Special Conditions from this Pokémon.\'}]', 'SM Black Star Promos', '2', 'Steenee', '', 'Its long, striking legs arent just for show but to be used to kick with skill. In victory, it shows off by kicking the defeated, laughing boisterously.', 'Seventh', '140', 'https://images.pokemoncard.io/images/smp/smp-SM26.png', 'unlimited: Legal, expanded: Legal', '', 'Tsareena', '763', 'TPCI', 'Promo', '', '02/03/2017', '', 'Colorless, Colorless', '', 'Sun & Moon', 'SM26', 'Stage 2', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('smp-SM27', '', '', 'TOKIYA', '[{\'name\': \'Flame Cloak\', \'cost\': [\'Fire\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'Attach a Fire Energy card from your discard pile to this Pokémon.\'}, {\'name\': \'Heat Blast\', \'cost\': [\'Fire\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'70\', \'text\': \'\'}]', 'SM Black Star Promos', '3', '', '', 'The shell on its back is chemically unstable and explodes violently if struck. The hole in its stomach is its weak point.', 'Seventh', '130', 'https://images.pokemoncard.io/images/smp/smp-SM27.png', 'unlimited: Legal, expanded: Legal', '', 'Turtonator', '776', 'TPCI', 'Promo', '', '02/03/2017', '', 'Colorless, Colorless, Colorless', '', 'Sun & Moon', 'SM27', 'Basic', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('smp-SM28', '[{\'name\': \'Strong Charge\', \'text\': \'Once during your turn (before your attack), you may search your deck for a Grass Energy card and a Lightning Energy card and attach them to your Pokémon in any way you like. Then, shuffle your deck.\', \'type\': \'Ability\'}]', '', 'Shin Nagasawa', '[{\'name\': \'Electro Cannon\', \'cost\': [\'Lightning\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'150\', \'text\': \'Discard 3 Energy from this Pokémon.\'}]', 'SM Black Star Promos', '3', 'Charjabug', '', 'It produces electricity via an electrical organ in its abdomen. It overwhelms bird Pokémon with shocking beams of electrical energy.', 'Seventh', '150', 'https://images.pokemoncard.io/images/smp/smp-SM28.png', 'unlimited: Legal, expanded: Legal', '', 'Vikavolt', '738', 'TPCI', 'Promo', '', '02/03/2017', 'type: Metal, value: -20', 'Colorless, Colorless, Colorless', '', 'Sun & Moon', 'SM28', 'Stage 2', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
('smp-SM29', '', '', 'Mitsuhiro Arita', '[{\'name\': \'Haunt\', \'cost\': [\'Psychic\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Put 1 damage counter on your opponent\'s Active Pokémon.\"}, {\'name\': \'Astonish\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'\', \'text\': \"Choose a random card from your opponent\'s hand. Your opponent reveals that card and shuffles it into their deck.\"}]', 'SM Black Star Promos', '1', '', '', 'Its actual appearance is unknown. A scholar who saw what was under its rag was overwhelmed by terror and died from the shock.', 'Seventh', '70', 'https://images.pokemoncard.io/images/smp/smp-SM29.png', 'unlimited: Legal, expanded: Legal', '', 'Mimikyu', '778', 'TPCI', 'Promo', '', '02/03/2017', '', 'Colorless', '', 'Sun & Moon', 'SM29', 'Basic', 'Pokémon', 'Psychic', ''),
('smp-SM30', '', '', 'kirisAki', '[{\'name\': \'Flying Flip\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'\', \'text\': \"This attack does 20 damage to each of your opponent\'s Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}, {\'name\': \'Electric Ball\', \'cost\': [\'Lightning\', \'Lightning\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'100\', \'text\': \'\'}]', 'SM Black Star Promos', '', '', '', 'This guardian deity of Melemele is brimming with curiosity. It summons thunderclouds and stores their lightning inside its body.', 'Seventh', '110', 'https://images.pokemoncard.io/images/smp/smp-SM30.png', 'unlimited: Legal, expanded: Legal', '', 'Tapu Koko', '785', 'TPCI', 'Promo', '', '02/03/2017', 'type: Metal, value: -20', '', '', 'Sun & Moon', 'SM30', 'Basic', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
('smp-SM30a', '', '', 'kirisAki', '[{\'name\': \'Flying Flip\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'\', \'text\': \"This attack does 20 damage to each of your opponent\'s Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}, {\'name\': \'Electric Ball\', \'cost\': [\'Lightning\', \'Lightning\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'100\', \'text\': \'\'}]', 'SM Black Star Promos', '', '', '', 'This guardian deity of Melemele is brimming with curiosity. It summons thunderclouds and stores their lightning inside its body.', 'Seventh', '110', 'https://images.pokemoncard.io/images/smp/smp-SM30a.png', 'unlimited: Legal, expanded: Legal', '', 'Tapu Koko', '785', 'TPCI', 'Promo', '', '02/03/2017', 'type: Metal, value: -20', '', '', 'Sun & Moon', 'SM30a', 'Basic', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
