('smp-SM33', '[{\'name\': \'Aero Trail\', \'text\': \'When you play this Pokémon from your hand onto your Bench during your turn, you may move any number of Lightning Energy from your other Pokémon to this Pokémon. If you do, switch this Pokémon with your Active Pokémon.\', \'type\': \'Ability\'}]', '', '5ban Graphics', '[{\'name\': \'Sky-High Claws\', \'cost\': [\'Lightning\', \'Lightning\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'130\', \'text\': \'\'}, {\'name\': \'Tapu Thunder-GX\', \'cost\': [\'Lightning\', \'Lightning\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50×\', \'text\': \"This attack does 50 damage times the amount of Energy attached to all of your opponent\'s Pokémon. (You can\'t use more than 1 GX attack in a game.)\"}]', 'SM Black Star Promos', '2', '', '', '', 'Seventh', '170', 'https://images.pokemoncard.io/images/smp/smp-SM33.png', 'unlimited: Legal, expanded: Legal', '', 'Tapu Koko-GX', '785', 'TPCI', 'Promo', '', '02/03/2017', '', 'Colorless, Colorless', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', 'SM33', 'Basic, GX', 'Pokémon', 'Lightning', ''),
('smp-SM34', '', '', '5ban Graphics', '[{\'name\': \'Bear Hug\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'80\', \'text\': \"The Defending Pokémon can\'t retreat during your opponent\'s next turn.\"}, {\'name\': \'Double Impact\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'100×\', \'text\': \'Flip 2 coins. This attack does 100 damage for each heads.\'}, {\'name\': \'Big Throw-GX\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'\', \'text\': \"Discard your opponent\'s Active Pokémon and all cards attached to it. (You can\'t use more than 1 GX attack in a game.)\"}]', 'SM Black Star Promos', '3', 'Stufful', '', '', 'Seventh', '210', 'https://images.pokemoncard.io/images/smp/smp-SM34.png', 'unlimited: Legal, expanded: Legal', '', 'Bewear-GX', '760', 'TPCI', 'Promo', '', '02/03/2017', '', 'Colorless, Colorless, Colorless', '[\'Pokémon-GX rule: When your Pokémon-GX is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sun & Moon', 'SM34', 'Stage 1, GX', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
