('sv1-186', '', '', 'Toyste Beach', '', 'Scarlet & Violet', '', '', '', '', 'Ninth', '', 'https://images.pokemoncard.io/images/sv1/sv1-186.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Pokégear 3.0', '', 'TPCI', 'Common', 'G', '3/31/2023', '', '', '[\'Look at the top 7 cards of your deck. You may reveal a Supporter card you find there and put it into your hand. Shuffle the other cards back into your deck.\', \'You may play any number of Item cards during your turn.\']', 'Scarlet & Violet', '186', 'Item', 'Trainer', '', ''),
('sv1-187', '', '', 'Studio Bora Inc.', '', 'Scarlet & Violet', '', '', '', '', 'Ninth', '', 'https://images.pokemoncard.io/images/sv1/sv1-187.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Pokémon Catcher', '', 'TPCI', 'Common', 'G', '3/31/2023', '', '', '[\"Flip a coin. If heads, switch in 1 of your opponent\'s Benched Pokémon to the Active Spot.\", \'You may play any number of Item cards during your turn.\']', 'Scarlet & Violet', '187', 'Item', 'Trainer', '', ''),
