('sv1-242', '', '', 'nagimiso', '', 'Scarlet & Violet', '', '', '', '', 'Ninth', '', 'https://images.pokemoncard.io/images/sv1/sv1-242.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Team Star Grunt', '', 'TPCI', 'Ultra Rare', 'G', '3/31/2023', '', '', '[\"Put an Energy attached to your opponent\'s Active Pokémon on top of their deck.\", \'You may play only 1 Supporter card during your turn.\']', 'Scarlet & Violet', '242', 'Supporter', 'Trainer', '', ''),
('sv1-243', '[{\'type\': \'Ability\', \'name\': \'Trap Territory\', \'text\': \"Your opponent\'s Active Pokémon\'s Retreat Cost is Colorless more.\"}]', '', 'Miki Tanaka', '[{\'cost\': [\'Grass\', \'Colorless\'], \'name\': \'Wire Hang\', \'damage\': \'90+\', \'text\': \"This attack does 30 more damage for each Colorless in your opponent\'s Active Pokémon\'s Retreat Cost.\", \'convertedEnergyCost\': 2}]', 'Scarlet & Violet', '2', 'Tarountula', '', '', 'Ninth', '260', 'https://images.pokemoncard.io/images/sv1/sv1-243.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Spidops ex', '918', 'TPCI', 'Special Illustration Rare', 'G', '3/31/2023', '', 'Colorless, Colorless', '[\'Pokémon ex rule: When your Pokémon ex is Knocked Out, your opponent takes 2 Prize cards.\']', 'Scarlet & Violet', '243', 'Stage 1, ex', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('sv1-244', '[{\'type\': \'Ability\', \'name\': \'Tandem Unit\', \'text\': \'Once during your turn, you may search your deck for up to 2 Basic Lightning Pokémon and put them onto your Bench. Then, shuffle your deck.\'}]', '', 'kantaro', '[{\'cost\': [\'Lightning\', \'Lightning\', \'Colorless\'], \'name\': \'Photon Blaster\', \'damage\': \'220\', \'text\': \"During your next turn, this Pokémon can\'t attack.\", \'convertedEnergyCost\': 3}]', 'Scarlet & Violet', '1', '', '', '', 'Ninth', '220', 'https://images.pokemoncard.io/images/sv1/sv1-244.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Miraidon ex', '1008', 'TPCI', 'Special Illustration Rare', 'G', '3/31/2023', '', 'Colorless', '[\'Pokémon ex rule: When your Pokémon ex is Knocked Out, your opponent takes 2 Prize cards.\']', 'Scarlet & Violet', '244', 'Basic, ex', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2');
