('sv2-202', '', '', 'kantaro', '[{\'cost\': [\'Fire\'], \'name\': \'Steady Firebreathing\', \'damage\': \'30\', \'text\': \'\', \'convertedEnergyCost\': 1}, {\'cost\': [\'Fire\', \'Fire\'], \'name\': \'Hyper Voice\', \'damage\': \'70\', \'text\': \'\', \'convertedEnergyCost\': 2}]', 'Paldea Evolved', '3', 'Fuecoco', '', 'The combination of Crocalor’s fire energy and overflowing vitality has caused an egg-shaped fireball to appear on the Pokémon’s head.', 'Ninth', '110', 'https://images.pokemoncard.io/images/sv2/sv2-202.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Crocalor', '910', 'TPCI', 'Illustration Rare', 'G', '06/09/2023', '', 'Colorless, Colorless, Colorless', '', 'Scarlet & Violet', '202', 'Stage 1', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('sv2-203', '', '', 'Shinji Kanda', '[{\'cost\': [\'Water\'], \'name\': \'Expert Splasher\', \'damage\': \'10+\', \'text\': \'Flip 2 coins. If both of them are heads, this attack does 20 more damage.\', \'convertedEnergyCost\': 1}]', 'Paldea Evolved', '1', '', '', 'An underpowered, pathetic Pokémon. It may jump high on rare occasions but never more than seven feet.', 'Ninth', '30', 'https://images.pokemoncard.io/images/sv2/sv2-203.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Magikarp', '129', 'TPCI', 'Illustration Rare', 'G', '06/09/2023', '', 'Colorless', '', 'Scarlet & Violet', '203', 'Basic', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
