('sv2-240', '', '', 'takuyoa', '[{\'cost\': [\'Colorless\', \'Colorless\'], \'name\': \'Big Hammer\', \'damage\': \'30×\', \'text\': \'This attack does 30 damage for each card in your hand.\', \'convertedEnergyCost\': 2}, {\'cost\': [\'Psychic\', \'Colorless\', \'Colorless\'], \'name\': \'Pulverizing Press\', \'damage\': \'140\', \'text\': \"This attack\'s damage isn\'t affected by any effects on your opponent\'s Active Pokémon.\", \'convertedEnergyCost\': 3}]', 'Paldea Evolved', '2', 'Tinkatuff', '', '', 'Ninth', '300', 'https://images.pokemoncard.io/images/sv2/sv2-240.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Tinkaton ex', '959', 'TPCI', 'Ultra Rare', 'G', '06/09/2023', '', 'Colorless, Colorless', '[\'Pokémon ex rule: When your Pokémon ex is Knocked Out, your opponent takes 2 Prize cards.\']', 'Scarlet & Violet', '240', 'Stage 2, ex', 'Pokémon', 'Psychic', 'type: Metal, value: ×2'),
('sv2-241', '', '', 'Ayaka Yoshida', '[{\'cost\': [\'Fighting\'], \'name\': \'Rock Throw\', \'damage\': \'40\', \'text\': \'\', \'convertedEnergyCost\': 1}, {\'cost\': [\'Fighting\', \'Colorless\', \'Colorless\'], \'name\': \'Scary Fangs\', \'damage\': \'140\', \'text\': \"During your opponent\'s next turn, if this Pokémon is damaged by an attack (even if it is Knocked Out), put 10 damage counters on the Attacking Pokémon.\", \'convertedEnergyCost\': 3}]', 'Paldea Evolved', '2', 'Rockruff', '', '', 'Ninth', '260', 'https://images.pokemoncard.io/images/sv2/sv2-241.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Lycanroc ex', '745', 'TPCI', 'Ultra Rare', 'G', '06/09/2023', '', 'Colorless, Colorless', '[\'Pokémon ex rule: When your Pokémon ex is Knocked Out, your opponent takes 2 Prize cards.\']', 'Scarlet & Violet', '241', 'Stage 1, ex', 'Pokémon', 'Fighting', 'type: Grass, value: ×2'),
('sv2-242', '', '', 'PLANETA Hiiragi', '[{\'cost\': [\'Fighting\'], \'name\': \'Angry Grudge\', \'damage\': \'20×\', \'text\': \'Put up to 12 damage counters on this Pokémon. This attack does 20 damage for each damage counter you placed in this way.\', \'convertedEnergyCost\': 1}, {\'cost\': [\'Fighting\', \'Colorless\'], \'name\': \'Seismic Toss\', \'damage\': \'150\', \'text\': \'\', \'convertedEnergyCost\': 2}]', 'Paldea Evolved', '2', 'Primeape', '', '', 'Ninth', '320', 'https://images.pokemoncard.io/images/sv2/sv2-242.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Annihilape ex', '979', 'TPCI', 'Ultra Rare', 'G', '06/09/2023', '', 'Colorless, Colorless', '[\'Pokémon ex rule: When your Pokémon ex is Knocked Out, your opponent takes 2 Prize cards.\']', 'Scarlet & Violet', '242', 'Stage 2, ex', 'Pokémon', 'Fighting', 'type: Psychic, value: ×2'),
