('sv2-266', '', '', 'GIDORA', '', 'Paldea Evolved', '', '', '', '', 'Ninth', '', 'https://images.pokemoncard.io/images/sv2/sv2-266.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Dendra', '', 'TPCI', 'Special Illustration Rare', 'G', '06/09/2023', '', '', '[\"Put a card from your hand on the bottom of your deck. If you do, draw cards until you have 5 cards in your hand.\\xa0(If you have no other cards in your hand, you can\'t use this card.)\", \'You may play only 1 Supporter card during your turn.\']', 'Scarlet & Violet', '266', 'Supporter', 'Trainer', '', ''),
('sv2-267', '', '', 'KIYOTAKA OSHIYAMA', '', 'Paldea Evolved', '', '', '', '', 'Ninth', '', 'https://images.pokemoncard.io/images/sv2/sv2-267.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Giacomo', '', 'TPCI', 'Special Illustration Rare', 'G', '06/09/2023', '', '', '[\"Discard a Special Energy from each of your opponent\'s Pokémon.\", \'You may play only 1 Supporter card during your turn.\']', 'Scarlet & Violet', '267', 'Supporter', 'Trainer', '', ''),
('sv2-268', '', '', 'DOM', '', 'Paldea Evolved', '', '', '', '', 'Ninth', '', 'https://images.pokemoncard.io/images/sv2/sv2-268.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Grusha', '', 'TPCI', 'Special Illustration Rare', 'G', '06/09/2023', '', '', '[\'Draw cards until you have 5 cards in your hand. If none of your Pokémon have any Energy attached, draw cards until you have 7 cards in your hand instead.\', \'You may play only 1 Supporter card during your turn.\']', 'Scarlet & Violet', '268', 'Supporter', 'Trainer', '', ''),
('sv2-269', '', '', 'kirisAki', '', 'Paldea Evolved', '', '', '', '', 'Ninth', '', 'https://images.pokemoncard.io/images/sv2/sv2-269.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Iono', '', 'TPCI', 'Special Illustration Rare', 'G', '06/09/2023', '', '', '[\'Each player shuffles their hand and puts it on the bottom of their deck. If either player put any cards on the bottom of their deck in this way, each player draws a card for each of their remaining Prize cards.\', \'You may play only 1 Supporter card during your turn.\']', 'Scarlet & Violet', '269', 'Supporter', 'Trainer', '', ''),
