('sv4-235', '', '', 'Akira Komayama', '', 'Paradox Rift', '', '', '', '', 'Ninth', '', 'https://images.pokemoncard.io/images/sv4/sv4-235.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Larry', '', 'TPCI', 'Ultra Rare', 'G', '11/03/2023', '', '', '[\'Flip a coin. If heads, search your deck for up to 2 Pokémon, reveal them, and put them into your hand. If tails, search your deck for a Basic Pokémon, reveal it, and put it into your hand. Then, shuffle your deck.\', \'You may play only 1 Supporter card during your turn.\']', 'Scarlet & Violet', '235', 'Supporter', 'Trainer', '', ''),
('sv4-236', '', '', 'kirisAki', '', 'Paradox Rift', '', '', '', '', 'Ninth', '', 'https://images.pokemoncard.io/images/sv4/sv4-236.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Mela', '', 'TPCI', 'Ultra Rare', 'G', '11/03/2023', '', '', '[\"You can use this card only if any of your Pokémon were Knocked Out during your opponent\'s last turn.    Attach a Basic Fire Energy card from your discard pile to 1 of your Pokémon. If you do, draw cards until you have 6 cards in your hand.\", \'You may play only 1 Supporter card during your turn.\']', 'Scarlet & Violet', '236', 'Supporter', 'Trainer', '', ''),
('sv4-237', '', '', 'Hideki Ishikawa', '', 'Paradox Rift', '', '', '', '', 'Ninth', '', 'https://images.pokemoncard.io/images/sv4/sv4-237.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Norman', '', 'TPCI', 'Ultra Rare', 'G', '11/03/2023', '', '', '[\"Draw 2 cards. If your opponent\'s Active Pokémon is a Pokémon ex, draw 2 more cards.\", \'You may play only 1 Supporter card during your turn.\']', 'Scarlet & Violet', '237', 'Supporter', 'Trainer', '', ''),
('sv4-238', '', '', 'Cona Nitanda', '', 'Paradox Rift', '', '', '', '', 'Ninth', '', 'https://images.pokemoncard.io/images/sv4/sv4-238.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Parasol Lady', '', 'TPCI', 'Ultra Rare', 'G', '11/03/2023', '', '', '[\"Shuffle your hand into your deck. Then, draw 4 cards. If you go second and it\'s your first turn, draw 8 cards instead.\", \'You may play only 1 Supporter card during your turn.\']', 'Scarlet & Violet', '238', 'Supporter', 'Trainer', '', ''),
('sv4-239', '', '', 'Megumi Mizutani', '', 'Paradox Rift', '', '', '', '', 'Ninth', '', 'https://images.pokemoncard.io/images/sv4/sv4-239.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Professor Sadas Vitality', '', 'TPCI', 'Ultra Rare', 'G', '11/03/2023', '', '', '[\'Choose up to 2 of your Ancient Pokémon and attach a Basic Energy card from your discard pile to each of them. If you attached any Energy in this way, draw 3 cards.\', \'You may play only 1 Supporter card during your turn.\']', 'Scarlet & Violet', '239', 'Supporter, Ancient', 'Trainer', '', ''),
('sv4-24', '', '', 'Pani Kobayashi', '[{\'name\': \'Rolling Fireball\', \'cost\': [\'Fire\', \'Fire\'], \'convertedEnergyCost\': 2, \'damage\': \'90\', \'text\': \'Put an Energy attached to this Pokémon into your hand.\'}]', 'Paradox Rift', '3', 'Fuecoco', '', 'The combination of Crocalors fire energy and overflowing vitality has caused an egg-shaped fireball to appear on the Pokémons head.', 'Ninth', '100', 'https://images.pokemoncard.io/images/sv4/sv4-24.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Crocalor', '', 'TPCI', 'Uncommon', 'G', '11/03/2023', '', 'Colorless, Colorless, Colorless', '', 'Scarlet & Violet', '24', 'Stage 1', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
