('swsh1-164', '', '', 'Toyste Beach', '', 'Sword & Shield', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh1/swsh1-164.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Great Ball', '', 'TPCI', 'Uncommon', 'D', '02/07/2020', '', '', '[\'Look at the top 7 cards of your deck. You may reveal a Pokémon you find there and put it into your hand. Shuffle the other cards back into your deck.\', \'You may play any number of Item cards during your turn.\']', 'Sword & Shield', '164', 'Item', 'Trainer', '', ''),
('swsh1-165', '', '', 'Ken Sugimori', '', 'Sword & Shield', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh1/swsh1-165.png', 'unlimited: Legal, expanded: Legal', '', 'Hop', '', 'TPCI', 'Uncommon', 'D', '02/07/2020', '', '', '[\'Draw 3 cards.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '165', 'Supporter', 'Trainer', '', ''),
