('swsh1-167', '', '', 'Studio Bora Inc.', '', 'Sword & Shield', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh1/swsh1-167.png', 'unlimited: Legal, expanded: Legal', '', 'Lucky Egg', '', 'TPCI', 'Uncommon', 'D', '02/07/2020', '', '', '[\"Attach a Pokémon Tool to 1 of your Pokémon that doesn\'t already have a Pokémon Tool attached.\", \"If the Pokémon this card is attached to is Knocked Out by damage from an opponent\'s attack, draw cards until you have 7 cards in your hand.\", \'You may play any number of Item cards during your turn.\']', 'Sword & Shield', '167', 'Pokémon Tool', 'Trainer', '', ''),
('swsh1-168', '', '', 'Yoshinobu Saito', '', 'Sword & Shield', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh1/swsh1-168.png', 'unlimited: Legal, expanded: Legal', '', 'Lum Berry', '', 'TPCI', 'Uncommon', 'D', '02/07/2020', '', '', '[\"Attach a Pokémon Tool to 1 of your Pokémon that doesn\'t already have a Pokémon Tool attached.\", \'At the end of each turn, if the Pokémon this card is attached to is affected by any Special Conditions, it recovers from all of them, and discard this card.\', \'You may play any number of Item cards during your turn.\']', 'Sword & Shield', '168', 'Pokémon Tool', 'Trainer', '', ''),
('swsh1-169', '', '', 'kirisAki', '', 'Sword & Shield', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh1/swsh1-169.png', 'unlimited: Legal, expanded: Legal', '', 'Marnie', '', 'TPCI', 'Rare Holo', 'D', '02/07/2020', '', '', '[\'Each player shuffles their hand and puts it on the bottom of their deck. If either player put any cards on the bottom of their deck in this way, you draw 5 cards, and your opponent draws 4 cards.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '169', 'Supporter', 'Trainer', '', ''),
('swsh1-17', '', '', 'Mina Nakai', '[{\'name\': \'Call for Family\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Search your deck for a Basic Pokémon and put it onto your Bench. Then, shuffle your deck.\'}]', 'Sword & Shield', '1', '', 'Dottler', 'A constant collector of information, this Pokémon is very smart. Very strong is what it isnt.', 'Eighth', '40', 'https://images.pokemoncard.io/images/swsh1/swsh1-17.png', 'unlimited: Legal, expanded: Legal', '', 'Blipbug', '824', 'TPCI', 'Common', 'D', '02/07/2020', '', 'Colorless', '', 'Sword & Shield', '17', 'Basic', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
