('swsh1-181', '', '', '5ban Graphics', '', 'Sword & Shield', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh1/swsh1-181.png', 'unlimited: Legal, expanded: Legal', '', 'Rotom Bike', '', 'TPCI', 'Uncommon', 'D', '02/07/2020', '', '', '[\'Draw cards until you have 6 cards in your hand. Your turn ends.\', \'You may play any number of Item cards during your turn.\']', 'Sword & Shield', '181', 'Item', 'Trainer', '', ''),
('swsh1-182', '', '', 'Yoshinobu Saito', '', 'Sword & Shield', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh1/swsh1-182.png', 'unlimited: Legal, expanded: Legal', '', 'Sitrus Berry', '', 'TPCI', 'Uncommon', 'D', '02/07/2020', '', '', '[\"Attach a Pokémon Tool to 1 of your Pokémon that doesn\'t already have a Pokémon Tool attached.\", \'At the end of each turn, if the Pokémon this card is attached to has 3 or more damage counters on it, heal 30 damage from it and discard this card.\', \'You may play any number of Item cards during your turn.\']', 'Sword & Shield', '182', 'Pokémon Tool', 'Trainer', '', ''),
('swsh1-183', '', '', 'Studio Bora Inc.', '', 'Sword & Shield', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh1/swsh1-183.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Switch', '', 'TPCI', 'Uncommon', 'D', '02/07/2020', '', '', '[\'Switch your Active Pokémon with 1 of your Benched Pokémon.\', \'You may play any number of Item cards during your turn.\']', 'Sword & Shield', '183', 'Item', 'Trainer', '', ''),
