('swsh1-186', '', '', '', '', 'Sword & Shield', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh1/swsh1-186.png', 'unlimited: Legal, expanded: Legal', '', 'Aurora Energy', '', 'TPCI', 'Uncommon', 'D', '02/07/2020', '', '', '[\'You can attach this card to 1 of your Pokémon only if you discard another card from your hand.\', \'As long as this card is attached to a Pokémon, it provides every type of Energy but provides only 1 Energy at a time.\']', 'Sword & Shield', '186', 'Special', 'Energy', '', ''),
('swsh1-187', '', '', 'Eske Yoshinob', '[{\'name\': \'Anchor Anger\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'30+\', \'text\': \"If any of your Grass Pokémon were Knocked Out by damage from an opponent\'s attack during their last turn, this attack does 90 more damage.\"}, {\'name\': \'Giga Hammer\', \'cost\': [\'Grass\', \'Grass\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'200\', \'text\': \"During your next turn, this Pokémon can\'t use Giga Hammer.\"}]', 'Sword & Shield', '2', '', '', '', 'Eighth', '220', 'https://images.pokemoncard.io/images/swsh1/swsh1-187.png', 'unlimited: Legal, expanded: Legal', '', 'Dhelmise V', '781', 'TPCI', 'Rare Ultra', 'D', '02/07/2020', '', 'Colorless, Colorless', '[\'V rule: When your Pokémon V is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sword & Shield', '187', 'Basic, V', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
