('swsh10-178', '', '', 'N-DESIGN Inc.', '[{\'name\': \'Dragon Claw\', \'cost\': [\'Water\', \'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'120\', \'text\': \'\'}, {\'name\': \'Sonic Strike\', \'cost\': [\'Water\', \'Fighting\', \'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'\', \'text\': \"Discard 3 Energy from this Pokémon. This attack does 220 damage to 1 of your opponent\'s Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'Astral Radiance', '', '', '', '', 'Eighth', '200', 'https://images.pokemoncard.io/images/swsh10/swsh10-178.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Garchomp V', '445', 'TPCI', 'Rare Ultra', 'F', '5/27/2022', '', '', '[\'V rule: When your Pokémon V is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sword & Shield', '178', 'Basic, V', 'Pokémon', 'Dragon', ''),
('swsh10-179', '[{\'name\': \'Back Order\', \'text\': \'Once during your turn, if this Pokémon is in the Active Spot, you may search your deck for up to 2 Pokémon Tool cards, reveal them, and put them into your hand. Then, shuffle your deck.\', \'type\': \'Ability\'}]', '', 'Toyste Beach', '[{\'name\': \'Psychic\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'30+\', \'text\': \"This attack does 50 more damage for each Energy attached to your opponent\'s Active Pokémon.\"}]', 'Astral Radiance', '2', '', '', '', 'Eighth', '210', 'https://images.pokemoncard.io/images/swsh10/swsh10-179.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Oranguru V', '765', 'TPCI', 'Rare Ultra', 'F', '5/27/2022', '', 'Colorless, Colorless', '[\'V rule: When your Pokémon V is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sword & Shield', '179', 'Basic, V', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('swsh10-18', '[{\'name\': \'Star Perfume\', \'text\': \"During your turn, you may search your deck for up to 5 in any combination of Grass Pokémon and Grass Energy cards, reveal them, and put them into your hand. Then, shuffle your deck. (You can\'t use more than 1 VSTAR Power in a game.)\", \'type\': \'Ability\'}]', '', '5ban Graphics', '[{\'name\': \'Parallel Spin\', \'cost\': [\'Grass\', \'Grass\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'130+\', \'text\': \'You may put an Energy attached to this Pokémon into your hand. If you do, this attack does 100 more damage.\'}]', 'Astral Radiance', '1', 'Hisuian Lilligant V', '', '', 'Eighth', '260', 'https://images.pokemoncard.io/images/swsh10/swsh10-18.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Hisuian Lilligant VSTAR', '549', 'TPCI', 'Rare Holo VSTAR', 'F', '5/27/2022', '', 'Colorless', '[\'VSTAR rule: When your Pokémon VSTAR is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sword & Shield', '18', 'VSTAR', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('swsh10-180', '[{\'name\': \'Frontier Road\', \'text\': \'Once during your turn, when this Pokémon moves from your Bench to the Active Spot, you may move any amount of Energy from your other Pokémon to it.\', \'type\': \'Ability\'}]', '', 'aky CG Works', '[{\'name\': \'Psyshield Bash\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40×\', \'text\': \'This attack does 40 damage for each Energy attached to this Pokémon.\'}]', 'Astral Radiance', '2', '', '', '', 'Eighth', '220', 'https://images.pokemoncard.io/images/swsh10/swsh10-180.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Wyrdeer V', '899', 'TPCI', 'Rare Ultra', 'F', '5/27/2022', '', 'Colorless, Colorless', '[\'V rule: When your Pokémon V is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sword & Shield', '180', 'Basic, V', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('swsh10-181', '', '', 'Souichirou Gunjima', '', 'Astral Radiance', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh10/swsh10-181.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Adaman', '', 'TPCI', 'Rare Ultra', 'F', '5/27/2022', '', '', '[\'You can use this card only if you discard 2 Metal Energy cards from your hand. Search your deck for up to 2 cards and put them into your hand. Then, shuffle your deck.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '181', 'Supporter', 'Trainer', '', ''),
('swsh10-182', '', '', 'Hitoshi Ariga', '', 'Astral Radiance', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh10/swsh10-182.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Choy', '', 'TPCI', 'Rare Ultra', 'F', '5/27/2022', '', '', '[\'Each player reveals their hand. Draw 3 cards.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '182', 'Supporter', 'Trainer', '', ''),
('swsh10-183', '', '', 'nagimiso', '', 'Astral Radiance', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh10/swsh10-183.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Cyllene', '', 'TPCI', 'Rare Ultra', 'F', '5/27/2022', '', '', '[\'Flip 2 coins. Put a number of cards up to the number of heads from your discard pile on top of your deck in any order.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '183', 'Supporter', 'Trainer', '', ''),
('swsh10-184', '', '', 'En Morikura', '', 'Astral Radiance', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh10/swsh10-184.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Gardenias Vigor', '', 'TPCI', 'Rare Ultra', 'F', '5/27/2022', '', '', '[\'Draw 2 cards. If you drew any cards in this way, attach up to 2 Grass Energy cards from your hand to 1 of your Benched Pokémon.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '184', 'Supporter', 'Trainer', '', ''),
('swsh10-185', '', '', 'Hideki Ishikawa', '', 'Astral Radiance', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh10/swsh10-185.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Grant', '', 'TPCI', 'Rare Ultra', 'F', '5/27/2022', '', '', '[\"During this turn, your Fighting Pokémon\'s attacks do 30 more damage to your opponent\'s Active Pokémon (before applying Weakness and Resistance). During your turn, if this Grant is in your discard pile, you may discard 2 cards, except any Grant, from your hand. If you do, put this Grant into your hand. (This effect doesn\'t use up your Supporter card for the turn.)\", \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '185', 'Supporter', 'Trainer', '', ''),
('swsh10-186', '', '', 'kirisAki', '', 'Astral Radiance', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh10/swsh10-186.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Irida', '', 'TPCI', 'Rare Ultra', 'F', '5/27/2022', '', '', '[\'Search your deck for a Water Pokémon and an Item card, reveal them, and put them into your hand. Then, shuffle your deck.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '186', 'Supporter', 'Trainer', '', ''),
('swsh10-187', '', '', 'Hitoshi Ariga', '', 'Astral Radiance', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh10/swsh10-187.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Kamado', '', 'TPCI', 'Rare Ultra', 'F', '5/27/2022', '', '', '[\"Choose a card in your hand, and discard the other cards. If you do, draw 4 cards. (If you have no other cards in your hand, you can\'t use this card.)\", \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '187', 'Supporter', 'Trainer', '', ''),
('swsh10-188', '', '', 'Sanosuke Sakuma', '', 'Astral Radiance', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh10/swsh10-188.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Roxanne', '', 'TPCI', 'Rare Ultra', 'F', '5/27/2022', '', '', '[\'You can use this card only if your opponent has 3 or fewer Prize cards remaining. Each player shuffles their hand into their deck. Then, you draw 6 cards, and your opponent draws 2 cards.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '188', 'Supporter', 'Trainer', '', ''),
('swsh10-189', '', '', 'kirisAki', '', 'Astral Radiance', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh10/swsh10-189.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Zisu', '', 'TPCI', 'Rare Ultra', 'F', '5/27/2022', '', '', '[\'Draw cards until you have 1 more card in your hand than your opponent.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '189', 'Supporter', 'Trainer', '', ''),
