('swsh10-199', '', '', 'Souichirou Gunjima', '', 'Astral Radiance', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh10/swsh10-199.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Adaman', '', 'TPCI', 'Rare Rainbow', 'F', '5/27/2022', '', '', '[\'You can use this card only if you discard 2 Metal Energy cards from your hand. Search your deck for up to 2 cards and put them into your hand. Then, shuffle your deck.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '199', 'Supporter', 'Trainer', '', ''),
('swsh10-2', '', '', 'nagimiso', '[{\'name\': \'Cheerful Charge\', \'cost\': [], \'convertedEnergyCost\': 0, \'damage\': \'\', \'text\': \'You can use this attack only if you go second, and only during your first turn. Choose up to 2 of your Benched Pokémon. For each of those Pokémon, search your deck for a basic Energy card and attach it to that Pokémon. Then, shuffle your deck.\'}, {\'name\': \'Ram\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'\'}]', 'Astral Radiance', '1', '', 'Electrode', 'An enigmatic Pokémon that happens to bear a resemblance to a Poké Ball. When excited, it discharges the electric current it has stored in its belly, then lets out a great, uproarious laugh.', 'Eighth', '50', 'https://images.pokemoncard.io/images/swsh10/swsh10-2.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Hisuian Voltorb', '100', 'TPCI', 'Common', 'F', '5/27/2022', '', 'Colorless', '', 'Sword & Shield', '2', 'Basic', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('swsh10-20', '', '', '313', '[{\'name\': \'Flap\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'30\', \'text\': \'\'}, {\'name\': \'Razor Wing\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60\', \'text\': \'\'}]', 'Astral Radiance', '1', 'Rowlet', 'Decidueye', 'Regularly basks in sunlight to gather power—presumably due to the frigid climate. Nonetheless, the edges of the blade quills set into its wings are keen as ever.', 'Eighth', '90', 'https://images.pokemoncard.io/images/swsh10/swsh10-20.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Dartrix', '723', 'TPCI', 'Uncommon', 'F', '5/27/2022', '', 'Colorless', '', 'Sword & Shield', '20', 'Stage 1', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('swsh10-200', '', '', 'Hitoshi Ariga', '', 'Astral Radiance', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh10/swsh10-200.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Choy', '', 'TPCI', 'Rare Rainbow', 'F', '5/27/2022', '', '', '[\'Each player reveals their hand. Draw 3 cards.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '200', 'Supporter', 'Trainer', '', ''),
('swsh10-201', '', '', 'nagimiso', '', 'Astral Radiance', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh10/swsh10-201.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Cyllene', '', 'TPCI', 'Rare Rainbow', 'F', '5/27/2022', '', '', '[\'Flip 2 coins. Put a number of cards up to the number of heads from your discard pile on top of your deck in any order.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '201', 'Supporter', 'Trainer', '', ''),
('swsh10-202', '', '', 'En Morikura', '', 'Astral Radiance', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh10/swsh10-202.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Gardenias Vigor', '', 'TPCI', 'Rare Rainbow', 'F', '5/27/2022', '', '', '[\'Draw 2 cards. If you drew any cards in this way, attach up to 2 Grass Energy cards from your hand to 1 of your Benched Pokémon.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '202', 'Supporter', 'Trainer', '', ''),
('swsh10-203', '', '', 'Hideki Ishikawa', '', 'Astral Radiance', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh10/swsh10-203.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Grant', '', 'TPCI', 'Rare Rainbow', 'F', '5/27/2022', '', '', '[\"During this turn, your Fighting Pokémon\'s attacks do 30 more damage to your opponent\'s Active Pokémon (before applying Weakness and Resistance). During your turn, if this Grant is in your discard pile, you may discard 2 cards, except any Grant, from your hand. If you do, put this Grant into your hand. (This effect doesn\'t use up your Supporter card for the turn.)\", \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '203', 'Supporter', 'Trainer', '', ''),
('swsh10-204', '', '', 'kirisAki', '', 'Astral Radiance', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh10/swsh10-204.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Irida', '', 'TPCI', 'Rare Rainbow', 'F', '5/27/2022', '', '', '[\'Search your deck for a Water Pokémon and an Item card, reveal them, and put them into your hand. Then, shuffle your deck.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '204', 'Supporter', 'Trainer', '', ''),
('swsh10-205', '', '', 'Hitoshi Ariga', '', 'Astral Radiance', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh10/swsh10-205.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Kamado', '', 'TPCI', 'Rare Rainbow', 'F', '5/27/2022', '', '', '[\"Choose a card in your hand, and discard the other cards. If you do, draw 4 cards. (If you have no other cards in your hand, you can\'t use this card.)\", \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '205', 'Supporter', 'Trainer', '', ''),
('swsh10-206', '', '', 'Sanosuke Sakuma', '', 'Astral Radiance', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh10/swsh10-206.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Roxanne', '', 'TPCI', 'Rare Rainbow', 'F', '5/27/2022', '', '', '[\'You can use this card only if your opponent has 3 or fewer Prize cards remaining. Each player shuffles their hand into their deck. Then, you draw 6 cards, and your opponent draws 2 cards.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '206', 'Supporter', 'Trainer', '', ''),
('swsh10-207', '', '', 'kirisAki', '', 'Astral Radiance', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh10/swsh10-207.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Zisu', '', 'TPCI', 'Rare Rainbow', 'F', '5/27/2022', '', '', '[\'Draw cards until you have 1 more card in your hand than your opponent.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '207', 'Supporter', 'Trainer', '', ''),
