('swsh10tg-TG18', '[{\'name\': \'Underworld Door\', \'text\': \'Once during your turn, you may attach a Psychic Energy card from your hand to 1 of your Benched Psychic Pokémon. If you attached Energy to a Pokémon in this way, draw 2 cards.\', \'type\': \'Ability\'}]', '', 'chibi', '[{\'name\': \'Max Geist\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'10+\', \'text\': \'This attack does 30 more damage for each Psychic Energy attached to all of your Pokémon.\'}]', 'Astral Radiance Trainer Gallery', '2', 'Shadow Rider Calyrex V', '', '', 'Eighth', '320', 'https://images.pokemoncard.io/images/swsh10tg/swsh10tg-TG18.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Shadow Rider Calyrex VMAX', '898', 'TPCI', 'Rare Holo VMAX', 'E', '5/27/2022', 'type: Fighting, value: -30', 'Colorless, Colorless', '[\'VMAX rule: When your Pokémon VMAX is Knocked Out, your opponent takes 3 Prize cards.\']', 'Sword & Shield', 'TG18', 'VMAX', 'Pokémon', 'Psychic', 'type: Darkness, value: ×2'),
('swsh10tg-TG19', '[{\'name\': \'Fighting Instinct\', \'text\': \"This Pokémon\'s attacks cost Colorless less for each of your opponent\'s Pokémon V in play.\", \'type\': \'Ability\'}]', '', 'kirisAki', '[{\'name\': \'Thunderous Kick\', \'cost\': [\'Fighting\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'170\', \'text\': \"Before doing damage, discard a Special Energy from your opponent\'s Active Pokémon.\"}]', 'Astral Radiance Trainer Gallery', '1', '', '', '', 'Eighth', '200', 'https://images.pokemoncard.io/images/swsh10tg/swsh10tg-TG19.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Galarian Zapdos V', '145', 'TPCI', 'Rare Holo V', 'E', '5/27/2022', '', 'Colorless', '[\'V rule: When your Pokémon V is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sword & Shield', 'TG19', 'Basic, V', 'Pokémon', 'Fighting', 'type: Psychic, value: ×2'),
('swsh10tg-TG20', '[{\'name\': \'Direflame Wings\', \'text\': \"Once during your turn, you may attach a Darkness Energy card from your discard pile to this Pokémon. You can\'t use more than 1 Direflame Wings Ability each turn.\", \'type\': \'Ability\'}]', '', 'Jiro Sasumo', '[{\'name\': \'Aura Burn\', \'cost\': [\'Darkness\', \'Darkness\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'190\', \'text\': \'This Pokémon also does 30 damage to itself.\'}]', 'Astral Radiance Trainer Gallery', '2', '', '', '', 'Eighth', '220', 'https://images.pokemoncard.io/images/swsh10tg/swsh10tg-TG20.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Galarian Moltres V', '146', 'TPCI', 'Rare Holo V', 'E', '5/27/2022', '', 'Colorless, Colorless', '[\'V rule: When your Pokémon V is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sword & Shield', 'TG20', 'Basic, V', 'Pokémon', 'Darkness', 'type: Grass, value: ×2'),
('swsh10tg-TG21', '[{\'name\': \'Intrepid Sword\', \'text\': \'Once during your turn, you may look at the top 3 cards of your deck and attach any number of Metal Energy cards you find there to this Pokémon. Put the other cards into your hand. If you use this Ability, your turn ends.\', \'type\': \'Ability\'}]', '', 'aoki', '[{\'name\': \'Brave Blade\', \'cost\': [\'Metal\', \'Metal\', \'Metal\'], \'convertedEnergyCost\': 3, \'damage\': \'230\', \'text\': \"During your next turn, this Pokémon can\'t attack.\"}]', 'Astral Radiance Trainer Gallery', '2', '', '', '', 'Eighth', '220', 'https://images.pokemoncard.io/images/swsh10tg/swsh10tg-TG21.png', 'unlimited: Legal, expanded: Legal', '', 'Zacian V', '888', 'TPCI', 'Rare Holo V', 'D', '5/27/2022', 'type: Grass, value: -30', 'Colorless, Colorless', '[\'V rule: When your Pokémon V is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sword & Shield', 'TG21', 'Basic, V', 'Pokémon', 'Metal', 'type: Fire, value: ×2'),
('swsh10tg-TG22', '[{\'name\': \'Dauntless Shield\', \'text\': \"Prevent all damage done to this Pokémon by attacks from your opponent\'s Pokémon VMAX.\", \'type\': \'Ability\'}]', '', 'Ryuta Fuse', '[{\'name\': \'Assault Tackle\', \'cost\': [\'Metal\', \'Metal\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'130\', \'text\': \"Discard a Special Energy from your opponent\'s Active Pokémon.\"}]', 'Astral Radiance Trainer Gallery', '2', '', '', '', 'Eighth', '230', 'https://images.pokemoncard.io/images/swsh10tg/swsh10tg-TG22.png', 'unlimited: Legal, expanded: Legal', '', 'Zamazenta V', '889', 'TPCI', 'Rare Holo V', 'D', '5/27/2022', 'type: Grass, value: -30', 'Colorless, Colorless', '[\'V rule: When your Pokémon V is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sword & Shield', 'TG22', 'Basic, V', 'Pokémon', 'Metal', 'type: Fire, value: ×2'),
('swsh10tg-TG23', '', '', 'Taira Akitsu', '[{\'name\': \'Dragon Claw\', \'cost\': [\'Water\', \'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'120\', \'text\': \'\'}, {\'name\': \'Sonic Strike\', \'cost\': [\'Water\', \'Fighting\', \'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'\', \'text\': \"Discard 3 Energy from this Pokémon. This attack does 220 damage to 1 of your opponent\'s Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'Astral Radiance Trainer Gallery', '', '', '', '', 'Eighth', '200', 'https://images.pokemoncard.io/images/swsh10tg/swsh10tg-TG23.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Garchomp V', '445', 'TPCI', 'Rare Holo V', 'F', '5/27/2022', '', '', '[\'V rule: When your Pokémon V is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sword & Shield', 'TG23', 'Basic, V', 'Pokémon', 'Dragon', ''),
('swsh10tg-TG24', '', '', 'Jiro Sasumo', '', 'Astral Radiance Trainer Gallery', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh10tg/swsh10tg-TG24.png', 'unlimited: Legal, expanded: Legal', '', 'Allister', '', 'TPCI', 'Rare Ultra', 'D', '5/27/2022', '', '', '[\'Draw 3 cards. If you drew any cards in this way, discard up to 3 cards from your hand. (You must discard at least 1 card.)\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', 'TG24', 'Supporter', 'Trainer', '', ''),
('swsh10tg-TG25', '', '', 'Souichirou Gunjima', '', 'Astral Radiance Trainer Gallery', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh10tg/swsh10tg-TG25.png', 'unlimited: Legal, expanded: Legal', '', 'Bea', '', 'TPCI', 'Rare Ultra', 'D', '5/27/2022', '', '', '[\'Discard the top 5 cards of your deck, and attach any Energy cards you discarded in this way to your Benched Fighting Pokémon in any way you like.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', 'TG25', 'Supporter', 'Trainer', '', ''),
('swsh10tg-TG26', '', '', 'nagimiso', '', 'Astral Radiance Trainer Gallery', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh10tg/swsh10tg-TG26.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Melony', '', 'TPCI', 'Rare Ultra', 'E', '5/27/2022', '', '', '[\'Attach a Water Energy card from your discard pile to 1 of your Pokémon V. If you do, draw 3 cards.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', 'TG26', 'Supporter', 'Trainer', '', ''),
('swsh10tg-TG27', '', '', 'Sanosuke Sakuma', '', 'Astral Radiance Trainer Gallery', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh10tg/swsh10tg-TG27.png', 'unlimited: Legal, expanded: Legal', '', 'Milo', '', 'TPCI', 'Rare Ultra', 'D', '5/27/2022', '', '', '[\'Discard up to 2 cards from your hand, and draw 2 cards for each card you discarded in this way.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', 'TG27', 'Supporter', 'Trainer', '', ''),
('swsh10tg-TG28', '', '', 'GOSSAN', '', 'Astral Radiance Trainer Gallery', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh10tg/swsh10tg-TG28.png', 'unlimited: Legal, expanded: Legal', '', 'Piers', '', 'TPCI', 'Rare Ultra', 'D', '5/27/2022', '', '', '[\'Search your deck for an Energy card and a Darkness Pokémon, reveal them, and put them into your hand. Then, shuffle your deck.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', 'TG28', 'Supporter', 'Trainer', '', ''),
('swsh10tg-TG29', '', '', '5ban Graphics', '[{\'name\': \'Ride of the High King\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'10+\', \'text\': \"This attack does 30 more damage for each of your opponent\'s Benched Pokémon.\"}, {\'name\': \'Max Lance\', \'cost\': [\'Water\', \'Water\'], \'convertedEnergyCost\': 2, \'damage\': \'10+\', \'text\': \'You may discard up to 2 Energy from this Pokémon. If you do, this attack does 120 more damage for each card you discarded in this way.\'}]', 'Astral Radiance Trainer Gallery', '2', 'Ice Rider Calyrex V', '', '', 'Eighth', '320', 'https://images.pokemoncard.io/images/swsh10tg/swsh10tg-TG29.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Ice Rider Calyrex VMAX', '898', 'TPCI', 'Rare Secret', 'E', '5/27/2022', '', 'Colorless, Colorless', '[\'VMAX rule: When your Pokémon VMAX is Knocked Out, your opponent takes 3 Prize cards.\']', 'Sword & Shield', 'TG29', 'VMAX', 'Pokémon', 'Water', 'type: Metal, value: ×2'),
('swsh10tg-TG30', '[{\'name\': \'Underworld Door\', \'text\': \'Once during your turn, you may attach a Psychic Energy card from your hand to 1 of your Benched Psychic Pokémon. If you attached Energy to a Pokémon in this way, draw 2 cards.\', \'type\': \'Ability\'}]', '', '5ban Graphics', '[{\'name\': \'Max Geist\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'10+\', \'text\': \'This attack does 30 more damage for each Psychic Energy attached to all of your Pokémon.\'}]', 'Astral Radiance Trainer Gallery', '2', 'Shadow Rider Calyrex V', '', '', 'Eighth', '320', 'https://images.pokemoncard.io/images/swsh10tg/swsh10tg-TG30.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Shadow Rider Calyrex VMAX', '898', 'TPCI', 'Rare Secret', 'E', '5/27/2022', 'type: Fighting, value: -30', 'Colorless, Colorless', '[\'VMAX rule: When your Pokémon VMAX is Knocked Out, your opponent takes 3 Prize cards.\']', 'Sword & Shield', 'TG30', 'VMAX', 'Pokémon', 'Psychic', 'type: Darkness, value: ×2'),
('swsh11-1', '', '', 'Miki Tanaka', '[{\'name\': \'Ram\', \'cost\': [\'Grass\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'\'}]', 'Lost Origin', '1', '', 'Gloom', 'If exposed to moonlight, it starts to move. It roams far and wide at night to scatter its seeds.', 'Eighth', '50', 'https://images.pokemoncard.io/images/swsh11/swsh11-1.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Oddish', '43', 'TPCI', 'Common', 'F', '09/09/2022', '', 'Colorless', '', 'Sword & Shield', '1', 'Basic', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('swsh11-10', '', '', 'Mitsuhiro Arita', '[{\'name\': \'Nadir Powder\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'\', \'text\': \"Your opponent\'s Active Pokémon is now Confused and Poisoned. During Pokémon Checkup, put 8 damage counters on that Pokémon instead of 1.\"}, {\'name\': \'Cutting Wind\', \'cost\': [\'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'110\', \'text\': \'\'}]', 'Lost Origin', '1', 'Cascoon', '', 'Tends to be drawn to bonfires on dark nights. Difficult to chase away from settlements because of the way it scatters highly toxic scales.', 'Eighth', '140', 'https://images.pokemoncard.io/images/swsh11/swsh11-10.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Dustox', '269', 'TPCI', 'Rare', 'F', '09/09/2022', '', 'Colorless', '', 'Sword & Shield', '10', 'Stage 2', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('swsh11-100', '', '', 'Kouki Saitou', '[{\'name\': \'Battle Step\', \'cost\': [\'Fighting\'], \'convertedEnergyCost\': 1, \'damage\': \'50\', \'text\': \'Search your deck for up to 2 Fighting Energy cards and attach them to your Benched Pokémon in any way you like. Then, shuffle your deck.\'}]', 'Lost Origin', '1', 'Meditite', '', 'Through yoga training, it gained the psychic power to predict its foes next move.', 'Eighth', '110', 'https://images.pokemoncard.io/images/swsh11/swsh11-100.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Medicham', '308', 'TPCI', 'Uncommon', 'F', '09/09/2022', '', 'Colorless', '', 'Sword & Shield', '100', 'Stage 1', 'Pokémon', 'Fighting', 'type: Psychic, value: ×2'),
('swsh11-101', '', '', 'ryoma uratsuka', '[{\'name\': \'Into the Deep\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Put up to 2 basic Energy cards from your discard pile into your hand.\'}, {\'name\': \'Tackle\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'80\', \'text\': \'\'}]', 'Lost Origin', '1', '', '', 'Rock-hard scales and oil-filled swim bladders allow this Pokémon to survive the intense water pressure of the deep sea.', 'Eighth', '90', 'https://images.pokemoncard.io/images/swsh11/swsh11-101.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Relicanth', '369', 'TPCI', 'Uncommon', 'F', '09/09/2022', '', 'Colorless', '', 'Sword & Shield', '101', 'Basic', 'Pokémon', 'Fighting', 'type: Grass, value: ×2'),
('swsh11-102', '', '', 'Sanosuke Sakuma', '[{\'name\': \'Recover\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Discard an Energy from this Pokémon and heal all damage from it.\'}, {\'name\': \'Earthquake\', \'cost\': [\'Fighting\', \'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'170\', \'text\': \"This attack also does 20 damage to each of your Benched Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'Lost Origin', '3', 'Shellos', '', 'Its search for food sometimes leads it onto land, where it leaves behind a sticky trail of slime as it passes through.', 'Eighth', '130', 'https://images.pokemoncard.io/images/swsh11/swsh11-102.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Gastrodon', '423', 'TPCI', 'Uncommon', 'F', '09/09/2022', '', 'Colorless, Colorless, Colorless', '', 'Sword & Shield', '102', 'Stage 1', 'Pokémon', 'Fighting', 'type: Grass, value: ×2'),
('swsh11-103', '', '', 'yuu', '[{\'name\': \'Chop\', \'cost\': [\'Fighting\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'\'}, {\'name\': \'Spiral Kick\', \'cost\': [\'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'\'}]', 'Lost Origin', '1', '', 'Mienshao', 'In one minute, a well-trained Mienfoo can chop with its arms more than 100 times.', 'Eighth', '60', 'https://images.pokemoncard.io/images/swsh11/swsh11-103.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Mienfoo', '619', 'TPCI', 'Common', 'F', '09/09/2022', '', 'Colorless', '', 'Sword & Shield', '103', 'Basic', 'Pokémon', 'Fighting', 'type: Psychic, value: ×2'),
('swsh11-104', '', '', 'Shibuzoh.', '[{\'name\': \'Pound\', \'cost\': [\'Fighting\'], \'convertedEnergyCost\': 1, \'damage\': \'30\', \'text\': \'\'}, {\'name\': \'Double Smash\', \'cost\': [\'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'70×\', \'text\': \'Flip 2 coins. This attack does 70 damage for each heads.\'}]', 'Lost Origin', '1', 'Mienfoo', '', 'When Mienshao comes across a truly challenging opponent, it will lighten itself by biting off the fur on its arms.', 'Eighth', '90', 'https://images.pokemoncard.io/images/swsh11/swsh11-104.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Mienshao', '620', 'TPCI', 'Uncommon', 'F', '09/09/2022', '', 'Colorless', '', 'Sword & Shield', '104', 'Stage 1', 'Pokémon', 'Fighting', 'type: Psychic, value: ×2'),
('swsh11-105', '', '', 'KEIICHIRO ITO', '[{\'name\': \'Slap Push\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'20\', \'text\': \'\'}, {\'name\': \'Smashing Edge\', \'cost\': [\'Fighting\', \'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'130\', \'text\': \'Discard 2 Energy from this Pokémon.\'}]', 'Lost Origin', '1', '', '', 'From the forces of lightning and wind, it creates energy to give nutrients to the soil and make the land abundant.', 'Eighth', '120', 'https://images.pokemoncard.io/images/swsh11/swsh11-105.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Landorus', '645', 'TPCI', 'Rare', 'F', '09/09/2022', '', 'Colorless', '', 'Sword & Shield', '105', 'Basic', 'Pokémon', 'Fighting', 'type: Grass, value: ×2'),
('swsh11-106', '', '', 'Scav', '[{\'name\': \'Mud-Slap\', \'cost\': [\'Fighting\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'\'}, {\'name\': \'Slash\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'\'}]', 'Lost Origin', '2', '', 'Barbaracle', 'After two Binacle find a suitably sized rock, they adhere themselves to it and live together. They cooperate to gather food during high tide.', 'Eighth', '70', 'https://images.pokemoncard.io/images/swsh11/swsh11-106.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Binacle', '688', 'TPCI', 'Common', 'F', '09/09/2022', '', 'Colorless, Colorless', '', 'Sword & Shield', '106', 'Basic', 'Pokémon', 'Fighting', 'type: Grass, value: ×2');
INSERT INTO `cards` (`id`, `abilities`, `ancient_trait`, `artist`, `attacks`, `card_set`, `converted`, `evolves_from`, `evolves_to`, `flavor_text`, `generation`, `hp`, `img`, `legalities`, `level`, `name`, `national_pokedex_numbers`, `publisher`, `rarity`, `regulation_mark`, `release_date`, `resistances`, `retreat_cost`, `rules`, `series`, `set_num`, `subtypes`, `supertype`, `types`, `weakness`) VALUES
('swsh11-107', '[{\'name\': \'Lost Block\', \'text\': \'Your opponent puts any Prize cards they would take in the Lost Zone instead of into their hand.\', \'type\': \'Ability\'}]', '', 'KEIICHIRO ITO', '[{\'name\': \'Dynamic Chop\', \'cost\': [\'Fighting\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'100\', \'text\': \'\'}]', 'Lost Origin', '3', 'Binacle', '', 'Seven Binacle come together to form one Barbaracle. The Binacle that serves as the head gives orders to those serving as the limbs.', 'Eighth', '130', 'https://images.pokemoncard.io/images/swsh11/swsh11-107.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Barbaracle', '689', 'TPCI', 'Rare Holo', 'F', '09/09/2022', '', 'Colorless, Colorless, Colorless', '', 'Sword & Shield', '107', 'Stage 1', 'Pokémon', 'Fighting', 'type: Grass, value: ×2'),
('swsh11-108', '', '', 'Tika Matsuno', '[{\'name\': \'Lucky Find\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Search your deck for up to 2 Item cards, reveal them, and put them into your hand. Then, shuffle your deck.\'}, {\'name\': \'Power Gem\', \'cost\': [\'Fighting\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'80\', \'text\': \'\'}]', 'Lost Origin', '1', '', '', 'When beset by attackers, Carbink wipes them all out by firing high-energy beams from the gems embedded in its body.', 'Eighth', '90', 'https://images.pokemoncard.io/images/swsh11/swsh11-108.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Carbink', '703', 'TPCI', 'Uncommon', 'F', '09/09/2022', '', 'Colorless', '', 'Sword & Shield', '108', 'Basic', 'Pokémon', 'Fighting', 'type: Grass, value: ×2'),
('swsh11-109', '', '', 'Miki Tanaka', '[{\'name\': \'Double Draw\', \'cost\': [\'Fighting\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Draw 2 cards.\'}, {\'name\': \'Rear Kick\', \'cost\': [\'Fighting\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'30\', \'text\': \'\'}]', 'Lost Origin', '1', '', 'Lycanroc', 'This Pokémon can bond very strongly with its Trainer, but it also has a habit of biting. Raising a Rockruff for a long time can be challenging.', 'Eighth', '60', 'https://images.pokemoncard.io/images/swsh11/swsh11-109.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Rockruff', '744', 'TPCI', 'Common', 'F', '09/09/2022', '', 'Colorless', '', 'Sword & Shield', '109', 'Basic', 'Pokémon', 'Fighting', 'type: Grass, value: ×2'),
('swsh11-11', '', '', 'Yuka Morii', '[{\'name\': \'Absorb\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'Heal 10 damage from this Pokémon.\'}]', 'Lost Origin', '1', '', 'Nuzleaf', 'If it remains still, it looks just like a real nut. It delights in surprising foraging Pokémon.', 'Eighth', '50', 'https://images.pokemoncard.io/images/swsh11/swsh11-11.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Seedot', '273', 'TPCI', 'Common', 'F', '09/09/2022', '', 'Colorless', '', 'Sword & Shield', '11', 'Basic', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('swsh11-110', '', '', 'sowsow', '[{\'name\': \'Fighting Headbutt\', \'cost\': [\'Fighting\'], \'convertedEnergyCost\': 1, \'damage\': \'10+\', \'text\': \"This attack\'s damage isn\'t affected by Weakness. If your opponent\'s Active Pokémon is a Pokémon V, this attack does 50 more damage.\"}, {\'name\': \'Jet Headbutt\', \'cost\': [\'Fighting\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'80\', \'text\': \'\'}]', 'Lost Origin', '1', '', '', 'Five of them are troopers, and one is the brass. The brasss orders are absolute.', 'Eighth', '100', 'https://images.pokemoncard.io/images/swsh11/swsh11-110.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Falinks', '870', 'TPCI', 'Common', 'F', '09/09/2022', '', 'Colorless', '', 'Sword & Shield', '110', 'Basic', 'Pokémon', 'Fighting', 'type: Psychic, value: ×2'),
('swsh11-111', '', '', 'HYOGONOSUKE', '[{\'name\': \'Power Stone\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Attach up to 2 Fighting Energy cards from your hand to your Pokémon in any way you like.\'}, {\'name\': \'Lost Shot\', \'cost\': [\'Fighting\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'120\', \'text\': \"Put the top card of your opponent\'s deck in the Lost Zone.\"}]', 'Lost Origin', '4', '', '', 'It stands in grasslands, watching the suns descent from zenith to horizon. This Pokémon has a talent for delivering dynamic kicks.', 'Eighth', '140', 'https://images.pokemoncard.io/images/swsh11/swsh11-111.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Stonjourner', '874', 'TPCI', 'Rare', 'F', '09/09/2022', '', 'Colorless, Colorless, Colorless, Colorless', '', 'Sword & Shield', '111', 'Basic', 'Pokémon', 'Fighting', 'type: Grass, value: ×2'),
('swsh11-112', '', '', 'Atsuko Nishida', '[{\'name\': \'Poison Sting\', \'cost\': [\'Darkness\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \"Your opponent\'s Active Pokémon is now Poisoned.\"}]', 'Lost Origin', '1', '', 'Ariados', 'Although the poison from its fangs isnt that strong, its potent enough to weaken prey that gets caught in its web.', 'Eighth', '50', 'https://images.pokemoncard.io/images/swsh11/swsh11-112.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Spinarak', '167', 'TPCI', 'Common', 'F', '09/09/2022', '', 'Colorless', '', 'Sword & Shield', '112', 'Basic', 'Pokémon', 'Darkness', 'type: Fighting, value: ×2'),
('swsh11-113', '', '', 'Shinji Kanda', '[{\'name\': \'String Bind\', \'cost\': [\'Darkness\'], \'convertedEnergyCost\': 1, \'damage\': \'10+\', \'text\': \"This attack does 30 more damage for each Colorless in your opponent\'s Active Pokémon\'s Retreat Cost.\"}, {\'name\': \'Venomous Fang\', \'cost\': [\'Darkness\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'80\', \'text\': \"Your opponent\'s Active Pokémon is now Poisoned.\"}]', 'Lost Origin', '1', 'Spinarak', '', 'It spews threads from its mouth to catch its prey. When night falls, it leaves its web to go hunt aggressively.', 'Eighth', '90', 'https://images.pokemoncard.io/images/swsh11/swsh11-113.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Ariados', '168', 'TPCI', 'Rare', 'F', '09/09/2022', '', 'Colorless', '', 'Sword & Shield', '113', 'Stage 1', 'Pokémon', 'Darkness', 'type: Fighting, value: ×2'),
('swsh11-114', '', '', 'Yuka Morii', '[{\'name\': \'Peck\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'\'}, {\'name\': \'Wing Attack\', \'cost\': [\'Darkness\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'\'}]', 'Lost Origin', '1', '', 'Honchkrow', 'It searches for shiny things for its boss. Murkrows presence is said to be unlucky, so many people detest it.', 'Eighth', '60', 'https://images.pokemoncard.io/images/swsh11/swsh11-114.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Murkrow', '198', 'TPCI', 'Common', 'F', '09/09/2022', 'type: Fighting, value: -30', 'Colorless', '', 'Sword & Shield', '114', 'Basic', 'Pokémon', 'Darkness', 'type: Lightning, value: ×2'),
('swsh11-115', '', '', 'Shiburingaru', '[{\'name\': \'Peck\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'20\', \'text\': \'\'}, {\'name\': \'Night Cyclone\', \'cost\': [\'Darkness\', \'Darkness\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'160\', \'text\': \'Move all Energy from this Pokémon to your Benched Pokémon in any way you like.\'}]', 'Lost Origin', '1', 'Murkrow', '', 'Its goons take care of most of the fighting for it. The only time it dirties its own hands is in delivering a final blow to finish off an opponent.', 'Eighth', '120', 'https://images.pokemoncard.io/images/swsh11/swsh11-115.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Honchkrow', '430', 'TPCI', 'Rare', 'F', '09/09/2022', 'type: Fighting, value: -30', 'Colorless', '', 'Sword & Shield', '115', 'Stage 1', 'Pokémon', 'Darkness', 'type: Lightning, value: ×2'),
('swsh11-116', '', '', 'Tomokazu Komiya', '[{\'name\': \'Sucker Punch and Turn\', \'cost\': [\'Darkness\', \'Darkness\'], \'convertedEnergyCost\': 2, \'damage\': \'60\', \'text\': \'Switch this Pokémon with 1 of your Benched Darkness Pokémon.\'}]', 'Lost Origin', '2', '', '', 'Constant polishing makes the edge of the blade on its tail extremely sharp. Its Zangooses archrival.', 'Eighth', '110', 'https://images.pokemoncard.io/images/swsh11/swsh11-116.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Seviper', '336', 'TPCI', 'Uncommon', 'F', '09/09/2022', '', 'Colorless, Colorless', '', 'Sword & Shield', '116', 'Basic', 'Pokémon', 'Darkness', 'type: Fighting, value: ×2'),
('swsh11-117', '[{\'name\': \'Cursed Message\', \'text\': \"If this Pokémon is Knocked Out by damage from an attack from your opponent\'s Pokémon, search your deck for a card and put it into your hand. Then, shuffle your deck.\", \'type\': \'Ability\'}]', '', 'sui', '[{\'name\': \'Chain of Spirits\', \'cost\': [\'Darkness\', \'Darkness\'], \'convertedEnergyCost\': 2, \'damage\': \'10+\', \'text\': \'This attack does 60 more damage for each Spiritomb in your discard pile.\'}]', 'Lost Origin', '2', '', '', 'Exactly 108 spirits gathered to become this Pokémon. Apparently there are some ill-natured spirits in the mix.', 'Eighth', '60', 'https://images.pokemoncard.io/images/swsh11/swsh11-117.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Spiritomb', '442', 'TPCI', 'Rare', 'F', '09/09/2022', '', 'Colorless, Colorless', '', 'Sword & Shield', '117', 'Basic', 'Pokémon', 'Darkness', 'type: Grass, value: ×2'),
('swsh11-118', '[{\'name\': \'Wild Style\', \'text\': \"This Pokémon\'s attacks cost Colorless less for each of your opponent\'s Single Strike, Rapid Strike, and Fusion Strike Pokémon in play.\", \'type\': \'Ability\'}]', '', 'N-DESIGN Inc.', '[{\'name\': \'Dynamic Tail\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'190\', \'text\': \"This attack also does 60 damage to 1 of your Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'Lost Origin', '2', '', '', '', 'Eighth', '210', 'https://images.pokemoncard.io/images/swsh11/swsh11-118.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Drapion V', '452', 'TPCI', 'Rare Holo V', 'F', '09/09/2022', '', 'Colorless, Colorless', '[\'V rule: When your Pokémon V is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sword & Shield', '118', 'Basic, V', 'Pokémon', 'Darkness', 'type: Fighting, value: ×2'),
('swsh11-119', '[{\'name\': \'Hazard Star\', \'text\': \"During your turn, you may make your opponent\'s Active Pokémon Paralyzed and Poisoned. During Pokémon Checkup, put 3 damage counters on that Pokémon instead of 1. (You can\'t use more than 1 VSTAR Power in a game.)\", \'type\': \'Ability\'}]', '', 'PLANETA Mochizuki', '[{\'name\': \'Big Bang Arm\', \'cost\': [\'Darkness\', \'Darkness\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'250-\', \'text\': \'This attack does 10 less damage for each damage counter on this Pokémon.\'}]', 'Lost Origin', '3', 'Drapion V', '', '', 'Eighth', '270', 'https://images.pokemoncard.io/images/swsh11/swsh11-119.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Drapion VSTAR', '452', 'TPCI', 'Rare Holo VSTAR', 'F', '09/09/2022', '', 'Colorless, Colorless, Colorless', '[\'VSTAR rule: When your Pokémon VSTAR is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sword & Shield', '119', 'VSTAR', 'Pokémon', 'Darkness', 'type: Fighting, value: ×2'),
('swsh11-12', '', '', 'Mizue', '[{\'name\': \'Push Down\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'30\', \'text\': \'You may have your opponent switch their Active Pokémon with 1 of their Benched Pokémon.\'}]', 'Lost Origin', '2', 'Seedot', 'Shiftry', 'It lives deep in forests. With the leaf on its head, it makes a flute whose song makes listeners uneasy.', 'Eighth', '80', 'https://images.pokemoncard.io/images/swsh11/swsh11-12.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Nuzleaf', '274', 'TPCI', 'Uncommon', 'F', '09/09/2022', '', 'Colorless, Colorless', '', 'Sword & Shield', '12', 'Stage 1', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('swsh11-120', '', '', 'Shin Nagasawa', '[{\'name\': \'Nightmare\', \'cost\': [\'Darkness\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \"Your opponent\'s Active Pokémon is now Asleep.\"}, {\'name\': \'Pitch-Black Blade\', \'cost\': [\'Darkness\', \'Darkness\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'130\', \'text\': \"During your next turn, this Pokémon can\'t attack.\"}]', 'Lost Origin', '2', '', '', 'On a moonless night, a strange incident occurred in which every one of a villages inhabitants suffered nightmares. The villagers attested that Darkrai appeared before them in these nightmares.', 'Eighth', '120', 'https://images.pokemoncard.io/images/swsh11/swsh11-120.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Darkrai', '491', 'TPCI', 'Rare Holo', 'F', '09/09/2022', '', 'Colorless, Colorless', '', 'Sword & Shield', '120', 'Basic', 'Pokémon', 'Darkness', 'type: Grass, value: ×2'),
('swsh11-121', '', '', 'Shibuzoh.', '[{\'name\': \'Call for Family\', \'cost\': [\'Darkness\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Search your deck for up to 2 Basic Pokémon and put them onto your Bench. Then, shuffle your deck.\'}, {\'name\': \'Tackle\', \'cost\': [\'Darkness\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'\'}]', 'Lost Origin', '1', '', 'Malamar', 'It spins while making its luminescent spots flash. These spots allow it to communicate with others by using different patterns of light.', 'Eighth', '50', 'https://images.pokemoncard.io/images/swsh11/swsh11-121.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Inkay', '686', 'TPCI', 'Common', 'F', '09/09/2022', '', 'Colorless', '', 'Sword & Shield', '121', 'Basic', 'Pokémon', 'Darkness', 'type: Grass, value: ×2'),
('swsh11-122', '', '', 'Sanosuke Sakuma', '[{\'name\': \'Hand of Djinn\', \'cost\': [\'Darkness\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Search your deck for a Darkness Energy card and attach it to 1 of your Pokémon. Then, shuffle your deck.\'}, {\'name\': \'Tyrannical Hole\', \'cost\': [\'Darkness\', \'Darkness\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'100\', \'text\': \'\'}]', 'Lost Origin', '1', '', '', 'It gathers things it likes and passes them through its loop to teleport them to a secret place.', 'Eighth', '120', 'https://images.pokemoncard.io/images/swsh11/swsh11-122.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Hoopa', '720', 'TPCI', 'Rare', 'F', '09/09/2022', '', 'Colorless', '', 'Sword & Shield', '122', 'Basic', 'Pokémon', 'Darkness', 'type: Grass, value: ×2'),
('swsh11-123', '[{\'name\': \'Poison Peak\', \'text\': \"During Pokémon Checkup, put 2 more damage counters on your opponent\'s Poisoned Pokémon.\", \'type\': \'Ability\'}]', '', 'Akira Komayama', '[{\'name\': \'Poison Jab\', \'cost\': [\'Darkness\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'90\', \'text\': \"Your opponent\'s Active Pokémon is now Poisoned.\"}]', 'Lost Origin', '1', '', '', 'Because of Sneaslers virulent poison and daunting physical prowess, no other species could hope to best it on the frozen highlands. Preferring solitude, this species does not form packs.', 'Eighth', '130', 'https://images.pokemoncard.io/images/swsh11/swsh11-123.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Radiant Hisuian Sneasler', '903', 'TPCI', 'Radiant Rare', 'F', '09/09/2022', '', 'Colorless', '[\"Radiant Pokémon Rule: You can\'t have more than 1 Radiant Pokémon in your deck.\"]', 'Sword & Shield', '123', 'Basic, Radiant', 'Pokémon', 'Darkness', 'type: Fighting, value: ×2'),
('swsh11-124', '', '', 'Sanosuke Sakuma', '[{\'name\': \'Energy Stream\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'20\', \'text\': \'Attach up to 2 Metal Energy cards from your discard pile to this Pokémon.\'}, {\'name\': \'Destructive Finish\', \'cost\': [\'Metal\', \'Metal\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60+\', \'text\': \'Discard cards from the top of your deck until only 1 card remains. This attack does 30 more damage for each Energy card you discarded in this way.\'}]', 'Lost Origin', '4', '', '', 'It is said that if an Onix lives for over 100 years, its composition changes to become diamond-like.', 'Eighth', '170', 'https://images.pokemoncard.io/images/swsh11/swsh11-124.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Radiant Steelix', '208', 'TPCI', 'Radiant Rare', 'F', '09/09/2022', 'type: Grass, value: -30', 'Colorless, Colorless, Colorless, Colorless', '[\"Radiant Pokémon Rule: You can\'t have more than 1 Radiant Pokémon in your deck.\"]', 'Sword & Shield', '124', 'Basic, Radiant', 'Pokémon', 'Metal', 'type: Fire, value: ×2'),
('swsh11-125', '', '', 'Tomokazu Komiya', '[{\'name\': \'Spinning Attack\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'\'}]', 'Lost Origin', '2', '', 'Bronzong', 'It appears in ancient ruins. The pattern on its body doesnt come from any culture in the Galar region, so it remains shrouded in mystery.', 'Eighth', '70', 'https://images.pokemoncard.io/images/swsh11/swsh11-125.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Bronzor', '436', 'TPCI', 'Common', 'F', '09/09/2022', 'type: Grass, value: -30', 'Colorless, Colorless', '', 'Sword & Shield', '125', 'Basic', 'Pokémon', 'Metal', 'type: Fire, value: ×2'),
('swsh11-126', '', '', 'AKIRA EGAWA', '[{\'name\': \'Ram\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'\'}, {\'name\': \'Gravitational Drop\', \'cost\': [\'Metal\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40+\', \'text\': \"This attack does 40 more damage for each Colorless in your opponent\'s Active Pokémon\'s Retreat Cost.\"}]', 'Lost Origin', '3', 'Bronzor', '', 'Some believe that its bell-like cry opens holes to another world. It has been revered as a deity since ancient times.', 'Eighth', '130', 'https://images.pokemoncard.io/images/swsh11/swsh11-126.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Bronzong', '437', 'TPCI', 'Uncommon', 'F', '09/09/2022', 'type: Grass, value: -30', 'Colorless, Colorless, Colorless', '', 'Sword & Shield', '126', 'Stage 1', 'Pokémon', 'Metal', 'type: Fire, value: ×2'),
('swsh11-127', '', '', 'Shigenori Negishi', '[{\'name\': \'Field Trap\', \'cost\': [\'Metal\'], \'convertedEnergyCost\': 1, \'damage\': \'20\', \'text\': \"If your opponent has a Stadium in play, discard it. If you discarded a Stadium in this way, discard 2 Energy from your opponent\'s Active Pokémon.\"}, {\'name\': \'Tackle\', \'cost\': [\'Metal\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'50\', \'text\': \'\'}]', 'Lost Origin', '3', '', '', 'Living in mud with a high iron content has given it a strong steel body.', 'Eighth', '100', 'https://images.pokemoncard.io/images/swsh11/swsh11-127.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Galarian Stunfisk', '618', 'TPCI', 'Uncommon', 'F', '09/09/2022', 'type: Grass, value: -30', 'Colorless, Colorless, Colorless', '', 'Sword & Shield', '127', 'Basic', 'Pokémon', 'Metal', 'type: Fire, value: ×2'),
