('swsh11tg-TG21', '', '', 'kodama', '[{\'name\': \'Power Accelerator\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'30\', \'text\': \'You may attach a Darkness Energy card from your hand to 1 of your Benched Pokémon.\'}, {\'name\': \'Dynamax Cannon\', \'cost\': [\'Darkness\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'120+\', \'text\': \"If your opponent\'s Active Pokémon is a Pokémon VMAX, this attack does 120 more damage.\"}]', 'Lost Origin Trainer Gallery', '2', '', '', '', 'Eighth', '220', 'https://images.pokemoncard.io/images/swsh11tg/swsh11tg-TG21.png', 'unlimited: Legal, expanded: Legal', '', 'Eternatus V', '890', 'TPCI', 'Rare Holo V', 'D', '09/09/2022', '', 'Colorless, Colorless', '[\'V rule: When your Pokémon V is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sword & Shield', 'TG21', 'Basic, V', 'Pokémon', 'Darkness', 'type: Fighting, value: ×2'),
('swsh11tg-TG22', '[{\'name\': \'Eternal Zone\', \'text\': \"If all of your Pokémon in play are Darkness type, you can have up to 8 Pokémon on your Bench, and you can\'t put non-Darkness Pokémon into play. (If this Ability stops working, discard Pokémon from your Bench until you have 5.)\", \'type\': \'Ability\'}]', '', 'Mitsuhiro Arita', '[{\'name\': \'Dread End\', \'cost\': [\'Darkness\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30×\', \'text\': \'This attack does 30 damage for each of your Darkness Pokémon in play.\'}]', 'Lost Origin Trainer Gallery', '3', 'Eternatus V', '', '', 'Eighth', '340', 'https://images.pokemoncard.io/images/swsh11tg/swsh11tg-TG22.png', 'unlimited: Legal, expanded: Legal', '', 'Eternatus VMAX', '890', 'TPCI', 'Rare Holo VMAX', 'D', '09/09/2022', '', 'Colorless, Colorless, Colorless', '[\'VMAX rule: When your Pokémon VMAX is Knocked Out, your opponent takes 3 Prize cards.\']', 'Sword & Shield', 'TG22', 'VMAX, Eternamax', 'Pokémon', 'Darkness', 'type: Fighting, value: ×2'),
('swsh11tg-TG23', '', '', 'Taira Akitsu', '', 'Lost Origin Trainer Gallery', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh11tg/swsh11tg-TG23.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Adventurers Discovery', '', 'TPCI', 'Rare Ultra', 'E', '09/09/2022', '', '', '[\'Search your deck for up to 3 Pokémon V, reveal them, and put them into your hand. Then, shuffle your deck.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', 'TG23', 'Supporter', 'Trainer', '', ''),
('swsh11tg-TG24', '', '', 'NC Empire', '', 'Lost Origin Trainer Gallery', '', '', '', 'Lysandre', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh11tg/swsh11tg-TG24.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Bosss Orders', '', 'TPCI', 'Rare Ultra', 'D', '09/09/2022', '', '', '[\"Switch 1 of your opponent\'s Benched Pokémon with their Active Pokémon.\", \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', 'TG24', 'Supporter', 'Trainer', '', ''),
('swsh11tg-TG25', '', '', 'Sanosuke Sakuma', '', 'Lost Origin Trainer Gallery', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh11tg/swsh11tg-TG25.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Cook', '', 'TPCI', 'Rare Ultra', 'E', '09/09/2022', '', '', '[\'Heal 70 damage from your Active Pokémon.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', 'TG25', 'Supporter', 'Trainer', '', ''),
('swsh11tg-TG26', '', '', 'Hideki Ishikawa', '', 'Lost Origin Trainer Gallery', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh11tg/swsh11tg-TG26.png', 'unlimited: Legal, expanded: Legal', '', 'Kabu', '', 'TPCI', 'Rare Ultra', 'D', '09/09/2022', '', '', '[\'Shuffle your hand into your deck. Then, draw 4 cards. If your Active Pokémon is your only Pokémon in play, draw 8 cards instead.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', 'TG26', 'Supporter', 'Trainer', '', ''),
('swsh11tg-TG27', '', '', 'saino misaki', '', 'Lost Origin Trainer Gallery', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh11tg/swsh11tg-TG27.png', 'unlimited: Legal, expanded: Legal', '', 'Nessa', '', 'TPCI', 'Rare Ultra', 'D', '09/09/2022', '', '', '[\'Put up to 4 in any combination of Water Pokémon and Water Energy cards from your discard pile into your hand.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', 'TG27', 'Supporter', 'Trainer', '', ''),
('swsh11tg-TG28', '', '', 'Taira Akitsu', '', 'Lost Origin Trainer Gallery', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh11tg/swsh11tg-TG28.png', 'unlimited: Legal, expanded: Legal', '', 'Opal', '', 'TPCI', 'Rare Ultra', 'D', '09/09/2022', '', '', '[\'Flip 2 coins. Search your deck for a number of cards up to the number of heads, put them into your hand, and shuffle your deck.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', 'TG28', 'Supporter', 'Trainer', '', ''),
('swsh11tg-TG29', '', '', 'aky CG Works', '[{\'name\': \'G-Max Volt Tackle\', \'cost\': [\'Lightning\', \'Lightning\', \'Lightning\'], \'convertedEnergyCost\': 3, \'damage\': \'120+\', \'text\': \'You may discard all Energy from this Pokémon. If you do, this attack does 150 more damage.\'}]', 'Lost Origin Trainer Gallery', '2', 'Pikachu V', 'Raichu', '', 'Eighth', '310', 'https://images.pokemoncard.io/images/swsh11tg/swsh11tg-TG29.png', 'unlimited: Legal, expanded: Legal', '', 'Pikachu VMAX', '25', 'TPCI', 'Rare Secret', 'D', '09/09/2022', '', 'Colorless, Colorless', '[\'VMAX rule: When your Pokémon VMAX is Knocked Out, your opponent takes 3 Prize cards.\']', 'Sword & Shield', 'TG29', 'VMAX', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
('swsh11tg-TG30', '', '', '5ban Graphics', '[{\'name\': \'Cross Fusion Strike\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'\', \'text\': \"Choose 1 of your Benched Fusion Strike Pokémon\'s attacks and use it as this attack.\"}, {\'name\': \'Max Miracle\', \'cost\': [\'Psychic\', \'Psychic\'], \'convertedEnergyCost\': 2, \'damage\': \'130\', \'text\': \"This attack\'s damage isn\'t affected by any effects on your opponent\'s Active Pokémon.\"}]', 'Lost Origin Trainer Gallery', '', 'Mew V', '', '', 'Eighth', '310', 'https://images.pokemoncard.io/images/swsh11tg/swsh11tg-TG30.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Mew VMAX', '151', 'TPCI', 'Rare Secret', 'E', '09/09/2022', 'type: Fighting, value: -30', '', '[\'VMAX rule: When your Pokémon VMAX is Knocked Out, your opponent takes 3 Prize cards.\']', 'Sword & Shield', 'TG30', 'VMAX, Fusion Strike', 'Pokémon', 'Psychic', 'type: Darkness, value: ×2'),
('swsh12-1', '', '', 'Sekio', '[{\'name\': \'Tackle\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'20\', \'text\': \'\'}]', 'Silver Tempest', '1', '', 'Venomoth', 'Lives in the shadows of tall trees where it eats bugs. It is attracted by light at night.', 'Eighth', '60', 'https://images.pokemoncard.io/images/swsh12/swsh12-1.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Venonat', '48', 'TPCI', 'Common', 'F', '11/11/2022', '', 'Colorless', '', 'Sword & Shield', '1', 'Basic', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('swsh12-10', '', '', 'Mitsuhiro Arita', '[{\'name\': \'Swelling Scent\', \'cost\': [], \'convertedEnergyCost\': 0, \'damage\': \'\', \'text\': \'Search your deck for up to 2 Grass Energy cards and attach them to your Benched Pokémon in any way you like. Then, shuffle your deck.\'}, {\'name\': \'Spiral Kick\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'50\', \'text\': \'\'}]', 'Silver Tempest', '1', 'Petilil', '', 'I suspect that its well-developed legs are the result of a life spent on mountains covered in deep snow. The scent it exudes from its flower crown heartens those in proximity.', 'Eighth', '120', 'https://images.pokemoncard.io/images/swsh12/swsh12-10.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Hisuian Lilligant', '549', 'TPCI', 'Rare', 'F', '11/11/2022', '', 'Colorless', '', 'Sword & Shield', '10', 'Stage 1', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('swsh12-100', '', '', 'sui', '[{\'name\': \'Sandpot Trap\', \'cost\': [\'Fighting\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"This attack does 30 damage to each of your opponent\'s Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}, {\'name\': \'Land Crush\', \'cost\': [\'Fighting\', \'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'120\', \'text\': \'\'}]', 'Silver Tempest', '3', 'Sandygast', '', 'Palossand is known as the Beach Nightmare. It pulls its prey down into the sand by controlling the sand itself, and then it sucks out their souls.', 'Eighth', '140', 'https://images.pokemoncard.io/images/swsh12/swsh12-100.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Palossand', '770', 'TPCI', 'Uncommon', 'F', '11/11/2022', '', 'Colorless, Colorless, Colorless', '', 'Sword & Shield', '100', 'Stage 1', 'Pokémon', 'Fighting', 'type: Grass, value: ×2'),
('swsh12-101', '', '', 'Hataya', '[{\'name\': \'Rock Throw\', \'cost\': [\'Fighting\'], \'convertedEnergyCost\': 1, \'damage\': \'20\', \'text\': \'\'}, {\'name\': \'Mystery Press\', \'cost\': [\'Fighting\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60+\', \'text\': \'If you have no Supporter cards in your discard pile, this attack does 130 more damage.\'}]', 'Silver Tempest', '3', '', '', 'It stands in grasslands, watching the suns descent from zenith to horizon. This Pokémon has a talent for delivering dynamic kicks.', 'Eighth', '130', 'https://images.pokemoncard.io/images/swsh12/swsh12-101.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Stonjourner', '874', 'TPCI', 'Uncommon', 'F', '11/11/2022', '', 'Colorless, Colorless, Colorless', '', 'Sword & Shield', '101', 'Basic', 'Pokémon', 'Fighting', 'type: Grass, value: ×2'),
('swsh12-102', '[{\'name\': \'Hard Coat\', \'text\': \'This Pokémon takes 30 less damage from attacks (after applying Weakness and Resistance).\', \'type\': \'Ability\'}]', '', '5ban Graphics', '[{\'name\': \'Peat Shoulder\', \'cost\': [\'Fighting\', \'Fighting\', \'Fighting\'], \'convertedEnergyCost\': 3, \'damage\': \'220-\', \'text\': \'This attack does 10 less damage for each damage counter on this Pokémon.\'}]', 'Silver Tempest', '4', '', '', '', 'Eighth', '230', 'https://images.pokemoncard.io/images/swsh12/swsh12-102.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Ursaluna V', '901', 'TPCI', 'Rare Holo V', 'F', '11/11/2022', '', 'Colorless, Colorless, Colorless, Colorless', '[\'V rule: When your Pokémon V is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sword & Shield', '102', 'Basic, V', 'Pokémon', 'Fighting', 'type: Grass, value: ×2'),
('swsh12-103', '', '', 'Shigenori Negishi', '[{\'name\': \'Bite\', \'cost\': [\'Darkness\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'\'}]', 'Silver Tempest', '', '', 'Golbat', 'It emits ultrasonic waves from its mouth to check its surroundings. Even in tight caves, Zubat flies around with skill.', 'Eighth', '40', 'https://images.pokemoncard.io/images/swsh12/swsh12-103.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Zubat', '41', 'TPCI', 'Common', 'F', '11/11/2022', '', '', '', 'Sword & Shield', '103', 'Basic', 'Pokémon', 'Darkness', 'type: Fighting, value: ×2');
