('swsh12pt5gg-GG47', '[{\'name\': \"Witch\'s Domain\", \'text\': \"Once during your turn, you may move up to 2 damage counters from your Pokémon to your opponent\'s Active Pokémon.\", \'type\': \'Ability\'}]', '', 'sui', '[{\'name\': \'G-Max Smite\', \'cost\': [\'Psychic\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'150\', \'text\': \"Your opponent\'s Active Pokémon is now Confused.\"}]', 'Crown Zenith Galarian Gallery', '2', 'Hatterene V', '', '', 'Eighth', '320', 'https://images.pokemoncard.io/images/swsh12pt5gg/swsh12pt5gg-GG47.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Hatterene VMAX', '858', 'TPCI', 'Rare Holo VMAX', 'F', '1/20/2023', 'type: Fighting, value: -30', 'Colorless, Colorless', '[\'VMAX rule: When your Pokémon VMAX is Knocked Out, your opponent takes 3 Prize cards.\']', 'Sword & Shield', 'GG47', 'VMAX', 'Pokémon', 'Psychic', 'type: Darkness, value: ×2'),
('swsh12pt5gg-GG48', '[{\'name\': \'Roar of the Sword\', \'text\': \'Once during your turn, you may search your deck for a Psychic Energy card and attach it to 1 of your Pokémon. Then, shuffle your deck. If you use this Ability, your turn ends.\', \'type\': \'Ability\'}]', '', 'Hataya', '[{\'name\': \'Storm Slash\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60+\', \'text\': \'This attack does 30 more damage for each Psychic Energy attached to this Pokémon.\'}]', 'Crown Zenith Galarian Gallery', '2', '', '', '', 'Eighth', '220', 'https://images.pokemoncard.io/images/swsh12pt5gg/swsh12pt5gg-GG48.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Zacian V', '888', 'TPCI', 'Rare Holo V', 'E', '1/20/2023', '', 'Colorless, Colorless', '[\'V rule: When your Pokémon V is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sword & Shield', 'GG48', 'Basic, V', 'Pokémon', 'Psychic', 'type: Metal, value: ×2'),
('swsh12pt5gg-GG49', '[{\'name\': \'Wild Style\', \'text\': \"This Pokémon\'s attacks cost Colorless less for each of your opponent\'s Single Strike, Rapid Strike, and Fusion Strike Pokémon in play.\", \'type\': \'Ability\'}]', '', 'Yuka Morii', '[{\'name\': \'Dynamic Tail\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'190\', \'text\': \"This attack also does 60 damage to 1 of your Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'Crown Zenith Galarian Gallery', '2', '', '', '', 'Eighth', '210', 'https://images.pokemoncard.io/images/swsh12pt5gg/swsh12pt5gg-GG49.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Drapion V', '452', 'TPCI', 'Rare Holo V', 'F', '1/20/2023', '', 'Colorless, Colorless', '[\'V rule: When your Pokémon V is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sword & Shield', 'GG49', 'Basic, V', 'Pokémon', 'Darkness', 'type: Fighting, value: ×2'),
('swsh12pt5gg-GG50', '[{\'name\': \'Star Abyss\', \'text\': \"During your turn, you may put up to 2 Item cards from your discard pile into your hand. (You can\'t use more than 1 VSTAR Power in a game.)\", \'type\': \'Ability\'}]', '', 'Pani Kobayashi', '[{\'name\': \'Dark Pulse\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30+\', \'text\': \'This attack does 30 more damage for each Darkness Energy attached to all of your Pokémon.\'}]', 'Crown Zenith Galarian Gallery', '2', 'Darkrai V', '', '', 'Eighth', '270', 'https://images.pokemoncard.io/images/swsh12pt5gg/swsh12pt5gg-GG50.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Darkrai VSTAR', '491', 'TPCI', 'Rare Holo VSTAR', 'F', '1/20/2023', '', 'Colorless, Colorless', '[\'VSTAR rule: When your Pokémon VSTAR is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sword & Shield', 'GG50', 'VSTAR', 'Pokémon', 'Darkness', 'type: Grass, value: ×2'),
('swsh12pt5gg-GG51', '', '', 'kodama', '[{\'name\': \'Basket Crash\', \'cost\': [\'Darkness\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Discard up to 2 Pokémon Tools from your opponent\'s Pokémon.\"}, {\'name\': \'Shadow Slash\', \'cost\': [\'Darkness\', \'Darkness\', \'Darkness\'], \'convertedEnergyCost\': 3, \'damage\': \'180\', \'text\': \'Discard an Energy from this Pokémon.\'}]', 'Crown Zenith Galarian Gallery', '2', '', '', '', 'Eighth', '220', 'https://images.pokemoncard.io/images/swsh12pt5gg/swsh12pt5gg-GG51.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Hisuian Samurott V', '503', 'TPCI', 'Rare Holo V', 'F', '1/20/2023', '', 'Colorless, Colorless', '[\'V rule: When your Pokémon V is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sword & Shield', 'GG51', 'Basic, V', 'Pokémon', 'Darkness', 'type: Grass, value: ×2'),
('swsh12pt5gg-GG52', '[{\'name\': \'Moon Cleave Star\', \'text\': \"During your turn, you may put 4 damage counters on 1 of your opponent\'s Pokémon. (You can\'t use more than 1 VSTAR Power in a game.)\", \'type\': \'Ability\'}]', '', 'Shibuzoh.', '[{\'name\': \'Merciless Blade\', \'cost\': [\'Darkness\', \'Darkness\'], \'convertedEnergyCost\': 2, \'damage\': \'110+\', \'text\': \"If your opponent\'s Active Pokémon already has any damage counters on it, this attack does 110 more damage.\"}]', 'Crown Zenith Galarian Gallery', '2', 'Hisuian Samurott V', '', '', 'Eighth', '270', 'https://images.pokemoncard.io/images/swsh12pt5gg/swsh12pt5gg-GG52.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Hisuian Samurott VSTAR', '503', 'TPCI', 'Rare Holo VSTAR', 'F', '1/20/2023', '', 'Colorless, Colorless', '[\'VSTAR rule: When your Pokémon VSTAR is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sword & Shield', 'GG52', 'VSTAR', 'Pokémon', 'Darkness', 'type: Grass, value: ×2'),
('swsh12pt5gg-GG53', '[{\'name\': \'Two-Faced\', \'text\': \'As long as this Pokémon is in play, it is Psychic and Darkness type.\', \'type\': \'Ability\'}]', '', 'OKACHEKE', '[{\'name\': \'Shadow Impact\', \'cost\': [\'Darkness\', \'Darkness\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'170\', \'text\': \'Put 3 damage counters on 1 of your Pokémon.\'}]', 'Crown Zenith Galarian Gallery', '2', '', '', '', 'Eighth', '220', 'https://images.pokemoncard.io/images/swsh12pt5gg/swsh12pt5gg-GG53.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Hoopa V', '720', 'TPCI', 'Rare Holo V', 'E', '1/20/2023', '', 'Colorless, Colorless', '[\'V rule: When your Pokémon V is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sword & Shield', 'GG53', 'Basic, V, Fusion Strike', 'Pokémon', 'Darkness', 'type: Grass, value: ×2'),
('swsh12pt5gg-GG54', '[{\'name\': \'Regal Stance\', \'text\': \'Once during your turn, you may discard your hand and draw 5 cards. If you use this Ability, your turn ends.\', \'type\': \'Ability\'}]', '', 'Haru Akasaka', '[{\'name\': \'Revenge Blast\', \'cost\': [\'Metal\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'120+\', \'text\': \'This attack does 30 more damage for each Prize card your opponent has taken.\'}]', 'Crown Zenith Galarian Gallery', '2', '', '', '', 'Eighth', '220', 'https://images.pokemoncard.io/images/swsh12pt5gg/swsh12pt5gg-GG54.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Zamazenta V', '889', 'TPCI', 'Rare Holo V', 'F', '1/20/2023', 'type: Grass, value: -30', 'Colorless, Colorless', '[\'V rule: When your Pokémon V is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sword & Shield', 'GG54', 'Basic, V', 'Pokémon', 'Metal', 'type: Fire, value: ×2'),
('swsh12pt5gg-GG55', '[{\'name\': \'Star Guardian\', \'text\': \"During your turn, if your opponent has exactly 1 Prize card remaining, you may choose 1 of your opponent\'s Benched Pokémon. They discard that Pokémon and all attached cards. (You can\'t use more than 1 VSTAR Power in a game.)\", \'type\': \'Ability\'}]', '', 'Aya Kusube', '[{\'name\': \'Giga Impact\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'230\', \'text\': \"During your next turn, this Pokémon can\'t attack.\"}]', 'Crown Zenith Galarian Gallery', '4', 'Regigigas V', '', '', 'Eighth', '300', 'https://images.pokemoncard.io/images/swsh12pt5gg/swsh12pt5gg-GG55.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Regigigas VSTAR', '486', 'TPCI', 'Rare Holo VSTAR', 'F', '1/20/2023', '', 'Colorless, Colorless, Colorless, Colorless', '[\'VSTAR rule: When your Pokémon VSTAR is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sword & Shield', 'GG55', 'VSTAR', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('swsh12pt5gg-GG56', '[{\'name\': \'Phantom Star\', \'text\': \"During your turn, you may discard your hand and draw 7 cards. (You can\'t use more than 1 VSTAR Power in a game.)\", \'type\': \'Ability\'}]', '', 'SIE NANAHARA', '[{\'name\': \'Ticking Curse\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'50×\', \'text\': \'This attack does 50 damage for each of your Pokémon that has any damage counters on it.\'}]', 'Crown Zenith Galarian Gallery', '2', 'Hisuian Zoroark V', '', '', 'Eighth', '270', 'https://images.pokemoncard.io/images/swsh12pt5gg/swsh12pt5gg-GG56.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Hisuian Zoroark VSTAR', '571', 'TPCI', 'Rare Holo VSTAR', 'F', '1/20/2023', '', 'Colorless, Colorless', '[\'VSTAR rule: When your Pokémon VSTAR is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sword & Shield', 'GG56', 'VSTAR', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('swsh12pt5gg-GG57', '', '', 'Naoki Saito', '', 'Crown Zenith Galarian Gallery', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh12pt5gg/swsh12pt5gg-GG57.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Adaman', '', 'TPCI', 'Rare Ultra', 'F', '1/20/2023', '', '', '[\'You can use this card only if you discard 2 Metal Energy cards from your hand. Search your deck for up to 2 cards and put them into your hand. Then, shuffle your deck.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', 'GG57', 'Supporter', 'Trainer', '', ''),
('swsh12pt5gg-GG58', '', '', 'chibi', '', 'Crown Zenith Galarian Gallery', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh12pt5gg/swsh12pt5gg-GG58.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Cherens Care', '', 'TPCI', 'Rare Ultra', 'F', '1/20/2023', '', '', '[\'Put 1 of your Colorless Pokémon that has any damage counters on it and all attached cards into your hand.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', 'GG58', 'Supporter', 'Trainer', '', ''),
('swsh12pt5gg-GG59', '', '', 'kantaro', '', 'Crown Zenith Galarian Gallery', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh12pt5gg/swsh12pt5gg-GG59.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Colresss Experiment', '', 'TPCI', 'Rare Ultra', 'F', '1/20/2023', '', '', '[\'Look at the top 5 cards of your deck and put 3 of them into your hand. Put the other cards in the Lost Zone.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', 'GG59', 'Supporter', 'Trainer', '', ''),
('swsh12pt5gg-GG60', '', '', 'Atsuya Uki', '', 'Crown Zenith Galarian Gallery', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh12pt5gg/swsh12pt5gg-GG60.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Cynthias Ambition', '', 'TPCI', 'Rare Ultra', 'F', '1/20/2023', '', '', '[\"Draw cards until you have 5 cards in your hand. If any of your Pokémon were Knocked Out during your opponent\'s last turn, draw cards until you have 8 cards in your hand instead.\", \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', 'GG60', 'Supporter', 'Trainer', '', ''),
('swsh12pt5gg-GG61', '', '', 'Yoriyuki Ikegami', '', 'Crown Zenith Galarian Gallery', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh12pt5gg/swsh12pt5gg-GG61.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Gardenias Vigor', '', 'TPCI', 'Rare Ultra', 'F', '1/20/2023', '', '', '[\'Draw 2 cards. If you drew any cards in this way, attach up to 2 Grass Energy cards from your hand to 1 of your Benched Pokémon.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', 'GG61', 'Supporter', 'Trainer', '', '');
INSERT INTO `cards` (`id`, `abilities`, `ancient_trait`, `artist`, `attacks`, `card_set`, `converted`, `evolves_from`, `evolves_to`, `flavor_text`, `generation`, `hp`, `img`, `legalities`, `level`, `name`, `national_pokedex_numbers`, `publisher`, `rarity`, `regulation_mark`, `release_date`, `resistances`, `retreat_cost`, `rules`, `series`, `set_num`, `subtypes`, `supertype`, `types`, `weakness`) VALUES
('swsh12pt5gg-GG62', '', '', 'Oswaldo KATO', '', 'Crown Zenith Galarian Gallery', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh12pt5gg/swsh12pt5gg-GG62.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Grant', '', 'TPCI', 'Rare Ultra', 'F', '1/20/2023', '', '', '[\"During this turn, your Fighting Pokémon\'s attacks do 30 more damage to your opponent\'s Active Pokémon (before applying Weakness and Resistance). During your turn, if this Grant is in your discard pile, you may discard 2 cards, except any Grant, from your hand. If you do, put this Grant into your hand. (This effect doesn\'t use up your Supporter card for the turn.)\", \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', 'GG62', 'Supporter', 'Trainer', '', ''),
('swsh12pt5gg-GG63', '', '', 'Naoki Saito', '', 'Crown Zenith Galarian Gallery', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh12pt5gg/swsh12pt5gg-GG63.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Irida', '', 'TPCI', 'Rare Ultra', 'F', '1/20/2023', '', '', '[\'Search your deck for a Water Pokémon and an Item card, reveal them, and put them into your hand. Then, shuffle your deck.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', 'GG63', 'Supporter', 'Trainer', '', ''),
('swsh12pt5gg-GG64', '', '', 'saino misaki', '', 'Crown Zenith Galarian Gallery', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh12pt5gg/swsh12pt5gg-GG64.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Melony', '', 'TPCI', 'Rare Ultra', 'E', '1/20/2023', '', '', '[\'Attach a Water Energy card from your discard pile to 1 of your Pokémon V. If you do, draw 3 cards.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', 'GG64', 'Supporter', 'Trainer', '', ''),
('swsh12pt5gg-GG65', '', '', 'GIDORA', '', 'Crown Zenith Galarian Gallery', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh12pt5gg/swsh12pt5gg-GG65.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Raihan', '', 'TPCI', 'Rare Ultra', 'E', '1/20/2023', '', '', '[\"You can play this card only if any of your Pokémon were Knocked Out during your opponent\'s last turn. Attach a basic Energy card from your discard pile to 1 of your Pokémon. If you do, search your deck for a card and put it into your hand. Then, shuffle your deck.\", \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', 'GG65', 'Supporter', 'Trainer', '', ''),
('swsh12pt5gg-GG66', '', '', 'Toshinao Aoki', '', 'Crown Zenith Galarian Gallery', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh12pt5gg/swsh12pt5gg-GG66.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Roxanne', '', 'TPCI', 'Rare Ultra', 'F', '1/20/2023', '', '', '[\'You can use this card only if your opponent has 3 or fewer Prize cards remaining. Each player shuffles their hand into their deck. Then, you draw 6 cards, and your opponent draws 2 cards.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', 'GG66', 'Supporter', 'Trainer', '', ''),
('swsh12pt5gg-GG67', '[{\'name\': \'Star Portal\', \'text\': \"During your turn, you may attach up to 3 Water Energy cards from your discard pile to your Water Pokémon in any way you like. (You can\'t use more than 1 VSTAR Power in a game.)\", \'type\': \'Ability\'}]', '', 'AKIRA EGAWA', '[{\'name\': \'Subspace Swell\', \'cost\': [\'Water\', \'Water\'], \'convertedEnergyCost\': 2, \'damage\': \'60+\', \'text\': \"This attack does 20 more damage for each Benched Pokémon (both yours and your opponent\'s).\"}]', 'Crown Zenith Galarian Gallery', '2', 'Origin Forme Palkia V', '', '', 'Eighth', '280', 'https://images.pokemoncard.io/images/swsh12pt5gg/swsh12pt5gg-GG67.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Origin Forme Palkia VSTAR', '484', 'TPCI', 'Rare Secret', 'F', '1/20/2023', '', 'Colorless, Colorless', '[\'VSTAR rule: When your Pokémon VSTAR is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sword & Shield', 'GG67', 'VSTAR', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('swsh12pt5gg-GG68', '', '', 'AKIRA EGAWA', '[{\'name\': \'Metal Blast\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'40+\', \'text\': \'This attack does 40 more damage for each Metal Energy attached to this Pokémon.\'}, {\'name\': \'Star Chronos\', \'cost\': [\'Metal\', \'Metal\', \'Metal\', \'Metal\', \'Colorless\'], \'convertedEnergyCost\': 5, \'damage\': \'220\', \'text\': \"Take another turn after this one. (Skip Pokémon Checkup.) (You can\'t use more than 1 VSTAR Power in a game.)\"}]', 'Crown Zenith Galarian Gallery', '3', 'Origin Forme Dialga V', '', '', 'Eighth', '280', 'https://images.pokemoncard.io/images/swsh12pt5gg/swsh12pt5gg-GG68.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Origin Forme Dialga VSTAR', '483', 'TPCI', 'Rare Secret', 'F', '1/20/2023', 'type: Grass, value: -30', 'Colorless, Colorless, Colorless', '[\'VSTAR rule: When your Pokémon VSTAR is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sword & Shield', 'GG68', 'VSTAR', 'Pokémon', 'Metal', 'type: Fire, value: ×2'),
('swsh12pt5gg-GG69', '', '', 'AKIRA EGAWA', '[{\'name\': \'Lost Impact\', \'cost\': [\'Grass\', \'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'280\', \'text\': \'Put 2 Energy attached to your Pokémon in the Lost Zone.\'}, {\'name\': \'Star Requiem\', \'cost\': [\'Grass\', \'Psychic\'], \'convertedEnergyCost\': 2, \'damage\': \'\', \'text\': \"You can use this attack only if you have 10 or more cards in the Lost Zone. Your opponent\'s Active Pokémon is Knocked Out. (You can\'t use more than 1 VSTAR Power in a game.)\"}]', 'Crown Zenith Galarian Gallery', '2', 'Giratina V', '', '', 'Eighth', '280', 'https://images.pokemoncard.io/images/swsh12pt5gg/swsh12pt5gg-GG69.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Giratina VSTAR', '487', 'TPCI', 'Rare Secret', 'F', '1/20/2023', '', 'Colorless, Colorless', '[\'VSTAR rule: When your Pokémon VSTAR is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sword & Shield', 'GG69', 'VSTAR', 'Pokémon', 'Dragon', ''),
('swsh12pt5gg-GG70', '[{\'name\': \'Starbirth\', \'text\': \"During your turn, you may search your deck for up to 2 cards and put them into your hand. Then, shuffle your deck. (You can\'t use more than 1 VSTAR Power in a game.)\", \'type\': \'Ability\'}]', '', 'AKIRA EGAWA', '[{\'name\': \'Trinity Nova\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'200\', \'text\': \'Search your deck for up to 3 basic Energy cards and attach them to your Pokémon V in any way you like. Then, shuffle your deck.\'}]', 'Crown Zenith Galarian Gallery', '2', 'Arceus V', '', '', 'Eighth', '280', 'https://images.pokemoncard.io/images/swsh12pt5gg/swsh12pt5gg-GG70.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Arceus VSTAR', '493', 'TPCI', 'Rare Secret', 'F', '1/20/2023', '', 'Colorless, Colorless', '[\'VSTAR rule: When your Pokémon VSTAR is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sword & Shield', 'GG70', 'VSTAR', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
