('swsh12tg-TG27', '', '', 'take', '', 'Silver Tempest Trainer Gallery', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh12tg/swsh12tg-TG27.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Raihan', '', 'TPCI', 'Rare Ultra', 'E', '11/11/2022', '', '', '[\"You can play this card only if any of your Pokémon were Knocked Out during your opponent\'s last turn. Attach a basic Energy card from your discard pile to 1 of your Pokémon. If you do, search your deck for a card and put it into your hand. Then, shuffle your deck.\", \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', 'TG27', 'Supporter', 'Trainer', '', ''),
('swsh12tg-TG28', '', '', 'nagimiso', '', 'Silver Tempest Trainer Gallery', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh12tg/swsh12tg-TG28.png', 'unlimited: Legal, expanded: Legal', '', 'Sordward & Shielbert', '', 'TPCI', 'Rare Ultra', 'D', '11/11/2022', '', '', '[\'Choose a Trainer card from your discard pile. Then, ask your opponent if you may put it into your hand. If yes, put that card into your hand. If no, draw 3 cards.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', 'TG28', 'Supporter', 'Trainer', '', ''),
('swsh12tg-TG29', '[{\'name\': \'Azure Pulse\', \'text\': \'Once during your turn, you may discard your hand and draw 3 cards.\', \'type\': \'Ability\'}]', '', 'PLANETA Mochizuki', '[{\'name\': \'Max Burst\', \'cost\': [\'Fire\', \'Lightning\'], \'convertedEnergyCost\': 2, \'damage\': \'20+\', \'text\': \'You may discard any amount of basic Fire Energy or any amount of basic Lightning Energy from this Pokémon. This attack does 80 more damage for each card you discarded in this way.\'}]', 'Silver Tempest Trainer Gallery', '2', 'Rayquaza V', '', '', 'Eighth', '320', 'https://images.pokemoncard.io/images/swsh12tg/swsh12tg-TG29.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Rayquaza VMAX', '384', 'TPCI', 'Rare Secret', 'E', '11/11/2022', '', 'Colorless, Colorless', '[\'VMAX rule: When your Pokémon VMAX is Knocked Out, your opponent takes 3 Prize cards.\']', 'Sword & Shield', 'TG29', 'VMAX, Rapid Strike', 'Pokémon', 'Dragon', ''),
('swsh12tg-TG30', '[{\'name\': \'Skyscraper\', \'text\': \"Prevent all damage done to this Pokémon by attacks from your opponent\'s Pokémon that have Special Energy attached.\", \'type\': \'Ability\'}]', '', 'PLANETA Mochizuki', '[{\'name\': \'G-Max Pulverization\', \'cost\': [\'Fighting\', \'Metal\', \'Metal\'], \'convertedEnergyCost\': 3, \'damage\': \'220\', \'text\': \"This attack\'s damage isn\'t affected by any effects on your opponent\'s Active Pokémon.\"}]', 'Silver Tempest Trainer Gallery', '3', 'Duraludon V', '', '', 'Eighth', '330', 'https://images.pokemoncard.io/images/swsh12tg/swsh12tg-TG30.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Duraludon VMAX', '884', 'TPCI', 'Rare Secret', 'E', '11/11/2022', '', 'Colorless, Colorless, Colorless', '[\'VMAX rule: When your Pokémon VMAX is Knocked Out, your opponent takes 3 Prize cards.\']', 'Sword & Shield', 'TG30', 'VMAX, Single Strike', 'Pokémon', 'Dragon', ''),
('swsh2-1', '[{\'name\': \'Adaptive Evolution\', \'text\': \'This Pokémon can evolve during your first turn or the turn you play it.\', \'type\': \'Ability\'}]', '', 'Uta', '[{\'name\': \'Gnaw\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'\'}]', 'Rebel Clash', '1', '', 'Metapod', 'For protection, it releases a horrible stench from the antenna on its head to drive away enemies.', 'Eighth', '50', 'https://images.pokemoncard.io/images/swsh2/swsh2-1.png', 'unlimited: Legal, expanded: Legal', '', 'Caterpie', '10', 'TPCI', 'Common', 'D', '05/01/2020', '', 'Colorless', '', 'Sword & Shield', '1', 'Basic', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('swsh2-10', '', '', 'Masakazu Fukuda', '[{\'name\': \'Agility\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \"Flip a coin. If heads, during your opponent\'s next turn, prevent all effects of attacks, including damage, done to this Pokémon.\"}]', 'Rebel Clash', '1', '', 'Masquerain', 'It lives in ponds and marshes that feature lots of plant life. It often fights with Dewpider, whose habitat and diet are similar.', 'Eighth', '50', 'https://images.pokemoncard.io/images/swsh2/swsh2-10.png', 'unlimited: Legal, expanded: Legal', '', 'Surskit', '283', 'TPCI', 'Common', 'D', '05/01/2020', '', 'Colorless', '', 'Sword & Shield', '10', 'Basic', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('swsh2-100', '[{\'name\': \'Submerge\', \'text\': \"As long as this Pokémon is on your Bench, prevent all damage done to this Pokémon by attacks (both yours and your opponent\'s).\", \'type\': \'Ability\'}]', '', 'kawayoo', '[{\'name\': \'Earthquake\', \'cost\': [\'Fighting\', \'Fighting\'], \'convertedEnergyCost\': 2, \'damage\': \'140\', \'text\': \"This attack also does 20 damage to each of your Benched Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'Rebel Clash', '3', 'Barboach', '', 'It makes its nest at the bottom of swamps. It will eat anything—if it is alive, Whiscash will eat it.', 'Eighth', '140', 'https://images.pokemoncard.io/images/swsh2/swsh2-100.png', 'unlimited: Legal, expanded: Legal', '', 'Whiscash', '340', 'TPCI', 'Rare', 'D', '05/01/2020', '', 'Colorless, Colorless, Colorless', '', 'Sword & Shield', '100', 'Stage 1', 'Pokémon', 'Fighting', 'type: Grass, value: ×2'),
('swsh2-101', '', '', 'Akira Komayama', '[{\'name\': \'Reckless Charge\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'50\', \'text\': \'This Pokémon also does 30 damage to itself.\'}]', 'Rebel Clash', '2', '', 'Runerigus', 'A clay slab with cursed engravings took possession of a Yamask. The slab is said to be absorbing the Yamasks dark power.', 'Eighth', '70', 'https://images.pokemoncard.io/images/swsh2/swsh2-101.png', 'unlimited: Legal, expanded: Legal', '', 'Galarian Yamask', '562', 'TPCI', 'Common', 'D', '05/01/2020', '', 'Colorless, Colorless', '', 'Sword & Shield', '101', 'Basic', 'Pokémon', 'Fighting', 'type: Grass, value: ×2'),
('swsh2-102', '', '', 'TOKIYA', '[{\'name\': \'Spreading Spite\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'\', \'text\': \"For each damage counter on this Galarian Runerigus, put 2 damage counters on your opponent\'s Pokémon in any way you like.\"}, {\'name\': \'Mad Hammer\', \'cost\': [\'Fighting\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'120\', \'text\': \'This Pokémon also does 30 damage to itself.\'}]', 'Rebel Clash', '2', 'Galarian Yamask', '', 'A powerful curse was woven into an ancient painting. After absorbing the spirit of a Yamask, the painting began to move.', 'Eighth', '100', 'https://images.pokemoncard.io/images/swsh2/swsh2-102.png', 'unlimited: Legal, expanded: Legal', '', 'Galarian Runerigus', '867', 'TPCI', 'Rare', 'D', '05/01/2020', '', 'Colorless, Colorless', '', 'Sword & Shield', '102', 'Stage 1', 'Pokémon', 'Fighting', 'type: Grass, value: ×2'),
('swsh2-103', '', '', 'Saya Tsuruta', '[{\'name\': \'Dual Chop\', \'cost\': [\'Fighting\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50×\', \'text\': \'Flip 2 coins. This attack does 50 damage for each heads.\'}]', 'Rebel Clash', '2', '', 'Barbaracle', 'After two Binacle find a suitably sized rock, they adhere themselves to it and live together. They cooperate to gather food during high tide.', 'Eighth', '80', 'https://images.pokemoncard.io/images/swsh2/swsh2-103.png', 'unlimited: Legal, expanded: Legal', '', 'Binacle', '688', 'TPCI', 'Common', 'D', '05/01/2020', '', 'Colorless, Colorless', '', 'Sword & Shield', '103', 'Basic', 'Pokémon', 'Fighting', 'type: Grass, value: ×2'),
('swsh2-104', '', '', 'Anesaki Dynamic', '[{\'name\': \'Rock Hurl\', \'cost\': [\'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'50\', \'text\': \"This attack\'s damage isn\'t affected by Resistance.\"}, {\'name\': \'Hand Press\', \'cost\': [\'Fighting\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'80+\', \'text\': \'If you have more cards in your hand than your opponent, this attack does 80 more damage.\'}]', 'Rebel Clash', '3', 'Binacle', '', 'Seven Binacle come together to form one Barbaracle. The Binacle that serves as the head gives orders to those serving as the limbs.', 'Eighth', '120', 'https://images.pokemoncard.io/images/swsh2/swsh2-104.png', 'unlimited: Legal, expanded: Legal', '', 'Barbaracle', '689', 'TPCI', 'Rare', 'D', '05/01/2020', '', 'Colorless, Colorless, Colorless', '', 'Sword & Shield', '104', 'Stage 1', 'Pokémon', 'Fighting', 'type: Grass, value: ×2'),
('swsh2-105', '', '', 'Misa Tsutsui', '[{\'name\': \'Ram\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'\'}]', 'Rebel Clash', '2', '', 'Carkol', 'Most of its body has the same composition as coal. Fittingly, this Pokémon was first discovered in coal mines about 400 years ago.', 'Eighth', '70', 'https://images.pokemoncard.io/images/swsh2/swsh2-105.png', 'unlimited: Legal, expanded: Legal', '', 'Rolycoly', '837', 'TPCI', 'Common', 'D', '05/01/2020', '', 'Colorless, Colorless', '', 'Sword & Shield', '105', 'Basic', 'Pokémon', 'Fighting', 'type: Grass, value: ×2'),
('swsh2-106', '', '', 'Mitsuhiro Arita', '[{\'name\': \'Ram\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'\'}, {\'name\': \'Heat Crash\', \'cost\': [\'Fighting\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60\', \'text\': \'\'}]', 'Rebel Clash', '3', 'Rolycoly', 'Coalossal', 'It forms coal inside its body. Coal dropped by this Pokémon once helped fuel the lives of people in the Galar region.', 'Eighth', '100', 'https://images.pokemoncard.io/images/swsh2/swsh2-106.png', 'unlimited: Legal, expanded: Legal', '', 'Carkol', '838', 'TPCI', 'Uncommon', 'D', '05/01/2020', '', 'Colorless, Colorless, Colorless', '', 'Sword & Shield', '106', 'Stage 1', 'Pokémon', 'Fighting', 'type: Grass, value: ×2'),
('swsh2-107', '[{\'name\': \'Tar Generator\', \'text\': \'Once during your turn, you may attach a Fire Energy card, a Fighting Energy card, or 1 of each from your discard pile to your Pokémon in any way you like.\', \'type\': \'Ability\'}]', '', 'Shin Nagasawa', '[{\'name\': \'Flaming Avalanche\', \'cost\': [\'Fighting\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'130\', \'text\': \'\'}]', 'Rebel Clash', '4', 'Carkol', '', 'Its usually peaceful, but the vandalism of mines enrages it. Offenders will be incinerated with flames that reach 2,700 degrees Fahrenheit.', 'Eighth', '160', 'https://images.pokemoncard.io/images/swsh2/swsh2-107.png', 'unlimited: Legal, expanded: Legal', '', 'Coalossal', '839', 'TPCI', 'Rare Holo', 'D', '05/01/2020', '', 'Colorless, Colorless, Colorless, Colorless', '', 'Sword & Shield', '107', 'Stage 2', 'Pokémon', 'Fighting', 'type: Grass, value: ×2'),
('swsh2-108', '', '', 'aky CG Works', '[{\'name\': \'Sand Eater\', \'cost\': [\'Fighting\'], \'convertedEnergyCost\': 1, \'damage\': \'30\', \'text\': \'Attach a Fighting Energy card from your discard pile to this Pokémon.\'}, {\'name\': \'Sand Breath\', \'cost\': [\'Fighting\', \'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'220\', \'text\': \'Discard 2 Energy from this Pokémon.\'}]', 'Rebel Clash', '3', '', '', '', 'Eighth', '220', 'https://images.pokemoncard.io/images/swsh2/swsh2-108.png', 'unlimited: Legal, expanded: Legal', '', 'Sandaconda V', '844', 'TPCI', 'Rare Holo V', 'D', '05/01/2020', '', 'Colorless, Colorless, Colorless', '[\'V rule: When your Pokémon V is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sword & Shield', '108', 'Basic, V', 'Pokémon', 'Fighting', 'type: Grass, value: ×2'),
('swsh2-109', '', '', 'Misa Tsutsui', '[{\'name\': \'Call for Family\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Search your deck for up to 2 Basic Pokémon and put them onto your Bench. Then, shuffle your deck.\'}, {\'name\': \'Team Attack\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30×\', \'text\': \'This attack does 30 damage for each of your Benched Pokémon that has \"Falinks\" in its name.\'}]', 'Rebel Clash', '1', '', '', 'Five of them are troopers, and one is the brass. The brasss orders are absolute.', 'Eighth', '90', 'https://images.pokemoncard.io/images/swsh2/swsh2-109.png', 'unlimited: Legal, expanded: Legal', '', 'Falinks', '870', 'TPCI', 'Uncommon', 'D', '05/01/2020', '', 'Colorless', '', 'Sword & Shield', '109', 'Basic', 'Pokémon', 'Fighting', 'type: Psychic, value: ×2'),
('swsh2-11', '', '', 'chibi', '[{\'name\': \'Threatening Pattern\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'30\', \'text\': \"During your opponent\'s next turn, Energy can\'t be attached from your opponent\'s hand to the Defending Pokémon.\"}, {\'name\': \'U-turn\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'40\', \'text\': \'Switch this Pokémon with 1 of your Benched Pokémon.\'}]', 'Rebel Clash', '1', 'Surskit', '', 'Its thin, winglike antennae are highly absorbent. It waits out rainy days in tree hollows.', 'Eighth', '90', 'https://images.pokemoncard.io/images/swsh2/swsh2-11.png', 'unlimited: Legal, expanded: Legal', '', 'Masquerain', '284', 'TPCI', 'Uncommon', 'D', '05/01/2020', '', 'Colorless', '', 'Sword & Shield', '11', 'Stage 1', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('swsh2-110', '[{\'name\': \'Iron Defense Formation\', \'text\': \'All of your Pokémon that have \"Falinks\" in their name take 20 less damage from your opponent\\\'s attacks (after applying Weakness and Resistance).\', \'type\': \'Ability\'}]', '', 'aky CG Works', '[{\'name\': \'Giga Impact\', \'cost\': [\'Fighting\', \'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'210\', \'text\': \"During your next turn, this Pokémon can\'t attack.\"}]', 'Rebel Clash', '2', '', '', '', 'Eighth', '160', 'https://images.pokemoncard.io/images/swsh2/swsh2-110.png', 'unlimited: Legal, expanded: Legal', '', 'Falinks V', '870', 'TPCI', 'Rare Holo V', 'D', '05/01/2020', '', 'Colorless, Colorless', '[\'V rule: When your Pokémon V is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sword & Shield', '110', 'Basic, V', 'Pokémon', 'Fighting', 'type: Psychic, value: ×2'),
('swsh2-111', '', '', 'Kouki Saitou', '[{\'name\': \'Mega Kick\', \'cost\': [\'Fighting\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'80\', \'text\': \'\'}, {\'name\': \'Power Press\', \'cost\': [\'Fighting\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'120+\', \'text\': \"If this Pokémon has at least 1 extra Energy attached (in addition to this attack\'s cost), this attack does 60 more damage.\"}]', 'Rebel Clash', '4', '', '', 'It stands in grasslands, watching the suns descent from zenith to horizon. This Pokémon has a talent for delivering dynamic kicks.', 'Eighth', '140', 'https://images.pokemoncard.io/images/swsh2/swsh2-111.png', 'unlimited: Legal, expanded: Legal', '', 'Stonjourner', '874', 'TPCI', 'Rare Holo', 'D', '05/01/2020', '', 'Colorless, Colorless, Colorless, Colorless', '', 'Sword & Shield', '111', 'Basic', 'Pokémon', 'Fighting', 'type: Grass, value: ×2'),
('swsh2-112', '', '', 'Kyoko Umemoto', '[{\'name\': \'Suffocating Gas\', \'cost\': [\'Darkness\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'\'}]', 'Rebel Clash', '1', '', 'Weezing', 'Its body is full of poisonous gas. It floats into garbage dumps, seeking out the fumes of raw, rotting trash.', 'Eighth', '70', 'https://images.pokemoncard.io/images/swsh2/swsh2-112.png', 'unlimited: Legal, expanded: Legal', '', 'Koffing', '109', 'TPCI', 'Common', 'D', '05/01/2020', '', 'Colorless', '', 'Sword & Shield', '112', 'Basic', 'Pokémon', 'Darkness', 'type: Fighting, value: ×2'),
('swsh2-113', '[{\'name\': \'Neutralizing Gas\', \'text\': \"As long as this Pokémon is in the Active Spot, your opponent\'s Pokémon in play have no Abilities, except for Neutralizing Gas.\", \'type\': \'Ability\'}]', '', 'Mitsuhiro Arita', '[{\'name\': \'Severe Poison\', \'cost\': [\'Darkness\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Your opponent\'s Active Pokémon is now Poisoned. Put 4 damage counters instead of 1 on that Pokémon during Pokémon Checkup.\"}]', 'Rebel Clash', '3', 'Koffing', '', 'This Pokémon consumes particles that contaminate the air. Instead of leaving droppings, it expels clean air.', 'Eighth', '130', 'https://images.pokemoncard.io/images/swsh2/swsh2-113.png', 'unlimited: Legal, expanded: Legal', '', 'Galarian Weezing', '110', 'TPCI', 'Rare Holo', 'D', '05/01/2020', '', 'Colorless, Colorless, Colorless', '', 'Sword & Shield', '113', 'Stage 1', 'Pokémon', 'Darkness', 'type: Fighting, value: ×2'),
('swsh2-114', '', '', 'Shigenori Negishi', '[{\'name\': \'Poison Gas\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'10\', \'text\': \"Your opponent\'s Active Pokémon is now Poisoned.\"}]', 'Rebel Clash', '2', '', 'Skuntank', 'From its rear, it sprays a foul-smelling liquid at opponents. It aims for their faces, and it can hit them from over 16 feet away.', 'Eighth', '70', 'https://images.pokemoncard.io/images/swsh2/swsh2-114.png', 'unlimited: Legal, expanded: Legal', '', 'Stunky', '434', 'TPCI', 'Common', 'D', '05/01/2020', '', 'Colorless, Colorless', '', 'Sword & Shield', '114', 'Basic', 'Pokémon', 'Darkness', 'type: Fighting, value: ×2'),
('swsh2-115', '', '', 'sowsow', '[{\'name\': \'Slash\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'50\', \'text\': \'\'}, {\'name\': \'Poison Ring\', \'cost\': [\'Darkness\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'80\', \'text\': \"Your opponent\'s Active Pokémon is now Poisoned. During your opponent\'s next turn, the Defending Pokémon can\'t retreat.\"}]', 'Rebel Clash', '3', 'Stunky', '', 'In its belly, it reserves stinky fluid that it shoots from its tail during battle. As this Pokémons diet varies, so does the stench of its fluid.', 'Eighth', '120', 'https://images.pokemoncard.io/images/swsh2/swsh2-115.png', 'unlimited: Legal, expanded: Legal', '', 'Skuntank', '435', 'TPCI', 'Uncommon', 'D', '05/01/2020', '', 'Colorless, Colorless, Colorless', '', 'Sword & Shield', '115', 'Stage 1', 'Pokémon', 'Darkness', 'type: Fighting, value: ×2'),
('swsh2-116', '', '', 'Tomokazu Komiya', '[{\'name\': \'Splitting Spite\', \'cost\': [\'Darkness\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Discard the top card of each player\'s deck.\"}, {\'name\': \'Dripping Grudge\', \'cost\': [\'Darkness\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'\', \'text\': \"Put 1 damage counter on your opponent\'s Active Pokémon for each Pokémon in your discard pile.\"}]', 'Rebel Clash', '2', '', '', 'It was bound to a fissure in an Odd Keystone as punishment for misdeeds 500 years ago.', 'Eighth', '60', 'https://images.pokemoncard.io/images/swsh2/swsh2-116.png', 'unlimited: Legal, expanded: Legal', '', 'Spiritomb', '442', 'TPCI', 'Rare', 'D', '05/01/2020', '', 'Colorless, Colorless', '', 'Sword & Shield', '116', 'Basic', 'Pokémon', 'Darkness', 'type: Grass, value: ×2');
INSERT INTO `cards` (`id`, `abilities`, `ancient_trait`, `artist`, `attacks`, `card_set`, `converted`, `evolves_from`, `evolves_to`, `flavor_text`, `generation`, `hp`, `img`, `legalities`, `level`, `name`, `national_pokedex_numbers`, `publisher`, `rarity`, `regulation_mark`, `release_date`, `resistances`, `retreat_cost`, `rules`, `series`, `set_num`, `subtypes`, `supertype`, `types`, `weakness`) VALUES
('swsh2-117', '', '', 'HYOGONOSUKE', '[{\'name\': \'Venoshock\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20+\', \'text\': \"If your opponent\'s Active Pokémon is Poisoned, this attack does 50 more damage.\"}]', 'Rebel Clash', '1', '', 'Garbodor', 'Its favorite places are unsanitary ones. If you leave trash lying around, you could even find one of these Pokémon living in your room.', 'Eighth', '60', 'https://images.pokemoncard.io/images/swsh2/swsh2-117.png', 'unlimited: Legal, expanded: Legal', '', 'Trubbish', '568', 'TPCI', 'Common', 'D', '05/01/2020', '', 'Colorless', '', 'Sword & Shield', '117', 'Basic', 'Pokémon', 'Darkness', 'type: Fighting, value: ×2'),
('swsh2-118', '[{\'name\': \'Poisonous Puddle\', \'text\': \"Once during your turn, if a Stadium is in play, you may make your opponent\'s Active Pokémon Poisoned.\", \'type\': \'Ability\'}]', '', 'AKIRA EGAWA', '[{\'name\': \'Sludge Bomb\', \'cost\': [\'Darkness\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'80\', \'text\': \'\'}]', 'Rebel Clash', '2', 'Trubbish', '', 'This Pokémon eats trash, which turns into poison inside its body. The main component of the poison depends on what sort of trash was eaten.', 'Eighth', '120', 'https://images.pokemoncard.io/images/swsh2/swsh2-118.png', 'unlimited: Legal, expanded: Legal', '', 'Garbodor', '569', 'TPCI', 'Rare', 'D', '05/01/2020', '', 'Colorless, Colorless', '', 'Sword & Shield', '118', 'Stage 1', 'Pokémon', 'Darkness', 'type: Fighting, value: ×2'),
('swsh2-119', '', '', 'Shibuzoh.', '[{\'name\': \'Pluck\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \"Before doing damage, discard all Pokémon Tools from your opponent\'s Active Pokémon.\"}]', 'Rebel Clash', '1', '', 'Mandibuzz', 'It wears a bone to protect its rear. It often squabbles with others of its kind over particularly comfy bones.', 'Eighth', '60', 'https://images.pokemoncard.io/images/swsh2/swsh2-119.png', 'unlimited: Legal, expanded: Legal', '', 'Vullaby', '629', 'TPCI', 'Common', 'D', '05/01/2020', 'type: Fighting, value: -30', 'Colorless', '', 'Sword & Shield', '119', 'Basic', 'Pokémon', 'Darkness', 'type: Lightning, value: ×2'),
('swsh2-12', '', '', 'Shibuzoh.', '[{\'name\': \'Beat\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'\'}, {\'name\': \'Razor Leaf\', \'cost\': [\'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50\', \'text\': \'\'}]', 'Rebel Clash', '3', '', 'Abomasnow', 'It lives on snowy mountains. It sinks its legs into the snow to absorb water and keep its own temperature down.', 'Eighth', '90', 'https://images.pokemoncard.io/images/swsh2/swsh2-12.png', 'unlimited: Legal, expanded: Legal', '', 'Snover', '459', 'TPCI', 'Common', 'D', '05/01/2020', '', 'Colorless, Colorless, Colorless', '', 'Sword & Shield', '12', 'Basic', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
