('swsh2-154', '', '', 'nagimiso', '', 'Rebel Clash', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh2/swsh2-154.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Bosss Orders', '', 'TPCI', 'Rare Holo', 'D', '05/01/2020', '', '', '[\"Switch 1 of your opponent\'s Benched Pokémon with their Active Pokémon.\", \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '154', 'Supporter', 'Trainer', '', ''),
('swsh2-155', '', '', 'Toyste Beach', '', 'Rebel Clash', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh2/swsh2-155.png', 'unlimited: Legal, expanded: Legal', '', 'Burning Scarf', '', 'TPCI', 'Uncommon', 'D', '05/01/2020', '', '', '[\"Attach a Pokémon Tool to 1 of your Pokémon that doesn\'t already have a Pokémon Tool attached.\", \"If the Fire Pokémon this card is attached to is in the Active Spot and is damaged by an opponent\'s attack (even if it is Knocked Out), the Attacking Pokémon is now Burned.\", \'You may play any number of Item cards during your turn.\']', 'Sword & Shield', '155', 'Pokémon Tool', 'Trainer', '', ''),
('swsh2-156', '', '', 'sadaji', '', 'Rebel Clash', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh2/swsh2-156.png', 'unlimited: Legal, expanded: Legal', '', 'Capacious Bucket', '', 'TPCI', 'Uncommon', 'D', '05/01/2020', '', '', '[\'Search your deck for up to 2 Water Energy cards, reveal them, and put them into your hand. Then, shuffle your deck.\', \'You may play any number of Item cards during your turn.\']', 'Sword & Shield', '156', 'Item', 'Trainer', '', ''),
('swsh2-157', '', '', 'Toyste Beach', '', 'Rebel Clash', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh2/swsh2-157.png', 'unlimited: Legal, expanded: Legal', '', 'Cursed Shovel', '', 'TPCI', 'Uncommon', 'D', '05/01/2020', '', '', '[\"Attach a Pokémon Tool to 1 of your Pokémon that doesn\'t already have a Pokémon Tool attached.\", \"If the Pokémon this card is attached to is Knocked Out by damage from an opponent\'s attack, discard the top 2 cards of your opponent\'s deck.\", \'You may play any number of Item cards during your turn.\']', 'Sword & Shield', '157', 'Pokémon Tool', 'Trainer', '', ''),
('swsh2-158', '', '', 'Hitoshi Ariga', '', 'Rebel Clash', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh2/swsh2-158.png', 'unlimited: Legal, expanded: Legal', '', 'Dan', '', 'TPCI', 'Uncommon', 'D', '05/01/2020', '', '', '[\'Draw 2 cards. You and your opponent play Rock-Paper-Scissors until someone wins. If you win, draw 2 more cards.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '158', 'Supporter', 'Trainer', '', ''),
('swsh2-159', '', '', 'Yoshinobu Saito', '', 'Rebel Clash', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh2/swsh2-159.png', 'unlimited: Legal, expanded: Legal', '', 'Full Heal', '', 'TPCI', 'Uncommon', 'D', '05/01/2020', '', '', '[\'Your Active Pokémon recovers from all Special Conditions.\', \'You may play any number of Item cards during your turn.\']', 'Sword & Shield', '159', 'Item', 'Trainer', '', ''),
('swsh2-16', '', '', 'Tomokazu Komiya', '[{\'name\': \'Gnaw\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'\'}]', 'Rebel Clash', '1', '', 'Charjabug', 'Its natural enemies, like Rookidee, may flee rather than risk getting caught in its large mandibles that can snap thick tree branches.', 'Eighth', '60', 'https://images.pokemoncard.io/images/swsh2/swsh2-16.png', 'unlimited: Legal, expanded: Legal', '', 'Grubbin', '736', 'TPCI', 'Common', 'D', '05/01/2020', '', 'Colorless', '', 'Sword & Shield', '16', 'Basic', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('swsh2-160', '', '', '5ban Graphics', '', 'Rebel Clash', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh2/swsh2-160.png', 'unlimited: Legal, expanded: Legal', '', 'Galar Mine', '', 'TPCI', 'Uncommon', 'D', '05/01/2020', '', '', '[\'The Retreat Cost of both Active Pokémon is ColorlessColorless more.\', \"This Stadium stays in play when you play it. Discard it if another Stadium comes into play. If a Stadium with the same name is in play, you can\'t play this card.\"]', 'Sword & Shield', '160', 'Stadium', 'Trainer', '', ''),
('swsh2-161', '', '', 'take', '', 'Rebel Clash', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh2/swsh2-161.png', 'unlimited: Legal, expanded: Legal', '', 'Milo', '', 'TPCI', 'Uncommon', 'D', '05/01/2020', '', '', '[\'Discard up to 2 cards from your hand, and draw 2 cards for each card you discarded in this way.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '161', 'Supporter', 'Trainer', '', ''),
('swsh2-162', '', '', 'sadaji', '', 'Rebel Clash', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh2/swsh2-162.png', 'unlimited: Legal, expanded: Legal', '', 'Nugget', '', 'TPCI', 'Uncommon', 'D', '05/01/2020', '', '', '[\'You can play this card only if you drew it from your deck at the beginning of your turn, before you put it into your hand.\', \'Draw 3 cards.\', \'You may play any number of Item cards during your turn.\']', 'Sword & Shield', '162', 'Item', 'Trainer', '', ''),
('swsh2-163', '', '', 'Yusuke Ohmura', '', 'Rebel Clash', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh2/swsh2-163.png', 'unlimited: Legal, expanded: Legal', '', 'Oleana', '', 'TPCI', 'Uncommon', 'D', '05/01/2020', '', '', '[\'You can play this card only if you discard 2 other cards from your hand.\', \'Your opponent reveals their hand. Put a Trainer card you find there on the bottom of their deck.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '163', 'Supporter', 'Trainer', '', ''),
('swsh2-164', '', '', 'Studio Bora Inc.', '', 'Rebel Clash', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh2/swsh2-164.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Poké Ball', '', 'TPCI', 'Uncommon', 'D', '05/01/2020', '', '', '[\'Flip a coin. If heads, search your deck for a Pokémon, reveal it, and put it into your hand. Then, shuffle your deck.\', \'You may play any number of Item cards during your turn.\']', 'Sword & Shield', '164', 'Item', 'Trainer', '', ''),
('swsh2-165', '', '', 'Ryo Ueda', '', 'Rebel Clash', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh2/swsh2-165.png', 'unlimited: Legal, expanded: Legal', '', 'Scoop Up Net', '', 'TPCI', 'Uncommon', 'D', '05/01/2020', '', '', '[\"Put 1 of your Pokémon that isn\'t a Pokémon V or a Pokémon-GX into your hand. (Discard all attached cards.)\", \'You may play any number of Item cards during your turn.\']', 'Sword & Shield', '165', 'Item', 'Trainer', '', ''),
('swsh2-166', '', '', 'Hideki Ishikawa', '', 'Rebel Clash', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh2/swsh2-166.png', 'unlimited: Legal, expanded: Legal', '', 'Skyla', '', 'TPCI', 'Uncommon', 'D', '05/01/2020', '', '', '[\'Search your deck for a Trainer card, reveal it, and put it into your hand. Then, shuffle your deck.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '166', 'Supporter', 'Trainer', '', ''),
('swsh2-167', '', '', 'Yusuke Ohmura', '', 'Rebel Clash', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh2/swsh2-167.png', 'unlimited: Legal, expanded: Legal', '', 'Sonia', '', 'TPCI', 'Uncommon', 'D', '05/01/2020', '', '', '[\'Search your deck for up to 2 Basic Pokémon or up to 2 basic Energy cards, reveal them, and put them into your hand. Then, shuffle your deck.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '167', 'Supporter', 'Trainer', '', ''),
('swsh2-168', '', '', 'Studio Bora Inc.', '', 'Rebel Clash', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh2/swsh2-168.png', 'unlimited: Legal, expanded: Legal', '', 'Tool Scrapper', '', 'TPCI', 'Uncommon', 'D', '05/01/2020', '', '', '[\"Choose up to 2 Pokémon Tools attached to Pokémon (yours or your opponent\'s) and discard them.\", \'You may play any number of Item cards during your turn.\']', 'Sword & Shield', '168', 'Item', 'Trainer', '', ''),
('swsh2-169', '', '', '5ban Graphics', '', 'Rebel Clash', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh2/swsh2-169.png', 'unlimited: Legal, expanded: Legal', '', 'Training Court', '', 'TPCI', 'Uncommon', 'D', '05/01/2020', '', '', '[\"Once during each player\'s turn, that player may put a basic Energy card from their discard pile into their hand.\", \"This Stadium stays in play when you play it. Discard it if another Stadium comes into play. If a Stadium with the same name is in play, you can\'t play this card.\"]', 'Sword & Shield', '169', 'Stadium', 'Trainer', '', ''),
('swsh2-17', '', '', '5ban Graphics', '[{\'name\': \'Forest Feast\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Search your deck for up to 2 Basic Grass Pokémon and put them onto your Bench. Then, shuffle your deck.\'}, {\'name\': \'Wood Hammer\', \'cost\': [\'Grass\', \'Grass\', \'Grass\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'220\', \'text\': \'This Pokémon also does 30 damage to itself.\'}]', 'Rebel Clash', '3', '', '', '', 'Eighth', '220', 'https://images.pokemoncard.io/images/swsh2/swsh2-17.png', 'unlimited: Legal, expanded: Legal', '', 'Rillaboom V', '812', 'TPCI', 'Rare Holo V', 'D', '05/01/2020', '', 'Colorless, Colorless, Colorless', '[\'V rule: When your Pokémon V is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sword & Shield', '17', 'Basic, V', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('swsh2-170', '', '', 'aky CG Works', '', 'Rebel Clash', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh2/swsh2-170.png', 'unlimited: Legal, expanded: Legal', '', 'Turffield Stadium', '', 'TPCI', 'Uncommon', 'D', '05/01/2020', '', '', '[\"Once during each player\'s turn, that player may search their deck for an Evolution Grass Pokémon, reveal it, and put it into their hand. Then, that player shuffles their deck.\", \"This Stadium stays in play when you play it. Discard it if another Stadium comes into play. If a Stadium with the same name is in play, you can\'t play this card.\"]', 'Sword & Shield', '170', 'Stadium', 'Trainer', '', ''),
('swsh2-171', '', '', '', '', 'Rebel Clash', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh2/swsh2-171.png', 'unlimited: Legal, expanded: Legal', '', 'Capture Energy', '', 'TPCI', 'Uncommon', 'D', '05/01/2020', '', '', '[\'As long as this card is attached to a Pokémon, it provides Colorless Energy.\', \'When you attach this card from your hand to a Pokémon, search your deck for a Basic Pokémon and put it onto your Bench. Then, shuffle your deck.\']', 'Sword & Shield', '171', 'Special', 'Energy', '', ''),
('swsh2-172', '', '', '', '', 'Rebel Clash', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh2/swsh2-172.png', 'unlimited: Legal, expanded: Legal', '', 'Horror Psychic Energy', '', 'TPCI', 'Uncommon', 'D', '05/01/2020', '', '', '[\'As long as this card is attached to a Pokémon, it provides Psychic Energy.\', \"If the Psychic Pokémon this card is attached to is in the Active Spot and is damaged by an opponent\'s attack (even if it is Knocked Out), put 2 damage counters on the Attacking Pokémon.\"]', 'Sword & Shield', '172', 'Special', 'Energy', '', ''),
('swsh2-173', '', '', '', '', 'Rebel Clash', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh2/swsh2-173.png', 'unlimited: Legal, expanded: Legal', '', 'Speed Lightning Energy', '', 'TPCI', 'Uncommon', 'D', '05/01/2020', '', '', '[\'As long as this card is attached to a Pokémon, it provides Lightning Energy.\', \'When you attach this card from your hand to a Lightning Pokémon, draw 2 cards.\']', 'Sword & Shield', '173', 'Special', 'Energy', '', ''),
