('swsh2-201', '', '', 'Hitoshi Ariga', '', 'Rebel Clash', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh2/swsh2-201.png', 'unlimited: Legal, expanded: Legal', '', 'Milo', '', 'TPCI', 'Rare Rainbow', 'D', '05/01/2020', '', '', '[\'Discard up to 2 cards from your hand, and draw 2 cards for each card you discarded in this way.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '201', 'Supporter', 'Trainer', '', ''),
('swsh2-202', '', '', 'kirisAki', '', 'Rebel Clash', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh2/swsh2-202.png', 'unlimited: Legal, expanded: Legal', '', 'Oleana', '', 'TPCI', 'Rare Rainbow', 'D', '05/01/2020', '', '', '[\'You can play this card only if you discard 2 other cards from your hand.\', \'Your opponent reveals their hand. Put a Trainer card you find there on the bottom of their deck.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '202', 'Supporter', 'Trainer', '', ''),
('swsh2-203', '', '', 'Naoki Saito', '', 'Rebel Clash', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh2/swsh2-203.png', 'unlimited: Legal, expanded: Legal', '', 'Sonia', '', 'TPCI', 'Rare Rainbow', 'D', '05/01/2020', '', '', '[\'Search your deck for up to 2 Basic Pokémon or up to 2 basic Energy cards, reveal them, and put them into your hand. Then, shuffle your deck.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '203', 'Supporter', 'Trainer', '', ''),
('swsh2-204', '[{\'name\': \'Ice Dance\', \'text\': \'As often as you like during your turn, you may attach a Water Energy card from your hand to 1 of your Benched Water Pokémon.\', \'type\': \'Ability\'}]', '', 'PLANETA Tsuji', '[{\'name\': \'Aurora Beam\', \'cost\': [\'Water\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'\'}]', 'Rebel Clash', '2', 'Snom', '', 'It shows no mercy to any who desecrate fields and mountains. It will fly around on its icy wings, causing a blizzard to chase offenders away.', 'Eighth', '90', 'https://images.pokemoncard.io/images/swsh2/swsh2-204.png', 'unlimited: Legal, expanded: Legal', '', 'Frosmoth', '873', 'TPCI', 'Rare Secret', 'D', '05/01/2020', '', 'Colorless, Colorless', '', 'Sword & Shield', '204', 'Stage 1', 'Pokémon', 'Water', 'type: Metal, value: ×2'),
('swsh2-205', '[{\'name\': \'Steely Spirit\', \'text\': \"Your Metal Pokémon\'s attacks do 20 more damage to your opponent\'s Active Pokémon (before applying Weakness and Resistance).\", \'type\': \'Ability\'}]', '', 'PLANETA Tsuji', '[{\'name\': \'Metal Claw\', \'cost\': [\'Metal\', \'Metal\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'70\', \'text\': \'\'}]', 'Rebel Clash', '2', 'Galarian Meowth', '', 'What appears to be an iron helmet is actually hardened hair. This Pokémon lives for the thrill of battle.', 'Eighth', '120', 'https://images.pokemoncard.io/images/swsh2/swsh2-205.png', 'unlimited: Legal, expanded: Legal', '', 'Galarian Perrserker', '863', 'TPCI', 'Rare Secret', 'D', '05/01/2020', 'type: Grass, value: -30', 'Colorless, Colorless', '', 'Sword & Shield', '205', 'Stage 1', 'Pokémon', 'Metal', 'type: Fire, value: ×2'),
('swsh2-206', '', '', 'inose yukie', '', 'Rebel Clash', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh2/swsh2-206.png', 'unlimited: Legal, expanded: Legal', '', 'Big Charm', '', 'TPCI', 'Rare Secret', 'D', '05/01/2020', '', '', '[\"Attach a Pokémon Tool to 1 of your Pokémon that doesn\'t already have a Pokémon Tool attached.\", \'The Pokémon this card is attached to gets +30 HP.\', \'You may play any number of Item cards during your turn.\']', 'Sword & Shield', '206', 'Pokémon Tool', 'Trainer', '', ''),
('swsh2-207', '', '', 'Ryo Ueda', '', 'Rebel Clash', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh2/swsh2-207.png', 'unlimited: Legal, expanded: Legal', '', 'Scoop Up Net', '', 'TPCI', 'Rare Secret', 'D', '05/01/2020', '', '', '[\"Put 1 of your Pokémon that isn\'t a Pokémon V or a Pokémon-GX into your hand. (Discard all attached cards.)\", \'You may play any number of Item cards during your turn.\']', 'Sword & Shield', '207', 'Item', 'Trainer', '', ''),
('swsh2-208', '', '', 'Studio Bora Inc.', '', 'Rebel Clash', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh2/swsh2-208.png', 'unlimited: Legal, expanded: Legal', '', 'Tool Scrapper', '', 'TPCI', 'Rare Secret', 'D', '05/01/2020', '', '', '[\"Choose up to 2 Pokémon Tools attached to Pokémon (yours or your opponent\'s) and discard them.\", \'You may play any number of Item cards during your turn.\']', 'Sword & Shield', '208', 'Item', 'Trainer', '', ''),
('swsh2-209', '', '', '', '', 'Rebel Clash', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh2/swsh2-209.png', 'unlimited: Legal, expanded: Legal', '', 'Twin Energy', '', 'TPCI', 'Rare Secret', 'D', '05/01/2020', '', '', '[\"As long as this card is attached to a Pokémon that isn\'t a Pokémon V or a Pokémon-GX, it provides ColorlessColorless Energy.\", \'If this card is attached to a Pokémon V or a Pokémon-GX, it provides Colorless Energy instead.\']', 'Sword & Shield', '209', 'Special', 'Energy', '', ''),
('swsh2-21', '', '', 'Kagemaru Himeno', '[{\'name\': \'Withdraw\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Flip a coin. If heads, during your opponent\'s next turn, prevent all damage done to this Pokémon by attacks.\"}]', 'Rebel Clash', '1', '', 'Flapple', 'It spends its entire life inside an apple. It hides from its natural enemies, bird Pokémon, by pretending its just an apple and nothing more.', 'Eighth', '40', 'https://images.pokemoncard.io/images/swsh2/swsh2-21.png', 'unlimited: Legal, expanded: Legal', '', 'Applin', '840', 'TPCI', 'Common', 'D', '05/01/2020', '', 'Colorless', '', 'Sword & Shield', '21', 'Basic', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('swsh2-22', '[{\'name\': \'Apple Drop\', \'text\': \"Once during your turn, you may put 2 damage counters on 1 of your opponent\'s Pokémon. If you placed any damage counters in this way, shuffle this Pokémon and all attached cards into your deck.\", \'type\': \'Ability\'}]', '', 'Shin Nagasawa', '[{\'name\': \'Acid Spray\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'60\', \'text\': \"Flip a coin. If heads, discard an Energy from your opponent\'s Active Pokémon.\"}]', 'Rebel Clash', '1', 'Applin', '', 'It ate a sour apple, and that induced its evolution. In its cheeks, it stores an acid capable of causing chemical burns.', 'Eighth', '80', 'https://images.pokemoncard.io/images/swsh2/swsh2-22.png', 'unlimited: Legal, expanded: Legal', '', 'Flapple', '841', 'TPCI', 'Rare Holo', 'D', '05/01/2020', '', 'Colorless', '', 'Sword & Shield', '22', 'Stage 1', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('swsh2-23', '[{\'name\': \'Delicious Aroma\', \'text\': \"Once during your turn, you may flip a coin. If heads, switch 1 of your opponent\'s Benched Basic Pokémon with their Active Pokémon.\", \'type\': \'Ability\'}]', '', 'Akira Komayama', '[{\'name\': \'Solar Beam\', \'cost\': [\'Grass\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'70\', \'text\': \'\'}]', 'Rebel Clash', '3', 'Applin', '', 'Eating a sweet apple caused its evolution. A nectarous scent wafts from its body, luring in the bug Pokémon it preys on.', 'Eighth', '90', 'https://images.pokemoncard.io/images/swsh2/swsh2-23.png', 'unlimited: Legal, expanded: Legal', '', 'Appletun', '842', 'TPCI', 'Rare Holo', 'D', '05/01/2020', '', 'Colorless, Colorless, Colorless', '', 'Sword & Shield', '23', 'Stage 1', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('swsh2-24', '', '', 'sui', '[{\'name\': \'Confuse Ray\', \'cost\': [\'Fire\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Your opponent\'s Active Pokémon is now Confused.\"}, {\'name\': \'Smash Kick\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'\'}]', 'Rebel Clash', '1', '', 'Ninetales', 'While young, it has six gorgeous tails. When it grows, several new tails are sprouted.', 'Eighth', '60', 'https://images.pokemoncard.io/images/swsh2/swsh2-24.png', 'unlimited: Legal, expanded: Legal', '', 'Vulpix', '37', 'TPCI', 'Common', 'D', '05/01/2020', '', 'Colorless', '', 'Sword & Shield', '24', 'Basic', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('swsh2-25', '', '', 'AKIRA EGAWA', '[{\'name\': \'Hex\', \'cost\': [\'Fire\'], \'convertedEnergyCost\': 1, \'damage\': \'30+\', \'text\': \"If your opponent\'s Active Pokémon is affected by a Special Condition, this attack does 90 more damage.\"}, {\'name\': \'Flickering Flames\', \'cost\': [\'Fire\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'90\', \'text\': \"Your opponent\'s Active Pokémon is now Asleep.\"}]', 'Rebel Clash', '1', 'Vulpix', '', 'It is said to live 1,000 years, and each of its tails is loaded with supernatural powers.', 'Eighth', '120', 'https://images.pokemoncard.io/images/swsh2/swsh2-25.png', 'unlimited: Legal, expanded: Legal', '', 'Ninetales', '38', 'TPCI', 'Rare', 'D', '05/01/2020', '', 'Colorless', '', 'Sword & Shield', '25', 'Stage 1', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
