('swsh35-62', '', '', 'Yusuke Ohmura', '', 'Champions Path', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh35/swsh35-62.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Professors Research Professor Magnolia', '', 'TPCI', 'Rare Holo', 'D', '9/25/2020', '', '', '[\'Discard your hand and draw 7 cards.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '62', 'Supporter', 'Trainer', '', ''),
('swsh35-63', '', '', '5ban Graphics', '', 'Champions Path', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh35/swsh35-63.png', 'unlimited: Legal, expanded: Legal', '', 'Rotom Bike', '', 'TPCI', 'Uncommon', 'D', '9/25/2020', '', '', '[\'Draw cards until you have 6 cards in your hand. Your turn ends.\', \'You may play any number of Item cards during your turn.\']', 'Sword & Shield', '63', 'Item', 'Trainer', '', ''),
('swsh35-64', '', '', 'Ryo Ueda', '', 'Champions Path', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh35/swsh35-64.png', 'unlimited: Legal, expanded: Legal', '', 'Rotom Phone', '', 'TPCI', 'Uncommon', 'D', '9/25/2020', '', '', '[\'Look at the top 5 cards of your deck, choose 1 of them, and shuffle the other cards back into your deck. Then, put the card you chose on top of your deck.\', \'You may play any number of Item cards during your turn.\']', 'Sword & Shield', '64', 'Item', 'Trainer', '', ''),
('swsh35-65', '', '', 'Yusuke Ohmura', '', 'Champions Path', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh35/swsh35-65.png', 'unlimited: Legal, expanded: Legal', '', 'Sonia', '', 'TPCI', 'Uncommon', 'D', '9/25/2020', '', '', '[\'Search your deck for up to 2 Basic Pokémon or up to 2 basic Energy cards, reveal them, and put them into your hand. Then, shuffle your deck.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '65', 'Supporter', 'Trainer', '', ''),
('swsh35-66', '', '', 'Ryo Ueda', '', 'Champions Path', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh35/swsh35-66.png', 'unlimited: Legal, expanded: Legal', '', 'Suspicious Food Tin', '', 'TPCI', 'Uncommon', 'D', '9/25/2020', '', '', '[\'Heal 80 damage from 1 of your Pokémon that has at least 1 Psychic Energy attached. If you healed any damage in this way, discard a Psychic Energy from it.\', \'You may play any number of Item cards during your turn.\']', 'Sword & Shield', '66', 'Item', 'Trainer', '', ''),
('swsh35-67', '', '', 'nagimiso', '', 'Champions Path', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh35/swsh35-67.png', 'unlimited: Legal, expanded: Legal', '', 'Team Yell Grunt', '', 'TPCI', 'Uncommon', 'D', '9/25/2020', '', '', '[\"Put an Energy attached to 1 of your opponent\'s Pokémon into their hand.\", \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '67', 'Supporter', 'Trainer', '', ''),
('swsh35-68', '', '', 'aky CG Works', '', 'Champions Path', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh35/swsh35-68.png', 'unlimited: Legal, expanded: Legal', '', 'Turffield Stadium', '', 'TPCI', 'Uncommon', 'D', '9/25/2020', '', '', '[\"Once during each player\'s turn, that player may search their deck for an Evolution Grass Pokémon, reveal it, and put it into their hand. Then, that player shuffles their deck.\", \"This Stadium stays in play when you play it. Discard it if another Stadium comes into play. If a Stadium with the same name is in play, you can\'t play this card.\"]', 'Sword & Shield', '68', 'Stadium', 'Trainer', '', ''),
