('swsh45-4', '', '', 'Uta', '[{\'name\': \'Pierce\', \'cost\': [\'Grass\', \'Grass\'], \'convertedEnergyCost\': 2, \'damage\': \'50\', \'text\': \'\'}]', 'Shining Fates', '2', '', 'Cacturne', 'It prefers harsh environments such as deserts. It can survive for 30 days on water stored in its body.', 'Eighth', '70', 'https://images.pokemoncard.io/images/swsh45/swsh45-4.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Cacnea', '331', 'TPCI', 'Common', 'E', '2/19/2021', '', 'Colorless, Colorless', '', 'Sword & Shield', '4', 'Basic', 'Pokémon', 'Grass', 'type: Fire, value: ×2');
INSERT INTO `cards` (`id`, `abilities`, `ancient_trait`, `artist`, `attacks`, `card_set`, `converted`, `evolves_from`, `evolves_to`, `flavor_text`, `generation`, `hp`, `img`, `legalities`, `level`, `name`, `national_pokedex_numbers`, `publisher`, `rarity`, `regulation_mark`, `release_date`, `resistances`, `retreat_cost`, `rules`, `series`, `set_num`, `subtypes`, `supertype`, `types`, `weakness`) VALUES
('swsh45-40', '', '', 'MAHOU', '[{\'name\': \"Land\'s Pulse\", \'cost\': [\'Fighting\'], \'convertedEnergyCost\': 1, \'damage\': \'10+\', \'text\': \'If a Stadium is in play, this attack does 10 more damage.\'}]', 'Shining Fates', '1', '', 'Vibrava', 'Its nest is a sloped, bowl-like pit in the desert. Once something has fallen in, there is no escape.', 'Eighth', '60', 'https://images.pokemoncard.io/images/swsh45/swsh45-40.png', 'unlimited: Legal, expanded: Legal', '', 'Trapinch', '328', 'TPCI', 'Common', 'D', '2/19/2021', '', 'Colorless', '', 'Sword & Shield', '40', 'Basic', 'Pokémon', 'Fighting', 'type: Grass, value: ×2'),
('swsh45-41', '', '', 'Pani Kobayashi', '[{\'name\': \'Ascension\', \'cost\': [\'Darkness\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Search your deck for a card that evolves from this Pokémon and put it onto this Pokémon to evolve it. Then, shuffle your deck.\'}]', 'Shining Fates', '1', '', 'Weezing', 'Its body is full of poisonous gas. It floats into garbage dumps, seeking out the fumes of raw, rotting trash.', 'Eighth', '60', 'https://images.pokemoncard.io/images/swsh45/swsh45-41.png', 'unlimited: Legal, expanded: Legal', '', 'Koffing', '109', 'TPCI', 'Common', 'D', '2/19/2021', '', 'Colorless', '', 'Sword & Shield', '41', 'Basic', 'Pokémon', 'Darkness', 'type: Fighting, value: ×2'),
('swsh45-42', '[{\'name\': \'Neutralizing Gas\', \'text\': \"As long as this Pokémon is in the Active Spot, your opponent\'s Pokémon in play have no Abilities, except for Neutralizing Gas.\", \'type\': \'Ability\'}]', '', 'Mitsuhiro Arita', '[{\'name\': \'Severe Poison\', \'cost\': [\'Darkness\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Your opponent\'s Active Pokémon is now Poisoned. Put 4 damage counters instead of 1 on that Pokémon during Pokémon Checkup.\"}]', 'Shining Fates', '3', 'Koffing', '', 'This Pokémon consumes particles that contaminate the air. Instead of leaving droppings, it expels clean air.', 'Eighth', '130', 'https://images.pokemoncard.io/images/swsh45/swsh45-42.png', 'unlimited: Legal, expanded: Legal', '', 'Galarian Weezing', '110', 'TPCI', 'Rare Holo', 'D', '2/19/2021', '', 'Colorless, Colorless, Colorless', '', 'Sword & Shield', '42', 'Stage 1', 'Pokémon', 'Darkness', 'type: Fighting, value: ×2'),
('swsh45-43', '', '', 'sowsow', '[{\'name\': \'Hang Down\', \'cost\': [\'Darkness\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'\'}, {\'name\': \'Sting\', \'cost\': [\'Darkness\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'\'}]', 'Shining Fates', '1', '', 'Ariados', 'Although the poison from its fangs isnt that strong, its potent enough to weaken prey that gets caught in its web.', 'Eighth', '60', 'https://images.pokemoncard.io/images/swsh45/swsh45-43.png', 'unlimited: Legal, expanded: Legal', '', 'Spinarak', '167', 'TPCI', 'Common', 'D', '2/19/2021', '', 'Colorless', '', 'Sword & Shield', '43', 'Basic', 'Pokémon', 'Darkness', 'type: Fighting, value: ×2'),
('swsh45-44', '[{\'name\': \'Dark Asset\', \'text\': \"When you play this Pokémon from your hand onto your Bench during your turn, you may draw cards until you have 6 cards in your hand. You can\'t use more than 1 Dark Asset Ability each turn.\", \'type\': \'Ability\'}]', '', 'PLANETA Mochizuki', '[{\'name\': \'Venomous Fang\', \'cost\': [\'Darkness\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'70\', \'text\': \"Your opponent\'s Active Pokémon is now Poisoned.\"}]', 'Shining Fates', '1', '', '', '', 'Eighth', '180', 'https://images.pokemoncard.io/images/swsh45/swsh45-44.png', 'unlimited: Legal, expanded: Legal', '', 'Crobat V', '169', 'TPCI', 'Rare Holo V', 'D', '2/19/2021', '', 'Colorless', '[\'V rule: When your Pokémon V is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sword & Shield', '44', 'Basic, V', 'Pokémon', 'Darkness', 'type: Fighting, value: ×2'),
('swsh45-45', '', '', 'PLANETA Tsuji', '[{\'name\': \'Stealth Poison\', \'cost\': [\'Darkness\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'70\', \'text\': \"Your opponent\'s Active Pokémon is now Poisoned. Switch this Pokémon with 1 of your Benched Pokémon.\"}, {\'name\': \'Max Cutter\', \'cost\': [\'Darkness\', \'Darkness\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'180\', \'text\': \'\'}]', 'Shining Fates', '1', 'Crobat V', '', '', 'Eighth', '300', 'https://images.pokemoncard.io/images/swsh45/swsh45-45.png', 'unlimited: Legal, expanded: Legal', '', 'Crobat VMAX', '169', 'TPCI', 'Rare Holo VMAX', 'D', '2/19/2021', '', 'Colorless', '[\'VMAX rule: When your Pokémon VMAX is Knocked Out, your opponent takes 3 Prize cards.\']', 'Sword & Shield', '45', 'VMAX', 'Pokémon', 'Darkness', 'type: Fighting, value: ×2'),
('swsh45-46', '', '', 'Hasuno', '[{\'name\': \'Amazing Destruction\', \'cost\': [\'Fire\', \'Psychic\', \'Darkness\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 5, \'damage\': \'\', \'text\': \"Your opponent\'s Active Pokémon is Knocked Out.\"}]', 'Shining Fates', '2', '', '', 'When its life comes to an end, it absorbs the life energy of every living thing and turns into a cocoon once more.', 'Eighth', '110', 'https://images.pokemoncard.io/images/swsh45/swsh45-46.png', 'unlimited: Legal, expanded: Legal', '', 'Yveltal', '717', 'TPCI', 'Amazing Rare', 'D', '2/19/2021', 'type: Fighting, value: -30', 'Colorless, Colorless', '', 'Sword & Shield', '46', 'Basic', 'Pokémon', 'Darkness', 'type: Lightning, value: ×2'),
('swsh45-47', '', '', 'kirisAki', '[{\'name\': \'Instigate\', \'cost\': [\'Darkness\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Your opponent shuffles their hand and puts it on the bottom of their deck. If they put any cards on the bottom of their deck in this way, they draw 3 cards.\'}]', 'Shining Fates', '1', '', 'Thievul', 'Aided by the soft pads on its feet, it silently raids the food stores of other Pokémon. It survives off its ill-gotten gains.', 'Eighth', '70', 'https://images.pokemoncard.io/images/swsh45/swsh45-47.png', 'unlimited: Legal, expanded: Legal', '', 'Nickit', '827', 'TPCI', 'Common', 'D', '2/19/2021', '', 'Colorless', '', 'Sword & Shield', '47', 'Basic', 'Pokémon', 'Darkness', 'type: Grass, value: ×2'),
('swsh45-48', '', '', 'Hideki Ishikawa', '[{\'name\': \'Call for Goons\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Search your deck for up to 3 Basic Pokémon and put them onto your Bench. Then, shuffle your deck.\'}, {\'name\': \'Corner\', \'cost\': [\'Darkness\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'80\', \'text\': \"During your opponent\'s next turn, the Defending Pokémon can\'t retreat.\"}]', 'Shining Fates', '1', 'Nickit', '', 'It secretly marks potential targets with a scent. By following the scent, it stalks its targets and steals from them when they least expect it.', 'Eighth', '100', 'https://images.pokemoncard.io/images/swsh45/swsh45-48.png', 'unlimited: Legal, expanded: Legal', '', 'Thievul', '828', 'TPCI', 'Rare Holo', 'D', '2/19/2021', '', 'Colorless', '', 'Sword & Shield', '48', 'Stage 1', 'Pokémon', 'Darkness', 'type: Grass, value: ×2'),
('swsh45-49', '', '', '313', '[{\'name\': \'Strength\', \'cost\': [\'Metal\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60\', \'text\': \'\'}]', 'Shining Fates', '3', '', 'Copperajah', 'It digs up the ground with its trunk. Its also very strong, being able to carry loads of over five tons without any problem at all.', 'Eighth', '100', 'https://images.pokemoncard.io/images/swsh45/swsh45-49.png', 'unlimited: Legal, expanded: Legal', '', 'Cufant', '878', 'TPCI', 'Common', 'D', '2/19/2021', 'type: Grass, value: -30', 'Colorless, Colorless, Colorless', '', 'Sword & Shield', '49', 'Basic', 'Pokémon', 'Metal', 'type: Fire, value: ×2'),
('swsh45-5', '', '', 'Akira Komayama', '[{\'name\': \'Attach Leaves\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Attach up to 2 Grass Energy cards from your discard pile to your Benched Pokémon in any way you like.\'}, {\'name\': \'Gust\', \'cost\': [\'Grass\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'\'}]', 'Shining Fates', '1', '', '', 'Bunches of delicious fruit grow around its neck. In warm areas, many ranches raise Tropius.', 'Eighth', '110', 'https://images.pokemoncard.io/images/swsh45/swsh45-5.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Tropius', '357', 'TPCI', 'Uncommon', 'E', '2/19/2021', '', 'Colorless', '', 'Sword & Shield', '5', 'Basic', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('swsh45-50', '[{\'name\': \'V Transformation\', \'text\': \'Once during your turn, you may choose a Basic Pokémon V from your discard pile and switch it with this Pokémon. Any attached cards, damage counters, Special Conditions, turns in play, and any other effects remain on the new Pokémon.\', \'type\': \'Ability\'}]', '', 'Saki Hayashiro', '[{\'name\': \'Stick On\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Attach a basic Energy card from your discard pile to this Pokémon.\'}]', 'Shining Fates', '2', '', '', '', 'Eighth', '170', 'https://images.pokemoncard.io/images/swsh45/swsh45-50.png', 'unlimited: Legal, expanded: Legal', '', 'Ditto V', '132', 'TPCI', 'Rare Holo V', 'D', '2/19/2021', '', 'Colorless, Colorless', '[\'V rule: When your Pokémon V is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sword & Shield', '50', 'Basic, V', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('swsh45-51', '', '', 'PLANETA Tsuji', '[{\'name\': \'Max Transform\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'\', \'text\': \"Choose 1 of your opponent\'s Active Pokémon\'s attacks and use it as this attack.\"}]', 'Shining Fates', '3', 'Ditto V', '', '', 'Eighth', '320', 'https://images.pokemoncard.io/images/swsh45/swsh45-51.png', 'unlimited: Legal, expanded: Legal', '', 'Ditto VMAX', '132', 'TPCI', 'Rare Holo VMAX', 'D', '2/19/2021', '', 'Colorless, Colorless, Colorless', '[\'VMAX rule: When your Pokémon VMAX is Knocked Out, your opponent takes 3 Prize cards.\']', 'Sword & Shield', '51', 'VMAX', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('swsh45-52', '', '', 'so-taro', '[{\'name\': \'Signs of Evolution\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Search your deck for a card that evolves from Eevee, reveal it, and put it into your hand. Then, shuffle your deck.\'}, {\'name\': \'Wild Kick\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'Flip a coin. If tails, this attack does nothing.\'}]', 'Shining Fates', '1', '', 'Vaporeon, Jolteon, Flareon, Sylveon, Espeon, Umbreon, Leafeon, Glaceon', 'It has the ability to alter the composition of its body to suit its surrounding environment.', 'Eighth', '60', 'https://images.pokemoncard.io/images/swsh45/swsh45-52.png', 'unlimited: Legal, expanded: Legal', '', 'Eevee', '133', 'TPCI', 'Common', 'D', '2/19/2021', '', 'Colorless', '', 'Sword & Shield', '52', 'Basic', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('swsh45-53', '', '', 'PLANETA Igarashi', '[{\'name\': \'Crunch\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'40\', \'text\': \"Discard an Energy from your opponent\'s Active Pokémon.\"}, {\'name\': \'Stumbling Press\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'180\', \'text\': \'Flip a coin. If tails, this attack does nothing.\'}]', 'Shining Fates', '2', '', '', '', 'Eighth', '200', 'https://images.pokemoncard.io/images/swsh45/swsh45-53.png', 'unlimited: Legal, expanded: Legal', '', 'Greedent V', '820', 'TPCI', 'Rare Holo V', 'D', '2/19/2021', '', 'Colorless, Colorless', '[\'V rule: When your Pokémon V is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sword & Shield', '53', 'Basic, V', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('swsh45-54', '', '', 'aky CG Works', '[{\'name\': \'Beak Catch\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Search your deck for up to 2 cards and put them into your hand. Then, shuffle your deck.\'}, {\'name\': \'Spit Shot\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'\', \'text\': \"Discard all Energy from this Pokémon. This attack does 160 damage to 1 of your opponent\'s Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'Shining Fates', '1', '', '', '', 'Eighth', '200', 'https://images.pokemoncard.io/images/swsh45/swsh45-54.png', 'unlimited: Legal, expanded: Legal', '', 'Cramorant V', '845', 'TPCI', 'Rare Holo V', 'D', '2/19/2021', 'type: Fighting, value: -30', 'Colorless', '[\'V rule: When your Pokémon V is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sword & Shield', '54', 'Basic, V', 'Pokémon', 'Colorless', 'type: Lightning, value: ×2'),
('swsh45-55', '', '', 'PLANETA Tsuji', '[{\'name\': \'Max Jet\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'80×\', \'text\': \'Flip a coin for each Energy attached to this Pokémon. This attack does 80 damage for each heads.\'}]', 'Shining Fates', '2', 'Cramorant V', '', '', 'Eighth', '320', 'https://images.pokemoncard.io/images/swsh45/swsh45-55.png', 'unlimited: Legal, expanded: Legal', '', 'Cramorant VMAX', '845', 'TPCI', 'Rare Holo VMAX', 'D', '2/19/2021', 'type: Fighting, value: -30', 'Colorless, Colorless', '[\'VMAX rule: When your Pokémon VMAX is Knocked Out, your opponent takes 3 Prize cards.\']', 'Sword & Shield', '55', 'VMAX', 'Pokémon', 'Colorless', 'type: Lightning, value: ×2'),
('swsh45-56', '', '', 'Souichirou Gunjima', '[{\'name\': \'Helping Hand\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Search your deck for a basic Energy card and attach it to 1 of your Benched Pokémon. Then, shuffle your deck.\'}, {\'name\': \'Psychic\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20+\', \'text\': \"This attack does 20 more damage for each Energy attached to your opponent\'s Active Pokémon.\"}]', 'Shining Fates', '1', '', '', 'It uses the horns on its head to sense the emotions of others. Males will act as valets for those they serve, looking after their every need.', 'Eighth', '100', 'https://images.pokemoncard.io/images/swsh45/swsh45-56.png', 'unlimited: Legal, expanded: Legal', '', 'Indeedee', '876', 'TPCI', 'Rare Holo', 'D', '2/19/2021', '', 'Colorless', '', 'Sword & Shield', '56', 'Basic', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('swsh45-57', '', '', 'Hitoshi Ariga', '', 'Shining Fates', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh45/swsh45-57.png', 'unlimited: Legal, expanded: Legal', '', 'Ball Guy', '', 'TPCI', 'Uncommon', 'D', '2/19/2021', '', '', '[\'Search your deck for up to 3 different Item cards that have the word \"Ball\" in their name, reveal them, and put them into your hand. Then, shuffle your deck.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '57', 'Supporter', 'Trainer', '', ''),
('swsh45-58', '', '', 'Ryuta Fuse', '', 'Shining Fates', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh45/swsh45-58.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Bosss Orders', '', 'TPCI', 'Rare', 'D', '2/19/2021', '', '', '[\"Switch 1 of your opponent\'s Benched Pokémon with their Active Pokémon.\", \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '58', 'Supporter', 'Trainer', '', ''),
('swsh45-59', '', '', 'Ryuta Fuse', '', 'Shining Fates', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh45/swsh45-59.png', 'unlimited: Legal, expanded: Legal', '', 'Gym Trainer', '', 'TPCI', 'Uncommon', 'D', '2/19/2021', '', '', '[\"Draw 2 cards. If any of your Pokémon were Knocked Out during your opponent\'s last turn, draw 2 more cards.\", \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '59', 'Supporter', 'Trainer', '', ''),
('swsh45-6', '[{\'name\': \'Sky Circus\', \'text\': \"If you played Bird Keeper from your hand during this turn, ignore all Energy in this Pokémon\'s attack costs.\", \'type\': \'Ability\'}]', '', 'HYOGONOSUKE', '[{\'name\': \'Wind Shard\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'\', \'text\': \"This attack does 60 damage to 1 of your opponent\'s Benched Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'Shining Fates', '1', '', 'Dartrix', 'At a distance, it launches its sharp feathers while flying about. If the enemy gets too close, Rowlet switches tactics and delivers vicious kicks.', 'Eighth', '50', 'https://images.pokemoncard.io/images/swsh45/swsh45-6.png', 'unlimited: Legal, expanded: Legal', '', 'Rowlet', '722', 'TPCI', 'Common', 'D', '2/19/2021', '', 'Colorless', '', 'Sword & Shield', '6', 'Basic', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('swsh45-60', '', '', 'Hideki Ishikawa', '', 'Shining Fates', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh45/swsh45-60.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Professors Research', '', 'TPCI', 'Rare', 'D', '2/19/2021', '', '', '[\'Discard your hand and draw 7 cards.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '60', 'Supporter', 'Trainer', '', ''),
('swsh45-61', '', '', '5ban Graphics', '', 'Shining Fates', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh45/swsh45-61.png', 'unlimited: Legal, expanded: Legal', '', 'Rusted Shield', '', 'TPCI', 'Uncommon', 'D', '2/19/2021', '', '', '[\"Attach a Pokémon Tool to 1 of your Pokémon that doesn\'t already have a Pokémon Tool attached.\", \'The Zamazenta V this card is attached to gets +70 HP.\', \'You may play any number of Item cards during your turn.\']', 'Sword & Shield', '61', 'Pokémon Tool', 'Trainer', '', ''),
('swsh45-62', '', '', '5ban Graphics', '', 'Shining Fates', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh45/swsh45-62.png', 'unlimited: Legal, expanded: Legal', '', 'Rusted Sword', '', 'TPCI', 'Uncommon', 'D', '2/19/2021', '', '', '[\"Attach a Pokémon Tool to 1 of your Pokémon that doesn\'t already have a Pokémon Tool attached.\", \"The attacks of the Zacian V this card is attached to do 30 more damage to your opponent\'s Active Pokémon (before applying Weakness and Resistance).\", \'You may play any number of Item cards during your turn.\']', 'Sword & Shield', '62', 'Pokémon Tool', 'Trainer', '', ''),
('swsh45-63', '', '', 'Studio Bora Inc.', '', 'Shining Fates', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh45/swsh45-63.png', 'unlimited: Legal, expanded: Legal', '', 'Team Yell Towel', '', 'TPCI', 'Uncommon', 'D', '2/19/2021', '', '', '[\'Heal 50 damage from both Active Pokémon.\', \'You may play any number of Item cards during your turn.\']', 'Sword & Shield', '63', 'Item', 'Trainer', '', ''),
('swsh45-64', '', '', 'Ayaka Yoshida', '[{\'name\': \'Sugary Sprinkles\', \'cost\': [\'Psychic\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Heal 30 damage from each of your Benched Pokémon.\'}, {\'name\': \'Sweet Splash\', \'cost\': [\'Psychic\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'100\', \'text\': \"If the Defending Pokémon is a Basic Pokémon, it can\'t attack during your opponent\'s next turn.\"}]', 'Shining Fates', '2', '', '', '', 'Eighth', '170', 'https://images.pokemoncard.io/images/swsh45/swsh45-64.png', 'unlimited: Legal, expanded: Legal', '', 'Alcremie V', '869', 'TPCI', 'Rare Ultra', 'D', '2/19/2021', '', 'Colorless, Colorless', '[\'V rule: When your Pokémon V is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sword & Shield', '64', 'Basic, V', 'Pokémon', 'Psychic', 'type: Metal, value: ×2'),
('swsh45-65', '', '', 'Hitoshi Ariga', '', 'Shining Fates', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh45/swsh45-65.png', 'unlimited: Legal, expanded: Legal', '', 'Ball Guy', '', 'TPCI', 'Rare Ultra', 'D', '2/19/2021', '', '', '[\'Search your deck for up to 3 different Item cards that have the word \"Ball\" in their name, reveal them, and put them into your hand. Then, shuffle your deck.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '65', 'Supporter', 'Trainer', '', ''),
