('swsh6-186', '', '', 'NC Empire', '', 'Chilling Reign', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh6/swsh6-186.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Agatha', '', 'TPCI', 'Rare Ultra', 'E', '6/18/2021', '', '', '[\"Move up to 3 damage counters from your Active Pokémon to your opponent\'s Active Pokémon.\", \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '186', 'Supporter', 'Trainer', '', ''),
('swsh6-187', '', '', 'kirisAki', '', 'Chilling Reign', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh6/swsh6-187.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Avery', '', 'TPCI', 'Rare Ultra', 'E', '6/18/2021', '', '', '[\'Draw 3 cards. If you drew any cards in this way, your opponent discards Pokémon from their Bench until they have 3.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '187', 'Supporter', 'Trainer', '', ''),
('swsh6-188', '', '', 'Sanosuke Sakuma', '', 'Chilling Reign', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh6/swsh6-188.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Brawly', '', 'TPCI', 'Rare Ultra', 'E', '6/18/2021', '', '', '[\'Search your deck for up to 3 Basic Rapid Strike Pokémon and put them onto your Bench. Then, shuffle your deck.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '188', 'Supporter, Rapid Strike', 'Trainer', '', ''),
('swsh6-189', '', '', 'En Morikura', '', 'Chilling Reign', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh6/swsh6-189.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Caitlin', '', 'TPCI', 'Rare Ultra', 'E', '6/18/2021', '', '', '[\'Put any number of cards from your hand on the bottom of your deck in any order. Then, draw that many cards.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '189', 'Supporter', 'Trainer', '', ''),
('swsh6-19', '', '', 'Shin Nagasawa', '[{\'name\': \'Pack Call\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Search your deck for a Grass Pokémon, reveal it, and put it into your hand. If you go second and it\'s your first turn, search for up to 3 Grass Pokémon instead of 1. Then, shuffle your deck.\"}, {\'name\': \'Repeated Whip\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60+\', \'text\': \'This attack does 20 more damage for each Grass Energy attached to this Pokémon.\'}]', 'Chilling Reign', '2', '', '', 'Once the vines on Zarudes body tear off, they become nutrients in the soil. This helps the plants of the forest grow.', 'Eighth', '130', 'https://images.pokemoncard.io/images/swsh6/swsh6-19.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Zarude', '893', 'TPCI', 'Rare Holo', 'E', '6/18/2021', '', 'Colorless, Colorless', '', 'Sword & Shield', '19', 'Basic', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('swsh6-190', '', '', 'Sanosuke Sakuma', '', 'Chilling Reign', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh6/swsh6-190.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Doctor', '', 'TPCI', 'Rare Ultra', 'E', '6/18/2021', '', '', '[\"Draw 2 cards. If your opponent\'s Active Pokémon is a Pokémon VMAX, draw 2 more cards.\", \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '190', 'Supporter', 'Trainer', '', ''),
('swsh6-191', '', '', 'Ryuta Fuse', '', 'Chilling Reign', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh6/swsh6-191.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Flannery', '', 'TPCI', 'Rare Ultra', 'E', '6/18/2021', '', '', '[\"Discard a Special Energy from 1 of your opponent\'s Pokémon, and discard a Stadium in play.\", \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '191', 'Supporter, Single Strike', 'Trainer', '', ''),
('swsh6-192', '', '', 'Ryuta Fuse', '', 'Chilling Reign', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh6/swsh6-192.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Honey', '', 'TPCI', 'Rare Ultra', 'E', '6/18/2021', '', '', '[\"Draw a card for each of your opponent\'s Benched Pokémon V.\", \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '192', 'Supporter', 'Trainer', '', ''),
('swsh6-193', '', '', 'Hideki Ishikawa', '', 'Chilling Reign', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh6/swsh6-193.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Karens Conviction', '', 'TPCI', 'Rare Ultra', 'E', '6/18/2021', '', '', '[\"During this turn, your Single Strike Pokémon\'s attacks do 20 more damage to your opponent\'s Active Pokémon for each Prize card your opponent has taken (before applying Weakness and Resistance).\", \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '193', 'Supporter, Single Strike', 'Trainer', '', ''),
('swsh6-194', '', '', 'Naoki Saito', '', 'Chilling Reign', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh6/swsh6-194.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Klara', '', 'TPCI', 'Rare Ultra', 'E', '6/18/2021', '', '', '[\'Choose 1 or both:\\n• Put up to 2 Pokémon from your discard pile into your hand.\\n• Put up to 2 basic Energy cards from your discard pile into your hand.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '194', 'Supporter', 'Trainer', '', ''),
('swsh6-195', '', '', 'Taira Akitsu', '', 'Chilling Reign', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh6/swsh6-195.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Melony', '', 'TPCI', 'Rare Ultra', 'E', '6/18/2021', '', '', '[\'Attach a Water Energy card from your discard pile to 1 of your Pokémon V. If you do, draw 3 cards.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '195', 'Supporter', 'Trainer', '', ''),
('swsh6-196', '', '', 'kirisAki', '', 'Chilling Reign', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh6/swsh6-196.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Peonia', '', 'TPCI', 'Rare Ultra', 'E', '6/18/2021', '', '', '[\'Put up to 3 Prize cards into your hand. Then, for each Prize card you put into your hand in this way, put a card from your hand face down as a Prize card.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '196', 'Supporter', 'Trainer', '', ''),
('swsh6-197', '', '', 'Hitoshi Ariga', '', 'Chilling Reign', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh6/swsh6-197.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Peony', '', 'TPCI', 'Rare Ultra', 'E', '6/18/2021', '', '', '[\'Discard your hand and search your deck for up to 2 Trainer cards, reveal them, and put them into your hand. Then, shuffle your deck.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '197', 'Supporter', 'Trainer', '', ''),
