('swsh6-21', '', '', 'AKIRA EGAWA', '[{\'name\': \'Clutch\', \'cost\': [\'Fire\'], \'convertedEnergyCost\': 1, \'damage\': \'60\', \'text\': \"During your opponent\'s next turn, the Defending Pokémon can\'t retreat.\"}, {\'name\': \'Max Blaze\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'130\', \'text\': \'Choose up to 2 of your Benched Rapid Strike Pokémon and attach an Energy card from your discard pile to each of them.\'}]', 'Chilling Reign', '2', 'Blaziken V', '', '', 'Eighth', '320', 'https://images.pokemoncard.io/images/swsh6/swsh6-21.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Blaziken VMAX', '257', 'TPCI', 'Rare Holo VMAX', 'E', '6/18/2021', '', 'Colorless, Colorless', '[\'VMAX rule: When your Pokémon VMAX is Knocked Out, your opponent takes 3 Prize cards.\']', 'Sword & Shield', '21', 'VMAX, Rapid Strike', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('swsh6-210', '', '', 'NC Empire', '', 'Chilling Reign', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh6/swsh6-210.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Agatha', '', 'TPCI', 'Rare Rainbow', 'E', '6/18/2021', '', '', '[\"Move up to 3 damage counters from your Active Pokémon to your opponent\'s Active Pokémon.\", \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '210', 'Supporter', 'Trainer', '', ''),
('swsh6-211', '', '', 'kirisAki', '', 'Chilling Reign', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh6/swsh6-211.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Avery', '', 'TPCI', 'Rare Rainbow', 'E', '6/18/2021', '', '', '[\'Draw 3 cards. If you drew any cards in this way, your opponent discards Pokémon from their Bench until they have 3.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '211', 'Supporter', 'Trainer', '', ''),
('swsh6-212', '', '', 'Sanosuke Sakuma', '', 'Chilling Reign', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh6/swsh6-212.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Brawly', '', 'TPCI', 'Rare Rainbow', 'E', '6/18/2021', '', '', '[\'Search your deck for up to 3 Basic Rapid Strike Pokémon and put them onto your Bench. Then, shuffle your deck.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '212', 'Supporter, Rapid Strike', 'Trainer', '', ''),
('swsh6-213', '', '', 'En Morikura', '', 'Chilling Reign', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh6/swsh6-213.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Caitlin', '', 'TPCI', 'Rare Rainbow', 'E', '6/18/2021', '', '', '[\'Put any number of cards from your hand on the bottom of your deck in any order. Then, draw that many cards.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '213', 'Supporter', 'Trainer', '', ''),
('swsh6-214', '', '', 'Sanosuke Sakuma', '', 'Chilling Reign', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh6/swsh6-214.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Doctor', '', 'TPCI', 'Rare Rainbow', 'E', '6/18/2021', '', '', '[\"Draw 2 cards. If your opponent\'s Active Pokémon is a Pokémon VMAX, draw 2 more cards.\", \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '214', 'Supporter', 'Trainer', '', ''),
('swsh6-215', '', '', 'Ryuta Fuse', '', 'Chilling Reign', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh6/swsh6-215.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Flannery', '', 'TPCI', 'Rare Rainbow', 'E', '6/18/2021', '', '', '[\"Discard a Special Energy from 1 of your opponent\'s Pokémon, and discard a Stadium in play.\", \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '215', 'Supporter, Single Strike', 'Trainer', '', ''),
('swsh6-216', '', '', 'Hideki Ishikawa', '', 'Chilling Reign', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh6/swsh6-216.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Karens Conviction', '', 'TPCI', 'Rare Rainbow', 'E', '6/18/2021', '', '', '[\"During this turn, your Single Strike Pokémon\'s attacks do 20 more damage to your opponent\'s Active Pokémon for each Prize card your opponent has taken (before applying Weakness and Resistance).\", \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '216', 'Supporter, Single Strike', 'Trainer', '', ''),
('swsh6-217', '', '', 'Naoki Saito', '', 'Chilling Reign', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh6/swsh6-217.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Klara', '', 'TPCI', 'Rare Rainbow', 'E', '6/18/2021', '', '', '[\'Choose 1 or both:\\n• Put up to 2 Pokémon from your discard pile into your hand.\\n• Put up to 2 basic Energy cards from your discard pile into your hand.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '217', 'Supporter', 'Trainer', '', ''),
('swsh6-218', '', '', 'Taira Akitsu', '', 'Chilling Reign', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh6/swsh6-218.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Melony', '', 'TPCI', 'Rare Rainbow', 'E', '6/18/2021', '', '', '[\'Attach a Water Energy card from your discard pile to 1 of your Pokémon V. If you do, draw 3 cards.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '218', 'Supporter', 'Trainer', '', ''),
('swsh6-219', '', '', 'kirisAki', '', 'Chilling Reign', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh6/swsh6-219.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Peonia', '', 'TPCI', 'Rare Rainbow', 'E', '6/18/2021', '', '', '[\'Put up to 3 Prize cards into your hand. Then, for each Prize card you put into your hand in this way, put a card from your hand face down as a Prize card.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '219', 'Supporter', 'Trainer', '', ''),
('swsh6-22', '[{\'name\': \'Weather Reading\', \'text\': \"If you have 8 or more Stadium cards in your discard pile, ignore all Energy in this Pokémon\'s attack costs.\", \'type\': \'Ability\'}]', '', 'Yuka Morii', '[{\'name\': \'High-Pressure Blast\', \'cost\': [\'Fire\', \'Fire\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'150\', \'text\': \"Discard a Stadium in play. If you can\'t, this attack does nothing.\"}]', 'Chilling Reign', '', '', '', 'Castform changes to this form when it basks in bright sunlight. When you touch its glowing skin, it feels all dried out!', 'Eighth', '70', 'https://images.pokemoncard.io/images/swsh6/swsh6-22.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Castform Sunny Form', '351', 'TPCI', 'Common', 'E', '6/18/2021', '', '', '', 'Sword & Shield', '22', 'Basic', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('swsh6-220', '', '', 'Hitoshi Ariga', '', 'Chilling Reign', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh6/swsh6-220.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Peony', '', 'TPCI', 'Rare Rainbow', 'E', '6/18/2021', '', '', '[\'Discard your hand and search your deck for up to 2 Trainer cards, reveal them, and put them into your hand. Then, shuffle your deck.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '220', 'Supporter', 'Trainer', '', ''),
('swsh6-221', '', '', 'Hideki Ishikawa', '', 'Chilling Reign', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh6/swsh6-221.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Siebold', '', 'TPCI', 'Rare Rainbow', 'E', '6/18/2021', '', '', '[\'Choose up to 2 of your Rapid Strike Pokémon and heal 60 damage from each of them.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '221', 'Supporter, Rapid Strike', 'Trainer', '', ''),
('swsh6-222', '[{\'name\': \'Buzzap Generator\', \'text\': \'Once during your turn, if this Pokémon is on your Bench, you may search your deck for up to 2 Lightning Energy cards and attach them to your Lightning Pokémon in any way you like. Then, shuffle your deck. If you searched your deck in this way, this Pokémon is Knocked Out.\', \'type\': \'Ability\'}]', '', 'Ryo Ueda', '[{\'name\': \'Electric Ball\', \'cost\': [\'Lightning\', \'Lightning\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'100\', \'text\': \'\'}]', 'Chilling Reign', '1', 'Voltorb', '', 'It stores an overflowing amount of electric energy inside its body. Even a small shock makes it explode.', 'Eighth', '90', 'https://images.pokemoncard.io/images/swsh6/swsh6-222.png', 'unlimited: Legal, expanded: Legal', '', 'Electrode', '101', 'TPCI', 'Rare Secret', 'D', '6/18/2021', '', 'Colorless', '', 'Sword & Shield', '222', 'Stage 1', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
('swsh6-223', '[{\'name\': \'Metal Transfer\', \'text\': \'As often as you like during your turn, you may move a Metal Energy from 1 of your Pokémon to another of your Pokémon.\', \'type\': \'Ability\'}]', '', 'Eske Yoshinob', '[{\'name\': \'Zen Headbutt\', \'cost\': [\'Metal\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'70\', \'text\': \'\'}]', 'Chilling Reign', '3', 'Bronzor', '', 'Many scientists suspect that this Pokémon originated outside the Galar region, based on the patterns on its body.', 'Eighth', '110', 'https://images.pokemoncard.io/images/swsh6/swsh6-223.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Bronzong', '437', 'TPCI', 'Rare Secret', 'E', '6/18/2021', 'type: Grass, value: -30', 'Colorless, Colorless, Colorless', '', 'Sword & Shield', '223', 'Stage 1', 'Pokémon', 'Metal', 'type: Fire, value: ×2'),
('swsh6-224', '[{\'name\': \'Gormandize\', \'text\': \'Once during your turn, if this Pokémon is in the Active Spot, you may draw cards until you have 7 cards in your hand. If you use this Ability, your turn ends.\', \'type\': \'Ability\'}]', '', 'Saki Hayashiro', '[{\'name\': \'Body Slam\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'100\', \'text\': \"Flip a coin. If heads, your opponent\'s Active Pokémon is now Paralyzed.\"}]', 'Chilling Reign', '3', '', '', 'It is not satisfied unless it eats over 880 pounds of food every day. When it is done eating, it goes promptly to sleep.', 'Eighth', '130', 'https://images.pokemoncard.io/images/swsh6/swsh6-224.png', 'unlimited: Legal, expanded: Legal', '', 'Snorlax', '143', 'TPCI', 'Rare Secret', 'D', '6/18/2021', '', 'Colorless, Colorless, Colorless', '', 'Sword & Shield', '224', 'Basic', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('swsh6-225', '', '', 'Studio Bora Inc.', '', 'Chilling Reign', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh6/swsh6-225.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Echoing Horn', '', 'TPCI', 'Rare Secret', 'E', '6/18/2021', '', '', '[\"Put a Basic Pokémon from your opponent\'s discard pile onto their Bench.\", \'You may play any number of Item cards during your turn.\']', 'Sword & Shield', '225', 'Item, Rapid Strike', 'Trainer', '', ''),
('swsh6-226', '', '', 'sadaji', '', 'Chilling Reign', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh6/swsh6-226.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Fan of Waves', '', 'TPCI', 'Rare Secret', 'E', '6/18/2021', '', '', '[\"Put a Special Energy attached to 1 of your opponent\'s Pokémon on the bottom of their deck.\", \'You may play any number of Item cards during your turn.\']', 'Sword & Shield', '226', 'Item, Rapid Strike', 'Trainer', '', ''),
('swsh6-227', '', '', 'sadaji', '', 'Chilling Reign', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh6/swsh6-227.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Fog Crystal', '', 'TPCI', 'Rare Secret', 'E', '6/18/2021', '', '', '[\'Search your deck for a Psychic Energy card or a Basic Psychic Pokémon, reveal it, and put it into your hand. Then, shuffle your deck.\', \'You may play any number of Item cards during your turn.\']', 'Sword & Shield', '227', 'Item', 'Trainer', '', ''),
('swsh6-228', '', '', 'sadaji', '', 'Chilling Reign', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh6/swsh6-228.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Rugged Helmet', '', 'TPCI', 'Rare Secret', 'E', '6/18/2021', '', '', '[\"Attach a Pokémon Tool to 1 of your Pokémon that doesn\'t already have a Pokémon Tool attached.\", \"If the Pokémon this card is attached to is in the Active Spot and is damaged by an attack from your opponent\'s Pokémon (even if it is Knocked Out), put an Energy attached to the Attacking Pokémon into your opponent\'s hand.\", \'You may play any number of Item cards during your turn.\']', 'Sword & Shield', '228', 'Pokémon Tool', 'Trainer', '', ''),
('swsh6-229', '', '', 'Toyste Beach', '', 'Chilling Reign', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh6/swsh6-229.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Urn of Vitality', '', 'TPCI', 'Rare Secret', 'E', '6/18/2021', '', '', '[\'Shuffle up to 2 Single Strike Energy cards from your discard pile into your deck.\', \'You may play any number of Item cards during your turn.\']', 'Sword & Shield', '229', 'Item, Single Strike', 'Trainer', '', ''),
('swsh6-23', '', '', 'Misa Tsutsui', '[{\'name\': \'Flame Charge\', \'cost\': [\'Fire\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'Search your deck for a Fire Energy card and attach it to this Pokémon. Then, shuffle your deck.\'}]', 'Chilling Reign', '3', '', 'Volcarona', 'It protects itself with flame. Long years ago, people believed Larvesta had a nest on the sun.', 'Eighth', '80', 'https://images.pokemoncard.io/images/swsh6/swsh6-23.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Larvesta', '636', 'TPCI', 'Common', 'E', '6/18/2021', '', 'Colorless, Colorless, Colorless', '', 'Sword & Shield', '23', 'Basic', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
