('swsh7-149', '', '', 'take', '', 'Evolving Skies', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh7/swsh7-149.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Gordie', '', 'TPCI', 'Uncommon', 'E', '8/27/2021', '', '', '[\'Look at the top 7 cards of your deck. You may reveal any number of Energy cards you find there and put them into your hand. Shuffle the other cards back into your deck.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '149', 'Supporter', 'Trainer', '', ''),
('swsh7-15', '', '', 'Mizue', '[{\'name\': \'Blot\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'Heal 10 damage from this Pokémon.\'}]', 'Evolving Skies', '1', '', 'Eldegoss', 'It whirls around in the wind while singing a joyous song. This delightful display has charmed many into raising this Pokémon.', 'Eighth', '50', 'https://images.pokemoncard.io/images/swsh7/swsh7-15.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Gossifleur', '829', 'TPCI', 'Common', 'E', '8/27/2021', '', 'Colorless', '', 'Sword & Shield', '15', 'Basic', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('swsh7-150', '', '', 'inose yukie', '', 'Evolving Skies', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh7/swsh7-150.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Lucky Ice Pop', '', 'TPCI', 'Uncommon', 'E', '8/27/2021', '', '', '[\'Heal 20 damage from your Active Pokémon. If you healed any damage in this way, flip a coin. If heads, put this Lucky Ice Pop into your hand instead of the discard pile.\', \'You may play any number of Item cards during your turn.\']', 'Sword & Shield', '150', 'Item', 'Trainer', '', ''),
('swsh7-151', '', '', 'Studio Bora Inc.', '', 'Evolving Skies', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh7/swsh7-151.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Moon & Sun Badge', '', 'TPCI', 'Uncommon', 'E', '8/27/2021', '', '', '[\'If the Pokémon V this card is attached to has \"Espeon\" or \"Umbreon\" in its name, whenever your opponent plays a Supporter card from their hand, prevent all effects of that card done to that Pokémon.\', \'You may play any number of Item cards during your turn.\', \"Attach a Pokémon Tool to 1 of your Pokémon that doesn\'t already have a Pokémon Tool attached.\"]', 'Sword & Shield', '151', 'Item, Pokémon Tool', 'Trainer', '', ''),
('swsh7-152', '', '', 'take', '', 'Evolving Skies', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh7/swsh7-152.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Raihan', '', 'TPCI', 'Uncommon', 'E', '8/27/2021', '', '', '[\"You can play this card only if any of your Pokémon were Knocked Out during your opponent\'s last turn. Attach a basic Energy card from your discard pile to 1 of your Pokémon. If you do, search your deck for a card and put it into your hand. Then, shuffle your deck.\", \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '152', 'Supporter', 'Trainer', '', ''),
('swsh7-153', '', '', '5ban Graphics', '', 'Evolving Skies', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh7/swsh7-153.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Rapid Strike Scroll of the Flying Dragon', '', 'TPCI', 'Uncommon', 'E', '8/27/2021', '', '', '[\"The Rapid Strike Pokémon this card is attached to can use the attack on this card. (You still need the necessary Energy to use this attack.) FireLightning Meteor Discard 2 Energy from this Pokémon. This attack does 90 damage to 1 of your opponent\'s Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\", \'You may play any number of Item cards during your turn.\', \"Attach a Pokémon Tool to 1 of your Pokémon that doesn\'t already have a Pokémon Tool attached.\"]', 'Sword & Shield', '153', 'Rapid Strike, Item, Pokémon Tool', 'Trainer', '', ''),
('swsh7-154', '', '', 'Ryo Ueda', '', 'Evolving Skies', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh7/swsh7-154.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Rescue Carrier', '', 'TPCI', 'Uncommon', 'E', '8/27/2021', '', '', '[\'Put up to 2 Pokémon, each with 90 HP or less, from your discard pile into your hand.\', \'You may play any number of Item cards during your turn.\']', 'Sword & Shield', '154', 'Item', 'Trainer', '', ''),
