('swsh7-199', '', '', 'En Morikura', '', 'Evolving Skies', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh7/swsh7-199.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Aroma Lady', '', 'TPCI', 'Rare Ultra', 'E', '8/27/2021', '', '', '[\'Draw 2 cards. If you do, your Active Pokémon recovers from all Special Conditions.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '199', 'Supporter', 'Trainer', '', ''),
('swsh7-2', '', '', 'Kagemaru Himeno', '[{\'name\': \'Continuous Spin\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'20×\', \'text\': \'Flip a coin until you get tails. This attack does 20 damage for each heads.\'}]', 'Evolving Skies', '', '', 'Skiploom', 'It drifts on winds. It is said that when Hoppip gather in fields and mountains, spring is on the way.', 'Eighth', '40', 'https://images.pokemoncard.io/images/swsh7/swsh7-2.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Hoppip', '187', 'TPCI', 'Common', 'E', '8/27/2021', '', '', '', 'Sword & Shield', '2', 'Basic, Rapid Strike', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('swsh7-20', '', '', 'Teeziro', '[{\'name\': \'Victory Dive\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'You may search your deck for up to 2 cards and put them into your hand. Then, shuffle your deck.\'}]', 'Evolving Skies', '1', '', '', 'When it shares the infinite energy it creates, that beings entire body will be overflowing with power.', 'Eighth', '60', 'https://images.pokemoncard.io/images/swsh7/swsh7-20.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Victini', '494', 'TPCI', 'Rare Holo', 'E', '8/27/2021', '', 'Colorless', '', 'Sword & Shield', '20', 'Basic', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('swsh7-200', '', '', 'Sanosuke Sakuma', '', 'Evolving Skies', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh7/swsh7-200.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Copycat', '', 'TPCI', 'Rare Ultra', 'E', '8/27/2021', '', '', '[\"Shuffle your hand into your deck. Then, draw a card for each card in your opponent\'s hand.\", \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '200', 'Supporter', 'Trainer', '', ''),
('swsh7-201', '', '', 'Hitoshi Ariga', '', 'Evolving Skies', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh7/swsh7-201.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Gordie', '', 'TPCI', 'Rare Ultra', 'E', '8/27/2021', '', '', '[\'Look at the top 7 cards of your deck. You may reveal any number of Energy cards you find there and put them into your hand. Shuffle the other cards back into your deck.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '201', 'Supporter', 'Trainer', '', ''),
('swsh7-202', '', '', 'kirisAki', '', 'Evolving Skies', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh7/swsh7-202.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Raihan', '', 'TPCI', 'Rare Ultra', 'E', '8/27/2021', '', '', '[\"You can play this card only if any of your Pokémon were Knocked Out during your opponent\'s last turn. Attach a basic Energy card from your discard pile to 1 of your Pokémon. If you do, search your deck for a card and put it into your hand. Then, shuffle your deck.\", \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '202', 'Supporter', 'Trainer', '', ''),
('swsh7-203', '', '', 'Taira Akitsu', '', 'Evolving Skies', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh7/swsh7-203.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Zinnias Resolve', '', 'TPCI', 'Rare Ultra', 'E', '8/27/2021', '', '', '[\"You can play this card only if you discard 2 other cards from your hand. Draw a card for each of your opponent\'s Pokémon in play.\", \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '203', 'Supporter', 'Trainer', '', ''),
