('swsh7-221', '', '', 'En Morikura', '', 'Evolving Skies', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh7/swsh7-221.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Aroma Lady', '', 'TPCI', 'Rare Rainbow', 'E', '8/27/2021', '', '', '[\'Draw 2 cards. If you do, your Active Pokémon recovers from all Special Conditions.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '221', 'Supporter', 'Trainer', '', ''),
('swsh7-222', '', '', 'Sanosuke Sakuma', '', 'Evolving Skies', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh7/swsh7-222.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Copycat', '', 'TPCI', 'Rare Rainbow', 'E', '8/27/2021', '', '', '[\"Shuffle your hand into your deck. Then, draw a card for each card in your opponent\'s hand.\", \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '222', 'Supporter', 'Trainer', '', ''),
('swsh7-223', '', '', 'Hitoshi Ariga', '', 'Evolving Skies', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh7/swsh7-223.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Gordie', '', 'TPCI', 'Rare Rainbow', 'E', '8/27/2021', '', '', '[\'Look at the top 7 cards of your deck. You may reveal any number of Energy cards you find there and put them into your hand. Shuffle the other cards back into your deck.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '223', 'Supporter', 'Trainer', '', ''),
('swsh7-224', '', '', 'kirisAki', '', 'Evolving Skies', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh7/swsh7-224.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Raihan', '', 'TPCI', 'Rare Rainbow', 'E', '8/27/2021', '', '', '[\"You can play this card only if any of your Pokémon were Knocked Out during your opponent\'s last turn. Attach a basic Energy card from your discard pile to 1 of your Pokémon. If you do, search your deck for a card and put it into your hand. Then, shuffle your deck.\", \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '224', 'Supporter', 'Trainer', '', ''),
('swsh7-225', '', '', 'Taira Akitsu', '', 'Evolving Skies', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh7/swsh7-225.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Zinnias Resolve', '', 'TPCI', 'Rare Rainbow', 'E', '8/27/2021', '', '', '[\"You can play this card only if you discard 2 other cards from your hand. Draw a card for each of your opponent\'s Pokémon in play.\", \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '225', 'Supporter', 'Trainer', '', ''),
('swsh7-226', '[{\'name\': \'Frost Over\', \'text\': \'When you play this Pokémon from your hand to evolve 1 of your Pokémon during your turn, you may attach a Water Energy card from your discard pile to 1 of your Pokémon.\', \'type\': \'Ability\'}]', '', 'Studio Bora Inc.', '[{\'name\': \'Crystal Breath\', \'cost\': [\'Water\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'90\', \'text\': \"During your next turn, this Pokémon can\'t attack.\"}]', 'Evolving Skies', '1', 'Snorunt', '', 'It spits out cold air of nearly -60 degrees Fahrenheit to freeze its quarry. It brings frozen prey back to its lair and neatly lines them up.', 'Eighth', '90', 'https://images.pokemoncard.io/images/swsh7/swsh7-226.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Froslass', '478', 'TPCI', 'Rare Secret', 'E', '8/27/2021', '', 'Colorless', '', 'Sword & Shield', '226', 'Stage 1', 'Pokémon', 'Water', 'type: Metal, value: ×2'),
('swsh7-227', '[{\'name\': \'Quick Shooting\', \'text\': \"Once during your turn, you may put 2 damage counters on 1 of your opponent\'s Pokémon.\", \'type\': \'Ability\'}]', '', 'Saki Hayashiro', '[{\'name\': \'Waterfall\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'70\', \'text\': \'\'}]', 'Evolving Skies', '1', 'Drizzile', '', 'Its nictitating membranes let it pick out foes weak points so it can precisely blast them with water that shoots from its fingertips at Mach 3.', 'Eighth', '150', 'https://images.pokemoncard.io/images/swsh7/swsh7-227.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Inteleon', '818', 'TPCI', 'Rare Secret', 'E', '8/27/2021', '', 'Colorless', '', 'Sword & Shield', '227', 'Stage 2, Rapid Strike', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('swsh7-228', '', '', 'Toyste Beach', '[{\'name\': \'Crescent Glow\', \'cost\': [\'Psychic\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Search your deck for a Psychic Energy card and attach it to 1 of your Pokémon. If you go second and it\'s your first turn, instead search for up to 3 Psychic Energy cards and attach them to 1 of your Pokémon. Then, shuffle your deck.\"}, {\'name\': \'Photon Laser\', \'cost\': [\'Psychic\', \'Psychic\'], \'convertedEnergyCost\': 2, \'damage\': \'30+\', \'text\': \'If you have at least 5 Energy in play, this attack does 90 more damage.\'}]', 'Evolving Skies', '1', '', '', 'Those who sleep holding Cresselias feather are assured of joyful dreams. It is said to represent the crescent moon.', 'Eighth', '120', 'https://images.pokemoncard.io/images/swsh7/swsh7-228.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Cresselia', '488', 'TPCI', 'Rare Secret', 'E', '8/27/2021', 'type: Fighting, value: -30', 'Colorless', '', 'Sword & Shield', '228', 'Basic', 'Pokémon', 'Psychic', 'type: Darkness, value: ×2'),
('swsh7-229', '', '', 'sadaji', '', 'Evolving Skies', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh7/swsh7-229.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Boost Shake', '', 'TPCI', 'Rare Secret', 'E', '8/27/2021', '', '', '[\'Search your deck for a card that evolves from 1 of your Pokémon and put it onto that Pokémon to evolve it. Then, shuffle your deck. You can use this card during your first turn or on a Pokémon that was put into play this turn. Your turn ends.\', \'You may play any number of Item cards during your turn.\']', 'Sword & Shield', '229', 'Item', 'Trainer', '', ''),
('swsh7-23', '', '', 'Hitoshi Ariga', '[{\'name\': \'Combustion\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'30\', \'text\': \'\'}, {\'name\': \'Rip Claw\', \'cost\': [\'Fire\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'70\', \'text\': \"Discard an Energy from your opponent\'s Active Pokémon.\"}]', 'Evolving Skies', '2', 'Litleo', '', 'The temperature of its breath is over 10,000 degrees Fahrenheit, but Pyroar doesnt use it on its prey. This Pokémon prefers to eat raw meat.', 'Eighth', '130', 'https://images.pokemoncard.io/images/swsh7/swsh7-23.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Pyroar', '668', 'TPCI', 'Uncommon', 'E', '8/27/2021', '', 'Colorless, Colorless', '', 'Sword & Shield', '23', 'Stage 1', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('swsh7-230', '', '', 'Toyste Beach', '', 'Evolving Skies', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh7/swsh7-230.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Crystal Cave', '', 'TPCI', 'Rare Secret', 'E', '8/27/2021', '', '', '[\"Once during each player\'s turn, that player may heal 30 damage from each of their Metal Pokémon and Dragon Pokémon.\"]', 'Sword & Shield', '230', 'Stadium', 'Trainer', '', ''),
('swsh7-231', '', '', 'AYUMI ODASHIMA', '', 'Evolving Skies', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh7/swsh7-231.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Full Face Guard', '', 'TPCI', 'Rare Secret', 'E', '8/27/2021', '', '', '[\"If the Pokémon this card is attached to has no Abilities, it takes 20 less damage from attacks from your opponent\'s Pokémon (after applying Weakness and Resistance).\", \'You may play any number of Item cards during your turn.\', \"Attach a Pokémon Tool to 1 of your Pokémon that doesn\'t already have a Pokémon Tool attached.\"]', 'Sword & Shield', '231', 'Item, Pokémon Tool', 'Trainer', '', ''),
