('swsh8-260', '', '', 'Ryuta Fuse', '', 'Fusion Strike', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh8/swsh8-260.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Elesas Sparkle', '', 'TPCI', 'Rare Ultra', 'E', '11/12/2021', '', '', '[\'Choose up to 2 of your Fusion Strike Pokémon. For each of those Pokémon, search your deck for a Fusion Strike Energy card and attach it to that Pokémon. Then, shuffle your deck.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '260', 'Supporter, Fusion Strike', 'Trainer', '', ''),
('swsh8-261', '', '', 'Hideki Ishikawa', '', 'Fusion Strike', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh8/swsh8-261.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Schoolboy', '', 'TPCI', 'Rare Ultra', 'E', '11/12/2021', '', '', '[\'Draw 2 cards. If your opponent has exactly 1, 3, or 5 Prize cards remaining, draw 2 more cards.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '261', 'Supporter', 'Trainer', '', ''),
