('swsh8-263', '', '', 'Yuu Nishida', '', 'Fusion Strike', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh8/swsh8-263.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Shauna', '', 'TPCI', 'Rare Ultra', 'E', '11/12/2021', '', '', '[\'Shuffle your hand into your deck. Then, draw 5 cards.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '263', 'Supporter', 'Trainer', '', ''),
('swsh8-264', '', '', 'Hideki Ishikawa', '', 'Fusion Strike', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh8/swsh8-264.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Sidney', '', 'TPCI', 'Rare Ultra', 'E', '11/12/2021', '', '', '[\'Your opponent reveals their hand. Discard up to 2 in any combination of Pokémon Tool cards, Special Energy cards, and Stadium cards from it.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '264', 'Supporter', 'Trainer', '', ''),
('swsh8-265', '[{\'name\': \'Cursed Shimmer\', \'text\': \"As long as this Pokémon is in the Active Spot, your opponent can\'t play any Pokémon Tool cards from their hand.\", \'type\': \'Ability\'}]', '', 'AKIRA EGAWA', '[{\'name\': \'Max Poltergeist\', \'cost\': [\'Fire\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'70×\', \'text\': \'Your opponent reveals their hand. This attack does 70 damage for each Trainer card you find there.\'}]', 'Fusion Strike', '2', 'Chandelure V', '', '', 'Eighth', '320', 'https://images.pokemoncard.io/images/swsh8/swsh8-265.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Chandelure VMAX', '609', 'TPCI', 'Rare Rainbow', 'E', '11/12/2021', '', 'Colorless, Colorless', '[\'VMAX rule: When your Pokémon VMAX is Knocked Out, your opponent takes 3 Prize cards.\']', 'Sword & Shield', '265', 'VMAX', 'Pokémon', 'Fire', 'type: Water, value: ×2');
