('swsh9-18', '', '', '5ban Graphics', '[{\'name\': \'Explosive Fire\', \'cost\': [\'Fire\', \'Fire\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'130+\', \'text\': \'If this Pokémon has any damage counters on it, this attack does 100 more damage.\'}, {\'name\': \'Star Blaze\', \'cost\': [\'Fire\', \'Fire\', \'Fire\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'320\', \'text\': \"Discard 2 Energy from this Pokémon. (You can\'t use more than 1 VSTAR Power in a game.)\"}]', 'Brilliant Stars', '2', 'Charizard V', '', '', 'Eighth', '280', 'https://images.pokemoncard.io/images/swsh9/swsh9-18.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Charizard VSTAR', '6', 'TPCI', 'Rare Holo VSTAR', 'F', '2/25/2022', '', 'Colorless, Colorless', '[\'VSTAR rule: When your Pokémon VSTAR is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sword & Shield', '18', 'VSTAR', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('swsh9-180', '', '', 'kirisAki', '', 'Brilliant Stars', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh9/swsh9-180.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Roseannes Backup', '', 'TPCI', 'Rare Rainbow', 'F', '2/25/2022', '', '', '[\'Choose 1 or more:\\n• Shuffle a Pokémon from your discard pile into your deck.\\n• Shuffle a Pokémon Tool card from your discard pile into your deck.\\n• Shuffle a Stadium card from your discard pile into your deck.\\n• Shuffle an Energy card from your discard pile into your deck.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', '180', 'Supporter', 'Trainer', '', ''),
('swsh9-181', '[{\'name\': \'Reconstitute\', \'text\': \'You must discard 2 cards from your hand in order to use this Ability. Once during your turn, you may draw a card.\', \'type\': \'Ability\'}]', '', '5ban Graphics', '[{\'name\': \'Psyray\', \'cost\': [\'Psychic\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'110\', \'text\': \"Your opponent\'s Active Pokémon is now Confused.\"}]', 'Brilliant Stars', '2', '', '', '', 'Eighth', '210', 'https://images.pokemoncard.io/images/swsh9/swsh9-181.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Galarian Articuno V', '144', 'TPCI', 'Rare Secret', 'E', '2/25/2022', 'type: Fighting, value: -30', 'Colorless, Colorless', '[\'V rule: When your Pokémon V is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sword & Shield', '181', 'Basic, V', 'Pokémon', 'Psychic', 'type: Darkness, value: ×2'),
('swsh9-182', '[{\'name\': \'Fighting Instinct\', \'text\': \"This Pokémon\'s attacks cost Colorless less for each of your opponent\'s Pokémon V in play.\", \'type\': \'Ability\'}]', '', '5ban Graphics', '[{\'name\': \'Thunderous Kick\', \'cost\': [\'Fighting\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'170\', \'text\': \"Before doing damage, discard a Special Energy from your opponent\'s Active Pokémon.\"}]', 'Brilliant Stars', '1', '', '', '', 'Eighth', '200', 'https://images.pokemoncard.io/images/swsh9/swsh9-182.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Galarian Zapdos V', '145', 'TPCI', 'Rare Secret', 'E', '2/25/2022', '', 'Colorless', '[\'V rule: When your Pokémon V is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sword & Shield', '182', 'Basic, V', 'Pokémon', 'Fighting', 'type: Psychic, value: ×2'),
('swsh9-183', '[{\'name\': \'Direflame Wings\', \'text\': \"Once during your turn, you may attach a Darkness Energy card from your discard pile to this Pokémon. You can\'t use more than 1 Direflame Wings Ability each turn.\", \'type\': \'Ability\'}]', '', 'akyCG Works', '[{\'name\': \'Aura Burn\', \'cost\': [\'Darkness\', \'Darkness\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'190\', \'text\': \'This Pokémon also does 30 damage to itself.\'}]', 'Brilliant Stars', '2', '', '', '', 'Eighth', '220', 'https://images.pokemoncard.io/images/swsh9/swsh9-183.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Galarian Moltres V', '146', 'TPCI', 'Rare Secret', 'E', '2/25/2022', '', 'Colorless, Colorless', '[\'V rule: When your Pokémon V is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sword & Shield', '183', 'Basic, V', 'Pokémon', 'Darkness', 'type: Grass, value: ×2'),
('swsh9-184', '[{\'name\': \'Starbirth\', \'text\': \"During your turn, you may search your deck for up to 2 cards and put them into your hand. Then, shuffle your deck. (You can\'t use more than 1 VSTAR Power in a game.)\", \'type\': \'Ability\'}]', '', '5ban Graphics', '[{\'name\': \'Trinity Nova\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'200\', \'text\': \'Search your deck for up to 3 basic Energy cards and attach them to your Pokémon V in any way you like. Then, shuffle your deck.\'}]', 'Brilliant Stars', '2', 'Arceus V', '', '', 'Eighth', '280', 'https://images.pokemoncard.io/images/swsh9/swsh9-184.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Arceus VSTAR', '493', 'TPCI', 'Rare Secret', 'F', '2/25/2022', '', 'Colorless, Colorless', '[\'VSTAR rule: When your Pokémon VSTAR is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sword & Shield', '184', 'VSTAR', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('swsh9-185', '', '', 'ORBITALLINK Inc.', '', 'Brilliant Stars', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swsh9/swsh9-185.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Magma Basin', '', 'TPCI', 'Rare Secret', 'F', '2/25/2022', '', '', '[\"Once during each player\'s turn, that player may attach a Fire Energy card from their discard pile to 1 of their Benched Fire Pokémon. If a player attached Energy to a Pokémon in this way, put 2 damage counters on that Pokémon.\"]', 'Sword & Shield', '185', 'Stadium', 'Trainer', '', '');
