('swsh9tg-TG29', '', '', 'PLANETA Tsuji', '[{\'name\': \'Beatdown\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'100\', \'text\': \'\'}, {\'name\': \'G-Max One Blow\', \'cost\': [\'Fighting\', \'Fighting\', \'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'270\', \'text\': \"Discard all Energy from this Pokémon. This attack\'s damage isn\'t affected by any effects on your opponent\'s Active Pokémon.\"}]', 'Brilliant Stars Trainer Gallery', '3', 'Single Strike Urshifu V', '', '', 'Eighth', '330', 'https://images.pokemoncard.io/images/swsh9tg/swsh9tg-TG29.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Single Strike Urshifu VMAX', '892', 'TPCI', 'Rare Secret', 'E', '2/25/2022', '', 'Colorless, Colorless, Colorless', '[\'VMAX rule: When your Pokémon VMAX is Knocked Out, your opponent takes 3 Prize cards.\']', 'Sword & Shield', 'TG29', 'VMAX, Single Strike', 'Pokémon', 'Fighting', 'type: Psychic, value: ×2'),
('swsh9tg-TG30', '', '', 'PLANETA Tsuji', '[{\'name\': \'Gale Thrust\', \'cost\': [\'Fighting\'], \'convertedEnergyCost\': 1, \'damage\': \'30+\', \'text\': \'If this Pokémon moved from your Bench to the Active Spot this turn, this attack does 120 more damage.\'}, {\'name\': \'G-Max Rapid Flow\', \'cost\': [\'Fighting\', \'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'\', \'text\': \"Discard all Energy from this Pokémon. This attack does 120 damage to 2 of your opponent\'s Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'Brilliant Stars Trainer Gallery', '2', 'Rapid Strike Urshifu V', '', '', 'Eighth', '330', 'https://images.pokemoncard.io/images/swsh9tg/swsh9tg-TG30.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Rapid Strike Urshifu VMAX', '892', 'TPCI', 'Rare Secret', 'E', '2/25/2022', '', 'Colorless, Colorless', '[\'VMAX rule: When your Pokémon VMAX is Knocked Out, your opponent takes 3 Prize cards.\']', 'Sword & Shield', 'TG30', 'VMAX, Rapid Strike', 'Pokémon', 'Fighting', 'type: Psychic, value: ×2'),
('swshp-SWSH001', '', '', 'kirisAki', '[{\'name\': \'Branch Poke\', \'cost\': [\'Grass\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'\'}]', 'SWSH Black Star Promos', '1', '', 'Thwackey', 'When it uses its special stick to strike up a beat, the sound waves produced carry revitalizing energy to the plants and flowers in the area.', 'Eighth', '60', 'https://images.pokemoncard.io/images/swshp/swshp-SWSH001.png', 'unlimited: Legal, expanded: Legal', '', 'Grookey', '810', 'TPCI', 'Promo', 'D', '11/15/2019', '', 'Colorless', '', 'Sword & Shield', 'SWSH001', 'Basic', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('swshp-SWSH002', '', '', 'Hitoshi Ariga', '[{\'name\': \'Super Singe\', \'cost\': [\'Fire\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \"Flip a coin. If heads, your opponent\'s Active Pokémon is now Burned.\"}]', 'SWSH Black Star Promos', '1', '', 'Raboot', 'A warm-up of running around gets fire energy coursing through this Pokémons body. Once that happens, its ready to fight at full power.', 'Eighth', '60', 'https://images.pokemoncard.io/images/swshp/swshp-SWSH002.png', 'unlimited: Legal, expanded: Legal', '', 'Scorbunny', '813', 'TPCI', 'Promo', 'D', '11/15/2019', '', 'Colorless', '', 'Sword & Shield', 'SWSH002', 'Basic', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('swshp-SWSH003', '', '', 'Mizue', '[{\'name\': \'Bind\', \'cost\': [\'Water\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \"Flip a coin. If heads, your opponent\'s Active Pokémon is now Paralyzed.\"}]', 'SWSH Black Star Promos', '1', '', 'Drizzile', 'When scared, this Pokémon cries. Its tears pack the chemical punch of 100 onions, and attackers wont be able to resist weeping.', 'Eighth', '60', 'https://images.pokemoncard.io/images/swshp/swshp-SWSH003.png', 'unlimited: Legal, expanded: Legal', '', 'Sobble', '816', 'TPCI', 'Promo', 'D', '11/15/2019', '', 'Colorless', '', 'Sword & Shield', 'SWSH003', 'Basic', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
