('swshp-SWSH055', '', '', 'PLANETA Igarashi', '[{\'name\': \'Confounding Pulse\', \'cost\': [\'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'\', \'text\': \"Switch 1 of your opponent\'s Benched Pokémon with their Active Pokémon. The new Active Pokémon is now Confused.\"}, {\'name\': \'Mental Crush\', \'cost\': [\'Psychic\', \'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'90+\', \'text\': \"If your opponent\'s Active Pokémon is Confused, this attack does 90 more damage.\"}]', 'SWSH Black Star Promos', '2', '', '', '', 'Eighth', '200', 'https://images.pokemoncard.io/images/swshp/swshp-SWSH055.png', 'unlimited: Legal, expanded: Legal', '', 'Hatterene V', '858', 'TPCI', 'Promo', 'D', '11/15/2019', 'type: Fighting, value: -30', 'Colorless, Colorless', '[\'V rule: When your Pokémon V is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sword & Shield', 'SWSH055', 'Basic, V', 'Pokémon', 'Psychic', 'type: Darkness, value: ×2'),
('swshp-SWSH056', '', '', '5ban Graphics', '[{\'name\': \'Spark\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'20\', \'text\': \"This attack also does 20 damage to 1 of your opponent\'s Benched Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}, {\'name\': \'Electro Wheel\', \'cost\': [\'Lightning\', \'Lightning\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'150\', \'text\': \'Discard an Energy from this Pokémon. If you do, switch it with 1 of your Benched Pokémon.\'}]', 'SWSH Black Star Promos', '2', '', '', '', 'Eighth', '170', 'https://images.pokemoncard.io/images/swshp/swshp-SWSH056.png', 'unlimited: Legal, expanded: Legal', '', 'Morpeko V', '877', 'TPCI', 'Promo', 'D', '11/15/2019', '', 'Colorless, Colorless', '[\'V rule: When your Pokémon V is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sword & Shield', 'SWSH056', 'Basic, V', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
('swshp-SWSH057', '', '', '5ban Graphics', '[{\'name\': \'Bite\', \'cost\': [\'Darkness\'], \'convertedEnergyCost\': 1, \'damage\': \'40\', \'text\': \'\'}, {\'name\': \'Spiky Knuckle\', \'cost\': [\'Darkness\', \'Darkness\', \'Darkness\'], \'convertedEnergyCost\': 3, \'damage\': \'200\', \'text\': \'Put 2 Darkness Energy attached to this Pokémon into your hand.\'}]', 'SWSH Black Star Promos', '2', '', '', '', 'Eighth', '220', 'https://images.pokemoncard.io/images/swshp/swshp-SWSH057.png', 'unlimited: Legal, expanded: Legal', '', 'Grimmsnarl V', '861', 'TPCI', 'Promo', 'D', '11/15/2019', '', 'Colorless, Colorless', '[\'V rule: When your Pokémon V is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sword & Shield', 'SWSH057', 'Basic, V', 'Pokémon', 'Darkness', 'type: Grass, value: ×2'),
('swshp-SWSH058', '', '', 'sui', '[{\'name\': \'Decorate\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Attach any number of basic Energy cards from your hand to your Pokémon in any way you like.\'}, {\'name\': \'Draining Kiss\', \'cost\': [\'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'50\', \'text\': \'Heal 30 damage from this Pokémon.\'}]', 'SWSH Black Star Promos', '1', 'Milcery', '', 'When it trusts a Trainer, it will treat them to berries its decorated with cream.', 'Eighth', '110', 'https://images.pokemoncard.io/images/swshp/swshp-SWSH058.png', 'unlimited: Legal, expanded: Legal', '', 'Alcremie', '869', 'TPCI', 'Promo', 'D', '11/15/2019', '', 'Colorless', '', 'Sword & Shield', 'SWSH058', 'Stage 1', 'Pokémon', 'Psychic', 'type: Metal, value: ×2'),
('swshp-SWSH059', '[{\'name\': \'Untamed Shout\', \'text\': \"When you play this Pokémon from your hand to evolve 1 of your Pokémon during your turn, you may put 3 damage counters on 1 of your opponent\'s Pokémon.\", \'type\': \'Ability\'}]', '', 'Hasuno', '[{\'name\': \'Obstruct\', \'cost\': [\'Darkness\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'90\', \'text\': \"During your opponent\'s next turn, prevent all damage done to this Pokémon by attacks from Basic Pokémon.\"}]', 'SWSH Black Star Promos', '2', 'Galarian Linoone', '', 'It evolved after experiencing numerous fights. While crossing its arms, it lets out a shout that would make any opponent flinch.', 'Eighth', '160', 'https://images.pokemoncard.io/images/swshp/swshp-SWSH059.png', 'unlimited: Legal, expanded: Legal', '', 'Galarian Obstagoon', '862', 'TPCI', 'Promo', 'D', '11/15/2019', '', 'Colorless, Colorless', '', 'Sword & Shield', 'SWSH059', 'Stage 2', 'Pokémon', 'Darkness', 'type: Grass, value: ×2'),
('swshp-SWSH060', '', '', 'Kazuma Koda', '[{\'name\': \'Metal Sharpener\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'30\', \'text\': \'Attach a Metal Energy card from your discard pile to 1 of your Pokémon.\'}, {\'name\': \'Power Beam\', \'cost\': [\'Metal\', \'Metal\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'110\', \'text\': \'\'}]', 'SWSH Black Star Promos', '2', '', '', 'Its body resembles polished metal, and its both lightweight and strong. The only drawback is that it rusts easily.', 'Eighth', '130', 'https://images.pokemoncard.io/images/swshp/swshp-SWSH060.png', 'unlimited: Legal, expanded: Legal', '', 'Duraludon', '884', 'TPCI', 'Promo', 'D', '11/15/2019', 'type: Grass, value: -30', 'Colorless, Colorless', '', 'Sword & Shield', 'SWSH060', 'Basic', 'Pokémon', 'Metal', 'type: Fire, value: ×2'),
('swshp-SWSH061', '', '', 'PLANETA Tsuji', '[{\'name\': \'Charge\', \'cost\': [\'Lightning\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Search your deck for up to 2 Lightning Energy cards and attach them to this Pokémon. Then, shuffle your deck.\'}, {\'name\': \'Thunderbolt\', \'cost\': [\'Lightning\', \'Lightning\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'200\', \'text\': \'Discard all Energy from this Pokémon.\'}]', 'SWSH Black Star Promos', '1', '', 'Raichu', '', 'Eighth', '190', 'https://images.pokemoncard.io/images/swshp/swshp-SWSH061.png', 'unlimited: Legal, expanded: Legal', '', 'Pikachu V', '25', 'TPCI', 'Promo', 'D', '11/15/2019', '', 'Colorless', '[\'V rule: When your Pokémon V is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sword & Shield', 'SWSH061', 'Basic, V', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
('swshp-SWSH062', '', '', 'PLANETA Mochizuki', '[{\'name\': \'G-Max Volt Tackle\', \'cost\': [\'Lightning\', \'Lightning\', \'Lightning\'], \'convertedEnergyCost\': 3, \'damage\': \'120+\', \'text\': \'You may discard all Energy from this Pokémon. If you do, this attack does 150 more damage.\'}]', 'SWSH Black Star Promos', '2', 'Pikachu V', 'Raichu', '', 'Eighth', '310', 'https://images.pokemoncard.io/images/swshp/swshp-SWSH062.png', 'unlimited: Legal, expanded: Legal', '', 'Pikachu VMAX', '25', 'TPCI', 'Promo', 'D', '11/15/2019', '', 'Colorless, Colorless', '[\'VMAX rule: When your Pokémon VMAX is Knocked Out, your opponent takes 3 Prize cards.\']', 'Sword & Shield', 'SWSH062', 'VMAX', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
