('swshp-SWSH102', '', '', 'aky CG Works', '[{\'name\': \'Forest Storm\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30×\', \'text\': \'This attack does 30 damage for each Grass Energy attached to all of your Pokémon.\'}, {\'name\': \'G-Max Bloom\', \'cost\': [\'Grass\', \'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'210\', \'text\': \'Heal 30 damage from this Pokémon.\'}]', 'SWSH Black Star Promos', '4', 'Venusaur V', '', '', 'Eighth', '330', 'https://images.pokemoncard.io/images/swshp/swshp-SWSH102.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Venusaur VMAX', '3', 'TPCI', 'Promo', 'E', '11/15/2019', '', 'Colorless, Colorless, Colorless, Colorless', '[\'VMAX rule: When your Pokémon VMAX is Knocked Out, your opponent takes 3 Prize cards.\']', 'Sword & Shield', 'SWSH102', 'VMAX', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('swshp-SWSH103', '', '', '5ban Graphics', '[{\'name\': \'Grand Falls\', \'cost\': [\'Water\', \'Water\', \'Water\'], \'convertedEnergyCost\': 3, \'damage\': \'120\', \'text\': \'Search your deck for up to 3 Water Energy cards and attach them to your Benched Pokémon in any way you like. Then, shuffle your deck.\'}, {\'name\': \'G-Max Bombard\', \'cost\': [\'Water\', \'Water\', \'Water\', \'Water\'], \'convertedEnergyCost\': 4, \'damage\': \'220\', \'text\': \"This attack also does 30 damage to 2 of your opponent\'s Benched Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'SWSH Black Star Promos', '3', 'Blastoise V', '', '', 'Eighth', '330', 'https://images.pokemoncard.io/images/swshp/swshp-SWSH103.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Blastoise VMAX', '9', 'TPCI', 'Promo', 'E', '11/15/2019', '', 'Colorless, Colorless, Colorless', '[\'VMAX rule: When your Pokémon VMAX is Knocked Out, your opponent takes 3 Prize cards.\']', 'Sword & Shield', 'SWSH103', 'VMAX', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
