('swshp-SWSH107', '', '', '5ban Graphics', '[{\'name\': \'Spiral Kick\', \'cost\': [\'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'40\', \'text\': \'\'}, {\'name\': \'Sonic Legs\', \'cost\': [\'Fighting\', \'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'90\', \'text\': \"This attack also does 20 damage to 2 of your opponent\'s Benched Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'SWSH Black Star Promos', '2', '', '', '', 'Eighth', '220', 'https://images.pokemoncard.io/images/swshp/swshp-SWSH107.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Rapid Strike Urshifu V', '892', 'TPCI', 'Promo', 'E', '11/15/2019', '', 'Colorless, Colorless', '[\'V rule: When your Pokémon V is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sword & Shield', 'SWSH107', 'Basic, V, Rapid Strike', 'Pokémon', 'Fighting', 'type: Psychic, value: ×2'),
('swshp-SWSH108', '[{\'name\': \"Emperor\'s Eyes\", \'text\': \"As long as this Pokémon is in the Active Spot, your opponent\'s Basic Pokémon in play have no Abilities, except for Pokémon with a Rule Box (Pokémon V, Pokémon-GX, etc. have Rule Boxes).\", \'type\': \'Ability\'}]', '', 'PLANETA Mochizuki', '[{\'name\': \'Swirling Slice\', \'cost\': [\'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'130\', \'text\': \'Move an Energy from this Pokémon to 1 of your Benched Pokémon.\'}]', 'SWSH Black Star Promos', '2', '', '', '', 'Eighth', '210', 'https://images.pokemoncard.io/images/swshp/swshp-SWSH108.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Empoleon V', '395', 'TPCI', 'Promo', 'E', '11/15/2019', '', 'Colorless, Colorless', '[\'V rule: When your Pokémon V is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sword & Shield', 'SWSH108', 'Basic, V, Rapid Strike', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('swshp-SWSH109', '', '', 'PLANETA Tsuji', '[{\'name\': \'Cragalanche\', \'cost\': [\'Darkness\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60\', \'text\': \"Discard the top 2 cards of your opponent\'s deck.\"}, {\'name\': \'Single Strike Crush\', \'cost\': [\'Darkness\', \'Darkness\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'240\', \'text\': \'Discard the top 4 cards of your deck.\'}]', 'SWSH Black Star Promos', '3', '', '', '', 'Eighth', '230', 'https://images.pokemoncard.io/images/swshp/swshp-SWSH109.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Tyranitar V', '248', 'TPCI', 'Promo', 'E', '11/15/2019', '', 'Colorless, Colorless, Colorless', '[\'V rule: When your Pokémon V is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sword & Shield', 'SWSH109', 'Basic, V, Single Strike', 'Pokémon', 'Darkness', 'type: Grass, value: ×2'),
('swshp-SWSH110', '[{\'name\': \'Dark Asset\', \'text\': \"When you play this Pokémon from your hand onto your Bench during your turn, you may draw cards until you have 6 cards in your hand. You can\'t use more than 1 Dark Asset Ability each turn.\", \'type\': \'Ability\'}]', '', 'PLANETA Mochizuki', '[{\'name\': \'Venomous Fang\', \'cost\': [\'Darkness\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'70\', \'text\': \"Your opponent\'s Active Pokémon is now Poisoned.\"}]', 'SWSH Black Star Promos', '1', '', '', '', 'Eighth', '180', 'https://images.pokemoncard.io/images/swshp/swshp-SWSH110.png', 'unlimited: Legal, expanded: Legal', '', 'Crobat V', '169', 'TPCI', 'Promo', 'D', '11/15/2019', '', 'Colorless', '[\'V rule: When your Pokémon V is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sword & Shield', 'SWSH110', 'Basic, V', 'Pokémon', 'Darkness', 'type: Fighting, value: ×2');
INSERT INTO `cards` (`id`, `abilities`, `ancient_trait`, `artist`, `attacks`, `card_set`, `converted`, `evolves_from`, `evolves_to`, `flavor_text`, `generation`, `hp`, `img`, `legalities`, `level`, `name`, `national_pokedex_numbers`, `publisher`, `rarity`, `regulation_mark`, `release_date`, `resistances`, `retreat_cost`, `rules`, `series`, `set_num`, `subtypes`, `supertype`, `types`, `weakness`) VALUES
('swshp-SWSH111', '', '', 'Saki Hayashiro', '[{\'name\': \'Libra Horn\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'\', \'text\': \"Put damage counters on 1 of your opponent\'s Pokémon until its remaining HP is 100.\"}, {\'name\': \'Psychic\', \'cost\': [\'Psychic\', \'Psychic\'], \'convertedEnergyCost\': 2, \'damage\': \'60+\', \'text\': \"This attack does 30 more damage for each Energy attached to your opponent\'s Active Pokémon.\"}]', 'SWSH Black Star Promos', '1', '', '', '', 'Eighth', '210', 'https://images.pokemoncard.io/images/swshp/swshp-SWSH111.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Galarian Rapidash V', '78', 'TPCI', 'Promo', 'E', '11/15/2019', 'type: Fighting, value: -30', 'Colorless', '[\'V rule: When your Pokémon V is Knocked Out, your opponent takes 2 Prize cards.\']', 'Sword & Shield', 'SWSH111', 'Basic, V', 'Pokémon', 'Psychic', 'type: Darkness, value: ×2'),
('swshp-SWSH112', '[{\'name\': \'Crisis Power\', \'text\': \"This Pokémon\'s attacks do 30 more damage to your opponent\'s Active Pokémon for each Prize card your opponent has taken (before applying Weakness and Resistance).\", \'type\': \'Ability\'}]', '', 'Anesaki Dynamic', '[{\'name\': \'Fireball Shot\', \'cost\': [\'Fire\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'150\', \'text\': \"During your next turn, this Pokémon can\'t attack.\"}]', 'SWSH Black Star Promos', '1', 'Raboot', '', 'Its skilled at both offense and defense, and it gets pumped up when cheered on. But if it starts showboating, it could put itself in a tough spot.', 'Eighth', '170', 'https://images.pokemoncard.io/images/swshp/swshp-SWSH112.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Cinderace', '815', 'TPCI', 'Promo', 'E', '11/15/2019', '', 'Colorless', '', 'Sword & Shield', 'SWSH112', 'Stage 2, Single Strike', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('swshp-SWSH113', '[{\'name\': \'Quick Shooting\', \'text\': \"Once during your turn, you may put 2 damage counters on 1 of your opponent\'s Pokémon.\", \'type\': \'Ability\'}]', '', 'AKIRA EGAWA', '[{\'name\': \'Waterfall\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'70\', \'text\': \'\'}]', 'SWSH Black Star Promos', '1', 'Drizzile', '', 'Its nictitating membranes let it pick out foes weak points so it can precisely blast them with water that shoots from its fingertips at Mach 3.', 'Eighth', '150', 'https://images.pokemoncard.io/images/swshp/swshp-SWSH113.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Inteleon', '818', 'TPCI', 'Promo', 'E', '11/15/2019', '', 'Colorless', '', 'Sword & Shield', 'SWSH113', 'Stage 2, Rapid Strike', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('swshp-SWSH114', '', '', 'Kagemaru Himeno', '[{\'name\': \'Crescent Glow\', \'cost\': [\'Psychic\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Search your deck for a Psychic Energy card and attach it to 1 of your Pokémon. If you go second and it\'s your first turn, instead search for up to 3 Psychic Energy cards and attach them to 1 of your Pokémon. Then, shuffle your deck.\"}, {\'name\': \'Photon Laser\', \'cost\': [\'Psychic\', \'Psychic\'], \'convertedEnergyCost\': 2, \'damage\': \'30+\', \'text\': \'If you have at least 5 Energy in play, this attack does 90 more damage.\'}]', 'SWSH Black Star Promos', '1', '', '', 'Those who sleep holding Cresselias feather are assured of joyful dreams. It is said to represent the crescent moon.', 'Eighth', '120', 'https://images.pokemoncard.io/images/swshp/swshp-SWSH114.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Cresselia', '488', 'TPCI', 'Promo', 'E', '11/15/2019', 'type: Fighting, value: -30', 'Colorless', '', 'Sword & Shield', 'SWSH114', 'Basic', 'Pokémon', 'Psychic', 'type: Darkness, value: ×2'),
('swshp-SWSH115', '[{\'name\': \'Throwing Coach\', \'text\': \"Your Rapid Strike Pokémon\'s attacks do 30 more damage to your opponent\'s Benched Pokémon V and Benched Pokémon-GX (before applying Weakness and Resistance). You can\'t apply more than 1 Throwing Coach Ability at a time.\", \'type\': \'Ability\'}]', '', 'Teeziro', '[{\'name\': \'Fling\', \'cost\': [\'Fighting\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"This attack does 20 damage to 1 of your opponent\'s Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'SWSH Black Star Promos', '1', '', '', 'Passimian live in groups of about 20, with each member performing an assigned role. Through cooperation, the group survives.', 'Eighth', '110', 'https://images.pokemoncard.io/images/swshp/swshp-SWSH115.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Passimian', '766', 'TPCI', 'Promo', 'E', '11/15/2019', '', 'Colorless', '', 'Sword & Shield', 'SWSH115', 'Basic, Rapid Strike', 'Pokémon', 'Fighting', 'type: Psychic, value: ×2'),
('swshp-SWSH116', '', '', 'Atsushi Furusawa', '[{\'name\': \'Famished\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Draw a card.\'}, {\'name\': \'Thunder Shock\', \'cost\': [\'Lightning\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'40\', \'text\': \"Flip a coin. If heads, your opponent\'s Active Pokémon is now Paralyzed.\"}]', 'SWSH Black Star Promos', '1', '', '', 'As it eats the seeds stored up in its pocket-like pouches, this Pokémon is not just satisfying its constant hunger. Its also generating electricity.', 'Eighth', '80', 'https://images.pokemoncard.io/images/swshp/swshp-SWSH116.png', 'unlimited: Legal, expanded: Legal', '', 'Morpeko', '877', 'TPCI', 'Promo', 'D', '11/15/2019', '', 'Colorless', '', 'Sword & Shield', 'SWSH116', 'Basic', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
('swshp-SWSH117', '', '', 'Kagemaru Himeno', '[{\'name\': \'Stampede\', \'cost\': [\'Fighting\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'\'}, {\'name\': \'Strike Back\', \'cost\': [\'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30×\', \'text\': \'This attack does 30 damage for each damage counter on this Pokémon.\'}]', 'SWSH Black Star Promos', '2', '', 'Donphan', 'It is strong despite its compact size. It can easily pick up and carry an adult human on its back.', 'Eighth', '70', 'https://images.pokemoncard.io/images/swshp/swshp-SWSH117.png', 'unlimited: Legal, expanded: Legal', '', 'Phanpy', '231', 'TPCI', 'Promo', 'D', '11/15/2019', '', 'Colorless, Colorless', '', 'Sword & Shield', 'SWSH117', 'Basic', 'Pokémon', 'Fighting', 'type: Grass, value: ×2'),
('swshp-SWSH118', '', '', 'Yuu Nishida', '[{\'name\': \'Signs of Evolution\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Search your deck for a card that evolves from Eevee, reveal it, and put it into your hand. Then, shuffle your deck.\'}, {\'name\': \'Wild Kick\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'Flip a coin. If tails, this attack does nothing.\'}]', 'SWSH Black Star Promos', '1', '', 'Vaporeon, Jolteon, Flareon, Sylveon, Espeon, Umbreon, Leafeon, Glaceon', 'It has the ability to alter the composition of its body to suit its surrounding environment.', 'Eighth', '60', 'https://images.pokemoncard.io/images/swshp/swshp-SWSH118.png', 'unlimited: Legal, expanded: Legal', '', 'Eevee', '133', 'TPCI', 'Promo', 'D', '11/15/2019', '', 'Colorless', '', 'Sword & Shield', 'SWSH118', 'Basic', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('swshp-SWSH119', '', '', 'Yuya Oka', '[{\'name\': \'Slap Push\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'\'}, {\'name\': \'Single Strike Tackle\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'120\', \'text\': \'This Pokémon also does 30 damage to itself.\'}]', 'SWSH Black Star Promos', '4', '', '', 'This Pokémons stomach is so strong, even eating moldy or rotten food will not affect it.', 'Eighth', '140', 'https://images.pokemoncard.io/images/swshp/swshp-SWSH119.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Snorlax', '143', 'TPCI', 'Promo', 'E', '11/15/2019', '', 'Colorless, Colorless, Colorless, Colorless', '', 'Sword & Shield', 'SWSH119', 'Basic, Single Strike', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('swshp-SWSH120', '', '', 'Sanosuke Sakuma', '', 'SWSH Black Star Promos', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swshp/swshp-SWSH120.png', 'unlimited: Legal, expanded: Legal', '', 'Marnie', '', 'TPCI', 'Promo', 'D', '11/15/2019', '', '', '[\'Each player shuffles their hand and puts it on the bottom of their deck. If either player put any cards on the bottom of their deck in this way, you draw 5 cards, and your opponent draws 4 cards.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', 'SWSH120', 'Supporter', 'Trainer', '', ''),
('swshp-SWSH121', '', '', 'Naoki Saito', '', 'SWSH Black Star Promos', '', '', '', '', 'Eighth', '', 'https://images.pokemoncard.io/images/swshp/swshp-SWSH121.png', 'unlimited: Legal, expanded: Legal', '', 'Marnie', '', 'TPCI', 'Promo', 'D', '11/15/2019', '', '', '[\'Each player shuffles their hand and puts it on the bottom of their deck. If either player put any cards on the bottom of their deck in this way, you draw 5 cards, and your opponent draws 4 cards.\', \'You may play only 1 Supporter card during your turn.\']', 'Sword & Shield', 'SWSH121', 'Supporter', 'Trainer', '', ''),
('swshp-SWSH122', '[{\'name\': \'Dynamotor\', \'text\': \'Once during your turn (before your attack), you may attach a Lightning Energy card from your discard pile to 1 of your Benched Pokémon.\', \'type\': \'Ability\'}]', '', 'Pani Kobayashi', '[{\'name\': \'Electro Ball\', \'cost\': [\'Lightning\', \'Lightning\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50\', \'text\': \'\'}]', 'SWSH Black Star Promos', '2', 'Mareep', 'Ampharos', 'It stores electricity in its fluffy fleece. If it stores up too much, it will start to go bald in those patches.', 'Eighth', '90', 'https://images.pokemoncard.io/images/swshp/swshp-SWSH122.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Flaaffy', '180', 'TPCI', 'Promo', 'E', '11/15/2019', '', 'Colorless, Colorless', '', 'Sword & Shield', 'SWSH122', 'Stage 1', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
('swshp-SWSH123', '[{\'name\': \'Cruel Charge\', \'text\': \'When you play this Pokémon from your hand onto your Bench during your turn, you may attach up to 2 Psychic Energy cards from your hand to this Pokémon.\', \'type\': \'Ability\'}]', '', 'Shin Nagasawa', '[{\'name\': \'Psylaser\', \'cost\': [\'Psychic\', \'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'\', \'text\': \"Discard all Psychic Energy from this Pokémon. This attack does 120 damage to 1 of your opponent\'s Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'SWSH Black Star Promos', '2', '', '', 'Known as Articuno, this Pokémon fires beams that can immobilize opponents as if they had been frozen solid.', 'Eighth', '120', 'https://images.pokemoncard.io/images/swshp/swshp-SWSH123.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Galarian Articuno', '144', 'TPCI', 'Promo', 'E', '11/15/2019', 'type: Fighting, value: -30', 'Colorless, Colorless', '', 'Sword & Shield', 'SWSH123', 'Basic', 'Pokémon', 'Psychic', 'type: Darkness, value: ×2'),
('swshp-SWSH124', '[{\'name\': \'Strong Legs Charge\', \'text\': \'When you play this Pokémon from your hand onto your Bench during your turn, you may attach up to 2 Fighting Energy cards from your hand to this Pokémon.\', \'type\': \'Ability\'}]', '', 'Oswaldo KATO', '[{\'name\': \'Zapper Kick\', \'cost\': [\'Fighting\', \'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'70\', \'text\': \"You may discard all Energy from this Pokémon. If you do, your opponent\'s Active Pokémon is now Paralyzed.\"}]', 'SWSH Black Star Promos', '', '', '', 'One kick from its powerful legs will pulverize a dump truck. Supposedly, this Pokémon runs through the mountains at over 180 mph.', 'Eighth', '110', 'https://images.pokemoncard.io/images/swshp/swshp-SWSH124.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Galarian Zapdos', '145', 'TPCI', 'Promo', 'E', '11/15/2019', '', '', '', 'Sword & Shield', 'SWSH124', 'Basic', 'Pokémon', 'Fighting', 'type: Psychic, value: ×2'),
