('xy0-34', '', '', '5ban Graphics', '', 'Kalos Starter Set', '', '', '', '', 'Sixth', '', 'https://images.pokemoncard.io/images/xy0/xy0-34.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Crushing Hammer', '', 'TPCI', '', '', '11/08/2013', '', '', '[\"Flip a coin. If heads, discard an Energy attached to 1 of your opponent\'s Pokémon.\", \'You may play as many Item cards as you like during your turn (before your attack).\']', 'XY', '34', 'Item', 'Trainer', '', ''),
('xy0-35', '', '', '5ban Graphics', '', 'Kalos Starter Set', '', '', '', '', 'Sixth', '', 'https://images.pokemoncard.io/images/xy0/xy0-35.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Poké Ball', '', 'TPCI', '', '', '11/08/2013', '', '', '[\'Flip a coin. If heads, search your deck for a Pokémon, reveal it, and put it into your hand. Shuffle your deck afterward.\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'XY', '35', 'Item', 'Trainer', '', ''),
('xy0-36', '', '', '5ban Graphics', '', 'Kalos Starter Set', '', '', '', '', 'Sixth', '', 'https://images.pokemoncard.io/images/xy0/xy0-36.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Pokémon Catcher', '', 'TPCI', '', '', '11/08/2013', '', '', '[\"Flip a coin. If heads, switch 1 of your opponent\'s Benched Pokémon with his or her Active Pokémon.\", \'You may play as many Item cards as you like during your turn (before your attack).\']', 'XY', '36', 'Item', 'Trainer', '', ''),
('xy0-37', '', '', '5ban Graphics', '', 'Kalos Starter Set', '', '', '', '', 'Sixth', '', 'https://images.pokemoncard.io/images/xy0/xy0-37.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Potion', '', 'TPCI', '', '', '11/08/2013', '', '', '[\'Heal 30 damage from 1 of your Pokémon.\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'XY', '37', 'Item', 'Trainer', '', ''),
('xy0-38', '', '', '5ban Graphics', '', 'Kalos Starter Set', '', '', '', '', 'Sixth', '', 'https://images.pokemoncard.io/images/xy0/xy0-38.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Switch', '', 'TPCI', '', '', '11/08/2013', '', '', '[\'Switch your Active Pokémon with 1 of your Benched Pokémon.\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'XY', '38', 'Item', 'Trainer', '', ''),
('xy0-39', '', '', 'Ken Sugimori', '', 'Kalos Starter Set', '', '', '', '', 'Sixth', '', 'https://images.pokemoncard.io/images/xy0/xy0-39.png', 'unlimited: Legal, expanded: Legal', '', 'Tierno', '', 'TPCI', '', '', '11/08/2013', '', '', '[\'Draw 3 cards.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'XY', '39', 'Supporter', 'Trainer', '', ''),
('xy0-4', '', '', '5ban Graphics', '[{\'name\': \'Leech Seed\', \'cost\': [\'Grass\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'Heal 10 damage from this Pokémon.\'}, {\'name\': \'Needle Arm\', \'cost\': [\'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50\', \'text\': \'\'}]', 'Kalos Starter Set', '2', 'Chespin', 'Chesnaught', 'It relies on its sturdy shell to deflect predators attacks. It counterattacks with its sharp quills.', 'Sixth', '90', 'https://images.pokemoncard.io/images/xy0/xy0-4.png', 'unlimited: Legal, expanded: Legal', '', 'Quilladin', '651', 'TPCI', '', '', '11/08/2013', '', 'Colorless, Colorless', '', 'XY', '4', 'Stage 1', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('xy0-5', '', '', '5ban Graphics', '[{\'name\': \'Needle Arm\', \'cost\': [\'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50\', \'text\': \'\'}, {\'name\': \'Tumbling Attack\', \'cost\': [\'Grass\', \'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'80+\', \'text\': \'Flip a coin. If heads, this attack does 40 more damage.\'}]', 'Kalos Starter Set', '4', 'Quilladin', '', 'Its Tackle is forceful enough to flip a 50-ton tank. It shields its allies from danger with its own body.', 'Sixth', '150', 'https://images.pokemoncard.io/images/xy0/xy0-5.png', 'unlimited: Legal, expanded: Legal', '', 'Chesnaught', '652', 'TPCI', '', '', '11/08/2013', '', 'Colorless, Colorless, Colorless, Colorless', '', 'XY', '5', 'Stage 2', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('xy0-6', '', '', 'Mitsuhiro Arita', '[{\'name\': \'Combustion\', \'cost\': [\'Fire\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'\'}]', 'Kalos Starter Set', '2', '', 'Magcargo', 'A common sight in volcanic areas, it slowly slithers around in a constant search for warm places.', 'Sixth', '80', 'https://images.pokemoncard.io/images/xy0/xy0-6.png', 'unlimited: Legal, expanded: Legal', '', 'Slugma', '218', 'TPCI', '', '', '11/08/2013', '', 'Colorless, Colorless', '', 'XY', '6', 'Basic', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('xy0-7', '', '', 'Naoyo Kimura', '[{\'name\': \'Collect\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Draw a card.\'}, {\'name\': \'Fury Swipes\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'10×\', \'text\': \'Flip 3 coins. This attack does 10 damage times the number of heads.\'}]', 'Kalos Starter Set', '1', '', 'Simisear', 'Very intelligent, it roasts berries before eating them. It likes to help people.', 'Sixth', '70', 'https://images.pokemoncard.io/images/xy0/xy0-7.png', 'unlimited: Legal, expanded: Legal', '', 'Pansear', '513', 'TPCI', '', '', '11/08/2013', '', 'Colorless', '', 'XY', '7', 'Basic', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('xy0-8', '', '', '5ban Graphics', '[{\'name\': \'Scratch\', \'cost\': [\'Fire\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'\'}, {\'name\': \'Live Coal\', \'cost\': [\'Fire\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'\'}]', 'Kalos Starter Set', '1', '', 'Braixen', 'Eating a twig fills it with energy, and its roomy ears give vent to air hotter than 390 degrees Fahrenheit.', 'Sixth', '60', 'https://images.pokemoncard.io/images/xy0/xy0-8.png', 'unlimited: Legal, expanded: Legal', '', 'Fennekin', '653', 'TPCI', '', '', '11/08/2013', '', 'Colorless', '', 'XY', '8', 'Basic', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('xy0-9', '', '', '5ban Graphics', '[{\'name\': \'Firebreathing\', \'cost\': [\'Fire\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20+\', \'text\': \'Flip a coin. If heads, this attack does 20 more damage.\'}, {\'name\': \'Flame Tail\', \'cost\': [\'Fire\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60\', \'text\': \'\'}]', 'Kalos Starter Set', '1', 'Fennekin', 'Delphox', 'It has a twig stuck in its tail. With friction from its tail fur, it sets the twig on fire and launches into battle.', 'Sixth', '80', 'https://images.pokemoncard.io/images/xy0/xy0-9.png', 'unlimited: Legal, expanded: Legal', '', 'Braixen', '654', 'TPCI', '', '', '11/08/2013', '', 'Colorless', '', 'XY', '9', 'Stage 1', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('xy1-1', '', '', 'Eske Yoshinob', '[{\'name\': \'Poison Powder\', \'cost\': [\'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60\', \'text\': \"Your opponent\'s Active Pokémon is now Poisoned.\"}, {\'name\': \'Jungle Hammer\', \'cost\': [\'Grass\', \'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'90\', \'text\': \'Heal 30 damage from this Pokémon.\'}]', 'XY', '4', '', 'M Venusaur-EX', '', 'Sixth', '180', 'https://images.pokemoncard.io/images/xy1/xy1-1.png', 'unlimited: Legal, expanded: Legal', '', 'Venusaur-EX', '3', 'TPCI', 'Rare Holo EX', '', '02/05/2014', '', 'Colorless, Colorless, Colorless, Colorless', '[\'Pokémon-EX rule: When a Pokémon-EX has been Knocked Out, your opponent takes 2 Prize cards.\']', 'XY', '1', 'Basic, EX', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('xy1-10', '', '', 'Midori Harada', '[{\'name\': \'Vine Whip\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'\'}, {\'name\': \'Leech Seed\', \'cost\': [\'Grass\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'Heal 10 damage from this Pokémon.\'}]', 'XY', '1', '', 'Simisage', 'It shares the leaf on its head with weary-looking Pokémon. These leaves are known to relieve stress.', 'Sixth', '60', 'https://images.pokemoncard.io/images/xy1/xy1-10.png', 'unlimited: Legal, expanded: Legal', '', 'Pansage', '511', 'TPCI', 'Common', '', '02/05/2014', '', 'Colorless', '', 'XY', '10', 'Basic', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('xy1-100', '', '', 'Midori Harada', '[{\'name\': \'Take Down\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'30\', \'text\': \'This Pokémon does 10 damage to itself.\'}, {\'name\': \'Seething Anger\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'30×\', \'text\': \'Flip a coin for each damage counter on this Pokémon. This attack does 30 damage times the number of heads.\'}]', 'XY', '2', '', '', 'After heightening its will to fight by whipping itself with its three tails, it charges at full speed.', 'Sixth', '110', 'https://images.pokemoncard.io/images/xy1/xy1-100.png', 'unlimited: Legal, expanded: Legal', '', 'Tauros', '128', 'TPCI', 'Rare', '', '02/05/2014', '', 'Colorless, Colorless', '', 'XY', '100', 'Basic', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('xy1-101', '', '', 'Naoyo Kimura', '[{\'name\': \'Glare\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Flip a coin. If heads, your opponent\'s Active Pokémon is now Paralyzed.\"}, {\'name\': \'Second Bite\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'10+\', \'text\': \"Does 10 more damage for each damage counter on your opponent\'s Active Pokémon.\"}]', 'XY', '', '', '', 'When spotted, this Pokémon escapes backwards by furiously boring into the ground with its tail.', 'Sixth', '40', 'https://images.pokemoncard.io/images/xy1/xy1-101.png', 'unlimited: Legal, expanded: Legal', '', 'Dunsparce', '206', 'TPCI', 'Uncommon', '', '02/05/2014', '', '', '', 'XY', '101', 'Basic', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('xy1-102', '', '', 'sui', '[{\'name\': \'Aerial Ace\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'10+\', \'text\': \'Flip a coin. If heads, this attack does 30 more damage.\'}]', 'XY', '1', '', 'Swellow', 'It has a gutsy spirit that makes it bravely take on tough foes. It flies in search of warm climates.', 'Sixth', '50', 'https://images.pokemoncard.io/images/xy1/xy1-102.png', 'unlimited: Legal, expanded: Legal', '', 'Taillow', '276', 'TPCI', 'Common', '', '02/05/2014', 'type: Fighting, value: -20', 'Colorless', '', 'XY', '102', 'Basic', 'Pokémon', 'Colorless', 'type: Lightning, value: ×2'),
('xy1-103', '[{\'name\': \'Drive Off\', \'text\': \'Once during your turn (before your attack), you may have your opponent switch his or her Active Pokémon with 1 of his or her Benched Pokémon.\', \'type\': \'Ability\'}]', '', 'Mizue', '[{\'name\': \'Wing Attack\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60\', \'text\': \'\'}]', 'XY', '1', 'Taillow', '', 'If its two tail feathers are standing at attention, it is proof of good health. It soars elegantly in the sky.', 'Sixth', '90', 'https://images.pokemoncard.io/images/xy1/xy1-103.png', 'unlimited: Legal, expanded: Legal', '', 'Swellow', '277', 'TPCI', 'Rare', '', '02/05/2014', 'type: Fighting, value: -20', 'Colorless', '', 'XY', '103', 'Stage 1', 'Pokémon', 'Colorless', 'type: Lightning, value: ×2'),
('xy1-104', '', '', 'kawayoo', '[{\'name\': \'Heal Bell\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Heal 10 damage from each of your Pokémon.\'}, {\'name\': \'Tail Whap\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'\'}]', 'XY', '1', '', 'Delcatty', 'It cant stop itself from chasing moving things, and it runs in a circle, chasing its own tail.', 'Sixth', '50', 'https://images.pokemoncard.io/images/xy1/xy1-104.png', 'unlimited: Legal, expanded: Legal', '', 'Skitty', '300', 'TPCI', 'Common', '', '02/05/2014', '', 'Colorless', '', 'XY', '104', 'Basic', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('xy1-105', '', '', 'Suwama Chiaki', '[{\'name\': \'Energy Salon\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Search your deck for 3 different types of basic Energy cards, reveal them, and put them into your hand. Shuffle your deck afterward.\'}, {\'name\': \'Fake Out\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \"Flip a coin. If heads, your opponent\'s Active Pokémon is now Paralyzed.\"}]', 'XY', '1', 'Skitty', '', 'It dislikes dirty places. It often searches for a comfortable place in which to groom itself.', 'Sixth', '80', 'https://images.pokemoncard.io/images/xy1/xy1-105.png', 'unlimited: Legal, expanded: Legal', '', 'Delcatty', '301', 'TPCI', 'Uncommon', '', '02/05/2014', '', 'Colorless', '', 'XY', '105', 'Stage 1', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('xy1-106', '', '', 'Kagemaru Himeno', '[{\'name\': \'Hyper Fang\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'40\', \'text\': \'Flip a coin. If tails, this attack does nothing.\'}]', 'XY', '3', '', 'Bibarel', 'With nerves of steel, nothing can perturb it. It is more agile and active than it appears.', 'Sixth', '60', 'https://images.pokemoncard.io/images/xy1/xy1-106.png', 'unlimited: Legal, expanded: Legal', '', 'Bidoof', '399', 'TPCI', 'Common', '', '02/05/2014', '', 'Colorless, Colorless, Colorless', '', 'XY', '106', 'Basic', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('xy1-107', '', '', 'Kyoko Umemoto', '[{\'name\': \'Double Headbutt\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30×\', \'text\': \'Flip 2 coins. This attack does 30 damage for each heads.\'}, {\'name\': \'Hypno Headbutt\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60+\', \'text\': \'You may do 30 more damage. If you do, this Pokémon is now Asleep.\'}]', 'XY', '3', 'Bidoof', '', 'It busily makes its nest with stacks of branches and roots it has cut up with its sharp incisors.', 'Sixth', '100', 'https://images.pokemoncard.io/images/xy1/xy1-107.png', 'unlimited: Legal, expanded: Legal', '', 'Bibarel', '400', 'TPCI', 'Rare', '', '02/05/2014', '', 'Colorless, Colorless, Colorless', '', 'XY', '107', 'Stage 1', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('xy1-108', '', '', 'match', '[{\'name\': \'Tackle\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'\'}, {\'name\': \'Bite\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'\'}]', 'XY', '1', '', 'Herdier', 'The long hair around its face provides an amazing radar that lets it sense subtle changes in its surroundings.', 'Sixth', '50', 'https://images.pokemoncard.io/images/xy1/xy1-108.png', 'unlimited: Legal, expanded: Legal', '', 'Lillipup', '506', 'TPCI', 'Common', '', '02/05/2014', '', 'Colorless', '', 'XY', '108', 'Basic', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('xy1-109', '', '', 'Tomokazu Komiya', '[{\'name\': \'Bite\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'\'}, {\'name\': \'Jump On\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50+\', \'text\': \'Flip a coin. If heads, this attack does 20 more damage.\'}]', 'XY', '1', 'Lillipup', 'Stoutland', 'This very loyal Pokémon helps Trainers, and it also takes care of other Pokémon.', 'Sixth', '80', 'https://images.pokemoncard.io/images/xy1/xy1-109.png', 'unlimited: Legal, expanded: Legal', '', 'Herdier', '507', 'TPCI', 'Uncommon', '', '02/05/2014', '', 'Colorless', '', 'XY', '109', 'Stage 1', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('xy1-11', '', '', 'Shigenori Negishi', '[{\'name\': \'Torment\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'20\', \'text\': \"Choose 1 of your opponent\'s Active Pokémon\'s attacks. That Pokémon can\'t use that attack during your opponent\'s next turn.\"}, {\'name\': \'Solar Beam\', \'cost\': [\'Grass\', \'Grass\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'70\', \'text\': \'\'}]', 'XY', '1', 'Pansage', '', 'It attacks enemies with strikes of its thorn-covered tail. This Pokémon is wild tempered.', 'Sixth', '90', 'https://images.pokemoncard.io/images/xy1/xy1-11.png', 'unlimited: Legal, expanded: Legal', '', 'Simisage', '512', 'TPCI', 'Rare', '', '02/05/2014', '', 'Colorless', '', 'XY', '11', 'Stage 1', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('xy1-110', '', '', 'Kouki Saitou', '[{\'name\': \'Bite Off\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60+\', \'text\': \"If your opponent\'s Active Pokémon is a Pokémon-EX, this attack does 60 more damage.\"}, {\'name\': \'Wild Barking\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'80\', \'text\': \"Does 20 damage to 1 of your opponent\'s Benched Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'XY', '3', 'Herdier', '', 'It rescues people stranded by blizzards in the mountains. Its shaggy fur shields it from the cold.', 'Sixth', '140', 'https://images.pokemoncard.io/images/xy1/xy1-110.png', 'unlimited: Legal, expanded: Legal', '', 'Stoutland', '508', 'TPCI', 'Rare', '', '02/05/2014', '', 'Colorless, Colorless, Colorless', '', 'XY', '110', 'Stage 2', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('xy1-111', '', '', '5ban Graphics', '[{\'name\': \'Dig\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'10\', \'text\': \"Flip a coin. If heads, prevent all effects of attacks, including damage, done to this Pokémon during your opponent\'s next turn.\"}]', 'XY', '1', '', 'Diggersby', 'They use their large ears to dig burrows. They will dig the whole night through.', 'Sixth', '60', 'https://images.pokemoncard.io/images/xy1/xy1-111.png', 'unlimited: Legal, expanded: Legal', '', 'Bunnelby', '659', 'TPCI', 'Common', '', '02/05/2014', '', 'Colorless', '', 'XY', '111', 'Basic', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2');
