('xy11-102', '', '', 'Toyste Beach', '', 'Steam Siege', '', '', '', '', 'Sixth', '', 'https://images.pokemoncard.io/images/xy11/xy11-102.png', 'unlimited: Legal, expanded: Legal', '', 'Greedy Dice', '', 'TPCI', 'Uncommon', '', '08/03/2016', '', '', '[\'You can play this card only if you took it as a face-down Prize card, before you put it into your hand.\', \'Flip a coin. If heads, take 1 more Prize card.\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'XY', '102', 'Item', 'Trainer', '', ''),
('xy11-103', '', '', 'Megumi Mizutani', '', 'Steam Siege', '', '', '', '', 'Sixth', '', 'https://images.pokemoncard.io/images/xy11/xy11-103.png', 'unlimited: Legal, expanded: Legal', '', 'Ninja Boy', '', 'TPCI', 'Uncommon', '', '08/03/2016', '', '', '[\'Choose 1 of your Basic Pokémon in play. Search your deck for a Basic Pokémon and switch it with that Pokémon. (Any attached cards, damage counters, Special Conditions, turns in play, and any other effects remain on the new Pokémon.) Shuffle the first Pokémon into your deck.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'XY', '103', 'Supporter', 'Trainer', '', ''),
('xy11-104', '', '', 'Yusuke Ohmura', '', 'Steam Siege', '', '', '', '', 'Sixth', '', 'https://images.pokemoncard.io/images/xy11/xy11-104.png', 'unlimited: Legal, expanded: Legal', '', 'Pokémon Ranger', '', 'TPCI', 'Uncommon', '', '08/03/2016', '', '', '[\'Remove all effects of attacks on each player and his or her Pokémon.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'XY', '104', 'Supporter', 'Trainer', '', ''),
('xy11-105', '', '', 'Toyste Beach', '', 'Steam Siege', '', '', '', '', 'Sixth', '', 'https://images.pokemoncard.io/images/xy11/xy11-105.png', 'unlimited: Legal, expanded: Legal', '', 'Special Charge', '', 'TPCI', 'Uncommon', '', '08/03/2016', '', '', '[\'Shuffle 2 Special Energy cards from your discard pile into your deck.\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'XY', '105', 'Item', 'Trainer', '', '');
INSERT INTO `cards` (`id`, `abilities`, `ancient_trait`, `artist`, `attacks`, `card_set`, `converted`, `evolves_from`, `evolves_to`, `flavor_text`, `generation`, `hp`, `img`, `legalities`, `level`, `name`, `national_pokedex_numbers`, `publisher`, `rarity`, `regulation_mark`, `release_date`, `resistances`, `retreat_cost`, `rules`, `series`, `set_num`, `subtypes`, `supertype`, `types`, `weakness`) VALUES
('xy11-106', '', '', '5ban Graphics', '', 'Steam Siege', '', '', '', '', 'Sixth', '', 'https://images.pokemoncard.io/images/xy11/xy11-106.png', 'unlimited: Legal, expanded: Legal', '', 'Steelix Spirit Link', '', 'TPCI', 'Uncommon', '', '08/03/2016', '', '', '[\"Attach a Pokémon Tool to 1 of your Pokémon that doesn\'t already have a Pokémon Tool attached to it.\", \'Your turn does not end if the Pokémon this card is attached to becomes M Steelix-EX.\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'XY', '106', 'Pokémon Tool', 'Trainer', '', ''),
('xy11-107', '[{\'name\': \'Steam Up\', \'text\': \"Once during your turn (before your attack), you may discard a Fire Energy card from your hand. If you do, during this turn, your Basic Fire Pokémon\'s attacks do 30 more damage to your opponent\'s Active Pokémon (before applying Weakness and Resistance).\", \'type\': \'Ability\'}]', '', '5ban Graphics', '[{\'name\': \'Volcanic Heat\', \'cost\': [\'Fire\', \'Fire\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'130\', \'text\': \"This Pokémon can\'t attack during your next turn.\"}]', 'Steam Siege', '3', '', '', '', 'Sixth', '180', 'https://images.pokemoncard.io/images/xy11/xy11-107.png', 'unlimited: Legal, expanded: Legal', '', 'Volcanion-EX', '721', 'TPCI', 'Rare Ultra', '', '08/03/2016', '', 'Colorless, Colorless, Colorless', '[\'Pokémon-EX rule: When a Pokémon-EX has been Knocked Out, your opponent takes 2 Prize cards.\']', 'XY', '107', 'Basic, EX', 'Pokémon', 'Fire, Water', 'type: Water, value: ×2'),
('xy11-108', '', '', 'Ryo Ueda', '[{\'name\': \'Wild Edge\', \'cost\': [\'Metal\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'80+\', \'text\': \'You may do 50 more damage. If you do, this Pokémon does 20 damage to itself.\'}, {\'name\': \'Iron Tail\', \'cost\': [\'Metal\', \'Colorless\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 5, \'damage\': \'100×\', \'text\': \'Flip a coin until you get tails. This attack does 100 damage times the number of heads.\'}]', 'Steam Siege', '4', '', 'M Steelix-EX', '', 'Sixth', '180', 'https://images.pokemoncard.io/images/xy11/xy11-108.png', 'unlimited: Legal, expanded: Legal', '', 'Steelix-EX', '208', 'TPCI', 'Rare Ultra', '', '08/03/2016', 'type: Psychic, value: -20', 'Colorless, Colorless, Colorless, Colorless', '[\'Pokémon-EX rule: When a Pokémon-EX has been Knocked Out, your opponent takes 2 Prize cards.\']', 'XY', '108', 'Basic, EX', 'Pokémon', 'Metal', 'type: Fire, value: ×2'),
('xy11-109', '', '', '5ban Graphics', '[{\'name\': \'Canyon Axe\', \'cost\': [\'Metal\', \'Colorless\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 5, \'damage\': \'160\', \'text\': \"This attack does 10 damage to each of your opponent\'s Benched Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'Steam Siege', '4', 'Steelix-EX', '', '', 'Sixth', '240', 'https://images.pokemoncard.io/images/xy11/xy11-109.png', 'unlimited: Legal, expanded: Legal', '', 'M Steelix-EX', '208', 'TPCI', 'Rare Ultra', '', '08/03/2016', 'type: Psychic, value: -20', 'Colorless, Colorless, Colorless, Colorless', '[\'Mega Evolution rule: When 1 of your Pokémon becomes a Mega Evolution Pokémon, your turn ends.\', \'Pokémon-EX rule: When a Pokémon-EX has been Knocked Out, your opponent takes 2 Prize cards.\']', 'XY', '109', 'MEGA, EX', 'Pokémon', 'Metal, Fighting', 'type: Fire, value: ×2'),
('xy11-11', '', '', 'Kagemaru Himeno', '[{\'name\': \'Wicked Wind\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'40\', \'text\': \"Until the end of your opponent\'s next turn, each Stadium or Pokémon Tool card in play has no effect. (This includes cards that come into play on that turn.)\"}, {\'name\': \'Extrasensory\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'60+\', \'text\': \'If you have the same number of cards in your hand as your opponent, this attack does 60 more damage.\'}]', 'Steam Siege', '2', 'Nuzleaf', '', 'By flapping its leafy fan, it can whip up gusts of 100 ft/second that can level houses.', 'Sixth', '140', 'https://images.pokemoncard.io/images/xy11/xy11-11.png', 'unlimited: Legal, expanded: Legal', '', 'Shiftry', '275', 'TPCI', 'Rare Holo', '', '08/03/2016', '', 'Colorless, Colorless', '', 'XY', '11', 'Stage 2', 'Pokémon', 'Grass, Darkness', 'type: Fire, value: ×2'),
('xy11-110', '[{\'name\': \'Mystic Heart\', \'text\': \"Prevent all effects of your opponent\'s attacks, except damage, done to each of your Pokémon that has any Metal Energy attached to it. (Existing effects are not removed.)\", \'type\': \'Ability\'}]', '', '5ban Graphics', '[{\'name\': \'Soul Blaster\', \'cost\': [\'Metal\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'120\', \'text\': \"During your next turn, this Pokémon\'s Soul Blaster attack\'s base damage is 60.\"}]', 'Steam Siege', '1', '', '', '', 'Sixth', '160', 'https://images.pokemoncard.io/images/xy11/xy11-110.png', 'unlimited: Legal, expanded: Legal', '', 'Magearna-EX', '801', 'TPCI', 'Rare Ultra', '', '08/03/2016', 'type: Psychic, value: -20', 'Colorless', '[\'Pokémon-EX rule: When a Pokémon-EX has been Knocked Out, your opponent takes 2 Prize cards.\']', 'XY', '110', 'Basic, EX', 'Pokémon', 'Metal', 'type: Fire, value: ×2'),
('xy11-111', '', '', 'Ryo Ueda', '[{\'name\': \'Link Blast\', \'cost\': [\'Fairy\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30+\', \'text\': \"If this Pokémon and your opponent\'s Active Pokémon have the same amount of Energy attached to them, this attack does 70 more damage.\"}, {\'name\': \'Luminous Blade\', \'cost\': [\'Fairy\', \'Fairy\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'120\', \'text\': \'Discard an Energy attached to this Pokémon.\'}]', 'Steam Siege', '2', '', 'M Gardevoir-EX', '', 'Sixth', '170', 'https://images.pokemoncard.io/images/xy11/xy11-111.png', 'unlimited: Legal, expanded: Legal', '', 'Gardevoir-EX', '282', 'TPCI', 'Rare Ultra', '', '08/03/2016', 'type: Darkness, value: -20', 'Colorless, Colorless', '[\'Pokémon-EX rule: When a Pokémon-EX has been Knocked Out, your opponent takes 2 Prize cards.\']', 'XY', '111', 'Basic, EX', 'Pokémon', 'Fairy', 'type: Metal, value: ×2'),
('xy11-112', '', '', '5ban Graphics', '[{\'name\': \'Despair Ray\', \'cost\': [\'Fairy\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'110+\', \'text\': \'Discard as many of your Benched Pokémon as you like. This attack does 10 more damage for each Benched Pokémon you discarded in this way.\'}]', 'Steam Siege', '2', 'Gardevoir-EX', '', '', 'Sixth', '210', 'https://images.pokemoncard.io/images/xy11/xy11-112.png', 'unlimited: Legal, expanded: Legal', '', 'M Gardevoir-EX', '282', 'TPCI', 'Rare Ultra', '', '08/03/2016', 'type: Darkness, value: -20', 'Colorless, Colorless', '[\'Mega Evolution rule: When 1 of your Pokémon becomes a Mega Evolution Pokémon, your turn ends.\', \'Pokémon-EX rule: When a Pokémon-EX has been Knocked Out, your opponent takes 2 Prize cards.\']', 'XY', '112', 'MEGA, EX', 'Pokémon', 'Fairy, Psychic', 'type: Metal, value: ×2'),
('xy11-113', '', '', 'Megumi Mizutani', '', 'Steam Siege', '', '', '', '', 'Sixth', '', 'https://images.pokemoncard.io/images/xy11/xy11-113.png', 'unlimited: Legal, expanded: Legal', '', 'Pokémon Ranger', '', 'TPCI', 'Rare Ultra', '', '08/03/2016', '', '', '[\'Remove all effects of attacks on each player and his or her Pokémon.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'XY', '113', 'Supporter', 'Trainer', '', ''),
