('xy12-102', '', '', '5ban Graphics', '[{\'name\': \'Hydro Bombard\', \'cost\': [\'Water\', \'Water\', \'Water\'], \'convertedEnergyCost\': 3, \'damage\': \'120\', \'text\': \"This attack does 30 damage to 2 of your opponent\'s Benched Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'Evolutions', '3', 'Blastoise-EX', '', '', 'Sixth', '220', 'https://images.pokemoncard.io/images/xy12/xy12-102.png', 'unlimited: Legal, expanded: Legal', '', 'M Blastoise-EX', '9', 'TPCI', 'Rare Ultra', '', '11/02/2016', '', 'Colorless, Colorless, Colorless', '[\'Mega Evolution rule: When 1 of your Pokémon becomes a Mega Evolution Pokémon, your turn ends.\', \'Pokémon-EX rule: When a Pokémon-EX has been Knocked Out, your opponent takes 2 Prize cards.\']', 'XY', '102', 'MEGA, EX', 'Pokémon', 'Water', 'type: Grass, value: ×2'),
('xy12-103', '', '', 'Ryo Ueda', '[{\'name\': \'Energy Absorption\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Attach an Energy card from your discard pile to this Pokémon.\'}, {\'name\': \'Regeneration\', \'cost\': [\'Psychic\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Heal 60 damage from this Pokémon.\'}, {\'name\': \'Psyburn\', \'cost\': [\'Psychic\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'110\', \'text\': \'\'}]', 'Evolutions', '2', '', 'M Mewtwo-EX', '', 'Sixth', '180', 'https://images.pokemoncard.io/images/xy12/xy12-103.png', 'unlimited: Legal, expanded: Legal', '', 'Mewtwo-EX', '150', 'TPCI', 'Rare Ultra', '', '11/02/2016', '', 'Colorless, Colorless', '[\'Pokémon-EX rule: When a Pokémon-EX has been Knocked Out, your opponent takes 2 Prize cards.\']', 'XY', '103', 'Basic, EX', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2'),
('xy12-104', '', '', 'Ryo Ueda', '[{\'name\': \'Mirror Move\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"If this Pokémon was damaged by an attack during your opponent\'s last turn, this attack does the same amount of damage to your opponent\'s Active Pokémon.\"}, {\'name\': \'Feather Lance\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'80\', \'text\': \"This attack does 20 damage to 1 of your opponent\'s Benched Pokémon. (Don\'t apply Weakness and resistance for Benched Pokémon.)\"}]', 'Evolutions', '1', '', 'M Pidgeot-EX', '', 'Sixth', '170', 'https://images.pokemoncard.io/images/xy12/xy12-104.png', 'unlimited: Legal, expanded: Legal', '', 'Pidgeot-EX', '18', 'TPCI', 'Rare Ultra', '', '11/02/2016', 'type: Fighting, value: -20', 'Colorless', '[\'Pokémon-EX rule: When a Pokémon-EX has been Knocked Out, your opponent takes 2 Prize cards.\']', 'XY', '104', 'Basic, EX', 'Pokémon', 'Colorless', 'type: Lightning, value: ×2'),
('xy12-105', '', '', '5ban Graphics', '[{\'name\': \'Mach Cyclone\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'130\', \'text\': \'You may have your opponent switch his or her Active Pokémon with 1 of his or her Benched Pokémon.\'}]', 'Evolutions', '', 'Pidgeot-EX', '', '', 'Sixth', '220', 'https://images.pokemoncard.io/images/xy12/xy12-105.png', 'unlimited: Legal, expanded: Legal', '', 'M Pidgeot-EX', '18', 'TPCI', 'Rare Ultra', '', '11/02/2016', 'type: Fighting, value: -20', '', '[\'Mega Evolution rule: When 1 of your Pokémon becomes a Mega Evolution Pokémon, your turn ends.\', \'Pokémon-EX rule: When a Pokémon-EX has been Knocked Out, your opponent takes 2 Prize cards.\']', 'XY', '105', 'MEGA, EX', 'Pokémon', 'Colorless', 'type: Lightning, value: ×2'),
('xy12-106', '[{\'name\': \'Pull Up\', \'text\': \'When you play this Pokémon from your hand onto your Bench, you may put 2 Basic Pokémon (except for Dragonite-EX) from your discard pile into your hand.\', \'type\': \'Ability\'}]', '', 'Ryo Ueda', '[{\'name\': \'Hyper Beam\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'130\', \'text\': \"Discard an Energy attached to your opponent\'s Active Pokémon.\"}]', 'Evolutions', '3', '', '', '', 'Sixth', '180', 'https://images.pokemoncard.io/images/xy12/xy12-106.png', 'unlimited: Legal, expanded: Legal', '', 'Dragonite-EX', '149', 'TPCI', 'Rare Ultra', '', '11/02/2016', 'type: Fighting, value: -20', 'Colorless, Colorless, Colorless', '[\'Pokémon-EX rule: When a Pokémon-EX has been Knocked Out, your opponent takes 2 Prize cards.\']', 'XY', '106', 'Basic, EX', 'Pokémon', 'Colorless', 'type: Lightning, value: ×2'),
('xy12-107', '', '', 'Hitoshi Ariga', '', 'Evolutions', '', '', '', '', 'Sixth', '', 'https://images.pokemoncard.io/images/xy12/xy12-107.png', 'unlimited: Legal, expanded: Legal', '', 'Brocks Grit', '', 'TPCI', 'Rare Ultra', '', '11/02/2016', '', '', '[\'Shuffle 6 in any combination of Pokémon and basic Energy cards from your discard pile into your deck.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'XY', '107', 'Supporter', 'Trainer', '', ''),
('xy12-108', '', '', 'Megumi Mizutani', '', 'Evolutions', '', '', '', '', 'Sixth', '', 'https://images.pokemoncard.io/images/xy12/xy12-108.png', 'unlimited: Legal, expanded: Legal', '', 'Mistys Determination', '', 'TPCI', 'Rare Ultra', '', '11/02/2016', '', '', '[\'Discard a card from your hand. If you do, look at the top 8 cards of your deck and put 1 of them into your hand. Shuffle the other cards back into your deck.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'XY', '108', 'Supporter', 'Trainer', '', ''),
('xy12-109', '', '', 'Dr.Ooyama', '[{\'name\': \'ふみつけ[Stomp]\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20+\', \'text\': \'コインを1回投げオモテなら、10ダメージを追加。 Flip a coin. If heads, this attack does 10 more damage.\'}]', 'Evolutions', '2', 'タマタマExeggcute', '', 'Dr.オーヤマ考案「日米交流カード」パーティ気分で和洋せっちゅう。', 'Sixth', '80', 'https://images.pokemoncard.io/images/xy12/xy12-109.png', 'unlimited: Legal, expanded: Legal', '', 'ナッシーExeggutor', '103', 'TPCI', 'Rare Secret', '', '11/02/2016', '', 'Colorless, Colorless', '', 'XY', '109', 'Stage 1', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('xy12-11', '[{\'name\': \'Energy Burn\', \'text\': \'All Energy attached to this Pokémon are Fire Energy instead of their usual type.\', \'type\': \'Ability\'}]', '', 'Mitsuhiro Arita', '[{\'name\': \'Fire Spin\', \'cost\': [\'Fire\', \'Fire\', \'Fire\', \'Fire\'], \'convertedEnergyCost\': 4, \'damage\': \'200\', \'text\': \'Discard 3 Energy attached to this Pokémon.\'}]', 'Evolutions', '3', 'Charmeleon', '', 'Its wings can carry this Pokémon close to an altitude of 4,600 feet. It blows out fire at very high temperatures.', 'Sixth', '150', 'https://images.pokemoncard.io/images/xy12/xy12-11.png', 'unlimited: Legal, expanded: Legal', '76', 'Charizard', '6', 'TPCI', 'Rare Holo', '', '11/02/2016', 'type: Fighting, value: -20', 'Colorless, Colorless, Colorless', '', 'XY', '11', 'Stage 2', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('xy12-110', '', '', 'Toshinao Aoki', '[{\'name\': \'Thunder Shock\', \'cost\': [\'Lightning\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \"Flip a coin. If heads, your opponent\'s Active Pokémon is now Paralyzed.\"}, {\'name\': \'Fly\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'30\', \'text\': \"Flip a coin. If tails, this attack does nothing. If heads, prevent all effects of attacks, including damage, done to this Pokémon during your opponent\'s next turn.\"}]', 'Evolutions', '1', '', 'Raichu', 'By learning how to fly, Pikachu overcame its weakness to Fighting Pokémon.', 'Sixth', '40', 'https://images.pokemoncard.io/images/xy12/xy12-110.png', 'unlimited: Legal, expanded: Legal', '12', 'Flying Pikachu', '25', 'TPCI', 'Rare Secret', '', '11/02/2016', 'type: Fighting, value: -20', 'Colorless', '', 'XY', '110', 'Basic', 'Pokémon', 'Lightning', ''),
('xy12-111', '', '', 'Toshinao Aoki', '[{\'name\': \'Surf\', \'cost\': [\'Water\', \'Water\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'\'}]', 'Evolutions', '1', '', 'Raichu', 'One summer, a group of Pikachu was found riding the waves at the local beach.', 'Sixth', '50', 'https://images.pokemoncard.io/images/xy12/xy12-111.png', 'unlimited: Legal, expanded: Legal', '13', 'Surfing Pikachu', '25', 'TPCI', 'Rare Secret', '', '11/02/2016', '', 'Colorless', '', 'XY', '111', 'Basic', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2');
INSERT INTO `cards` (`id`, `abilities`, `ancient_trait`, `artist`, `attacks`, `card_set`, `converted`, `evolves_from`, `evolves_to`, `flavor_text`, `generation`, `hp`, `img`, `legalities`, `level`, `name`, `national_pokedex_numbers`, `publisher`, `rarity`, `regulation_mark`, `release_date`, `resistances`, `retreat_cost`, `rules`, `series`, `set_num`, `subtypes`, `supertype`, `types`, `weakness`) VALUES
('xy12-112', '[{\'name\': \'Frenzied Escape\', \'text\': \'When this Doduo retreats, hold this card and throw it as hard as you can because Doduo is running away. Throw the card horizontally with a snap to get the farthest distance!\', \'type\': \'Pokémon Power\'}]', '', 'Imakuni?', '[{\'name\': \'Harmonize\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'From the moment you use this attack, you must begin to sing a song. (While the song is being sung, the game continues.) When the song is finished, this attack does 30 damage.\'}]', 'Evolutions', '', '', '', '', 'Sixth', '50', 'https://images.pokemoncard.io/images/xy12/xy12-112.png', 'unlimited: Legal, expanded: Legal', '15', 'Imakuni?s Doduo', '84', 'TPCI', 'Rare Secret', '', '11/02/2016', 'type: Fighting, value: -20', '', '[\'(This card cannot be used at official tournaments.)\']', 'XY', '112', 'Basic', 'Pokémon', 'Colorless', 'type: Lightning, value: ×2'),
('xy12-113', '', '', 'Ken Sugimori', '', 'Evolutions', '', '', '', '', 'Sixth', '', 'https://images.pokemoncard.io/images/xy12/xy12-113.png', 'unlimited: Legal, expanded: Legal', '', 'Here Comes Team Rocket!', '', 'TPCI', 'Rare Secret', '', '11/02/2016', '', '', '[\'Each player turns all of his or her Prize cards face up. (Those Prize cards remain face up for the rest of the game.)\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'XY', '113', 'Supporter', 'Trainer', '', ''),
('xy12-12', '', '', 'PLANETA', '[{\'name\': \'Wing Attack\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60\', \'text\': \'\'}, {\'name\': \'Combustion Blast\', \'cost\': [\'Fire\', \'Fire\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'150\', \'text\': \"This Pokémon can\'t use Combustion Blast during your next turn.\"}]', 'Evolutions', '2', '', 'M Charizard-EX', '', 'Sixth', '180', 'https://images.pokemoncard.io/images/xy12/xy12-12.png', 'unlimited: Legal, expanded: Legal', '', 'Charizard-EX', '6', 'TPCI', 'Rare Holo EX', '', '11/02/2016', '', 'Colorless, Colorless', '[\'Pokémon-EX rule: When a Pokémon-EX has been Knocked Out, your opponent takes 2 Prize cards.\']', 'XY', '12', 'Basic, EX', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('xy12-13', '', '', '5ban Graphics', '[{\'name\': \'Crimson Dive\', \'cost\': [\'Fire\', \'Fire\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 5, \'damage\': \'300\', \'text\': \'This Pokémon does 50 damage to itself.\'}]', 'Evolutions', '1', 'Charizard-EX', '', '', 'Sixth', '220', 'https://images.pokemoncard.io/images/xy12/xy12-13.png', 'unlimited: Legal, expanded: Legal', '', 'M Charizard-EX', '6', 'TPCI', 'Rare Holo EX', '', '11/02/2016', '', 'Colorless', '[\'Mega Evolution rule: When 1 of your Pokémon becomes a Mega Evolution Pokémon, your turn ends.\', \'Pokémon-EX rule: When a Pokémon-EX has been Knocked Out, your opponent takes 2 Prize cards.\']', 'XY', '13', 'MEGA, EX', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('xy12-14', '', '', 'Ken Sugimori', '[{\'name\': \'Confuse Ray\', \'cost\': [\'Fire\', \'Fire\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \"Flip a coin. If heads, your opponent\'s Active Pokémon is now Confused.\"}]', 'Evolutions', '1', '', 'Ninetales', 'While young, it has six gorgeous tails. When it grows, several new tails are sprouted.', 'Sixth', '60', 'https://images.pokemoncard.io/images/xy12/xy12-14.png', 'unlimited: Legal, expanded: Legal', '11', 'Vulpix', '37', 'TPCI', 'Common', '', '11/02/2016', '', 'Colorless', '', 'XY', '14', 'Basic', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('xy12-15', '', '', 'Ken Sugimori', '[{\'name\': \'Lure\', \'cost\': [\'Fire\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Switch 1 of your opponent\'s Benched Pokémon with his or her Active Pokémon. The new Active Pokémon can\'t retreat during your opponent\'s next turn.\"}, {\'name\': \'Fire Blast\', \'cost\': [\'Fire\', \'Fire\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'120\', \'text\': \'Discard a Fire Energy attached to this Pokémon.\'}]', 'Evolutions', '1', 'Vulpix', '', 'It has nine long tails and fur that gleams gold. It is said to live for 1,000 years.', 'Sixth', '100', 'https://images.pokemoncard.io/images/xy12/xy12-15.png', 'unlimited: Legal, expanded: Legal', '32', 'Ninetales', '38', 'TPCI', 'Rare Holo', '', '11/02/2016', '', 'Colorless', '', 'XY', '15', 'Stage 1', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('xy12-16', '', '', '5ban Graphics', '[{\'name\': \'Explosive Fireball\', \'cost\': [\'Fire\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'10+\', \'text\': \'Discard all Fire Energy attached to this Pokémon. This attack does 60 more damage for each Energy card discarded in this way.\'}]', 'Evolutions', '', 'Ninetales', '', '', 'Sixth', '140', 'https://images.pokemoncard.io/images/xy12/xy12-16.png', 'unlimited: Legal, expanded: Legal', '', 'Ninetales BREAK', '38', 'TPCI', 'Rare BREAK', '', '11/02/2016', '', '', '[\'BREAK Evolution Rule: Ninetales BREAK retains the attacks, Abilities, Weakness, Resistance, and Retreat Cost of its previous Evolution.\']', 'XY', '16', 'BREAK', 'Pokémon', 'Fire', ''),
('xy12-17', '', '', 'Ken Sugimori', '[{\'name\': \'Hind Kick\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'Switch this Pokémon with 1 of your Benched Pokémon.\'}, {\'name\': \'Flare\', \'cost\': [\'Fire\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'\'}]', 'Evolutions', '2', '', 'Arcanine', 'Very friendly and faithful to people. It will try to repel enemies by barking and biting.', 'Sixth', '70', 'https://images.pokemoncard.io/images/xy12/xy12-17.png', 'unlimited: Legal, expanded: Legal', '18', 'Growlithe', '58', 'TPCI', 'Common', '', '11/02/2016', '', 'Colorless, Colorless', '', 'XY', '17', 'Basic', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('xy12-18', '[{\'name\': \'Burning Road\', \'text\': \'Once during your turn (before your attack), if this Pokémon was on the Bench and became your Active Pokémon this turn, you may move any number of Fire Energy attached to your Pokémon to this Pokémon.\', \'type\': \'Ability\'}]', '', 'Ken Sugimori', '[{\'name\': \'Scorching Breath\', \'cost\': [\'Fire\', \'Fire\', \'Fire\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'150\', \'text\': \"This Pokémon can\'t attack during your next turn.\"}]', 'Evolutions', '2', 'Growlithe', '', 'A Pokémon that is described in Chinese legends. It is said to race at an unbelievable speed.', 'Sixth', '130', 'https://images.pokemoncard.io/images/xy12/xy12-18.png', 'unlimited: Legal, expanded: Legal', '45', 'Arcanine', '59', 'TPCI', 'Rare', '', '11/02/2016', '', 'Colorless, Colorless', '', 'XY', '18', 'Stage 1', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('xy12-19', '', '', 'Ken Sugimori', '[{\'name\': \'Smash Kick\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'\'}, {\'name\': \'Flame Tail\', \'cost\': [\'Fire\', \'Fire\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'\'}]', 'Evolutions', '1', '', 'Rapidash', 'Its body is light, and its legs are incredibly powerful. It can clear Ayers Rock in one leap.', 'Sixth', '60', 'https://images.pokemoncard.io/images/xy12/xy12-19.png', 'unlimited: Legal, expanded: Legal', '10', 'Ponyta', '77', 'TPCI', 'Common', '', '11/02/2016', '', 'Colorless', '', 'XY', '19', 'Basic', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
