('xy4-109', '', '', '5ban Graphics', '', 'Phantom Forces', '', '', '', '', 'Sixth', '', 'https://images.pokemoncard.io/images/xy4/xy4-109.png', 'unlimited: Legal, expanded: Legal', '', 'VS Seeker', '', 'TPCI', 'Uncommon', '', '11/05/2014', '', '', '[\'Put a Supporter card from your discard pile into your hand.\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'XY', '109', 'Item', 'Trainer', '', ''),
('xy4-11', '', '', 'Atsuko Nishida', '[{\'name\': \'Roar\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Your opponent switches his or her Active Pokémon with 1 of his or her Benched Pokémon.\'}, {\'name\': \'Live Coal\', \'cost\': [\'Fire\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'\'}]', 'Phantom Forces', '2', '', 'Pyroar', 'The stronger the opponent it faces, the more heat surges from its mane and the more power flows through its body.', 'Sixth', '60', 'https://images.pokemoncard.io/images/xy4/xy4-11.png', 'unlimited: Legal, expanded: Legal', '', 'Litleo', '667', 'TPCI', 'Common', '', '11/05/2014', '', 'Colorless, Colorless', '', 'XY', '11', 'Basic', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('xy4-110', '', '', 'Yusuke Ohmura', '', 'Phantom Forces', '', '', '', '', 'Sixth', '', 'https://images.pokemoncard.io/images/xy4/xy4-110.png', 'unlimited: Legal, expanded: Legal', '', 'Xerosic', '', 'TPCI', 'Uncommon', '', '11/05/2014', '', '', '[\"Choose a Pokémon Tool or Special Energy card attached to a Pokémon in play (yours or your opponent\'s) and discard it.\", \'You may play only 1 Supporter card during your turn (before your attack).\']', 'XY', '110', 'Supporter', 'Trainer', '', ''),
('xy4-111', '', '', '5ban Graphics', '', 'Phantom Forces', '', '', '', '', 'Sixth', '', 'https://images.pokemoncard.io/images/xy4/xy4-111.png', 'unlimited: Legal, expanded: Legal', '', 'Double Colorless Energy', '', 'TPCI', 'Uncommon', '', '11/05/2014', '', '', '[\'Double Colorless Energy provides ColorlessColorless Energy.\']', 'XY', '111', 'Special', 'Energy', '', ''),
('xy4-112', '', '', '5ban Graphics', '', 'Phantom Forces', '', '', '', '', 'Sixth', '', 'https://images.pokemoncard.io/images/xy4/xy4-112.png', 'unlimited: Legal, expanded: Legal', '', 'Mystery Energy', '', 'TPCI', 'Uncommon', '', '11/05/2014', '', '', '[\'This card can only be attached to Psychic Pokémon. This card provides Psychic Energy only while this card is attached to a Psychic Pokémon.\', \'The Retreat Cost of the Pokémon this card is attached to is ColorlessColorless less.\', \'(If this card is attached to anything other than a Psychic Pokémon, discard this card.)\']', 'XY', '112', 'Special', 'Energy', '', ''),
('xy4-113', '', '', 'Ryo Ueda', '[{\'name\': \'Overrun\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'20\', \'text\': \"This attack does 20 damage to 1 of your opponent\'s Benched Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}, {\'name\': \'Assault Laser\', \'cost\': [\'Lightning\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'60+\', \'text\': \"If your opponent\'s Active Pokémon has a Pokémon Tool card attached to it, this attack does 60 more damage.\"}]', 'Phantom Forces', '1', '', 'M Manectric-EX', '', 'Sixth', '170', 'https://images.pokemoncard.io/images/xy4/xy4-113.png', 'unlimited: Legal, expanded: Legal', '', 'Manectric-EX', '310', 'TPCI', 'Rare Ultra', '', '11/05/2014', 'type: Metal, value: -20', 'Colorless', '[\'Pokémon-EX rule: When a Pokémon-EX has been Knocked Out, your opponent takes 2 Prize cards.\']', 'XY', '113', 'Basic, EX', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
