('xy4-97', '', '', '5ban Graphics', '', 'Phantom Forces', '', '', '', '', 'Sixth', '', 'https://images.pokemoncard.io/images/xy4/xy4-97.png', 'unlimited: Legal, expanded: Legal', '', 'Head Ringer Team Flare Hyper Gear', '', 'TPCI', 'Rare Holo', '', '11/05/2014', '', '', '[\"Attach this Pokemon Tool to 1 of your opponent\'s Pokemon-EX that doesn\'t already have a Pokemon Tool attached to it.\", \'The attacks of the Pokémon this card is attached to cost Colorless more.\', \"When this card is removed from a Pokémon for any reason, put this card in its owner\'s discard pile.\", \'You may play as many Item cards as you like during your turn (before your attack).\']', 'XY', '97', 'Pokémon Tool F', 'Trainer', '', ''),
('xy4-98', '', '', '5ban Graphics', '', 'Phantom Forces', '', '', '', '', 'Sixth', '', 'https://images.pokemoncard.io/images/xy4/xy4-98.png', 'unlimited: Legal, expanded: Legal', '', 'Jamming Net Team Flare Hyper Gear', '', 'TPCI', 'Rare Holo', '', '11/05/2014', '', '', '[\"Attach this Pokemon Tool to 1 of your opponent\'s Pokemon-EX that doesn\'t already have a Pokemon Tool attached to it.\", \"The attacks of the Pokémon this card is attached to do 20 less damage to all Defending Pokémon (before applying Weakness and Resistance). (Don\'t apply Weakness and Resistance for Benched Pokémon.)\", \"When this card is removed from a Pokémon for any reason, put this card in its owner\'s discard pile.\", \'You may play as many Item cards as you like during your turn (before your attack).\']', 'XY', '98', 'Pokémon Tool F', 'Trainer', '', ''),
('xy4-99', '', '', 'Hitoshi Ariga', '', 'Phantom Forces', '', '', '', '', 'Sixth', '', 'https://images.pokemoncard.io/images/xy4/xy4-99.png', 'unlimited: Legal, expanded: Banned', '', 'Lysandres Trump Card', '', 'TPCI', 'Uncommon', '', '11/05/2014', '', '', '[\"Each player shuffles all cards in his or her discard pile into his or her deck (except for Lysandre\'s Trump Card).\", \'You may play only 1 Supporter card during your turn (before your attack).\']', 'XY', '99', 'Supporter', 'Trainer', '', ''),
