('xy6-108', '', '', 'Megumi Mizutani', '', 'Roaring Skies', '', '', '', '', 'Sixth', '', 'https://images.pokemoncard.io/images/xy6/xy6-108.png', 'unlimited: Legal, expanded: Legal', '', 'Winona', '', 'TPCI', 'Rare Ultra', '', '05/06/2015', '', '', '[\'Search your deck for up to 3 Colorless Pokémon and put them into your hand. Shuffle your deck afterward.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'XY', '108', 'Supporter', 'Trainer', '', ''),
('xy6-109', '', '', '5ban Graphics', '', 'Roaring Skies', '', '', '', '', 'Sixth', '', 'https://images.pokemoncard.io/images/xy6/xy6-109.png', 'unlimited: Legal, standard: Legal, expanded: Legal', '', 'Energy Switch', '', 'TPCI', 'Rare Secret', '', '05/06/2015', '', '', '[\'Move a basic Energy from 1 of your Pokémon to another of your Pokémon.\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'XY', '109', 'Item', 'Trainer', '', ''),
('xy6-11', '', '', 'Aya Kusube', '[{\'name\': \'Cursed Rain\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Put 1 damage counter on each of your opponent\'s Pokémon. Switch this Pokémon with 1 of your Benched Pokémon.\"}, {\'name\': \'Hopeless Scream\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'50×\', \'text\': \'This attack does 50 damage times the number of damage counters on this Pokémon.\'}]', 'Roaring Skies', '1', 'Nincada', '', 'A most peculiar Pokémon that somehow appears in a Poké Ball when a Nincada evolves.', 'Sixth', '30', 'https://images.pokemoncard.io/images/xy6/xy6-11.png', 'unlimited: Legal, expanded: Legal', '', 'Shedinja', '292', 'TPCI', 'Rare', '', '05/06/2015', '', 'Colorless', '', 'XY', '11', 'Stage 1', 'Pokémon', 'Grass', ''),
