INSERT INTO `cards` (`id`, `abilities`, `ancient_trait`, `artist`, `attacks`, `card_set`, `converted`, `evolves_from`, `evolves_to`, `flavor_text`, `generation`, `hp`, `img`, `legalities`, `level`, `name`, `national_pokedex_numbers`, `publisher`, `rarity`, `regulation_mark`, `release_date`, `resistances`, `retreat_cost`, `rules`, `series`, `set_num`, `subtypes`, `supertype`, `types`, `weakness`) VALUES
('xy6-35', '', '', '5ban Graphics', '[{\'name\': \'Unwavering Blade\', \'cost\': [\'Psychic\', \'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'110\', \'text\': \"This attack does 30 damage to each of your opponent\'s Benched Pokémon that has any damage counters on it. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'Roaring Skies', '2', 'Gallade-EX', '', '', 'Sixth', '220', 'https://images.pokemoncard.io/images/xy6/xy6-35.png', 'unlimited: Legal, expanded: Legal', '', 'M Gallade-EX', '475', 'TPCI', 'Rare Holo EX', '', '05/06/2015', '', 'Colorless, Colorless', '[\'Mega Evolution rule: When 1 of your Pokémon becomes a Mega Evolution Pokémon, your turn ends.\', \'Pokémon-EX rule: When a Pokémon-EX has been Knocked Out, your opponent takes 2 Prize cards.\']', 'XY', '35', 'MEGA, EX', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2'),
('xy6-36', '', '', 'Suwama Chiaki', '[{\'name\': \'Stun Poison\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Flip a coin. If heads, your opponent\'s Active Pokémon is now Paralyzed and Poisoned.\"}]', 'Roaring Skies', '1', '', 'Gliscor', 'It flies straight at its targets face then clamps down on the startled victim to inject poison.', 'Sixth', '70', 'https://images.pokemoncard.io/images/xy6/xy6-36.png', 'unlimited: Legal, expanded: Legal', '', 'Gligar', '207', 'TPCI', 'Common', '', '05/06/2015', '', 'Colorless', '', 'XY', '36', 'Basic', 'Pokémon', 'Fighting', 'type: Water, value: ×2'),
('xy6-37', '', '', 'Hajime Kusajima', '[{\'name\': \'Rock Slide\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'20\', \'text\': \"This attack does 20 damage to 2 of your opponent\'s Benched Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}, {\'name\': \'Slash\', \'cost\': [\'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'40\', \'text\': \'\'}]', 'Roaring Skies', '1', 'Gligar', '', 'Its flight is soundless. It uses its lengthy tail to carry off its prey… Then its elongated fangs do the rest.', 'Sixth', '90', 'https://images.pokemoncard.io/images/xy6/xy6-37.png', 'unlimited: Legal, expanded: Legal', '', 'Gliscor', '472', 'TPCI', 'Uncommon', '', '05/06/2015', '', 'Colorless', '', 'XY', '37', 'Stage 1', 'Pokémon', 'Fighting', 'type: Water, value: ×2'),
('xy6-38', '', '', 'Kanako Eo', '[{\'name\': \'Sand Attack\', \'cost\': [\'Fighting\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"If the Defending Pokémon tries to attack during your opponent\'s next turn, your opponent flips a coin. If tails, that attack does nothing.\"}, {\'name\': \'Mud-Slap\', \'cost\': [\'Fighting\', \'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40\', \'text\': \'\'}]', 'Roaring Skies', '2', '', 'Barbaracle', 'Two Binacle live together on one rock. When they fight, one of them will move to a different rock.', 'Sixth', '60', 'https://images.pokemoncard.io/images/xy6/xy6-38.png', 'unlimited: Legal, expanded: Legal', '', 'Binacle', '688', 'TPCI', 'Common', '', '05/06/2015', '', 'Colorless, Colorless', '', 'XY', '38', 'Basic', 'Pokémon', 'Fighting', 'type: Grass, value: ×2'),
('xy6-39', '', '', 'Shin Nagasawa', '[{\'name\': \'Tackle\', \'cost\': [\'Fighting\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'\'}, {\'name\': \'Midair Strike\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40+\', \'text\': \'Flip a coin. If heads, this attack does 40 more damage.\'}]', 'Roaring Skies', '1', '', '', 'Although its body is small, its proficient fighting skills enable it to keep up with big bruisers like Machamp and Hariyama.', 'Sixth', '80', 'https://images.pokemoncard.io/images/xy6/xy6-39.png', 'unlimited: Legal, expanded: Legal', '', 'Hawlucha', '701', 'TPCI', 'Common', '', '05/06/2015', 'type: Fighting, value: -20', 'Colorless', '', 'XY', '39', 'Basic', 'Pokémon', 'Fighting', 'type: Lightning, value: ×2'),
('xy6-4', '', '', 'Shigenori Negishi', '[{\'name\': \'String Shot\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \"Flip a coin. If heads, your opponent\'s Active Pokémon is now Paralyzed.\"}]', 'Roaring Skies', '3', 'Wurmple', 'Beautifly', 'It drinks dew that collects on its silk and waits for evolution. Its hard cocoon repels attacks.', 'Sixth', '80', 'https://images.pokemoncard.io/images/xy6/xy6-4.png', 'unlimited: Legal, expanded: Legal', '', 'Silcoon', '266', 'TPCI', 'Uncommon', '', '05/06/2015', '', 'Colorless, Colorless, Colorless', '', 'XY', '4', 'Stage 1', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('xy6-40', '[{\'name\': \'Cursed Eyes\', \'text\': \"When you play this Pokémon from your hand onto your Bench, you may move 3 damage counters from 1 of your opponent\'s Pokémon to another of his or her Pokémon.\", \'type\': \'Ability\'}]', '', 'Kagemaru Himeno', '[{\'name\': \'Mach Claw\', \'cost\': [\'Darkness\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \"This attack\'s damage isn\'t affected by Resistance.\"}]', 'Roaring Skies', '1', '', '', 'It appears when it senses an impending natural disaster. As a result, it was mistaken as a doom bringer.', 'Sixth', '100', 'https://images.pokemoncard.io/images/xy6/xy6-40.png', 'unlimited: Legal, expanded: Legal', '', 'Absol', '359', 'TPCI', 'Rare Holo', '', '05/06/2015', 'type: Psychic, value: -20', 'Colorless', '', 'XY', '40', 'Basic', 'Pokémon', 'Darkness', 'type: Fighting, value: ×2'),
('xy6-41', '', '', 'Akira Komayama', '[{\'name\': \'Rip Off\', \'cost\': [\'Darkness\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Choose a random card from your opponent\'s hand. Your opponent reveals that card and shuffles it into his or her deck.\"}, {\'name\': \'Psybeam\', \'cost\': [\'Darkness\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \"Flip a coin. If heads, your opponent\'s Active Pokémon is now Confused.\"}]', 'Roaring Skies', '1', '', 'Malamar', 'It flashes the light-emitting spots on its body, which drains its opponents will to fight. It takes the opportunity to scuttle away and hide.', 'Sixth', '50', 'https://images.pokemoncard.io/images/xy6/xy6-41.png', 'unlimited: Legal, expanded: Legal', '', 'Inkay', '686', 'TPCI', 'Common', '', '05/06/2015', 'type: Psychic, value: -20', 'Colorless', '', 'XY', '41', 'Basic', 'Pokémon', 'Darkness', 'type: Fighting, value: ×2'),
('xy6-42', '', '', 'Sanosuke Sakuma', '[{\'name\': \'Diminutive Desire\', \'cost\': [\'Metal\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Look at the top 7 cards of your deck and put 1 of them into your hand. Shuffle the other cards back into your deck.\'}, {\'name\': \'Doom Desire\', \'cost\': [\'Metal\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'\', \'text\': \"Discard all Energy attached to this Pokémon. The Defending Pokémon is Knocked Out at the end of your opponent\'s next turn.\"}]', 'Roaring Skies', '1', '', '', 'It is said to have the ability to grant any wish for just one week every thousand years.', 'Sixth', '70', 'https://images.pokemoncard.io/images/xy6/xy6-42.png', 'unlimited: Legal, expanded: Legal', '', 'Jirachi', '385', 'TPCI', 'Rare Holo', '', '05/06/2015', 'type: Psychic, value: -20', 'Colorless', '', 'XY', '42', 'Basic', 'Pokémon', 'Metal', 'type: Fire, value: ×2'),
('xy6-43', '', '', 'HiRON', '[{\'name\': \'Sweet Kiss\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'Your opponent draws a card.\'}]', 'Roaring Skies', '1', '', 'Togetic', 'A proverb claims that happiness will come to anyone who can make a sleeping Togepi stand up.', 'Sixth', '40', 'https://images.pokemoncard.io/images/xy6/xy6-43.png', 'unlimited: Legal, expanded: Legal', '', 'Togepi', '175', 'TPCI', 'Common', '', '05/06/2015', 'type: Darkness, value: -20', 'Colorless', '', 'XY', '43', 'Basic', 'Pokémon', 'Fairy', 'type: Metal, value: ×2'),
('xy6-44', '', '', 'Kanako Eo', '[{\'name\': \'Go Fetch\', \'cost\': [\'Fairy\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Shuffle 3 basic Energy cards from your discard pile into your deck.\'}, {\'name\': \'Fairy Wind\', \'cost\': [\'Fairy\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40\', \'text\': \'\'}]', 'Roaring Skies', '1', 'Togepi', 'Togekiss', 'They say that it will appear before kindhearted, caring people and shower them with happiness.', 'Sixth', '80', 'https://images.pokemoncard.io/images/xy6/xy6-44.png', 'unlimited: Legal, expanded: Legal', '', 'Togetic', '176', 'TPCI', 'Uncommon', '', '05/06/2015', 'type: Darkness, value: -20', 'Colorless', '', 'XY', '44', 'Stage 1', 'Pokémon', 'Fairy', 'type: Metal, value: ×2'),
('xy6-45', '', '', 'Sumiyoshi Kizuki', '[{\'name\': \'Powerful Slap\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'50×\', \'text\': \'Flip a coin for each Energy attached to this Pokémon. This attack does 50 damage times the number of heads.\'}, {\'name\': \'Aura Sphere\', \'cost\': [\'Fairy\', \'Fairy\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'70\', \'text\': \"This attack does 20 damage to 1 of your opponent\'s Benched Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'Roaring Skies', '2', 'Togetic', '', 'It shares many blessings with people who respect one anothers rights and avoid needless strife.', 'Sixth', '140', 'https://images.pokemoncard.io/images/xy6/xy6-45.png', 'unlimited: Legal, expanded: Legal', '', 'Togekiss', '468', 'TPCI', 'Rare', '', '05/06/2015', 'type: Darkness, value: -20', 'Colorless, Colorless', '', 'XY', '45', 'Stage 2', 'Pokémon', 'Fairy', 'type: Metal, value: ×2'),
('xy6-46', '[{\'name\': \'Serene Grace\', \'text\': \'When you play this Pokémon from your hand to evolve 1 of your Pokémon, you may look at the top 8 cards of your deck. Choose any basic Energy cards you find there and attach them to your Pokémon in any way you like. Shuffle the other cards back into your deck.\', \'type\': \'Ability\'}]', 'name: Δ Evolution, text: You may play this card from your hand to evolve a Pokémon during your first turn or the turn you play that Pokémon.', 'PLANETA', '[{\'name\': \'Fairy Wind\', \'cost\': [\'Fairy\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60\', \'text\': \'\'}]', 'Roaring Skies', '1', 'Togetic', '', 'It shares many blessings with people who respect one anothers rights and avoid needless strife.', 'Sixth', '130', 'https://images.pokemoncard.io/images/xy6/xy6-46.png', 'unlimited: Legal, expanded: Legal', '', 'Togekiss', '468', 'TPCI', 'Rare Holo', '', '05/06/2015', 'type: Darkness, value: -20', 'Colorless', '', 'XY', '46', 'Stage 2', 'Pokémon', 'Fairy', 'type: Metal, value: ×2'),
('xy6-47', '[{\'name\': \'Jewel Armor\', \'text\': \"As long as this Pokémon is on your Bench, prevent all damage done to this Pokémon by attacks (both yours and your opponent\'s).\", \'type\': \'Ability\'}]', '', 'Akira Komayama', '[{\'name\': \'Spin Tackle\', \'cost\': [\'Fairy\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60\', \'text\': \'Flip a coin. If tails, this Pokémon does 20 damage to itself.\'}]', 'Roaring Skies', '2', '', '', 'Born from temperatures and pressures deep underground, it fires beams from the stone in its head.', 'Sixth', '70', 'https://images.pokemoncard.io/images/xy6/xy6-47.png', 'unlimited: Legal, expanded: Legal', '', 'Carbink', '703', 'TPCI', 'Rare', '', '05/06/2015', 'type: Darkness, value: -20', 'Colorless, Colorless', '', 'XY', '47', 'Basic', 'Pokémon', 'Fairy', 'type: Metal, value: ×2'),
('xy6-48', '', '', 'Kagemaru Himeno', '[{\'name\': \'Look for Keys\', \'cost\': [\'Fairy\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Reveal cards from the top of your deck until you reveal an Item card. Put it into your hand. Shuffle the other cards back into your deck.\'}, {\'name\': \'Play Rough\', \'cost\': [\'Fairy\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20+\', \'text\': \'Flip a coin. If heads, this attack does 20 more damage.\'}]', 'Roaring Skies', '1', '', '', 'These key collectors threaten any attackers by fiercely jingling their keys at them.', 'Sixth', '60', 'https://images.pokemoncard.io/images/xy6/xy6-48.png', 'unlimited: Legal, expanded: Legal', '', 'Klefki', '707', 'TPCI', 'Rare', '', '05/06/2015', 'type: Darkness, value: -20', 'Colorless', '', 'XY', '48', 'Basic', 'Pokémon', 'Fairy', 'type: Metal, value: ×2'),
('xy6-49', '', '', 'Miki Tanaka', '[{\'name\': \'Hook\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'\'}, {\'name\': \'Slam\', \'cost\': [\'Lightning\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20×\', \'text\': \'Flip 2 coins. This attack does 20 damage times the number of heads.\'}]', 'Roaring Skies', '1', '', 'Dragonair', 'This Pokémon is full of life energy. It continually sheds its skin and grows steadily larger.', 'Sixth', '50', 'https://images.pokemoncard.io/images/xy6/xy6-49.png', 'unlimited: Legal, expanded: Legal', '', 'Dratini', '147', 'TPCI', 'Common', '', '05/06/2015', '', 'Colorless', '', 'XY', '49', 'Basic', 'Pokémon', 'Dragon', 'type: Fairy, value: ×2'),
('xy6-5', '[{\'name\': \'Miraculous Scales\', \'text\': \"Prevent all damage done to this Pokémon by attacks from your opponent\'s Pokémon-EX.\", \'type\': \'Ability\'}]', '', 'Midori Harada', '[{\'name\': \'Whirlwind\', \'cost\': [\'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'80\', \'text\': \'You may have your opponent switch his or her Active Pokémon with 1 of his or her Benched Pokémon.\'}]', 'Roaring Skies', '', 'Silcoon', '', 'It has an aggressive nature. It stabs prey with its long, narrow mouth to drain the preys fluids.', 'Sixth', '130', 'https://images.pokemoncard.io/images/xy6/xy6-5.png', 'unlimited: Legal, expanded: Legal', '', 'Beautifly', '267', 'TPCI', 'Rare Holo', '', '05/06/2015', '', '', '', 'XY', '5', 'Stage 2', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('xy6-50', '', '', 'Mizue', '[{\'name\': \'Shed Skin\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Heal 30 damage from this Pokémon.\'}, {\'name\': \'Slam\', \'cost\': [\'Grass\', \'Lightning\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60×\', \'text\': \'Flip 2 coins. This attack does 60 damage times the number of heads.\'}]', 'Roaring Skies', '2', 'Dratini', 'Dragonite', 'A mystical Pokémon that exudes a gentle aura. It is said to have the ability to change the weather.', 'Sixth', '80', 'https://images.pokemoncard.io/images/xy6/xy6-50.png', 'unlimited: Legal, expanded: Legal', '', 'Dragonair', '148', 'TPCI', 'Uncommon', '', '05/06/2015', '', 'Colorless, Colorless', '', 'XY', '50', 'Stage 1', 'Pokémon', 'Dragon', 'type: Fairy, value: ×2'),
('xy6-51', '[{\'name\': \'Max Wind\', \'text\': \'When you play this Pokémon from your hand to evolve 1 of your Pokémon, you may heal all damage from 1 of your Pokémon.\', \'type\': \'Ability\'}]', '', 'kawayoo', '[{\'name\': \'Mach Press\', \'cost\': [\'Grass\', \'Lightning\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'80\', \'text\': \"Flip 2 coins. If both of them are heads, your opponent\'s Active Pokémon is now Paralyzed.\"}]', 'Roaring Skies', '3', 'Dragonair', '', 'It is said to make its home somewhere in the sea. It guides crews of shipwrecks to shore.', 'Sixth', '150', 'https://images.pokemoncard.io/images/xy6/xy6-51.png', 'unlimited: Legal, expanded: Legal', '', 'Dragonite', '149', 'TPCI', 'Rare', '', '05/06/2015', '', 'Colorless, Colorless, Colorless', '', 'XY', '51', 'Stage 2', 'Pokémon', 'Dragon', 'type: Fairy, value: ×2'),
('xy6-52', '', 'name: Δ Plus, text: If your opponents Pokémon is Knocked Out by damage from an attack of this Pokémon, take 1 more Prize card.', 'hatachu', '[{\'name\': \'Wrapped in Wind\', \'cost\': [\'Lightning\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Attach up to 2 basic Energy cards from your hand to this Pokémon.\'}, {\'name\': \'Heavy Impact\', \'cost\': [\'Grass\', \'Grass\', \'Grass\', \'Lightning\', \'Colorless\'], \'convertedEnergyCost\': 5, \'damage\': \'150\', \'text\': \'\'}]', 'Roaring Skies', '4', 'Dragonair', '', 'It is said to make its home somewhere in the sea. It guides crews of shipwrecks to shore.', 'Sixth', '160', 'https://images.pokemoncard.io/images/xy6/xy6-52.png', 'unlimited: Legal, expanded: Legal', '', 'Dragonite', '149', 'TPCI', 'Rare Holo', '', '05/06/2015', '', 'Colorless, Colorless, Colorless, Colorless', '', 'XY', '52', 'Stage 2', 'Pokémon', 'Dragon', 'type: Fairy, value: ×2'),
('xy6-53', '', '', 'Mitsuhiro Arita', '[{\'name\': \'Song of Echoes\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Shuffle your hand into your deck. Then, draw a number of cards equal to the number of Benched Pokémon (both yours and your opponent\'s).\"}, {\'name\': \'Midnight Eyes\', \'cost\': [\'Water\', \'Metal\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \"Your opponent\'s Active Pokémon is now Asleep.\"}]', 'Roaring Skies', '1', 'Swablu', '', 'On sunny days, it flies freely through the sky and blends into the clouds. It sings in a beautiful soprano.', 'Sixth', '80', 'https://images.pokemoncard.io/images/xy6/xy6-53.png', 'unlimited: Legal, expanded: Legal', '', 'Altaria', '334', 'TPCI', 'Uncommon', '', '05/06/2015', '', 'Colorless', '', 'XY', '53', 'Stage 1', 'Pokémon', 'Dragon', 'type: Fairy, value: ×2'),
('xy6-54', '', '', 'Kagemaru Himeno', '[{\'name\': \'Continuous Headbutt\', \'cost\': [\'Fire\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30×\', \'text\': \'Flip a coin until you get tails. This attack does 30 damage times the number of heads.\'}]', 'Roaring Skies', '1', '', 'Shelgon', 'Dreaming of one day flying, it practices by leaping off cliffs every day.', 'Sixth', '60', 'https://images.pokemoncard.io/images/xy6/xy6-54.png', 'unlimited: Legal, expanded: Legal', '', 'Bagon', '371', 'TPCI', 'Common', '', '05/06/2015', '', 'Colorless', '', 'XY', '54', 'Basic', 'Pokémon', 'Dragon', 'type: Fairy, value: ×2'),
('xy6-55', '', '', 'kirisAki', '[{\'name\': \'Leer\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Flip a coin. If heads, your opponent\'s Active Pokémon is now Paralyzed.\"}, {\'name\': \'Almost Flight\', \'cost\': [\'Fire\', \'Water\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'This Pokémon does 10 damage to itself.\'}]', 'Roaring Skies', '1', '', 'Shelgon', 'Dreaming of one day flying, it practices by leaping off cliffs every day.', 'Sixth', '60', 'https://images.pokemoncard.io/images/xy6/xy6-55.png', 'unlimited: Legal, expanded: Legal', '', 'Bagon', '371', 'TPCI', 'Common', '', '05/06/2015', '', 'Colorless', '', 'XY', '55', 'Basic', 'Pokémon', 'Dragon', 'type: Fairy, value: ×2'),
