('xy8-145', '', '', '5ban Graphics', '', 'BREAKthrough', '', '', '', '', 'Sixth', '', 'https://images.pokemoncard.io/images/xy8/xy8-145.png', 'unlimited: Legal, expanded: Legal', '', 'Parallel City', '', 'TPCI', 'Uncommon', '', '11/04/2015', '', '', '[\"Choose which way this card faces before you play it. This ↓ player can\'t have more than 3 Benched Pokémon. (When this card comes into play, this ↓ player discards Benched Pokémon until he or she has 3 Pokémon on the Bench.)\", \"Choose which way this card faces before you play it. Any damage done by attacks from this ↓ player\'s Grass, Fire, or Water Pokémon is reduced by 20 (before applying Weakness and Resistance).\", \"This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can\'t play this card.\"]', 'XY', '145', 'Stadium', 'Trainer', '', ''),
('xy8-146', '', '', '5ban Graphics', '', 'BREAKthrough', '', '', '', '', 'Sixth', '', 'https://images.pokemoncard.io/images/xy8/xy8-146.png', 'unlimited: Legal, expanded: Legal', '', 'Professors Letter', '', 'TPCI', 'Uncommon', '', '11/04/2015', '', '', '[\'Search your deck for up to 2 basic Energy cards, reveal them, and put them into your hand. Shuffle your deck afterward.\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'XY', '146', 'Item', 'Trainer', '', ''),
('xy8-146a', '', '', 'Yoshinobu Saito', '', 'BREAKthrough', '', '', '', '', 'Sixth', '', 'https://images.pokemoncard.io/images/xy8/xy8-146a.png', 'unlimited: Legal, expanded: Legal', '', 'Professors Letter', '', 'TPCI', 'Uncommon', '', '11/04/2015', '', '', '[\'Search your deck for up to 2 basic Energy cards, reveal them, and put them into your hand. Shuffle your deck afterward.\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'XY', '146a', 'Item', 'Trainer', '', ''),
('xy8-147', '', '', 'Toyste Beach', '', 'BREAKthrough', '', '', '', '', 'Sixth', '', 'https://images.pokemoncard.io/images/xy8/xy8-147.png', 'unlimited: Legal, expanded: Legal', '', 'Reserved Ticket', '', 'TPCI', 'Uncommon', '', '11/04/2015', '', '', '[\'Flip a coin. If heads, search your deck for a card, shuffle your deck, then put that card on top of it.\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'XY', '147', 'Item', 'Trainer', '', ''),
('xy8-148', '', '', 'Yusuke Ohmura', '', 'BREAKthrough', '', '', '', '', 'Sixth', '', 'https://images.pokemoncard.io/images/xy8/xy8-148.png', 'unlimited: Legal, expanded: Legal', '', 'Skyla', '', 'TPCI', 'Uncommon', '', '11/04/2015', '', '', '[\'Search your deck for a Trainer card, reveal it, and put it into your hand. Shuffle your deck afterward.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'XY', '148', 'Supporter', 'Trainer', '', ''),
('xy8-149', '', '', 'Toyste Beach', '', 'BREAKthrough', '', '', '', '', 'Sixth', '', 'https://images.pokemoncard.io/images/xy8/xy8-149.png', 'standard: Legal, unlimited: Legal, expanded: Legal', '', 'Super Rod', '', 'TPCI', 'Uncommon', '', '11/04/2015', '', '', '[\'Shuffle 3 in any combination of Pokémon and basic Energy cards from your discard pile into your deck.\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'XY', '149', 'Item', 'Trainer', '', ''),
('xy8-15', '[{\'name\': \'Energy Color\', \'text\': \'Once during your turn (before your attack), you may flip a coin. If heads, search your deck for a basic Energy card and attach it to 1 of your Pokémon. Shuffle your deck afterward.\', \'type\': \'Ability\'}]', '', 'Mizue', '[{\'name\': \'Sleep Powder\', \'cost\': [\'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60\', \'text\': \"Your opponent\'s Active Pokémon is now Asleep.\"}]', 'BREAKthrough', '1', 'Spewpa', '', 'The patterns on this Pokémons wings depend on the climate and topography of its habitat. It scatters colorful scales.', 'Sixth', '120', 'https://images.pokemoncard.io/images/xy8/xy8-15.png', 'unlimited: Legal, expanded: Legal', '', 'Vivillon', '666', 'TPCI', 'Rare Holo', '', '11/04/2015', '', 'Colorless', '', 'XY', '15', 'Stage 2', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('xy8-150', '', '', 'Toyste Beach', '', 'BREAKthrough', '', '', '', '', 'Sixth', '', 'https://images.pokemoncard.io/images/xy8/xy8-150.png', 'unlimited: Legal, expanded: Legal', '', 'Town Map', '', 'TPCI', 'Uncommon', '', '11/04/2015', '', '', '[\'Turn all of your Prize cards face up. (Those Prize cards remain face up for the rest of the game.)\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'XY', '150', 'Item', 'Trainer', '', ''),
('xy8-151', '', '', '5ban Graphics', '', 'BREAKthrough', '', '', '', '', 'Sixth', '', 'https://images.pokemoncard.io/images/xy8/xy8-151.png', 'unlimited: Legal, expanded: Legal', '', 'Burning Energy', '', 'TPCI', 'Uncommon', '', '11/04/2015', '', '', '[\'This card can only be attached to Fire Pokémon. This card provides Fire Energy only while this card is attached to a Fire Pokémon.\', \'If this card is discarded by an attack of the Fire Pokémon this card is attached to, attach this card from your discard pile to that Pokémon after attacking.\', \'(If this card is attached to anything other than a Fire Pokémon, discard this card.)\']', 'XY', '151', 'Special', 'Energy', '', ''),
('xy8-152', '', '', '5ban Graphics', '', 'BREAKthrough', '', '', '', '', 'Sixth', '', 'https://images.pokemoncard.io/images/xy8/xy8-152.png', 'unlimited: Legal, expanded: Legal', '', 'Rainbow Energy', '', 'TPCI', 'Uncommon', '', '11/04/2015', '', '', '[\'This card provides Colorless Energy. While in play, this card provides every type of Energy but provides only 1 Energy at a time. When you attach this card from your hand to 1 of your Pokémon, put 1 damage counter on that Pokémon.\']', 'XY', '152', 'Special', 'Energy', '', ''),
('xy8-153', '', '', 'Ryo Ueda', '[{\'name\': \'Melting Horn\', \'cost\': [\'Fire\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Discard the top 2 cards of your opponent\'s deck.\"}, {\'name\': \'Grand Flame\', \'cost\': [\'Fire\', \'Fire\'], \'convertedEnergyCost\': 2, \'damage\': \'50\', \'text\': \'Attach a Fire Energy card from your discard pile to 1 of your Benched Pokémon.\'}]', 'BREAKthrough', '2', '', 'M Houndoom-EX', '', 'Sixth', '170', 'https://images.pokemoncard.io/images/xy8/xy8-153.png', 'unlimited: Legal, expanded: Legal', '', 'Houndoom-EX', '229', 'TPCI', 'Rare Ultra', '', '11/04/2015', '', 'Colorless, Colorless', '[\'Pokémon-EX rule: When a Pokémon-EX has been Knocked Out, your opponent takes 2 Prize cards.\']', 'XY', '153', 'Basic, EX', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('xy8-154', '', '', '5ban Graphics', '[{\'name\': \'Inferno Fang\', \'cost\': [\'Fire\', \'Fire\'], \'convertedEnergyCost\': 2, \'damage\': \'80+\', \'text\': \'You may discard all Fire Energy attached to this Pokémon. If you do, this attack does 80 more damage.\'}]', 'BREAKthrough', '1', 'Houndoom-EX', '', '', 'Sixth', '210', 'https://images.pokemoncard.io/images/xy8/xy8-154.png', 'unlimited: Legal, expanded: Legal', '', 'M Houndoom-EX', '229', 'TPCI', 'Rare Ultra', '', '11/04/2015', '', 'Colorless', '[\'Mega Evolution rule: When 1 of your Pokémon becomes a Mega Evolution Pokémon, your turn ends.\', \'Pokémon-EX rule: When a Pokémon-EX has been Knocked Out, your opponent takes 2 Prize cards.\']', 'XY', '154', 'MEGA, EX', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('xy8-155', '', '', 'Ryo Ueda', '[{\'name\': \'Ice Breath\', \'cost\': [\'Water\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Flip a coin. If heads, your opponent\'s Active Pokémon is now Paralyzed.\"}, {\'name\': \'Instant Freeze\', \'cost\': [\'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50+\', \'text\': \'If you have the same number of cards in your hand as your opponent, this attack does 100 more damage.\'}]', 'BREAKthrough', '3', '', 'Froslass', '', 'Sixth', '170', 'https://images.pokemoncard.io/images/xy8/xy8-155.png', 'unlimited: Legal, expanded: Legal', '', 'Glalie-EX', '362', 'TPCI', 'Rare Ultra', '', '11/04/2015', '', 'Colorless, Colorless, Colorless', '[\'Pokémon-EX rule: When a Pokémon-EX has been Knocked Out, your opponent takes 2 Prize cards.\']', 'XY', '155', 'Basic, EX', 'Pokémon', 'Water', 'type: Metal, value: ×2'),
