('xy8-161', '', '', 'Megumi Mizutani', '', 'BREAKthrough', '', '', '', '', 'Sixth', '', 'https://images.pokemoncard.io/images/xy8/xy8-161.png', 'unlimited: Legal, expanded: Legal', '', 'Brigette', '', 'TPCI', 'Rare Ultra', '', '11/04/2015', '', '', '[\'Search your deck for 1 Basic Pokémon-EX or 3 Basic Pokémon (except for Pokémon-EX), and put them onto your Bench. Shuffle your deck afterward.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'XY', '161', 'Supporter', 'Trainer', '', ''),
('xy8-162', '', '', 'Ken Sugimori', '', 'BREAKthrough', '', '', '', '', 'Sixth', '', 'https://images.pokemoncard.io/images/xy8/xy8-162.png', 'unlimited: Legal, expanded: Legal', '', 'Giovannis Scheme', '', 'TPCI', 'Rare Ultra', '', '11/04/2015', '', '', '[\"Choose 1:\\n• Draw cards until you have 5 cards in your hand.\\n• During this turn, your Pokémon\'s attacks do 20 more damage to your opponent\'s Active Pokémon (before applying Weakness and Resistance).\", \'You may play only 1 Supporter card during your turn (before your attack).\']', 'XY', '162', 'Supporter', 'Trainer', '', ''),
