('xyp-XY130', '[{\'name\': \'Raging Roar\', \'text\': \'When you play this Pokémon from your hand to evolve 1 of your Pokémon, you may attach 1 Darkness Energy from your discard pile to this Pokémon for each Prize card your opponent has taken.\', \'type\': \'Ability\'}]', '', 'Satoshi Shirai', '[{\'name\': \'Dark Mountain\', \'cost\': [\'Darkness\', \'Darkness\', \'Darkness\', \'Darkness\', \'Darkness\'], \'convertedEnergyCost\': 5, \'damage\': \'150+\', \'text\': \'Discard the top 2 cards of your deck. This attack does 50 more damage for each Supporter card discard in this way.\'}]', 'XY Black Star Promos', '4', 'Pupitar', '', 'If it rampages, it knocks down mountains and buries rivers. Maps must be redrawn afterward.', 'Fifth', '160', 'https://images.pokemoncard.io/images/xyp/xyp-XY130.png', 'unlimited: Legal, expanded: Legal', '', 'Tyranitar', '248', 'TPCI', 'Promo', '', '10/12/2013', 'type: Psychic, value: -20', 'Colorless, Colorless, Colorless, Colorless', '', 'XY', 'XY130', 'Stage 2', 'Pokémon', 'Darkness', 'type: Fighting, value: ×2'),
('xyp-XY131', '', '', 'sui', '[{\'name\': \'Fury Swipes\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'10×\', \'text\': \'Flip 3 coins. This attack does 10 damage times the number of heads.\'}]', 'XY Black Star Promos', '1', '', 'Simisear', 'This Pokémon lives in caves with volcanoes. The fire within the tuft on its head can reach 600 degrees Fahrenheit.', 'Fifth', '60', 'https://images.pokemoncard.io/images/xyp/xyp-XY131.png', 'unlimited: Legal, expanded: Legal', '', 'Pansear', '513', 'TPCI', 'Promo', '', '10/12/2013', '', 'Colorless', '', 'XY', 'XY131', 'Basic', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('xyp-XY132', '', '', 'Shigenori Negishi', '[{\'name\': \'Sleep Poison\', \'cost\': [\'Psychic\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Flip a coin. If heads, your opponent\'s Active Pokémon is now Asleep and Poisoned.\"}]', 'XY Black Star Promos', '1', '', 'Haunter', 'Born from gases, anyone would faint if engulfed by its gaseous body, which contains poison.', 'Fifth', '50', 'https://images.pokemoncard.io/images/xyp/xyp-XY132.png', 'unlimited: Legal, expanded: Legal', '', 'Gastly', '92', 'TPCI', 'Promo', '', '10/12/2013', 'type: Fighting, value: -20', 'Colorless', '', 'XY', 'XY132', 'Basic', 'Pokémon', 'Psychic', 'type: Darkness, value: ×2'),
('xyp-XY133', '', '', '5ban Graphics', '[{\'name\': \'Dancing Shuriken\', \'cost\': [\'Water\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'\', \'text\': \"Flip 3 coins. This attack does 20 damage times the number of heads to 1 of your opponent\'s Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}, {\'name\': \'Ninja Blade\', \'cost\': [\'Water\', \'Water\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'130\', \'text\': \"This Pokémon can\'t use Ninja Blade during your next turn.\"}]', 'XY Black Star Promos', '1', '', '', '', 'Fifth', '170', 'https://images.pokemoncard.io/images/xyp/xyp-XY133.png', 'unlimited: Legal, expanded: Legal', '', 'Ash-Greninja-EX', '658', 'TPCI', 'Promo', '', '10/12/2013', '', 'Colorless', '[\'Pokémon-EX rule: When a Pokémon-EX has been Knocked Out, your opponent takes 2 Prize cards.\']', 'XY', 'XY133', 'Basic, EX', 'Pokémon', 'Water', 'type: Grass, value: ×2'),
('xyp-XY134', '', '', '5ban Graphics', '[{\'name\': \"Emperor\'s Command\", \'cost\': [\'Water\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30×\', \'text\': \'This attack does 30 damage times the number of Pokémon your opponent has in play.\'}]', 'XY Black Star Promos', '', 'Empoleon', '', '', 'Fifth', '170', 'https://images.pokemoncard.io/images/xyp/xyp-XY134.png', 'unlimited: Legal, expanded: Legal', '', 'Empoleon BREAK', '395', 'TPCI', 'Promo', '', '10/12/2013', '', '', '[\'BREAK Evolution Rule: Empoleon BREAK retains the attacks, Abilities, Weakness, Resistance, and Retreat Cost of its previous Evolution.\']', 'XY', 'XY134', 'BREAK', 'Pokémon', 'Water', ''),
('xyp-XY135', '', '', '5ban Graphics', '[{\'name\': \'Cosmic Circle\', \'cost\': [\'Psychic\', \'Psychic\', \'Psychic\'], \'convertedEnergyCost\': 3, \'damage\': \'100\', \'text\': \'Move as many Psychic Energy attached to your Pokémon to your other Pokémon in any way you like.\'}]', 'XY Black Star Promos', '', 'Beheeyem', '', '', 'Fifth', '130', 'https://images.pokemoncard.io/images/xyp/xyp-XY135.png', 'unlimited: Legal, expanded: Legal', '', 'Beheeyem BREAK', '606', 'TPCI', 'Promo', '', '10/12/2013', '', '', '[\'BREAK Evolution Rule: Beheeyem BREAK retains the attacks, Abilities, Weakness, Resistance, and Retreat Cost of its previous Evolution.\']', 'XY', 'XY135', 'BREAK', 'Pokémon', 'Psychic', ''),
('xyp-XY136', '', '', '5ban Graphics', '[{\'name\': \'Night Scan\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60+\', \'text\': \'Your opponent reveals his or her hand. This attack does 30 more damage for each Trainer card you find there.\'}]', 'XY Black Star Promos', '', 'Noctowl', '', '', 'Fifth', '130', 'https://images.pokemoncard.io/images/xyp/xyp-XY136.png', 'unlimited: Legal, expanded: Legal', '', 'Noctowl BREAK', '164', 'TPCI', 'Promo', '', '10/12/2013', '', '', '[\'BREAK Evolution Rule: Noctowl BREAK retains the attacks, Abilities, Weakness, Resistance, and Retreat Cost of its previous Evolution.\']', 'XY', 'XY136', 'BREAK', 'Pokémon', 'Colorless', ''),
('xyp-XY137', '', '', 'match', '[{\'name\': \'Dizzying Poison\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Your opponent\'s Active Pokémon is now Confused and Poisoned.\"}, {\'name\': \'Powder\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'30+\', \'text\': \"This attack does 30 more damage for each Fire Energy attached to your opponent\'s Active Pokémon.\"}]', 'XY Black Star Promos', '1', 'Spewpa', '', 'The patterns on this Pokémons wings depend on the climate and topography of its habitat. It scatters colorful scales.', 'Fifth', '120', 'https://images.pokemoncard.io/images/xyp/xyp-XY137.png', 'unlimited: Legal, expanded: Legal', '', 'Vivillon', '666', 'TPCI', 'Promo', '', '10/12/2013', '', 'Colorless', '', 'XY', 'XY137', 'Stage 2', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('xyp-XY138', '', '', 'Sanosuke Sakuma', '[{\'name\': \'Bubble\', \'cost\': [\'Water\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Flip a coin. If heads, your opponent\'s Active Pokémon is now Paralyzed.\"}]', 'XY Black Star Promos', '1', '', 'Frogadier', 'It protects its skin by covering its body in delicate bubbles. Beneath its happy-go-lucky air, it keeps a watchful eye on its surroundings.', 'Fifth', '60', 'https://images.pokemoncard.io/images/xyp/xyp-XY138.png', 'unlimited: Legal, expanded: Legal', '', 'Froakie', '656', 'TPCI', 'Promo', '', '10/12/2013', '', 'Colorless', '', 'XY', 'XY138', 'Basic', 'Pokémon', 'Water', 'type: Grass, value: ×2'),
('xyp-XY139', '', '', 'Midori Harada', '[{\'name\': \'Aromatherapy\', \'cost\': [\'Fairy\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Heal 30 damage from each of your Pokémon.\'}, {\'name\': \'Magical Leaf\', \'cost\': [\'Fairy\', \'Fairy\'], \'convertedEnergyCost\': 2, \'damage\': \'20+\', \'text\': \'Flip a coin. If heads, this attack does 20 more damage and heal 20 damage from this Pokémon.\'}]', 'XY Black Star Promos', '1', 'Flabebe', 'Florges', 'When the flowers of a well-tended flower bed bloom, it appears and celebrates with an elegant dance.', 'Fifth', '70', 'https://images.pokemoncard.io/images/xyp/xyp-XY139.png', 'unlimited: Legal, expanded: Legal', '', 'Floette', '670', 'TPCI', 'Promo', '', '10/12/2013', 'type: Darkness, value: -20', 'Colorless', '', 'XY', 'XY139', 'Stage 1', 'Pokémon', 'Fairy', 'type: Metal, value: ×2'),
('xyp-XY14', '', '', 'Kouki Saitou', '[{\'name\': \'Eerie Wave\', \'cost\': [\'Psychic\'], \'convertedEnergyCost\': 1, \'damage\': \'20\', \'text\': \"Your opponent\'s Active Pokémon is now Confused.\"}, {\'name\': \'Wood Hammer\', \'cost\': [\'Psychic\', \'Psychic\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'90\', \'text\': \'Flip a coin. If tails, this Pokémon does 20 damage to itself.\'}]', 'XY Black Star Promos', '3', 'Phantump', '', 'It can control trees at will. It will trap people who harm the forest, so they can never leave.', 'Fifth', '110', 'https://images.pokemoncard.io/images/xyp/xyp-XY14.png', 'unlimited: Legal, expanded: Legal', '', 'Trevenant', '709', 'TPCI', 'Promo', '', '10/12/2013', 'type: Fighting, value: -20', 'Colorless, Colorless, Colorless', '', 'XY', 'XY14', 'Stage 1', 'Pokémon', 'Psychic', 'type: Darkness, value: ×2'),
('xyp-XY140', '', '', 'Naoki Saito', '[{\'name\': \'Bone Rush\', \'cost\': [\'Fighting\'], \'convertedEnergyCost\': 1, \'damage\': \'30×\', \'text\': \'Flip a coin until you get tails. This attack does 30 damage times the number of heads.\'}, {\'name\': \'Mach Claw\', \'cost\': [\'Fighting\', \'Fighting\', \'Fighting\'], \'convertedEnergyCost\': 3, \'damage\': \'90\', \'text\': \"This attack\'s damage isn\'t affected by Resistance.\"}]', 'XY Black Star Promos', '2', 'Riolu', '', 'By reading the auras of all things, it can tell how others are feeling from over half a mile away.', 'Fifth', '100', 'https://images.pokemoncard.io/images/xyp/xyp-XY140.png', 'unlimited: Legal, expanded: Legal', '', 'Lucario', '448', 'TPCI', 'Promo', '', '10/12/2013', '', 'Colorless, Colorless', '', 'XY', 'XY140', 'Stage 1', 'Pokémon', 'Fighting', 'type: Psychic, value: ×2'),
('xyp-XY141', '', '', 'Masakazu Fukuda', '[{\'name\': \'Dual Claw\', \'cost\': [\'Fire\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20×\', \'text\': \'Flip 2 coins. This attack does 20 damage times the number of heads.\'}, {\'name\': \'Dragon Blast\', \'cost\': [\'Fire\', \'Lightning\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'120\', \'text\': \'Discard 1 Fire Energy and 1 Lightning Energy attached to this Pokémon.\'}]', 'XY Black Star Promos', '2', '', '', 'It flies in the ozone layer, way up high in the sky. Until recently, no one had ever seen it.', 'Fifth', '120', 'https://images.pokemoncard.io/images/xyp/xyp-XY141.png', 'unlimited: Legal, expanded: Legal', '', 'Rayquaza', '384', 'TPCI', 'Promo', '', '10/12/2013', '', 'Colorless, Colorless', '', 'XY', 'XY141', 'Basic', 'Pokémon', 'Dragon', 'type: Fairy, value: ×2'),
('xyp-XY142', '', '', 'chibi', '[{\'name\': \'Shining Eyes\', \'cost\': [\'Psychic\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Put 2 damage counters on each of your opponent\'s Pokémon that has any damage counters on it.\"}, {\'name\': \'Mind Bend\', \'cost\': [\'Psychic\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'30\', \'text\': \"Your opponent\'s Active Pokémon is now Confused.\"}]', 'XY Black Star Promos', '1', '', '', 'It is thought that Uxie, Mesprit, and Azelf all came from the same egg.', 'Fifth', '70', 'https://images.pokemoncard.io/images/xyp/xyp-XY142.png', 'unlimited: Legal, expanded: Legal', '', 'Azelf', '482', 'TPCI', 'Promo', '', '10/12/2013', '', 'Colorless', '', 'XY', 'XY142', 'Basic', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2'),
('xyp-XY143', '', '', 'Saya Tsuruta', '[{\'name\': \'Epic Splash\', \'cost\': [\'Water\'], \'convertedEnergyCost\': 1, \'damage\': \'30\', \'text\': \'Flip 2 coins. If either of them is tails, this attack does nothing.\'}]', 'XY Black Star Promos', '1', '', 'Gyarados', 'In the distant past, it was somewhat stronger than the horribly weak descendants that exist today.', 'Fifth', '30', 'https://images.pokemoncard.io/images/xyp/xyp-XY143.png', 'unlimited: Legal, expanded: Legal', '', 'Magikarp', '129', 'TPCI', 'Promo', '', '10/12/2013', '', 'Colorless', '', 'XY', 'XY143', 'Basic', 'Pokémon', 'Water', 'type: Lightning, value: ×2'),
('xyp-XY144', '[{\'name\': \'Sonic Vision\', \'text\': \"If you have exactly 4 cards in your hand, ignore all Energy in the attack cost of each of this Pokémon\'s attacks.\", \'type\': \'Ability\'}]', '', 'Midori Harada', '[{\'name\': \'Assault Boom\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50+\', \'text\': \"If your opponent\'s Active Pokémon has a Pokémon Tool card attached to it, this attack does 70 more damage.\"}]', 'XY Black Star Promos', '', 'Yanma', '', 'This six-legged Pokémon is easily capable of transporting an adult in flight. The wings on its tail help it stay balanced.', 'Fifth', '110', 'https://images.pokemoncard.io/images/xyp/xyp-XY144.png', 'unlimited: Legal, expanded: Legal', '', 'Yanmega', '469', 'TPCI', 'Promo', '', '10/12/2013', 'type: Fighting, value: -20', '', '', 'XY', 'XY144', 'Stage 1', 'Pokémon', 'Grass', 'type: Lightning, value: ×2'),
('xyp-XY145', '', '', '5ban Graphics', '[{\'name\': \'Power Heater\', \'cost\': [\'Fire\'], \'convertedEnergyCost\': 1, \'damage\': \'20\', \'text\': \'Choose 2 of your Benched Pokémon. Attach a Fire Energy card from your discard pile to each of those Pokémon.\'}, {\'name\': \'Steam Artillery\', \'cost\': [\'Fire\', \'Fire\', \'Fire\'], \'convertedEnergyCost\': 3, \'damage\': \'100\', \'text\': \'\'}]', 'XY Black Star Promos', '2', '', '', 'It expels its internal steam from the arms on its back. It has enough power to blow away a mountain.', 'Fifth', '130', 'https://images.pokemoncard.io/images/xyp/xyp-XY145.png', 'unlimited: Legal, expanded: Legal', '', 'Volcanion', '721', 'TPCI', 'Promo', '', '10/12/2013', '', 'Colorless, Colorless', '', 'XY', 'XY145', 'Basic', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('xyp-XY146', '[{\'name\': \'Mega Boost\', \'text\': \'Once during your turn (before your attack), you may attach a Special Energy card from your hand to 1 of your Mega Evolution Pokémon.\', \'type\': \'Ability\'}]', '', 'Mitsuhiro Arita', '[{\'name\': \'Crabhammer\', \'cost\': [\'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60\', \'text\': \'\'}]', 'XY Black Star Promos', '2', 'Clauncher', '', 'By expelling water from the nozzle in the back of its claw, it can move at a speed of 60 knots.', 'Fifth', '100', 'https://images.pokemoncard.io/images/xyp/xyp-XY146.png', 'unlimited: Legal, expanded: Legal', '', 'Clawitzer', '693', 'TPCI', 'Promo', '', '10/12/2013', '', 'Colorless, Colorless', '', 'XY', 'XY146', 'Stage 1', 'Pokémon', 'Water', 'type: Grass, value: ×2'),
('xyp-XY147', '', '', 'Yoshinobu Saito', '[{\'name\': \'Hyperspace Punch\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"This attack does 20 damage to 2 of your opponent\'s Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}, {\'name\': \'Portal Strike\', \'cost\': [\'Psychic\', \'Psychic\', \'Psychic\'], \'convertedEnergyCost\': 3, \'damage\': \'130\', \'text\': \"This Pokémon can\'t use Portal Strike during your next turn.\"}]', 'XY Black Star Promos', '2', '', '', 'It is said to be able to seize anything it desires with its six rings and six huge arms. With its power sealed, it is transformed into a much smaller form.', 'Fifth', '130', 'https://images.pokemoncard.io/images/xyp/xyp-XY147.png', 'unlimited: Legal, expanded: Legal', '', 'Hoopa', '720', 'TPCI', 'Promo', '', '10/12/2013', '', 'Colorless, Colorless', '', 'XY', 'XY147', 'Basic', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2'),
