('xyp-XY176', '', '', 'Naoki Saito', '', 'XY Black Star Promos', '', '', '', '', 'Fifth', '', 'https://images.pokemoncard.io/images/xyp/xyp-XY176.png', 'unlimited: Legal, expanded: Legal', '', 'Champions Festival', '', 'TPCI', 'Promo', '', '10/12/2013', '', '', '[\"Once during each player\'s turn, if that player has 6 Pokémon in play, he or she may heal 10 damage from each of his or her Pokémon.\", \"This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can\'t play this card.\"]', 'XY', 'XY176', 'Stadium', 'Trainer', '', ''),
('xyp-XY177', '', '', 'You Iribi', '', 'XY Black Star Promos', '', '', '', '', 'Fifth', '', 'https://images.pokemoncard.io/images/xyp/xyp-XY177.png', 'unlimited: Legal, expanded: Legal', '', 'Karen', '', 'TPCI', 'Promo', '', '10/12/2013', '', '', '[\'Each player shuffles all Pokémon in his or her discard pile into his or her deck.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'XY', 'XY177', 'Supporter', 'Trainer', '', ''),
('xyp-XY177a', '', '', 'Hitoshi Ariga', '', 'XY Black Star Promos', '', '', '', '', 'Fifth', '', 'https://images.pokemoncard.io/images/xyp/xyp-XY177a.png', 'unlimited: Legal, expanded: Legal', '', 'Karen', '', 'TPCI', 'Promo', '', '10/12/2013', '', '', '[\'Each player shuffles all Pokémon in his or her discard pile into his or her deck.\', \'You may play only 1 Supporter card during your turn (before your attack).\']', 'XY', 'XY177a', 'Supporter', 'Trainer', '', ''),
('xyp-XY178', '[{\'name\': \'Lamentation\', \'text\': \"If this Pokémon is your Active Pokémon and is damaged by an opponent\'s attack (even if this Pokémon is Knocked Out), discard a random card from your opponent\'s hand.\", \'type\': \'Ability\'}]', '', 'Hasuno', '[{\'name\': \'Shadow Cage\', \'cost\': [\'Darkness\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60\', \'text\': \"The Defending Pokémon can\'t retreat during your opponent\'s next turn.\"}]', 'XY Black Star Promos', '1', '', '', 'It appears when it senses an impending natural disaster. As a result, it was mistaken as a doom bringer.', 'Fifth', '100', 'https://images.pokemoncard.io/images/xyp/xyp-XY178.png', 'unlimited: Legal, expanded: Legal', '', 'Absol', '359', 'TPCI', 'Promo', '', '10/12/2013', 'type: Psychic, value: -20', 'Colorless', '', 'XY', 'XY178', 'Basic', 'Pokémon', 'Darkness', 'type: Fighting, value: ×2'),
('xyp-XY179', '[{\'name\': \'Immunity\', \'text\': \"This Pokémon can\'t be affected by any Special Conditions. (Remove any Special Conditions affecting this Pokémon.)\", \'type\': \'Ability\'}]', '', 'Ken Sugimori', '[{\'name\': \'Body Slam\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'50\', \'text\': \"Flip a coin. If heads, your opponent\'s Active Pokémon is now Paralyzed.\"}]', 'XY Black Star Promos', '4', '', '', 'It is not satisfied unless it eats over 880 pounds of food every day. When it is done eating, it goes promptly to sleep.', 'Fifth', '130', 'https://images.pokemoncard.io/images/xyp/xyp-XY179.png', 'unlimited: Legal, expanded: Legal', '20', 'Snorlax', '143', 'TPCI', 'Promo', '', '10/12/2013', '', 'Colorless, Colorless, Colorless, Colorless', '', 'XY', 'XY179', 'Basic', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('xyp-XY18', '', '', '5ban Graphics', '[{\'name\': \'Pin Missile\', \'cost\': [\'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40×\', \'text\': \'Flip 4 coins. This attack does 40 damage times the number of heads.\'}, {\'name\': \'Wild Tackle\', \'cost\': [\'Grass\', \'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'120\', \'text\': \'This Pokémon does 20 damage to itself.\'}]', 'XY Black Star Promos', '4', '', '', '', 'Fifth', '180', 'https://images.pokemoncard.io/images/xyp/xyp-XY18.png', 'unlimited: Legal, expanded: Legal', '', 'Chesnaught-EX', '652', 'TPCI', 'Promo', '', '10/12/2013', '', 'Colorless, Colorless, Colorless, Colorless', '[\'Pokémon-EX rule: When a Pokémon-EX has been Knocked Out, your opponent takes 2 Prize cards.\']', 'XY', 'XY18', 'Basic, EX', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('xyp-XY180', '', '', '5ban Graphics', '[{\'name\': \'Turbo Flame\', \'cost\': [\'Fire\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'80\', \'text\': \'Attach 2 basic Energy cards from your discard pile to 1 of your Benched Pokémon.\'}]', 'XY Black Star Promos', '', 'Arcanine', '', '', 'Fifth', '160', 'https://images.pokemoncard.io/images/xyp/xyp-XY180.png', 'unlimited: Legal, expanded: Legal', '', 'Arcanine BREAK', '59', 'TPCI', 'Promo', '', '10/12/2013', '', '', '[\'BREAK Evolution Rule: Arcanine BREAK retains the attacks, Abilities, Weakness, Resistance, and Retreat Cost of its previous Evolution.\']', 'XY', 'XY180', 'BREAK', 'Pokémon', 'Fire', ''),
('xyp-XY181', '', '', '5ban Graphics', '[{\'name\': \'Silent Bite\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60\', \'text\': \"You may leave your opponent\'s Active Pokémon Paralyzed. If you do, shuffle this Pokémon and all cards attached to into your deck.\"}]', 'XY Black Star Promos', '', 'Crobat', '', '', 'Fifth', '160', 'https://images.pokemoncard.io/images/xyp/xyp-XY181.png', 'unlimited: Legal, expanded: Legal', '', 'Crobat BREAK', '169', 'TPCI', 'Promo', '', '10/12/2013', '', '', '[\'BREAK Evolution Rule: Crobat BREAK retains the attacks, Abilities, Weakness, Resistance, and Retreat Cost of its previous Evolution.\']', 'XY', 'XY181', 'BREAK', 'Pokémon', 'Psychic', ''),
('xyp-XY182', '', '', '5ban Graphics', '[{\'name\': \'Wings of Disaster\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"This attack does 20 damage to each of your opponent\'s Pokémon. Don\'t apply Weakness and Resistance. Discard all Pokémon Tool cards attached to each of your opponent\'s Pokémon.\"}]', 'XY Black Star Promos', '', 'Mandibuzz', '', '', 'Fifth', '140', 'https://images.pokemoncard.io/images/xyp/xyp-XY182.png', 'unlimited: Legal, expanded: Legal', '', 'Mandibuzz BREAK', '630', 'TPCI', 'Promo', '', '10/12/2013', '', '', '[\'BREAK Evolution Rule: Mandibuzz BREAK retains the attacks, Abilities, Weakness, Resistance, and Retreat Cost of its previous Evolution.\']', 'XY', 'XY182', 'BREAK', 'Pokémon', 'Darkness', '');
INSERT INTO `cards` (`id`, `abilities`, `ancient_trait`, `artist`, `attacks`, `card_set`, `converted`, `evolves_from`, `evolves_to`, `flavor_text`, `generation`, `hp`, `img`, `legalities`, `level`, `name`, `national_pokedex_numbers`, `publisher`, `rarity`, `regulation_mark`, `release_date`, `resistances`, `retreat_cost`, `rules`, `series`, `set_num`, `subtypes`, `supertype`, `types`, `weakness`) VALUES
('xyp-XY183', '', '', '5ban Graphics', '[{\'name\': \'Photon Wave\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \"During your opponent\'s next turn, any damage done by attacks from the Defending Pokémon is reduced by 30 (before applying Weakness and Resistance).\"}, {\'name\': \'Psyburn\', \'cost\': [\'Psychic\', \'Psychic\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'120\', \'text\': \'\'}]', 'XY Black Star Promos', '2', '', 'M Mewtwo-EX', '', 'Fifth', '170', 'https://images.pokemoncard.io/images/xyp/xyp-XY183.png', 'unlimited: Legal, expanded: Legal', '', 'Mewtwo-EX', '150', 'TPCI', 'Promo', '', '10/12/2013', '', 'Colorless, Colorless', '[\'Pokémon-EX rule: When a Pokémon-EX has been Knocked Out, your opponent takes 2 Prize cards.\']', 'XY', 'XY183', 'Basic, EX', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2'),
('xyp-XY184', '[{\'name\': \'Devour Light\', \'text\': \'Each Pokémon BREAK has no Abilities (this includes Abilities of its previous Evolution).\', \'type\': \'Ability\'}]', '', '5ban Graphics', '[{\'name\': \'Shadow Claw\', \'cost\': [\'Psychic\', \'Psychic\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'110\', \'text\': \"Discard a random card from your opponent\'s hand.\"}]', 'XY Black Star Promos', '2', '', '', 'It was banished for its violence. It silently gazed upon the old world from the Distortion World.', 'Fifth', '130', 'https://images.pokemoncard.io/images/xyp/xyp-XY184.png', 'unlimited: Legal, expanded: Legal', '', 'Giratina', '487', 'TPCI', 'Promo', '', '10/12/2013', 'type: Fighting, value: -20', 'Colorless, Colorless', '', 'XY', 'XY184', 'Basic', 'Pokémon', 'Psychic', 'type: Darkness, value: ×2'),
('xyp-XY185', '', '', 'Hasuno', '[{\'name\': \'Concentrated Fire\', \'cost\': [\'Fire\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50×\', \'text\': \'Flip a coin for each Fire Energy attached to this Pokémon. This attack does 50 damage times the number of heads.\'}, {\'name\': \'Combustion Impact\', \'cost\': [\'Fire\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'100\', \'text\': \'Your opponent switches his or her Active Pokémon with 1 of his or her Benched Pokémon.\'}]', 'XY Black Star Promos', '4', '', '', 'It expels its internal steam from the arms on its back. It has enough power to blow away a mountain.', 'Fifth', '130', 'https://images.pokemoncard.io/images/xyp/xyp-XY185.png', 'unlimited: Legal, expanded: Legal', '', 'Volcanion', '721', 'TPCI', 'Promo', '', '10/12/2013', '', 'Colorless, Colorless, Colorless, Colorless', '', 'XY', 'XY185', 'Basic', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('xyp-XY186', '', '', 'Sanosuke Sakuma', '[{\'name\': \'Entertain\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Heal 40 damage from 1 of your Benched Pokémon.\'}, {\'name\': \'Prismatic Wave\', \'cost\': [\'Metal\'], \'convertedEnergyCost\': 1, \'damage\': \'20×\', \'text\': \"This attack does 20 damage times the number of different types of Pokémon on your opponent\'s Bench.\"}]', 'XY Black Star Promos', '1', '', '', 'Magearna, with its metallic body, is an artificial Pokémon created 500 years ago by humans.', 'Fifth', '90', 'https://images.pokemoncard.io/images/xyp/xyp-XY186.png', 'unlimited: Legal, expanded: Legal', '', 'Magearna', '801', 'TPCI', 'Promo', '', '10/12/2013', 'type: Psychic, value: -20', 'Colorless', '', 'XY', 'XY186', 'Basic', 'Pokémon', 'Metal', 'type: Fire, value: ×2'),
('xyp-XY187', '', '', 'Tomokazu Komiya', '[{\'name\': \'Time Call\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Flip a coin. If heads, search your deck for a card that evolves from 1 of your Pokémon and put it onto that Pokémon. (This counts as evolving that Pokémon.) Shuffle your deck afterward.\'}, {\'name\': \'Leech Seed\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'10\', \'text\': \'Heal 10 damage from this Pokémon.\'}]', 'XY Black Star Promos', '1', '', '', 'It has the power to travel across time, but it is said to appear only in peaceful times.', 'Fifth', '70', 'https://images.pokemoncard.io/images/xyp/xyp-XY187.png', 'unlimited: Legal, expanded: Legal', '', 'Celebi', '251', 'TPCI', 'Promo', '', '10/12/2013', '', 'Colorless', '', 'XY', 'XY187', 'Basic', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('xyp-XY188', '', '', 'Ken Sugimori', '[{\'name\': \'Aromatherapy\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'\', \'text\': \'Heal 30 damage from each of your Pokémon.\'}, {\'name\': \'Magical Leaf\', \'cost\': [\'Grass\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40+\', \'text\': \'Flip a coin. If heads, this attack does 20 more damage and heal 20 damage from this Pokémon.\'}]', 'XY Black Star Promos', '1', '', '', 'The blooming of Gracidea flowers confers the power of flight upon it. Feelings of gratitude are the message it delivers.', 'Fifth', '70', 'https://images.pokemoncard.io/images/xyp/xyp-XY188.png', 'unlimited: Legal, expanded: Legal', '', 'Shaymin', '492', 'TPCI', 'Promo', '', '10/12/2013', '', 'Colorless', '', 'XY', 'XY188', 'Basic', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('xyp-XY189', '', '', 'Ken Sugimori', '[{\'name\': \'Energy Assist\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Flip a coin. If heads, attach a basic Energy card from your discard pile to 1 of your Benched Pokémon.\'}, {\'name\': \'Victory Ball\', \'cost\': [\'Fire\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'50\', \'text\': \'Discard a Fire Energy attached to this Pokémon.\'}]', 'XY Black Star Promos', '1', '', '', 'When it shares the infinite energy it creates, that beings entire body will be overflowing with power.', 'Fifth', '70', 'https://images.pokemoncard.io/images/xyp/xyp-XY189.png', 'unlimited: Legal, expanded: Legal', '', 'Victini', '494', 'TPCI', 'Promo', '', '10/12/2013', '', 'Colorless', '', 'XY', 'XY189', 'Basic', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('xyp-XY19', '', '', '5ban Graphics', '[{\'name\': \'Psybeam\', \'cost\': [\'Fire\'], \'convertedEnergyCost\': 1, \'damage\': \'20\', \'text\': \"Flip a coin. If heads, your opponent\'s Active Pokémon is now Confused.\"}, {\'name\': \'Wonder Flare\', \'cost\': [\'Fire\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'80+\', \'text\': \"Your opponent reveals his or her hand. This attack does 40 more damage for each Energy card in your opponent\'s hand.\"}]', 'XY Black Star Promos', '2', '', '', '', 'Fifth', '170', 'https://images.pokemoncard.io/images/xyp/xyp-XY19.png', 'unlimited: Legal, expanded: Legal', '', 'Delphox-EX', '655', 'TPCI', 'Promo', '', '10/12/2013', '', 'Colorless, Colorless', '[\'Pokémon-EX rule: When a Pokémon-EX has been Knocked Out, your opponent takes 2 Prize cards.\']', 'XY', 'XY19', 'Basic, EX', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('xyp-XY190', '', '', 'Ken Sugimori', '[{\'name\': \'Marine Guidance\', \'cost\': [\'Water\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Search your deck for a Water Pokémon, reveal it, and put it into your hand. Shuffle your deck afterward.\'}, {\'name\': \'Aqua Ring\', \'cost\': [\'Water\', \'Water\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'Switch this Pokémon with 1 of your Benched Pokémon.\'}]', 'XY Black Star Promos', '1', '', '', 'It starts its life with a wondrous power that permits it to bond with any kind of Pokémon.', 'Fifth', '70', 'https://images.pokemoncard.io/images/xyp/xyp-XY190.png', 'unlimited: Legal, expanded: Legal', '', 'Manaphy', '490', 'TPCI', 'Promo', '', '10/12/2013', '', 'Colorless', '', 'XY', 'XY190', 'Basic', 'Pokémon', 'Water', 'type: Grass, value: ×2'),
('xyp-XY191', '[{\'name\': \'Justified\', \'text\': \"This Pokémon\'s attacks do 50 more damage to your opponent\'s Darkness Pokémon (before applying Weakness and Resistance).\", \'type\': \'Ability\'}]', '', 'Hajime Kusajima', '[{\'name\': \'Sacred Sword\', \'cost\': [\'Water\', \'Water\', \'Water\'], \'convertedEnergyCost\': 3, \'damage\': \'100\', \'text\': \"This Pokémon can\'t use Sacred Sword during your next turn.\"}]', 'XY Black Star Promos', '1', '', '', 'When it is resolute, it body fills with power and it becomes swifter. Its jumps are then too fast to follow.', 'Fifth', '90', 'https://images.pokemoncard.io/images/xyp/xyp-XY191.png', 'unlimited: Legal, expanded: Legal', '', 'Keldeo', '647', 'TPCI', 'Promo', '', '10/12/2013', '', 'Colorless', '', 'XY', 'XY191', 'Basic', 'Pokémon', 'Water', 'type: Grass, value: ×2'),
('xyp-XY192', '', '', 'Saya Tsuruta', '[{\'name\': \'Clairvoyance\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Your opponent reveals his or her hand.\'}, {\'name\': \'Psychic\', \'cost\': [\'Psychic\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'40+\', \'text\': \"This attack does 10 more damage for each Energy attached to your opponent\'s Active Pokémon.\"}]', 'XY Black Star Promos', '1', '', '', 'Its DNA is said to contain the genetic codes of all Pokémon, so it can use all kinds of techniques.', 'Fifth', '70', 'https://images.pokemoncard.io/images/xyp/xyp-XY192.png', 'unlimited: Legal, expanded: Legal', '', 'Mew', '151', 'TPCI', 'Promo', '', '10/12/2013', '', 'Colorless', '', 'XY', 'XY192', 'Basic', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2'),
('xyp-XY193', '', '', 'Hasuno', '[{\'name\': \'Soprano Wave\', \'cost\': [\'Psychic\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Flip 3 coins. This attack does 10 damage times the number of heads to each of your opponent\'s Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}, {\'name\': \'Entrancing Melody\', \'cost\': [\'Psychic\', \'Psychic\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \"Your opponent\'s Active Pokémon is now Confused.\"}]', 'XY Black Star Promos', '1', '', '', 'Its melodies are sung with a special vocalization method that can control the feelings of those who hear it.', 'Fifth', '80', 'https://images.pokemoncard.io/images/xyp/xyp-XY193.png', 'unlimited: Legal, expanded: Legal', '', 'Meloetta', '648', 'TPCI', 'Promo', '', '10/12/2013', '', 'Colorless', '', 'XY', 'XY193', 'Basic', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2'),
('xyp-XY194', '', '', 'Ken Sugimori', '[{\'name\': \'Dark Cutter\', \'cost\': [\'Darkness\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'\'}, {\'name\': \'Abyssal Sleep\', \'cost\': [\'Darkness\', \'Darkness\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'80\', \'text\': \"Your opponent\'s Active Pokémon is now Asleep. Your opponent flips 2 coins instead of 1 between turns. If either of them is tails, the Pokémon is still Asleep.\"}]', 'XY Black Star Promos', '2', '', '', 'It can lull people to sleep and make them dream. It is active during the nights of the new moon.', 'Fifth', '110', 'https://images.pokemoncard.io/images/xyp/xyp-XY194.png', 'unlimited: Legal, expanded: Legal', '', 'Darkrai', '491', 'TPCI', 'Promo', '', '10/12/2013', 'type: Psychic, value: -20', 'Colorless, Colorless', '', 'XY', 'XY194', 'Basic', 'Pokémon', 'Darkness', 'type: Fighting, value: ×2'),
('xyp-XY195', '', '', 'Ken Sugimori', '[{\'name\': \'Precognitive Dream\', \'cost\': [\'Metal\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Draw 3 cards. This Pokémon is now Asleep.\'}, {\'name\': \'Iron Head\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30×\', \'text\': \'Flip a coin until you get tails. This attack does 30 damage times the number of heads.\'}]', 'XY Black Star Promos', '1', '', '', 'It is said to have the ability to grant any wish for just one week every thousand years.', 'Fifth', '70', 'https://images.pokemoncard.io/images/xyp/xyp-XY195.png', 'unlimited: Legal, expanded: Legal', '', 'Jirachi', '385', 'TPCI', 'Promo', '', '10/12/2013', 'type: Psychic, value: -20', 'Colorless', '', 'XY', 'XY195', 'Basic', 'Pokémon', 'Metal', 'type: Fire, value: ×2'),
('xyp-XY196', '', '', 'Ken Sugimori', '[{\'name\': \'Linear Attack\', \'cost\': [\'Metal\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'\', \'text\': \"This attack does 30 damage to 1 of your opponent\'s Pokémon. (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}, {\'name\': \'Destructor Beam\', \'cost\': [\'Metal\', \'Metal\', \'Metal\'], \'convertedEnergyCost\': 3, \'damage\': \'90\', \'text\': \"Flip a coin. If heads, discard an Energy attached to your opponent\'s Active Pokémon.\"}]', 'XY Black Star Promos', '2', '', '', 'This Pokémon existed 300 million years ago. Team Plasma altered it and attached a cannon to its back.', 'Fifth', '110', 'https://images.pokemoncard.io/images/xyp/xyp-XY196.png', 'unlimited: Legal, expanded: Legal', '', 'Genesect', '649', 'TPCI', 'Promo', '', '10/12/2013', 'type: Psychic, value: -20', 'Colorless, Colorless', '', 'XY', 'XY196', 'Basic', 'Pokémon', 'Metal', 'type: Fire, value: ×2'),
('xyp-XY197', '', '', 'kirisAki', '[{\'name\': \'Type Switch\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Choose Grass, Fire, Water, Lightning, Psychic, Fighting, Darkness, Metal, Fairy, or Dragon type. Until the end of your next turn, this Pokémon is that type.\'}, {\'name\': \'Power Blast\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'120\', \'text\': \'Discard an Energy attached to this Pokémon.\'}]', 'XY Black Star Promos', '2', '', '', 'It is told in mythology that this Pokémon was born before the universe even existed.', 'Fifth', '130', 'https://images.pokemoncard.io/images/xyp/xyp-XY197.png', 'unlimited: Legal, expanded: Legal', '', 'Arceus', '493', 'TPCI', 'Promo', '', '10/12/2013', '', 'Colorless, Colorless', '', 'XY', 'XY197', 'Basic', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('xyp-XY198', '', '', '5ban Graphics', '[{\'name\': \'Magma Eruption\', \'cost\': [\'Fire\', \'Fire\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'120+\', \'text\': \"You may discard the top 3 cards of each player\'s deck. If you do, this attack does 40 more damage for each Energy card you discarded in this way.\"}]', 'XY Black Star Promos', '4', 'Camerupt-EX', '', '', 'Fifth', '230', 'https://images.pokemoncard.io/images/xyp/xyp-XY198.png', 'unlimited: Legal, expanded: Legal', '', 'M Camerupt-EX', '323', 'TPCI', 'Promo', '', '10/12/2013', '', 'Colorless, Colorless, Colorless, Colorless', '[\'Mega Evolution rule: When 1 of your Pokémon becomes a Mega Evolution Pokémon, your turn ends.\', \'Pokémon-EX rule: When a Pokémon-EX has been Knocked Out, your opponent takes 2 Prize cards.\']', 'XY', 'XY198', 'MEGA, EX', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('xyp-XY198a', '', '', '5ban Graphics', '[{\'name\': \'Magma Eruption\', \'cost\': [\'Fire\', \'Fire\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'120+\', \'text\': \"You may discard the top 3 cards of each player\'s deck. If you do, this attack does 40 more damage for each Energy card you discarded in this way.\"}]', 'XY Black Star Promos', '4', 'Camerupt-EX', '', '', 'Fifth', '230', 'https://images.pokemoncard.io/images/xyp/xyp-XY198a.png', 'unlimited: Legal, expanded: Legal', '', 'M Camerupt-EX', '323', 'TPCI', 'Promo', '', '10/12/2013', '', 'Colorless, Colorless, Colorless, Colorless', '[\'Mega Evolution rule: When 1 of your Pokémon becomes a Mega Evolution Pokémon, your turn ends.\', \'Pokémon-EX rule: When a Pokémon-EX has been Knocked Out, your opponent takes 2 Prize cards.\']', 'XY', 'XY198a', 'MEGA, EX', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
