('xyp-XY83', '', '', 'Shin Nagasawa', '[{\'name\': \'Gather Light\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Move as many Energy as you like from your Benched Pokémon to this Pokémon.\'}, {\'name\': \'Judgment Blast\', \'cost\': [\'Colorless\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'10+\', \'text\': \'This attack does 30 more damage for each different type of basic Energy attached to this Pokémon.\'}]', 'XY Black Star Promos', '2', '', '', 'It is told in mythology that this Pokémon was born before the universe even existed.', 'Fifth', '120', 'https://images.pokemoncard.io/images/xyp/xyp-XY83.png', 'unlimited: Legal, expanded: Legal', '', 'Arceus', '493', 'TPCI', 'Promo', '', '10/12/2013', '', 'Colorless, Colorless', '', 'XY', 'XY83', 'Basic', 'Pokémon', 'Colorless', 'type: Fighting, value: ×2'),
('xyp-XY84', '', '', 'Hitoshi Ariga', '[{\'name\': \'Iron Tail\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'30×\', \'text\': \'Flip a coin until you get tails. This attack does 30 damage times the number of heads.\'}, {\'name\': \'Overspark\', \'cost\': [\'Lightning\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'50×\', \'text\': \'Discard all Lightning Energy attached to this Pokémon. This attack does 50 damage times the number of Energy cards you discarded.\'}]', 'XY Black Star Promos', '1', '', 'Raichu', '', 'Fifth', '130', 'https://images.pokemoncard.io/images/xyp/xyp-XY84.png', 'unlimited: Legal, expanded: Legal', '', 'Pikachu-EX', '25', 'TPCI', 'Promo', '', '10/12/2013', 'type: Metal, value: -20', 'Colorless', '[\'Pokémon-EX rule: When a Pokémon-EX has been Knocked Out, your opponent takes 2 Prize cards.\']', 'XY', 'XY84', 'Basic, EX', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
('xyp-XY85', '', '', 'Hitoshi Ariga', '[{\'name\': \'Hyperspace Ring\', \'cost\': [\'Psychic\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Search your deck for up to 2 Item cards, reveal them, and put them into your hand. Shuffle your deck afterward.\'}, {\'name\': \'Wonder Trick\', \'cost\': [\'Psychic\', \'Psychic\', \'Psychic\'], \'convertedEnergyCost\': 3, \'damage\': \'100\', \'text\': \'Your opponent switches his or her Active Pokémon with 1 of his or her Benched Pokémon.\'}]', 'XY Black Star Promos', '2', '', '', '', 'Fifth', '140', 'https://images.pokemoncard.io/images/xyp/xyp-XY85.png', 'unlimited: Legal, expanded: Legal', '', 'Hoopa-EX', '720', 'TPCI', 'Promo', '', '10/12/2013', '', 'Colorless, Colorless', '[\'Pokémon-EX rule: When a Pokémon-EX has been Knocked Out, your opponent takes 2 Prize cards.\']', 'XY', 'XY85', 'Basic, EX', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2'),
('xyp-XY86', '', '', '5ban Graphics', '[{\'name\': \'Moonsault Blaze\', \'cost\': [\'Fire\', \'Fire\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'100\', \'text\': \"During your next turn, this Pokémon\'s Moonsault Blaze attack does 100 more damage (before applying Weakness and Resistance).\"}]', 'XY Black Star Promos', '2', 'Blaziken-EX', '', '', 'Fifth', '210', 'https://images.pokemoncard.io/images/xyp/xyp-XY86.png', 'unlimited: Legal, expanded: Legal', '', 'M Blaziken-EX', '257', 'TPCI', 'Promo', '', '10/12/2013', '', 'Colorless, Colorless', '[\'Mega Evolution rule: When 1 of your Pokémon becomes a Mega Evolution Pokémon, your turn ends.\', \'Pokémon-EX rule: When a Pokémon-EX has been Knocked Out, your opponent takes 2 Prize cards.\']', 'XY', 'XY86', 'MEGA, EX', 'Pokémon', 'Fire', 'type: Water, value: ×2'),
('xyp-XY87', '', '', '5ban Graphics', '[{\'name\': \'Strongarm Impact\', \'cost\': [\'Water\', \'Water\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 4, \'damage\': \'130+\', \'text\': \"You may do 30 more damage. If you do, discard the top 3 cards of each player\'s deck.\"}]', 'XY Black Star Promos', '3', 'Swampert-EX', '', '', 'Fifth', '220', 'https://images.pokemoncard.io/images/xyp/xyp-XY87.png', 'unlimited: Legal, expanded: Legal', '', 'M Swampert-EX', '260', 'TPCI', 'Promo', '', '10/12/2013', '', 'Colorless, Colorless, Colorless', '[\'Mega Evolution rule: When 1 of your Pokémon becomes a Mega Evolution Pokémon, your turn ends.\', \'Pokémon-EX rule: When a Pokémon-EX has been Knocked Out, your opponent takes 2 Prize cards.\']', 'XY', 'XY87', 'MEGA, EX', 'Pokémon', 'Water', 'type: Grass, value: ×2'),
('xyp-XY88', '', '', 'Atsuko Nishida', '[{\'name\': \'Vine Whip\', \'cost\': [\'Grass\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \'\'}]', 'XY Black Star Promos', '2', '', 'Quilladin', 'Such a thick shell of wood covers its head and back that even a direct hit from a truck wouldnt faze it.', 'Fifth', '60', 'https://images.pokemoncard.io/images/xyp/xyp-XY88.png', 'unlimited: Legal, expanded: Legal', '', 'Chespin', '650', 'TPCI', 'Promo', '', '10/12/2013', '', 'Colorless, Colorless', '', 'XY', 'XY88', 'Basic', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('xyp-XY89', '', '', 'Masakazu Fukuda', '[{\'name\': \'Thunder Wave\', \'cost\': [\'Lightning\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Flip a coin. If heads, your opponent\'s Active Pokémon is now Paralyzed.\"}, {\'name\': \'Electric Ring\', \'cost\': [\'Lightning\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'30+\', \'text\': \'If Hoopa is on your Bench, this attack does 30 more damage.\'}]', 'XY Black Star Promos', '1', '', 'Raichu', 'It has small electric sacs on both its cheeks. If threatened, it looses electric charges from the sacs.', 'Fifth', '60', 'https://images.pokemoncard.io/images/xyp/xyp-XY89.png', 'unlimited: Legal, expanded: Legal', '', 'Pikachu', '25', 'TPCI', 'Promo', '', '10/12/2013', 'type: Metal, value: -20', 'Colorless', '', 'XY', 'XY89', 'Basic', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
('xyp-XY90', '', '', 'Masakazu Fukuda', '[{\'name\': \'Summoning Draw\', \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'If Pikachu is on your Bench, draw 3 cards.\'}, {\'name\': \'Double Spin\', \'cost\': [\'Psychic\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'30×\', \'text\': \'Flip 2 coins. This attack does 30 damage times the number of heads.\'}]', 'XY Black Star Promos', '1', '', '', 'It gathers things it likes and pushes them through its loop to teleport them to a secret place.', 'Fifth', '70', 'https://images.pokemoncard.io/images/xyp/xyp-XY90.png', 'unlimited: Legal, expanded: Legal', '', 'Hoopa', '720', 'TPCI', 'Promo', '', '10/12/2013', '', 'Colorless', '', 'XY', 'XY90', 'Basic', 'Pokémon', 'Psychic', 'type: Psychic, value: ×2'),
('xyp-XY91', '', '', 'Naoki Saito', '', 'XY Black Star Promos', '', '', '', '', 'Fifth', '', 'https://images.pokemoncard.io/images/xyp/xyp-XY91.png', 'unlimited: Legal, expanded: Legal', '', 'Champions Festival', '', 'TPCI', 'Promo', '', '10/12/2013', '', '', '[\"Once during each player\'s turn, if that player has 6 Pokémon in play, he or she may heal 10 damage from each of his or her Pokémon.\", \"This card stays in play when you play it. Discard this card if another Stadium card comes into play. If another card with the same name is in play, you can\'t play this card.\"]', 'XY', 'XY91', 'Stadium', 'Trainer', '', ''),
('xyp-XY92', '', 'name: θ Stop, text: Prevent all effects of your opponents Pokémons Abilities done to this Pokémon.', 'match', '[{\'name\': \'Energy Hunt\', \'cost\': [\'Psychic\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Flip 3 coins. For each heads, attach a basic Energy card from your discard pile to your Benched Pokémon-EX in any way you like.\'}, {\'name\': \'Claw Slash\', \'cost\': [\'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'20\', \'text\': \'\'}]', 'XY Black Star Promos', '2', '', '', 'It dwells in the darkness of caves. It uses its sharp claws to dig up gems to nourish itself.', 'Fifth', '70', 'https://images.pokemoncard.io/images/xyp/xyp-XY92.png', 'unlimited: Legal, expanded: Legal', '', 'Sableye', '302', 'TPCI', 'Promo', '', '10/12/2013', '', 'Colorless, Colorless', '', 'XY', 'XY92', 'Basic', 'Pokémon', 'Psychic', ''),
('xyp-XY93', '[{\'name\': \'Leap Through Time\', \'text\': \"When this Pokémon is Knocked Out, flip a coin. If heads, shuffle this Pokémon and all cards attached to it into your deck, and your opponent can\'t take any Prize cards for it.\", \'type\': \'Ability\'}]', 'name: θ Stop, text: Prevent all effects of your opponents Pokémons Abilities done to this Pokémon.', 'Shin Nagasawa', '[{\'name\': \'Sparkle Motion\', \'cost\': [\'Grass\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \"Put 1 damage counter on each of your opponent\'s Pokémon.\"}]', 'XY Black Star Promos', '1', '', '', 'It has the power to travel across time, but it is said to appear only in peaceful times.', 'Fifth', '70', 'https://images.pokemoncard.io/images/xyp/xyp-XY93.png', 'unlimited: Legal, expanded: Legal', '', 'Celebi', '251', 'TPCI', 'Promo', '', '10/12/2013', '', 'Colorless', '', 'XY', 'XY93', 'Basic', 'Pokémon', 'Grass', 'type: Fire, value: ×2'),
('xyp-XY94', '[{\'name\': \'Nervous Seed\', \'text\': \"As long as this Pokémon is your Active Pokémon, the attacks of your opponent\'s Basic Pokémon cost Colorless more.\", \'type\': \'Ability\'}]', '', 'Midori Harada', '[{\'name\': \'Energy Press\', \'cost\': [\'Psychic\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'70+\', \'text\': \"This attack does 10 more damage for each Energy attached to your opponent\'s Active Pokémon.\"}]', 'XY Black Star Promos', '3', 'Phantump', '', 'Using its roots as a nervous system, it controls the trees in the forest. Its kind to the Pokémon that reside in its body.', 'Fifth', '110', 'https://images.pokemoncard.io/images/xyp/xyp-XY94.png', 'unlimited: Legal, expanded: Legal', '', 'Trevenant', '709', 'TPCI', 'Promo', '', '10/12/2013', 'type: Fighting, value: -20', 'Colorless, Colorless, Colorless', '', 'XY', 'XY94', 'Stage 1', 'Pokémon', 'Psychic', 'type: Darkness, value: ×2'),
('xyp-XY95', '', '', 'Kanako Eo', '[{\'name\': \"Let\'s Eat Together\", \'cost\': [\'Colorless\'], \'convertedEnergyCost\': 1, \'damage\': \'\', \'text\': \'Heal 30 damage from both Active Pokémon.\'}, {\'name\': \'Quick Attack\', \'cost\': [\'Lightning\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'10+\', \'text\': \'Flip a coin. If heads, this attack does 20 more damage.\'}]', 'XY Black Star Promos', '1', '', 'Raichu', 'It has small electric sacs on both its cheeks. If threatened, it looses electric charges from the sacs.', 'Fifth', '60', 'https://images.pokemoncard.io/images/xyp/xyp-XY95.png', 'unlimited: Legal, expanded: Legal', '', 'Pikachu', '25', 'TPCI', 'Promo', '', '10/12/2013', 'type: Metal, value: -20', 'Colorless', '', 'XY', 'XY95', 'Basic', 'Pokémon', 'Lightning', 'type: Fighting, value: ×2'),
('xyp-XY96', '', '', 'kawayoo', '[{\'name\': \'Mach Claw\', \'cost\': [\'Darkness\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30\', \'text\': \"This attack\'s damage isn\'t affected by Resistance.\"}, {\'name\': \'Lunatic Sense\', \'cost\': [\'Darkness\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'60+\', \'text\': \'Turn 1 of your face-down Prize cards face up. If that Prize card is a Pokémon, this attack does 60 more damage. (That Prize card remains up for the rest of the game.)\'}]', 'XY Black Star Promos', '2', 'Eevee', '', 'When exposed to the moons aura, the rings on its body glow faintly and its filled with a mysterious power.', 'Fifth', '100', 'https://images.pokemoncard.io/images/xyp/xyp-XY96.png', 'unlimited: Legal, expanded: Legal', '', 'Umbreon', '197', 'TPCI', 'Promo', '', '10/12/2013', 'type: Psychic, value: -20', 'Colorless, Colorless', '', 'XY', 'XY96', 'Stage 1', 'Pokémon', 'Darkness', 'type: Fighting, value: ×2'),
('xyp-XY97', '', '', 'Ayaka Yoshida', '[{\'name\': \'Rock Smash\', \'cost\': [\'Fighting\', \'Colorless\'], \'convertedEnergyCost\': 2, \'damage\': \'30+\', \'text\': \'Flip a coin. If heads, this attack does 30 more damage.\'}, {\'name\': \'Land Crush\', \'cost\': [\'Fighting\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'70\', \'text\': \'\'}]', 'XY Black Star Promos', '1', '', 'M Aerodactyl-EX', '', 'Fifth', '170', 'https://images.pokemoncard.io/images/xyp/xyp-XY97.png', 'unlimited: Legal, expanded: Legal', '', 'Aerodactyl-EX', '142', 'TPCI', 'Promo', '', '10/12/2013', 'type: Fighting, value: -20', 'Colorless', '[\'Pokémon-EX rule: When a Pokémon-EX has been Knocked Out, your opponent takes 2 Prize cards.\']', 'XY', 'XY97', 'Basic, EX', 'Pokémon', 'Fighting', 'type: Lightning, value: ×2'),
('xyp-XY98', '', '', '5ban Graphics', '[{\'name\': \'Rock Drill Dive\', \'cost\': [\'Fighting\', \'Colorless\', \'Colorless\'], \'convertedEnergyCost\': 3, \'damage\': \'110\', \'text\': \"This attack does 10 damage to each Benched Pokémon (both yours and your opponent\'s). (Don\'t apply Weakness and Resistance for Benched Pokémon.)\"}]', 'XY Black Star Promos', '1', 'Aerodactyl-EX', '', '', 'Fifth', '210', 'https://images.pokemoncard.io/images/xyp/xyp-XY98.png', 'unlimited: Legal, expanded: Legal', '', 'M Aerodactyl-EX', '142', 'TPCI', 'Promo', '', '10/12/2013', 'type: Fighting, value: -20', 'Colorless', '[\'Mega Evolution rule: When 1 of your Pokémon becomes a Mega Evolution Pokémon, your turn ends.\', \'Pokémon-EX rule: When a Pokémon-EX has been Knocked Out, your opponent takes 2 Prize cards.\']', 'XY', 'XY98', 'MEGA, EX', 'Pokémon', 'Fighting', 'type: Lightning, value: ×2'),
('xyp-XY99', '', '', '5ban Graphics', '', 'XY Black Star Promos', '', '', '', '', 'Fifth', '', 'https://images.pokemoncard.io/images/xyp/xyp-XY99.png', 'unlimited: Legal, expanded: Legal', '', 'Aerodactyl Spirit Link', '', 'TPCI', 'Promo', '', '10/12/2013', '', '', '[\"Attach a Pokémon Tool to 1 of your Pokémon that doesn\'t already have a Pokémon Tool attached to it.\", \'Your turn does not end if the Pokémon this card is attached to becomes M Aerodactyl-EX.\', \'You may play as many Item cards as you like during your turn (before your attack).\']', 'XY', 'XY99', 'Pokémon Tool', 'Trainer', '', '');
